(function(){var m=window.SITE_DATA_BY_DOMAIN=window.SITE_DATA_BY_DOMAIN||{};var d=m["multimodal"]=m["multimodal"]||{};d["appendix"]=[{"id":"ap-vision-encoder-terms","title":"视觉编码器术语表","summary":"统一定义ViT patch切分、CLIP/SigLIP视觉塔、动态分辨率与位置插值、视觉token序列长度、图像塔输出维度与projector接口，确保跨团队讨论视觉编码器推理时口径一致。","kind":"术语","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-1\">一 · 条目的边界：什么算视觉编码器术语</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-2\">二 · 分类维度：按输出形态、按分辨率策略、按接口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-3\">三 · 与相邻概念的区别：token 数、维度、分辨率不是一回事</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-4\">四 · 定义的可执行性：五项契约与一个失败案例</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-5\">五 · 分类维度如何映射到推理形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-6\">六 · 契约五项：视觉编码器口径的边界与失效面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-7\">七 · 五字段契约速查表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-8\">八 · 序列长度与显存口径换算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-9\">九 · 动态分辨率与位置插值判定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-10\">十 · 输出形态与 projector 接口口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-11\">十一 · 速查表落地检查项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-12\">十二 · 速查表落地：字段、阈值与口径的边界条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-13\">十三 · 速查表的失效边界：五项契约缺一即口径漂移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-14\">十四 · 像素预算与 token 数的换算阈值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-15\">十五 · 位置插值的失配判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-16\">十六 · class token 与序列长度的计数口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-17\">十七 · projector 维度的接口阈值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-18\">十八 · 五项契约的自检清单与测量节奏</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-19\">十九 · 阈值不是拍脑袋：像素预算、token 数与显存的三条硬边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-20\">二十 · 视觉口径三处静默错位：计数、插值、维度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-21\">二十一 · 踩坑清单：按代价排序的十类失败</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-22\">二十二 · 检查顺序：从契约到端到端指标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-23\">二十三 · 回滚方案：配置、权重、缓存三层分离</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-24\">二十四 · 把检查清单固化为启动断言</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-25\">二十五 · 视觉编码器契约的失效边界与联调检查顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-26\">二十六 · 上游依赖：像素预算与 patch 切分决定了下游一切长度的起点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-27\">二十七 · 下游影响：输出形态决定 projector 接口与跨模态注意力的输入契约</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-28\">二十八 · 动态分辨率与位置插值的下游传导：一个被低估的全局偏移源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-29\">二十九 · 与量化、显存、批调度条目的耦合点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-30\">三十 · 在全书中的位置：术语表条目作为跨条目口径的锚</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-vision-encoder-terms-sec-31\">三十一 · 契约边界：五项声明缺一即口径漂移</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-vision-encoder-terms\"><svg style=\"max-width:482px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 482.0 319\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"400.0\" height=\"83.0\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"53.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"57.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：视觉编码器术语表</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">统一定义ViT patch切分、CLIP/SigLIP视觉塔、动态分辨率与</text><text x=\"75.0\" y=\"78.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">位置…</text><line x1=\"82.0\" y1=\"97.0\" x2=\"82.0\" y2=\"114.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 113.0 L 86.5 113.0 L 82.0 121.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"121.0\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"143.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"147.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"148.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">入口</text><line x1=\"82.0\" y1=\"167.9\" x2=\"82.0\" y2=\"184.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 183.9 L 86.5 183.9 L 82.0 191.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"191.9\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"214.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"218.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"219.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">依赖</text><line x1=\"82.0\" y1=\"238.7\" x2=\"82.0\" y2=\"255.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 254.8 L 86.5 254.8 L 82.0 262.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"262.8\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"285.2\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"289.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"290.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">最小复现</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-vision-encoder-terms-sec-1\">一 · 条目的边界：什么算视觉编码器术语</h3>\n<p>视觉编码器术语表收录的不是“所有跟图像有关的词”，而是那些一旦口径不一致就会直接改变推理系统数值的词。判据有三条：第一，该量进入 LLM prefill 长度或 KV cache 预算；第二，该量决定视觉塔的显存驻留或单次前向的计算量；第三，该量在跨团队接口文档里会被写成一行契约。按这三条筛，ViT patch 切分、CLIP/SigLIP 视觉塔形态、动态分辨率与位置插值、视觉 token 序列长度、图像塔输出维度与 projector 接口构成第一组核心条目。反过来，“图像增强”“标注格式”“数据集划分”这类词不进入本表——它们不改变推理时的张量形状。</p>\n<p>定义必须写成可代入的形式，而不是描述性句子。以 patch 切分为例，条目正文给出的不是“把图像切成小块”，而是 $N=\\frac{HW}{P^2}$ 与线性投影到 $d$ 维这两步，并明确 $P$ 与 $d$ 是“第一组参数”。这样定义的好处是：任何人拿到 $H$、$W$、$P$ 就能算出序列长度，拿到 $d$ 就能算出单 token 的投影计算量。术语表的价值在于把口头词换成可计算的量。</p>\n<p>代价层面，这一组条目对应的是推理系统的三个硬约束。序列长度 $N$ 直接进入 prefill 的注意力计算，其代价随 $N^2$ 增长（因果注意力下为 $O(N^2 d)$ 量级）；$d$ 决定视觉塔权重与激活的显存占用；$P$ 越小则 $N$ 越大，二者是同一枚硬币的两面。举例：同一张图，$P$ 从 16 降到 14，$N$ 按 $(16/14)^2$ 放大，prefill 的注意力项随之放大，而视觉塔卷积/投影的 FLOPs 也同步上升——这不是“精度更高”的免费午餐，而是容量规划里必须提前声明的口径变化。</p>\n\n<h3 id=\"ap-vision-encoder-terms-sec-2\">二 · 分类维度：按输出形态、按分辨率策略、按接口</h3>\n<p>本表不按“模型家族”分类，而按三个正交维度分类，因为推理系统的代价只对这三个维度敏感。</p>\n<ul>\n<li><b>输出形态维度</b>：单向量汇聚型 vs token 序列型。CLIP 视觉塔用全局平均池化或 class token 汇聚为单一图像嵌入；SigLIP 视觉塔改用 sigmoid 对比损失，且常保留 patch token 序列供 projector 使用。这一维度决定下游是取一个向量还是取一串 token，进而决定 projector 是“线性映射一个向量”还是“逐 token 映射一个序列”。</li>\n<li><b>分辨率策略维度</b>：固定网格 vs 动态分辨率 + 位置插值。动态分辨率按输入长宽比与像素预算选择网格；位置插值把预训练固定网格的位置编码双线性重采样到新网格。这一维度决定同一张图在不同批次里是否产生不同的 $N$，从而决定连续批处理能否把视觉塔前向拼成一个大 batch。</li>\n<li><b>接口维度</b>：projector 类型（MLP/线性/Q-Former）与维度契约。图像塔输出维度指 projector 输入的特征维 $d_v$，projector 负责把 $d_v$ 映射到语言模型隐藏维 $d_l$。这一维度决定显存分配与 prefill 的输入宽度。</li>\n</ul>\n<p>三个维度不是并列的标签，而是有依赖顺序：先定输出形态，才能定 projector 的输入是单向量还是序列；先定分辨率策略，才能定 $N$ 是常量还是变量；最后才谈接口维度。工程上常把像素预算、patch 大小、位置插值方式、是否保留 class token、projector 类型这五项写成固定契约——这正是三个维度落到纸面上的形式。跨团队讨论时必须同时声明这五项，否则同一句“视觉 token 数”会指向不同口径。</p>\n<p>代价举例：若一个服务同时接入固定网格与动态分辨率两种视觉塔，批调度器不能假设 $N$ 恒定，KV cache 的预分配必须按该批次的最大 $N$ 留余量，否则动态分辨率样本会把预分配打穿，触发重分配或截断。这是分类维度直接转化为显存代价的典型路径。</p>\n\n<h3 id=\"ap-vision-encoder-terms-sec-3\">三 · 与相邻概念的区别：token 数、维度、分辨率不是一回事</h3>\n<p>最容易混淆的三组概念，本表用“指向对象”来区分，而不是用同义词辨析。</p>\n<table class=\"mini\">\n<thead><tr><th>概念</th><th>指向的张量</th><th>推理系统里的落点</th><th>常见误用</th></tr></thead>\n<tbody>\n<tr><td>视觉 token 序列长度 $N$</td><td>视觉塔输出的序列维</td><td>LLM prefill 长度的主要构成项</td><td>含/不含 class token 口径不一</td></tr>\n<tr><td>图像塔输出维度 $d_v$</td><td>每个 token 的特征维</td><td>projector 输入宽度、视觉塔激活显存</td><td>与 projector 输出维 $d_l$ 混写</td></tr>\n<tr><td>动态分辨率</td><td>网格 $(H/P)\\times(W/P)$</td><td>决定 $N$ 是否随样本变化</td><td>换网格后不同步位置插值</td></tr>\n</tbody>\n</table>\n<p>第一组区别：$N$ 是“有几个 token”，$d_v$ 是“每个 token 多宽”。二者相乘才是视觉塔输出张量的元素数，也才是 projector 的输入规模。把 $N$ 说成“视觉特征维度”是口径污染。第二组区别：$d_v$ 是视觉塔的输出维，$d_l$ 是语言模型的隐藏维，projector 是二者之间的映射。把 projector 输出维度误当作视觉塔输出维度写进接口文档，下游会按错误维度分配显存，prefill 阶段出现静默截断或维度不匹配报错——这是本表明确列出的失败模式。第三组区别：动态分辨率是“选网格”的策略，位置插值是“把位置编码重采样到新网格”的补偿动作。二者必须成对出现；切换网格后忘记同步插值，视觉塔输出看似正常，但跨模态注意力打分整体偏移，表现为检索与 grounding 指标同时下降。</p>\n<p>还有一个相邻概念需要一句话指路：视觉 token 压缩（剪枝、合并、重采样）改变的是 $N$ 的有效值，属于另一条目的主题，本表只负责把压缩前的 $N$ 定义清楚，否则压缩率的分母本身就是错的。</p>\n<div class=\"formula\">$$N=\\frac{HW}{P^2},\\qquad \\text{prefill 注意力代价}\\ \\propto\\ N^2 d_l,\\qquad \\text{视觉塔输出元素数}=N\\cdot d_v$$</div>\n<p>这三个式子把三组概念钉在同一张量链上：$N$ 进 prefill，$d_v$ 进 projector 输入，$N\\cdot d_v$ 进视觉塔输出缓冲。任何一项口径漂移，都会在这条链的某一环上变成显存或延迟的偏差。</p>\n\n<h3 id=\"ap-vision-encoder-terms-sec-4\">四 · 定义的可执行性：五项契约与一个失败案例</h3>\n<p>术语表条目的合格标准是“能被写进接口文档并被机器校验”。因此每个核心条目都附带一个契约字段。像素预算、patch 大小、位置插值方式、是否保留 class token、projector 类型这五项，构成视觉编码器推理口径的最小完备集。缺任何一项，下游都无法独立复算 $N$ 与 $d_v$。</p>\n<p>失败案例可以直接写成伪代码式的校验思路：容量估算脚本读取契约，若“是否保留 class token”字段缺失，则 $N$ 的取值在团队 A（含 class token）与团队 B（不含）之间相差一个 token。单看一个 token 微不足道，但 KV cache 预算按批大小乘以每序列长度计算，联调时批大小与 KV cache 预算就对不上——这是本表记录的真实失败模式，其根因不是算错，而是口径未声明。</p>\n<ul>\n<li>契约字段一：像素预算（决定 $H\\cdot W$ 的上界）。</li>\n<li>契约字段二：patch 大小 $P$（与像素预算共同决定 $N$）。</li>\n<li>契约字段三：位置插值方式（决定新网格下位置编码是否重采样）。</li>\n<li>契约字段四：是否保留 class token（决定 $N$ 的计数口径）。</li>\n<li>契约字段五：projector 类型（决定 $d_v\\to d_l$ 的映射形态与参数量）。</li>\n</ul>\n<p>代价视角：这五项里，前两项影响 prefill 延迟与视觉塔 FLOPs，第三项影响数值正确性（不插值而直接外推会导致位置编码分布偏移、注意力打分失真），第四项影响 KV cache 预算的常数项，第五项影响 projector 的显存与 prefill 输入宽度。举例：Q-Former 型 projector 引入可学习的 query 序列，其输出 token 数与视觉塔 patch token 数解耦，此时“视觉 token 数”必须明确指 Q-Former 输出还是视觉塔输出，否则批调度的长度假设再次失效。</p>\n\n<h3 id=\"ap-vision-encoder-terms-sec-5\">五 · 分类维度如何映射到推理形态</h3>\n<p>把三个维度组合起来，会得到几种在推理系统里行为截然不同的视觉编码器形态，本表用它们来校验定义是否够用。</p>\n<p>形态一：单向量汇聚 + 固定网格 + 线性 projector。此时 $N$ 对下游不可见（被池化掉），prefill 只增加一个图像嵌入位置，KV cache 增量近似常数；代价集中在视觉塔前向本身，显存由 $d$ 与固定网格决定。形态二：token 序列 + 动态分辨率 + MLP projector。此时 $N$ 随样本变化，prefill 长度是变量，KV cache 必须按批内最大 $N$ 预留，连续批处理的拼批效率受 $N$ 方差影响。形态三：token 序列 + 动态分辨率 + Q-Former。此时视觉塔输出与 projector 输出是两套长度，接口文档必须分别声明，否则批调度的长度统计会把两者混为一谈。</p>\n<p>这三种形态说明：分类维度不是学术标签，而是批调度器与显存分配器读取的参数来源。一个只写“视觉编码器输出 token 序列”的条目，对形态一就是错的；一个只写“输出单一图像嵌入”的条目，对形态二、三就是错的。因此本表的每个条目都要求标注它适用的输出形态，而不是给出一个万能定义。</p>\n<p>工程判断落在最后一步：当团队为视觉塔写容量规划时，先问“这五项契约齐了吗”，再问“$N$ 是常量还是变量”。若 $N$ 是变量而批调度仍按常量预分配 KV cache，动态分辨率样本就会把预算打穿；若五项契约缺项，联调阶段的维度报错会被误诊为框架 bug。术语表的作用不是让讨论更文雅，而是让这两个问题在写代码之前就有确定答案。</p>\n\n<h3 id=\"ap-vision-encoder-terms-sec-6\">六 · 契约五项：视觉编码器口径的边界与失效面</h3>\n<p>把“视觉 token 数”当成一个可比较的标量，是跨团队对齐中最常见的口径塌陷。严格地说，它是一组契约的函数：像素预算 $(H,W)$、patch 边长 $P$、位置插值方式、是否计入 class token、projector 类型。序列长度只由前三项中的前两项直接决定，$N=\\frac{HW}{P^2}$，但工程上真正被下游消费的是 $N$ 加上汇聚位（class token 或池化位）再经 projector 折叠后的长度。因此同一张图在 A 团队口中是 $N$，在 B 团队口中是 $N+1$，容量估算便相差一个 token 的 KV 占用——单看微不足道，乘上并发批与层数后足以让 KV cache 预算与批大小在联调时对不上。这一节的边界正在于此：定义不是名词解释，而是把五项写成不可省略的接口契约，缺一项则口径不可复现。</p>\n<p>失效条件可以按契约项逐条定位。位置插值缺失时，动态分辨率切换网格后视觉塔输出数值看似正常，但位置编码分布已偏移，注意力打分整体失真，表现为检索与 grounding 指标同步下滑——这类故障不报错、不崩溃，只悄悄劣化，属于最难在压测中暴露的一类。维度口径混淆则更直接：把 projector 输出维 $d_l$ 误记为视觉塔特征维 $d_v$ 写入接口文档，下游按错误维度分配显存，prefill 阶段出现静默截断或维度不匹配报错。设单图视觉 token 数为 $N_v$、每 token 每层 KV 字节为 $b$、层数为 $L$、并发为 $B$，则视觉侧 KV 占用为</p>\n<div class=\"formula\">$$M_{\\text{kv}}^{\\text{vis}} = B \\cdot L \\cdot N_v \\cdot b$$</div>\n<p>一个 token 的口径差在此式中被 $B \\cdot L \\cdot b$ 放大，这正是“差一个 token”在容量规划上不可忽略的原因。</p>\n<table class=\"mini\"><thead><tr><th>契约项</th><th>缺失时的失效形态</th><th>系统代价落点</th></tr></thead><tbody><tr><td>像素预算与 patch 边长</td><td>$N$ 不可复现，prefill 长度估算漂移</td><td>吞吐与批调度</td></tr><tr><td>位置插值方式</td><td>打分偏移，指标静默下降</td><td>精度而非延迟</td></tr><tr><td>class token 计数</td><td>KV 预算与批大小对不上</td><td>显存</td></tr><tr><td>projector 类型与维度</td><td>静默截断或维度报错</td><td>prefill 首 token 延迟</td></tr></tbody></table>\n<p>与相邻概念的区别须落在“谁消费输出”上。CLIP 视觉塔以池化或 class token 汇聚为单一图像嵌入，下游取单向量；SigLIP 视觉塔常保留 patch token 序列交由 projector 处理，下游取序列。二者输出形态不同，直接决定 projector 是线性/MLP 的点式映射还是 Q-Former 式的定长查询压缩，也决定视觉 token 序列长度是否成为 LLM prefill 长度的主要构成项。工程判断因此很具体：接口文档必须同时声明五项，并把 $d_v$ 与 $d_l$ 分列两栏，任何只写“视觉输出维度”的字段都应视为未定义。</p>\n<h3 id=\"ap-vision-encoder-terms-sec-7\">七 · 五字段契约速查表</h3>\n<p>跨团队对齐视觉编码器推理口径，唯一可操作的做法是把“视觉 token 数”这句话拆成五个必须同时声明的字段。下表给出每个字段的取值来源、可接受区间与判定口径，工程上直接照抄进接口文档即可，任何一项缺失都视为契约不完整。</p>\n<table class=\"mini\">\n<thead><tr><th>字段</th><th>取值来源</th><th>典型取值/区间</th><th>口径判定</th></tr></thead>\n<tbody>\n<tr><td>像素预算 $HW$</td><td>预处理阶段按长宽比裁剪后的实际像素数</td><td>由业务分辨率档位决定，必须写成整数像素而非“高清”</td><td>以裁剪后、归一化前的像素数为准，不含 padding</td></tr>\n<tr><td>patch 大小 $P$</td><td>视觉塔权重固定属性</td><td>与权重绑定，不可在推理侧改动</td><td>以权重 config 中的 patch_size 为准，不按输入推测</td></tr>\n<tr><td>位置插值方式</td><td>动态分辨率切换网格时的位置编码重采样策略</td><td>双线性重采样；禁止直接外推</td><td>必须声明“插值到目标网格”，并记录预训练网格尺寸</td></tr>\n<tr><td>class token 是否保留</td><td>视觉塔汇聚方式</td><td>CLIP 常保留；SigLIP 常保留 patch 序列</td><td>计数时必须写明“含/不含 class token”</td></tr>\n<tr><td>projector 类型与维度</td><td>视觉塔输出维 $d_v$ 到语言模型隐藏维 $d_l$ 的映射</td><td>MLP / 线性 / Q-Former</td><td>接口文档写 $d_v$ 与 $d_l$ 两个数，禁止只写“输出维度”</td></tr>\n</tbody>\n</table>\n<p>这张表的用法是逐字段核对而非整体估算。视觉 token 序列长度由 $N=\\frac{HW}{P^2}$ 给出，含 class token 时为 $N+1$。工程代价直接落在 KV cache 上：多计一个 token，在长上下文批处理中会按批大小成倍放大显存占用，联调时表现为 KV cache 预算与批大小对不上。具体例子：团队 A 按含 class token 报 $N+1$，团队 B 按 $N$ 报，容量规划阶段两边的 prefill 长度差一个 token，批调度器按较小值分配后，实际 prefill 触发静默截断。</p>\n\n<h3 id=\"ap-vision-encoder-terms-sec-8\">八 · 序列长度与显存口径换算</h3>\n<p>速查表第二层是把 token 数换算成显存与带宽代价，这一步决定容量规划能否落地。视觉塔输出序列进入 LLM prefill 后，KV cache 占用与序列长度线性相关，单层单头的 KV 字节数为 $2 \\times N \\times d_h \\times b$（$b$ 为字节宽度，系数 2 对应 K 与 V）。整模型 KV 占用再乘以层数与头数。因此视觉 token 数每增加 $\\Delta N$，KV cache 增量是 $\\Delta N$ 乘以每 token 每层 KV 字节再乘以层数。</p>\n<div class=\"formula\">$$N=\\frac{HW}{P^2},\\qquad \\text{KV}_{\\text{vision}} = 2 \\cdot N \\cdot L \\cdot H_k \\cdot d_h \\cdot b$$</div>\n<p>口径上必须区分“视觉塔自身激活”与“进入 LLM 后的 KV”。前者随 batch 内图像数线性增长，后者随 prefill 长度增长并与并发批大小相乘。工程判断：当 $N$ 超过语言模型单次 prefill 的舒适区间时，优先降低像素预算而不是缩小 $P$，因为 $P$ 与权重绑定、改动会破坏位置编码网格一致性。具体例子：同一张图按较高像素预算切出的 $N$ 是低预算档的数倍，若直接送进固定批大小的解码循环，KV cache 峰值会挤占解码阶段的剩余显存，表现为批大小被迫下调、吞吐下降。</p>\n\n<h3 id=\"ap-vision-encoder-terms-sec-9\">九 · 动态分辨率与位置插值判定</h3>\n<p>动态分辨率按输入长宽比与像素预算选择网格，网格一变，位置编码就必须双线性重采样到新网格。速查表在此处的判定口径是：记录预训练固定网格尺寸，记录本次推理目标网格，记录插值算法，三者缺一不可。若跳过插值直接外推，位置编码分布偏移会让注意力打分整体失真，视觉塔输出表面正常，但跨模态注意力打分偏移，检索与 grounding 指标同时下降。</p>\n<ul>\n<li>判定顺序：先确认目标网格与预训练网格是否一致；不一致则必须走插值路径。</li>\n<li>插值代价：重采样在视觉塔前向中引入额外张量操作，属于一次性开销，随 batch 内图像数线性增长，不进入 KV cache。</li>\n<li>口径陷阱：把“支持动态分辨率”写成能力声明而不写插值方式，等于把网格一致性责任推给下游。</li>\n</ul>\n<p>工程代价体现在延迟上：插值本身是轻量操作，但网格切换会改变 $N$，进而改变 prefill 长度与批调度器的分桶结果。具体例子：同一批内混入不同长宽比的图像，若按统一网格强制 resize，会引入形变并浪费像素预算；若按各自网格切分，则批内 $N$ 不一致，连续批处理需要按最大 $N$ 对齐或做 token 级 padding，两者都影响吞吐。速查表要求把“批内是否允许 $N$ 不一致”作为独立字段记录。</p>\n\n<h3 id=\"ap-vision-encoder-terms-sec-10\">十 · 输出形态与 projector 接口口径</h3>\n<p>CLIP 视觉塔用全局平均池化或 class token 汇聚为单一图像嵌入，SigLIP 视觉塔用 sigmoid 对比损失且常保留 patch token 序列供 projector 使用。输出形态不同，直接决定下游取单向量还是取 token 序列，这是速查表中唯一影响接口签名的字段。projector 负责把视觉塔特征维 $d_v$ 映射到语言模型隐藏维 $d_l$，接口文档必须同时写这两个数。</p>\n<table class=\"mini\">\n<thead><tr><th>输出形态</th><th>下游取用</th><th>接口字段</th><th>显存口径</th></tr></thead>\n<tbody>\n<tr><td>单图像嵌入（池化/class token）</td><td>取单向量，作为软提示或条件向量</td><td>$d_v$ 与 $d_l$</td><td>不进入 KV cache 序列，占用为常数</td></tr>\n<tr><td>patch token 序列</td><td>取 token 序列，经 projector 后进入 prefill</td><td>$N$、$d_v$、$d_l$、projector 类型</td><td>按 $N$ 计入 KV cache</td></tr>\n</tbody>\n</table>\n<p>失败模式在此处最隐蔽：把 projector 输出维度误当作视觉塔输出维度写进接口文档，下游按错误维度分配显存，prefill 阶段出现静默截断或维度不匹配报错。速查表的判定口径是：接口文档中 $d_v$ 标注为“视觉塔特征维”，$d_l$ 标注为“语言模型隐藏维”，projector 类型单独成行。工程代价：维度写错不会在视觉塔前向暴露，只会在 projector 之后、LLM 输入处暴露，定位成本高。具体例子：Q-Former 类 projector 输出的 token 数与视觉塔 patch 数不同，若接口只写 $N$ 而不写 projector 输出 token 数，下游按视觉塔 $N$ 分配 KV cache，实际 prefill 长度不符。</p>\n\n<h3 id=\"ap-vision-encoder-terms-sec-11\">十一 · 速查表落地检查项</h3>\n<p>速查表要能直接照着用，必须落到可勾选的检查项上。以下四项是跨团队联调前的最小核对集，每项都对应一个具体机制与一个代价口径。</p>\n<ul>\n<li>计数口径：视觉 token 数写明含/不含 class token，并写明是否经 projector 改变了 token 数。代价口径为 KV cache 预算与批大小的乘积关系。</li>\n<li>网格一致性：记录预训练网格、目标网格、插值方式三项。代价口径为注意力打分偏移导致的指标下降，属正确性问题而非性能问题。</li>\n<li>维度双写：$d_v$ 与 $d_l$ 同时出现在接口文档，projector 类型单独标注。代价口径为 prefill 阶段静默截断或维度报错。</li>\n<li>批内一致性：声明批内是否允许 $N$ 不一致，以及对齐策略（按最大 $N$ 对齐或 token 级 padding）。代价口径为连续批处理的吞吐与显存峰值。</li>\n</ul>\n<p>这四项的共同点是：任何一项缺失都不会在单团队内部暴露，只在跨团队拼接时暴露。工程判断是，把速查表作为接口文档的强制附录，字段缺失即拒绝联调，比事后排查 KV cache 对不上或维度报错的成本低一个量级。具体机制上，批内 $N$ 不一致时的对齐策略直接改变 prefill 的有效长度，进而改变批调度器的分桶与显存预留；速查表要求把对齐策略写成枚举值而非描述性文字，便于调度器直接读取。</p>\n\n<h3 id=\"ap-vision-encoder-terms-sec-12\">十二 · 速查表落地：字段、阈值与口径的边界条件</h3>\n<p>这张速查表的价值不在于“列全”，而在于每个字段都绑定一个可判定的口径与一个失效条件。字段分为五组：像素预算（$H\\times W$ 上限）、patch 大小 $P$、位置插值方式（双线性重采样/不外推）、class token 计入口径（含/不含）、projector 类型（MLP/线性/Q-Former）与输入维 $d_v$。阈值不是性能门限，而是契约门限：像素预算决定 $N=\\frac{HW}{P^2}$ 的上界，$P$ 与 $d$ 决定单 token 计算量，$d_v\\to d_l$ 的映射决定 projector 的显存与带宽占用。口径必须写成“$N$ 含 class token 与否”这样的显式断言，否则同一句“视觉 token 数”在容量估算里会差一个 token——单看微不足道，但在 KV cache 预算与批大小联调时，一个 token 的偏差会沿连续批处理放大成批边界错位。</p>\n<p>失效条件集中在三处。其一，动态分辨率切换网格后未同步插值位置编码：视觉塔输出数值看似正常，但位置编码分布偏移使跨模态注意力打分整体失真，检索与 grounding 指标同时下降，这类失效不报错、只掉点，最难在联调中被发现。其二，把 projector 输出维度当作视觉塔输出维度写进接口文档：下游按错误维度分配显存，prefill 阶段出现静默截断或维度不匹配报错，前者比后者更危险，因为截断后的 token 序列仍能跑通。其三，CLIP 与 SigLIP 输出形态混用：CLIP 经全局平均池化或 class token 汇聚为单一图像嵌入，SigLIP 常保留 patch token 序列供 projector 使用，下游若按单向量口径分配而实际拿到序列，prefill 长度估算直接失准。系统代价上，$N$ 是 LLM prefill 长度的主要构成项，$N$ 每增一份，prefill 的计算与 KV cache 显存同步增一份；projector 的 $d_v\\times d_l$ 映射则是一次稠密矩阵乘，其带宽开销与 $d_v$、$d_l$ 成正比，Q-Former 还额外引入可学习 query 的串行开销。</p>\n<div class=\"formula\">$$N_{\\text{prefill}} = N_{\\text{vision}} + N_{\\text{text}},\\quad N_{\\text{vision}} = \\frac{HW}{P^2} + \\mathbb{1}[\\text{class token}]$$</div>\n<table class=\"mini\"><thead><tr><th>字段</th><th>口径断言</th><th>失效条件</th><th>系统代价</th></tr></thead><tbody><tr><td>像素预算</td><td>$H\\times W$ 上限，按长宽比选网格</td><td>切换网格未同步插值</td><td>prefill 长度与 KV cache 线性增</td></tr><tr><td>patch 大小 $P$</td><td>与 $d$ 共同定单 token 计算量</td><td>跨团队 $P$ 不一致</td><td>视觉塔算力与序列长度反比</td></tr><tr><td>class token</td><td>显式声明含/不含</td><td>A 含 B 不含，差一个 token</td><td>批大小与 KV 预算错位</td></tr><tr><td>projector 输入维</td><td>$d_v$ 而非输出维 $d_l$</td><td>误写输出维进接口文档</td><td>显存错配、静默截断</td></tr><tr><td>输出形态</td><td>CLIP 单向量 / SigLIP 序列</td><td>下游按错形态分配</td><td>prefill 长度估算失准</td></tr></tbody></table>\n<p>工程判断落在“契约先行”：五项字段必须在接口文档里以断言形式固化，任何一项变更都要触发下游容量重算，而不是靠口头同步。速查表的用法是联调前的对表动作——逐项核对口径断言与失效条件，把“视觉 token 数”这类模糊表述替换成带 $P$、$HW$、class token 标志与 projector 类型的完整表达式。阈值一侧只保留可判定的量：像素预算上界、$P$ 取值、插值方式枚举、class token 布尔、projector 类型枚举，不引入无法从契约推出的性能门限。这样做的代价是文档变重、变更流程变长，收益是 prefill 长度、KV cache 预算与批大小三者在跨团队联调时不再各说各话。</p>\n\n<h3 id=\"ap-vision-encoder-terms-sec-13\">十三 · 速查表的失效边界：五项契约缺一即口径漂移</h3>\n<p>这张速查表能照着用，前提是五项契约同时落纸：像素预算、patch 大小、位置插值方式、是否保留 class token、projector 类型。缺任何一项，表里的“视觉 token 数”就退化为一个无口径的裸整数。最典型的失效是计数口径：团队 A 含 class token、团队 B 不含，容量估算相差一个 token，KV cache 预算与批大小在联调时对不上。这类误差不会在单测里暴露，只在压测的批边界上以显存溢出或吞吐台阶的形式出现，排查成本极高。因此速查表每一行都必须带“计数是否含 class token”这一列，而不是把它写进脚注。</p>\n<p>第二个失效条件是动态分辨率与位置插值的耦合。切换网格后若忘记同步重采样位置编码，视觉塔输出数值看似正常，但跨模态注意力打分整体偏移，检索与 grounding 指标同时下降——这是静默错误，没有报错、没有 NaN，只有端到端指标滑坡。速查表应把“插值方式”与“网格变更”绑定为一行原子操作，并给出判据：新网格的 $N=\\frac{HW}{P^2}$ 变化即触发插值，不允许外推。位置编码分布偏移的代价不是算力，而是整条评测链路的重跑。</p>\n<div class=\"formula\">$$N=\\frac{HW}{P^2},\\quad \\text{KV}_{\\text{vision}} \\approx 2 \\cdot L \\cdot N \\cdot d_l \\cdot b$$</div>\n<p>上式的口径意义大于数值意义：$N$ 是 prefill 长度的主要构成项，$L$ 为层数、$b$ 为字节数，class token 是否计入直接改变 $N$ 的奇偶。系统代价上，视觉 token 序列拉长会线性推高 prefill 延迟与 KV 显存，而 projector 把 $d_v$ 映射到 $d_l$ 时若接口文档误把 projector 输出维当作视觉塔输出维，下游按错误维度分配显存，prefill 阶段出现静默截断或维度不匹配报错——前者更危险，因为它不报错。</p>\n<table class=\"mini\"><thead><tr><th>字段</th><th>阈值/判据</th><th>口径</th></tr></thead><tbody><tr><td>视觉 token 数</td><td>网格变更即重算</td><td>声明含/不含 class token</td></tr><tr><td>位置插值</td><td>网格≠预训练网格必插值</td><td>双线性重采样，禁外推</td></tr><tr><td>projector 输入维</td><td>等于 $d_v$，非输出维</td><td>接口文档单列</td></tr><tr><td>输出形态</td><td>单向量或 token 序列</td><td>CLIP 汇聚 vs SigLIP 保留序列</td></tr></tbody></table>\n<h3 id=\"ap-vision-encoder-terms-sec-14\">十四 · 像素预算与 token 数的换算阈值</h3>\n<p>视觉编码器推理口径的第一道工程阈值，是把“像素预算”换算成“视觉 token 数”。给定 $N=\\frac{HW}{P^2}$，在 $P=14$ 的常见配置下，一张 $448\\times448$ 的图给出 $N=1024$；一张 $896\\times896$ 给出 $N=4096$。这意味着像素预算翻四倍，prefill 长度就翻四倍，KV cache 与注意力计算同步翻四倍。工程上真正需要盯住的不是“我传了多大图”，而是“这张图在视觉塔出口处贡献了多少个 token”。</p>\n<p>换算阈值的用法是反推：先由 SLO 决定单请求可承受的 prefill token 上限，再由该上限反推像素预算上限。设语言模型侧允许的视觉 token 上限为 $N_{\\max}$，则像素预算上限为 $H\\cdot W \\le N_{\\max}\\cdot P^2$。当 $N_{\\max}=2048$、$P=14$ 时，像素预算上限约为 $401408$ 像素，即约 $633\\times633$ 的正方形等效面积。动态分辨率按长宽比选网格时，这个上限是硬约束，任何“按原图比例放大”的预处理都必须在此截断。</p>\n<p>测量方法不依赖任何外部数字：取一批真实业务图像，用固定契约（像素预算、patch 大小、插值方式、class token 取舍、projector 类型）跑一遍视觉塔，统计 $N$ 的分布直方图与分位数。这个直方图就是容量规划的输入，也是判断“是否需要引入视觉 token 压缩”的唯一依据。代价面很直接：$N$ 每增加一档，prefill 延迟近似线性上升，而视觉塔本身的算力消耗与 $N\\cdot d$ 成正比，显存侧则体现在激活与 KV 两处。</p>\n\n<h3 id=\"ap-vision-encoder-terms-sec-15\">十五 · 位置插值的失配判据</h3>\n<p>动态分辨率切换网格后，位置编码必须双线性重采样到新网格。工程上判断“是否插值正确”不能靠肉眼看输出是否正常，因为失配时视觉塔输出在数值上仍然合理，偏差只体现在注意力打分上。可操作的判据是：对同一张图，分别用预训练固定网格与目标网格各跑一次，比较两者在若干固定 patch 位置上的注意力打分排序一致性。若排序发生系统性偏移，说明位置编码分布已经漂移。</p>\n<div class=\"formula\">$$\\text{score}_{ij}=\\frac{q_i k_j^{\\top}}{\\sqrt{d}},\\quad \\text{pos}(i,j)\\ \\text{由重采样网格决定}$$</div>\n<p>更省事的测量办法是构造一个受控探针：取一张网格状纹理图，其 patch 内容在空间上高度可区分，然后检查视觉塔输出的跨模态注意力是否把语言侧 query 落到正确的空间区域。若 grounding 指标与检索指标同时下降，且下降幅度随分辨率偏离预训练网格而增大，即可判定插值链路有问题。这类失配的代价不是崩溃而是静默劣化：延迟与吞吐不变，显存不变，但下游任务指标整体下移，属于最难在压测中发现的一类。</p>\n<p>工程判断上，把“插值方式”写进固定契约的第五项之外，还要在服务启动时做一次自检：用预训练网格尺寸与最大像素预算尺寸各跑一次探针图，比对注意力打分的相对偏差。偏差超过预设容忍带就拒绝上线该分辨率档位，而不是让它在流量里慢慢劣化。</p>\n\n<h3 id=\"ap-vision-encoder-terms-sec-16\">十六 · class token 与序列长度的计数口径</h3>\n<p>“视觉 token 数”这句话在跨团队讨论里至少有三种口径：不含 class token 的 patch 数、含 class token 的序列长度、以及经过 projector 之后进入语言模型的 token 数。三者可以互不相等。CLIP 视觉塔常以 class token 或全局池化汇聚为单向量，此时进入语言模型的可能只有一个或极少数 token；SigLIP 视觉塔常保留 patch token 序列交给 projector，此时进入语言模型的 token 数与 $N$ 同阶。</p>\n<p>计数口径失配的代价是可量化的：容量估算相差一个 token 时，KV cache 预算与批大小在联调时对不上，表现为压测中批大小被迫下调一档，或长序列请求被静默截断。测量方法是把三项计数同时打印进日志：patch 数、视觉塔输出序列长度、projector 输出 token 数。任何一项与契约声明不符即告警。这条日志的成本极低，但它是唯一能在联调阶段定位口径分歧的手段。</p>\n<p>具体例子：团队 A 按含 class token 计数做容量规划，团队 B 按不含计数做批调度，两边各自自洽，联调时 KV cache 预算差出一个 token 的份额，批大小对不上。修复不是改数字，而是把五项契约写进接口文档并在日志里强制声明。</p>\n\n<h3 id=\"ap-vision-encoder-terms-sec-17\">十七 · projector 维度的接口阈值</h3>\n<p>projector 接口的输入是视觉塔特征维 $d_v$，输出是语言模型隐藏维 $d_l$。工程上最常见的错误是把 projector 输出维度误当作视觉塔输出维度写进接口文档，下游按错误维度分配显存，prefill 阶段出现静默截断或维度不匹配报错。判断阈值很简单：接口文档里 $d_v$ 与 $d_l$ 必须成对出现，且明确标注哪一个是视觉塔出口、哪一个是语言模型入口。</p>\n<p>测量方法是在 projector 前后各打一次形状探针，记录张量的实际维度与 dtype。MLP、线性、Q-Former 三类 projector 的输出 token 数行为不同：MLP 与线性通常保持 token 数不变，只改维度；Q-Former 会把序列压缩到固定数量的 query token。因此“projector 类型”这一项契约同时决定了维度与 token 数两个量，缺一不可。代价面在于：维度写错时显存分配按错误尺寸进行，prefill 阶段的截断是静默的，不会抛错，只会让下游注意力拿到不完整的序列。</p>\n\n<h3 id=\"ap-vision-encoder-terms-sec-18\">十八 · 五项契约的自检清单与测量节奏</h3>\n<p>把像素预算、patch 大小、位置插值方式、class token 取舍、projector 类型写成固定契约后，还需要一套可执行的测量节奏，否则契约只是文档。建议的节奏是三层：启动时自检、变更时回归、容量规划时统计。</p>\n<ul>\n<li>启动自检：用固定探针图跑一遍视觉塔，打印 patch 数、视觉塔输出序列长度、projector 输出 token 数与 $d_v$、$d_l$，与契约逐项比对。</li>\n<li>变更回归：任何预处理、分辨率档位、插值方式或 projector 改动，都重跑探针图并比对注意力打分排序一致性。</li>\n<li>容量统计：对真实流量采样，统计 $N$ 的分布分位数，作为 KV cache 与批大小的输入。</li>\n</ul>\n<p>这三层测量的代价都不高，但覆盖了三类失败模式：计数口径分歧、插值失配、维度误标。表格给出每项契约对应的测量对象与失效表现，便于在联调时快速定位。</p>\n<table class=\"mini\"><thead><tr><th>契约项</th><th>测量对象</th><th>失效表现</th></tr></thead><tbody><tr><td>像素预算</td><td>$N$ 分布分位数</td><td>prefill 延迟超 SLO、批大小被迫下调</td></tr><tr><td>patch 大小</td><td>$N=\\frac{HW}{P^2}$ 换算</td><td>token 数口径与容量规划不一致</td></tr><tr><td>位置插值方式</td><td>注意力打分排序一致性</td><td>检索与 grounding 指标同时下降</td></tr><tr><td>class token 取舍</td><td>三项计数日志</td><td>KV cache 预算差一个 token、批大小对不上</td></tr><tr><td>projector 类型</td><td>$d_v$、$d_l$ 与输出 token 数</td><td>显存按错误维度分配、prefill 静默截断</td></tr></tbody></table>\n<p>工程判断落在最后一项上：这五项契约里，只有位置插值与 projector 维度会造成静默劣化，其余三项造成的是可观测的容量或延迟偏差。因此自检的优先级应当向这两项倾斜，把探针图与形状探针做成服务启动的强制步骤，而不是可选的调试开关。</p>\n\n\n<h3 id=\"ap-vision-encoder-terms-sec-19\">十九 · 阈值不是拍脑袋：像素预算、token 数与显存的三条硬边界</h3>\n<p>视觉编码器推理里真正会咬人的不是“平均情况”，而是几个临界点：像素预算跨过某条线后，prefill 长度从“可被连续批处理吸收”变成“单请求独占一个 batch slot”；patch 网格从方形切成非方形后，位置插值一旦漏做，注意力打分整体偏移而输出张量形状完全合法，监控上看不出异常。工程上必须把这三件事写成可测量的契约：像素预算 $S=H\\times W$、patch 边长 $P$、视觉 token 数 $N=S/P^2$（是否含 class token 单独标注）、projector 输入维 $d_v$ 与输出维 $d_l$。测量方法不是看单图延迟，而是固定 batch 内混合分辨率，记录每个请求的 $N$ 分布与 prefill 阶段实际占用 slot 的时长；只有这个分布才能回答“批大小该按哪个 $N$ 定”。系统代价直接落在 KV cache：视觉 token 进入 LLM prefill 后，其 KV 占用正比于 $N\\times L\\times 2\\times d_l\\times b$（$L$ 为层数、$b$ 为字节数），因此 $N$ 每翻一倍，同等显存下可容纳的并发请求数近似减半——这是容量规划里最容易被低估的一项，因为视觉塔本身的激活显存远小于它注入 LLM 的 KV 增量。</p>\n<p>第二个阈值是动态分辨率的切换点。按长宽比选网格时，常见做法是给定像素预算 $S$ 后取 $h=\\sqrt{S\\cdot r}$、$w=\\sqrt{S/r}$（$r$ 为宽高比），再各自对齐到 $P$ 的整数倍，于是实际 $N=\\lceil h/P\\rceil\\cdot\\lceil w/P\\rceil$ 往往略大于 $S/P^2$，这个“取整溢出”在高宽比极端时可达数个 token。测量方法是把候选网格逐一枚举，算出真实 $N$ 与插值后位置编码的最大偏移量，取二者都落在预算内的最大 $S$。失效条件很明确：预训练网格为固定方形，推理时若只改网格不做双线性重采样，位置编码索引超出训练分布，跨模态注意力打分整体偏移，表现为检索召回与 grounding 指标同时下滑而视觉塔输出统计量正常。代价是插值本身要重算位置编码表，属于每图像一次的小算子，但若在 host 侧做再拷回 device，就会在解码路径上引入同步点，把连续批处理的流水打断。</p>\n<p>第三个阈值是 projector 接口的维度契约。$d_v$ 是视觉塔输出特征维，$d_l$ 是语言模型隐藏维，projector 负责 $d_v\\to d_l$ 的映射；把 $d_l$ 误写进接口文档当作视觉塔输出维，下游按错误维度预分配显存，prefill 阶段要么静默截断要么在第一次 matmul 时报维度不匹配——前者更危险，因为截断后的 token 仍参与注意力，指标缓慢劣化而无人报警。测量方法是在接口层加一次形状断言并记录实际 $d_v$、$d_l$ 与 projector 类型（MLP/线性/Q-Former），三者任一变化都必须触发契约版本号变更。下表给出这五项契约在联调时最常对不上的口径，工程判断是：任何跨团队容量估算，先对齐“是否含 class token”与“$N$ 是预算值还是取整后的真实值”，这两项对不上，KV cache 预算与批大小的偏差就足以让联调阶段的吞吐目标落空。</p>\n<table class=\"mini\"><thead><tr><th>契约项</th><th>常见错位口径</th><th>系统代价</th></tr></thead><tbody><tr><td>token 计数</td><td>含/不含 class token</td><td>KV 预算差一个 token 量级，批大小对不上</td></tr><tr><td>像素预算</td><td>预算值 vs 取整后真实 $N$</td><td>高宽比极端时溢出数个 token</td></tr><tr><td>位置插值</td><td>切网格未同步重采样</td><td>打分整体偏移，检索/grounding 同降</td></tr><tr><td>输出维度</td><td>$d_v$ 与 $d_l$ 混写</td><td>显存错配、静默截断</td></tr></tbody></table>\n<p>没有实测数字时，测量口径本身要写死：单图延迟按“视觉塔前向 + projector + 注入 prefill”三段分别计时，避免把插值开销摊进视觉塔掩盖同步点；吞吐按固定 SLO 下每秒完成的图像数计，且必须报告混合分辨率分布的均值与尾部 $N$；显存按峰值 KV 增量与视觉塔激活分开记。工程判断落在最后一条：视觉编码器的阈值管理本质是把“形状合法”与“数值正确”分开验证——形状断言只能挡住维度错配，位置编码偏移和 class token 计数错位都必须靠指标回归（检索召回、grounding IoU）来兜底，因此每次改动像素预算或插值方式，回归集里必须包含极端宽高比样本，否则失效条件会在上线后才以“指标缓慢下降”的形式出现。</p>\n<h3 id=\"ap-vision-encoder-terms-sec-20\">二十 · 视觉口径三处静默错位：计数、插值、维度</h3>\n<p>视觉编码器推理的坑，绝大多数不是算子写错，而是<strong>口径错位</strong>：契约里少写一项，两个团队各自按默认值实现，联调时数值对不上却没有任何报错。最典型的三处错位都发生在“视觉 token 数”这一个词上。第一处是 class token：CLIP 类视觉塔用 class token 汇聚，SigLIP 类常保留 patch token 序列交给 projector，团队 A 按含 class token 计数、团队 B 按不含计数，容量估算相差一个 token——单看一个 token 微不足道，但它进入的是 LLM prefill 长度，KV cache 预算按 $2 \\cdot L \\cdot n_{kv} \\cdot d_h \\cdot b$ 线性放大，批大小在联调时就会对不上。第二处是位置插值：动态分辨率按长宽比与像素预算选了新网格，却忘记把预训练固定网格的位置编码双线性重采样过去，视觉塔前向不报错、输出张量形状完全正确，但注意力打分整体偏移，表现为检索与 grounding 指标同时下降——这是最贵的一类坑，因为监控上看不到异常，只能靠端到端指标回归发现。第三处是维度：把 projector 输出维度（语言模型隐藏维 $d_l$）误当作视觉塔输出维度 $d_v$ 写进接口文档，下游按错误维度分配显存，prefill 阶段出现静默截断或维度不匹配报错。三处错位的共同点是：<em>错误发生在契约层，暴露发生在系统层</em>，中间隔着数小时的联调与一次全量回归。</p>\n<p>防御方式是把五项写成不可省略的契约字段，并在每次前向时把实际值打回日志：像素预算、patch 大小 $P$、位置插值方式、是否保留 class token、projector 类型（MLP/线性/Q-Former）。任何一项在请求级别发生变化（动态分辨率必然让第一项变化），都必须触发插值路径的显式分支，而不是让框架默认走外推。</p>\n\n<h3 id=\"ap-vision-encoder-terms-sec-21\">二十一 · 踩坑清单：按代价排序的十类失败</h3>\n<p>把已知失败模式按“发现难度 × 影响面”排序，比按发生频率排序更有用，因为高代价坑的共同特征是<strong>静默</strong>。以下清单按修复代价从高到低排列，每项给出机制与系统代价。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>机制</th><th>系统代价</th></tr></thead><tbody>\n<tr><td>插值缺失导致打分偏移</td><td>新网格位置编码外推，分布偏移</td><td>端到端指标下降，无异常告警</td></tr>\n<tr><td>projector 维度错配</td><td>$d_v$ 与 $d_l$ 混用，显存按错维分配</td><td>prefill 静默截断或运行时报错</td></tr>\n<tr><td>class token 计数分歧</td><td>含/不含计数，prefill 长度差 1</td><td>KV cache 预算与批大小失配</td></tr>\n<tr><td>像素预算无上限</td><td>超高分辨率图使 $N=\\frac{HW}{P^2}$ 暴涨</td><td>视觉塔显存尖峰、prefill 延迟抖动</td></tr>\n<tr><td>动态分辨率抖动</td><td>同批内网格不一，padding 到最大网格</td><td>有效算力浪费、批吞吐下降</td></tr>\n<tr><td>视觉塔与 LLM 精度不一致</td><td>塔用 FP8、projector 用 BF16 混跑</td><td>数值漂移累积到跨模态注意力</td></tr>\n<tr><td>token 序列未截断</td><td>超长序列直接进 prefill</td><td>挤占 KV cache，挤掉同批其他请求</td></tr>\n<tr><td>预处理与推理网格不一致</td><td>工具链 resize 与塔的 patch 网格错位</td><td>图像内容被裁切，指标隐性下降</td></tr>\n<tr><td>缓存键未含分辨率</td><td>同一图不同网格命中同一视觉缓存</td><td>返回错误嵌入，难复现</td></tr>\n<tr><td>回滚未覆盖契约字段</td><td>只回滚权重不回滚配置</td><td>回滚后仍复现故障</td></tr>\n</tbody></table>\n<p>清单里前四项占了绝大多数线上事故。特别提“像素预算无上限”：$N=\\frac{HW}{P^2}$ 是二次增长，一张远超预算的图会让视觉塔激活显存与 prefill 长度同时跳变，而批调度器若按平均长度做容量规划，就会在这一张图上触发显存尖峰。工程判断是：像素预算必须在预处理层硬截断，而不是指望调度器兜底。</p>\n\n<h3 id=\"ap-vision-encoder-terms-sec-22\">二十二 · 检查顺序：从契约到端到端指标</h3>\n<p>检查顺序的设计原则是<strong>先验契约、后验数值、最后验指标</strong>，因为越靠后的检查越贵、越难定位。伪代码思路如下：</p>\n<div class=\"formula\">$$\\begin{aligned}\n&amp;\\text{check}_1: \\text{contract} \\leftarrow \\{P,\\ \\text{budget},\\ \\text{interp},\\ \\text{cls},\\ \\text{proj}\\}\\ \\text{五项齐全且请求级一致}\\\\\n&amp;\\text{check}_2: N_{\\text{actual}} = \\frac{HW}{P^2} + \\mathbb{1}[\\text{cls}]\\ \\text{与调度器估算逐请求对齐}\\\\\n&amp;\\text{check}_3: \\text{shape}(z_v) = [b, N, d_v],\\ \\text{shape}(z_p) = [b, N, d_l]\\\\\n&amp;\\text{check}_4: \\text{interp\\_path} = \\text{true}\\ \\text{当网格} \\neq \\text{预训练网格}\\\\\n&amp;\\text{check}_5: \\text{端到端指标回归（检索/grounding）}\n\\end{aligned}$$</div>\n<p>顺序上，check1 与 check2 是纯静态校验，成本近乎为零，应在每次配置变更时自动跑；check3 是形状断言，代价是一次前向的元数据检查；check4 需要比对预训练网格与运行时网格，属于配置层比对；check5 最贵，必须走全量回归集。实践中把 check1–check4 做成启动自检，check5 做成发布门禁，能把“插值缺失”这类静默坑挡在发布前。系统代价上，check5 的回归集若覆盖多分辨率与多长宽比样本，单次回归的 GPU 时间远高于前四项之和，但它是唯一能发现打分偏移的手段——因为偏移不改变任何张量形状。</p>\n<p>具体例子：某次动态分辨率开关上线后，check1–check4 全绿，check5 显示 grounding 指标下降而检索指标同步下降，定位到插值路径未触发；修复只需在网格切换处加一个双线性重采样分支，但若没有 check5，这个故障会以“模型变差”的形式被误判为权重问题，进而触发错误的回滚。</p>\n\n<h3 id=\"ap-vision-encoder-terms-sec-23\">二十三 · 回滚方案：配置、权重、缓存三层分离</h3>\n<p>回滚失效的根因是把回滚当成“换回旧权重”。视觉编码器推理的故障可能来自三层：<strong>契约配置层</strong>（像素预算、插值方式、projector 类型）、<strong>权重与精度层</strong>（视觉塔精度、projector 精度）、<strong>缓存层</strong>（视觉嵌入缓存键是否含分辨率与网格）。只回滚权重而配置未回滚，故障依旧复现；只回滚配置而缓存未失效，旧网格的嵌入会被新配置命中，返回错误结果且难复现。</p>\n<p>因此回滚方案必须按层设计版本号，并保证三层版本可独立回退又可组合回退。工程判断是：契约配置的版本号要打进每个请求的日志，缓存键必须包含契约版本与网格参数，这样任何一次回滚都能通过日志定位到具体是哪一层生效。代价方面，缓存键加长会略微增加缓存查找开销与内存占用，但相比“错误嵌入静默返回”的代价，这个开销可以忽略。回滚顺序建议为：先冻结新请求进入、再回滚配置、再失效缓存、最后回滚权重——因为配置错误的影响面最大且修复最快，权重回滚最慢且通常不是根因。</p>\n<p>具体例子：projector 维度错配事故中，正确回滚是先回滚接口文档与配置里的维度字段（配置层），再清空按错误维度分配的显存池（缓存层），最后确认权重未变——三步中只有第一步是真正的修复，后两步是清理残留状态。若只回滚权重，错误维度仍会从配置读出，故障原样复现。</p>\n\n<h3 id=\"ap-vision-encoder-terms-sec-24\">二十四 · 把检查清单固化为启动断言</h3>\n<p>清单与顺序若只写在文档里，就会在赶工期时被跳过。可行的固化方式是把 check1–check4 写成启动期断言，任何一项失败直接拒绝加载模型，而不是打警告继续跑。断言的具体形式：契约五项必须非空且请求级一致；$N_{\\text{actual}}$ 与调度器估算逐请求比对，偏差超过一个 token 即失败（这正好覆盖 class token 计数分歧）；$z_v$ 与 $z_p$ 的形状断言绑定到 projector 类型；网格与预训练网格不等时必须走插值分支，否则失败。系统代价是启动时间增加一次元数据比对与一次小批量前向，量级在秒级，换来的是把三类静默错位挡在服务启动之前。</p>\n<p>最后一层是监控侧的兜底：即便断言全绿，也要对“视觉 token 数分布”与“跨模态注意力打分均值”做在线监控，前者能发现像素预算被绕过，后者能发现插值路径在运行时被跳过。这两个指标都不依赖端到端回归集，能在分钟级暴露异常，是检查顺序中 check5 的在线补充。</p>\n\n<h3 id=\"ap-vision-encoder-terms-sec-25\">二十五 · 视觉编码器契约的失效边界与联调检查顺序</h3>\n<p>视觉编码器推理的绝大多数故障不是算子写错，而是五项契约参数在跨团队传递中发生了口径漂移。像素预算、patch 大小、位置插值方式、是否保留 class token、projector 类型，这五项一旦有一项没写进接口文档，同一句“视觉 token 数”就会指向不同对象。失效的典型形态是静默的：视觉塔输出张量形状合法、数值范围正常，错误却在下游以注意力打分整体偏移或显存分配不足的形式暴露。因此检查顺序必须从“口径”走向“数值”再走向“形状”，而不是反过来——先对齐契约，再验证位置编码分布，最后核对维度。顺序颠倒会导致在错误维度上做大量无谓的数值调试。</p>\n<p>第一顺位检查是 token 计数口径。序列长度 $N=\\frac{HW}{P^2}$ 是否含 class token，直接决定 LLM prefill 长度，进而决定 KV cache 预算与批大小。团队 A 按含 class token 计数、团队 B 按不含计数，容量估算相差一个 token，联调时 KV cache 预算与批大小就对不上。这个偏差在单请求下不可见，在连续批处理满载时才以显存溢出或批大小被迫下调的形式显现，系统代价是吞吐按比例损失。检查动作是让接口文档显式写出计数公式与是否含 class token，并在 prefill 长度统计处打点比对，而不是靠口头约定。第二顺位是位置插值。动态分辨率按长宽比与像素预算切换网格后，若忘记把预训练固定网格的位置编码双线性重采样到新网格，视觉塔输出看似正常，但跨模态注意力打分整体偏移，检索与 grounding 指标同时下降。这类失效不会报错，只会让指标缓慢劣化，定位成本极高。检查动作是在网格切换路径上断言位置编码的采样网格与当前 $H\\times W$ 一致，把插值方式作为契约字段随请求传递。</p>\n<p>第三顺位是维度归属。projector 输入的特征维 $d_v$ 是视觉塔输出维度，projector 输出才是语言模型隐藏维 $d_l$；把 projector 输出维度误当作视觉塔输出维度写进接口文档，下游会按错误维度分配显存，prefill 阶段出现静默截断或维度不匹配报错。系统代价体现在显存与带宽两侧：维度低估导致截断，高估则浪费 KV cache 与中间激活的显存预算。检查动作是在 projector 前后各打一次形状断言，并核对文档字段名是否区分 $d_v$ 与 $d_l$。回滚方案按失效类型分层：口径类失效回滚到上一版契约文档并冻结五项参数，位置插值类失效回滚到固定网格路径并关闭动态分辨率，维度类失效回滚到上一版 projector 接口并重放 prefill 形状断言。回滚的判据不是“指标恢复”，而是“契约字段与打点一致”，否则同一坑会在下一次网格切换时重现。</p>\n<table class=\"mini\"><thead><tr><th>检查顺位</th><th>失效形态</th><th>系统代价</th><th>回滚动作</th></tr></thead><tbody><tr><td>token 计数口径</td><td>KV cache 预算与批大小对不上</td><td>吞吐按比例损失</td><td>冻结五项契约参数</td></tr><tr><td>位置插值</td><td>注意力打分整体偏移，指标缓降</td><td>检索与 grounding 质量下降</td><td>关闭动态分辨率，回固定网格</td></tr><tr><td>维度归属</td><td>静默截断或维度报错</td><td>显存与带宽浪费</td><td>回上一版 projector 接口</td></tr></tbody></table>\n<h3 id=\"ap-vision-encoder-terms-sec-26\">二十六 · 上游依赖：像素预算与 patch 切分决定了下游一切长度的起点</h3>\n<p>视觉编码器条目在全书里不是孤立的一页，它处在一条“预处理→视觉塔→projector→LLM prefill→KV cache”链的最上游。上游依赖有两个层次。第一层是预处理工具链给出的张量形状：分辨率、长宽比、归一化方式。第二层是视觉塔自身的切分契约：patch 大小 $P$ 与特征维 $d$ 一旦写进配置，视觉 token 序列长度 $N=\\frac{HW}{P^2}$ 就被锁死，而这个 $N$ 是 LLM prefill 长度的主要构成项。换句话说，视觉编码器条目定义的是一串“长度预算”的源头，任何下游条目——多模态批调度、分离式预填、KV cache 容量规划——所处理的序列长度，都是从这里的 $H,W,P$ 推导出来的。</p>\n<p>这条依赖关系在工程上表现为一个硬约束：像素预算、patch 大小、位置插值方式、是否保留 class token、projector 类型这五项必须同时声明。跨团队讨论时少写一项，同一句“视觉 token 数”就指向不同口径。团队 A 按含 class token 计数、团队 B 按不含计数，容量估算相差一个 token，联调时 KV cache 预算与批大小对不上——这不是精度问题，而是接口契约问题。视觉编码器条目的价值就在于把这些参数固化成可被其他条目引用的定义，而不是让每个团队各自解释。</p>\n<p>代价层面，$P$ 与 $d$ 共同决定单 token 计算量与输出序列长度。缩小 $P$ 会以平方关系放大 $N$，直接抬高 prefill 的算力与显存占用；放大 $d$ 则抬高视觉塔自身的矩阵乘规模与 projector 输入带宽。因此视觉编码器条目的参数选择，等价于在“视觉保真度”和“prefill 长度预算”之间做一次不可逆的分配，下游条目只能在这个分配结果上做调度优化，无法回头修改它。</p>\n\n<h3 id=\"ap-vision-encoder-terms-sec-27\">二十七 · 下游影响：输出形态决定 projector 接口与跨模态注意力的输入契约</h3>\n<p>视觉塔的输出形态是 CLIP 与 SigLIP 两类条目的分水岭，也是下游影响的第一个分叉点。CLIP 视觉塔用全局平均池化或 class token 汇聚为单一图像嵌入；SigLIP 视觉塔用 sigmoid 对比损失，常保留 patch token 序列交给 projector。前者下游取单向量，后者下游取 token 序列。这个差异直接改变跨模态注意力条目的输入契约：单向量走的是把图像嵌入拼进文本序列的路径，token 序列走的是把 $N$ 个视觉 token 作为独立位置参与注意力的路径。两条路径的注意力掩码结构、位置编码对齐方式、以及 KV cache 中视觉段的条目数都不同。</p>\n<p>第二个分叉点是 projector 接口。图像塔输出维度 $d_v$ 是 projector 的输入特征维，projector 负责把 $d_v$ 映射到语言模型隐藏维 $d_l$。MLP、线性、Q-Former 三种 projector 类型对下游的影响不同：线性与 MLP 保持 token 数不变、只改维度，因此视觉段在 prefill 中的长度等于 $N$；Q-Former 则把 $N$ 个 patch token 压缩为固定数量的 query token，直接改写下游看到的序列长度。这意味着视觉 token 压缩条目所讨论的压缩比，在接口层面必须与 projector 类型一起声明，否则压缩收益无法被下游容量规划正确计入。</p>\n<p>工程代价体现在显存与带宽上。把 projector 输出维度误当作视觉塔输出维度写进接口文档，下游会按错误维度分配显存，prefill 阶段出现静默截断或维度不匹配报错。这类错误的代价不是一次报错，而是显存分配与 kernel 选择同时偏离，导致批大小被保守压低、吞吐下降。正确做法是把 $d_v$、$d_l$、projector 类型、输出 token 数四项写进同一份契约，让下游按契约而非按猜测分配。</p>\n\n<h3 id=\"ap-vision-encoder-terms-sec-28\">二十八 · 动态分辨率与位置插值的下游传导：一个被低估的全局偏移源</h3>\n<p>动态分辨率按输入长宽比与像素预算选择网格，位置插值把预训练固定网格的位置编码双线性重采样到新网格。这两件事发生在视觉塔内部，但其影响会传导到整条推理链。若不插值而直接外推，位置编码分布偏移会导致注意力打分失真；更隐蔽的失败是切换网格后忘记同步插值位置编码——视觉塔输出看似正常，跨模态注意力打分却整体偏移，表现为检索与 grounding 指标同时下降。这种失败不会在单测中暴露，因为视觉塔前向不报错、形状也对，错的是数值分布。</p>\n<div class=\"formula\">$$\\text{pos}_{\\text{new}} = \\text{BilinearResample}\\left(\\text{pos}_{\\text{pretrain}},\\ \\frac{H'}{P}\\times\\frac{W'}{P}\\right)$$</div>\n<p>对下游条目的传导路径是：位置编码偏移改变注意力打分，打分改变跨模态注意力条目的融合权重，融合权重改变生成质量，最终在多模态上线前清单的验收项上体现为指标不达标。因此视觉编码器条目必须把“网格切换即插值”写成强制契约，而不是可选优化。代价上，插值本身是轻量的重采样操作，但漏做插值的代价是整批请求的输出质量下降，且难以通过增加算力或调整批调度挽回——这是调度层无法修复的上游缺陷。</p>\n<p>具体例子：同一模型在固定网格下检索指标正常，切到按长宽比选网格的动态分辨率后，若插值未同步，grounding 与检索指标同时下滑，而视觉塔输出张量的形状与数值范围均无异常。排查时必须回到视觉编码器条目的五项契约逐项核对，而不是在下游调度或量化配方里找原因。</p>\n\n<h3 id=\"ap-vision-encoder-terms-sec-29\">二十九 · 与量化、显存、批调度条目的耦合点</h3>\n<p>视觉编码器条目与多模态量化配方的耦合点在数值精度上。视觉塔的矩阵乘与 projector 的映射层是否走 NVFP4/FP8，会改变 $d_v$ 与 $d_l$ 之间映射的数值误差，进而影响跨模态注意力的打分稳定性。量化配方条目讨论的是精度选择与校准，但它的输入契约来自视觉编码器条目：$d_v$ 的实际取值、projector 类型、以及视觉段 token 数决定了量化误差在序列上的累积方式。若契约里 $d_v$ 写错，量化校准的统计口径也随之错位。</p>\n<p>与视觉塔显存溢出条目的耦合点在峰值显存。视觉塔前向的激活峰值与 $N\\times d$ 成正比，动态分辨率抬高 $N$ 时峰值同步抬高；显存溢出条目处理的是溢出后的降级策略，但降级是否可行取决于视觉编码器条目是否允许在网格层面收缩像素预算。与多模态批饥饿条目的耦合点在批构成：视觉段长度 $N$ 的方差决定了批内序列长度的离散度，离散度大则连续批处理的填充浪费大，批饥饿更容易发生。视觉编码器条目通过固定 patch 与像素预算上限，实际上是在为批调度条目控制长度方差。</p>\n<table class=\"mini\"><thead><tr><th>下游条目</th><th>耦合参数</th><th>失效表现</th></tr></thead><tbody><tr><td>多模态量化配方</td><td>$d_v$、projector 类型</td><td>校准统计口径错位，打分漂移</td></tr><tr><td>视觉塔显存溢出</td><td>$N\\times d$ 峰值</td><td>降级策略不可行</td></tr><tr><td>多模态批调度</td><td>$N$ 的长度方差</td><td>填充浪费、批饥饿</td></tr><tr><td>分离式预填</td><td>视觉段 prefill 长度</td><td>预填/解码资源配比失衡</td></tr></tbody></table>\n\n<h3 id=\"ap-vision-encoder-terms-sec-30\">三十 · 在全书中的位置：术语表条目作为跨条目口径的锚</h3>\n<p>把视觉编码器术语表放在全书结构里看，它的位置是“口径锚”。全书七个领域的推理形态各自有不同的视觉输入特征——高分辨率文档、长视频、多图交错——但它们共享同一组视觉编码器参数口径。术语表条目的作用不是重复各领域配方，而是提供一个所有条目都能引用的定义层：$N=\\frac{HW}{P^2}$、$d_v$、$d_l$、projector 类型、class token 计数规则。其他条目在讨论压缩比、批大小、KV cache 预算、量化校准、分离式预填配比时，只需一句话指回本条目，避免每个条目各自重新定义一遍导致口径分裂。</p>\n<p>这也解释了为什么本条目把五项契约写成强制声明项：它是全书里少数几个“上游定义、下游引用”的条目之一。视觉 token 压缩术语讨论的是如何在 $N$ 上做减法，跨模态注意力术语讨论的是 $N$ 个 token 如何参与打分，多模态批调度术语讨论的是不同 $N$ 如何拼批——三者都建立在视觉编码器条目给出的 $N$ 与输出形态之上。若本条目口径不稳，下游三个条目的结论会同时失去可比性。</p>\n<p>工程判断上，维护这份口径锚的成本很低：一份包含五项参数的契约文档，加上网格切换即插值的强制检查。但它避免的代价是联调阶段的容量对不上、指标整体偏移、显存按错误维度分配这三类问题。对有多团队协作的多模态推理系统，这项投入的回报体现在联调周期而非单次推理延迟上——它不直接让某个 kernel 变快，但让所有下游优化建立在同一个长度与维度基准上。</p>\n\n<h3 id=\"ap-vision-encoder-terms-sec-31\">三十一 · 契约边界：五项声明缺一即口径漂移</h3>\n<p>本条目在全书中的位置是“口径层”而非“优化层”：它不提供任何加速手段，却决定上游视觉塔实现与下游 prefill 调度能否对齐。其上游依赖是 patch 切分参数（$P$、$d$）与位置编码方案，下游影响直接落在 LLM prefill 长度、KV cache 预算与批大小三处。工程上把像素预算、patch 大小、位置插值方式、是否保留 class token、projector 类型写成固定契约，五项必须同时声明——少一项，“视觉 token 数”这句话就指向不同对象。失效条件是契约被跨团队口头传递而非落成接口字段：团队 A 按含 class token 计数、团队 B 按不含计数，容量估算相差一个 token，KV cache 预算与批大小在联调时对不上，且这种偏差不会在单测中暴露，只会在压测的 OOM 或吞吐塌陷时显形。</p>\n<p>第二类失效来自动态分辨率与位置插值的解耦。按长宽比与像素预算选网格后，若忘记把预训练固定网格的位置编码双线性重采样到新网格而直接外推，位置编码分布偏移使注意力打分失真：视觉塔输出数值看似正常，跨模态注意力打分却整体偏移，表现为检索与 grounding 指标同时下降。这类故障的代价是隐性的——单帧延迟不变、显存不涨，但端到端质量指标下滑，排查时容易被误判为语言侧问题。系统代价可写成网格切换的约束式：</p>\n<div class=\"formula\">$$N_{\\text{vis}}=\\frac{HW}{P^2}+\\delta_{\\text{cls}},\\qquad L_{\\text{prefill}}=N_{\\text{vis}}+N_{\\text{text}}$$</div>\n<p>其中 $\\delta_{\\text{cls}}\\in\\{0,1\\}$ 即 class token 是否计入，$N_{\\text{vis}}$ 是 prefill 长度的主要构成项。像素预算上调一档，$N_{\\text{vis}}$ 随之线性上升，KV cache 占用与首 token 延迟同步抬升，因此契约里必须绑定“像素预算—网格—插值方式”三元组，不允许任一项单独变更。</p>\n<p>第三类失效在接口维度上：把 projector 输出维度误当作视觉塔输出维度写进接口文档，下游按错误维度分配显存，prefill 阶段出现静默截断或维度不匹配报错。正确口径是视觉塔特征维 $d_v$ 为 projector 输入，projector 负责把 $d_v$ 映射到语言模型隐藏维 $d_l$，二者不可混写。下游影响还体现在输出形态上：CLIP 视觉塔经全局平均池化或 class token 汇聚为单一图像嵌入，下游取单向量；SigLIP 常保留 patch token 序列供 projector 使用，下游取序列——同一 projector 类型（MLP/线性/Q-Former）在两种形态下的显存与算力开销不同，容量规划必须按形态而非按模型名立项。</p>\n<table class=\"mini\"><thead><tr><th>契约项</th><th>漏声明时的下游代价</th></tr></thead><tbody><tr><td>class token 计数</td><td>KV cache 预算与批大小差一个 token，联调对不上</td></tr><tr><td>位置插值方式</td><td>打分整体偏移，检索与 grounding 指标同降</td></tr><tr><td>$d_v$ 与 $d_l$ 区分</td><td>显存按错误维度分配，prefill 静默截断</td></tr></tbody></table>\n<table class=\"mini\" data-fig=\"app-t-ap-vision-encoder-terms\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>仓库</td><td>统一定义ViT patch切分、CLIP/SigLIP视觉塔、动态分辨率与位置插值、视觉token序列长度、图…</td></tr><tr><td>入口</td><td>见正文</td></tr><tr><td>依赖</td><td>见正文</td></tr><tr><td>最小复现</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-vision-encoder-terms · 共 5 个片段</p>\n"},{"id":"ap-token-compress-terms","title":"视觉token压缩术语","summary":"界定token合并、池化、Q-Former压缩、感知器重采样、空间下采样与token剪枝的差异，并标注各自对视觉信息保真度与后续LLM prefill长度的工程影响。","kind":"术语","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-1\">一 · 术语的边界：压缩的是&quot;序列&quot;，不是&quot;信息&quot;</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-2\">二 · 分类维度一：有无可学习参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-3\">三 · 分类维度二：输出长度与分辨率的耦合关系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-4\">四 · 分类维度三：保真度的空间结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-5\">五 · 与相邻概念的切分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-6\">六 · 定义带来的三个工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-7\">七 · 压缩方案的边界条件与批处理代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-8\">八 · 速查表的结构与口径约定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-9\">九 · 合并与池化：阈值该盯在哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-10\">十 · 固定 $K$ 方案：最容易踩的阈值陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-11\">十一 · 剪枝：位置与掩码的口径必须成对填</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-12\">十二 · 批内联动：合并率与序列长度必须同表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-13\">十三 · 阈值判据的落地写法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-14\">十四 · 速查表：压缩方案的失效边界与批内代价口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-15\">十五 · 阈值的物理来源：把压缩率锚定到可测的系统量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-16\">十六 · 合并率与池化的经验区间：按任务族分层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-17\">十七 · 剪枝的阈值：重要性分数与批内方差</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-18\">十八 · 固定 $K$ 方案的阈值：分辨率解耦的代价曲线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-19\">十九 · 测量方法：没有数字时怎么测</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-20\">二十 · 阈值联动的工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-21\">二十一 · 阈值从哪来：压缩率、批内方差与固定 K 的三条红线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-22\">二十二 · 踩坑清单：三类高频失败模式的结构性成因</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-23\">二十三 · 检查顺序：从数值到调度的四层递进</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-24\">二十四 · 合并率与批调度的联动检查</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-25\">二十五 · 保真度回滚：按任务形态而非按指标回滚</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-26\">二十六 · 上线前的压缩专项检查清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-27\">二十七 · 压缩链路上的三类失效与回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-28\">二十八 · 上游依赖：压缩策略被视觉塔与预处理钉死</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-29\">二十九 · 下游影响：压缩形态决定 LLM 侧的批处理与 KV 布局</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-30\">三十 · 与量化配方的耦合：压缩改变数值精度的作用面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-31\">三十一 · 与分离式预填、投机解码的接口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-32\">三十二 · 在全书中的位置：压缩是分辨率预算的执行器</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-token-compress-terms-sec-33\">三十三 · 压缩方案的上游依赖与下游耦合：从视觉塔输出契约到连续批处理分块</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-token-compress-terms\"><svg style=\"max-width:499px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 499.2 319\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"417.2\" height=\"83.0\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"53.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"57.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：视觉token压缩术语</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">界定token合并、池化、Q-Former压缩、感知器重采样、空间下采</text><text x=\"75.0\" y=\"78.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">样与to…</text><line x1=\"82.0\" y1=\"97.0\" x2=\"82.0\" y2=\"114.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 113.0 L 86.5 113.0 L 82.0 121.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"121.0\" width=\"417.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"143.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"147.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"148.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><line x1=\"82.0\" y1=\"167.9\" x2=\"82.0\" y2=\"184.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 183.9 L 86.5 183.9 L 82.0 191.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"191.9\" width=\"417.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"214.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"218.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"219.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"238.7\" x2=\"82.0\" y2=\"255.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 254.8 L 86.5 254.8 L 82.0 262.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"262.8\" width=\"417.2\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"285.2\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"289.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"290.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-token-compress-terms-sec-1\">一 · 术语的边界：压缩的是\"序列\"，不是\"信息\"</h3>\n<p>视觉 token 压缩这一族术语的共同前提，是把视觉塔输出的二维 patch 网格展平成一条序列之后，在进入 LLM 之前对这条序列做长度缩减。因此本卷所说的\"压缩\"，严格指<b>序列长度</b>的缩减，而不是视觉特征的维度缩减、不是权重量化、也不是图像分辨率本身的降低。这个边界必须先划清：一个 ViT 输出的 token 若保持 1024 维不变，仅把数量从 4096 降到 1024，属于本条目范围；若把每个 token 从 1024 维投影到 512 维而数量不变，则属于投影层/适配器设计，不在压缩术语之内。工程上区分的意义在于代价落点不同——长度缩减直接削减 LLM prefill 的算术量与 KV cache 容量，维度缩减削减的是视觉塔到 LLM 之间的搬运带宽与适配器参数量。</p>\n<p>据此，本条目收录六类机制：token 合并、池化、Q-Former 压缩、感知器重采样、空间下采样、token 剪枝。它们的共同输出是一个更短的 token 序列（或一个定长 latent 数组），差别在于\"用什么规则决定保留哪些信息\"以及\"输出长度是否与输入分辨率耦合\"。</p>\n<div class=\"formula\">$$N_{\\text{out}} = \\begin{cases} \\lceil N/r \\rceil &amp; \\text{合并、池化、空间下采样} \\\\ K &amp; \\text{Q-Former、感知器重采样} \\\\ N' &amp; \\text{剪枝（} N' \\text{ 为保留数）} \\end{cases}$$</div>\n<p>这条分段式就是整个术语表的骨架。它把六类机制分成三族：比率型、定长型、选择型。后续所有关于保真度、批内方差、显存解耦的判断，都可以回溯到输出长度属于哪一族。</p>\n\n<h3 id=\"ap-token-compress-terms-sec-2\">二 · 分类维度一：有无可学习参数</h3>\n<p>最常用的第一刀切在\"压缩规则是否由训练得到\"。token 合并与池化都不引入可学习参数：合并按相邻或语义相近的 token 配对后求平均，池化在固定窗口内做平均或最大汇聚。二者是纯几何/统计操作，行为在推理时完全确定，可以离线预算出压缩后的长度，也可以在不重新训练的情况下调整压缩率。代价是保真度损失集中在高频细节——平均操作天然是低通滤波，边缘、细笔画、小字符的响应被邻域稀释。</p>\n<p>Q-Former 压缩与感知器重采样则相反：用固定数量 $K$ 个可学习 query，通过 cross-attention 从视觉 token 中抽取信息。压缩规则由权重决定，无法在推理时无损改 $K$——改 $K$ 等于换一个模型。二者机制相同，区别在挂载位置：Q-Former 通常作为视觉塔与 LLM 之间的独立桥接模块，感知器重采样一般紧接视觉塔之后，以 latent 数组形式供 LLM 读取。这个位置差异影响的是显存驻留与流水线切分，而非压缩语义本身。</p>\n<p>工程代价上，无参数方案的收益是调度友好：合并率 $r$ 可以在服务端按 SLO 动态调，同一份权重支持多档压缩。有参数方案的收益是压缩质量上限更高，但把压缩率写死进了权重，容量规划时 $K$ 是一个不可协商的常数。举例：一个部署同时服务高分辨率文档与低分辨率缩略图，若用池化，可以按图像尺寸选不同窗口；若用固定 $K$ 的重采样器，缩略图被\"过度保留\"、文档被\"过度压缩\"，两端都不讨好。</p>\n\n<h3 id=\"ap-token-compress-terms-sec-3\">三 · 分类维度二：输出长度与分辨率的耦合关系</h3>\n<p>比率型（合并、池化、空间下采样）的输出长度是输入 token 数 $N$ 的函数，$N$ 又正比于分辨率。这意味着分辨率翻倍，prefill 长度翻倍，KV cache 按长度比例增长。空间下采样是这条线上最直接的一种：在 patch 网格层面做 $2\\times2$ 邻域合并，等价于增大有效 patch 尺寸，压缩率由网格步长决定，与合并/池化的区别只在于它发生在 patch 化阶段而非序列阶段，因而保留的是规整的网格结构。</p>\n<p>定长型（Q-Former、感知器重采样）把输出长度钉死在 $K$，与输入分辨率解耦。这是它最被低估的工程价值：显存与分辨率解耦，意味着服务端可以在不改变 KV cache 预算的前提下接纳更高分辨率的输入，容量规划从\"按最大分辨率预留\"变成\"按 $K$ 预留\"。代价是信息被压进一个固定容量的瓶颈，高分辨率带来的额外 token 只能争夺同样的 $K$ 个槽位。</p>\n<p>选择型（剪枝）的输出长度是保留数 $N'$，由注意力或重要性分数决定，因而<b>逐样本不同</b>。这是三族中唯一输出长度不确定的一族，也是批调度最不友好的一族。</p>\n<table class=\"mini\"><thead><tr><th>族</th><th>机制</th><th>输出长度</th><th>可学习参数</th><th>批内长度方差</th></tr></thead><tbody><tr><td>比率型</td><td>合并 / 池化 / 空间下采样</td><td>$\\lceil N/r\\rceil$</td><td>无</td><td>随分辨率变化，可预算</td></tr><tr><td>定长型</td><td>Q-Former / 感知器重采样</td><td>$K$</td><td>有</td><td>零</td></tr><tr><td>选择型</td><td>token 剪枝</td><td>$N'$</td><td>评分器可学习</td><td>大，逐样本不可预算</td></tr></tbody></table>\n\n<h3 id=\"ap-token-compress-terms-sec-4\">四 · 分类维度三：保真度的空间结构</h3>\n<p>第三个维度不是\"保真度高低\"，而是\"保真度损失落在什么结构上\"。合并与池化保留空间邻接关系：输出 token 仍对应输入网格上的一个连续区域，位置编码可以按比例缩放后继续使用，稠密定位任务（分割、检测框回归、密集 OCR）能从中受益，因为邻域平均不破坏拓扑。空间下采样同理，只是粒度更粗。</p>\n<p>Q-Former 类压缩保留语义但丢失精细坐标：$K$ 个 query 与图像区域的对应关系是软性的、由注意力权重隐式表达的，没有稳定的网格索引。这对\"这张图里有没有猫\"足够，对\"猫的左耳在哪个像素\"就不够。剪枝则相反：保留的 token 本身未经混合，保真度高，但保留位置不连续，序列不规则。</p>\n<p>不规则带来两个必须同步处理的工程动作：位置编码重排与注意力掩码重建。保留 token 的位置索引若仍指向原网格，跨模态注意力会读到错位的空间先验，表现为空间 grounding 的系统性偏移——不是随机噪声，而是方向一致的偏差，这类错误在评测中极易被平均指标掩盖。代价上，掩码重建让注意力核从规整的因果/全掩码退化为变长稀疏掩码，flash-attention 类核的块对齐效率下降，实际算力利用率低于理论值。</p>\n\n<h3 id=\"ap-token-compress-terms-sec-5\">五 · 与相邻概念的切分</h3>\n<p>必须与本条目区分的第一组概念是<b>视觉编码器侧的 token 数</b>。改变 patch 尺寸、改变输入分辨率、采用层次化视觉塔，都会改变 $N$，但它们发生在视觉塔内部，属于编码器设计，不属于\"压缩\"。区别在于：压缩是在 $N$ 已确定之后对其做后处理，编码器设计是在源头决定 $N$。工程上二者的代价落点也不同——前者只影响 LLM 侧 prefill 与 KV cache，后者同时影响视觉塔自身的算力与激活显存。</p>\n<p>第二组是<b>跨模态投影/适配器</b>。把视觉 token 投影到 LLM 隐空间是维度变换，长度不变；压缩是长度变换，维度不变。二者常被串在同一段流水线里，但容量规划时必须分开核算：投影层吃的是搬运带宽，压缩吃的是 prefill 算术量与 KV cache。</p>\n<p>第三组是<b>KV cache 量化与驱逐</b>。后者在解码阶段对已生成的 KV 做精度压缩或按重要性淘汰，属于显存管理；本条目讨论的压缩发生在 prefill 之前，削减的是\"将要写入 KV cache 的条目数\"。一个是写少，一个是写得省，不可互相替代。第四组是<b>多模态批调度</b>中的分块策略：压缩改变的是序列长度分布，调度改变的是如何把这条分布装进 GPU；压缩是调度的输入条件，不是调度本身。</p>\n\n<h3 id=\"ap-token-compress-terms-sec-6\">六 · 定义带来的三个工程判断</h3>\n<p>第一，固定 $K$ 不是可伸缩变量。把 Q-Former 的 $K$ 当作能随分辨率放大的参数，是高分辨率输入下信息被过度压缩的直接原因，小目标检测与 OCR 类任务的准确率会骤降。判断规则：若目标任务的判别依据落在小于有效 patch 尺度的区域上，定长型压缩的 $K$ 必须按该任务的最小可辨目标反推，而不是按平均图像尺寸设定。</p>\n<p>第二，压缩率必须与批内序列长度联动。同一批内不同分辨率图像经比率型压缩后长度差异过大时，连续批处理的分块策略失效，GPU 利用率被最短序列拖低——分块按最长序列对齐，短序列的槽位空转。工程上要么在预处理阶段把分辨率归一到一个窄区间，要么在调度层按压缩后长度分桶，而不是按原始分辨率分桶。</p>\n<p>第三，压缩族的选择应由\"位置是否需要被引用\"决定。下游若需要输出坐标、框、掩码，选保留空间邻接的比率型；若只需要语义标签或自由文本描述，定长型更省显存且使容量规划与分辨率解耦；只有在保留 token 本身保真度是硬约束、且能承担变长掩码开销时，才选剪枝。这个判断先于任何压缩率调参，因为三族的代价结构不同，调参无法弥补选错族带来的结构性损失。</p>\n\n<h3 id=\"ap-token-compress-terms-sec-7\">七 · 压缩方案的边界条件与批处理代价</h3>\n<p>六类压缩在工程上真正的分水岭不在“是否可学习”，而在长度是否可预测。合并与池化给出确定性的 $\\lceil N/r\\rceil$，剪枝给出依赖内容的 $N'$，Q-Former 与感知器重采样把长度钉死在 $K$。只有 $K$ 类方案让 KV cache 与输入分辨率彻底解耦，代价是压缩比随分辨率漂移：当视觉塔输出的 $N$ 远大于 $K$，每 query 需承担的 token 数按 $N/K$ 增长，cross-attention 的 softmax 在大量近邻 patch 上趋于平坦，小目标与 OCR 字符的判别性特征被平均掉，检测与识别精度骤降。因此 $K$ 必须随分辨率分档配置，或对高分辨率输入改用合并加局部保留的混合路径，而不能当作可无限外推的常量。</p>\n<p>剪枝的失效点不在丢弃本身，而在索引一致性。保留 token 的位置索引仍指向原 patch 网格，若未同步重排位置编码与注意力掩码，跨模态注意力的空间对应关系错位，grounding 出现系统性偏移；批内保留数 $N'$ 随图像内容波动，连续批处理的分块策略按最长序列预留，短序列的算力空转拉低 GPU 利用率。合并率与批内长度未联动时同理：同批不同分辨率图像压缩后长度差异过大，调度器只能按最大长度对齐，显存按峰值预留而实际占用参差。</p>\n<div class=\"formula\">$$L_{\\text{out}}=\\begin{cases}\\lceil N/r\\rceil &amp; \\text{合并、池化}\\\\ K &amp; \\text{Q-Former、重采样}\\\\ N' &amp; \\text{剪枝}\\end{cases}\\qquad \\text{KV}\\propto L_{\\text{out}}\\cdot d_{\\text{layer}}$$</div>\n<table class=\"mini\"><thead><tr><th>方案</th><th>长度可预测性</th><th>主要失效条件</th></tr></thead><tbody><tr><td>合并/池化</td><td>确定</td><td>高频细节丢失，稠密定位退化</td></tr><tr><td>Q-Former/重采样</td><td>固定 $K$</td><td>高分辨率下过度压缩</td></tr><tr><td>剪枝</td><td>内容相关</td><td>位置编码错位、批内方差大</td></tr></tbody></table>\n<p>系统代价上，固定 $K$ 方案把 prefill 长度与显存占用从分辨率中剥离，容量规划可按 $K$ 静态估算，但视觉塔侧的算力仍随 $N$ 增长，压缩只削减 LLM 侧开销而非前端编码开销；合并与池化按 $r$ 线性削减 prefill 与 KV，适合稠密定位任务且保留空间邻接；剪枝在保留 token 上保真度最高，却把不确定性引入调度层，需以长度分桶或 padding 上限换取批处理稳定性。</p>\n<h3 id=\"ap-token-compress-terms-sec-8\">八 · 速查表的结构与口径约定</h3>\n<p>这张表按“字段—阈值—口径”三列组织，目的是让工程师在写配置、审 PR、排查线上回归时能直接对照，而不是再去翻定义。字段列给出该压缩方案在代码与配置里最常出现的参数名与语义；阈值列给出触发“该换方案”或“该加保护”的判据，全部为定性或比例型判据，不依赖具体硬件型号；口径列说明这个字段在统计时算的是什么——是压缩前长度、压缩后长度、还是对 KV cache 的等效削减量。三列必须一起读：只看字段会漏掉口径差异，只看阈值会误判适用域。</p>\n<p>口径的第一条铁律是区分“序列长度口径”与“显存口径”。合并与池化把长度从 $N$ 降到 $\\lceil N/r\\rceil$，Q-Former 与感知器重采样把长度钉死为 $K$，剪枝把长度降为保留数 $N'$。四者对 KV cache 的削减量可按长度比例直接估算，但只有固定 $K$ 方案让显存与输入分辨率解耦。因此在容量规划表里，前两者的显存列必须写成“分辨率 × 合并率”的函数，后两者写成常数，混写会导致高分辨率档位的显存预估系统性偏低。</p>\n<div class=\"formula\">$$\\text{KV}_{\\text{eff}} = 2 \\cdot L \\cdot H_{\\text{kv}} \\cdot d_{\\text{head}} \\cdot N_{\\text{vis}} \\cdot b_{\\text{bytes}}$$</div>\n<p>其中 $N_{\\text{vis}}$ 取压缩后的长度：合并/池化为 $\\lceil N/r\\rceil$，固定 $K$ 方案为 $K$，剪枝为 $N'$。这条式子决定了速查表里“压缩后长度”字段必须与“每 token KV 字节数”分开填，否则不同精度（FP8 与 NVFP4 的 KV 量化）下的估算会串味。</p>\n<table class=\"mini\"><thead><tr><th>字段</th><th>阈值判据</th><th>口径</th></tr></thead><tbody><tr><td>合并率 $r$</td><td>$r$ 增大到使稠密定位任务指标出现可复现下降时停止上调</td><td>压缩前 token 数 ÷ 压缩后 token 数，按 $\\lceil N/r\\rceil$ 取整后回填</td></tr><tr><td>固定 query 数 $K$</td><td>输入分辨率提升而 $K$ 不变时，小目标与 OCR 类任务出现准确率骤降即为过压缩信号</td><td>输出长度常数，与分辨率无关；显存按 $K$ 计</td></tr><tr><td>保留率 $N'/N$</td><td>批内长度方差超过分块策略可容忍范围时判定剪枝不可用</td><td>保留 token 数占原网格 token 数的比例，需与位置重排同步统计</td></tr><tr><td>窗口尺寸（池化）</td><td>窗口跨越语义边界导致高频细节损失不可接受时改用合并</td><td>固定窗口内平均或最大汇聚，无学习参数</td></tr></tbody></table>\n\n<h3 id=\"ap-token-compress-terms-sec-9\">九 · 合并与池化：阈值该盯在哪里</h3>\n<p>合并与池化都不引入可学习参数，保真度损失集中在高频细节，因此阈值不能只看长度缩减比，要看“细节承载任务”的指标拐点。工程上把合并率 $r$ 的上限锚定在稠密定位任务（检测框回归、关键点、OCR 字符框）的指标开始可复现下滑的位置，而不是锚定在平均精度上——平均精度会被占多数的粗粒度样本掩盖。池化的窗口尺寸同理：窗口越大，空间邻接关系保留得越完整，但窗口内平均会把边界处的梯度抹平，跨语义边界的窗口是主要风险源。</p>\n<p>口径上有一个常被忽略的点：合并按相似度配对，配对结果依赖输入内容，因此同一张图在不同批内可能产生不同的压缩后长度；池化按固定窗口，长度只由 $N$ 与窗口尺寸决定，是确定性的。做连续批处理的分块策略时，确定性方案更容易预估，非确定性方案必须在调度器里预留长度方差余量。代价体现在 GPU 利用率上：批内长度方差越大，分块越难对齐，最短序列会把整批拖到低占用。</p>\n<ul>\n<li>机制：相似度配对求平均 vs 固定窗口汇聚，前者内容相关、后者形状相关。</li>\n<li>公式：压缩后长度 $\\lceil N/r\\rceil$，池化为 $\\lceil N/w^2\\rceil$（$w$ 为窗口边长）。</li>\n<li>代价：合并的配对开销是额外的一次相似度计算，属于 prefill 前的预处理延迟；池化几乎零开销但损失不可调。</li>\n<li>例子：高分辨率文档图做 OCR 时，池化窗口跨越字符行边界会造成字符粘连，此时应改用合并并降低 $r$。</li>\n</ul>\n\n<h3 id=\"ap-token-compress-terms-sec-10\">十 · 固定 $K$ 方案：最容易踩的阈值陷阱</h3>\n<p>Q-Former 与感知器重采样用固定数量 $K$ 个可学习 query 通过 cross-attention 抽取信息，输出长度与输入分辨率解耦。速查表里 $K$ 这一行的阈值判据必须写成“分辨率提升而 $K$ 不变时的任务指标”，而不是写成 $K$ 的绝对大小。失败模式很明确：把固定 $K$ 当作可随分辨率伸缩的变量，高分辨率输入下信息被过度压缩，小目标检测与 OCR 类任务准确率骤降。工程判断是——$K$ 是容量预算，不是自适应旋钮；分辨率档位提升时必须同步评估 $K$ 是否仍够用，或者把高分辨率样本路由到合并/池化路径。</p>\n<p>口径上，$K$ 方案的显存是常数，这让容量规划变得简单，但也让“分辨率越高越省”的直觉失效：分辨率翻倍时视觉塔的计算量上升，而 LLM prefill 长度不变，KV cache 不变，瓶颈从解码侧转移到视觉编码侧。此时优化重点应放在视觉塔的算子与精度（如视觉侧 FP8）上，而不是继续压 $K$。代价上，$K$ 过小带来的不是延迟问题而是保真度问题，且这种损失在离线评测里常被平均指标掩盖，必须单列小目标与 OCR 子集。</p>\n<div class=\"formula\">$$\\text{压缩比}_{\\text{fixed}} = \\frac{N}{K}, \\quad \\text{KV 削减} \\propto \\frac{K}{N}$$</div>\n<p>例子：同一批内混有低分辨率缩略图与高分辨率扫描件，若统一走固定 $K$，缩略图的压缩比接近 1（几乎无损），扫描件的压缩比极高（严重过压缩）。正确做法是按分辨率分档配置 $K$ 或分派到不同压缩路径，而不是让一个 $K$ 通吃。</p>\n\n<h3 id=\"ap-token-compress-terms-sec-11\">十一 · 剪枝：位置与掩码的口径必须成对填</h3>\n<p>token 剪枝按注意力或重要性分数丢弃整 token，保留位置不连续，因此速查表里“保留率”字段旁边必须紧跟“位置重排”与“掩码同步”两个布尔字段，三者成对填写。失败模式是剪枝后未重排位置编码与注意力掩码，保留 token 的位置索引仍指向原网格，跨模态注意力出现错位，表现为空间 grounding 系统性偏移。这种偏移在单图评测里可能被语言先验掩盖，在多图或视频帧序列里会放大。</p>\n<p>口径上，保留率 $N'/N$ 只描述数量，不描述分布：保留的 token 在网格上是否成簇、是否覆盖关键区域，决定了保真度的实际水平。剪枝在保留 token 上保真度高，但序列不规则、批内长度方差大，这是它与合并/池化的本质差异。工程代价体现在调度侧：长度方差大意味着连续批处理的分块策略容易失效，GPU 利用率被最短序列拖低；同时不规则序列对注意力核的掩码处理提出更高要求，掩码构造本身成为 prefill 延迟的一部分。</p>\n<ul>\n<li>机制：按分数丢弃整 token，保留位置不连续，需重排位置编码与掩码。</li>\n<li>公式：压缩后长度 $N'$，削减比例 $1 - N'/N$，但方差项需单独统计。</li>\n<li>代价：掩码与位置重排的构造开销、批内方差导致的利用率损失。</li>\n<li>例子：视频帧序列剪枝后若沿用原帧内网格索引，跨帧 grounding 会出现系统性偏移，需按帧重排并同步掩码。</li>\n</ul>\n\n<h3 id=\"ap-token-compress-terms-sec-12\">十二 · 批内联动：合并率与序列长度必须同表</h3>\n<p>速查表最后一行留给“批内长度联动”，因为这是三类方案共同的失效点：合并率与批内序列长度未联动，同一批内不同分辨率图像压缩后长度差异过大，连续批处理的分块策略失效、GPU 利用率被最短序列拖低。口径上要求把“压缩后长度”按批统计其最大值、最小值与方差，而不是只填均值。均值会掩盖长尾，而分块策略恰恰对长尾敏感。</p>\n<p>工程判断是：在调度器入口处对压缩后长度做一次分档，把长度接近的样本聚成批，或者对超长样本单独成批；固定 $K$ 方案天然方差小，合并与剪枝方案必须显式做这件事。代价上，分档本身增加调度复杂度，但换来的是分块对齐与更高的 SM 占用；不做分档时，视觉塔的算力被浪费在等待最短序列上，prefill 吞吐下降。这条与多模态批调度条目里的分块策略是同一件事的两个视角，此处只保留压缩侧的口径要求。</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>压缩后长度</th><th>批内方差</th><th>位置处理</th></tr></thead><tbody><tr><td>合并</td><td>$\\lceil N/r\\rceil$</td><td>中（内容相关）</td><td>邻接保留，无需重排</td></tr><tr><td>池化</td><td>$\\lceil N/w^2\\rceil$</td><td>低（形状确定）</td><td>邻接保留，无需重排</td></tr><tr><td>固定 $K$</td><td>$K$</td><td>零</td><td>无位置语义，需另行注入</td></tr><tr><td>剪枝</td><td>$N'$</td><td>高</td><td>必须重排位置与掩码</td></tr></tbody></table>\n<p>这张表的使用方式是：先按任务类型选行（稠密定位偏合并/池化，语义检索偏固定 $K$），再用批内方差列决定是否需要在调度器加分档，最后用位置处理列确认实现里有没有漏掉重排。任何一行在位置处理列填“无需”却在代码里做了重排，都是口径不一致的信号。</p>\n\n<h3 id=\"ap-token-compress-terms-sec-13\">十三 · 阈值判据的落地写法</h3>\n<p>阈值列全部写成“指标出现可复现下降”而非绝对数值，是因为保真度拐点随任务、分辨率、视觉塔精度变化，写死数字会在换模型时失效。落地时把每条阈值转成一个离线回归用例：稠密定位子集、OCR 子集、小目标子集各一组，压缩参数上调一档就跑一次，记录指标是否可复现下滑。这个用例集本身就是速查表的执行体——表是给人看的，用例是给 CI 跑的。</p>\n<p>口径列则要转成日志字段：压缩前长度、压缩后长度、合并率或保留率、批内长度方差、位置重排是否执行。缺任何一个字段，线上回归时都无法判断是压缩参数问题还是调度问题。特别是“位置重排是否执行”这个布尔字段，它对应的是 grounding 系统性偏移这一类最难在平均指标里发现的故障，必须显式打点。工程判断落在最后一句：速查表的价值不在于列全术语，而在于让每个字段都能被日志验证、被 CI 拦住。</p>\n\n<h3 id=\"ap-token-compress-terms-sec-14\">十四 · 速查表：压缩方案的失效边界与批内代价口径</h3>\n<p>这张表不重复各方案的定义，只给“什么时候会坏、坏了看哪个指标”。口径统一为：压缩率按 LLM prefill 长度计，即 $L_{\\text{prefill}} = \\lceil N/r\\rceil$（合并/池化）、$L_{\\text{prefill}} = K$（Q-Former/感知器重采样）、$L_{\\text{prefill}} = N'$（剪枝）；KV cache 占用按 $2 \\cdot L_{\\text{prefill}} \\cdot d_{\\text{head}} \\cdot n_{\\text{kv}} \\cdot b_{\\text{bytes}}$ 线性折算，因此压缩率直接等于显存削减比，但剪枝因批内长度方差大，须按批内最长序列而非均值预留。</p>\n<table class=\"mini\"><thead><tr><th>字段</th><th>阈值/判据</th><th>失效条件</th><th>系统代价落点</th></tr></thead><tbody><tr><td>固定 $K$ 与分辨率之比</td><td>$K$ 不随输入分辨率伸缩</td><td>高分辨率下 $N/K$ 过大，小目标与 OCR 精度骤降</td><td>精度损失不体现在延迟上，只体现在任务指标</td></tr><tr><td>剪枝后位置索引</td><td>保留 token 索引须重映射到压缩后网格</td><td>未重排位置编码与注意力掩码</td><td>空间 grounding 系统性偏移，且不报错</td></tr><tr><td>批内压缩后长度方差</td><td>$\\max L / \\min L$ 超过分块粒度</td><td>合并率与批内序列长度未联动</td><td>连续批处理分块失效，GPU 利用率被最短序列拖低</td></tr><tr><td>保真度取向</td><td>稠密定位选合并/池化；语义检索选 $K$ 方案</td><td>用 $K$ 方案做坐标回归</td><td>精细坐标丢失，KV 省了但重跑成本更高</td></tr></tbody></table>\n<p>第一类边界是“固定 $K$ 被当成可调变量”。Q-Former 与感知器重采样的输出长度与输入分辨率解耦，这是它省显存的来源，也是它在高分辨率输入下过压缩的根源：$N$ 随分辨率平方增长而 $K$ 不变，单位 query 承载的信息量随之上升，cross-attention 的注意力分布被迫摊薄，小目标与文字笔画这类高频信号最先被平均掉。工程判断是：一旦下游任务含 OCR 或小目标检测，$K$ 必须随分辨率分档上调，或改用保留空间邻接的合并/池化路径，不能指望“同一套 $K$ 打通所有分辨率”。</p>\n<p>第二类边界是剪枝的索引一致性。剪枝保留的 token 位置不连续，若位置编码仍指向原 patch 网格、掩码仍按原长度构造，跨模态注意力就会把保留 token 与错误的空间坐标对齐，表现为 grounding 整体偏移——这类错误不抛异常、不降吞吐，只让精度悄悄下滑，是最难在压测中发现的一类。第三类边界在批调度层：合并率固定而批内图像分辨率不一，压缩后长度差异被放大，连续批处理的分块策略按最长序列切分，短序列所在的块大量空转，GPU 利用率被最短序列拖低。可行口径是把合并率与批内长度联动，或按压缩后长度分桶成批，让 $L_{\\text{prefill}}$ 的方差落在分块粒度以内。</p>\n<h3 id=\"ap-token-compress-terms-sec-15\">十五 · 阈值的物理来源：把压缩率锚定到可测的系统量</h3>\n<p>视觉 token 压缩的工程阈值不是调参玄学，而是从三个可测量里反推出来的：视觉塔输出长度 $N$、LLM prefill 的每 token 边际成本、以及批内长度方差。合并率 $r$ 的候选值应当由目标 prefill 长度倒推，而不是先定 $r$ 再看好不好。给定目标序列长度 $N_{\\text{tgt}}$，合并率取 $r=\\lceil N/N_{\\text{tgt}}\\rceil$，再检查 $N_{\\text{tgt}}$ 是否落在连续批处理分块（chunk）的整数倍附近——落在非整数倍上会让分块边界切进图像 token 段，跨 chunk 的跨模态注意力需要额外拼接逻辑。</p>\n<p>对固定 $K$ 的 Q-Former／感知器重采样，阈值形式不同：$K$ 是显存预算的硬约束，一旦选定，视觉侧显存与输入分辨率解耦，代价是信息压缩比随分辨率上升而恶化。工程上应把 $K$ 与视觉塔输出长度 $N$ 的比值 $\\rho=K/N$ 作为监控量，而不是监控 $K$ 本身。$\\rho$ 低于某一水平时，小目标与 OCR 类任务的保真度开始塌陷，这个水平必须由本 workload 的评测集测出，不能跨任务借用。</p>\n<div class=\"formula\">$$\\rho=\\frac{K}{N},\\qquad N=\\frac{H\\cdot W}{p^{2}}$$</div>\n<p>其中 $H,W$ 为输入分辨率、$p$ 为 patch 边长。分辨率翻倍使 $N$ 变为四倍，$\\rho$ 变为四分之一，这就是“把固定 $K$ 当可伸缩变量”这一失败模式的定量根源。系统代价上，$\\rho$ 下降不改变 KV cache 占用（$K$ 固定），但改变视觉塔侧的算力与显存峰值——高分辨率下视觉塔激活随 $N$ 线性增长，而 LLM 侧不变，于是瓶颈从解码侧迁移到视觉编码侧。</p>\n\n<h3 id=\"ap-token-compress-terms-sec-16\">十六 · 合并率与池化的经验区间：按任务族分层</h3>\n<p>合并与池化不引入可学习参数，其阈值本质是“高频细节能丢多少”。稠密定位任务（检测、分割、文档版面）对 $2\\times2$ 邻域合并敏感，因为合并等价于增大有效 patch 尺寸，细粒度边界在合并后不可恢复；语义检索与图文匹配类任务对合并率容忍度高得多。工程做法是按任务族设定合并率上限，并在同一批内按分辨率联动：同一批内不同分辨率图像压缩后长度差异过大，会让连续批处理的分块策略失效、GPU 利用率被最短序列拖低，因此合并率必须与批内最大长度绑定，取使批内长度方差最小化的 $r$，而非全局统一 $r$。</p>\n<p>池化的窗口大小与合并率在长度上等价（窗口 $w\\times w$ 对应 $r=w^{2}$），但保真度损失分布不同：平均汇聚平滑高频，最大汇聚保留显著响应但丢失幅值信息。测量方法是构造一组只在高频细节上有差异的对照输入（同一场景的不同纹理版本），比较压缩前后下游任务输出的差异幅度，差异幅度相对未压缩基线的比值即为该窗口的保真度代价。系统代价上，池化与合并在视觉塔之后执行时是纯带宽操作：读 $N$ 个 token、写 $\\lceil N/r\\rceil$ 个，带宽开销与 $N$ 成正比，在视觉塔输出规模较大时这段搬运本身就会出现在 profile 里，需与视觉塔 kernel 融合以消除中间张量。</p>\n<ul>\n<li>稠密定位：合并率上限取低值，优先保空间邻接；池化窗口不宜超过 $2\\times2$。</li>\n<li>语义检索／分类：合并率可显著提高，长度缩减直接转化为 prefill 延迟下降。</li>\n<li>OCR／小目标：避免合并与池化，改用固定 $K$ 方案时须把 $\\rho$ 维持在评测集验证过的水平之上。</li>\n</ul>\n\n<h3 id=\"ap-token-compress-terms-sec-17\">十七 · 剪枝的阈值：重要性分数与批内方差</h3>\n<p>剪枝按注意力或重要性分数丢弃整 token，保留位置不连续，长度降为 $N'$。阈值是分数分位数：保留前 $q$ 分位，$N'=\\lfloor qN\\rfloor$。这里的关键工程量不是 $q$ 本身，而是批内 $N'$ 的方差——剪枝使序列不规则，批内长度方差大，连续批处理的分块与 padding 效率随之下降。测量方法是记录每个请求的 $N'$ 分布，计算其分位数跨度；跨度超过分块粒度的若干倍时，应改为按批统一 $q$ 或按长度桶分组调度。</p>\n<p>剪枝还有一项不可省的代价：保留 token 的位置索引仍指向原网格，必须同步重排位置编码与注意力掩码，否则跨模态注意力出现错位，表现为空间 grounding 系统性偏移。这项重排是 $O(N)$ 的索引操作，在 host 侧做会引入不可忽略的调度延迟，应放进 kernel 或预分配索引缓冲。系统代价上，剪枝的收益是 prefill 长度线性下降，代价是索引重排的额外 kernel 与批内方差带来的 padding 浪费；净收益在批内方差小时为正，方差大时可能被 padding 抵消。</p>\n<div class=\"formula\">$$N'=\\lfloor qN\\rfloor,\\qquad \\text{Var}_{\\text{batch}}(N')=\\text{Var}\\big(\\lfloor qN_{i}\\rfloor\\big)$$</div>\n\n<h3 id=\"ap-token-compress-terms-sec-18\">十八 · 固定 $K$ 方案的阈值：分辨率解耦的代价曲线</h3>\n<p>Q-Former 与感知器重采样把长度固定为 $K$，使显存与分辨率解耦：KV cache 削减量按长度比例估算时，固定 $K$ 方案在低分辨率下可能比合并更费显存（$K&gt;N/r$），在高分辨率下则显著更省。阈值因此是分辨率的分界点：令 $K=N/r$ 解出临界分辨率，低于它用合并／池化更省，高于它用固定 $K$ 更省。这条曲线必须按实际 $K$ 与 $r$ 画出来，而不是凭直觉选方案。</p>\n<p>保真度侧，固定 $K$ 保留语义但丢失精细坐标，高分辨率输入下信息被过度压缩，小目标检测与 OCR 类任务准确率骤降。测量方法是分层评测：在同一评测集上按目标尺寸分桶统计准确率，观察准确率随目标尺寸下降的拐点，该拐点对应的 $\\rho$ 即为该任务族的可用下界。系统代价上，固定 $K$ 让 LLM prefill 长度恒定，分块策略简单、批内方差近零，调度侧收益明显；代价集中在视觉塔与 cross-attention 抽取环节，$K$ 个 query 对 $N$ 个 token 的注意力计算量为 $O(KN)$，高分辨率下这段计算会成为视觉侧主耗时。</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>长度</th><th>批内方差</th><th>显存随分辨率</th><th>主要代价位置</th></tr></thead><tbody><tr><td>合并／池化</td><td>$\\lceil N/r\\rceil$</td><td>中（随分辨率线性）</td><td>线性</td><td>视觉塔后带宽搬运</td></tr><tr><td>固定 $K$</td><td>$K$</td><td>近零</td><td>解耦</td><td>$O(KN)$ 抽取计算</td></tr><tr><td>剪枝</td><td>$N'$</td><td>高</td><td>线性</td><td>索引重排 + padding</td></tr></tbody></table>\n\n<h3 id=\"ap-token-compress-terms-sec-19\">十九 · 测量方法：没有数字时怎么测</h3>\n<p>三类量必须分开测，混在一起测会得出互相矛盾的结论。第一类是保真度：用分层对照输入（按目标尺寸、文本密度、纹理频率分桶）跑下游任务，记录相对未压缩基线的准确率差；这是唯一能定出 $\\rho$ 下界与合并率上限的方法。第二类是系统量：分别测视觉编码侧耗时、压缩算子耗时、LLM prefill 耗时与 KV cache 峰值，四者随时间线对齐，才能看出瓶颈迁移；只测端到端延迟会掩盖压缩算子本身的带宽开销。第三类是调度量：记录批内压缩后长度分布、分块命中率与 padding 比例，用于判断合并率是否与批内长度联动得当。</p>\n<p>测量时必须固定分辨率分布与批组成，否则长度方差的变化会被误读为压缩策略的效果。对固定 $K$ 方案，额外测 $\\rho$ 的分布而非均值——均值达标而长尾过低时，长尾请求正是准确率塌陷的来源。对剪枝，额外测位置索引重排的正确性：构造已知空间关系的对照样本，检查 grounding 输出是否系统性偏移，这是掩码未同步的典型症状。</p>\n<ul>\n<li>保真度：分层对照 + 相对基线差值，按任务族分别定阈值。</li>\n<li>系统量：四段耗时对齐 + KV cache 峰值，识别瓶颈迁移点。</li>\n<li>调度量：批内长度分布、分块命中率、padding 比例。</li>\n<li>正确性：剪枝后位置编码与掩码一致性检查。</li>\n</ul>\n\n<h3 id=\"ap-token-compress-terms-sec-20\">二十 · 阈值联动的工程判断</h3>\n<p>阈值之间不是独立的：合并率决定批内长度方差，方差决定分块策略，分块策略又反过来约束合并率可取的值。工程上应把这条链写成一个约束求解：给定 SLO 的目标 prefill 延迟上界与显存预算，先由显存定 $K$ 或 $r$ 的上界，再由批内方差定分块粒度，最后由保真度评测定下界，取交集。交集为空时，说明该任务族在当前分辨率下不适合单一压缩策略，应改为按分辨率或按任务类型路由到不同压缩路径——这正是多模态批调度层面要处理的问题，此处只标注接口。</p>\n<p>一个具体的工程判断：当 $\\rho$ 的长尾低于评测集验证的下界，且这些长尾请求恰好是高分辨率输入时，正确动作不是调低 $K$，而是对这些请求旁路固定 $K$ 路径、改走合并或不下采样，把长度方差重新引入调度层并用长度桶吸收。代价是批内方差回升、padding 比例上升，收益是长尾准确率回到基线；这笔交换是否划算，取决于该任务族的准确率权重与吞吐 SLO 的相对紧迫度，必须由测量数据而非默认配置决定。</p>\n\n<h3 id=\"ap-token-compress-terms-sec-21\">二十一 · 阈值从哪来：压缩率、批内方差与固定 K 的三条红线</h3>\n<p>视觉 token 压缩的工程阈值不是调参偏好，而是由三条互相牵制的红线决定：合并率 $r$ 决定 prefill 长度 $\\lceil N/r\\rceil$ 与 KV cache 的线性削减；批内压缩后长度方差决定连续批处理的分块效率；固定 $K$ 方案则把显存与分辨率解耦，代价是信息容量与分辨率脱钩。测量方法上，先固定分辨率与 batch，扫 $r\\in\\{2,4,8\\}$ 或 $K$，同时记录三项：单请求 TTFT（prefill 主导）、稳态 tokens/s、以及峰值 KV 占用。判据是边际收益——当 $r$ 再翻一倍而 TTFT 改善不足、且稠密定位类样本的 grounding 误差开始抬升时，该点即为该任务的合并率上限。对稠密任务（小目标检测、OCR、文档版面），上限通常落在低合并率一侧；对语义检索类任务，上限可以更激进。没有实测就不要写死数字，把扫描脚本与判据固化进评测流水线，让阈值随模型与分辨率版本一起回归。</p>\n<p>批内方差这条红线最容易被忽略。合并与池化把长度压到 $N/r$，但同一批里不同分辨率图像的 $N$ 本就不同，压缩后长度差异被同步放大；连续批处理的分块策略按最长序列预留 KV 与计算槽位，最短序列的 GPU 利用率被拖低。可用的量化指标是批内长度极差比 $\\rho=\\max_i L_i/\\min_i L_i$（$L_i$ 为压缩后长度），工程上以 $\\rho$ 超过分块粒度所容忍的倍率为触发条件，改用分辨率分桶或按 $\\rho$ 动态拆批。代价是调度复杂度与桶内空转，收益是避免整批被一条长序列钉死。</p>\n<div class=\"formula\">$$\\text{KV}_{\\text{peak}}\\approx B\\cdot L_{\\max}\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot 2\\ \\text{bytes（FP8 时减半）},\\quad L_{\\max}=\\max_i L_i$$</div>\n<p>固定 $K$ 的失效条件很明确：把 $K$ 当成可随分辨率伸缩的变量。高分辨率输入下视觉 token 数 $N$ 增大而 $K$ 不变，压缩比 $N/K$ 随之上升，信息被过度压缩，小目标与 OCR 类任务准确率骤降；此时显存虽与分辨率解耦，保真度却与分辨率反向挂钩。测量办法是固定 $K$、阶梯提升输入分辨率，观察稠密任务指标随 $N/K$ 的衰减曲线，找到拐点后再决定是否让 $K$ 随分辨率分段抬升——抬升 $K$ 会重新把 prefill 长度与 KV 占用绑回分辨率，这是一次显式的容量交易，必须计入容量规划而非事后补救。</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>压缩后长度</th><th>主要失效条件</th><th>系统代价</th></tr></thead><tbody><tr><td>合并/池化</td><td>$\\lceil N/r\\rceil$</td><td>高频细节丢失，稠密定位退化</td><td>批内长度方差放大，分块失效</td></tr><tr><td>Q-Former/重采样</td><td>$K$（固定）</td><td>$N/K$ 过高时信息过压缩</td><td>抬升 $K$ 即重新绑定分辨率与显存</td></tr><tr><td>token 剪枝</td><td>$N'$（不规则）</td><td>位置编码与掩码未重排致 grounding 偏移</td><td>批内方差最大，掩码与索引开销上升</td></tr></tbody></table>\n<p>剪枝的边界在索引一致性：保留 token 的位置索引若仍指向原网格，跨模态注意力出现系统性空间偏移，表现为 grounding 整体漂移而非随机噪声——这种偏差在评测里表现为固定方向的误差，容易误判为模型能力问题。测量时应单独跑一组位置重排前后的对照，确认偏移消失再谈压缩收益；同时记录掩码构造与索引重排的额外 kernel 时间，这部分开销在短序列、高 batch 场景下会侵蚀剪枝带来的吞吐收益。</p>\n<h3 id=\"ap-token-compress-terms-sec-22\">二十二 · 踩坑清单：三类高频失败模式的结构性成因</h3>\n<p>视觉 token 压缩上线后最典型的翻车不是“压缩率不够高”，而是压缩语义与下游消费方式错配。第一类坑是<strong>把固定 K 当作可伸缩变量</strong>：Q-Former 与感知器重采样的输出长度 $K$ 与输入分辨率解耦，这本来是显存规划的优势，但工程上常被误当成“分辨率涨了 K 也该涨”的旋钮。高分辨率输入下视觉 token 数 $N$ 随 patch 网格平方增长，而 cross-attention 只有 $K$ 个 query 去抽取，信息瓶颈落在 query 侧而非输入侧，小目标与 OCR 类稠密文本的召回被系统性削掉。判断依据很直接：把分辨率翻倍后若压缩后长度不变而任务指标掉档，瓶颈就在 $K$，不在视觉塔。</p>\n<p>第二类坑是<strong>剪枝后位置语义未重建</strong>。token 剪枝按重要性分数丢弃整 token，保留位置不连续，若位置编码仍按原网格索引注入、注意力掩码仍按原长度构造，跨模态注意力就会把文本 query 对齐到错误的网格坐标，表现为空间 grounding 的稳定偏移而非随机噪声——偏移方向一致恰恰是索引错位的指纹。第三类坑是<strong>合并率与批内长度未联动</strong>：同一批里不同分辨率图像经合并/池化后长度从 $N$ 降到 $\\lceil N/r\\rceil$，方差被压缩率放大，连续批处理的分块策略按最长序列切分，短序列填充浪费显存与算力，GPU 利用率被批内最短序列拖低。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>可观测症状</th><th>根因定位</th></tr></thead><tbody><tr><td>固定 K 过度压缩</td><td>小目标/OCR 指标骤降，分辨率提升无收益</td><td>query 数量与信息量不匹配</td></tr><tr><td>剪枝位置错位</td><td>grounding 偏移方向一致</td><td>位置编码/掩码未按保留索引重排</td></tr><tr><td>批内长度方差</td><td>SM 占用低、tokens/s 抖动</td><td>合并率未与批调度联动</td></tr></tbody></table>\n\n<h3 id=\"ap-token-compress-terms-sec-23\">二十三 · 检查顺序：从数值到调度的四层递进</h3>\n<p>排查必须按代价从低到高、从局部到全局的顺序推进，避免一上来就动调度器。第一层查<strong>压缩算子本身的数值行为</strong>：合并是相似度配对求平均、池化是窗口内平均或最大汇聚，二者都不引入可学习参数，损失集中在高频细节。用一组含细纹理与密集小字的固定样本做前后对比，若高频区域出现块状模糊而平坦区域无损，说明合并窗口或池化核过大，此时应缩小窗口而非换压缩族。</p>\n<p>第二层查<strong>长度契约</strong>：压缩输出长度必须与下游 LLM prefill 的假设一致。合并/池化给 $\\lceil N/r\\rceil$、Q-Former 类给 $K$、剪枝给 $N'$，三者混用时若框架按固定长度预分配 KV cache 或按固定形状编译图，长度不符会触发重编译或隐式填充。检查方式是打印压缩后张量的实际 shape 与调度器记录的序列长度，二者不等即为契约破裂。</p>\n<p>第三层查<strong>位置与掩码一致性</strong>：仅剪枝路径需要，验证保留 token 的网格坐标是否随索引重排、掩码是否同步收缩。第四层才查<strong>批级联动</strong>：统计一个 batch 内压缩后长度的极差与分位数，若极差超过分块阈值的容忍带，说明合并率需要按分辨率分档配置，或调度器需按压缩后长度而非原始分辨率分桶。这个顺序的理由是：前三层的错误会伪装成精度问题，只有排除了它们，批级指标才有解释力。</p>\n<div class=\"formula\">$$\\text{压缩后长度}=\\begin{cases}\\lceil N/r\\rceil &amp; \\text{合并/池化}\\\\ K &amp; \\text{Q-Former/感知器重采样}\\\\ N' &amp; \\text{剪枝}\\end{cases}$$</div>\n\n<h3 id=\"ap-token-compress-terms-sec-24\">二十四 · 合并率与批调度的联动检查</h3>\n<p>合并率 $r$ 是一个全局参数，但它的代价按批而非按样本结算。设批内第 $i$ 个样本原始视觉 token 数为 $N_i$，压缩后为 $L_i=\\lceil N_i/r\\rceil$，连续批处理的分块若以 $\\max_i L_i$ 为基准，则填充浪费正比于 $\\max_i L_i-\\overline{L_i}$。分辨率异构的批（例如同一请求里混入缩略图与整页扫描件）会让这一差值迅速放大。检查清单应包含：批内长度分布的 p50 与 p99 之比、分块利用率、以及压缩前后批内长度方差的变化倍数——若方差被放大到调度器分桶失效的程度，正确做法是按压缩后长度分桶而非按原始分辨率分桶。</p>\n<p>具体例子：一个视觉问答服务同时接收 336 像素级缩略图与高分辨率文档图，前者压缩后长度很小，后者在固定 $K$ 方案下长度不变。若按原始分辨率分桶，两桶内部长度仍不齐；若按压缩后长度分桶，Q-Former 路径天然落进同一桶（长度恒为 $K$），而合并路径则按 $r$ 分档。代价体现在显存侧：KV cache 按长度比例估算削减量，固定 $K$ 方案使显存与分辨率解耦，这是它相对合并/池化的结构性优势，但前提是调度器真的按 $K$ 分配而非按原始 token 数预留。</p>\n<ul><li>检查项：压缩后长度是否进入调度器的分桶键，而非仅作日志字段。</li><li>检查项：KV cache 预分配是按压缩后长度还是按视觉塔输出长度，后者会造成成倍显存浪费。</li><li>检查项：批内极差是否触发分块退化，表现为 SM 占用率与 tokens/s 同步下滑。</li></ul>\n\n<h3 id=\"ap-token-compress-terms-sec-25\">二十五 · 保真度回滚：按任务形态而非按指标回滚</h3>\n<p>回滚方案不能是“指标掉了就关压缩”，因为压缩族与任务形态的匹配关系是结构性的。合并/池化保留空间邻接关系，适合稠密定位任务；Q-Former 类保留语义但丢失精细坐标；剪枝在保留 token 上保真度高但序列不规则。因此回滚应分级：第一级是<strong>参数回滚</strong>，把合并率 $r$ 调低或把 $K$ 调高，代价是 prefill 长度回升、KV cache 与首 token 延迟同步上涨；第二级是<strong>压缩族回滚</strong>，从固定 $K$ 切回合并/池化以恢复坐标保真度，代价是长度重新与分辨率耦合、批内方差回归；第三级是<strong>路径回滚</strong>，对特定任务路由到不压缩路径，代价是那部分请求的显存与算力按原始 token 数结算。</p>\n<p>分级的判据要落在可观测信号上：若偏移是方向一致的 grounding 误差，回滚到位置重排修复而非降压缩率；若误差集中在高频细节且随 $r$ 单调恶化，降 $r$ 有效；若高分辨率下指标塌陷而低分辨率正常，问题在 $K$ 与分辨率的解耦，应提高 $K$ 或改走合并路径。回滚还必须带<strong>灰度边界</strong>：按任务类型而非按流量比例切分，因为同一服务里 OCR 请求与自然图像描述对压缩的敏感度不在一个量级，按流量随机灰度会把两类请求混在同一批里，污染判断。</p>\n\n<h3 id=\"ap-token-compress-terms-sec-26\">二十六 · 上线前的压缩专项检查清单</h3>\n<p>把上述内容收敛成一份可执行的清单，顺序即排查顺序。第一，<strong>数值层</strong>：固定样本集上比对压缩前后高频区域，确认合并窗口/池化核与任务粒度匹配。第二，<strong>契约层</strong>：压缩输出 shape 与调度器、KV cache 预分配、图编译假设三者一致。第三，<strong>位置层</strong>：仅剪枝路径，验证位置编码重排与掩码收缩，用合成网格样本检查 grounding 偏移是否为零。第四，<strong>批层</strong>：批内压缩后长度极差、分桶键、分块利用率。第五，<strong>回滚层</strong>：三级回滚的触发阈值与灰度切分维度已配置，且回滚后 prefill 长度与显存的回升量已预估。</p>\n<p>每一项都对应一个具体的系统代价：数值层失误换来的是精度不可逆损失；契约层失误换来的是隐式填充导致的显存浪费与重编译抖动；位置层失误换来的是系统性 grounding 偏移，且这种偏移不会被 loss 曲线暴露；批层失误换来的是 GPU 利用率被最短序列拖低；回滚层缺失换来的是故障时只能全量关压缩，prefill 长度瞬间回到 $N$，KV cache 按长度比例膨胀，首 token 延迟与吞吐同时恶化。检查清单的价值不在于列全，而在于固定顺序——先证伪低代价层，再动高代价层，避免把调度问题误诊为压缩精度问题。</p>\n<p>最后一条工程判断：压缩方案的稳定性取决于<strong>长度语义是否单一来源</strong>。合并率、$K$、保留数 $N'$ 三者若分散在预处理、视觉塔、调度器三处各自计算，任何一处改动都会造成契约漂移，而漂移的表现形式往往是批利用率下降而非报错。把压缩后长度作为唯一权威字段向下游传递，是这份清单里成本最低、收益最确定的一项。</p>\n\n<h3 id=\"ap-token-compress-terms-sec-27\">二十七 · 压缩链路上的三类失效与回滚判据</h3>\n<p>视觉 token 压缩的坑几乎都不在压缩算子本身，而在压缩算子与下游调度、位置语义的耦合处。第一类失效是参数化压缩的容量错配：Q-Former 与感知器重采样把输出长度钉死为 $K$，这个 $K$ 是权重的一部分，不随输入分辨率伸缩。工程上必须把 $K$ 与视觉塔输出的 token 数 $N$ 一起当作容量预算来审：当 $N/K$ 超过某个倍数，cross-attention 的 softmax 在大量 key 上摊薄，小目标与文字笔画这类高频信息首先被平均掉。判断阈值不必精确，但要有可观测代理——在固定校准集上分别测小目标召回与 OCR 字符准确率，若二者相对未压缩基线出现同向下降，而整体 VQA 分数几乎不动，就是过度压缩的典型指纹，此时应回滚到合并/池化路径或提高 $K$ 并重训 query，而不是调 LLM 侧 prompt。</p>\n<p>第二类失效是剪枝后的索引错位。token 剪枝保留的是原网格中的离散子集，位置编码与注意力掩码必须按保留索引重排，否则保留 token 携带的仍是旧网格坐标，跨模态注意力在空间 grounding 上产生系统性偏移——模型能答对“有没有”，却答错“在哪里”。检查顺序应固定为：先验剪枝输出的索引单调性与唯一性，再验重排后的位置编码与视觉塔原始网格的映射表，最后用一组带框标注的 grounding 样本做偏移量回归。代价上，剪枝虽把 prefill 长度降到 $N'$、KV cache 按 $N'/N$ 比例削减，但批内长度方差被放大：同一批里高分辨率图保留 token 多、低分辨率图保留少，连续批处理的分块策略被迫按最长序列对齐，GPU 利用率被最短序列拖低，吞吐收益可能被方差吃掉。</p>\n<div class=\"formula\">$$\\text{有效吞吐} \\approx \\frac{B}{\\max_i N'_i}\\cdot\\frac{1}{t_{\\text{prefill}}(N'_{\\max})},\\quad \\text{显存} \\propto \\sum_i N'_i$$</div>\n<p>第三类失效是合并率与批调度的脱钩。合并/池化把长度压到 $\\lceil N/r\\rceil$，若 $r$ 按单图设定而不与批内分辨率分布联动，不同分辨率图像压缩后长度差异过大，分块与 padding 浪费显存带宽。回滚方案应分级：一级回滚只改调度侧，把压缩后长度分桶、按桶组批，不动模型；二级回滚把 $r$ 或 $K$ 退回上一档并在校准集上复测保真度；三级回滚整体切回未压缩路径，仅保留 KV cache 量化等正交优化。触发条件写成表更利于值班执行。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>定位</th><th>回滚动作</th></tr></thead><tbody><tr><td>小目标/OCR 同向下降</td><td>$N/K$ 过大</td><td>提高 $K$ 或切合并路径</td></tr><tr><td>grounding 系统性偏移</td><td>位置编码未重排</td><td>修索引映射后复测</td></tr><tr><td>GPU 利用率被拖低</td><td>批内长度方差</td><td>按压缩后长度分桶组批</td></tr></tbody></table>\n<h3 id=\"ap-token-compress-terms-sec-28\">二十八 · 上游依赖：压缩策略被视觉塔与预处理钉死</h3>\n<p>视觉 token 压缩不是可以独立选型的模块，它的可选空间由上游两件事决定：视觉编码器输出的 token 网格形态，以及预处理工具链给出的分辨率与切图方式。编码器若采用固定 patch 尺寸的 ViT，输出就是规则网格 $H_p \\times W_p$，token 合并与池化可以直接在网格邻域上定义；若编码器带窗口注意力或可变分辨率（NaViT 类打包输入），网格边界随样本变化，合并配对就必须携带每样本的网格元数据，否则跨样本邻域会被错误配对。预处理侧的切图（tiling）策略同样直接改写压缩的输入：一张高分辨率图被切成 $T$ 个 tile 后，压缩面对的是 $T$ 倍长度的 token 序列，此时池化窗口若仍按单图设定，等效压缩率就被稀释为原来的 $1/T$。</p>\n<p>工程上的判断是：压缩率 $r$ 与固定 query 数 $K$ 必须作为预处理配置的函数来标定，而不是全局常量。设预处理输出 token 数为 $N_{\\text{pre}}$，压缩后长度为 $L$，则下游 LLM 的 prefill 计算量近似正比于</p>\n<div class=\"formula\">$$C_{\\text{prefill}} \\approx \\alpha \\cdot L^2 + \\beta \\cdot L \\cdot d_{\\text{LLM}}$$</div>\n<p>其中二次项来自注意力、线性项来自投影与 MLP。这个式子说明压缩的收益不是线性的：$L$ 减半，注意力部分降到四分之一。因此上游任何让 $N_{\\text{pre}}$ 翻倍的动作（提高分辨率、增加 tile 数、视频抽帧变密），都必须同步重算 $r$ 或 $K$，否则压缩环节名义上还在工作，实际已被上游稀释。具体例子：OCR 场景把输入从单图改为 4-tile 切图，$N_{\\text{pre}}$ 变为约 4 倍，若 $K$ 不变，等效压缩率升到 4 倍以上，小字信息在 cross-attention 抽取阶段被抹平——这正是把固定 $K$ 当作可伸缩变量时的典型失效路径。</p>\n<p>上游还决定了压缩的显存代价归属。视觉塔的激活峰值出现在编码阶段，与压缩无关；压缩本身引入的额外显存主要是配对/打分所需的中间缓冲。token 合并若用相似度配对，需要一次 $N \\times N$ 或分块的相似度计算，其带宽代价与 $N^2$ 同阶，在长视频序列上会成为视觉塔内的新峰值。这一点与视觉塔显存溢出条目共享同一片显存预算，压缩模块不能假设自己免费。</p>\n\n<h3 id=\"ap-token-compress-terms-sec-29\">二十九 · 下游影响：压缩形态决定 LLM 侧的批处理与 KV 布局</h3>\n<p>压缩输出的不是长度，而是长度分布。合并与池化给出确定性的 $\\lceil N/r \\rceil$，同一批内不同分辨率样本的长度差异被压缩率线性缩放；Q-Former 与感知器重采样把长度钉死为 $K$，批内长度方差趋近于零；token 剪枝保留 $N'$ 个不连续 token，长度随内容变化，批内方差最大。这三种分布在 LLM 侧的代价完全不同。</p>\n<p>固定 $K$ 方案让 KV cache 与分辨率解耦，显存估算可以写成与输入无关的常数项，连续批处理的分块（chunking）策略也最稳定；代价是信息瓶颈固定，高分辨率输入的边际信息无法进入 LLM。剪枝方案在保留 token 上保真度高，但批内长度方差大，连续批处理按最长序列预留的 KV 空间会被短序列浪费，GPU 利用率被最短序列拖低——这与多模态批饥饿条目描述的现象同源，只是触发点从请求到达率换成了序列长度离散度。合并/池化居中：长度可预测，但压缩率与分辨率耦合，批内长短样本的绝对长度差仍随分辨率放大。</p>\n<p>KV cache 的削减量可按长度比例直接估算：设原始长度 $N$、压缩后 $L$，每 token 每层 KV 字节数为 $2 \\cdot d_{\\text{kv}} \\cdot b$（$b$ 为每元素字节数），则单样本 KV 节省为</p>\n<div class=\"formula\">$$\\Delta M_{\\text{KV}} = (N - L) \\cdot L_{\\text{layers}} \\cdot 2 \\cdot d_{\\text{kv}} \\cdot b$$</div>\n<p>这个线性关系只在长度维度成立，前提是压缩不改变 KV 的头数与维度。剪枝若同时改变位置索引的连续性，还会影响分页 KV 管理中的块对齐：不连续保留位置使位置编码重排成为必须步骤，否则跨模态注意力出现系统性空间偏移。具体例子：一批混合 448×448 与 1024×1024 输入的请求，若用合并率 $r=4$，两者压缩后长度比仍为分辨率比；调度器若按固定块大小分配 KV 页，长样本会跨更多页，短样本尾部页浪费，页利用率下降直接体现为可并发批大小的下降。</p>\n\n<h3 id=\"ap-token-compress-terms-sec-30\">三十 · 与量化配方的耦合：压缩改变数值精度的作用面</h3>\n<p>压缩与多模态量化配方在同一段数据通路上前后相邻，耦合点有两个。其一是压缩发生在视觉塔输出之后、LLM prefill 之前，这段张量的数值精度选择会改变压缩算子的可实现形式：相似度配对需要可比的距离度量，低精度下 top-k 配对的排序稳定性下降，合并结果的保真度损失从高频细节扩散到中频；池化是平均或最大，对精度更宽容。其二是压缩后的长度直接决定 LLM 侧 KV cache 的量化收益规模——KV 量化的节省是按字节比例算的，长度越短，绝对节省越小，但单位 token 的量化误差对注意力的影响被放大，因为每个保留 token 承载的信息更多。</p>\n<p>工程判断：Q-Former 类压缩的 cross-attention 抽取层应保持在较高精度（FP8 起步需评估），因为 $K$ 个 query 是全部下游信息的唯一入口，量化误差在此处不可恢复；而合并/池化的平均操作可以在 BF16 甚至更低精度下执行，误差被平均本身平滑。这与 NVFP4/FP8 的块缩放机制配合时要注意：合并后的 token 若来自不同缩放块，求平均会跨块混算，需先把配对 token 归一到同一缩放因子再合并，否则块级缩放引入的偏置会累积。</p>\n<p>代价侧：压缩把 LLM prefill 的 token 数降下来，直接减少的是 prefill 阶段的算力与 KV 写入带宽；量化减少的是每 token 的字节数与 MMA 的输入位宽。两者叠加时，瓶颈会从算力转向调度与页管理——这正是压缩形态（长度方差）比压缩率更重要的原因。</p>\n\n<h3 id=\"ap-token-compress-terms-sec-31\">三十一 · 与分离式预填、投机解码的接口</h3>\n<p>分离式预填把 prefill 与 decode 拆到不同资源池，压缩位于 prefill 池的入口。压缩后的长度 $L$ 决定 prefill 池的单请求算力占用与 KV 传输量：prefill 节点算完后要把 KV 传给 decode 节点，传输字节正比于 $L$，因此压缩率直接换算成 NVLink/NIXL 上的传输节省。固定 $K$ 方案在这里最友好，因为传输量是常数，可以按连接带宽做容量规划；剪枝方案的不规则长度使传输量随请求波动，NIXL 的批量传输需要按实际长度打包，规划难度上升。</p>\n<p>与投机解码的接口在 decode 侧：压缩不改变 decode 的每步 token 数，但改变了 KV 的绝对规模，从而改变 draft 模型与目标模型之间 KV 复用的可行性。若压缩把 KV 压到很小，draft 模型可以承担更长的草稿序列而显存不溢出；若压缩形态导致批内长度方差大，投机解码的验证批（verify batch）会因长短不一而降低接受率的统计效率。具体例子：视频抽帧场景下每帧 token 经池化压缩后长度固定，投机解码的验证批形状稳定，接受率估计方差小；换成剪枝且帧内容差异大时，验证批内序列长度参差，接受率的批级估计被长短样本混合稀释。</p>\n\n<h3 id=\"ap-token-compress-terms-sec-32\">三十二 · 在全书中的位置：压缩是分辨率预算的执行器</h3>\n<p>把这条目放回全书结构，它的位置是“分辨率预算”的执行端。上游的视觉编码器术语表与图像视频预处理工具链决定预算的输入端（多少 token 进入），多模态批调度与分离式预填决定预算的消费端（多少 token 被调度与传输），而视觉 token 压缩是中间那个把输入预算换算成 LLM 可承受长度的换算器。它不产生新信息，只做取舍：合并/池化保留空间邻接，Q-Former 类保留语义、丢弃坐标，剪枝保留高显著性 token、放弃规则性。</p>\n<p>因此选型不该问“哪种压缩率最高”，而该问“下游任务的保真度需求落在哪个维度”。稠密定位与 OCR 需要空间邻接与精细坐标，合并/池化与高保留率剪枝是候选，固定 $K$ 方案在此是错误默认值；语义检索与图文匹配只需语义摘要，Q-Former 类固定 $K$ 最省且显存可预测；视频理解面对的是帧间冗余，压缩应作用在时间轴与空间轴两个方向，且必须与抽帧配方联动，否则抽帧已降采样、压缩再降一次，等效分辨率跌破任务下限。</p>\n<p>工程上的落地顺序是：先由预处理与编码器确定 $N_{\\text{pre}}$ 的分布，再由任务保真度需求选定压缩族，最后由批调度与分离式预填的容量规划反推 $r$ 或 $K$ 的取值区间。三步中任何一步单独优化都会把代价推给下一步——这正是压缩条目必须与其他条目共享同一批读者的原因：它不是孤立算子，而是分辨率预算链条上的换算节点，其输出形态（长度与方差）比其压缩率更能决定整条推理链路的吞吐与稳定性。</p>\n\n<h3 id=\"ap-token-compress-terms-sec-33\">三十三 · 压缩方案的上游依赖与下游耦合：从视觉塔输出契约到连续批处理分块</h3>\n<p>本条目界定的六类压缩并非孤立算子，它们各自对上游视觉编码器提出不同的输出契约，并向下游 LLM prefill 与调度器传递不同的长度分布。合并与池化只要求视觉塔输出规则的 patch 网格与邻接索引，因此可与任意 ViT 主干搭配，代价是压缩后网格分辨率下降、高频细节被平均掉；Q-Former 与感知器重采样要求视觉塔提供完整的 token 序列供 cross-attention 读取，并额外引入 $K$ 个 query 的参数与一次注意力量算，其输出长度与输入分辨率解耦，使显存规划可以脱离图像尺寸独立进行；空间下采样在 patch 嵌入层之前就改变有效 patch 尺寸，属于编码器侧的改动而非后处理；token 剪枝则要求上游暴露逐 token 的重要性分数（注意力权重或 norm），并把不规则索引一路传到位置编码与掩码构造。下游影响集中在两处：prefill 长度决定 KV cache 占用与首 token 延迟，长度分布决定连续批处理能否稳定分块。</p>\n<div class=\"formula\">$$L_{\\text{prefill}} = \\begin{cases} \\lceil N/r\\rceil &amp; \\text{合并、池化} \\\\ K &amp; \\text{Q-Former、感知器重采样} \\\\ N' &amp; \\text{剪枝} \\end{cases} \\qquad M_{\\text{KV}} \\propto L_{\\text{prefill}} \\cdot d_{\\text{layer}} \\cdot b_{\\text{bytes}}$$</div>\n<p>边界与失效条件需要按方案分别标注。固定 $K$ 的方案最危险的误用是把 $K$ 当成随分辨率伸缩的变量：输入分辨率升高时视觉 token 数 $N$ 增长，而 $K$ 不变，压缩比 $N/K$ 随之恶化，信息被过度挤压，小目标检测与 OCR 类任务的准确率骤降——这类任务恰恰依赖精细坐标而非语义摘要，属于 Q-Former 类压缩的结构性盲区。剪枝的失效点在于索引一致性：保留 token 的位置索引若仍指向原网格，跨模态注意力就会错位，空间 grounding 出现系统性偏移，因此必须同步重排位置编码并重建注意力掩码，这一步的工程量常被低估。合并率与批内长度未联动则是调度层的失效：同一批内不同分辨率图像压缩后长度差异过大，连续批处理的分块策略失效，GPU 利用率被最短序列拖低，长序列样本反而成为显存瓶颈。</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>上游契约</th><th>长度形态</th><th>主要系统代价</th></tr></thead><tbody><tr><td>合并/池化</td><td>规则网格与邻接索引</td><td>$\\lceil N/r\\rceil$，批内可预测</td><td>高频细节损失，稠密定位退化</td></tr><tr><td>Q-Former/重采样</td><td>完整 token 序列 + $K$ 个 query</td><td>固定 $K$，与分辨率解耦</td><td>额外 cross-attention 算力，高分辨率下过度压缩</td></tr><tr><td>空间下采样</td><td>patch 嵌入层可改</td><td>网格级缩减</td><td>编码器改动，有效感受野变化</td></tr><tr><td>token 剪枝</td><td>逐 token 重要性分数</td><td>$N'$，批内方差大</td><td>索引重排开销，分块策略失效</td></tr></tbody></table>\n<p>在全书结构中，本条目处在视觉前端与 LLM 服务层的接缝上：向上它约束视觉编码器的输出形态与是否可改 patch 嵌入，向下它把长度分布交给 KV cache 估算、连续批处理分块与 SLO 容量规划三条线。工程判断的落点是——稠密定位与 OCR 场景优先选保留空间邻接的合并/池化并控制合并率，语义检索类场景可用固定 $K$ 换取显存与分辨率解耦，剪枝只在能保证索引一致性与批内长度上界时启用；任何方案在接入调度器前都应先量化批内长度方差，否则压缩带来的显存收益会被分块失效抵消。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-token-compress-terms\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>界定token合并、池化、Q-Former压缩、感知器重采样、空间下采样与token剪枝的差异，并标注各自对视…</td></tr><tr><td>关键点</td><td>见正文</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-token-compress-terms · 共 5 个片段</p>\n"},{"id":"ap-cross-attn-terms","title":"跨模态注意力术语","summary":"说明单向cross-attention、融合层位置、视觉前缀拼接、门控融合与KV注入等形态，明确其在Blackwell上对KV cache布局、注意力掩码与批内异构序列的处理要求。","kind":"术语","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-1\">一 · 条目边界：跨模态注意力在推理栈中的位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-2\">二 · 分类维度一：方向性——单向与双向的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-3\">三 · 分类维度二：融合层位置——早期与深层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-4\">四 · 分类维度三：写入方式——前缀拼接、门控融合与 KV 注入</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-5\">五 · 与相邻概念的判别：三个易混点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-6\">六 · 分类维度四：批内异构序列的处理要求</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-7\">七 · 速查表的分层口径：形态、布局、掩码三轴</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-8\">八 · 速查表主体：字段、阈值、口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-9\">九 · 阈值行的工程含义：什么必须硬性、什么可以定性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-10\">十 · 失败模式到表项的映射：三行配置错误对应三种症状</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-11\">十一 · 与批调度和显存规划的接口口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-12\">十二 · 表项冻结与版本口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-13\">十三 · 速查表：跨模态注意力的边界条件与系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-14\">十四 · 阈值从哪来：先定测量口径再定数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-15\">十五 · 掩码正确性的经验判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-16\">十六 · KV 注入的槽位与屏蔽阈值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-17\">十七 · 门控融合的开销测量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-18\">十八 · 融合层位置的延迟归因</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-19\">十九 · 把阈值落成可重放的测量脚本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-20\">二十 · 阈值从哪里来：掩码、槽位与分页的三条验收线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-21\">二十一 · 掩码形态与注意力退化的隐蔽性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-22\">二十二 · KV 注入的无效槽与噪声输出</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-23\">二十三 · 深层融合的独立视觉 KV 池与碎片化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-24\">二十四 · 踩坑清单与检查顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-25\">二十五 · 回滚方案与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-26\">二十六 · 跨模态注意力的失效边界与回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-27\">二十七 · 上游依赖：视觉塔与投影器决定 KV 的物理形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-28\">二十八 · 下游影响：批调度与分离式预填被迫感知视觉槽</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-29\">二十九 · 门控融合：不改变布局，但改变数值路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-30\">三十 · 在全书中的位置：连接算子层与调度层的中间术语</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-cross-attn-terms-sec-31\">三十一 · 跨模态注意力的边界条件与全书坐标</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-cross-attn-terms\"><svg style=\"max-width:494px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 494.0 319\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"412.0\" height=\"83.0\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"53.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"57.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：跨模态注意力术语</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">说明单向cross-attention、融合层位置、视觉前缀拼接、门控</text><text x=\"75.0\" y=\"78.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">融合与K…</text><line x1=\"82.0\" y1=\"97.0\" x2=\"82.0\" y2=\"114.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 113.0 L 86.5 113.0 L 82.0 121.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"121.0\" width=\"412.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"143.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"147.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"148.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><line x1=\"82.0\" y1=\"167.9\" x2=\"82.0\" y2=\"184.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 183.9 L 86.5 183.9 L 82.0 191.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"191.9\" width=\"412.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"214.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"218.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"219.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"238.7\" x2=\"82.0\" y2=\"255.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 254.8 L 86.5 254.8 L 82.0 262.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"262.8\" width=\"412.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"285.2\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"289.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"290.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-cross-attn-terms-sec-1\">一 · 条目边界：跨模态注意力在推理栈中的位置</h3>\n<p>“跨模态注意力”在本卷中不是一个模型结构名词，而是一个<strong>推理期数据流契约</strong>：它规定视觉侧产出的 key/value 以何种形态、在哪个时刻、进入语言侧注意力的哪一层、占用哪块显存。判断一个实现是否属于本条目，看三条：视觉 token 是否作为独立的 K/V 张量存在（而非被投影成文本 embedding 混入隐藏状态）；语言侧 query 是否显式读取该张量；该张量在解码步之间是否被复用而非重算。三条全满足才是本条目讨论的对象；只满足第一条的是视觉编码器术语表的内容，只满足第三条的是视觉 token 压缩术语的范畴。</p>\n<p>由此可划出与相邻概念的硬边界。与<strong>视觉前缀拼接</strong>的区别在于张量是否同构：前缀拼接把视觉 token 变成语言序列的一段，此后不存在“视觉 K/V”这一独立对象，注意力退化为普通因果自注意力，属于序列布局问题而非跨模态注意力问题。与<strong>视觉塔显存溢出</strong>的区别在于责任归属：后者是视觉编码阶段激活与中间张量的峰值管理，跨模态注意力讨论的是编码完成之后、写入语言侧 KV 结构的那一段。与<strong>多模态批调度</strong>的区别在于时间尺度：批调度决定哪些请求同批、何时抢占，跨模态注意力决定同批之后这些请求的视觉 K/V 如何在物理上共存。</p>\n<p>代价上，这条边界直接决定显存账本的口径。前缀拼接形态下，视觉 token 计入序列长度，KV cache 需求按 $L_v+L_t$ 线性增长；独立视觉 K/V 形态下，视觉部分是一块<strong>只读、跨解码步不变</strong>的池子，其容量按批内最大视觉长度预分配，与文本 KV 的增长曲线解耦。前者在长视觉、短文本的请求上浪费文本侧的分页灵活性，后者则要求分配器同时管理两种生命周期的页。工程判断的落点：若你的负载以短视觉、长文本为主，前缀拼接的账本更简单；若视觉长度方差大且解码步数多，独立池的复用收益才成立。</p>\n\n<h3 id=\"ap-cross-attn-terms-sec-2\">二 · 分类维度一：方向性——单向与双向的取舍</h3>\n<p>本卷默认形态是<strong>单向 cross-attention</strong>：语言侧 query 只 attend 视觉侧 key/value，视觉 token 不反向读取文本。这不是能力限制而是推理经济性选择——视觉 K/V 由视觉塔输出经 projector 投影后<strong>一次性写入</strong>，在整个解码过程中保持不变，因此无需为视觉侧维护任何随解码增长的缓存，也无需在每步重算视觉表示。反向读取会让视觉表示依赖已生成的文本前缀，视觉 K/V 就必须每步失效重算，把一次投影变成 $N_{\\text{decode}}$ 次。</p>\n<p>形式化地，设第 $l$ 层语言隐藏状态为 $H^l$，视觉投影输出为 $K_v,V_v\\in\\mathbb{R}^{L_v\\times d}$，则单向形态下该层输出为</p>\n<div class=\"formula\">$$H^{l+1}=\\text{SelfAttn}(H^l)+\\text{CrossAttn}\\big(Q{=}H^lW_Q,\\;K{=}K_v,\\;V{=}V_v\\big)$$</div>\n<p>其中 $K_v,V_v$ 与 $l$ 无关（若为深层融合则每层各有一份投影，但同样不随解码步变化）。这一“与步数无关”的性质是单向形态全部收益的来源，也是其全部约束的来源：任何需要视觉表示随文本演化的能力，单向形态都给不了。</p>\n<p>系统代价体现在掩码与批内异构上。单向形态下视觉 K/V 对同批所有请求都是全可见的，因此视觉段的掩码是一个<strong>全 1 块</strong>，只有文本段保留因果结构；批内不同请求的视觉长度不同，掩码必须按请求拼接而非按批张成矩形。一个具体例子：同批三个请求视觉长度分别为 256、1024、64，若按最大长度 1024 张成矩形掩码而不屏蔽无效槽，短请求会 attend 到属于其他请求或未初始化的视觉槽，输出出现与图像无关的噪声——这与 KV 注入方案中“无效槽参与打分”是同一类错误，只是发生在前缀形态。吞吐上，单向形态让视觉 K/V 可跨请求共享（同一图像被多次引用时），代价是共享池的引用计数与淘汰策略必须与文本 KV 的分页器协同。</p>\n\n<h3 id=\"ap-cross-attn-terms-sec-3\">三 · 分类维度二：融合层位置——早期与深层</h3>\n<p>第二个维度是视觉信息进入语言栈的<strong>深度</strong>。早期融合把视觉 token 作为前缀拼进语言序列，由自注意力统一处理，视觉与文本在同一注意力算子内交互，KV 布局与文本同构。深层融合在若干语言层插入 cross-attention 子层，视觉信息按层注入，每层需要独立的视觉 K/V 投影，因此<strong>需独立维护视觉 KV 池</strong>——池的层数是插入层数，不是语言层总数。</p>\n<p>两者的推理代价曲线形状不同。早期融合的 prefill 计算量随视觉长度线性增长，因为视觉 token 参与每一层的自注意力，其 Q/K/V 投影与注意力打分都按 $L_v$ 计入；深层融合的视觉侧计算集中在插入层的 cross-attention 上，视觉 token 不参与其余层的自注意力，prefill 的注意力项从 $O((L_v+L_t)^2)$ 降为 $O(L_t^2+L_tL_v)$ 量级，但代价是每层一份视觉投影的显存与一次额外的算子启动。</p>\n<p>显存布局的差异更关键。早期融合只有一套 KV cache，分页器无需区分来源；深层融合有两套生命周期不同的结构：文本 KV 随解码增长、按页分配，视觉 KV 池按层预分配、只读、跨步不变。批内异构序列在深层融合下要求视觉池<strong>按最大视觉长度对齐或用分页表映射</strong>，否则短序列的请求会占着按最大长度分配的槽位。失败模式很具体：独立视觉 KV 池未随批内序列动态分页时，异构批次下显存碎片化，长视觉序列请求频繁触发重分配与同步等待，表现为解码步间出现周期性停顿而非稳定的 token 间隔。工程判断：视觉长度方差小于 2 倍时按最大长度对齐更省心；方差大时必须上分页表，否则碎片化成本会吃掉深层融合省下的注意力计算。</p>\n\n<h3 id=\"ap-cross-attn-terms-sec-4\">四 · 分类维度三：写入方式——前缀拼接、门控融合与 KV 注入</h3>\n<p>第三个维度是视觉 K/V <strong>以何种方式落到语言侧</strong>，它决定掩码形态与批内异构的友好程度。视觉前缀拼接把投影后的视觉 token 直接置于文本 token 之前，序列长度等于视觉长度加文本长度，注意力掩码为<strong>因果掩码加前缀全可见块</strong>。该形态对批内异构序列最友好——不同长度的请求只是序列长度不同，分页器按普通变长序列处理即可——但 prefill 计算量随视觉长度线性增长，且视觉段与文本段共享同一套 KV 页，长视觉请求会挤占同批短请求的页预算。</p>\n<p>门控融合在 cross-attention 输出上乘一个由文本状态计算的标量或向量门 $g$：</p>\n<div class=\"formula\">$$\\text{out}=g\\odot\\text{Attn}(Q,K_v,V_v),\\quad g=\\sigma\\big(W_g\\,h_t\\big)$$</div>\n<p>其作用是抑制无关视觉 token——当文本状态表明当前解码步不需要视觉信息时，$g$ 趋近于零，cross-attention 输出被压掉。门控参数只增加少量逐元素计算，<strong>不改变 KV cache 布局</strong>，因此它是三种写入方式中对分页器最透明的一种；代价是每步一次额外的门计算与一次逐元素乘，在解码步延迟中占比很小，但在极短序列、极高并发下会成为不可忽略的逐元素开销，且门控无法解决无效槽问题——它抑制的是数值贡献，不是掩码错误。</p>\n<p>KV 注入把视觉 KV 直接写入语言模型 KV cache 的<strong>指定槽位</strong>，解码时无需重复投影。这是三种方式中显存效率最高、掩码要求最严的一种：在 Blackwell 上要求 KV cache 按层预分配视觉槽与文本槽，批内异构序列需按最大视觉长度对齐或用分页表映射，掩码需显式屏蔽无效视觉槽。它的收益在于视觉投影只发生一次且直接落在最终位置，省去前缀形态下视觉 token 参与自注意力各层投影的开销；代价是把“视觉长度对齐”的责任从序列布局转移到了分配器，一旦屏蔽逻辑漏掉一个槽，错误直接表现为输出噪声而非性能下降——后者容易被监控发现，前者不会。</p>\n<table class=\"mini\"><thead><tr><th>写入方式</th><th>KV 布局</th><th>掩码要求</th><th>批内异构友好度</th><th>主要代价</th></tr></thead><tbody><tr><td>视觉前缀拼接</td><td>与文本同构，单套 KV</td><td>因果掩码 + 前缀全可见块</td><td>高</td><td>prefill 随视觉长度线性增长</td></tr><tr><td>门控融合</td><td>不改变布局</td><td>沿用底层 cross-attention 掩码</td><td>取决于底层形态</td><td>每步逐元素门计算</td></tr><tr><td>KV 注入</td><td>按层预分配视觉槽与文本槽</td><td>显式屏蔽无效视觉槽</td><td>低，需对齐或分页映射</td><td>分配器复杂度与碎片化</td></tr></tbody></table>\n\n<h3 id=\"ap-cross-attn-terms-sec-5\">五 · 与相邻概念的判别：三个易混点</h3>\n<p>第一，<strong>跨模态注意力与视觉 token 压缩</strong>。压缩改变的是 $L_v$ 的数值，跨模态注意力改变的是这 $L_v$ 个 token 以何种结构被读取。压缩后的视觉 token 仍要走同一条写入路径；把压缩率当成跨模态注意力的调参旋钮是范畴错误——压缩降低的是前缀拼接的线性 prefill 成本与视觉池容量，但不改变掩码形态与批内异构的处理要求。判别方法：若改动只让 $L_v$ 变小而 KV 布局与掩码不变，那是压缩；若改动让视觉 K/V 从序列中独立出来成为只读池，那才是本条目。</p>\n<p>第二，<strong>跨模态注意力与多模态分离式预填</strong>。后者是执行编排：把视觉编码与语言 prefill 放到不同资源池、不同时刻。跨模态注意力是数据契约：无论预填是否分离，视觉 K/V 的写入方式、掩码、池布局都要定义。分离式预填会把视觉 K/V 的<strong>生产者与消费者在时间上拆开</strong>，于是跨模态注意力的一个隐含要求浮现：视觉 K/V 必须能被序列化、跨进程传输、并在消费者侧按原布局重建，这直接影响 KV 注入方案中槽位编号的稳定性——若槽位编号依赖本地分配顺序，跨进程重建就会错位。</p>\n<p>第三，<strong>跨模态注意力与视觉塔显存溢出</strong>。后者发生在编码阶段，是激活峰值问题；前者发生在编码完成之后。二者的耦合点在于：视觉塔溢出时常见的缓解手段是分块编码再拼接，这会改变视觉 token 的产出顺序与数量，若跨模态注意力侧按固定 $L_v$ 预分配了视觉槽，分块拼接后的实际长度与预分配不符，就落进“无效槽未屏蔽”的失败模式。判别方法：看显存峰值出现在视觉塔前向还是解码步——前者归视觉塔显存溢出，后者归本条目的池布局。</p>\n<p>三个易混点共享一个工程判断：跨模态注意力的所有失败模式最终都表现为<strong>掩码或槽位与真实长度不一致</strong>，而不是算力不足。因此上线前的检查项应落在“视觉段掩码是否为全可见块”“无效槽是否显式屏蔽”“视觉池是否随批动态分页”这三条上，而非视觉塔的吞吐指标。</p>\n\n<h3 id=\"ap-cross-attn-terms-sec-6\">六 · 分类维度四：批内异构序列的处理要求</h3>\n<p>第四个维度不是形态分类而是<strong>约束分类</strong>：不同形态对批内异构序列的容忍度不同，这一维度决定分配器与掩码生成器的设计。前缀拼接形态下，异构只体现为序列长度不同，分页器按变长序列处理，掩码生成器按请求拼接因果块与前缀全可见块即可；其代价是 prefill 计算量随批内最大视觉长度线性增长，短视觉请求被迫与长视觉请求同步等待同一批的 prefill 完成。</p>\n<p>KV 注入形态下，异构的代价转移到分配与屏蔽两处。分配侧要求按层预分配视觉槽与文本槽，批内异构序列需按最大视觉长度对齐或用分页表映射；屏蔽侧要求掩码显式屏蔽无效视觉槽。二者必须同时成立：只对齐不屏蔽，短序列的无效槽参与打分；只屏蔽不对齐，分页表映射正确但物理页仍按最大长度占用，碎片化照旧。深层融合形态下还要叠加一层：独立视觉 KV 池未随批内序列动态分页时，异构批次下显存碎片化，长视觉序列请求频繁触发重分配与同步等待。</p>\n<p>量化这一约束的代价，可用视觉池的<strong>有效利用率</strong>刻画：设批内请求视觉长度为 $L_v^{(i)}$，池按 $L_v^{\\max}$ 预分配，则利用率为</p>\n<div class=\"formula\">$$\\eta=\\frac{\\sum_i L_v^{(i)}}{B\\cdot L_v^{\\max}}$$</div>\n<p>$\\eta$ 越低，按最大长度对齐的浪费越大，越应改用分页表映射。一个具体例子：批内四个请求视觉长度 64、128、256、1024，按最大长度对齐时 $\\eta\\approx0.36$，即近三分之二的视觉池容量被无效槽占据；此时若不屏蔽，无效槽参与注意力打分直接产生噪声，若屏蔽但不对齐，噪声消失而碎片化仍在。工程判断：$\\eta$ 低于某个由分页器开销决定的阈值时，分页表映射的元数据成本低于对齐浪费，应切换；高于阈值时对齐更简单且掩码生成更快。这一判断与批调度侧的抢占策略耦合——被抢占的请求若持有按最大长度分配的视觉槽，重调度时槽位需重新映射，跨模态注意力的槽位编号稳定性因此成为批调度正确性的前置条件。</p>\n<h3 id=\"ap-cross-attn-terms-sec-7\">七 · 速查表的分层口径：形态、布局、掩码三轴</h3>\n<p>跨模态注意力的速查表不能按“模型名”组织，而必须按三个正交轴组织，否则字段之间会互相污染。第一轴是<strong>形态</strong>：单向 cross-attention、视觉前缀拼接、深层融合、门控融合、KV 注入，这五种形态决定了视觉 KV 是否与文本 KV 同构。第二轴是<strong>KV 布局</strong>：同构（视觉 token 与文本 token 共用一套分页表）、异构（独立视觉 KV 池，按层维护）、注入式（视觉槽预分配在语言 KV cache 内）。第三轴是<strong>掩码口径</strong>：因果掩码加前缀全可见块、显式无效槽屏蔽、层内 cross-attention 掩码。三轴组合出速查表的主键，任何一行都必须同时给出这三项，缺一项就无法在 Blackwell 上落地。</p>\n<p>把三轴写成判定式：设批内第 $i$ 条序列的视觉长度为 $L^i_v$、文本长度为 $L^i_t$，若形态为前缀拼接，则有效序列长度 $L^i=L^i_v+L^i_t$，掩码矩阵为</p>\n<div class=\"formula\">$$M^i_{jk}=\\begin{cases}1 &amp; j\\ge k\\ \\text{或}\\ k\\le L^i_v\\\\ 0 &amp; \\text{否则}\\end{cases}$$</div>\n<p>即文本区保持因果，视觉前缀区对全部 query 可见。若形态为 KV 注入，则掩码需额外乘一个槽有效位 $e^i_k\\in\\{0,1\\}$，$M^i_{jk}\\leftarrow M^i_{jk}\\cdot e^i_k$，无效视觉槽在打分前被置为 $-\\infty$。这两条式子就是速查表“掩码口径”字段的取值来源，工程上直接照着填，不要临场推导。</p>\n<p>代价口径必须与轴绑定：前缀拼接的 prefill 计算量随 $L^i_v$ 线性增长，注意力打分是 $O(L^2)$ 但视觉块只贡献一次；KV 注入省掉解码期重复投影，代价是 KV cache 显存按最大视觉长度预分配，批内短序列会浪费槽位；深层融合的独立视觉池在异构批次下产生显存碎片。速查表每一行都要标注这三类代价中至少一项，否则读者无法判断该形态在目标 SLO 下是否可行。</p>\n\n<h3 id=\"ap-cross-attn-terms-sec-8\">八 · 速查表主体：字段、阈值、口径</h3>\n<p>下表是可直接照用的主表。字段列给出配置项名称，阈值列给出判定边界（定性处标注“定性”，有给定数字处直接写数字），口径列说明该字段在 Blackwell 上的测量或配置方式。表中不出现任何未经给定的事实数字。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>字段</th><th>阈值 / 取值</th><th>口径</th></tr>\n</thead>\n<tbody>\n<tr><td>形态</td><td>单向 cross-attn / 前缀拼接 / 深层融合 / 门控融合 / KV 注入</td><td>按视觉 KV 是否与文本同构判定，不按模型名判定</td></tr>\n<tr><td>视觉 KV 布局</td><td>同构 / 独立池 / 注入槽</td><td>同构走统一分页表；独立池按层预分配；注入槽在语言 KV cache 内按层预留</td></tr>\n<tr><td>前缀掩码类型</td><td>因果+前缀全可见块</td><td>视觉 token 之间必须互相可见，写成纯因果即失败模式</td></tr>\n<tr><td>无效槽屏蔽</td><td>必填，$e_k\\in\\{0,1\\}$</td><td>注入式方案按最大视觉长度预分配时，短序列必须显式屏蔽</td></tr>\n<tr><td>视觉槽对齐</td><td>按最大长度对齐 / 分页表映射</td><td>异构批次二选一；分页映射优先，避免重分配</td></tr>\n<tr><td>门控计算位置</td><td>cross-attn 输出后逐元素</td><td>$g$ 由文本状态算出，标量或向量；不改 KV 布局</td></tr>\n<tr><td>视觉 KV 生命周期</td><td>整个解码过程不变</td><td>单向形态下视觉 KV 一次写入、全程复用，不随 step 重算</td></tr>\n<tr><td>prefill 计算量</td><td>随 $L_v$ 线性增长</td><td>前缀拼接口径；深层融合按注入层数分摊</td></tr>\n<tr><td>批内异构容忍度</td><td>前缀拼接最友好；独立池最差</td><td>以显存碎片与重分配同步等待为代价指标</td></tr>\n<tr><td>视觉池分页</td><td>必须动态分页</td><td>深层融合独立池未分页即触发碎片化失败模式</td></tr>\n</tbody>\n</table>\n<p>读表方式是先定形态，再由形态锁定后三行（布局、掩码、生命周期），最后用代价行做容量判断。举例：一个请求批里同时有 $L_v$ 差异很大的图文对，若形态选前缀拼接，则布局同构、掩码为因果加前缀全可见块、异构容忍度最高，代价是 prefill 随最长 $L_v$ 线性增长；若形态选 KV 注入，则必须填“无效槽屏蔽=必填”与“视觉槽对齐=分页映射”，否则直接落入噪声输出的失败模式。</p>\n\n<h3 id=\"ap-cross-attn-terms-sec-9\">九 · 阈值行的工程含义：什么必须硬性、什么可以定性</h3>\n<p>速查表里“阈值”一列不是性能数字，而是<strong>判定边界</strong>。硬性项只有三类：掩码类型（前缀拼接必须是因果加前缀全可见块，写成纯因果即失败）、无效槽屏蔽（注入式必填）、视觉池分页（独立池必须动态分页）。这三项是布尔判定，没有中间地带，配置错就直接对应一条已知失败模式。其余项是定性排序：批内异构容忍度、prefill 计算量增长方式、显存碎片风险，这些不给绝对数字，只给相对次序，因为给定事实中没有可引用的实验阈值。</p>\n<p>门控融合是唯一“加了计算但不改布局”的形态，速查表把它单列一行：$\\text{out}=g\\odot\\text{Attn}(Q,K_v,V_v)$，$g$ 由文本状态算出，逐元素乘。它的代价口径是少量逐元素计算，不进入 KV cache 布局判定，也不改变掩码。工程判断上，门控适合“视觉 token 多但相关 token 少”的场景，用门抑制无关视觉 token，但不要指望它解决批内异构问题——异构问题归布局轴管。</p>\n<p>单向 cross-attention 的生命周期行是整张表里最容易被忽略的：视觉 KV 由视觉塔输出经 projector 投影后<strong>一次性写入</strong>，整个解码过程保持不变。这意味着解码期没有视觉侧的重投影开销，代价全部压在 prefill 与显存占用上。速查表据此把“视觉 KV 生命周期”设为固定值“全程不变”，任何需要每 step 重算视觉 KV 的实现都不符合该形态，应改判为其他形态。</p>\n\n<h3 id=\"ap-cross-attn-terms-sec-10\">十 · 失败模式到表项的映射：三行配置错误对应三种症状</h3>\n<p>速查表的价值在于把症状反查到表项。第一种症状是跨模态注意力退化为仅首 token 可见：根因是前缀拼接时把前缀掩码写成因果掩码，视觉 token 之间互相不可见。反查表项为“前缀掩码类型”行，修复动作是把视觉前缀块改为全可见。第二种症状是输出出现与图像无关的噪声：根因是 KV 注入方案按最大视觉长度预分配槽位、短序列未屏蔽无效槽，无效槽参与注意力打分。反查表项为“无效槽屏蔽”行，修复是把 $e_k$ 置零并在打分前置 $-\\infty$。第三种症状是长视觉序列请求频繁触发重分配与同步等待：根因是深层融合的独立视觉 KV 池未随批内序列动态分页，异构批次下显存碎片化。反查表项为“视觉池分页”行，修复是改为动态分页表映射。</p>\n<p>三种症状对应三种代价：第一种是融合效果下降（质量代价），第二种是噪声输出（正确性代价），第三种是重分配与同步等待（延迟代价）。速查表在代价列不做定量，只标注代价类型，因为给定事实只支持定性描述。工程上把这三条作为上线前的强制检查项：掩码类型、无效槽屏蔽、视觉池分页，三项任一不满足即阻断发布，其余项作为调优项。</p>\n<p>举例说明反查流程：某批内序列视觉长度参差，观测到解码延迟尖刺且显存占用抖动，按症状三反查到“视觉池分页”与“视觉槽对齐”两行，判定形态为深层融合且独立池未分页；修复为分页映射后，重分配与同步等待消失。整个过程不需要重跑实验，只靠表项与症状的对应关系定位。</p>\n\n<h3 id=\"ap-cross-attn-terms-sec-11\">十一 · 与批调度和显存规划的接口口径</h3>\n<p>速查表不是孤立文档，它要和批调度、显存规划两张表对接。对接口径有三条：第一，形态决定批内异构序列的处理方式——前缀拼接对异构最友好，因为序列长度等于视觉长度加文本长度、布局同构，调度器只需按总长度排序；KV 注入与深层融合则要求调度器感知视觉槽占用，按最大视觉长度对齐或走分页表映射。第二，视觉 KV 生命周期决定显存回收时机——单向形态下视觉 KV 全程不变，回收只能发生在请求结束，不能在解码中途释放；独立池则要按层跟踪分页表，避免碎片。第三，门控不进入调度接口，它只影响单序列内的逐元素计算，调度器无需感知。</p>\n<p>显存规划侧的口径是：注入式方案按层预分配视觉槽与文本槽，槽位数按批内最大视觉长度乘以并发数估算，短序列浪费的槽位用 $e_k$ 屏蔽但不释放；独立池方案按分页表动态映射，碎片风险由分页粒度控制。速查表把这两条写成“视觉槽对齐”与“视觉池分页”两行，调度与显存两张表直接引用这两行的取值，不另立口径，避免同一概念在不同文档里出现两套说法。</p>\n<p>代价上，注入式的预分配会抬高常驻显存，独立池的分页会抬高管理开销与同步等待风险，前缀拼接则把代价推到 prefill 计算量。三者在速查表里各有对应行，容量规划时按行取代价类型，不跨行混用。举例：高并发短视觉序列场景选前缀拼接，prefill 线性增长可被批处理摊薄；长视觉序列、低并发场景选注入式，预分配浪费可接受，换取解码期零重投影。</p>\n\n<h3 id=\"ap-cross-attn-terms-sec-12\">十二 · 表项冻结与版本口径</h3>\n<p>速查表一旦冻结，字段名与取值域不得随模型迭代随意改动，否则下游的调度表与显存表会失配。冻结口径是：形态五项、布局三项、掩码两项、门控一行、生命周期一行、代价三行，共固定字段；新增形态必须同时给出布局、掩码、代价三轴取值，缺一不入表。版本口径上，表只记录“当前形态集合”，不记录历史形态的废弃过程，历史差异由其他部分承担。工程判断落在最后一行：任何跨模态注意力配置在进入容量规划前，必须先在三轴上填满速查表，三轴缺项即视为未定义行为，不允许上线。</p>\n\n<h3 id=\"ap-cross-attn-terms-sec-13\">十三 · 速查表：跨模态注意力的边界条件与系统代价</h3>\n<p>这张表按“形态—字段—阈值口径—失效条件”四列组织，供直接对照实现。字段指必须显式建模的配置项；阈值口径指判定该形态是否可用的量化依据；失效条件指越过即退化的具体机制。</p>\n<table class=\"mini\"><thead><tr><th>形态</th><th>关键字段</th><th>阈值口径</th><th>失效条件</th></tr></thead><tbody><tr><td>视觉前缀拼接</td><td>prefix_len、掩码块类型、批内最大序列长度</td><td>prefill 计算量随视觉长度线性增长，序列长度 = 视觉长度 + 文本长度</td><td>前缀掩码误写为因果掩码，视觉 token 互不可见，跨模态注意力退化为仅首 token 可见</td></tr><tr><td>深层融合</td><td>注入层索引集合、独立视觉 KV 池、分页粒度</td><td>视觉 KV 池容量需覆盖批内最大视觉长度，否则触发重分配</td><td>独立视觉 KV 池未随批内序列动态分页，异构批次显存碎片化，长视觉请求频繁重分配与同步等待</td></tr><tr><td>KV 注入</td><td>视觉槽位区间、文本槽位区间、无效槽屏蔽位</td><td>按层预分配视觉槽与文本槽，批内异构序列按最大视觉长度对齐或分页表映射</td><td>视觉槽按最大长度预分配而实际序列较短，未屏蔽的无效槽参与打分，输出出现与图像无关的噪声</td></tr><tr><td>门控融合</td><td>门向量维度、门计算所依赖的文本状态</td><td>门控仅增加少量逐元素计算，不改变 KV cache 布局</td><td>门退化为常量时抑制失效，视觉 token 权重不受文本状态调制</td></tr></tbody></table>\n<p>门控融合的代价可以写成逐元素乘加的形式：<div class=\"formula\">$$\\text{out}=g\\odot\\text{Attn}(Q,K_v,V_v),\\quad g=f(h_t)$$</div>其中 $h_t$ 为当前文本状态。它的系统代价落在计算而非显存：门向量与注意力输出同形，每层每 token 增加一次逐元素乘，带宽开销与输出张量同量级，但 KV cache 布局与纯 cross-attention 完全一致，因此不引入额外的分页或槽位管理。判断门控是否值得启用，口径是视觉 token 中无关比例——当无关视觉 token 占多数时门控收益明显，否则逐元素计算成为纯开销。</p>\n<p>KV 注入的边界最硬：视觉 KV 由视觉塔经 projector 一次性写入后在整个解码过程中保持不变，这既是它省去重复投影的来源，也是它失效的根源。预分配按最大视觉长度对齐时，实际短序列留下的无效槽必须在掩码中显式屏蔽；屏蔽位一旦遗漏，无效槽参与 softmax 打分，输出被与图像无关的噪声污染。分页表映射可以缓解对齐浪费，但要求分页粒度与批内异构序列的视觉长度分布匹配，粒度过粗则碎片化，过细则页表查询与同步等待上升。</p>\n<p>视觉前缀拼接对批内异构序列最友好，KV 布局与文本同构，代价集中在 prefill：计算量随视觉长度线性增长，长视觉序列请求会拉高首 token 延迟。深层融合则相反，视觉信息按层注入、需独立维护视觉 KV 池，异构批次下池容量与分页策略直接决定显存碎片程度。工程判断是：批内视觉长度方差大时选前缀拼接，层间注入收益明确且视觉长度稳定时选深层融合，KV 注入只在视觉 KV 复用次数足够高、且掩码屏蔽位可被静态验证时启用。</p>\n<h3 id=\"ap-cross-attn-terms-sec-14\">十四 · 阈值从哪来：先定测量口径再定数</h3>\n<p>跨模态注意力的工程阈值没有“通用正确值”，只有“在给定口径下可复现的判据”。口径包含三件事：测什么、在哪一层测、批形态是什么。测什么决定指标——视觉前缀拼接看的是 prefill 阶段每 token 的注意力计算量与显存占用，深层融合看的是每层 cross-attention 子层的 KV 池驻留量与重分配频率，KV 注入看的是视觉槽位利用率与无效槽屏蔽开销。在哪一层测决定采样点——注意力掩码的正确性要在融合层入口处验证，KV 布局的正确性要在 cache 分配器出口处验证，端到端收益要在解码步的 token 间隔上验证。批形态决定阈值能否迁移——单请求短视觉序列下测出的显存余量，在异构长视觉批里会被最大视觉长度对齐直接吃掉。</p>\n<p>因此本部分的经验数字一律标注口径。没有标注口径的数字不可用于容量规划。工程上建议把口径固化成一条可重放的测量脚本：固定随机种子、固定图像分辨率与抽帧数、固定批内序列长度分布，只改一个变量。这样得到的阈值才是可比的。</p>\n<div class=\"formula\">$$\\text{有效视觉槽利用率}=\\frac{\\sum_{i\\in\\text{batch}} L^{\\text{vis}}_i}{B\\cdot L^{\\text{vis}}_{\\max}}$$</div>\n<p>该比值直接决定 KV 注入方案是否值得启用：当批内视觉长度差异大时，按最大长度预分配会让利用率显著下降，未被屏蔽的无效槽还会参与打分。测量方法是：在分配器出口记录每个请求的实际视觉长度与分配槽数，按上式聚合，同时统计掩码屏蔽位的比例。若利用率低且屏蔽开销占比高，说明应改用分页表映射而非定长对齐。</p>\n\n<h3 id=\"ap-cross-attn-terms-sec-15\">十五 · 掩码正确性的经验判据</h3>\n<p>视觉前缀拼接最常见的失败是把前缀掩码写成因果掩码，导致视觉 token 之间互相不可见，跨模态注意力退化为仅首 token 可见。这个问题不会报错，只会让融合效果下降，因此必须有可测的判据。经验判据有三条：其一，前缀块内注意力权重矩阵应近似满秩而非下三角；其二，文本首 token 对视觉前缀的注意力分布应覆盖多个视觉位置而非集中在位置 0；其三，遮蔽视觉前缀后输出应有可测的差异。</p>\n<p>测量方法：在融合层取出注意力权重，对前缀块做行归一化后计算行熵。因果掩码下前缀块的行熵随位置单调下降，全可见块下行熵应保持在较高水平且不随位置单调衰减。这是一个不依赖标注数据的结构性检查，适合放进上线前清单的自动化项。代价方面，该检查只需在 prefill 阶段采样若干层若干头，额外开销可忽略；但若在解码每步都做，会引入同步点，破坏连续批处理的流水。</p>\n<p>第二条判据的测量更直接：取文本首 token 的注意力向量，统计其在前缀长度上的有效支撑数（权重超过均值的位点数）。若支撑数接近 1，几乎可以断定掩码写错。第三条判据用消融：把视觉前缀替换为等长占位 token，比较输出分布的 KL 散度，散度接近零说明视觉信息未被读取。</p>\n\n<h3 id=\"ap-cross-attn-terms-sec-16\">十六 · KV 注入的槽位与屏蔽阈值</h3>\n<p>KV 注入把视觉 KV 直接写入语言模型 KV cache 的指定槽位，解码时无需重复投影。在 Blackwell 上要求 KV cache 按层预分配视觉槽与文本槽，批内异构序列需按最大视觉长度对齐或用分页表映射，掩码需显式屏蔽无效视觉槽。这里的工程阈值围绕两个量：视觉槽占比与屏蔽位占比。</p>\n<p>视觉槽占比定义为视觉槽数除以该层 KV cache 总槽数。占比过高会挤压文本槽，导致可并发序列数下降；占比过低则说明预分配不足，长视觉请求会触发重分配。测量方法：在每层 cache 分配后记录视觉槽与文本槽的占用，按批统计占比分布，取 P95 作为容量规划输入。屏蔽位占比定义为无效视觉槽位数除以视觉槽总数，它直接反映对齐浪费。经验判据是：屏蔽位占比持续高于某一水平时，定长对齐不再经济，应切换分页表映射。</p>\n<div class=\"formula\">$$\\text{重分配代价}\\approx N_{\\text{realloc}}\\cdot\\left(t_{\\text{sync}}+t_{\\text{copy}}\\right)$$</div>\n<p>深层融合的独立视觉 KV 池若未随批内序列动态分页，异构批次下显存碎片化，长视觉序列请求频繁触发重分配与同步等待。测量方法是：在分配器中埋点统计单位时间内的重分配次数与每次的同步等待时长，把上式作为延迟预算的一项。若该项在解码步间隔中占比不可忽略，说明分页粒度太粗或池预留策略过于保守。</p>\n<p>具体例子：一个批内同时存在短视觉前缀请求与长视频请求，按最大视觉长度对齐后，短请求的视觉槽大量闲置且需逐位屏蔽。此时若掩码遗漏，无效槽参与注意力打分，输出出现与图像无关的噪声。可测信号是：屏蔽位未置位时，文本 token 对视觉槽的注意力权重在无效区间出现非零质量；修复后该质量归零。这个检查应作为 KV 注入方案的回归测试项。</p>\n\n<h3 id=\"ap-cross-attn-terms-sec-17\">十七 · 门控融合的开销测量</h3>\n<p>门控融合在 cross-attention 输出上乘一个由文本状态计算的标量或向量门，$\\text{out}=g\\odot\\text{Attn}(Q,K_v,V_v)$，用于抑制无关视觉 token。门控参数增加少量逐元素计算，不改变 KV cache 布局。因此它的工程阈值不在显存，而在逐元素计算的吞吐占比与门值的分布稳定性。</p>\n<p>测量方法：在融合层分别记录注意力主体耗时与门计算加逐元素乘的耗时，取比值。由于门不改变 KV 布局，它不会引入额外的 cache 分配或掩码复杂度，这是它相对 KV 注入的结构性优势。代价评估应聚焦于：门向量维度是否与注意力输出对齐、门计算是否引入了跨头同步、以及门值是否在解码过程中剧烈波动导致输出不稳。</p>\n<p>门值分布稳定性的测量：按解码步记录门向量的均值与方差，若方差随步数单调上升，说明门在追逐噪声而非抑制无关 token。经验判据是门值应集中在抑制与放行两端而非均匀分布；均匀分布意味着门未学到有效区分。这一检查不需要标注，只需统计分布形状。</p>\n\n<h3 id=\"ap-cross-attn-terms-sec-18\">十八 · 融合层位置的延迟归因</h3>\n<p>早期融合把视觉 token 作为前缀拼进语言序列、由自注意力统一处理，KV 布局与文本同构；深层融合在若干语言层插入 cross-attention 子层，视觉信息按层注入，需独立维护视觉 KV 池。两者的阈值测量口径不同：前者看 prefill 计算量随视觉长度的线性增长，后者看每层注入带来的额外延迟与池管理开销。</p>\n<p>早期融合的测量：固定文本长度，扫描视觉长度，记录 prefill 阶段耗时。由于序列长度等于视觉长度加文本长度，prefill 计算量随视觉长度线性增长，这是该形态对批内异构序列最友好但 prefill 成本最高的根源。工程判据是：当视觉长度占比超过某一水平时，prefill 成为端到端延迟主项，此时应评估分离式预填或视觉 token 压缩。测量时必须区分注意力计算与投影计算，否则归因错误。</p>\n<p>深层融合的测量：按层记录 cross-attention 子层耗时与视觉 KV 池的驻留量，统计池的分配/释放频率。独立视觉 KV 池的碎片化不会体现在单请求延迟上，只会体现在异构批的尾部延迟上。因此测量必须在混合批形态下进行，单请求基准会系统性低估问题。具体例子：一个批内长短视觉序列混排，独立池未动态分页，长序列请求触发重分配并同步等待，尾部延迟抬升；可测信号是重分配次数与同步等待时长在批级统计中的分布。</p>\n\n<h3 id=\"ap-cross-attn-terms-sec-19\">十九 · 把阈值落成可重放的测量脚本</h3>\n<p>上述所有判据要落地，需要一条统一的测量脚本骨架：固定输入分布、固定批形态、逐层埋点、输出结构化记录。伪代码思路如下：对每个融合层，记录掩码类型、前缀块行熵、视觉槽占比、屏蔽位占比、门值分布、子层耗时；对每个批，记录重分配次数与同步等待；对端到端，记录 prefill 与解码步间隔。所有记录带口径标签，禁止跨口径比较。</p>\n<p>工程判断落在取舍上：掩码正确性检查是低成本高收益项，应无条件纳入回归；视觉槽利用率与屏蔽位占比决定 KV 注入是否经济，需在目标批形态下测；门值分布稳定性决定门控融合是否值得保留；融合层位置的延迟归因决定是否需要分离式预填。没有在目标批形态下测过的数字，不进入容量规划。测量脚本本身应版本化，与模型版本、框架版本、Blackwell 驱动版本绑定，否则阈值不可复现。</p>\n\n<h3 id=\"ap-cross-attn-terms-sec-20\">二十 · 阈值从哪里来：掩码、槽位与分页的三条验收线</h3>\n<p>跨模态注意力的工程阈值不是调参玄学，而是由掩码正确性、槽位利用率与分页粒度三条线共同卡出来的。第一条线是前缀掩码的验收：视觉前缀拼接要求掩码为“因果掩码 + 前缀全可见块”，一旦误写成纯因果掩码，视觉 token 之间互相不可见，跨模态注意力退化为仅首 token 可见。测量方法很直接——构造一个视觉 token 数远超文本 token 的样本，对比正确掩码与错误掩码下首层 cross-attention 的注意力熵；若熵塌缩到接近单点分布，说明前缀块被因果化。系统代价体现在 prefill：该形态对批内异构序列最友好，但 prefill 计算量随视觉长度线性增长，视觉长度翻倍即 prefill FLOPs 翻倍，长视觉请求会成为批内拖尾者。</p>\n<p>第二条线是 KV 注入的槽位有效率。视觉槽按批内最大视觉长度预分配，实际序列较短时，未屏蔽的无效槽会参与注意力打分，输出出现与图像无关的噪声。设批内最大视觉长度为 <span class=\"inline-formula\">$L_v^{\\max}$</span>、某请求实际长度为 <span class=\"inline-formula\">$L_v$</span>，则无效槽比例 <span class=\"inline-formula\">$\\rho = 1 - L_v / L_v^{\\max}$</span>；工程上应把 <span class=\"inline-formula\">$\\rho$</span> 作为调度器的准入指标，超过阈值即拒绝合批或改用分页表映射。测量手段是逐层统计被掩码屏蔽的视觉槽占全部视觉槽的比例，并对照输出 token 与图像内容的相关性做定性回归。代价是显存：无效槽仍占 KV cache 容量，<span class=\"inline-formula\">$\\rho$</span> 高时显存带宽被无意义的打分读取吃掉。</p>\n<p>第三条线是深层融合独立视觉 KV 池的分页粒度。该形态需独立维护视觉 KV 池，若池不随批内序列动态分页，异构批次下显存碎片化，长视觉序列请求频繁触发重分配与同步等待。可测的量是单位时间内的重分配次数与同步等待时长占比；把分页块大小设为视觉塔输出 token 数的整数分之一，可让碎片率与重分配频率同时下降。门控融合则不同：<span class=\"inline-formula\">$\\text{out}=g\\odot\\text{Attn}(Q,K_v,V_v)$</span>，门控参数只增加少量逐元素计算，不改变 KV cache 布局，因此它的失效条件不在显存而在数值——门 <span class=\"inline-formula\">$g$</span> 若在低精度下饱和到 0 或 1，抑制无关视觉 token 的能力即丧失，需在门计算处保留足够精度。</p>\n<table class=\"mini\"><thead><tr><th>形态</th><th>关键阈值对象</th><th>测量方法</th><th>系统代价</th></tr></thead><tbody><tr><td>视觉前缀拼接</td><td>前缀掩码正确性</td><td>首层注意力熵对比</td><td>prefill 随视觉长度线性增长</td></tr><tr><td>KV 注入</td><td>无效槽比例 ρ</td><td>逐层屏蔽槽占比统计</td><td>显存容量与带宽浪费</td></tr><tr><td>深层融合</td><td>分页块大小</td><td>重分配次数与同步等待占比</td><td>显存碎片化、同步停顿</td></tr></tbody></table>\n<h3 id=\"ap-cross-attn-terms-sec-21\">二十一 · 掩码形态与注意力退化的隐蔽性</h3>\n<p>视觉前缀拼接的掩码必须写成“因果掩码 + 前缀全可见块”，而不是把整条序列统一套用因果掩码。后者在数值上不会报错，也不会触发断言，但视觉 token 之间彼此不可见，语言侧对视觉的读取被压缩到前缀首 token 这一条窄路径上，跨模态注意力实质退化。这类失败在 loss 曲线上看不出来，在离线评测里也可能只表现为“融合收益不明显”，工程上极易被误判为投影层没训好。</p>\n<p>检查手段是直接对注意力打分做结构探针：取一个固定样本，导出某一语言层对视觉槽位的注意力权重矩阵，验证视觉块内部是否呈现块内全连接、语言块对视觉块是否全列可见。伪代码思路为：对 mask 张量按 <span>q_idx</span> 与 <span>kv_idx</span> 分块，断言视觉区段 <span>mask[v_i, v_j] == True</span> 对所有 <span>i, j</span> 成立，语言区段对视觉区段全为 <span>True</span>，语言区段自身保持下三角。这一步应在模型加载后一次性执行，作为上线前的静态校验。</p>\n<p>代价体现在两个方向：错误掩码让 prefill 的有效计算被浪费，视觉长度越长浪费越大，因为前缀块内注意力被屏蔽后仍需走完 MMA 流水；而正确掩码下 prefill 计算量随视觉长度线性增长，这是前缀拼接形态的固有成本，不能靠掩码优化掉。举例：一个视觉长度远大于文本长度的请求，在错误掩码下视觉块内注意力全部无效，却仍占用 tcgen05 的 MMA 周期与 TMEM 带宽，等于用满算力换回接近零的跨模态信息。</p>\n\n<h3 id=\"ap-cross-attn-terms-sec-22\">二十二 · KV 注入的无效槽与噪声输出</h3>\n<p>KV 注入把视觉 KV 一次性写入语言模型 KV cache 的指定槽位，解码时不再重复投影。问题出在槽位分配策略：按批内最大视觉长度预分配视觉槽，实际序列较短时，尾部槽位没有内容却仍参与注意力打分。若掩码未显式屏蔽这些无效槽，softmax 会在这些位置上分配概率质量，输出出现与图像无关的噪声，且噪声随无效槽数量增长而增强。</p>\n<p>形式上，设有效视觉槽数为 <span>n_v</span>、预分配槽数为 <span>N_v</span>，无效槽集合为 <span>I</span>，则注意力输出为</p>\n<div class=\"formula\">$$\\text{out}=\\sum_{j\\notin I}\\text{softmax}\\Big(\\frac{q\\cdot k_j}{\\sqrt{d}}\\Big)v_j+\\sum_{j\\in I}\\text{softmax}\\Big(\\frac{q\\cdot k_j}{\\sqrt{d}}\\Big)v_j$$</div>\n<p>第二项即污染项。工程上必须保证 <span>j∈I</span> 的打分被置为负无穷，或在写入时把无效槽的 key 置零、value 置零并配合掩码双保险。检查顺序上，先验证掩码是否覆盖无效槽，再验证写入路径是否在序列结束时正确截断槽位计数，最后用固定图像加固定 prompt 做贪心解码复现，比较屏蔽前后 logits 差异。</p>\n<p>代价是显存与带宽：按最大长度预分配意味着 KV cache 的视觉区段按批内最长请求占用，短请求造成显存浪费；Blackwell 上 KV cache 按层预分配视觉槽与文本槽，浪费按层累加。若改用分页表映射，则需承担页表查询与地址转换的额外开销，且分页粒度影响碎片率。举例：一个批内混有长视觉与短视觉请求，短请求的无效槽若未屏蔽，其解码输出在无关 token 上出现高概率，表现为复读或跑题。</p>\n\n<h3 id=\"ap-cross-attn-terms-sec-23\">二十三 · 深层融合的独立视觉 KV 池与碎片化</h3>\n<p>深层融合在若干语言层插入 cross-attention 子层，视觉信息按层注入，需独立维护视觉 KV 池，与文本 KV 布局不同构。坑在于该池未随批内序列动态分页：异构批次下，长短视觉序列混合，池按请求整块分配，释放时机不一致，显存碎片化累积，长视觉序列请求频繁触发重分配与同步等待，表现为解码阶段的周期性停顿。</p>\n<p>检查顺序建议为：先看视觉 KV 池的分配粒度是否与分页表一致，再看批内序列进出时池的回收是否走异步路径，最后看长视觉请求的首次解码延迟分布是否出现尖峰。伪代码思路：为每个序列维护 <span>(layer_id, slot_start, slot_len)</span> 三元组，池分配以页为单位，页表映射到物理槽；序列结束时只归还页，不搬移数据，避免同步拷贝。</p>\n<p>代价集中在显存与同步：独立池意味着视觉 KV 与文本 KV 不能共享同一块预分配区域，显存占用按层叠加；重分配触发的同步等待直接抬高解码尾延迟。门控融合在此不改变 KV cache 布局，只增加少量逐元素计算，因此门控本身不是碎片来源，但门控若依赖跨层文本状态，会引入额外的层间依赖，放大同步点。举例：批内同时存在长视频请求与短图像请求，长请求的视觉池页在解码中途被挤压，触发重分配，短请求的解码步被同步阻塞。</p>\n\n<h3 id=\"ap-cross-attn-terms-sec-24\">二十四 · 踩坑清单与检查顺序</h3>\n<p>把上述失败模式收敛为一张按顺序执行的清单，避免在错误方向上反复调参。检查顺序遵循“静态结构 → 掩码语义 → 槽位生命周期 → 批内异构 → 回滚”的链路，前一步不通过不进入下一步。</p>\n<table class=\"mini\"><thead><tr><th>序</th><th>检查项</th><th>判定信号</th><th>代价维度</th></tr></thead><tbody>\n<tr><td>1</td><td>融合形态与 KV 布局是否匹配</td><td>前缀拼接却维护独立视觉池，或深层融合却复用文本池</td><td>显存</td></tr>\n<tr><td>2</td><td>前缀掩码是否为块内全可见</td><td>视觉块内注意力权重为零</td><td>prefill 算力</td></tr>\n<tr><td>3</td><td>无效视觉槽是否被屏蔽</td><td>屏蔽前后 logits 差异显著</td><td>输出质量</td></tr>\n<tr><td>4</td><td>视觉池是否按页动态分配</td><td>解码延迟出现周期性尖峰</td><td>尾延迟、同步</td></tr>\n<tr><td>5</td><td>批内异构序列是否按最大长度对齐或分页映射</td><td>短请求占用长槽位</td><td>显存、吞吐</td></tr>\n<tr><td>6</td><td>门控是否引入额外层间同步</td><td>逐元素计算之外的等待</td><td>解码步延迟</td></tr>\n</tbody></table>\n<p>每一项都应绑定一个可复现的固定样本，而不是依赖整体评测分数。第 2、3 项属于语义正确性，必须在任何性能调优之前通过；第 4、5 项属于资源管理，影响的是吞吐与尾延迟，可在正确性通过后单独压测。</p>\n\n<h3 id=\"ap-cross-attn-terms-sec-25\">二十五 · 回滚方案与工程判断</h3>\n<p>回滚不是简单切回旧权重，而是按失败模式分层回退。掩码类失败回滚到“前缀全可见块 + 因果”的已验证掩码实现，并保留结构探针作为回归测试；无效槽类失败回滚到“按实际长度截断槽位计数 + 显式屏蔽”的保守路径，牺牲部分预分配效率换取输出确定性；碎片化类失败回滚到整块预分配加最大长度对齐，放弃动态分页的显存收益，换取解码延迟的平稳。</p>\n<p>回滚的触发条件应量化为可观测信号：注意力结构探针失败、屏蔽前后 logits 差异超过设定阈值、解码尾延迟尖峰频率上升。三者任一触发即回退，不做局部修补。工程判断上，前缀拼接形态对批内异构序列最友好，但 prefill 计算量随视觉长度线性增长，若视觉长度分布长尾明显，应优先保证掩码正确而非追求槽位复用；深层融合的独立视觉池在异构批次下必须分页，否则碎片化是必然结果而非偶发。</p>\n<p>最后落在具体机制上：把视觉槽的写入、屏蔽与回收做成一个原子化的槽位生命周期管理器，写入时记录有效长度，屏蔽时按有效长度生成掩码，回收时按页归还，三步共享同一份元数据。这样掩码错误与无效槽污染在结构上不可能同时发生，回滚也只需切换元数据的生成策略，而不必改动注意力内核。</p>\n\n<h3 id=\"ap-cross-attn-terms-sec-26\">二十六 · 跨模态注意力的失效边界与回滚判据</h3>\n<p>三类形态的坑不在定义层，而在“掩码—槽位—分页”三者的一致性上。视觉前缀拼接最典型的失效是前缀掩码误写成纯因果掩码：视觉 token 之间互相不可见，语言侧 query 实际只能看到视觉前缀的首 token，跨模态注意力退化为单点可见，融合效果断崖式下降。检查顺序应从掩码构造入手——先验证前缀块是否为全可见块、文本段是否严格因果，再核对位置编码是否把视觉段与文本段连续编号。代价上，该形态 prefill 计算量随视觉长度线性增长，批内异构序列虽最友好，但长视觉请求会把整批 prefill 的 FLOPs 抬上去，短请求被迫等待，形成批级尾延迟。</p>\n<p>KV 注入的坑在“预分配但不屏蔽”。视觉槽按批内最大视觉长度预分配，实际序列较短时，未屏蔽的无效槽仍参与注意力打分，输出混入与图像无关的噪声。判据是打分前的掩码必须显式覆盖无效视觉槽，且槽位映射表要与分页表同源，避免“逻辑槽有效、物理页未写”的中间态。Blackwell 上 KV cache 按层预分配视觉槽与文本槽，异构批需按最大视觉长度对齐或用分页表映射；对齐策略省去映射开销但浪费显存，分页策略省显存但每层多一次间接寻址。用 <span class=\"formula\">$$\\;S_{\\text{kv}}=L\\cdot H_{\\text{kv}}\\cdot d_h\\cdot b_{\\text{vis}}^{\\max}\\;$$</span> 估算视觉槽占用，其中 $L$ 为层数、$H_{\\text{kv}}$ 为 KV 头数、$d_h$ 为头维、$b_{\\text{vis}}^{\\max}$ 为批内最大视觉长度；当批内视觉长度方差大时，对齐策略的显存浪费按最大长度而非均值计。</p>\n<p>深层融合的独立视觉 KV 池若未随批内序列动态分页，异构批次下显存碎片化，长视觉序列请求频繁触发重分配与同步等待。这类等待不体现在单请求延迟上，而体现在批调度器的排队时间与重分配同步点——解码步被池扩容打断，连续批处理的步进节奏被拉长。门控融合本身不改变 KV 布局，坑在门 $g$ 的计算依赖文本状态，若在 prefill 阶段用整段文本状态算门、解码阶段却用单 token 状态，门值分布漂移会让视觉 token 的抑制强度前后不一致；<span class=\"formula\">$$\\text{out}=g\\odot\\text{Attn}(Q,K_v,V_v)$$</span> 中 $g$ 的逐元素计算量小，但跨阶段一致性检查不能省。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>检查点</th><th>系统代价</th><th>回滚动作</th></tr></thead><tbody><tr><td>前缀掩码写成因果</td><td>前缀块全可见、文本段因果</td><td>融合效果退化，prefill FLOPs 线性增长</td><td>回退到深层融合或纯文本路径</td></tr><tr><td>无效视觉槽未屏蔽</td><td>打分前掩码覆盖、槽页同源</td><td>输出噪声，显存按最大长度浪费</td><td>切回分页映射，关闭预对齐</td></tr><tr><td>视觉 KV 池不分页</td><td>池扩容同步点、碎片率</td><td>解码步被打断，批排队拉长</td><td>冻结池上限，拒绝超长视觉请求</td></tr></tbody></table>\n<p>回滚方案要按“影响面从小到大”排序：先关预对齐、切分页映射，再降级融合层位置（深层融合回退为前缀拼接），最后整体切回纯文本路径并丢弃视觉 KV。判据是重分配同步点是否落在解码关键路径上——若池扩容触发的同步等待已进入步进节奏，说明分页粒度与批内视觉长度分布不匹配，此时继续调掩码无意义，应直接冻结池上限并对超长视觉请求做准入拒绝，把不确定性挡在调度层而非注意力核内。</p>\n<h3 id=\"ap-cross-attn-terms-sec-27\">二十七 · 上游依赖：视觉塔与投影器决定 KV 的物理形态</h3>\n<p>跨模态注意力的形态不是自选的，它被上游两个组件锁死：视觉塔输出什么形状的 token 序列，投影器把它映射到什么维度与什么精度。单向 cross-attention 的 K/V 由视觉塔输出经 projector 一次性写入，此后整个解码过程不变——这条性质把“视觉 KV 何时产生、产生多少、存在哪”全部推给了上游。视觉塔若采用高分辨率切块加位置编码重采样，输出 token 数随图像分辨率近似二次增长；projector 若是 MLP 或 Q-Former 类结构，还会引入额外的 token 压缩比。二者共同决定视觉 KV 的条目数 $N_v$ 与每条目字节数：</p>\n<div class=\"formula\">$$M_{\\text{vkv}} = L_{\\text{fuse}} \\times N_v \\times 2 \\times d_{\\text{kv}} \\times b_{\\text{elem}}$$</div>\n<p>其中 $L_{\\text{fuse}}$ 是注入视觉信息的层数（前缀拼接形态下等于全部语言层，深层融合形态下等于插入 cross-attention 子层的层数），因子 2 是 K 与 V 两份，$b_{\\text{elem}}$ 是 KV 元素字节数（FP8 为 1，BF16 为 2）。这个式子说明：深层融合虽然每层注入的视觉信息更“精准”，但独立视觉 KV 池的容量随 $L_{\\text{fuse}}$ 线性膨胀；前缀拼接把视觉 token 变成普通文本 token，KV 布局与文本同构，却让 prefill 计算量随视觉长度线性增长。上游视觉 token 压缩条目若把 $N_v$ 压到原来的几分之一，跨模态注意力的显存代价同比例下降，但压缩引入的信息损失会直接体现在门控融合的门值分布上——门控若普遍趋近于零，说明视觉侧有效信息已被压缩器吃掉。这是本条目与视觉 token 压缩术语、视觉编码器术语表之间的硬接口：前者给 $N_v$，后者给 $d_{\\text{kv}}$ 与数值精度。</p>\n<p>工程代价落在 prefill 阶段。前缀拼接形态下，一个视觉长度 1024、文本长度 512 的请求，prefill 的注意力计算量按 $L_{\\text{seq}}^2$ 计，视觉部分贡献了约四分之三的二次项；若批内还有纯文本请求，异构序列的掩码构造必须把前缀全可见块与因果块拼在一起，掩码张量的构造开销在短请求上不可忽略。Blackwell 上 tcgen05 的 MMA 对掩码的容忍度取决于是否能在 TMEM 中直接表达块结构，前缀全可见块恰好是规则块，代价可控；深层融合的逐层注入则要求每个融合层单独一次 cross-attention 的 MMA 发射，发射次数随 $L_{\\text{fuse}}$ 增长，小 batch 下发射开销占比上升。</p>\n\n<h3 id=\"ap-cross-attn-terms-sec-28\">二十八 · 下游影响：批调度与分离式预填被迫感知视觉槽</h3>\n<p>跨模态注意力一旦选择 KV 注入形态，批调度器就不能再把请求当作等长的文本序列处理。KV cache 需按层预分配视觉槽与文本槽，批内异构序列要么按最大视觉长度对齐，要么用分页表映射。对齐策略浪费显存：批内最大视觉长度 2048、最小 256 时，短请求的视觉槽有大量空洞；分页策略把空洞转化为页表间接寻址，代价是解码每一步多一次页表查找与槽位有效性判断。掩码必须显式屏蔽无效视觉槽，否则未屏蔽的空洞参与注意力打分，输出出现与图像无关的噪声——这正是失败模式清单里那条“无效槽未屏蔽”的成因。分页表映射的伪代码思路是：</p>\n<ul>\n<li>为每层维护视觉槽基址与文本槽基址两段地址空间；</li>\n<li>请求入批时按实际 $N_v$ 分配页，页大小取与文本 KV 页一致的粒度以复用分配器；</li>\n<li>解码每步构造槽位有效性位图，作为注意力掩码的附加项传入 kernel；</li>\n<li>请求退出时视觉页整体归还，避免与文本页交叉造成碎片。</li>\n</ul>\n<p>这条链路直接影响多模态批调度术语与多模态批饥饿两个条目：调度器若按文本 token 数估算单步延迟，会低估含长视觉序列请求的 prefill 占比，导致短请求被长请求的视觉 prefill 阻塞，形成批饥饿。反过来，若调度器为规避饥饿而限制每批视觉 token 总量，长视觉请求的排队时间上升，SLO 的尾延迟恶化。分离式预填把 prefill 与 decode 拆到不同实例后，视觉 KV 必须跨实例传输：prefill 实例产出视觉 KV 后经 NIXL 写入 decode 实例的 KV cache 指定槽位，传输量正比于 $M_{\\text{vkv}}$。视觉长度大的请求在这一跳上产生带宽尖峰，NVLink 5 的链路带宽决定了单请求传输的下界，批内多个长视觉请求同时完成 prefill 时，传输排队会反压 prefill 实例的吞吐。这是跨模态注意力与多模态分离式预填配方之间的耦合点：配方里选择在哪一侧做视觉投影，等价于选择把 $M_{\\text{vkv}}$ 的传输放在哪一段链路上。</p>\n\n<h3 id=\"ap-cross-attn-terms-sec-29\">二十九 · 门控融合：不改变布局，但改变数值路径</h3>\n<p>门控融合是唯一不触碰 KV cache 布局的形态：视觉 KV 仍按上述任一方式存放，门控只在 cross-attention 输出上乘一个由文本状态计算的标量或向量 $g$，$\\text{out}=g\\odot\\text{Attn}(Q,K_v,V_v)$。它的代价是少量逐元素计算与一个额外的投影矩阵（文本状态到门值），在 Blackwell 上这部分计算可以融进 cross-attention 的 epilogue，不额外发射 kernel。但门控改变了数值路径：门值在 FP8 下量化时，接近零的门与接近一的门共享同一缩放因子，小门值的相对误差被放大，抑制无关视觉 token 的能力下降。多模态量化配方条目若对门控投影矩阵采用与主权重相同的 per-tensor 缩放，就会踩到这个坑；正确做法是门控投影走更高精度或 per-channel 缩放。门控的另一个下游效应在投机解码：草稿模型若不含视觉塔，它无法计算门值，验证阶段主模型的门值与草稿阶段的注意力分布不一致，接受率在多模态请求上下降。这要求投机解码的草稿路径要么复用主模型已算出的视觉 KV 与门值，要么在多模态请求上关闭投机。</p>\n<p>具体例子：一个图文问答请求，视觉 token 512、文本 prompt 128、生成长度 64。前缀拼接形态下 prefill 序列长 640，因果掩码加前缀全可见块；若误写成纯因果掩码，视觉 token 之间互不可见，跨模态注意力退化为仅首个视觉 token 可见，融合效果大幅下降——这是失败模式清单的第一条，其根因不在注意力算子而在掩码构造的上游代码。深层融合形态下，同一请求在 $L_{\\text{fuse}}=4$ 层插入 cross-attention，视觉 KV 池容量为 4 层乘 512 条目，若批内另有一个视觉长度 2048 的请求，独立视觉 KV 池未随批内序列动态分页，则显存碎片化，长视觉请求频繁触发重分配与同步等待，解码步的同步开销吃掉吞吐。</p>\n\n<h3 id=\"ap-cross-attn-terms-sec-30\">三十 · 在全书中的位置：连接算子层与调度层的中间术语</h3>\n<p>跨模态注意力术语在全书结构里处于中间层：向上它依赖算子与数值精度条目给出的 tcgen05 MMA 形态、TMEM 容量与 FP8/NVFP4 缩放规则；向下它把 KV 布局、掩码结构与批内异构序列的处理要求传递给批调度、分离式预填、显存与 KV cache 管理各条目。它不重复视觉编码器的结构细节，也不重复视觉 token 压缩的算法，只规定“视觉信息以什么形状、在什么时刻、以什么可见性进入语言侧注意力”。七个领域的推理形态各自对这一层提出不同约束：文档理解类请求视觉 token 多但文本短，前缀拼接的二次项代价突出；视频类请求视觉长度随时序增长，KV 注入形态的视觉槽预分配按最大长度对齐会迅速耗尽显存，必须走分页；交互式多轮对话中视觉 KV 在整个会话内不变，跨轮复用视觉槽可以省掉重复投影，但会话切换时的槽位回收策略要与调度器的请求生命周期对齐。这些约束不改变术语定义，只改变参数取值与实现路径的选择。</p>\n<p>与视觉塔显存溢出条目的关系是容量侧的：视觉塔前向的激活峰值与视觉 KV 的常驻占用是两笔账，前者发生在 prefill 的编码阶段，后者贯穿整个解码过程。跨模态注意力选择深层融合时，独立视觉 KV 池的常驻占用随 $L_{\\text{fuse}}$ 增长，可能把原本能容纳的批推过显存上限，触发视觉塔显存溢出条目里描述的重分配与抢占。与多模态上线前清单的关系是验证侧的：清单里应包含掩码构造的单元测试（前缀全可见块是否真的全可见）、无效视觉槽的屏蔽检查、以及异构批次下分页表的压力测试——这三项恰好对应本条目列出的三条失败模式。跨模态注意力不是孤立术语，它是把视觉侧产物接入语言侧解码循环的那道接口，接口的形状决定了上下游所有条目的参数边界。</p>\n\n<h3 id=\"ap-cross-attn-terms-sec-31\">三十一 · 跨模态注意力的边界条件与全书坐标</h3>\n<p>这一节只谈跨模态注意力条目自身不成立的地方。它的上游是视觉塔与 projector：视觉 KV 一次性写入后在整个解码期不变，因此任何“视觉侧也随文本更新”的设想都不在本方案范围内，需要回到视觉编码器或流式视觉条目去解决。它的下游直接压在三处：KV cache 布局、注意力掩码生成、批内异构序列调度。早期融合（视觉前缀拼接）把序列长度写成 <span class=\"formula\">$$L = L_v + L_t$$</span>，KV 与文本同构，掩码是因果掩码叠加前缀全可见块，prefill 计算量随视觉长度线性增长——这是它换取批内异构友好性的代价。深层融合则必须独立维护视觉 KV 池，门控融合 <span class=\"formula\">$$\\text{out}=g\\odot\\text{Attn}(Q,K_v,V_v)$$</span> 只增加逐元素开销、不改布局，是三者中对显存最温和的一种。</p>\n<p>失效条件集中在掩码与槽位两处。前缀拼接若把前缀块误写成因果掩码，视觉 token 之间互相不可见，跨模态注意力退化为仅首 token 可见，融合效果大幅下降，而这一错误在数值上不会报错，只能靠对齐检查发现。KV 注入把视觉 KV 写入语言 KV cache 的指定槽位，解码时无需重复投影，但在 Blackwell 上要求按层预分配视觉槽与文本槽；若按最大视觉长度预分配而实际序列较短，未屏蔽的无效槽参与打分，输出会出现与图像无关的噪声。深层融合的独立视觉 KV 池若不随批动态分页，异构批次下显存碎片化，长视觉序列请求频繁触发重分配与同步等待，直接表现为解码阶段的尾延迟抖动。</p>\n<table class=\"mini\"><thead><tr><th>形态</th><th>KV 布局</th><th>主要系统代价</th><th>典型失效</th></tr></thead><tbody><tr><td>视觉前缀拼接</td><td>与文本同构</td><td>prefill 随视觉长度线性增长</td><td>前缀掩码写成因果掩码</td></tr><tr><td>深层 cross-attention</td><td>独立视觉 KV 池</td><td>池未分页则显存碎片、重分配等待</td><td>异构批次下同步抖动</td></tr><tr><td>KV 注入</td><td>按层预分配视觉槽/文本槽</td><td>按最大长度对齐浪费显存</td><td>无效槽未屏蔽引入噪声</td></tr></tbody></table>\n<p>在全书中的位置由此确定：本条目是“视觉侧只读”这一约束的术语锚点，向上承接视觉编码与 projector 的精度选择（NVFP4/FP8 下视觉 KV 的量化误差会直接进入 cross-attention 打分），向下为 KV cache 分页、连续批处理与分离式预填/解码提供布局前提——预填阶段一次性写入视觉 KV，解码阶段只读，正是分离式部署能把视觉编码放到独立资源池的依据。工程判断上，先确定融合层位置，再决定掩码生成器与分页表是否共用同一套槽位编号；两者不一致时，上述三类失效会同时出现。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-cross-attn-terms\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>说明单向cross-attention、融合层位置、视觉前缀拼接、门控融合与KV注入等形态，明确其在Black…</td></tr><tr><td>关键点</td><td>见正文</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-cross-attn-terms · 共 5 个片段</p>\n"},{"id":"ap-mm-batch-terms","title":"多模态批调度术语","summary":"定义视觉编码批、LLM prefill批、连续批处理、分块prefill、图像分辨率分桶与SLO感知调度等概念，区分视觉塔与语言塔解耦调度时的队列与优先级语义。","kind":"术语","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-1\">一 · 条目边界：什么算“多模态批调度术语”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-2\">二 · 分类维度一：按执行阶段与计算形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-3\">三 · 分类维度二：按队列语义与优先级来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-4\">四 · 与相邻概念的区别：解耦语义是分水岭</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-5\">五 · 定义的稳定性：哪些词会随拓扑漂移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-6\">六 · 解耦双队列的边界条件与失效代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-7\">七 · 速查表的字段骨架：把批调度拆成可填的格子</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-8\">八 · 视觉队列的口径：像素预算、桶内 padding 与超时</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-9\">九 · 语言队列的口径：序列长度、分块与分页对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-10\">十 · 两队列的优先级语义对照：不可共用一套阈值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-11\">十一 · 阈值判据的落地：从字段到动作的判定链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-12\">十二 · 字段命名与配置边界：速查表直接进配置文件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-13\">十三 · 速查表：解耦双队列的字段口径与失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-14\">十四 · 像素预算：视觉批的第一道工程阈值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-15\">十五 · 分块 prefill 的块大小：与分页粒度对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-16\">十六 · 双队列的阈值：像素排序键与超时策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-17\">十七 · 视觉塔显存释放的时序阈值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-18\">十八 · 测量方法：没有数字时怎么测</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-19\">十九 · 像素预算、块对齐与超时门限：三个必须实测的阈值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-20\">二十 · 视觉队列按张数定批：像素预算失守的第一现场</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-21\">二十一 · 分块 prefill 与 KV 分页粒度错位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-22\">二十二 · SLO 感知只覆盖语言队列</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-23\">二十三 · 解耦调度的交接语义检查</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-24\">二十四 · 回滚方案与检查清单的落地顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-25\">二十五 · 解耦双队列的失效边界与回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-26\">二十六 · 上游依赖：本条目吃谁的输出</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-27\">二十七 · 下游影响：谁在消费调度决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-28\">二十八 · 与并行通信条目的耦合面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-29\">二十九 · 在全书中的位置：术语层与配方层的接缝</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-30\">三十 · 接口失配的三种典型断法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-terms-sec-31\">三十一 · 边界条件：像素预算、分页粒度与双队列超时的耦合失效</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-mm-batch-terms\"><svg style=\"max-width:484px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 483.7 319\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"401.7\" height=\"83.0\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"53.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"57.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：多模态批调度术语</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">定义视觉编码批、LLM prefill批、连续批处理、分块prefill</text><text x=\"75.0\" y=\"78.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">、图像…</text><line x1=\"82.0\" y1=\"97.0\" x2=\"82.0\" y2=\"114.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 113.0 L 86.5 113.0 L 82.0 121.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"121.0\" width=\"401.7\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"143.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"147.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"148.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><line x1=\"82.0\" y1=\"167.9\" x2=\"82.0\" y2=\"184.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 183.9 L 86.5 183.9 L 82.0 191.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"191.9\" width=\"401.7\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"214.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"218.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"219.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"238.7\" x2=\"82.0\" y2=\"255.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 254.8 L 86.5 254.8 L 82.0 262.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"262.8\" width=\"401.7\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"285.2\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"289.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"290.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-mm-batch-terms-sec-1\">一 · 条目边界：什么算“多模态批调度术语”</h3>\n<p>本卷把“多模态批调度术语”限定为一个可判定的集合：凡描述<b>视觉塔与语言塔在批维度上如何被切分、排序、拼接与释放</b>的名词，才进入条目表。判据有三条，缺一不可。其一，该术语必须指涉一个可观测的调度单元——一个视觉编码批、一个 LLM prefill 批、一个解码步内的连续批，或一次分块 prefill 的块。其二，它必须携带至少一个可配置量，例如批大小、像素预算、块大小、超时阈值、优先级序。其三，它的语义在解耦调度下会发生变化：同一个词在单体执行与分离式预填/解码两种拓扑下指的不是同一件事。</p>\n<p>按此判据，“视觉编码批”是条目，“图像张量”不是；“分块 prefill”是条目，“序列长度”不是；“SLO 感知调度”是条目，“时延预算”本身不是，因为后者是输入而非机制。这条边界把术语表与相邻的视觉编码器术语表、视觉 token 压缩术语切开：后者描述的是<b>塔内</b>的算子与张量形态，本条目描述的是<b>塔间</b>的排队与拼批决策。一个术语若只影响单塔内部的数值精度或网格切分，归入算子卷；只有当它改变队列的成员构成或出队顺序时，才归入本条目。</p>\n<p>工程上这条边界有直接代价。把塔内术语误并入调度条目，会导致配置面膨胀：一个视觉塔的窗口切分参数被当成批参数暴露给调度器，运维侧就要为它维护超时与优先级，而它根本不参与排队。反过来，把调度术语降格为塔内细节，则会出现视觉队列按图像张数定批大小的典型错误——高分辨率桶内单批显存溢出，触发重试与队列积压，尾部时延被重试放大。</p>\n\n<h3 id=\"ap-mm-batch-terms-sec-2\">二 · 分类维度一：按执行阶段与计算形态</h3>\n<p>第一个分类维度是阶段。视觉编码批只跑视觉塔，输入为预处理后的图像张量，按分辨率分桶后同桶内可拼批；它的吞吐由像素总量而非图像张数决定，因此批大小应随分辨率反比调整。LLM prefill 批则把投影后的视觉 token 与文本 token 拼成一条序列做一次前向，计算量随序列长度平方增长。解码阶段的连续批处理动态替换已完成序列、接纳新请求，是第三个阶段类别。三者的资源画像完全不同：视觉批吃的是像素吞吐与激活显存，prefill 批吃的是平方级的算力与单次激活峰值，解码批吃的是 KV cache 带宽与批内序列的碎片化程度。</p>\n<p>分块 prefill 是 prefill 类目的一个子类，它把长序列切成固定块逐步前填。设序列长度为 <i>L</i>、块大小为 <i>B</i>，则调度轮次为 ⌈<i>L</i>/<i>B</i>⌉，单次激活峰值大致按 <i>B</i> 而非 <i>L</i> 缩放，而注意力计算的有效工作量仍随 <i>L</i> 增长。用伪代码表达其调度语义：</p>\n<div class=\"formula\">$$\\text{for } k \\leftarrow 0 \\text{ to } \\lceil L/B \\rceil - 1:\\ \\text{prefill}(x[kB:(k+1)B]);\\ \\text{append\\_kv}(k)$$</div>\n<p>代价出现在两处。轮次增加意味着调度器每块都要做一次出队与资源检查，长序列请求的端到端时延里混入了更多调度开销；更关键的是块大小与 KV cache 分页粒度不匹配时，跨块写入会产生额外拷贝，长序列请求时延高于不分块的基线。这是一个纯调度侧的失败模式，与算子实现无关。具体例子：一个含大量视觉 token 的长请求，若块大小取值为分页粒度的非整数倍，每块边界都要重排页表，拷贝量随块数线性上升，分块带来的激活峰值收益被拷贝开销吃掉。</p>\n\n<h3 id=\"ap-mm-batch-terms-sec-3\">三 · 分类维度二：按队列语义与优先级来源</h3>\n<p>第二个维度是队列语义。视觉塔与语言塔解耦调度时形成两条队列，它们的排序键不同：视觉队列按像素预算与分辨率桶排序，语言队列按到达时间与剩余长度排序。这不是实现偏好，而是由两塔的资源形态决定的。视觉塔的批内成员必须共享同一分辨率桶的网格，否则 padding 会制造无效计算；语言队列的成员则可以跨长度拼批，因为注意力掩码能吸收长度差异，排序键自然落在时延与剩余工作量上。</p>\n<p>由此派生出一组必须分别配置的量：两队列的批大小、优先级与超时策略。若只配一边，结果是视觉塔空转或语言队列饥饿。图像分辨率分桶是视觉队列的前置步骤，它把长宽比与像素数相近的输入归入同一桶，桶内统一 padding 到桶最大网格以减少无效计算；分桶的粒度直接决定视觉批的拼批成功率，桶太细则批不满、视觉塔利用率下降，桶太粗则 padding 浪费像素吞吐。</p>\n<p>SLO 感知调度是优先级来源的第三个类别，它按剩余时延预算决定新请求进视觉队列还是等待合并，超预算请求优先单独成批。这里的语义要点是：SLO 判定发生在<b>入队</b>时刻而非出队时刻，因此它改变的是队列成员构成，而不是排序。代价是判定本身要读请求的剩余预算，若只对语言队列生效、视觉队列无超时策略，低优先级大图会长期占用视觉塔，尾部请求时延失控。具体例子：一批高分辨率图像在视觉队列中按像素预算排序，若无超时策略，它们会持续压制后到的小图请求，而语言队列侧的 SLO 判定对此完全无感。</p>\n<table class=\"mini\"><thead><tr><th>类别</th><th>排序键</th><th>可配置量</th><th>主要代价</th></tr></thead><tbody><tr><td>视觉编码批</td><td>像素预算、分辨率桶</td><td>批大小（随分辨率反比）、桶粒度</td><td>激活显存、padding 无效计算</td></tr><tr><td>LLM prefill 批</td><td>到达时间、序列长度</td><td>批大小、块大小</td><td>平方级算力、单次激活峰值</td></tr><tr><td>连续批处理</td><td>完成状态、剩余长度</td><td>替换策略、批上限</td><td>KV cache 带宽、碎片化</td></tr><tr><td>SLO 感知调度</td><td>剩余时延预算</td><td>超时阈值、单独成批门限</td><td>判定开销、尾部时延</td></tr></tbody></table>\n\n<h3 id=\"ap-mm-batch-terms-sec-4\">四 · 与相邻概念的区别：解耦语义是分水岭</h3>\n<p>本条目与“多模态分离式预填配方”的区别在于抽象层级：配方描述的是拓扑与部署形态，本条目描述的是该拓扑下队列的<b>名词与语义</b>。解耦调度的关键语义是视觉编码结果以 token 张量形式入语言队列，视觉批完成即释放视觉塔显存。这句话定义了两个条目的接缝：视觉批的生命周期终止于 token 张量交付，此后它的一切资源计量都归语言队列。因此“视觉编码批”与“LLM prefill 批”不是同一批的两个阶段，而是两个独立资源池上的两个独立批，中间以一次张量交接为界。</p>\n<p>与“多模态批饥饿”的区别在于，后者是一个<b>现象</b>，本条目是产生该现象的名词集合。饥饿的根因可以在条目层面定位：视觉队列按图像张数而非像素总量定批大小，会让高分辨率桶的批显存溢出并触发重试，重试又反过来拉长队列；或者两队列的批大小与超时策略未分别配置，使一侧长期空转。术语表的作用是让这类根因有名字可指，而不是在监控面板上看到一个无名的队列长度曲线。</p>\n<p>与“视觉塔显存溢出”的区别同理：溢出是结果，本条目里的批大小定义与分辨率桶粒度是可控的因。一个可操作的判断是，若某次溢出发生在同桶拼批之后，则问题在桶粒度与批大小的乘积上；若发生在跨桶拼批，则说明分桶逻辑本身被绕过。这个区分不需要读算子代码，只需要看批成员的桶标签分布。</p>\n\n<h3 id=\"ap-mm-batch-terms-sec-5\">五 · 定义的稳定性：哪些词会随拓扑漂移</h3>\n<p>并非所有条目都同等稳定。“连续批处理”在单体执行下指解码步内替换已完成序列；在解耦拓扑下它分裂为两条队列各自的连续接纳，语义从“一个批”变成“两个批的协同”，批大小与优先级必须分别配置。这类词的条目定义必须写成条件式：给出拓扑前提，再给语义。相反，“图像分辨率分桶”的语义不随拓扑漂移，它始终是视觉队列的前置分组步骤，漂移的只是桶粒度这个参数值。</p>\n<p>稳定性差异带来维护代价。条件式定义的条目在术语表中需要携带拓扑标签，检索时要先匹配拓扑再匹配词；稳定条目则可以直接作为跨拓扑的公共词汇。工程判断上，把漂移词与稳定词混排在同一张表里，会让配置模板无法复用——一个按单体拓扑写死的批大小默认值，搬到解耦拓扑上就变成视觉塔空转的直接原因。因此本卷在条目表里为每个词标注“拓扑敏感/不敏感”，这不是分类学趣味，而是配置面复用的前提。</p>\n<p>最后一个可判定的区别落在“批”这个词本身。视觉编码批的成员是图像张量，LLM prefill 批的成员是 token 序列，连续批处理的成员是解码中的序列，三者的成员类型不同，因此“批大小”这个量在三处不可通约：前者按像素总量计量，中者按序列长度计量，后者按活跃序列数计量。任何跨队列的容量规划若把这三个数直接相加，都会得到一个没有物理意义的和。这正是本条目要在定义层面把三者分开的原因。</p>\n\n<h3 id=\"ap-mm-batch-terms-sec-6\">六 · 解耦双队列的边界条件与失效代价</h3>\n<p>视觉编码批与 LLM prefill 批在解耦调度下并非两个独立优化问题，而是一对耦合的预算分配问题。视觉队列按像素预算排序、语言队列按到达时间与剩余长度排序，二者优先级语义不可通约：前者是资源约束型排序（同桶内拼批、跨桶不混），后者是时延约束型排序（先到先服务叠加长度修正）。把视觉编码结果以 token 张量形式推入语言队列、视觉批完成即释放视觉塔显存，这一语义成立的前提是视觉塔显存占用与语言队列的 KV cache 分页池物理隔离；一旦二者共享同一显存池，视觉批的峰值激活就会挤压分页空间，使语言队列在解码阶段被迫驱逐或重算。系统代价直接体现在尾部时延上：视觉塔空转意味着像素吞吐归零而功耗不降，语言队列饥饿则意味着已到达请求在队列中空耗 SLO 预算。</p>\n<p>第一类失效来自批大小语义错位。视觉编码批的吞吐由像素总量决定，批大小应随分辨率反比调整，即 <span class=\"formula\">$$B_{\\text{vis}} \\approx \\frac{P_{\\text{budget}}}{\\bar{p}_{\\text{bucket}}}$$</span>，其中 <span class=\"formula\">$$P_{\\text{budget}}$$</span> 是单批像素预算、<span class=\"formula\">$$\\bar{p}_{\\text{bucket}}$$</span> 是该桶平均像素数。若按图像张数定批，高分辨率桶内单批显存溢出，触发重试与队列积压，重试本身又占用调度轮次，形成正反馈。第二类失效来自分块 prefill 与 KV cache 分页粒度不匹配：块大小若不对齐分页边界，跨块写入产生额外拷贝，长序列请求时延反而高于不分块的基线——分块降低的是单次激活峰值，付出的是调度轮次与拷贝开销，二者在长序列上可能倒挂。</p>\n<p>第三类失效是 SLO 语义只覆盖单侧队列。SLO 感知调度按剩余时延预算决定新请求进视觉队列还是等待合并，超预算请求优先单独成批；但若该策略只对语言队列生效、视觉队列无超时策略，低优先级大图会长期占用视觉塔，尾部请求时延失控。工程判断上，两队列的批大小、优先级与超时策略必须分别配置并共享同一时延预算账本：视觉队列的超时阈值应由“该桶像素量 ÷ 视觉塔有效像素吞吐”反推，语言队列的接纳阈值则由剩余长度与分块轮次估算。下表给出三类失效的可观测信号与代价落点。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>代价落点</th></tr></thead><tbody><tr><td>按张数定视觉批</td><td>高分辨率桶显存溢出、重试率上升</td><td>视觉吞吐塌陷、队列积压</td></tr><tr><td>块大小与分页不对齐</td><td>跨块拷贝计数上升</td><td>长序列时延高于不分块基线</td></tr><tr><td>视觉队列无超时</td><td>大图驻留时长单调增长</td><td>尾部时延失控、语言队列饥饿</td></tr></tbody></table>\n<h3 id=\"ap-mm-batch-terms-sec-7\">七 · 速查表的字段骨架：把批调度拆成可填的格子</h3>\n<p>速查表的价值不在“全”，而在“照着填就能跑”。多模态批调度涉及两类批、两条队列、三种优先级语义，任何一项没落到字段上，工程上就会退化成“凭感觉调参”。本表按“批对象—字段—口径—阈值判据”四层组织：批对象区分视觉编码批与 LLM prefill 批；字段是调度器实际读写的量；口径规定该字段按什么单位计量；阈值判据给出越界后的动作。视觉编码批的批大小必须按像素总量而非图像张数定义，因此字段里必须同时存在 <code>batch_images</code> 与 <code>batch_pixels</code>，且后者是调度决策的主键。LLM prefill 批则以 <code>seq_tokens</code>（视觉 token 与文本 token 之和）为主键，因为其计算量随序列长度平方增长，按张数或按请求数定批都会失真。</p>\n<table class=\"mini\"><thead><tr><th>批对象</th><th>字段</th><th>口径</th><th>阈值判据与动作</th></tr></thead><tbody><tr><td>视觉编码批</td><td>batch_pixels</td><td>桶内所有图像像素数之和</td><td>超过桶像素预算即拆批；批大小随分辨率反比调整</td></tr><tr><td>视觉编码批</td><td>bucket_id</td><td>长宽比与像素数相近归桶，桶内 padding 到桶最大网格</td><td>跨桶不得拼批；padding 浪费率超阈值则重分桶</td></tr><tr><td>视觉编码批</td><td>vis_queue_timeout</td><td>请求在视觉队列的驻留时长</td><td>超时即单独成批或降桶，防止大图长期占用视觉塔</td></tr><tr><td>LLM prefill 批</td><td>seq_tokens</td><td>投影后视觉 token + 文本 token</td><td>按平方增长估算算力；超预算转分块 prefill</td></tr><tr><td>LLM prefill 批</td><td>chunk_size</td><td>分块 prefill 的单块 token 数</td><td>须与 KV cache 分页粒度对齐，否则跨块写入产生额外拷贝</td></tr><tr><td>解码连续批</td><td>lang_queue_order</td><td>到达时间 + 剩余长度</td><td>与视觉队列优先级语义分离配置</td></tr></tbody></table>\n<p>这张表的用法是：调度器每次组批前，先读 <code>batch_pixels</code> 与 <code>seq_tokens</code> 两个主键，再查对应阈值判据决定“拼、拆、等、转”。字段缺失的后果是可观测的——若只有 <code>batch_images</code> 而无 <code>batch_pixels</code>，高分辨率桶内单批显存溢出就会触发重试与队列积压，这正是失败模式里最典型的一条。</p>\n\n<h3 id=\"ap-mm-batch-terms-sec-8\">八 · 视觉队列的口径：像素预算、桶内 padding 与超时</h3>\n<p>视觉队列的排序键是像素预算与分辨率桶，不是到达时间。口径上要区分三个量：桶像素预算（单批允许的像素上限）、桶最大网格（桶内统一 padding 的目标尺寸）、单图有效像素（padding 前的真实像素）。桶内 padding 到桶最大网格是为了减少无效计算的分支发散，但 padding 本身是纯浪费，因此需要一个浪费率口径：</p>\n<div class=\"formula\">$$w = \\frac{\\sum_i (A_{\\text{pad},i} - A_{\\text{eff},i})}{\\sum_i A_{\\text{pad},i}}$$</div>\n<p>其中 $A_{\\text{pad},i}$ 是第 $i$ 张图 padding 后的网格面积，$A_{\\text{eff},i}$ 是有效像素面积。$w$ 越界说明分桶粒度过粗，应重分桶而不是加大批。视觉批的吞吐由像素总量决定，因此批大小应随分辨率反比调整：高分辨率桶的批像素预算固定时，单批张数自然下降，这是口径而非调参技巧。</p>\n<p>超时策略是视觉队列独立的字段。SLO 感知调度按剩余时延预算决定新请求进视觉队列还是等待合并，超预算请求优先单独成批。代价体现在两处：视觉塔空转（队列无批可拼时的算力闲置）与尾部时延（低优先级大图长期占用视觉塔）。若只对语言队列配超时、视觉队列无 <code>vis_queue_timeout</code>，尾部请求时延失控就是必然结果。工程判断是：视觉队列的超时阈值应短于语言队列，因为视觉批完成即释放视觉塔显存，早释放比晚拼批更值钱。</p>\n\n<h3 id=\"ap-mm-batch-terms-sec-9\">九 · 语言队列的口径：序列长度、分块与分页对齐</h3>\n<p>语言队列按到达时间与剩余长度排序，其批对象是 LLM prefill 批与解码连续批。prefill 批的主键是 <code>seq_tokens</code>，算力按长度平方估算；当单批 <code>seq_tokens</code> 超过激活峰值预算时，转分块 prefill。分块 prefill 把长序列切成固定块逐步前填，降低单次激活峰值但增加调度轮次——这是明确的延迟换显存交易，口径上要同时记录 <code>chunk_size</code> 与 <code>num_chunks</code>，后者直接等于新增的调度轮次。</p>\n<p>关键约束是 <code>chunk_size</code> 与 KV cache 分页粒度对齐。伪代码思路如下：</p>\n<ul><li>读分页粒度 <code>page_tokens</code>；</li><li>令 <code>chunk_size</code> 为 <code>page_tokens</code> 的整数倍；</li><li>逐块前填，每块写满整页再切下一页；</li><li>若 <code>chunk_size</code> 非整数倍，跨块写入触发额外拷贝，长序列请求时延高于不分块基线。</li></ul>\n<p>解码阶段的连续批处理动态替换已完成序列、接纳新请求，其口径是“每步接纳数”与“每步替换数”，而非批大小本身。视觉编码结果以 token 张量形式入语言队列，视觉批完成即释放视觉塔显存——这条语义决定了语言队列看到的视觉 token 是“已落地”的，因此 prefill 批的 <code>seq_tokens</code> 可以在视觉批完成前预估、完成后校正，预估偏差要作为字段记录下来供容量规划用。</p>\n\n<h3 id=\"ap-mm-batch-terms-sec-10\">十 · 两队列的优先级语义对照：不可共用一套阈值</h3>\n<p>解耦调度的核心风险是两队列共用一套批大小、优先级与超时策略。视觉队列按像素预算与分辨率桶排序，语言队列按到达时间与剩余长度排序，二者优先级语义不同：视觉队列的“高优先级”意味着小像素、早入队、可拼批；语言队列的“高优先级”意味着短剩余长度、早到达。把语言队列的到达时间排序套到视觉队列上，会让大图先入队却拼不进任何桶，视觉塔空转；把视觉队列的像素预算套到语言队列上，会让长序列请求被反复推迟，语言队列饥饿。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>视觉队列</th><th>语言队列</th></tr></thead><tbody><tr><td>排序主键</td><td>像素预算 + 分辨率桶</td><td>到达时间 + 剩余长度</td></tr><tr><td>批大小依据</td><td>像素总量，随分辨率反比</td><td>序列 token 数，按平方估算算力</td></tr><tr><td>超时动作</td><td>单独成批或降桶</td><td>转分块 prefill 或推迟接纳</td></tr><tr><td>释放时机</td><td>批完成即释放视觉塔显存</td><td>序列完成或块边界释放分页</td></tr></tbody></table>\n<p>代价口径也要分开记：视觉队列的代价是视觉塔显存占用与空转功耗；语言队列的代价是激活峰值与 KV cache 分页压力。SLO 感知调度若只对语言队列生效，视觉队列无超时策略，低优先级大图长期占用视觉塔，尾部请求时延失控——这条失败模式的根因就是优先级语义被合并。工程判断是：两队列的批大小、优先级、超时三组字段必须分别配置，配置项在速查表里各占一行，不允许“继承默认值”。</p>\n\n<h3 id=\"ap-mm-batch-terms-sec-11\">十一 · 阈值判据的落地：从字段到动作的判定链</h3>\n<p>速查表要能“照着用”，阈值判据必须写成判定链而非单点阈值。视觉侧判定链：读 <code>batch_pixels</code> → 对比桶像素预算 → 超则拆批 → 拆后仍超则降桶 → 降桶后仍超则单独成批并记超时。语言侧判定链：读 <code>seq_tokens</code> → 对比激活峰值预算 → 超则转分块 → 检查 <code>chunk_size</code> 是否为分页粒度整数倍 → 非整数倍则改块大小 → 记录新增调度轮次。两条链的终点都是“动作 + 记录字段”，记录字段是容量规划与上线前清单的输入。</p>\n<p>一个具体例子：某请求带一张高分辨率图，进视觉队列时桶内已有若干小图，<code>batch_pixels</code> 加上该图后越过桶像素预算。判定链动作是拆批——小图先成批、大图单独成批，而不是把整桶一起推迟。若视觉队列无超时字段，大图会一直等待合并，视觉塔在小图批完成后空转；若语言队列的 <code>chunk_size</code> 与分页粒度不匹配，该请求的视觉 token 入队后跨块写入产生额外拷贝，时延高于不分块基线。两个代价叠加，就是“视觉塔空转 + 语言队列饥饿”同时出现。</p>\n<p>阈值判据的另一个口径是“批完成即释放”的时序：视觉批完成释放视觉塔显存后，语言队列才拿到 token 张量，因此 <code>seq_tokens</code> 的预估必须早于视觉批完成，否则 prefill 批无法提前组批。速查表里应有一行专门记“预估偏差”，供后续校准。</p>\n\n<h3 id=\"ap-mm-batch-terms-sec-12\">十二 · 字段命名与配置边界：速查表直接进配置文件</h3>\n<p>速查表的最终形态是配置文件的行。字段命名要能直接映射到调度器读写点：<code>batch_pixels</code>、<code>bucket_id</code>、<code>vis_queue_timeout</code>、<code>seq_tokens</code>、<code>chunk_size</code>、<code>lang_queue_order</code> 六个主键，加上各自的阈值字段。配置边界有三条硬约束：视觉批大小不得以图像张数为唯一依据；<code>chunk_size</code> 必须是 KV cache 分页粒度的整数倍；两队列的超时与优先级字段不得共用默认值。违反任一条，失败模式即可复现——高分辨率桶显存溢出触发重试与积压、跨块写入额外拷贝、视觉塔被大图长期占用。</p>\n<p>速查表的使用顺序是：先填批对象与主键，再填口径，最后填阈值判据与动作。填不出的格子就是调度器缺的观测点，应在上线前补齐，而不是用经验值糊过去。像素总量与序列长度这两个主键一旦缺失，后续所有阈值都失去计量基准，批调度的“快、省、稳”就无从谈起。</p>\n\n<h3 id=\"ap-mm-batch-terms-sec-13\">十三 · 速查表：解耦双队列的字段口径与失效边界</h3>\n<p>这张表按“字段—取值口径—触发阈值—代价落点”四列组织，直接照着填配置即可。核心口径只有一条：视觉队列的批大小必须以像素总量为约束，而非图像张数；语言队列则以 token 数与剩余时延预算为约束。两队列的批大小、优先级、超时策略必须分别配置，任一侧沿用另一侧的语义，就会出现视觉塔空转或语言队列饥饿。</p>\n<table class=\"mini\"><thead><tr><th>字段</th><th>口径</th><th>阈值/触发条件</th><th>系统代价</th></tr></thead><tbody><tr><td>视觉批大小</td><td>按桶内像素总量反比于分辨率</td><td>桶内 padding 后显存逼近上限即降批</td><td>显存峰值、重试与队列积压</td></tr><tr><td>分辨率桶</td><td>长宽比与像素数相近归桶，统一 padding 到桶最大网格</td><td>桶内网格差异过大则拆桶</td><td>无效计算量、视觉塔利用率</td></tr><tr><td>prefill 块大小</td><td>与 KV cache 分页粒度对齐</td><td>块边界跨页即产生额外拷贝</td><td>长序列首 token 时延</td></tr><tr><td>视觉队列超时</td><td>按像素预算与桶排序，独立超时</td><td>低优先级大图占用超时即抢占</td><td>尾部请求时延</td></tr><tr><td>语言队列优先级</td><td>到达时间与剩余长度排序</td><td>剩余时延预算不足即前置</td><td>解码吞吐、SLO 达标率</td></tr></tbody></table>\n<p>失效条件集中在三处。其一，视觉队列若按图像张数定批，高分辨率桶内单批显存溢出，触发重试并反向加剧积压——此时应改用像素预算硬约束，批大小随分辨率反比收缩。其二，分块 prefill 的块大小与 KV cache 分页粒度不匹配，跨块写入产生额外拷贝，长序列请求时延反而高于不分块基线；块大小应取分页粒度的整数倍，使每次写入落在同一页内。其三，SLO 感知调度只挂在语言队列上、视觉队列无超时策略时，低优先级大图长期占用视觉塔，尾部请求时延失控。视觉编码结果以 token 张量入语言队列、视觉批完成即释放视觉塔显存，这一语义决定了视觉侧的超时必须独立于语言侧。</p>\n<div class=\"formula\">$$B_{vis} \\le \\frac{M_{free} - M_{act}}{\\alpha \\cdot P_{bucket}},\\quad T_{tail} = \\max_{i}\\left(t^{enc}_i + t^{pre}_i + t^{dec}_i\\right)$$</div>\n<p>式中 $P_{bucket}$ 为桶内单图像素量，$\\alpha$ 为单位像素的激活系数，$M_{free}$ 为视觉塔可用显存；尾部时延由编码、prefill、解码三段串联决定，任一段超预算都会把整条链路拖出 SLO。工程判断上，把视觉队列的超时阈值设为语言队列剩余预算的固定比例，并在桶切换时重算批大小，是避免“视觉塔空转—语言队列饥饿”交替出现的最小改动；代价是调度轮次增加，prefill 阶段的计算量随序列长度平方增长，轮次越多单次激活峰值越低但总调度开销越高，需在块大小与分页粒度之间取平衡。</p>\n<h3 id=\"ap-mm-batch-terms-sec-14\">十四 · 像素预算：视觉批的第一道工程阈值</h3>\n<p>视觉编码批的批大小不能按“张数”配，必须按“像素预算”配。设单张图像预处理后高宽为 <span class=\"inline\">(H_i, W_i)</span>，patch 边长为 <span class=\"inline\">p</span>，则单图 token 数约为 <span class=\"inline\">N_i = (H_i/p)·(W_i/p)</span>；一个视觉批的总像素负载是 <span class=\"inline\">Σ H_i·W_i</span>。工程上真正卡住显存与算力的是这个和，而不是 batch size 字段。于是有第一条经验规则：<strong>批大小与平均分辨率成反比</strong>——分辨率翻倍，同桶可拼的张数应压到约四分之一，因为像素量按平方增长。</p>\n<div class=\"formula\">$$B_{\\text{vis}} \\approx \\left\\lfloor \\frac{P_{\\text{budget}}}{\\overline{HW}} \\right\\rfloor,\\qquad \\overline{HW}=\\frac{1}{n}\\sum_i H_iW_i$$</div>\n<p>这里的 <span class=\"inline\">P_budget</span> 是视觉塔单批可承受的像素总量上限，它不是拍脑袋定的常数，而是由三个约束取最小：视觉塔激活峰值显存、单批视觉编码的目标时延、以及视觉塔在解耦调度中允许占用的显存份额。测量方法是：固定分辨率桶，从单张开始倍增批大小，记录每次的峰值显存与端到端视觉编码时延，找到“时延开始超线性上升”或“显存逼近份额上限”的拐点，取拐点前一级作为 <span class=\"inline\">P_budget</span>。注意拐点通常出现在像素总量而非张数上——同桶内张数翻倍若分辨率减半，负载不变，时延也基本不变，这正是分桶的意义。</p>\n<p>代价侧要看清：像素预算定小了，视觉塔空转、语言队列饥饿；定大了，高分辨率桶单批显存溢出，触发重试与队列积压，尾部时延反而更差。一个具体例子：同一视觉塔，低分辨率桶（小图）可拼几十张，高分辨率桶只能拼个位数；若调度器用同一个 batch size 字段跑两个桶，高分辨率桶必然溢出。正确做法是每个桶独立维护 <span class=\"inline\">P_budget</span> 与推导出的张数上限，桶内 padding 到桶最大网格。</p>\n\n<h3 id=\"ap-mm-batch-terms-sec-15\">十五 · 分块 prefill 的块大小：与分页粒度对齐</h3>\n<p>LLM prefill 批把投影后的视觉 token 与文本 token 拼成一条序列做前向，计算量随序列长度平方增长。分块 prefill 把长序列切成固定块 <span class=\"inline\">C</span> 逐步前填，单次激活峰值从 <span class=\"inline\">O(L²)</span> 降到 <span class=\"inline\">O(C·L)</span> 量级，代价是调度轮次从 1 变成 <span class=\"inline\">⌈L/C⌉</span>，每轮都有固定的调度与 kernel launch 开销。</p>\n<div class=\"formula\">$$T_{\\text{prefill}} \\approx \\left\\lceil \\frac{L}{C} \\right\\rceil \\cdot \\left( t_{\\text{chunk}}(C) + t_{\\text{sched}} \\right)$$</div>\n<p>块大小 <span class=\"inline\">C</span> 的第一个工程阈值不是算力，而是 <strong>KV cache 分页粒度</strong>。若分页粒度为 <span class=\"inline\">P</span>（每页容纳固定 token 数），而 <span class=\"inline\">C</span> 不是 <span class=\"inline\">P</span> 的整数倍，跨块写入会在页边界产生额外拷贝与部分页填充，长序列请求的时延会高于不分块的基线——这是已知失败模式，不是理论担忧。因此经验规则是：<span class=\"inline\">C</span> 取分页粒度的整数倍，且尽量让每块恰好填满整数页。</p>\n<p>第二个阈值是“分块收益临界长度”。短序列分块只会增加轮次开销而无激活收益，所以设一个 <span class=\"inline\">L_min</span>：低于它的请求不分块，直接整段前填。测量方法：对同一模型，扫描序列长度与块大小二维网格，记录首 token 时延（TTFT）与峰值激活显存；<span class=\"inline\">L_min</span> 取“分块后 TTFT 开始低于整段前填”的交叉点，<span class=\"inline\">C</span> 取“TTFT 最低且显存不超预算”的那一档，再向上取整到分页粒度的倍数。视觉 token 往往成段出现，跨模态拼接点附近的块边界要避免切断图像段，否则注意力掩码与位置处理会引入额外分支。</p>\n\n<h3 id=\"ap-mm-batch-terms-sec-16\">十六 · 双队列的阈值：像素排序键与超时策略</h3>\n<p>解耦调度下视觉队列按像素预算与分辨率桶排序，语言队列按到达时间与剩余长度排序，两者优先级语义不同。视觉队列的排序键应是一个复合量：先按桶分组，桶内按像素量降序（大图优先吃掉预算，避免碎片化），同像素量再按到达时间。语言队列则是经典的到达时间加剩余长度，短剩余优先以压低平均时延。两队列的批大小、优先级、超时策略必须分别配置。</p>\n<p>视觉队列必须有独立的超时阈值 <span class=\"inline\">T_vis</span>：一个低优先级大图在视觉塔上停留超过 <span class=\"inline\">T_vis</span> 仍未凑满批，就单独成批发射，宁可牺牲一点视觉塔利用率也不让尾部请求无限等待。这是 SLO 感知调度只作用于语言队列时的典型失控点——视觉队列无超时，大图长期占用视觉塔，尾部时延失控。测量 <span class=\"inline\">T_vis</span> 的方法：统计视觉队列等待时间的分布，取目标 SLO 下可容忍的等待上限，再减去该桶单批编码时延的估计值；也可用“等待时间超过阈值即发射”的简单规则做在线自适应。</p>\n<p>语言队列侧的经验阈值是<strong>合并等待窗口</strong> <span class=\"inline\">W_merge</span>：新请求到达时，若其剩余时延预算充足且当前批还有空位，就等待合并进下一批；若预算紧张，立即单独成批。判据是剩余预算 <span class=\"inline\">D_rem</span> 与预估排队加执行时间 <span class=\"inline\">t_est</span> 的比较：<span class=\"inline\">D_rem &lt; t_est</span> 即超预算，优先单独成批。代价是合并窗口越长，批越大、吞吐越高，但尾部时延越差；窗口取零则退化为逐请求调度，吞吐塌陷。</p>\n\n<h3 id=\"ap-mm-batch-terms-sec-17\">十七 · 视觉塔显存释放的时序阈值</h3>\n<p>解耦调度的关键语义是视觉编码结果以 token 张量形式入语言队列，视觉批完成即释放视觉塔显存。这里有一个容易被忽略的时序阈值：token 张量从视觉塔搬到语言队列的<strong>交接缓冲</strong>必须在上游视觉批释放显存之前完成写入，否则要么阻塞视觉塔下一批，要么在交接区额外驻留一份拷贝。工程上把交接缓冲当作独立的小池管理，其容量阈值由“视觉批产出 token 张量的最大字节数 × 在途批数”决定。</p>\n<div class=\"formula\">$$M_{\\text{handoff}} \\ge n_{\\text{inflight}} \\cdot \\max_i \\left( N_i \\cdot d_{\\text{token}} \\right)$$</div>\n<p>其中 <span class=\"inline\">N_i</span> 是单图 token 数，<span class=\"inline\">d_token</span> 是每 token 的字节数（取决于量化精度，NVFP4/FP8 下显著小于 BF16）。在途批数 <span class=\"inline\">n_inflight</span> 是视觉塔流水深度，取“视觉编码时延 / 语言队列消费 token 的速率”之比向上取整。这个阈值定小了，视觉塔会在交接处空转；定大了，等于把视觉塔的显存份额偷偷挪给了交接区，反过来压缩 <span class=\"inline\">P_budget</span>。测量方法：在视觉批完成事件与语言队列接纳事件之间打时间戳，统计交接区峰值占用，取 P99 作为容量下限。</p>\n<p>另一个时序阈值是<strong>视觉批的最小有效张数</strong>。若一个桶长期凑不满最小张数，说明该桶的到达率过低，继续等批只会拉长时延；此时应把该桶并入相邻桶或降低其批大小目标。判据是桶到达率 <span class=\"inline\">λ_bucket</span> 与单批编码时延 <span class=\"inline\">t_bucket</span> 的乘积：<span class=\"inline\">λ_bucket · t_bucket &lt; 1</span> 意味着平均一个批周期内来不了一张图，该桶不具备独立成批的经济性。</p>\n\n<h3 id=\"ap-mm-batch-terms-sec-18\">十八 · 测量方法：没有数字时怎么测</h3>\n<p>本卷不给实验数字，只给可复现的测量协议。视觉侧的核心测量是<strong>像素-时延曲线</strong>：固定桶与分辨率，扫描像素总量（通过拼不同张数或缩放分辨率），记录视觉编码时延与峰值显存，拟合出拐点，得到该桶的 <span class=\"inline\">P_budget</span> 与张数上限。语言侧的核心测量是<strong>块大小-首 token 时延曲线</strong>：扫描 <span class=\"inline\">C</span> 与序列长度，记录 TTFT 与激活峰值，交叉点给出 <span class=\"inline\">L_min</span>，最低点给出 <span class=\"inline\">C</span>，再对齐分页粒度。</p>\n<p>调度侧的核心测量是<strong>双队列等待时间分布</strong>：分别统计视觉队列与语言队列的排队时延 P50/P99，以及视觉塔利用率与语言队列饥饿时长。三个指标互相牵制：视觉塔利用率高而语言队列饥饿，说明视觉批过大或视觉队列优先级过高；语言队列时延好而视觉塔空转，说明视觉批过小或超时阈值过短。调参顺序应是先定 <span class=\"inline\">P_budget</span> 与桶张数上限（硬件约束），再定 <span class=\"inline\">C</span> 与 <span class=\"inline\">L_min</span>（数值与分页约束），最后调 <span class=\"inline\">T_vis</span> 与 <span class=\"inline\">W_merge</span>（SLO 约束）。</p>\n<table class=\"mini\"><thead><tr><th>阈值</th><th>约束来源</th><th>测量信号</th><th>调错的代价</th></tr></thead><tbody><tr><td>像素预算 P_budget</td><td>视觉塔激活显存 / 显存份额</td><td>像素-时延拐点</td><td>溢出重试或视觉塔空转</td></tr><tr><td>块大小 C</td><td>KV 分页粒度</td><td>TTFT-块大小曲线</td><td>跨块额外拷贝，时延劣于基线</td></tr><tr><td>分块临界长度 L_min</td><td>调度轮次开销</td><td>分块/整段 TTFT 交叉点</td><td>短请求白付轮次开销</td></tr><tr><td>视觉超时 T_vis</td><td>尾部 SLO</td><td>视觉队列等待 P99</td><td>大图长期占塔，尾部失控</td></tr><tr><td>合并窗口 W_merge</td><td>吞吐与时延权衡</td><td>语言队列时延分布</td><td>窗口过长尾部差，过短吞吐塌</td></tr></tbody></table>\n<p>最后一条工程判断：所有阈值都应绑定到具体硬件与具体模型配置，跨配置复用阈值是失败模式的温床。视觉塔换精度（BF16 到 FP8/NVFP4）会改变 <span class=\"inline\">P_budget</span> 与交接缓冲容量；语言塔换分页粒度会改变 <span class=\"inline\">C</span> 的对齐要求；SLO 换档会改变 <span class=\"inline\">T_vis</span> 与 <span class=\"inline\">W_merge</span>。阈值表应随配置版本化，而不是当成全局常量写死在调度器里。</p>\n\n<h3 id=\"ap-mm-batch-terms-sec-19\">十九 · 像素预算、块对齐与超时门限：三个必须实测的阈值</h3>\n<p>视觉编码批的批大小不能按图像张数配置，必须按像素预算配置：单批像素总量 P_batch ≈ B_img × W × H，而显存占用近似正比于 P_batch 乘以每像素激活字节数。工程上先把视觉塔单批可用显存（总显存减去权重、workspace 与预留碎片）除以实测的每像素激活占用，得到像素预算上限，再让分桶器按桶最大网格反推该桶的批大小 B_bucket = floor(P_budget / (W_bucket × H_bucket))。这个反比关系是硬约束：同一像素预算下，1024×1024 桶的批大小只有 512×512 桶的四分之一。测量方法是固定桶、固定批大小，用 CUDA event 记录视觉塔前向的墙钟时间与峰值显存（torch.cuda.max_memory_allocated 或 Nsight 的显存曲线），二分逼近显存溢出点，取溢出点往下留一档作为生产配置。失效条件是分桶粒度太粗：若把长宽比差异大的图强行并入同桶，padding 到桶最大网格会放大 P_batch，实际像素远超预算，单批溢出触发重试，队列积压随之出现。</p>\n<p>分块 prefill 的块大小必须与 KV cache 分页粒度对齐。设分页粒度为 g 个 token（PagedAttention 的 block size），分块长度为 c，则跨块写入的额外拷贝量近似为每块边界一次 (c mod g) 的残片搬运，块数 N = ceil(L/c) 时总残片开销约 N × g 字节级拷贝。当 c 是 g 的整数倍时残片为零；当 c 与 g 互质，长序列请求的调度轮次增加，同时每块都要重读已写入的 KV 页，时延反而高于不分块基线。测量方法是同一长序列分别跑不分块与不同 c 值，记录首 token 时延与每块激活峰值，找出激活峰值下降但时延不升的 c 区间；若找不到，说明该序列长度下分块不划算，应回退整段 prefill。系统代价体现在调度轮次上：轮次越多，批间切换与流水气泡越多，吞吐被调度开销吃掉。</p>\n<table class=\"mini\"><thead><tr><th>阈值</th><th>约束对象</th><th>失效表现</th><th>测量手段</th></tr></thead><tbody><tr><td>像素预算 P_budget</td><td>视觉批大小</td><td>高分辨率桶溢出、重试积压</td><td>峰值显存二分逼近</td></tr><tr><td>块对齐 c ≡ 0 (mod g)</td><td>分块 prefill</td><td>跨块残片拷贝、时延反超</td><td>首 token 时延对比</td></tr><tr><td>视觉队列超时 T_vis</td><td>SLO 感知调度</td><td>大图长期占用视觉塔、尾部失控</td><td>尾部时延分位统计</td></tr></tbody></table>\n<p>视觉队列必须有独立的超时门限 T_vis，否则 SLO 感知调度只作用于语言队列，低优先级大图会长期占据视觉塔。判据是：请求剩余时延预算 R 小于其预计视觉编码时延加排队时延时，跳过合并、单独成批立即执行；否则进等待合并窗口，窗口长度取 T_vis。T_vis 的测量靠尾部时延分位：按分辨率桶分别统计视觉编码完成时刻的 P99，若某桶 P99 持续高于其 SLO 预算，说明该桶的合并窗口过长或批大小过大，应缩短窗口或拆批。代价是单独成批会降低视觉塔的批利用率，像素预算被小批浪费，吞吐下降；工程判断是优先保尾部时延，把利用率损失记入容量规划的冗余系数，而不是靠拉长窗口摊薄。</p>\n<div class=\"formula\">$$B_{\\text{bucket}}=\\left\\lfloor \\frac{P_{\\text{budget}}}{W_{\\text{bucket}}\\cdot H_{\\text{bucket}}}\\right\\rfloor,\\qquad \\text{copy}\\propto \\sum_{k=1}^{\\lceil L/c\\rceil}(c \\bmod g)$$</div>\n<h3 id=\"ap-mm-batch-terms-sec-20\">二十 · 视觉队列按张数定批：像素预算失守的第一现场</h3>\n<p>视觉编码批的吞吐由像素总量决定，而不是图像张数。这条事实一旦在配置里被写成“每批 N 张”，高分辨率桶就会立刻反噬：同一个 N 在低分辨率桶里只占少量显存，在 4K 桶里却能把视觉塔的激活与中间张量推到溢出边缘。溢出触发框架的重试逻辑，重试又把请求重新排回队尾，队列积压与显存抖动互相喂养，形成正反馈。</p>\n<p>正确的约束应写成像素预算下的反比关系。设桶的最大网格为 <span>H×W</span>，单批像素上限为 <span>P<sub>max</sub></span>，则桶内可拼批的张数上界为：</p>\n<div class=\"formula\">$$B_{\\text{img}}^{\\text{bucket}} = \\left\\lfloor \\frac{P_{\\max}}{H \\cdot W} \\right\\rfloor,\\quad B_{\\text{img}} \\ge 1$$</div>\n<p>工程上还要留出 padding 的余量：桶内统一 padding 到桶最大网格，意味着小图也在按最大网格计费，因此实际拼批应按“padding 后的网格像素”而非原始像素求和。检查顺序上，先验证每个分辨率桶的 <span>B<sub>img</sub></span> 是否随网格面积单调下降，再验证桶内 padding 后的总像素是否始终低于 <span>P<sub>max</sub></span>，最后才看吞吐。代价体现在显存峰值与重试率：一次溢出不只是浪费一个批，而是把整条视觉队列的时延分布拖出长尾。</p>\n\n<h3 id=\"ap-mm-batch-terms-sec-21\">二十一 · 分块 prefill 与 KV 分页粒度错位</h3>\n<p>分块 prefill 把长序列切成固定块逐步前填，降低单次激活峰值，但代价是调度轮次增加。真正的坑不在块大小本身，而在块大小与 KV cache 分页粒度不匹配：当块边界不落在分页边界上，跨块写入会触发额外拷贝，长序列请求的时延反而高于不分块的基线。这是一种“优化变成负优化”的典型失败，且因为单次激活峰值确实下降了，监控面板上看不出异常，只有端到端时延在长序列分位上悄悄劣化。</p>\n<p>检查方法是把块大小取为分页粒度的整数倍，并在调度器里显式记录每块的 token 区间与页区间映射。伪代码思路：</p>\n<ul>\n<li>对每个请求计算 <span>L<sub>seq</sub></span>，按 <span>ceil(L<sub>seq</sub>/C)</span> 得到块数，<span>C</span> 为块大小；</li>\n<li>强制 <span>C mod G = 0</span>，<span>G</span> 为 KV 分页粒度，使每块恰好覆盖整数个页；</li>\n<li>块尾若不足一页，用掩码而非补齐写入，避免跨页拷贝；</li>\n<li>在 profiler 中对比分块与不分块两条基线的长序列时延分位，若分块版本 P99 更高即判定为错位。</li>\n</ul>\n<p>系统代价是双重的：错位带来额外拷贝带宽，轮次增加带来调度开销；两者叠加时，长序列请求的时延会超过不分块基线。这个检查必须放在压测的早期，因为它的信号只出现在长序列分位，短请求压测完全测不出来。</p>\n\n<h3 id=\"ap-mm-batch-terms-sec-22\">二十二 · SLO 感知只覆盖语言队列</h3>\n<p>SLO 感知调度按剩余时延预算决定新请求进视觉队列还是等待合并，超预算请求优先单独成批。失败模式是这套逻辑只对语言队列生效，视觉队列没有超时策略：低优先级大图长期占用视觉塔，尾部请求时延失控。解耦调度形成两条优先级语义不同的队列——视觉队列按像素预算与分辨率桶排序，语言队列按到达时间与剩余长度排序——只给一条队列配 SLO，等于把另一条队列变成无底洞。</p>\n<p>视觉队列需要自己的超时与抢占规则。设请求的剩余预算为 <span>D<sub>rem</sub></span>，视觉塔单批预计耗时为 <span>t<sub>vis</sub></span>，则准入判据可写成：</p>\n<div class=\"formula\">$$\\text{admit} \\iff t_{\\text{vis}}(B_{\\text{img}}, \\text{bucket}) \\le D_{\\text{rem}} - t_{\\text{lang}}^{\\text{est}}$$</div>\n<p>其中 <span>t<sub>lang</sub><sup>est</sup></span> 是该请求进入语言队列后的预估排队与前填时间。判据不成立时，请求不应被塞进视觉批“碰运气”，而应转入等待合并或降级分辨率桶。检查清单上要分别核对两条队列的批大小、优先级与超时策略是否独立配置；任何一项共用默认值，都会在混合负载下暴露为视觉塔空转或语言队列饥饿。代价是尾部时延：视觉队列无超时策略时，一张大图可以把整条队列的 P99 拉高一个数量级。</p>\n\n<h3 id=\"ap-mm-batch-terms-sec-23\">二十三 · 解耦调度的交接语义检查</h3>\n<p>解耦调度的关键语义是视觉编码结果以 token 张量形式入语言队列，视觉批完成即释放视觉塔显存。这条语义在实现里最容易出两类错：一是视觉批完成后张量仍被引用，视觉塔显存不释放，下一批被迫等待；二是 token 张量入语言队列时没有携带分辨率桶与像素预算的元数据，语言队列无法据此做长度预估与分块决策。</p>\n<p>检查顺序建议按数据流走：视觉批完成事件 → 张量句柄移交 → 视觉塔显存释放 → 语言队列入队元数据完整性 → 语言队列按剩余长度排序。每一步都要有可观测的计数器和断言。具体例子：一个请求在视觉队列完成编码后，若其 token 张量仍挂在视觉侧的缓存池上，视觉塔的可用显存会随请求数线性下降，直到某次高分辨率桶拼批时溢出——此时错误现场在视觉塔，根因却在交接语义。</p>\n<p>系统代价是显存与吞吐的耦合：视觉塔显存不释放会压缩后续视觉批的拼批空间，间接降低视觉吞吐；元数据缺失则让语言队列失去长度预估能力，分块 prefill 的块数计算退化为保守估计，增加调度轮次。回滚方案上，这类问题适合用“关闭解耦、回退到串行视觉-语言”作为兜底开关，先把尾部时延稳住，再逐请求排查交接路径。</p>\n\n<h3 id=\"ap-mm-batch-terms-sec-24\">二十四 · 回滚方案与检查清单的落地顺序</h3>\n<p>多模态批调度的回滚不是单一开关，而是分层降级。第一层是调度层：关闭 SLO 感知调度，两条队列退回固定批大小与先到先服务，牺牲吞吐换时延可预测性。第二层是批组织层：关闭分辨率分桶的跨桶合并，只允许桶内拼批，减少 padding 无效计算与溢出风险。第三层是 prefill 层：关闭分块 prefill，回退到整段前填，接受更高的激活峰值以换取更少的调度轮次。每一层都要有独立的配置项与灰度开关，避免“一键回滚”把已经验证有效的优化一起关掉。</p>\n<p>检查清单按代价从高到低排序，先查会引发级联失败的项：</p>\n<table class=\"mini\">\n<thead>\n<tr><th>检查项</th><th>判据</th><th>失败代价</th></tr>\n</thead>\n<tbody>\n<tr><td>视觉批按像素预算定批</td><td>桶内 padding 后总像素 ≤ P<sub>max</sub></td><td>显存溢出、重试积压</td></tr>\n<tr><td>块大小对齐分页粒度</td><td>C mod G = 0，块尾掩码写入</td><td>长序列时延劣化、额外拷贝带宽</td></tr>\n<tr><td>视觉队列独立超时策略</td><td>准入判据含 D<sub>rem</sub> 与 t<sub>lang</sub><sup>est</sup></td><td>尾部时延失控、视觉塔被大图独占</td></tr>\n<tr><td>交接后视觉塔显存释放</td><td>完成事件后显存计数回落</td><td>拼批空间收缩、视觉吞吐下降</td></tr>\n<tr><td>入队元数据完整</td><td>token 张量携带桶与像素元数据</td><td>长度预估退化、分块轮次增加</td></tr>\n</tbody>\n</table>\n<p>回滚的触发条件应绑定可观测指标而非主观判断：视觉队列重试率、长序列 P99 与不分块基线的差值、视觉塔显存占用随请求数的斜率。三者任一越界即触发对应层的降级。最后落在工程判断上：多模态批调度的稳定性不取决于单点优化有多激进，而取决于每条队列是否拥有独立的预算、超时与回滚路径——把视觉队列当成语言队列的附属，是所有尾部时延事故的共同起点。</p>\n\n<h3 id=\"ap-mm-batch-terms-sec-25\">二十五 · 解耦双队列的失效边界与回滚判据</h3>\n<p>视觉队列与语言队列各自独立配置，是这套调度方案成立的前提，也是最容易失守的地方。视觉编码批的批大小必须按像素预算反推，而不是按图像张数：设桶内最大网格为 H×W、单批像素预算为 P<sub>budget</sub>、单图像素为 p<sub>i</sub>，则批内可容纳图像数 n 应满足 <span class=\"formula\">$$n \\le \\left\\lfloor \\frac{P_{\\text{budget}}}{\\max_i p_i} \\right\\rfloor$$</span> 同桶内 padding 到桶最大网格意味着实际占用按最大图像算，若按张数定批，高分辨率桶会直接把激活峰值推过显存水位，触发 OOM 重试，重试请求重新入队又进一步抬高峰值，形成积压正反馈。检查顺序上应先验证“像素预算 → 批大小 → 显存水位”这条链，再看语言队列的到达时间与剩余长度排序是否被视觉 token 洪峰打乱。代价体现在两处：视觉塔空转浪费的是 SM 与 HBM 带宽，语言队列饥饿浪费的是解码阶段的算力与 SLO 余量，两者叠加时吞吐下降而尾部时延同时恶化。</p>\n<p>分块 prefill 与 KV cache 分页粒度的对齐是第二个高频坑。块大小若与分页粒度不成整数倍关系，跨块写入会退化为额外拷贝，长序列请求的时延反而高于不分块基线——分块降低的是单次激活峰值，却增加了调度轮次与跨块同步开销。判据是：当块数 k 增加而单块计算量下降不足以抵消跨块拷贝与调度开销时，分块即为负收益。工程上应把块大小锁定为分页粒度的整数倍，并在压测中对比长序列请求的端到端时延与激活峰值两条曲线，只有峰值下降且时延不劣化才保留分块。系统代价是显存碎片与拷贝带宽：分页不匹配时拷贝走的是 HBM 往返，长序列请求在解码前就被拖慢，直接吃掉 SLO 预算。</p>\n<p>SLO 感知调度只挂在语言队列上，是尾部时延失控的典型成因。视觉队列若无超时策略，低优先级大图会长期占用视觉塔，视觉编码结果迟迟不能以 token 张量形式入语言队列，语言侧看到的只是“请求未到达”，超时判定失效。回滚方案应分层：第一层是视觉队列启用按剩余时延预算的抢占，超预算请求优先单独成批、跳过合并等待；第二层是把视觉批完成即释放视觉塔显存的语义做成硬约束，避免结果滞留；第三层才是整体回退到视觉与语言同步调度，牺牲解耦带来的重叠收益换取可预测的尾部时延。检查清单按此顺序执行：先看视觉队列是否有独立超时与像素预算，再看分块与分页是否对齐，最后看两队列批大小与优先级是否分别配置。任一环节缺失，解耦调度的收益都会被空转或饥饿抵消。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>可观测信号</th><th>回滚动作</th></tr></thead><tbody><tr><td>按张数定视觉批</td><td>高分辨率桶 OOM 重试率上升</td><td>改为按像素预算反推批大小</td></tr><tr><td>块大小与分页不匹配</td><td>长序列时延高于不分块基线</td><td>块大小对齐分页粒度整数倍</td></tr><tr><td>视觉队列无超时</td><td>语言队列饥饿、尾部时延抬升</td><td>启用预算抢占与单独成批</td></tr></tbody></table>\n<h3 id=\"ap-mm-batch-terms-sec-26\">二十六 · 上游依赖：本条目吃谁的输出</h3>\n<p>多模态批调度的每一个决策变量都不是自产的，而是上游条目的输出。视觉编码批的批大小由像素总量决定，这个“像素总量”来自预处理工具链给出的张量形状与分辨率分桶结果；分桶边界一旦被上游改动，桶内 padding 到最大网格的浪费比例随之变化，批大小必须跟着反比调整，否则高分辨率桶单批显存溢出。语言队列的排序键“剩余长度”依赖视觉 token 压缩条目输出的 token 数——压缩率变了，同一张图投影后的序列长度变了，prefill 批的计算量随序列长度平方增长，调度器按旧长度估算的时延预算立即失真。</p>\n<p>跨模态注意力条目决定视觉 token 以何种布局进入语言塔，这直接影响分块 prefill 的块边界能否与 KV cache 分页粒度对齐。若视觉 token 在序列中的插入位置随请求变化，块切分点就落在不确定的偏移上，跨块写入产生额外拷贝，长序列请求时延高于不分块基线。量化配方条目则约束了视觉塔与语言塔能否共用同一批精度路径：视觉塔走 FP8、语言塔走 NVFP4 时，投影层的数值转换点必须落在解耦边界上，调度器需要知道这个边界在哪，才能判断视觉批完成即释放视觉塔显存是否安全。</p>\n<p>把这些依赖写成调度器可消费的形式，是一条显式的接口契约：</p>\n<div class=\"formula\">$$B_{\\text{vis}} = \\left\\lfloor \\frac{P_{\\text{budget}}}{\\max_{(w,h)\\in \\text{bucket}} w\\cdot h} \\right\\rfloor,\\quad T_{\\text{prefill}} \\approx f\\!\\left(\\sum_i L_i^2\\right)$$</div>\n<p>其中像素预算 P_budget 由视觉塔显存溢出条目给出的可用显存上限折算，L_i 是第 i 条请求投影后的总序列长度。工程代价在于：契约字段每增加一个，调度器每轮排序就要多读一次元数据；在 NVL72 这种单机 72 卡、视觉塔与语言塔分池部署的形态下，元数据跨池传递走的是 NIXL 通道，字段膨胀直接抬高控制面延迟，而控制面延迟又计入 SLO 预算。因此上游条目应只暴露调度真正需要的三个量：桶标识、像素数、投影后 token 数，其余留在各自模块内部。</p>\n\n<h3 id=\"ap-mm-batch-terms-sec-27\">二十七 · 下游影响：谁在消费调度决策</h3>\n<p>调度器的输出不是“排好序的队列”这么抽象，而是三样具体东西：每个视觉批的成员集合与网格形状、每个语言批的成员集合与块切分方案、以及两条队列各自的超时阈值。分离式预填配方条目直接消费前两样——它要决定 prefill 实例与 decode 实例的配比，而这个配比的分母正是调度器给出的 prefill 批到达节奏。若调度器把视觉批与语言批的节奏错开，prefill 池会出现周期性空洞，decode 池则因 KV 传输等待而抖动；NIXL 上的 KV 迁移带宽被这种抖动放大成尾延迟。</p>\n<p>多模态批饥饿条目消费第三样。饥饿的本质是两条队列优先级语义不同却共用一套资源：视觉队列按像素预算与分辨率桶排序，语言队列按到达时间与剩余长度排序。调度器若只给语言队列配超时策略，低优先级大图会长期占用视觉塔，视觉批完成即释放显存的设计失效，尾部请求时延失控。反过来，若视觉队列超时过紧，大图被反复拆成小批，桶内 padding 浪费上升，视觉塔吞吐由像素总量决定这一优势被抵消。</p>\n<p>上线前清单条目则把上述全部转成可观测项：视觉队列的像素利用率、语言队列的块边界对齐率、跨池 KV 迁移的 P99 时延。这些指标的阈值不是拍脑袋定的，而是从本条目给出的批大小公式与块切分规则反推出来的。容量规划条目进一步把它们折算成卡数：视觉塔的卡数由峰值像素吞吐除以单卡像素吞吐得出，语言塔的卡数由峰值 token 吞吐与 KV cache 容量共同约束，两者的比值决定了 NVL72 机柜内 GPU 的分池比例。调度策略一变，这个比值就要重算，否则扩容方向会错。</p>\n\n<h3 id=\"ap-mm-batch-terms-sec-28\">二十八 · 与并行通信条目的耦合面</h3>\n<p>批调度看似是单机内的队列问题，但在 GB200/GB300 NVL72 上它必然跨池。视觉塔与语言塔解耦部署意味着视觉批的 token 张量要经 NVLink 5 送到语言池，这条路径的带宽与消息粒度由批的网格形状决定：桶内统一 padding 到桶最大网格，若桶跨度太大，小图被 padding 成大图，传输的是大量无效 token，NVLink 带宽被浪费；若桶切得太细，批数增多，每批的消息头开销占比上升，NCCL 集合通信的启动延迟摊薄不掉。</p>\n<p>更细的耦合点在分块 prefill 与 KV cache 分页。块大小若与分页粒度不匹配，跨块写入产生额外拷贝，这部分拷贝发生在语言池内部，但它的触发条件是调度器给的块切分方案。调度器若不知道分页粒度，就无法在排序时优先把长度接近分页整数倍的请求合并，结果是每个块都带一次尾部拷贝。工程判断是：块大小应取分页粒度的整数倍，并在调度器的排序键里加入“距最近整数倍的偏差”作为次级键，代价是排序复杂度从 O(n log n) 升到 O(n log n + n·k)，k 为候选桶数，在百级请求规模下可忽略，但换来的是拷贝次数下降带来的确定性时延。</p>\n<p>功耗维度同样被调度牵动。视觉塔在空转时仍占着显存与时钟，若视觉队列无超时策略导致长期低利用率占用，机柜功耗预算被无效持有；反之语言队列饥饿时 decode 池的 SM 利用率掉下来，功耗换不来吞吐。NVL72 的机柜级功耗上限是硬约束，调度器必须把两条队列的占用率作为功耗分配的输入，而不是事后统计。</p>\n\n<h3 id=\"ap-mm-batch-terms-sec-29\">二十九 · 在全书中的位置：术语层与配方层的接缝</h3>\n<p>本条目处在术语层与配方层的接缝上。向上，它把视觉编码器术语表、视觉 token 压缩术语、跨模态注意力术语里的名词转成调度器可比较的量；向下，它为多模态推理框架条目提供配置项语义——框架里那些看起来像“批大小上限”“队列超时”的参数，其正确取值只能由本条目定义的像素预算、桶边界、块对齐规则推出。框架文档不会告诉你为什么视觉批的批大小要随分辨率反比调整，本条目给出的是这条规则的推导链。</p>\n<p>它也是七个领域推理形态的共同底座。不同领域的图像分辨率分布、长宽比分布、视频抽帧节奏差异极大，分桶策略必须按领域重定，但分桶之后的批调度语义是同一套：像素总量定批大小、桶内 padding 到最大网格、视觉批完成即释放显存、两队列分别配超时。领域条目负责给出各自的分布参数，本条目负责给出参数到调度决策的映射。这条映射若写错，领域侧再精细的预处理也救不回来——高分辨率桶单批显存溢出触发重试与队列积压，是跨领域共通的失败模式。</p>\n<p>与多模态量化配方的接缝在于精度边界即调度边界。视觉塔与语言塔用不同精度时，投影层是唯一的转换点，调度器把视觉批的完成事件定义在转换点之前还是之后，决定了显存释放的时机与 KV 写入的时机能否重叠。定义在之前，视觉塔显存早释放但语言池要等转换；定义在之后，转换与传输可流水但视觉塔多占一段显存。这个选择没有普适答案，取决于桶内批大小与 NVLink 可用带宽的比值，属于容量规划条目要算的账。</p>\n\n<h3 id=\"ap-mm-batch-terms-sec-30\">三十 · 接口失配的三种典型断法</h3>\n<p>第一种断法在上游：预处理工具链改了分桶边界却没通知调度器，桶内最大网格变大，按旧公式算出的批大小使单批显存溢出，触发重试，重试请求回到视觉队列头部又挤掉正常请求，积压自我放大。检查点是桶边界变更必须走版本化契约，调度器读到不认识的桶版本时降级为保守批大小而非沿用旧值。</p>\n<p>第二种断法在横向：分块 prefill 的块大小由语言侧配置，KV cache 分页粒度由显存管理侧配置，两者独立演进后失配，跨块写入产生额外拷贝。这类断法不会报错，只表现为长序列请求时延高于不分块基线，极难定位。工程手段是把块大小与分页粒度的整除关系做成启动期断言，不满足则拒绝启动，把隐性性能损失转成显性配置错误。</p>\n<p>第三种断法在下游：SLO 感知调度只对语言队列生效，视觉队列无超时策略。低优先级大图长期占用视觉塔，视觉批完成即释放显存的设计被绕过，语言队列因等不到 token 而饥饿，两条队列的优先级语义彻底脱钩。修复不是给视觉队列加一个拍脑袋的超时值，而是把剩余时延预算拆成视觉段与语言段两本账，超预算请求优先单独成批，让大图以牺牲桶内拼批效率换取时延确定性——这是一次显式的取舍，必须记录在容量规划的假设里，否则下次扩容会按错误的效率假设算卡数。</p>\n\n<h3 id=\"ap-mm-batch-terms-sec-31\">三十一 · 边界条件：像素预算、分页粒度与双队列超时的耦合失效</h3>\n\n<p>这套术语体系的适用边界由三个耦合点划出。第一是视觉队列的批大小必须以像素总量为约束而非图像张数——当调度器沿用“每批 N 张”的直觉配置，高分辨率桶内单批激活与中间张量会直接撑爆视觉塔显存，触发重试、回退到更小批，进而形成队列积压；正确做法是令批大小随桶内平均像素数反比缩放，即 <span class=\"formula\">$$B_{\\text{vis}} \\approx \\left\\lfloor \\frac{P_{\\text{budget}}}{\\bar{p}_{\\text{bucket}}} \\right\\rfloor$$</span>，其中 <span class=\"formula\">$$P_{\\text{budget}}$$</span> 是视觉塔单批可承受的像素上限。代价是低分辨率桶被允许更大的批、更高的像素吞吐，而高分辨率桶批大小被压到很小，视觉塔利用率在混合负载下呈现明显的不均衡——这正是分辨率分桶必须与像素预算同时配置、不能只做 padding 对齐的原因。</p>\n\n<p>第二个失效点是分块 prefill 的块大小与 KV cache 分页粒度的错配。分块把长序列切成固定块逐步前填，降低单次激活峰值，但每块的 KV 写入若不能对齐分页边界，跨块写入就会产生额外的拼接拷贝，长序列请求的实际时延反而高于不分块基线。工程判断是：块大小应取分页粒度的整数倍，并让视觉 token 段与文本 token 段在块边界上尽量不跨界，否则解耦调度中“视觉批完成即释放视觉塔显存”的收益会被语言侧反复搬运抵消。此处系统代价体现在显存带宽而非算力上——拷贝是纯带宽开销，对 HBM 压力直接可见。</p>\n\n<p>第三个失效点是优先级语义的单边配置。视觉队列按像素预算与分辨率桶排序、语言队列按到达时间与剩余长度排序，二者语义本就不同；若 SLO 感知调度只挂在语言队列上，视觉队列缺少超时与抢占策略，低优先级大图会长期占用视觉塔，尾部请求时延失控。可用一张最小对照表刻画两队列必须分别配置的维度：</p>\n\n<table class=\"mini\"><thead><tr><th>维度</th><th>视觉队列</th><th>语言队列</th></tr></thead><tbody><tr><td>排序键</td><td>像素预算 / 分辨率桶</td><td>到达时间 / 剩余长度</td></tr><tr><td>批大小约束</td><td>像素总量上限</td><td>序列长度与 KV 分页</td></tr><tr><td>超时策略</td><td>桶级超时 + 超预算单独成批</td><td>剩余时延预算驱动接纳</td></tr></tbody></table>\n\n<p>该表的意义在于：两队列的批大小、优先级与超时策略任一维度共用配置，都会退化为视觉塔空转或语言队列饥饿。这条边界也决定了本条目在全书中的位置——它向上依赖显存与 KV cache 分页、NVFP4/FP8 数值精度对视觉塔激活的约束，向下为连续批处理、分离式预填/解码与 SLO 容量规划提供队列语义；一旦像素预算、分页粒度、双队列超时三者未同时对齐，后续所有吞吐与尾延迟推算都失去前提。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-mm-batch-terms\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>定义视觉编码批、LLM prefill批、连续批处理、分块prefill、图像分辨率分桶与SLO感知调度等概念…</td></tr><tr><td>关键点</td><td>见正文</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-mm-batch-terms · 共 5 个片段</p>\n"},{"id":"ap-preprocess-toolchain","title":"图像视频预处理工具链","summary":"覆盖解码、缩放、裁剪、归一化、动态分辨率分桶与视频抽帧的GPU侧管线，推荐使用DALI或torchvision v2在Blackwell上以CUDA kernel完成resize与normalize，避免CPU瓶颈拖慢视觉塔吞吐。","kind":"工具","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-1\">一 · 条目边界：什么算预处理，什么不算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-2\">二 · 按处理阶段的四类划分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-3\">三 · 按后端与融合程度的分类维度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-4\">四 · 速查表字段即分类维度的落地</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-5\">五 · 与相邻概念的区分：分桶不是批调度，抽帧不是几何变换</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-6\">六 · 分类的工程落点：阈值与失败模式的归属</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-7\">七 · 速查表的列定义与填写口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-8\">八 · 阈值表：三条必须落地的判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-9\">九 · 分桶与对齐：把形状收敛成常量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-10\">十 · 视频抽帧：解码位置决定延迟归属</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-11\">十一 · 归一化融合与接口张量的三个字段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-12\">十二 · 速查表模板与填写检查</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-13\">十三 · 预处理阈值的第一性原则：先测主机侧占比，再谈调参</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-14\">十四 · 分辨率分桶的对齐阈值：形状变化次数比分辨率本身更贵</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-15\">十五 · 归一化融合的判定：一次遍历还是两次遍历</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-16\">十六 · 视频抽帧的串行阈值：解码段是否主导端到端延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-17\">十七 · 没有数字时的测量协议：三条可复现的观测线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-18\">十八 · 阈值之间的耦合：批大小放大主机侧缺口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-19\">十九 · 预处理管线的失效边界：从利用率阈值到分桶对齐的工程判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-20\">二十 · 踩坑清单：按代价排序的四类失败</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-21\">二十一 · 检查顺序：从形状到数值的自外向内</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-22\">二十二 · 分桶对齐的伪代码与代价核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-23\">二十三 · 视频抽帧：解码与推理的重叠方案</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-24\">二十四 · 回滚方案：按影响面分层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-25\">二十五 · 预处理管线的失效边界与回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-26\">二十六 · 上游依赖：预处理是视觉塔吞吐的下限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-27\">二十七 · 下游影响：张量布局与分桶形状决定融合侧成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-28\">二十八 · 与量化配方的耦合：预处理决定 NVFP4/FP8 输入的动态范围</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-29\">二十九 · 与分离式预填/解码的位置关系：预处理属于预填侧的前置段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-30\">三十 · 在全书中的位置：预处理是七领域推理形态的共同底座</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-preprocess-toolchain-sec-31\">三十一 · 预处理管线的边界：它决定视觉塔能跑多快，也决定它何时失效</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-preprocess-toolchain\"><svg style=\"max-width:561px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 561.3 319\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"479.3\" height=\"83.0\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"53.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"57.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：图像视频预处理工具链</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">覆盖解码、缩放、裁剪、归一化、动态分辨率分桶与视频抽帧的GPU侧管线，</text><text x=\"75.0\" y=\"78.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">推荐使用…</text><line x1=\"82.0\" y1=\"97.0\" x2=\"82.0\" y2=\"114.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 113.0 L 86.5 113.0 L 82.0 121.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"121.0\" width=\"479.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"143.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"147.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"148.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><line x1=\"82.0\" y1=\"167.9\" x2=\"82.0\" y2=\"184.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 183.9 L 86.5 183.9 L 82.0 191.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"191.9\" width=\"479.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"214.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"218.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"219.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"238.7\" x2=\"82.0\" y2=\"255.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 254.8 L 86.5 254.8 L 82.0 262.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"262.8\" width=\"479.3\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"285.2\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"289.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"290.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-preprocess-toolchain-sec-1\">一 · 条目边界：什么算预处理，什么不算</h3>\n<p>图像视频预处理工具链的准确定义是：在 GPU 侧完成解码、缩放、裁剪、归一化、动态分辨率分桶与视频抽帧的管线集合，目标是把像素到张量的转换全部留在 CUDA kernel 内，避免主机内存与设备内存之间的往返拷贝。这个定义有三个限定词，缺一不可。第一是“GPU 侧”——同一套变换若在 CPU 上执行，属于主机侧数据加载，不构成本条目的讨论对象；第二是“像素到张量”——它的输入是压缩码流或原始像素，输出是视觉塔可直接消费的连续张量，边界落在张量布局确定的那一刻；第三是“管线集合”——它不是单个算子，而是从码流到批张量的有序阶段组合，任何一段掉回 CPU 都会把整条链路的收益吃掉。</p>\n<p>据此可以划出三条排除线。视觉编码器内部的 patch embedding、位置编码注入不属于预处理，它们发生在张量进入视觉塔之后，属于模型前向的一部分；视觉 token 压缩发生在编码器输出侧，输入已经是特征而非像素，方向相反；多模态批调度决定的是“哪些请求组成一批、批多大”，而预处理的分桶调度只决定“同一批内样本如何归并到形状一致的张量”，前者是请求级策略，后者是张量级整形。把这三者混为一谈，是速查表列错字段的常见根源。</p>\n<p>一个具体例子能说明边界的实际意义：当视觉塔因等待数据而利用率偏低时，工程师第一反应往往是调批大小或换调度器，但如果瓶颈在 CPU 侧的 resize 与 normalize，调批只会让等待更明显——批越大，主机侧要准备的像素越多，GPU 空转的窗口越长。判断归属的方法是看时间花在哪一段：若 NVDEC 或 GPU JPEG 解码已启动而后续 kernel 未排队，问题在几何变换与归一化是否融合进了 CUDA 图；若解码本身没启动，问题在码流获取，已经越出本条目边界。</p>\n\n<h3 id=\"ap-preprocess-toolchain-sec-2\">二 · 按处理阶段的四类划分</h3>\n<p>条目内部按处理阶段分为四类，外加视频侧的时间维度。解码类负责把压缩码流还原为像素平面，后端是 NVDEC（视频）与 GPU JPEG 解码（图像），其代价由码流码率与解码器吞吐决定，输出通常落在设备显存的平面格式缓冲里；几何变换类执行 resize、crop、pad，代价由插值方式与输出像素数决定，双线性与最近邻的 kernel 开销差异直接体现在每样本的 SM 占用上；像素归一化类做 mean/std 减除与通道置换，代价是逐元素带宽，融合进 resize 的 epilogue 可省掉一次全张量读写；分桶调度类按分辨率归并样本，代价不在算力而在形状稳定性。</p>\n<p>四类的串联顺序有硬约束：解码必须最先，归一化必须最后（因为它改变数值域），几何变换居中，分桶在几何变换之后、归一化之前或之后皆可，但必须保证同一批输出张量形状一致。视频侧另含抽帧与时间采样维度，它不是第五类几何变换，而是决定“哪些帧进入管线”的采样策略，与解码类耦合：抽帧若在 CPU 解码后做，等于把解码段拉回主机，整条链路的串行化从这里开始。</p>\n<div class=\"formula\">$$T_{\\text{pipe}} = T_{\\text{dec}} + \\max_i \\left( T_{\\text{geo},i} + T_{\\text{norm},i} \\right) + T_{\\text{pack}}$$</div>\n<p>这个式子表达的是：解码段与后续段在流水线填满后可重叠，几何变换与归一化在同一 stream 内串行，pack 是把分桶结果拼成批张量的整形开销。工程含义很直接——若 <span>T<sub>dec</sub></span> 在 CPU 上执行，它无法与 GPU 段重叠，端到端延迟被解码段主导，这正是视频抽帧在 CPU 解码后再拷贝到 GPU 的失败模式：解码与推理串行，抽帧策略再优也救不回来。</p>\n\n<h3 id=\"ap-preprocess-toolchain-sec-3\">三 · 按后端与融合程度的分类维度</h3>\n<p>第二个分类维度是后端实现：DALI、torchvision v2 与自研三类。DALI 的价值在于把解码、几何变换、归一化组织成 GPU 侧的算子图，天然支持 NVDEC 与批内形状处理；torchvision v2 的价值在于以 CUDA kernel 执行 resize 与 normalize，并与 PyTorch 张量生态直接对接，省去跨框架的布局转换；自研路线的价值在于可以把归一化融进 resize 的 epilogue、把分桶逻辑编进 kernel 的 grid 映射，代价是维护成本与对插值语义的自行保证。三者的选择不取决于功能清单，而取决于视觉塔接口的张量布局是否与工具输出一致——布局不一致时的转置拷贝，会把 GPU 侧省下的带宽又还回去。</p>\n<p>第三个维度是融合程度，它比后端选择更能决定实际吞吐。归一化是否融合进几何变换，决定了每样本是否多一次全张量读加一次全张量写；在像素数大的分辨率下，这次往返的带宽开销与 resize 本身同量级。是否 GPU 解码决定了流水线能否重叠；resize 插值方式决定了 kernel 的算术强度，双线性需要四次采样加权重，最近邻只需一次索引。动态分辨率分桶支持则是形状维度的融合——它不减少单样本开销，但把“每批形状变化”变成“每桶形状固定”，从而消掉重编译。</p>\n<table class=\"mini\"><thead><tr><th>分类维度</th><th>取值</th><th>对推理系统的直接代价</th></tr></thead><tbody><tr><td>处理阶段</td><td>解码 / 几何 / 归一化 / 分桶</td><td>决定流水线能否重叠，解码在 CPU 则串行</td></tr><tr><td>后端</td><td>DALI / torchvision v2 / 自研</td><td>决定布局转换次数与维护成本</td></tr><tr><td>解码位置</td><td>GPU 解码 / CPU 解码后拷贝</td><td>CPU 解码使端到端延迟被解码段主导</td></tr><tr><td>归一化融合</td><td>融合进 resize / 独立 kernel</td><td>独立 kernel 多一次全张量读写带宽</td></tr><tr><td>分桶对齐</td><td>对齐到固定尺寸 / 任意形状</td><td>未对齐触发 kernel 重编译与显存碎片</td></tr></tbody></table>\n\n<h3 id=\"ap-preprocess-toolchain-sec-4\">四 · 速查表字段即分类维度的落地</h3>\n<p>速查表应包含的列本身就是分类维度的投影：工具名称、支持后端（DALI/torchvision v2/自研）、是否 GPU 解码、resize 插值方式、归一化是否融合、动态分辨率分桶支持、视频抽帧策略、与视觉塔的接口张量布局。前七列刻画工具能力，最后一列刻画接口契约。工程上最后一列最容易被忽略却最先出问题：工具输出的张量若是 NCHW 而视觉塔期望 NHWC，或通道顺序是 BGR 而模型按 RGB 训练，转换发生在视觉塔入口，等于把预处理省下的带宽在入口处重新付出，且这次转换往往不在任何性能剖析的显式标记里。</p>\n<p>把速查表当分类工具用时，正确的读法是按“是否 GPU 解码”与“归一化是否融合”两列先筛，再用“分桶支持”列筛形状稳定性，最后用接口布局列做兼容性校验。这个顺序对应代价量级：解码位置决定流水线是否串行，融合程度决定带宽往返次数，分桶决定 kernel 启动是否稳定，布局决定是否需要额外拷贝。反过来按功能丰富度排序，会选出功能全但布局不合的工具，落地时在入口处付出转置代价。</p>\n<p>一个具体判断：若某工具在速查表中“是否 GPU 解码”为否而其余列全优，它在本条目语境下仍是次优选择——因为解码段在 CPU 意味着抽帧与推理串行，几何变换与归一化再快也只能缩短串行段的后半截。这不是工具优劣的评价，而是分类维度与系统代价的对应关系：解码位置是流水线重叠的前提，其余维度是重叠成立后的优化。</p>\n\n<h3 id=\"ap-preprocess-toolchain-sec-5\">五 · 与相邻概念的区分：分桶不是批调度，抽帧不是几何变换</h3>\n<p>最容易混淆的相邻概念是动态分辨率分桶与多模态批调度。分桶调度类的动作发生在张量层：把不同分辨率的样本按目标尺寸归并，必要时 pad 到桶边界，使同一批的输出张量形状一致；批调度的动作发生在请求层：决定哪些请求同批、批多大、何时抢占。二者的失败模式也不同——分桶未对齐到固定尺寸，导致每批形状变化，引发 kernel 重编译与显存碎片；批调度失当导致批饥饿，是请求供给问题。把分桶写进批调度条目，会让读者以为调大批就能解决重编译，实际上重编译的根因是形状不稳定，与批大小无关。</p>\n<p>第二个区分是视频抽帧与几何变换。抽帧决定时间轴上的采样，几何变换决定空间轴上的重采样，二者正交但共享解码段。抽帧策略若表达为“解码全部帧再在 GPU 上选帧”，解码开销按全帧计；若表达为“按时间戳定位关键帧再解码”，解码开销按选中帧计。后者要求解码器支持按位置寻址，属于解码类的能力，不属于抽帧策略本身。工程含义是：抽帧的代价不在选帧那一步，而在它迫使解码段做多少工作——这正是视频侧预处理与图像侧最大的结构差异。</p>\n<p>第三个区分是本条目与视觉塔显存溢出的关系。预处理输出的批张量占据设备显存，分辨率越高、批越大，占用越显著；但显存溢出的根因常在视觉塔的激活与 KV 侧，预处理只是把输入尺寸送上去。判断方法是看溢出发生在预处理输出之后还是视觉塔前向之中：前者可通过分桶与批形状控制缓解，后者越出本条目。这个区分决定了优化动作该落在工具链还是模型侧，混在一起会把显存问题误诊为预处理配置问题。</p>\n\n<h3 id=\"ap-preprocess-toolchain-sec-6\">六 · 分类的工程落点：阈值与失败模式的归属</h3>\n<p>材料未给出具体吞吐数字，但给出了一条可操作的工程阈值：预处理若在 CPU 完成，单卡视觉塔常因主机侧瓶颈出现 GPU 利用率低于 50% 的情况，故推荐 DALI 或 torchvision v2 以 CUDA kernel 执行 resize 与 normalize。这条阈值的分类含义是：GPU 利用率低于一半时，先查预处理归属，再查模型与调度。它把“CPU 侧 resize 与归一化成为瓶颈、视觉塔 GPU 利用率被拖低、批越大等待越明显”这一失败模式定位在分类的第一维（处理阶段）与第三维（解码位置）上，而不是归因于批大小或模型效率。</p>\n<p>失败模式的归属因此可以按分类维度直接映射：CPU 侧 resize 与归一化瓶颈归入“归一化未融合 + 解码/变换在主机”；分桶未对齐归入“分桶调度类的形状维度”；视频抽帧在 CPU 解码后拷贝归入“解码位置”维度。三者对应三种不同的修复动作——换后端并把归一化融进 resize、把桶边界对齐到固定尺寸、把解码移入 GPU 侧并与抽帧策略合并。分类的价值不在于给工具贴标签，而在于让失败模式一出现就能落到具体维度上，从而选出正确的修复动作而不是调参。</p>\n<p>最后落在一条工程判断上：本条目所有分类维度的排序应以“是否消除主机与设备之间的往返拷贝”为第一优先级，因为它是定义中唯一不可妥协的限定；融合程度与分桶对齐是在此前提下压缩带宽与稳定 kernel 启动的二阶优化，接口张量布局则是防止收益在视觉塔入口被抵消的校验项。按这个优先级读速查表，选型与排障会收敛到同一套判断上。</p>\n<h3 id=\"ap-preprocess-toolchain-sec-7\">七 · 速查表的列定义与填写口径</h3>\n<p>这张表不是选型推荐表，而是“照着填就能跑”的字段清单。每一行代表一个候选工具（DALI、torchvision v2、自研 CUDA 管线），八列必须全部填满，缺一列就意味着上线后会出现一处不可观测的代价。填写口径统一如下：<strong>工具名称</strong>写库名加版本分支（如 DALI 的 GPU 后端、torchvision v2 的 CUDA 算子路径）；<strong>支持后端</strong>只填该工具实际执行 kernel 的后端，不要写“支持多种”；<strong>是否 GPU 解码</strong>填“是/否/仅视频”，图像 JPEG 解码走 nvJPEG 与视频走 NVDEC 是两条不同路径，必须分开标注；<strong>resize 插值方式</strong>填具体算法（bilinear、bicubic、nearest、area），因为插值方式决定视觉塔输入分布是否与训练一致；<strong>归一化是否融合</strong>填“融合进 resize kernel / 独立 kernel / CPU 侧”，这一列直接对应显存往返次数；<strong>动态分辨率分桶支持</strong>填“原生 / 需外层包装 / 不支持”；<strong>视频抽帧策略</strong>填抽帧发生在解码前（按时间戳 seek）还是解码后（全解码再采样）；<strong>与视觉塔的接口张量布局</strong>填 NCHW 还是 NHWC、是否已经是 pinned 的 device tensor、是否带 padding mask。</p>\n<p>口径上有一条硬约束：<em>任何一列填“CPU 侧”的行，都必须在备注里标出它对应的主机侧带宽开销</em>。原因是预处理管线里最贵的不是算术，而是 H2D 拷贝。以一张 1024×1024×3 的 uint8 图像为例，单张 3 MiB，一个 batch 32 张就是 96 MiB；若归一化在 CPU 完成再转 float32 送入设备，同一批数据在 PCIe 上要搬 384 MiB，而 GPU 侧 resize+normalize 只需一次 3 MiB 的 H2D。这个比例关系就是速查表要暴露的东西：</p>\n<div class=\"formula\">$$T_{\\text{pre}} \\approx \\max\\left(\\frac{B \\cdot S \\cdot C}{b_{\\text{H2D}}},\\ \\frac{B \\cdot S \\cdot C \\cdot k_{\\text{op}}}{F_{\\text{SM}}}\\right)$$</div>\n<p>其中 $B$ 为批大小，$S$ 为单样本字节数，$C$ 为通道数相关的放大系数（CPU 归一化后转 float32 时 $C=4$），$b_{\\text{H2D}}$ 为主机到设备带宽，$k_{\\text{op}}$ 为每像素算子数，$F_{\\text{SM}}$ 为可用 SM 吞吐。第一项是拷贝项，第二项是计算项；CPU 侧预处理把第一项放大 4 倍以上，于是拷贝项压倒计算项，视觉塔就在等数据。工程判断很简单：<strong>速查表里凡是“归一化=CPU 侧”的行，直接判为不满足 GPU 侧管线目标</strong>，不必再测吞吐。</p>\n\n<h3 id=\"ap-preprocess-toolchain-sec-8\">八 · 阈值表：三条必须落地的判据</h3>\n<p>材料没有给出具体吞吐数字，因此阈值只能写成结构性判据而非绝对值。第一条是<strong>GPU 利用率判据</strong>：预处理若留在 CPU 完成，单卡视觉塔常因主机侧瓶颈出现 GPU 利用率低于 50% 的情况。这条阈值的作用不是监控告警，而是分诊——利用率低于 50% 且 batch 越大等待越明显，几乎可以断定瓶颈在主机侧 resize/normalize，而不是视觉塔本身算力不足。第二条是<strong>形状稳定性判据</strong>：动态分辨率分桶后，若同一 batch 内张量未做 padding 对齐到固定尺寸，每批形状变化会触发 kernel 重编译与显存碎片。判据写成“桶内尺寸集合的基数”更可操作：一个桶内出现的不同 (H, W) 组合数应当收敛到 1，最多允许少量离散档位；基数随 batch 增长而增长，就是没对齐。第三条是<strong>串行度判据</strong>：视频抽帧若在 CPU 解码后再拷贝到 GPU，解码与推理串行，端到端延迟被解码段主导；判据是解码段耗时占端到端延迟的比例，超过一半即判定为串行瓶颈。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>判据</th><th>观测字段</th><th>阈值口径</th><th>触发的系统代价</th></tr>\n</thead>\n<tbody>\n<tr><td>主机侧瓶颈</td><td>视觉塔 SM 利用率、batch 等待时间</td><td>利用率低于 50%，且随 batch 增大而恶化</td><td>吞吐被 H2D 带宽锁死，增大 batch 无收益</td></tr>\n<tr><td>形状漂移</td><td>桶内 (H,W) 组合基数、kernel 编译次数</td><td>桶内基数应收敛到 1</td><td>kernel 重编译 + 显存碎片，延迟抖动</td></tr>\n<tr><td>解码串行</td><td>解码段耗时 / 端到端延迟</td><td>解码占比超过一半</td><td>端到端延迟由解码段主导，GPU 空转</td></tr>\n</tbody>\n</table>\n<p>三条判据共享一个前提：都要在<em>真实 batch 分布</em>下测，而不是单样本基准。单样本时拷贝项与计算项都小，CPU 侧预处理看不出问题；批越大等待越明显，这正是失败模式里写的那句话。所以阈值表的用法是：先用小 batch 确认功能正确，再用生产 batch 分布跑三条判据，任何一条不达标就回到速查表改对应列。</p>\n\n<h3 id=\"ap-preprocess-toolchain-sec-9\">九 · 分桶与对齐：把形状收敛成常量</h3>\n<p>动态分辨率分桶的本质是把连续的分辨率分布离散化，让视觉塔看到有限个形状。速查表里“动态分辨率分桶支持”这一列填“原生”的工具，通常自带按面积或按长边归并的逻辑；填“需外层包装”的，则要在数据加载器里自己实现归并与 padding。归并的伪代码思路如下：</p>\n<ul>\n<li>对每个样本计算目标桶键 $k = \\lfloor \\log_2(\\max(H,W)) \\rfloor$，按 $k$ 分组；</li>\n<li>组内取该桶的最大 (H, W) 作为对齐尺寸，所有样本 pad 到该尺寸，pad 区域在接口张量里用 mask 标记；</li>\n<li>若组内尺寸跨度超过一档，拆分成两个桶，宁可多一个桶也不要让桶内基数大于 1；</li>\n<li>桶的数量上限由显存决定：每个桶对应一组固定形状的激活缓冲，桶越多，显存碎片越多。</li>\n</ul>\n<p>代价落在两处。其一是<strong>显存</strong>：padding 到桶内最大尺寸意味着小图被放大占用，桶内尺寸跨度越大，浪费的显存越多；用 mask 标记 pad 区域可以让视觉塔的注意力跳过这些位置，但卷积类视觉塔仍会实打实算 pad 像素。其二是<strong>延迟</strong>：形状固定后 kernel 只需编译一次，launch 开销摊薄；形状漂移时每次新形状都要重编译，延迟抖动直接体现在 P99 上。具体例子：一批样本长边分布在 640 到 1280 之间，若按 log2 分桶得到 640–896、896–1280 两档，桶内 pad 到 896 与 1280；若不归并直接按原始尺寸送，一个 batch 内可能出现七八种形状，视觉塔侧就是七八次重编译。</p>\n<div class=\"formula\">$$W_{\\text{pad}} = \\sum_{i \\in \\text{bucket}} \\left(H_{\\max} W_{\\max} - H_i W_i\\right) \\cdot C$$</div>\n<p>上式是单桶的 padding 浪费像素量。工程上把它控制在桶内总像素的百分之几以内，否则不如把桶拆细；拆细的代价是桶数增加、显存碎片上升。这个权衡就是速查表“分桶支持”列要标注的东西：原生支持的工具通常已经内置了这层权衡，外层包装的工具则要自己承担。</p>\n\n<h3 id=\"ap-preprocess-toolchain-sec-10\">十 · 视频抽帧：解码位置决定延迟归属</h3>\n<p>视频侧的速查表多出一列“视频抽帧策略”，填写口径只有两种合法值：<strong>解码前按时间戳 seek</strong> 与 <strong>解码后采样</strong>。前者在 NVDEC 上只解目标帧，后者全解码再丢弃。两者的代价差异不在算术量，而在解码段是否与推理重叠。按时间戳 seek 时，解码器只需定位关键帧并解到目标帧，解码段短且可与上一批的视觉塔计算重叠；解码后采样则把整段视频解完，解码段长度与视频时长成正比，端到端延迟被解码段主导，正是失败模式第三条。</p>\n<p>抽帧策略还要与批调度对齐：一个视频样本通常抽固定数量的帧（如 8 帧或 16 帧），这些帧在接口张量里应当作为独立的视觉塔输入排进同一批，而不是作为带时间维的 5D 张量。原因是视觉塔的 kernel 按 4D NCHW 优化，5D 张量会退化成逐帧循环 launch。速查表“接口张量布局”列因此要写清：帧是折叠进 batch 维，还是保留时间维。折叠进 batch 维的代价是 batch 变大、显存占用上升，但 kernel launch 次数下降；保留时间维的代价是 launch 次数随帧数线性增长。具体例子：8 帧 × 批 4 个视频 = 32 个视觉输入，折叠后是一次 batch 32 的视觉塔前向，保留时间维则是 4 次 batch 8 的前向加一次时间维归约。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>抽帧策略</th><th>解码段长度</th><th>与推理重叠</th><th>端到端延迟归属</th></tr>\n</thead>\n<tbody>\n<tr><td>解码前按时间戳 seek</td><td>与目标帧位置相关，短</td><td>可与上一批重叠</td><td>视觉塔</td></tr>\n<tr><td>解码后采样</td><td>与视频时长成正比，长</td><td>串行</td><td>解码段</td></tr>\n</tbody>\n</table>\n\n<h3 id=\"ap-preprocess-toolchain-sec-11\">十一 · 归一化融合与接口张量的三个字段</h3>\n<p>归一化是否融合，是速查表里最容易被填错的一列。融合的正确含义是：mean/std 减法与通道置换被编译进 resize kernel 的同一次访存，像素从全局内存读出一次就完成几何变换与数值变换，写回时已是视觉塔可直接消费的布局。独立 kernel 的含义是 resize 写回一次、归一化再读一次写一次，访存次数翻倍。CPU 侧的含义是上述两次访存发生在主机内存，外加一次放大的 H2D。三者的代价按访存次数排序，融合最优。</p>\n<p>接口张量布局要填三个字段：<strong>通道顺序</strong>（NCHW 或 NHWC）、<strong>数据类型</strong>（uint8 还是 float16/bfloat16）、<strong>是否带 mask</strong>。通道顺序决定视觉塔第一层卷积是否需要转置；数据类型决定 H2D 带宽占用，uint8 比 float16 省一半带宽，但归一化必须在设备侧做才能保持这个优势；mask 决定分桶 padding 是否被注意力跳过。三个字段组合起来就是一次完整的接口契约，任何一项与视觉塔预期不符，都会在视觉塔内部插入一次额外的转换 kernel，把预处理省下的时间又还回去。具体例子：预处理输出 NHWC float16 无 mask，而视觉塔期望 NCHW float16 带 mask，则视觉塔入口要多一次 permute 与一次 mask 构造，两次额外 kernel 的 launch 开销在小 batch 下足以抵消融合归一化的收益。</p>\n<div class=\"formula\">$$N_{\\text{access}} = \\begin{cases} 2 &amp; \\text{融合} \\\\ 4 &amp; \\text{独立 kernel} \\\\ 4 + \\tfrac{4S}{S} &amp; \\text{CPU 侧（含放大 H2D）} \\end{cases}$$</div>\n<p>工程判断落在最后一行：CPU 侧预处理的访存次数不是 4 而是 4 加上放大系数，因为 float32 转换让 H2D 字节数变成 uint8 的四倍。速查表填完后，把每一行的 $N_{\\text{access}}$ 算出来排序，排在前面的就是该换掉的行。这一步不需要跑基准，只需要读表。</p>\n\n<h3 id=\"ap-preprocess-toolchain-sec-12\">十二 · 速查表模板与填写检查</h3>\n<p>把上面五节的字段与口径合并，得到可直接复制使用的模板。填写时的检查顺序是：先确认“是否 GPU 解码”与“归一化是否融合”两列没有 CPU 侧值，再确认“分桶支持”列对应的桶内基数能收敛到 1，最后确认“接口张量布局”三字段与视觉塔预期一致。三关都过，这一行才算可用。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>工具名称</th><th>支持后端</th><th>GPU 解码</th><th>resize 插值</th><th>归一化融合</th><th>分桶支持</th><th>抽帧策略</th><th>接口布局</th></tr>\n</thead>\n<tbody>\n<tr><td>DALI（GPU 后端）</td><td>DALI</td><td>是（nvJPEG/NVDEC）</td><td>bilinear/bicubic/area</td><td>融合</td><td>需外层包装</td><td>解码前 seek</td><td>NCHW，uint8 或 fp16，可带 mask</td></tr>\n<tr><td>torchvision v2（CUDA 算子）</td><td>torchvision v2</td><td>否（解码另配）</td><td>bilinear/bicubic/nearest</td><td>独立 kernel 或融合</td><td>需外层包装</td><td>解码后采样</td><td>NCHW，fp16，可带 mask</td></tr>\n<tr><td>自研 CUDA 管线</td><td>自研</td><td>按需</td><td>按需</td><td>按需</td><td>原生</td><td>按需</td><td>按需</td></tr>\n</tbody>\n</table>\n<p>模板里“自研”行的“按需”不是偷懒，而是提醒：自研管线的每一列都要自己给出确定值，否则它就不是一张可查的表。检查时还有一个隐含字段要写进备注——<strong>该工具在 Blackwell 上是否以 CUDA kernel 执行 resize 与 normalize</strong>。材料给出的推荐是 DALI 或 torchvision v2 以 CUDA kernel 完成这两步，避免 CPU 瓶颈拖慢视觉塔吞吐；因此速查表里凡是不满足这条的行，备注必须写明替代路径，否则这张表就只是罗列而没有判据。最后一条检查落在视频行：抽帧策略填“解码后采样”的行，备注要标注解码段与推理是否串行，串行的行直接判为端到端延迟不可控。</p>\n<h3 id=\"ap-preprocess-toolchain-sec-13\">十三 · 预处理阈值的第一性原则：先测主机侧占比，再谈调参</h3>\n<p>预处理工具链的阈值不是从论文里抄来的，而是从一条可观测的分解式里推出来的。把端到端视觉塔前向时间拆成三段：<span class=\"formula\">$$T_{\\text{e2e}} = T_{\\text{host}} + T_{\\text{h2d}} + T_{\\text{tower}}$$</span>，其中 <span class=\"formula\">$$T_{\\text{host}}$$</span> 是解码、resize、normalize 在主机侧（CPU 或未走 CUDA kernel 的路径）消耗的时间，<span class=\"formula\">$$T_{\\text{h2d}}$$</span> 是主机到设备的拷贝，<span class=\"formula\">$$T_{\\text{tower}}$$</span> 是视觉塔本身。工程上唯一有意义的阈值是比值 <span class=\"formula\">$$r = T_{\\text{host}} / T_{\\text{tower}}$$</span>：当 <span class=\"formula\">$$r$$</span> 接近或超过 1，视觉塔的 GPU 利用率就会被拖到 50% 以下，此时批越大等待越明显，因为每批都要等主机侧把整批像素准备好。测量方法很直接：在视觉塔前后各打一个 CUDA event，同时在主机侧用单调时钟记录预处理函数的进入与退出，两者相减即得 <span class=\"formula\">$$T_{\\text{host}}$$</span>；再用 Nsight Systems 的 CUDA API 与 kernel 行确认这段时间里 GPU 是否真的空闲。若时间线上出现大段无 kernel 的空白，且空白与预处理函数调用对齐，则瓶颈判定成立。这一步必须在调任何参数之前完成，否则后续所有阈值都是在错误的基线上做优化。</p>\n\n<h3 id=\"ap-preprocess-toolchain-sec-14\">十四 · 分辨率分桶的对齐阈值：形状变化次数比分辨率本身更贵</h3>\n<p>动态分辨率分桶的收益来自按分辨率归并样本，代价来自形状变化。Blackwell 上视觉塔的 kernel 一旦遇到未对齐的输入尺寸，会触发重编译或退化为低效 launch，同时显存分配器面对不断变化的张量尺寸会产生碎片。因此分桶的工程阈值应落在“每批形状变化次数”上，而不是“桶的数量”上。设一个桶集合 <span class=\"formula\">$$B = \\{s_1, s_2, \\dots, s_k\\}$$</span>，每个尺寸 <span class=\"formula\">$$s_i$$</span> 对齐到 <span class=\"formula\">$$a$$</span> 的整数倍（<span class=\"formula\">$$a$$</span> 取视觉塔 patch 尺寸与 MMA tile 尺寸的公倍数），则批内形状方差被压到零。判据是：在一个统计窗口内，若同一桶内出现两种以上非对齐尺寸，或分桶后每批仍需 padding 到不同尺寸，则对齐阈值不达标。测量方法是记录每个 batch 的实际张量 shape 序列，统计相邻 batch 之间 shape 变化的频率；频率高即说明分桶键没有把尺寸收敛到有限集合。代价体现在两处：kernel launch 开销随形状变化次数线性上升，显存碎片使后续大 batch 无法分配到连续块。具体例子：同一批 8 张图若分别落在 1024×768、1000×750、1024×760 三个未对齐尺寸，视觉塔要跑三次不同的 launch 配置；把它们统一 padding 到 1024×768 后只跑一次，代价是少量无效像素的计算，收益是形状稳定。</p>\n\n<h3 id=\"ap-preprocess-toolchain-sec-15\">十五 · 归一化融合的判定：一次遍历还是两次遍历</h3>\n<p>归一化（减 mean、除 std、通道置换）是否与 resize 融合进同一个 CUDA kernel，决定了像素数据被读几次。未融合时，resize 写出一份中间张量到显存，normalize 再读回来，带宽开销翻倍；融合后一次遍历完成缩放与仿射变换，中间张量不再落地。判定阈值用带宽账来算：设单张图元素数为 <span class=\"formula\">$$N$$</span>、元素字节为 <span class=\"formula\">$$b$$</span>，未融合路径的显存流量约为 <span class=\"formula\">$$4Nb$$</span>（读原图、写中间、读中间、写结果），融合路径约为 <span class=\"formula\">$$2Nb$$</span>。当预处理吞吐已经接近显存带宽的某个比例时，这 2 倍差距直接体现为视觉塔的输入供给速率。测量方法是看 DALI 或 torchvision v2 的算子图里 resize 与 normalize 是否落在同一 kernel，或用 profiler 统计该阶段的 DRAM 读写字节数，与理论值 <span class=\"formula\">$$2Nb$$</span> 对比；实测显著高于理论值即说明存在未融合的中间落地。工程判断：只要工具链支持融合，就应默认融合，因为不融合的代价是确定的带宽浪费，而融合的代价仅是算子实现约束。具体例子：通道置换若单独作为一个 kernel，会再引入一次全张量读写，把它并入 normalize 的仿射步骤可省掉这一趟。</p>\n\n<h3 id=\"ap-preprocess-toolchain-sec-16\">十六 · 视频抽帧的串行阈值：解码段是否主导端到端延迟</h3>\n<p>视频侧的失败模式是解码与推理串行：CPU 解码一帧、拷贝到 GPU、推理、再解码下一帧，端到端延迟被解码段主导。判定阈值是解码时间占比 <span class=\"formula\">$$\\rho = T_{\\text{decode}} / T_{\\text{e2e}}$$</span>。当 <span class=\"formula\">$$\\rho$$</span> 明显偏高且时间线上解码与视觉塔前向不重叠时，串行判定成立。测量方法：分别记录解码调用耗时与视觉塔 kernel 耗时，检查两者在时间轴上是否有交集；无交集即串行。修复方向是把解码放到 GPU 侧（NVDEC 或 GPU JPEG 解码），使解码与视觉塔前向进入同一流或不同流形成流水，抽帧策略（时间采样间隔、每段取帧数）则决定送入视觉塔的帧总量。代价体现在延迟与吞吐两端：串行时延迟等于解码加推理之和，流水后延迟趋近两者最大值；吞吐则受解码器实例数与帧采样率共同约束。具体例子：一段需要按固定间隔采样的视频，若每帧都在 CPU 解码后再拷贝，解码段会稳定占据端到端时间的大头；改为 GPU 解码并把抽帧作为解码输出上的索引操作，解码与视觉塔即可重叠。</p>\n\n<h3 id=\"ap-preprocess-toolchain-sec-17\">十七 · 没有数字时的测量协议：三条可复现的观测线</h3>\n<p>材料未给出具体吞吐数字，因此本部分的工程结论必须落在“怎么测”上，而不是“调到多少”。三条观测线足以覆盖前述所有阈值。第一条是时间线分解：CUDA event 加主机单调时钟，产出 <span class=\"formula\">$$T_{\\text{host}}$$</span>、<span class=\"formula\">$$T_{\\text{h2d}}$$</span>、<span class=\"formula\">$$T_{\\text{tower}}$$</span> 三段占比，用于判定 <span class=\"formula\">$$r$$</span> 是否越线。第二条是形状序列：逐 batch 记录张量 shape 与桶键，统计形状变化频率与 padding 浪费比例，用于判定分桶对齐是否达标。第三条是显存流量：profiler 统计预处理阶段的 DRAM 读写字节，与 <span class=\"formula\">$$2Nb$$</span> 理论值对比，用于判定归一化是否融合。三条线都不依赖绝对吞吐数字，只依赖比值与计数，因此在任何硬件配置上可复现。工程判断：先跑第一条线确认主机侧不是瓶颈，再跑第二条线确认形状稳定，最后跑第三条线确认带宽没有浪费；顺序颠倒会把形状问题误判为带宽问题。</p>\n\n<h3 id=\"ap-preprocess-toolchain-sec-18\">十八 · 阈值之间的耦合：批大小放大主机侧缺口</h3>\n<p>上述阈值并非独立。批大小 <span class=\"formula\">$$B$$</span> 增大时，<span class=\"formula\">$$T_{\\text{tower}}$$</span> 近似线性增长，而 <span class=\"formula\">$$T_{\\text{host}}$$</span> 若仍在 CPU 侧逐样本处理，也近似线性增长，比值 <span class=\"formula\">$$r$$</span> 不会因批增大而自动改善；相反，主机侧的准备时间与 GPU 前向之间的空隙被放大，表现为批越大等待越明显。这正是“预处理留在 CPU 侧”成为最常见踩坑的原因。耦合关系给出一个排序判断：在 <span class=\"formula\">$$r$$</span> 未降到阈值以下之前，调批大小、调分桶粒度、调抽帧间隔都只是在放大或转移同一个缺口。具体机制上，把 resize 与 normalize 移入 CUDA kernel 后，<span class=\"formula\">$$T_{\\text{host}}$$</span> 从逐样本 CPU 计算变为一次 kernel launch，<span class=\"formula\">$$r$$</span> 的分母不变而分子骤降，批大小的调节才真正作用在视觉塔上。因此工程顺序是：先消除主机侧瓶颈，再谈分桶对齐，最后才进入批与抽帧策略的调参。</p>\n\n\n<h3 id=\"ap-preprocess-toolchain-sec-19\">十九 · 预处理管线的失效边界：从利用率阈值到分桶对齐的工程判据</h3>\n<p>预处理不是“能跑就行”的环节，它的边界由三个可测的失效点界定：主机侧吞吐是否成为视觉塔的上限、分桶后张量形状是否落在 kernel 的稳定编译域内、视频解码是否与推理串行。第一个判据是 GPU 利用率。材料给出的经验阈值是：预处理若留在 CPU 完成，单卡视觉塔常因主机侧瓶颈出现 GPU 利用率低于 50%。这个数字不是性能目标，而是诊断信号——它意味着视觉塔的 SM 有一半时间在等 H2D 拷贝与主机侧 resize/normalize 的完成，而不是在算卷积或 attention。工程上应把它当作红线：一旦稳态利用率跌破该值，优先怀疑数据管线而非模型本身。测量方法很直接：在推理循环中按固定窗口采样 <code>nvidia-smi</code> 的 utilization 或 DCGM 的 SM active 指标，同时记录每批的端到端时延与其中 H2D 拷贝耗时占比；若拷贝与主机侧处理合计超过批间隔的一半，即判定为管线瓶颈。更严格的测法是在视觉塔入口打时间戳、在 kernel 启动处再打一次，两者之差即“数据等待时间”，它与批大小正相关——批越大，等待越明显，因为主机侧要串行处理更多样本才能凑满一批。</p>\n<p>第二个失效点是动态分辨率分桶后的形状对齐。分桶的目的是把相近分辨率的样本归并成批以减少 padding 浪费，但若每批的实际张量尺寸都在变，cuDNN/cuBLAS 的启发式选择与 Triton/CUTLASS 的 kernel 特化就会反复触发重编译或退化到通用 kernel，代价是启动开销与显存碎片同时上升。判据是“批内形状方差”：把每个桶的目标尺寸固定为若干离散档位（例如按长边归入固定档、短边按比例缩放后 pad 到档位边界），使同一桶内所有批共享完全一致的 <code>[N, C, H, W]</code>。测量方法是统计单位时间内 kernel launch 次数与编译缓存命中率：若同一模型在稳定负载下 launch 次数随批数线性增长而非随批次数增长，说明形状在抖动。显存代价同样可测：用 <code>torch.cuda.memory_summary()</code> 或 CUDA 的 allocator 统计观察 reserved 与 allocated 的差额，碎片化表现为 reserved 持续抬升而 allocated 平稳。对齐到固定档位后，桶内 padding 比例上升会带来额外计算量，这笔账要算清楚：padding 浪费的算力与重编译/低效 launch 的损失之间存在权衡点，通常在小批量高并发场景下对齐更划算。</p>\n<div class=\"formula\">$$T_{\\text{batch}} = \\max\\left(T_{\\text{host}},\\ T_{\\text{h2d}} + T_{\\text{compute}}\\right),\\quad \\eta_{\\text{GPU}} = \\frac{T_{\\text{compute}}}{T_{\\text{batch}}}$$</div>\n<p>上式给出预处理的系统代价模型：批时延由主机侧处理时间与“拷贝加计算”两者取大，GPU 利用率就是计算时间占批时延的比例。当 <code>T_host</code> 主导时，η 随批增大而下降——这正是材料所述“批越大等待越明显”的量化表达。把 resize 与 normalize 迁到 CUDA kernel（DALI 或 torchvision v2）本质上是把 <code>T_host</code> 压到接近零，使批时延回到拷贝加计算的通道上；此时新的瓶颈转为 H2D 带宽，判据变为拷贝时间是否超过计算时间，测量上比较每批字节数与实测 PCIe/NVLink 有效带宽即可。视频侧还有第三个失效点：CPU 解码后再拷贝到 GPU 会使解码与推理串行，端到端延迟被解码段主导。判据是解码段占端到端时延的比例，测量方法是分别对解码、抽帧、推理三段打点；若解码占比超过一半，应改用 NVDEC 在 GPU 侧解码并让抽帧与推理形成流水，把串行段变成重叠段。这三条判据的共同点是都可现场测量、都不依赖厂商给出的吞吐数字，工程上应以它们作为上线前的验收门槛。</p>\n<table class=\"mini\"><thead><tr><th>失效点</th><th>判据与阈值</th><th>测量方法</th><th>系统代价</th></tr></thead><tbody><tr><td>主机侧预处理瓶颈</td><td>视觉塔 GPU 利用率低于 50%</td><td>DCGM/SM active 采样 + 入口时间戳差</td><td>批时延被主机侧主导，吞吐随批增大而恶化</td></tr><tr><td>分桶形状抖动</td><td>launch 次数随批数线性增长、编译缓存命中率下降</td><td>统计 kernel launch 与编译缓存、allocator reserved/allocated 差额</td><td>重编译开销与显存碎片，SM 有效占用下降</td></tr><tr><td>视频解码串行</td><td>解码段占端到端时延过半</td><td>解码/抽帧/推理三段分别打点</td><td>端到端延迟被解码段锁定，GPU 空转</td></tr></tbody></table>\n<p>把这三条判据落到工具选型上：DALI 的价值在于把解码、resize、normalize 串成一条 GPU 侧流水并自带批调度，适合视频与高并发图像；torchvision v2 的 CUDA kernel 路径适合与 PyTorch 训练/推理栈同构、需要灵活几何变换的场景，但其分桶与抽帧策略需自研补齐。无论选哪个，验收时都应先跑上述三项测量再谈吞吐，因为材料明确指出材料未给出具体吞吐数字——没有基线数字时，唯一可靠的工程判断来自对自身管线的失效点定位，而不是照搬他人的性能曲线。</p>\n<h3 id=\"ap-preprocess-toolchain-sec-20\">二十 · 踩坑清单：按代价排序的四类失败</h3>\n<p>预处理管线的问题不在于“能不能跑通”，而在于跑通之后在稳态下悄悄吃掉视觉塔的吞吐。把踩坑按系统代价排序，而不是按出现频率排序，才能决定先修哪个。第一类是主机侧瓶颈：resize 与 normalize 留在 CPU，视觉塔的 GEMM 在等 H2D 拷贝，单卡 GPU 利用率被压在低位，批越大等待窗口越长——因为 CPU 侧的处理时间随批线性增长，而 GPU 侧视觉塔的算力是固定的，二者的比值随批增大而恶化。第二类是形状抖动：动态分辨率分桶之后，同一桶内不同样本的实际尺寸没有 pad 到统一张量，每批形状变化触发 kernel 重编译或退化为低效 launch，代价表现为吞吐的锯齿状波动和显存碎片累积。第三类是解码串行：视频在 CPU 解码后再拷贝到 GPU，解码段与推理段无法重叠，端到端延迟由解码主导，视觉塔的算力在解码期间完全空转。第四类是隐性拷贝：解码在 GPU、resize 在 CPU、归一化又在 GPU，像素在两个内存域之间往返，带宽被无谓消耗，且每一步都引入同步点。</p>\n<p>这四类的共同结构是“管线中出现了非 CUDA kernel 的环节”。判断方法不需要 profiler 深度分析：看一段稳态推理的 timeline，若视觉塔 kernel 之间存在大于其自身执行时间的空隙，空隙的归属就是瓶颈所在。空隙出现在 H2D 拷贝前，是主机侧处理；空隙出现在 kernel launch 之间且形状频繁变化，是分桶未对齐；空隙出现在解码段之后，是解码未与推理重叠。</p>\n<div class=\"formula\">$$T_{\\text{batch}} = \\max\\left(T_{\\text{preprocess}}^{\\text{host}},\\ T_{\\text{vision}}^{\\text{GPU}}\\right) + T_{\\text{copy}}$$</div>\n<p>这个式子说明为什么“把预处理挪到 GPU”不是优化而是消除上限：只要 $T_{\\text{preprocess}}^{\\text{host}}$ 与 $T_{\\text{vision}}^{\\text{GPU}}$ 是串行相加的关系，主机侧再快也是在给总时间做加法；只有当两者进入同一 CUDA 流、由 GPU 侧 kernel 承担预处理，$T_{\\text{batch}}$ 才退化为视觉塔自身的执行时间。工程上的判断标准是：视觉塔利用率低于一半且批增大时利用率进一步下降，几乎必然指向主机侧环节。</p>\n\n<h3 id=\"ap-preprocess-toolchain-sec-21\">二十一 · 检查顺序：从形状到数值的自外向内</h3>\n<p>检查顺序应当遵循“先排除结构性错误，再排查数值错误”的原则，因为结构性错误的代价高且症状明显，数值错误的定位成本高但影响面窄。第一步查张量布局契约：视觉塔期望的输入是 NCHW 还是 NHWC、通道顺序是否已置换、dtype 是否为视觉塔 kernel 支持的精度。布局不匹配不会报错，只会让 kernel 走一条低效路径或触发隐式转置，代价是带宽翻倍。第二步查分桶对齐：确认每个桶的输出张量被 pad 到固定尺寸，且 pad 值不会污染后续的 mask 或位置编码；这一步的验证方法是打印连续若干批的 shape，若出现多于桶数的形状种类，说明对齐没做。第三步查解码路径：确认解码发生在 GPU（NVDEC 或 GPU JPEG 解码），且解码输出直接进入 CUDA 流的下一环，中间没有 D2H。第四步查归一化融合：mean/std 与通道置换是否与 resize 融合进同一个 kernel，还是拆成多个 pass 各自读写一遍显存。第五步才查数值：归一化的 mean/std 是否与视觉塔训练时一致、resize 插值方式是否与训练管线匹配、视频抽帧的时间戳采样是否与位置编码的时间维度对齐。</p>\n<p>把数值检查放在最后，是因为前三步的任何一处错误都会让数值检查失去意义——布局错了，数值再对也是错的张量。检查顺序的另一个含义是回滚顺序的反向：一旦上线后发现问题，先回滚最外层的形状契约变更，再回滚数值配方，因为形状变更的影响面覆盖整条管线，数值变更通常只影响单个模型的精度表现。</p>\n<table class=\"mini\"><thead><tr><th>检查步</th><th>对象</th><th>失败症状</th><th>系统代价</th></tr></thead><tbody><tr><td>1</td><td>张量布局与 dtype</td><td>无报错，吞吐偏低</td><td>带宽翻倍（隐式转置）</td></tr><tr><td>2</td><td>分桶 pad 对齐</td><td>shape 种类多于桶数</td><td>kernel 重编译、显存碎片</td></tr><tr><td>3</td><td>解码位置</td><td>解码段与推理串行</td><td>端到端延迟由解码主导</td></tr><tr><td>4</td><td>归一化融合</td><td>多个 pass 读写显存</td><td>额外显存带宽往返</td></tr><tr><td>5</td><td>数值配方一致性</td><td>精度漂移、无吞吐异常</td><td>精度损失，吞吐不变</td></tr></tbody></table>\n\n<h3 id=\"ap-preprocess-toolchain-sec-22\">二十二 · 分桶对齐的伪代码与代价核算</h3>\n<p>分桶对齐是第二类坑的核心，也是最容易被“看起来能跑”掩盖的一类。分桶的本意是把相近分辨率的样本归并成批，减少 pad 浪费；但如果桶内输出不做统一 pad，每个样本保持原始尺寸，那么批内张量无法拼成一个连续的 N 维张量，框架要么退化为逐样本 launch，要么在运行时做动态拼接——两者都把分桶的收益吃掉。正确做法是在桶定义时就固定输出尺寸，桶的上界即 pad 目标，超出上界的样本归入更高一档的桶。</p>\n<p>伪代码思路：桶表按分辨率上界排序，每个桶记录目标 H/W；样本按面积落入最小可行桶；桶内所有样本 resize 到目标尺寸（保持长宽比的样本做 letterbox pad，不保持的直接拉伸）；输出张量形状恒为桶的目标形状。这样同一桶的任意批都共享同一 shape，kernel 只需为每个桶编译一次。</p>\n<div class=\"formula\">$$W_{\\text{pad}} = \\frac{\\sum_i \\left(H_{\\text{tgt}}W_{\\text{tgt}} - H_iW_i\\right)}{\\sum_i H_{\\text{tgt}}W_{\\text{tgt}}}$$</div>\n<p>$W_{\\text{pad}}$ 是桶内的 pad 浪费比例，它决定了桶划分的粒度：桶太粗，$W_{\\text{pad}}$ 升高，视觉塔在 pad 像素上做无效计算；桶太细，桶数增多，每个桶的批变小，批利用率下降且 kernel 编译次数上升。代价核算的落点是显存：pad 后的张量按桶的目标尺寸分配，桶数越多，常驻的中间缓冲越多，显存碎片越容易累积。工程判断是桶数控制在个位数到十余个量级，且桶的目标尺寸取视觉塔支持的整数倍对齐值，避免非对齐尺寸触发额外的边界处理 kernel。</p>\n\n<h3 id=\"ap-preprocess-toolchain-sec-23\">二十三 · 视频抽帧：解码与推理的重叠方案</h3>\n<p>视频侧的坑与图像侧不同：图像的解码是一次性的，视频的解码是持续的，且解码吞吐与视觉塔吞吐往往不在同一量级。若在 CPU 解码再拷贝，解码段的时间直接加到端到端延迟上，视觉塔在解码期间空转；若解码在 GPU 但抽帧后的帧缓冲要回到主机做时间采样再传回 GPU，则引入两次跨域拷贝。正确形态是把解码、抽帧、resize、normalize 全部串在同一个 CUDA 流上，抽帧作为解码输出的视图选择，不产生额外拷贝。</p>\n<p>时间采样维度是视频特有的检查项：抽帧策略（固定间隔、关键帧优先、均匀采样）决定了进入视觉塔的帧数与时间跨度，而视觉塔的位置编码按固定帧数设计，采样策略与位置编码的时间维度不一致会导致帧序错位。代价表现为：解码段若不能与推理重叠，端到端延迟由解码主导，视觉塔利用率随视频长度增加而下降；抽帧若产生 D2H 往返，每帧引入一次同步，批处理退化为逐帧处理。检查方法是看 timeline 上解码 kernel 与视觉塔 kernel 是否在同一流上首尾相接，若中间出现主机同步点，即为拷贝坑。</p>\n\n<h3 id=\"ap-preprocess-toolchain-sec-24\">二十四 · 回滚方案：按影响面分层</h3>\n<p>回滚不是“把配置改回去”，而是按影响面分层设计，使得一次回滚只触动必要的那一层。最外层是形状契约：桶表、pad 目标尺寸、张量布局。这一层变更的影响面覆盖整条管线与视觉塔的 kernel 选择，回滚代价最高但最必要——一旦上线后发现形状抖动，必须先回滚桶表到上一版，恢复固定的 shape 集合，再排查新桶的划分逻辑。中间层是解码与融合策略：解码位置从 GPU 退回 CPU、归一化从融合退回多 pass，这类回滚影响吞吐但不影响精度，适合作为止血手段。最内层是数值配方：mean/std、插值方式、抽帧策略，影响精度不影响吞吐，回滚粒度最细。</p>\n<p>分层回滚的工程前提是每一层都有独立的版本标识与可切换开关，且开关切换不要求重启整条管线。判断回滚是否成功的标准不是“服务恢复”，而是“timeline 上的空隙消失”——因为很多形状与拷贝问题在低负载下不可见，只有稳态 timeline 才能确认回滚真正生效。回滚顺序与检查顺序相反：先回滚形状契约，再回滚解码与融合，最后才动数值配方；这个顺序保证每次回滚后症状的变化可归因到单一层，而不是多层同时变动导致无法定位。</p>\n<p>一个具体的工程判断：若上线后视觉塔利用率下降但精度无异常，回滚应止步于解码与融合层，不要动数值配方——数值配方与利用率无关，动它只会引入新的变量。反之若精度漂移而吞吐正常，直接跳到数值层，形状层无需触碰。这个判断把回滚从“全量还原”变成“定点还原”，是预处理管线可运维性的核心。</p>\n\n<h3 id=\"ap-preprocess-toolchain-sec-25\">二十五 · 预处理管线的失效边界与回滚判据</h3>\n<p>这条管线最脆弱的不是算子本身，而是<strong>形状契约</strong>。动态分辨率分桶把相近长宽比的样本归并成一批，但如果归并后不做 padding 对齐到固定 tile（如 16 像素或 32 像素的倍数），每批的张量形状都在变，视觉塔侧就会反复触发 kernel 重编译与低效 launch，显存分配器也会因尺寸抖动产生碎片。代价可直接量化：设批内样本数为 B、单样本像素为 H·W，对齐后单批显存占用为 <span class=\"formula\">$$M_{\\text{batch}} = B \\cdot \\lceil H/t \\rceil t \\cdot \\lceil W/t \\rceil t \\cdot C \\cdot b$$</span>，其中 t 为对齐粒度、b 为每元素字节数；不对齐时 M 随批波动，对齐后 M 稳定但引入最多 (t−1)/t 量级的像素浪费。工程判断是：对齐粒度取视觉塔 patch 尺寸的整数倍，宁可浪费几个百分点的算力，也不要让形状抖动穿透到编译层。</p>\n<p>第二个边界是解码与推理的串行耦合。视频抽帧若在 CPU 侧解码再拷到 GPU，解码段与视觉塔前向严格串行，端到端延迟被解码主导，且主机到设备的拷贝带宽成为硬上限。正确做法是把 NVDEC 或 GPU JPEG 解码放进同一 CUDA 流图，让抽帧、resize、normalize 与视觉塔的输入拷贝形成流水；此时端到端延迟近似为 <span class=\"formula\">$$L \\approx \\max(L_{\\text{decode}},\\, L_{\\text{pre}},\\, L_{\\text{tower}}) + L_{\\text{tail}}$$</span>，而非三者之和。代价是显存中要预留解码输出缓冲与预处理双缓冲，抽帧密度越高、分辨率越大，这部分驻留显存越不可忽略。</p>\n<p>检查顺序应按“先证伪瓶颈、再证伪形状、最后证伪精度”推进，避免一上来就调参：</p>\n<table class=\"mini\"><thead><tr><th>顺序</th><th>检查项</th><th>失败信号</th><th>回滚动作</th></tr></thead><tbody><tr><td>1</td><td>resize/normalize 是否在 CUDA kernel 内</td><td>视觉塔 GPU 利用率长期偏低、批越大等待越明显</td><td>切回 DALI 或 torchvision v2 的 GPU 路径，禁用 CPU 兜底</td></tr><tr><td>2</td><td>分桶后是否 padding 到固定 tile</td><td>kernel 重编译、launch 开销占比升高、显存碎片</td><td>关闭动态分桶，退回固定分辨率批</td></tr><tr><td>3</td><td>视频解码是否与推理同流</td><td>端到端延迟被解码段主导</td><td>降抽帧率或改 GPU 解码，恢复串行基线</td></tr><tr><td>4</td><td>归一化 mean/std 与通道置换是否融合</td><td>额外 kernel launch 与中间张量驻留</td><td>回退到分离算子，确认数值一致性后再融合</td></tr></tbody></table>\n<p>回滚方案必须预设“安全基线”：一条全 CPU 预处理加固定分辨率的保守路径，吞吐低但形状与数值完全确定。任何 GPU 侧优化上线前，先用小批对比两条路径的输出张量逐元素误差，确认归一化融合与插值方式变更未引入偏移；一旦线上出现利用率骤降或延迟抖动，直接切回基线而不是现场调参。这里的关键判断是：预处理优化的收益上限由视觉塔本身决定，若视觉塔已接近算力饱和，把 resize 搬上 GPU 只减少等待、不提升上限；反之若利用率被主机侧拖住，回滚到 CPU 路径只会让问题更糟，此时应保留 GPU 路径并只回滚分桶策略。</p>\n<h3 id=\"ap-preprocess-toolchain-sec-26\">二十六 · 上游依赖：预处理是视觉塔吞吐的下限</h3>\n<p>视觉预处理在全书里不是孤立模块，它处在“像素输入 → 视觉塔 → 跨模态融合”这条链的最前端，因此它的上游是数据源与解码器，下游直接决定视觉塔能拿到多密的张量。上游依赖有三类：容器与编码格式（H.264/H.265 视频流、JPEG/WebP 静态图）、存储与传输路径（对象存储拉取、主机内存页、PCIe 拷贝）、以及框架侧的样本加载器（DALI 的 pipeline、torchvision v2 的 <code>v2.Resize</code>/<code>v2.Normalize</code> 组合）。这三类中任何一环把像素留在 CPU 侧，视觉塔的 GPU 利用率就被钉死在低位——经验上 CPU 完成 resize 与 normalize 时，单卡视觉塔常出现 GPU 利用率低于 50% 的情况，批越大等待越明显。换句话说，预处理不是“把图变小”的辅助步骤，而是视觉塔吞吐的上限约束：上游解码与几何变换若不能全程在 CUDA kernel 内完成，下游再快的 tcgen05 MMA 也只能空转等数据。</p>\n<p>把这条依赖写成代价关系更清楚。设单批视觉 token 数为 <span class=\"inline-math\">N</span>，视觉塔每 token 的计算量为 <span class=\"inline-math\">c</span>，预处理每样本的主机侧耗时为 <span class=\"inline-math\">t_h</span>，则批时间近似为</p>\n<div class=\"formula\">$$T_{\\text{batch}} \\approx \\max\\left(\\frac{N c}{P_{\\text{gpu}}},\\; B \\cdot t_h\\right)$$</div>\n<p>其中 <span class=\"inline-math\">B</span> 为批内样本数，<span class=\"inline-math\">\\(P_{\\text{gpu}}\\)</span> 为视觉塔有效算力。当 <span class=\"inline-math\">\\(B \\cdot t_h\\)</span> 超过第一项时，整批被主机侧串行段主导，GPU 算力被浪费。工程判断很直接：把 <span class=\"inline-math\">t_h</span> 压到接近零（DALI 或 torchvision v2 的 CUDA kernel 路径），让第一项成为唯一瓶颈。具体例子：一路 1080p 视频按固定间隔抽帧送入视觉塔，若抽帧在 CPU 解码后再拷贝到 GPU，解码段与推理段串行，端到端延迟被解码段主导；改为 NVDEC 在 GPU 侧解码并直接进入 resize/normalize 管线，串行段消失，视觉塔的输入节奏由 GPU 解码吞吐决定而非主机线程调度。</p>\n\n<h3 id=\"ap-preprocess-toolchain-sec-27\">二十七 · 下游影响：张量布局与分桶形状决定融合侧成本</h3>\n<p>预处理的下游不只是视觉塔本身，还包括跨模态注意力的输入契约。预处理输出的张量布局（NCHW 还是 NHWC、通道置换是否融合进 normalize、padding 是否对齐）会一路传导到视觉塔的 patch embedding 与后续融合算子。若归一化与通道置换在预处理阶段融合为单个 kernel，视觉塔拿到的就是已就绪的布局，省掉一次额外的 permute 与一次显存往返；若留在 CPU 侧分步做，则每批多出数次主机-设备拷贝，带宽开销直接叠加在融合前的关键路径上。这里的系统代价是显存带宽与 kernel launch 次数：布局转换每多一步，就多一次全张量读写，对 动态分辨率 的大张量尤其明显。</p>\n<p>分桶调度的下游影响更隐蔽。动态分辨率分桶把同分辨率样本归并成批，本意是减少 padding 浪费、提高视觉塔的算力利用率；但若分桶后不同分辨率的张量未做 padding 对齐到固定尺寸，每批形状都在变，触发 kernel 重编译与显存碎片。重编译的代价不是一次性的：它把批调度从稳态推回冷启动，连续批处理（continuous batching）的流水被打断，吞吐出现锯齿。伪代码思路如下：</p>\n<ul>\n<li>按 (H, W) 的桶键归并样本，桶内取最大 H、W 作为对齐目标；</li>\n<li>对每个样本做 pad 到桶尺寸，pad 区域在归一化时置零并在注意力 mask 中屏蔽；</li>\n<li>桶尺寸集合预先固定为有限几档（例如按视觉塔支持的 patch 网格整数倍），使编译缓存命中；</li>\n<li>桶内批满或超时即发射，避免为凑齐同分辨率样本而制造批饥饿。</li>\n</ul>\n<p>这段逻辑与多模态批调度条目共享“桶”的概念，但本片段的角度是：桶的尺寸集合必须在预处理阶段就固定下来，否则下游融合侧要为形状抖动付出重编译代价。具体例子：同一批里混入 224×224 与 448×448 两种输入，若不做对齐，视觉塔每批要跑两种 kernel 配置；对齐到统一桶后，融合侧的跨模态注意力只需处理一种序列长度，显存碎片也随之收敛。</p>\n\n<h3 id=\"ap-preprocess-toolchain-sec-28\">二十八 · 与量化配方的耦合：预处理决定 NVFP4/FP8 输入的动态范围</h3>\n<p>预处理与多模态量化配方之间存在一条容易被忽略的耦合：归一化的 mean/std 与裁剪策略直接决定送入视觉塔的张量动态范围，而 NVFP4/FP8 的量化粒度（per-tensor 还是 per-block scale）对这个范围敏感。若预处理把像素归一化到过窄的区间，低精度格式的有效位被浪费；若裁剪过激，量化后的激活分布出现长尾，融合侧的 scale 需要更细的 block 粒度才能保住精度。这里的系统代价是精度损失与额外的 scale 计算：per-block scale 的粒度越细，量化 kernel 的元数据开销越大，显存里要多存一份 scale 张量。</p>\n<p>工程上的做法是把归一化参数当作量化配方的一部分来管理，而不是预处理侧的随手常数。具体机制：在 DALI pipeline 里把 mean/std 作为可配置算子参数，与量化配方的校准统计同源；torchvision v2 侧则用 <code>v2.Normalize</code> 的融合路径保证 mean/std 与通道置换在同一个 CUDA kernel 内完成，避免中间张量落地显存。这样视觉塔的输入分布在校准阶段与推理阶段一致，NVFP4 的 per-block scale 不会因预处理漂移而失配。具体例子：同一视觉塔在 FP8 与 NVFP4 两套配方下，若预处理归一化参数不同源，校准得到的激活范围与实际推理输入错位，融合侧注意力输出的误差被放大；统一参数后，两套配方的精度差异只来自格式本身而非预处理。</p>\n\n<h3 id=\"ap-preprocess-toolchain-sec-29\">二十九 · 与分离式预填/解码的位置关系：预处理属于预填侧的前置段</h3>\n<p>在分离式预填/解码（disaggregated prefill/decode）架构里，视觉预处理天然归属预填侧：像素到张量的转换、视觉塔前向、跨模态注意力的 KV 写入都发生在预填节点，解码节点只消费已写入的 KV。这意味着预处理的吞吐直接决定预填节点的服务能力，而预填节点往往是长序列、大 batch 的形态，对主机侧瓶颈最敏感。若预处理在 CPU 完成，预填节点的视觉塔 GPU 利用率被拖低，整个分离式架构的预填-解码配比失衡——解码侧等不到足够的 KV，SLO 的首 token 延迟被拉长。</p>\n<p>把预处理放进预填侧的工程含义是资源隔离：预填节点的 CPU 线程应全部让给调度与网络（NIXL 传输），像素处理交给 GPU 解码与 CUDA kernel。系统代价体现在预填节点的显存占用上：预处理阶段的中间张量（解码后的原始帧、resize 中间结果）若未及时释放，会与视觉塔的激活、KV 写入缓冲争抢显存，尤其在 GB200 NVL72 这类多 GPU 共享机箱的场景里，显存压力会传导到整个 NVL72 域。具体例子：视频抽帧在预填节点用 NVDEC 解码，抽出的帧直接进入 GPU resize/normalize，中间帧缓冲用固定大小的环形池复用，避免每帧新分配；这样预填节点的显存曲线平稳，KV 写入不被预处理挤占。</p>\n\n<h3 id=\"ap-preprocess-toolchain-sec-30\">三十 · 在全书中的位置：预处理是七领域推理形态的共同底座</h3>\n<p>放到全书结构里看，预处理工具链是七个领域推理形态的共同底座，但每个领域对它的要求不同：图像理解类要求动态分辨率分桶与高质量 resize；视频类要求抽帧策略与时间采样维度；文档与 OCR 类要求裁剪与去畸变；多模态检索类要求大批量吞吐与稳定的归一化。这些差异不改变工具链的骨架（解码 → 几何变换 → 归一化 → 分桶），只改变各阶段的参数与桶尺寸集合。因此本条目在全书中的位置是“横切条目”：它不定义某个领域的推理形态，而是为每个领域提供像素到张量的统一入口，其他条目（视觉 token 压缩、跨模态注意力、多模态量化配方）都假定这个入口已经就绪。</p>\n<p>这也解释了为什么预处理的上游依赖与下游影响必须成对管理。上游的解码路径决定 <span class=\"inline-math\">t_h</span> 能否压到零，下游的张量布局与桶形状决定融合侧的 kernel 配置能否稳定命中。两者之间用一个可检查的接口契约连接：速查表里那几列（是否 GPU 解码、插值方式、归一化是否融合、分桶支持、抽帧策略、接口张量布局）就是契约的字段。工程判断落在最后一步：上线前把这份契约与视觉塔的实际输入形状逐项核对，任何一项不匹配都会在批调度层放大成吞吐锯齿或显存碎片，而不是在预处理层表现为一个孤立的慢 kernel。</p>\n\n<h3 id=\"ap-preprocess-toolchain-sec-31\">三十一 · 预处理管线的边界：它决定视觉塔能跑多快，也决定它何时失效</h3>\n<p>这条管线在全书中的位置是“喂料段”：它不产生任何 token，却决定了视觉塔的 GPU 利用率上限。上游依赖解码类算子（NVDEC/GPU JPEG）与几何变换类算子（resize/crop/pad）能否全程留在设备侧；下游则直接约束视觉塔的输入契约——张量布局、分辨率集合、批内形状一致性。工程判断很直接：只要有一环回落到主机侧，视觉塔就会进入“等数据”状态，单卡 GPU 利用率被压到一半以下，且批越大等待越明显，因为主机侧吞吐不随批增大而线性扩展。因此这条管线的正确性标准不是“结果对不对”，而是“像素到张量之间有没有一次 H2D 往返”。</p>\n<p>失效条件可以写成一条可判定的不等式。设单批视觉塔计算耗时为 <span>T_c</span>，预处理在主机侧耗时为 <span>T_h</span>，则流水线稳态吞吐受限于 <span>max(T_c, T_h)</span>，GPU 利用率近似为：</p>\n<div class=\"formula\">$$U \\approx \\frac{T_c}{\\max(T_c,\\,T_h)}$$</div>\n<p>当 <span>T_h &gt; T_c</span> 时 <span>U &lt; 1</span> 且随批增大进一步恶化——这正是 CPU 侧 resize 与 normalize 成为瓶颈的定量形态。第二个失效点是分桶后形状未对齐：不同分辨率张量若不做 padding 对齐到固定尺寸集合，每批形状变化会触发 kernel 重编译与显存碎片，代价表现为启动抖动与显存池碎片化，而非单纯变慢。第三个失效点在视频侧：CPU 解码后再拷贝到 GPU，解码与推理串行，端到端延迟由解码段主导，抽帧策略再优也无法挽回。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>触发条件</th><th>系统代价</th></tr></thead><tbody><tr><td>主机侧瓶颈</td><td>resize/normalize 留在 CPU</td><td>视觉塔利用率低于 50%，批越大越明显</td></tr><tr><td>形状漂移</td><td>分桶未 padding 对齐</td><td>kernel 重编译、显存碎片、启动抖动</td></tr><tr><td>解码串行</td><td>CPU 解码后 H2D 拷贝</td><td>端到端延迟被解码段主导</td></tr></tbody></table>\n<p>边界之外还有一层：这条管线与显存/KV cache 条目共享“批内形状一致性”这一约束，与并行通信条目共享“视觉塔输入布局必须与张量并行切分对齐”这一接口。举例来说，动态分辨率分桶若把一批样本归并到若干固定档位，视觉塔的 kernel launch 次数与显存峰值就变得可预测；反之，若每批形状随机，容量规划中的显存上界就失去意义。因此本条目在全书中的角色是“把不确定性挡在视觉塔之外”：分桶调度类算子的职责不是提速单张图，而是把形状空间压缩成有限集合，让下游的 tcgen05 路径与批调度器能按固定契约排布。</p>\n<p>工程上应把这条管线当作有明确失效域的子系统来验收：先确认解码与几何变换均在 CUDA kernel 内完成，再确认分桶档位是有限且对齐的，最后确认视频抽帧与推理重叠而非串行。三者任一不满足，视觉塔的吞吐上限就由主机侧或形状抖动决定，而非由 Blackwell 的算力决定。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-preprocess-toolchain\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>覆盖解码、缩放、裁剪、归一化、动态分辨率分桶与视频抽帧的GPU侧管线，推荐使用DALI或torchvision…</td></tr><tr><td>关键点</td><td>见正文</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-preprocess-toolchain · 共 5 个片段</p>\n"},{"id":"ap-visual-token-tools","title":"视觉token压缩工具","summary":"列出可插拔的token合并与重采样实现，包括基于相似度的merge、快速池化下采样与可学习Q-Former，需支持在视觉塔输出后、projector之前以融合kernel完成，减少中间张量显存往返。","kind":"工具","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-1\">一 · 条目边界：压缩发生在视觉塔与projector之间</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-2\">二 · 分类维度一：压缩方式决定并行形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-3\">三 · 分类维度二：可学习性与压缩比动态性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-4\">四 · 分类维度三：顺序语义与变分辨率适配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-5\">五 · 与相邻概念的切分线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-6\">六 · 选型判断落在融合与并行上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-7\">七 · 速查表的列语义与口径约定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-8\">八 · 速查表主体</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-9\">九 · 阈值：压缩比、分辨率档位与批内并行</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-10\">十 · 显存与带宽代价的核算口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-11\">十一 · 接口约定与顺序语义的核对项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-12\">十二 · 用表做容量规划的三个动作</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-13\">十三 · 速查表的失效边界：什么情况下这张表会误导你</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-14\">十四 · 阈值不是常数：压缩比的分段判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-15\">十五 · 融合kernel的带宽账：中间张量往返次数是硬指标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-16\">十六 · 相似度merge的数据依赖阈值：批内并行度的量化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-17\">十七 · 变分辨率适配的测量口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-18\">十八 · 压缩比动态化的判据与回归口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-19\">十九 · 与projector接口约定的测量落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-20\">二十 · 压缩模块的失效边界与系统代价核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-21\">二十一 · 坑一：压缩模块独立起 kernel，中间张量反复落盘</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-22\">二十二 · 坑二：相似度 merge 的数据依赖打断批内并行</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-23\">二十三 · 坑三：固定压缩比与变分辨率输入的错配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-24\">二十四 · 检查顺序：从显存流量到语义正确性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-25\">二十五 · 回滚方案：把压缩做成可旁路的开关</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-26\">二十六 · 融合边界、失效条件与回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-27\">二十七 · 上游依赖：视觉塔的输出契约决定压缩工具的形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-28\">二十八 · 下游影响：压缩比与token顺序语义如何传导到projector与LLM</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-29\">二十九 · 与量化配方的耦合：压缩发生在量化之前还是之后</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-30\">三十 · 与分离式预填、批调度的关系：压缩改变的是阶段边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-31\">三十一 · 在全书中的位置：窄通道上的可插拔决策点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-token-tools-sec-32\">三十二 · 压缩工具的边界：失效条件、系统代价与全书坐标</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-visual-token-tools\"><svg style=\"max-width:525px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 525.1 319\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"443.1\" height=\"83.0\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"53.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"57.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：视觉token压缩工具</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">列出可插拔的token合并与重采样实现，包括基于相似度的merge、快</text><text x=\"75.0\" y=\"78.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">速池化下…</text><line x1=\"82.0\" y1=\"97.0\" x2=\"82.0\" y2=\"114.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 113.0 L 86.5 113.0 L 82.0 121.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"121.0\" width=\"443.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"143.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"147.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"148.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><line x1=\"82.0\" y1=\"167.9\" x2=\"82.0\" y2=\"184.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 183.9 L 86.5 183.9 L 82.0 191.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"191.9\" width=\"443.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"214.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"218.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"219.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"238.7\" x2=\"82.0\" y2=\"255.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 254.8 L 86.5 254.8 L 82.0 262.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"262.8\" width=\"443.1\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"285.2\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"289.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"290.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-visual-token-tools-sec-1\">一 · 条目边界：压缩发生在视觉塔与projector之间</h3>\n<p>视觉token压缩工具在本卷中的准确定义是：一类可插拔的、作用于视觉塔（ViT/ConvNeXt 类主干）输出张量与多模态 projector 之间的 token 合并与重采样实现。它的输入是形状为 <span class=\"inline-code\">[B, N_v, D_v]</span> 的视觉塔末层输出（<span class=\"inline-code\">N_v</span> 为视觉 token 数，<span class=\"inline-code\">D_v</span> 为视觉塔隐藏维），输出是压缩后的 <span class=\"inline-code\">[B, N_c, D_v]</span>，随后才交给 projector 做维度映射到语言模型隐藏维。这个位置约束是条目定义的核心：压缩工具不改变视觉塔内部结构，也不接管 projector 的映射职责，它只在这两者之间的窄缝里做一件事——把 <span class=\"inline-code\">N_v</span> 降下来。</p>\n<p>把位置钉死，才能把它与相邻概念区分开。视觉编码器术语表讨论的是塔内部的 patch embedding、窗口注意力、位置编码插值；多模态量化配方讨论的是权重与激活的数值格式；视觉塔显存溢出讨论的是激活峰值与分块策略。压缩工具既不碰权重精度，也不改塔的层结构，它的全部杠杆是序列长度。因此判断一个实现是否属于本条目，只需问三个问题：它是否在塔外、projector 前？它是否输出更短的 token 序列？它是否以可插拔方式替换而不改动上下游？三者皆 yes 才算条目内。</p>\n<p>工程上这个窄缝的代价非常具体。视觉塔输出到 projector 之间的中间张量在未融合时会反复落盘显存：以 <span class=\"inline-code\">B=8</span>、<span class=\"inline-code\">N_v</span> 为数千、<span class=\"inline-code\">D_v</span> 为千级、BF16 计，单次中间张量就是数十 MB 量级，压缩若单独起 kernel，读一次、写一次、再被 projector 读一次，显存带宽被三次往返吃掉。这正是条目说明强调“以融合 kernel 完成、减少中间张量显存往返”的原因——融合不是优化项，而是条目的准入门槛。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-2\">二 · 分类维度一：压缩方式决定并行形态</h3>\n<p>第一维是压缩方式，条目给定三类：基于相似度的 merge、快速池化下采样、可学习 Q-Former（注意力重采样）。三者的差别不在压缩比，而在数据依赖结构。相似度 merge 需要在序列内做两两或近邻比较，把相似 token 对合并为一个；池化下采样在固定网格上做局部聚合，token 之间无跨位置依赖；Q-Former 用一组可学习 query 对视觉 token 做交叉注意力，把 <span class=\"inline-code\">N_v</span> 压到 query 数 <span class=\"inline-code\">N_q</span>。</p>\n<div class=\"formula\">$$\\text{merge: } \\mathbf{h}'_{i} = \\frac{1}{|S_i|}\\sum_{j\\in S_i}\\mathbf{h}_j,\\quad S_i=\\{j:\\ \\mathrm{sim}(\\mathbf{h}_i,\\mathbf{h}_j)&gt;\\tau\\}$$</div>\n<p>上式里集合 <span class=\"inline-code\">S_i</span> 的构造依赖整条序列的相似度矩阵，这就是代价来源：变长批内每条样本的 <span class=\"inline-code\">N_v</span> 不同，相似度矩阵尺寸不同，无法拼成一个规整的批维度做并行，实际实现往往退化为按样本循环或填充到最大长度，后者浪费算力、前者破坏批内并行。池化则天然规整：把 <span class=\"inline-code\">N_v</span> 个 token 视作二维网格做 <span class=\"inline-code\">k×k</span> 平均或步长卷积，输出长度 <span class=\"inline-code\">N_v/k^2</span>，无跨样本依赖，可与视觉塔尾层或 projector 首层融合进同一 kernel。Q-Former 的并行性介于两者之间：交叉注意力对 query 维可并行，但对 <span class=\"inline-code\">N_v</span> 的注意力仍是长序列 softmax，显存占用随 <span class=\"inline-code\">N_v</span> 线性增长。</p>\n<p>具体例子：一个 8 卡推理服务同时接收 4 张 1024×1024 与 4 张 384×384 的图像，前者 <span class=\"inline-code\">N_v</span> 远大于后者。若用相似度 merge，批内必须按最大 <span class=\"inline-code\">N_v</span> 填充，小图样本的算力被浪费在填充位上，且相似度矩阵的显存峰值由最大样本决定；若用池化，两条路径各自按自己的网格下采样，批维度保持规整，延迟由最大样本主导但无填充浪费。这就是“压缩方式”作为第一分类维度的工程含义：它先决定能不能并行，再决定压得多好。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-3\">三 · 分类维度二：可学习性与压缩比动态性</h3>\n<p>第二维是是否可学习。池化下采样无可学习参数，压缩规则由网格尺寸固定；相似度 merge 通常也无可学习参数（阈值 <span class=\"inline-code\">τ</span> 是超参），但可引入可学习的打分头；Q-Former 的 query 与交叉注意力权重全部可学习。可学习性直接对应两件事：一是是否需要额外的权重加载与显存驻留，二是压缩行为是否随输入内容自适应。Q-Former 的 query 数 <span class=\"inline-code\">N_q</span> 是固定输出长度，这带来一个隐性好处——projector 的输入形状恒定，下游 kernel 可预编译、批调度可预估显存；代价是无论图像信息量多少都压到同一长度，高分辨率细节多时信息损失固定发生。</p>\n<p>第三维是压缩比是否动态。固定压缩比（如固定 <span class=\"inline-code\">k</span> 或固定 <span class=\"inline-code\">N_q</span>）实现简单、形状可预测，但条目列出的失败模式明确指出：压缩比按固定值设定时，高分辨率输入下丢失过多细节，低分辨率下又几乎不压缩。动态压缩比则依据输入内容（如 token 相似度分布、边缘密度、文本区域占比）决定保留多少 token，输出长度 <span class=\"inline-code\">N_c</span> 随样本变化。动态比的代价是批内形状不一致，需要 padding 或 varlen 支持，且下游 projector 与语言模型必须接受变长视觉前缀——这会把压力传导到多模态批调度层，属于跨条目接口问题，此处只指出边界。</p>\n<table class=\"mini\"><thead><tr><th>实现名称</th><th>压缩类型</th><th>压缩比范围</th><th>可学习参数</th><th>融合kernel</th><th>插入位置</th><th>中间张量影响</th><th>projector接口</th></tr></thead><tbody><tr><td>相似度 merge</td><td>相似度合并</td><td>材料未给定</td><td>否（阈值超参）</td><td>难，需序列依赖</td><td>塔输出后</td><td>需存相似度矩阵</td><td>变长输入</td></tr><tr><td>池化下采样</td><td>池化</td><td>由网格尺寸决定</td><td>否</td><td>易，可融合</td><td>塔输出后</td><td>可原地缩减</td><td>规整短序列</td></tr><tr><td>Q-Former</td><td>注意力重采样</td><td>由 query 数决定</td><td>是</td><td>部分可融合</td><td>塔输出后</td><td>注意力中间量大</td><td>定长输入</td></tr></tbody></table>\n<p>上表即条目要求的速查表骨架，列的含义本身就是分类维度的落地：压缩类型对应第一维，可学习参数对应第二维，压缩比范围对应第三维，融合 kernel 与中间张量影响对应工程门槛，插入位置与 projector 接口约定则把条目与相邻概念切开。填表时“材料未给定”必须如实标注，不得臆造压缩比数字。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-4\">四 · 分类维度三：顺序语义与变分辨率适配</h3>\n<p>第四维是是否改变 token 顺序语义。池化在固定网格上聚合，输出 token 与图像空间位置的对应关系保持规整，位置编码可继续按网格索引；相似度 merge 把不同位置的 token 合并，输出序列不再与原始空间网格一一对应，若下游 projector 或语言模型依赖绝对位置编码，语义就被破坏；Q-Former 的输出 query 本身没有空间顺序含义，位置信息只能通过 query 的隐式学习承载。这一维决定压缩工具能否与依赖空间结构的任务共存——检测、OCR、文档版面理解对位置语义敏感，而整图分类不敏感。</p>\n<p>第五维是对变分辨率输入的适配方式。视觉塔通常把不同分辨率图像切成不同数量的 patch，<span class=\"inline-code\">N_v</span> 随分辨率变化。池化适配最直接：按当前网格尺寸选 <span class=\"inline-code\">k</span>，输出长度随输入缩放；相似度 merge 需在变长序列上构造依赖，条目已指出这是破坏批内并行的主因；Q-Former 用固定 query 数吸收任意 <span class=\"inline-code\">N_v</span>，适配性最好但计算量随 <span class=\"inline-code\">N_v</span> 增长。适配方式的代价可用一个简单关系表达：</p>\n<div class=\"formula\">$$N_c = f(N_v),\\quad \\text{显存峰值} \\propto B\\cdot \\max_i N_{v,i}\\cdot D_v$$</div>\n<p>即批内显存峰值由最大样本的 <span class=\"inline-code\">N_v</span> 决定，而非平均。这意味着变分辨率混合批下，压缩工具若不能逐样本缩减，显存就被最大图钉死。具体例子：文档理解服务里一页 A4 扫描件与一张缩略图同批，扫描件的 <span class=\"inline-code\">N_v</span> 远高于缩略图，池化可在融合 kernel 中把扫描件压到目标网格、缩略图按比例少压，批内峰值随之下降；相似度 merge 则因填充把缩略图也拉到扫描件长度，峰值不降反升。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-5\">五 · 与相邻概念的切分线</h3>\n<p>与视觉 token 压缩术语的切分：术语条目给的是词汇表与定义，本条目给的是可插拔实现的分类与选型维度，前者回答“叫什么”，后者回答“怎么分、怎么插”。与跨模态注意力术语的切分：Q-Former 内部确实用交叉注意力，但那是压缩工具的一种实现机制，跨模态注意力条目讨论的是语言模型侧视觉前缀如何参与注意力，二者作用层不同。与多模态量化配方的切分：量化改的是数值格式与位宽，压缩改的是序列长度，两者可叠加但代价来源不同——量化省带宽与显存容量，压缩省的是注意力计算量与 KV 前缀长度。</p>\n<p>与视觉塔显存溢出的切分最需要说清：显存溢出条目处理的是塔内部激活峰值与分块重计算，压缩工具处理的是塔输出之后的序列缩减。二者的交点在中间张量：若压缩单独起 kernel，塔输出先落盘、压缩再读写、projector 再读，显存往返次数增加，反而加重溢出风险；若压缩与塔尾层或 projector 首层融合，中间张量不落盘，溢出压力下降。这就是条目说明把“融合 kernel”写成关键工程要求的原因，也是本条目区别于纯算法描述的地方。</p>\n<p>与多模态推理框架的切分：框架负责调度、批处理、显存池；压缩工具是框架可插拔的一个算子实现，框架通过接口约定调用它。条目要求的“与 projector 的接口约定”正是这条切分线的落点：压缩工具输出什么形状、是否变长、是否需要位置索引，必须与 projector 的输入契约对齐，否则框架层要做额外拷贝，融合失效。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-6\">六 · 选型判断落在融合与并行上</h3>\n<p>把五个维度收束成一个工程判断：在 Blackwell 上，压缩工具的价值不由压缩比单独决定，而由“能否在塔输出到 projector 之间以融合 kernel 完成、且不破坏批内并行”决定。池化下采样在规整网格上天然满足这两条，是混合分辨率批的默认起点；Q-Former 以固定 query 数换取形状可预测，适合下游需要定长视觉前缀的场景，代价是注意力中间量的显存；相似度 merge 在单样本、定长、离线场景可用，在变长在线批里因序列内数据依赖而延迟高于池化，条目已将其列为第二失败模式。</p>\n<p>具体到实现检查，一个压缩工具是否合格，看它在融合路径上是否做到：输入直接来自塔尾层输出缓冲、输出直接写入 projector 输入缓冲、中间不产生额外的全局张量。以 BF16、<span class=\"inline-code\">D_v</span> 千级、批内最大 <span class=\"inline-code\">N_v</span> 数千计，一次未融合的中间张量往返就是数十 MB 量级的显存读写，在带宽受限的 decode 阶段这是可观测的延迟项。因此选型时先问融合，再问压缩比，最后才问可学习性——顺序反了，就会掉进“压缩模块单独起 kernel 导致中间张量反复读写显存”这个最常见踩坑里。</p>\n<h3 id=\"ap-visual-token-tools-sec-7\">七 · 速查表的列语义与口径约定</h3>\n<p>这张表不是选型推荐，而是把每个可插拔实现的可观测行为固定成字段，让工程侧在接入时不必反复读源码。八列的口径必须事先约定，否则同一行数据在不同团队手里会得出相反结论。<strong>实现名称</strong>填模块级标识（如 <code>merge_sim</code>、<code>pool_fast</code>、<code>qformer_lite</code>），不填论文名；<strong>压缩类型</strong>只允许三值：相似度合并、池化、注意力重采样；<strong>压缩比范围</strong>写成闭区间并注明是“相对视觉塔输出 token 数”的比值，而非绝对 token 数；<strong>是否可学习参数</strong>填布尔，指该模块是否携带随推理加载的权重，池化类通常为否；<strong>是否支持融合kernel</strong>填布尔，指压缩算子能否与视觉塔尾部归一化/转置、projector 首层线性在同一个 kernel 内完成；<strong>插入位置</strong>恒为“视觉塔输出之后、projector 之前”，该列实际记录的是插入点在数据流中的精确锚点（塔输出张量名、layout、dtype）；<strong>对显存中间张量的影响</strong>用“落盘次数”与“峰值占用相对塔输出”两个量描述；<strong>与projector的接口约定</strong>记录 token 顺序语义是否保持、是否附带有效长度向量、是否需要 projector 侧感知压缩比。</p>\n<p>口径上有一条硬约束：压缩比的定义必须绑定输入分辨率档位。同一实现，在 448×448 与 1024×1024 输入下若按固定 token 数压缩，其“压缩比”数值完全不同，表中必须写成“随输入自适应”或给出区间，禁止填单一常数。另一个口径是延迟归属：压缩模块的耗时是否计入视觉塔 kernel 时间，取决于融合与否，表中“是否支持融合kernel”为真时，其延迟应归入塔侧流水，为假时单独成段，这会直接改变容量规划里的阶段划分。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-8\">八 · 速查表主体</h3>\n<p>下表按压缩类型分组，字段值只使用条目给定的事实范围，未给出具体数字处一律以定性口径填写，工程侧接入时以实测替换。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>实现名称</th><th>压缩类型</th><th>压缩比范围</th><th>可学习参数</th><th>融合kernel</th><th>插入位置</th><th>中间张量影响</th><th>projector接口约定</th></tr>\n</thead>\n<tbody>\n<tr><td>merge_sim</td><td>相似度合并</td><td>随输入自适应，区间待实测</td><td>否</td><td>需定制，默认否</td><td>塔输出后、projector前</td><td>非融合时中间张量多次落盘，带宽成瓶颈</td><td>保持token顺序语义，需附有效长度</td></tr>\n<tr><td>pool_fast</td><td>池化下采样</td><td>固定倍率，随分辨率档位换算</td><td>否</td><td>是（可与塔尾/线性首层融合）</td><td>同上</td><td>融合后中间张量不落盘，峰值显著下降</td><td>顺序语义不变，无需长度向量</td></tr>\n<tr><td>qformer_lite</td><td>注意力重采样</td><td>查询数决定，固定输出token数</td><td>是</td><td>部分可融合，跨注意力段独立</td><td>同上</td><td>查询与键值中间张量占用随查询数线性增长</td><td>输出定长，projector需按定长配置</td></tr>\n</tbody>\n</table>\n<p>三行的差异集中在两处。其一是<strong>数据依赖</strong>：merge_sim 的压缩结果依赖序列内两两相似度，输出长度随内容变化，因此必须向 projector 传递有效长度；pool_fast 与 qformer_lite 的输出长度由配置决定，接口更简单。其二是<strong>融合可行性</strong>：池化是逐窗口的局部归约，天然可与塔输出的 layout 变换、projector 首层线性拼进同一 kernel；相似度合并需要跨 token 归约，融合窗口受限于片上缓存容量；Q-Former 的跨注意力在查询维度上可并行，但键值投影通常仍需单独一段。</p>\n<div class=\"formula\">$$T_{\\text{stage}} = T_{\\text{tower}} + T_{\\text{compress}} + T_{\\text{proj}},\\quad T_{\\text{compress}}^{\\text{fused}} \\approx 0,\\quad T_{\\text{compress}}^{\\text{split}} = \\frac{2 \\cdot S_{\\text{mid}}}{B_{\\text{HBM}}}$$</div>\n<p>式中 $S_{\\text{mid}}$ 为塔输出到 projector 之间中间张量的字节数，系数 2 表示写回与再读入各一次，$B_{\\text{HBM}}$ 为有效显存带宽。该式给出速查表“中间张量影响”列的定量含义：非融合路径的压缩代价不是算力，而是两次全量搬运；融合路径把这项代价压到接近零，代价转移到 kernel 实现的复杂度与寄存器压力上。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-9\">九 · 阈值：压缩比、分辨率档位与批内并行</h3>\n<p>压缩比阈值不能按单一常数设定，这是条目明确指出的失败模式：固定压缩比在高分辨率输入下丢失过多细节，在低分辨率下又几乎不压缩。工程上应把压缩比表达为分辨率档位的函数，档位由预处理阶段给出（预处理链路本身不在本表范围内，此处只约定接口）。判定规则是：当输入像素数跨过档位边界时，压缩比随之切换，且切换点必须与视觉塔的 patch 网格对齐，避免出现非整数窗口导致的补齐开销。</p>\n<p>第二个阈值是<strong>批内并行度</strong>。相似度合并依赖序列内两两比较，变长批下每个样本的有效长度不同，归约规模不一致，实际延迟高于池化方案——这是条目列出的第二失败模式。可操作的判据是：当批内长度方差超过设定比例时，merge_sim 应退化为按最大长度补齐或拆批，否则其延迟被最长样本拖住。表中“压缩比范围”列写“随输入自适应”正是为了提示这一退化路径，而不是暗示它总能自适应地快。</p>\n<p>第三个阈值是<strong>融合窗口容量</strong>。融合 kernel 一次能处理的中间张量块受片上存储限制，池化窗口越大、每线程负责的 token 越多，寄存器与共享内存压力越高。当压缩比要求的下采样倍率超过融合窗口可容纳的归约跨度时，必须拆成两段 kernel，此时表中“是否支持融合kernel”应从“是”改为“分段融合”，中间张量落盘次数由 0 变为 1，延迟按上式回算。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-10\">十 · 显存与带宽代价的核算口径</h3>\n<p>中间张量的峰值占用应按“塔输出形状 × dtype 字节数”计，而非按压缩后形状计。原因在于压缩发生在塔输出之后，塔输出本身必须先完整存在（除非塔尾与压缩融合到同一 kernel 的写出阶段）。以 qformer_lite 为例，其查询向量与键值投影的中间结果随查询数线性增长，若查询数设为定长输出 token 数，则这部分占用与输入分辨率无关，但键值侧仍随塔输出长度增长，形成“输入越长、键值缓存越大”的隐性成本。表中该行“中间张量影响”写“随查询数线性增长”只描述了查询侧，键值侧的增长需在接入时另行核算。</p>\n<p>带宽口径上，非融合路径的代价可用下式估算单位 token 的搬运字节：</p>\n<div class=\"formula\">$$\\text{Bytes}_{\\text{per-token}} = d \\cdot b \\cdot 2,\\quad \\text{BW}_{\\text{need}} = \\frac{N_{\\text{tok}} \\cdot \\text{Bytes}_{\\text{per-token}}}{\\text{latency budget}}$$</div>\n<p>$d$ 为塔输出隐藏维，$b$ 为 dtype 字节数，$N_{\\text{tok}}$ 为批内塔输出 token 总数。当该需求逼近可用带宽时，压缩模块就从“省显存”变成“吃带宽”，这正是条目所述“带宽成为瓶颈”的量化形态。判断依据不是压缩比大小，而是 $S_{\\text{mid}}$ 与压缩后张量之比：若压缩后张量远小于中间张量，融合的收益最大；若两者接近，融合收益有限，应优先考虑把压缩逻辑并入 projector 首层而不是单独成 kernel。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-11\">十一 · 接口约定与顺序语义的核对项</h3>\n<p>接入前需逐项核对表中“与projector的接口约定”列，共四项。第一，<strong>顺序语义</strong>：池化与相似度合并是否改变 token 的排列顺序，若改变，projector 的位置编码或后续跨模态注意力的对齐假设必须同步调整；条目将“是否改变token顺序语义”列为分类维度，表中虽未单列该列，但接口约定列已隐含此判定。第二，<strong>有效长度</strong>：变长输出必须随张量附带长度向量，否则 projector 的批内掩码无法构造，注意力会跨样本泄漏。第三，<strong>dtype 与 layout</strong>：融合 kernel 要求塔输出与 projector 首层期望的 layout 一致，若塔输出为通道优先而 projector 期望序列优先，融合点必须包含转置，转置本身在片上完成才不引入额外落盘。第四，<strong>压缩比可见性</strong>：projector 是否需要知道压缩比以调整其内部维度，池化类通常不需要，Q-Former 类因输出定长而需要按定长配置权重。</p>\n<p>这四项中任何一项不满足，都会把“可插拔”退化为“需改 projector”。工程判断是：优先选接口约定最少的那一行——池化类在四项上全部满足且无需长度向量，是接入成本最低的基线；相似度合并仅在需要内容自适应压缩比时才值得承担长度向量与批内并行的代价；Q-Former 类适用于输出必须定长的下游结构，其代价是键值侧显存随输入增长。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-12\">十二 · 用表做容量规划的三个动作</h3>\n<p>第一个动作是把表中“是否支持融合kernel”为否的行单独标记为带宽敏感项，在容量规划里为其预留中间张量的峰值显存与对应带宽，而不是按压缩后形状估算。第二个动作是按分辨率档位为每行填入实测压缩比，形成“档位 × 实现”的二维表，替换本表中的定性区间；档位切换点必须与预处理输出对齐，否则压缩比在运行时会跳变，导致批内样本的有效长度分布不可控。第三个动作是把批内长度方差纳入调度判据：当方差超过阈值时，merge_sim 行应被调度器降级或拆批，这一判据应写入批调度配置而非压缩模块内部，因为压缩模块看不到批的全局形态。</p>\n<p>三个动作的共同前提是：压缩模块的延迟必须能被归入塔侧或 projector 侧的流水段，否则容量规划无法把它的耗时摊到正确的阶段预算里。融合为真时归塔侧，分段融合时按落盘次数折算为独立段，非融合时独立成段——这条归属规则比压缩比本身更影响端到端延迟的预测精度，也是本表在接入评审中最先被追问的一列。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-13\">十三 · 速查表的失效边界：什么情况下这张表会误导你</h3>\n<p>速查表把每个实现压成一行，但行的成立有前提：压缩必须与projector在同一融合kernel内完成。一旦拆成两个kernel，视觉塔输出到projector之间的中间张量就要在显存里往返，此时表里“压缩比范围”和“是否可学习”都失去意义——带宽成为唯一瓶颈。判断口径很简单：看实现是否声明融合kernel支持；若否，该行只适用于离线预处理或显存充裕、批极小的场景。代价上，一次中间张量落盘再读回，等于把视觉塔输出按<em>写+读</em>两次计入显存带宽，压缩比越高、省下的张量越小，但这两次往返是固定开销，压缩比低于某阈值时净收益为负。</p>\n<div class=\"formula\">$$T_{\\text{eff}} = \\frac{T_{\\text{tower}} + T_{\\text{fused}}}{\\max(1,\\; r_{\\text{comp}})} + \\frac{2S_{\\text{vis}}}{B_{\\text{mem}}}$$</div>\n<p>式中$S_{\\text{vis}}$为视觉塔输出张量字节数，$B_{\\text{mem}}$为有效显存带宽，第二项即未融合时的往返代价。它不随压缩比缩小，所以表里“对显存中间张量的影响”一列必须按“是否融合”分两套口径读，否则会把池化方案误判为省显存。</p>\n<p>第二类失效来自相似度merge：它依赖序列内两两比较，变长批下token间存在数据依赖，批内并行被打断，实际延迟高于池化。速查表若只标“压缩类型=相似度合并”而不标“变长批适配方式”，读者会按定长吞吐估算容量，结果在真实变长负载下SLO失守。第三类是固定压缩比：高分辨率输入下细节丢失过多，低分辨率下几乎不压缩，表里“压缩比范围”应读作“需按输入分辨率动态选择”的提示，而非可直接填死的常数。字段口径上，“插入位置”必须写明视觉塔输出后、projector前；“与projector的接口约定”要写清压缩后张量的形状与顺序语义是否改变，因为改变token顺序语义的实现不能与依赖位置编码的projector直接对接。</p>\n<table class=\"mini\"><thead><tr><th>字段</th><th>可照用的阈值/口径</th><th>失效条件</th></tr></thead><tbody><tr><td>是否支持融合kernel</td><td>必须为是，否则不计入在线路径</td><td>拆kernel时带宽主导</td></tr><tr><td>变长批适配</td><td>相似度merge需声明并行化方式</td><td>两两比较破坏批内并行</td></tr><tr><td>压缩比</td><td>按分辨率动态，不填固定值</td><td>高分辨率丢细节、低分辨率不压缩</td></tr></tbody></table>\n<h3 id=\"ap-visual-token-tools-sec-14\">十四 · 阈值不是常数：压缩比的分段判据</h3>\n<p>视觉token压缩工具在工程上最先被问到的永远是“压缩比设多少”。材料没有给出可直接套用的压缩比数字，因此正确的做法不是找一个全局常数，而是把压缩比写成输入分辨率的函数，并在视觉塔输出处按 token 网格规模分段。设视觉塔输出序列长度为 <span class=\"inline-math\">N</span>、目标序列长度为 <span class=\"inline-math\">M</span>、压缩比为 <span class=\"inline-math\">r = N/M</span>，工程上真正需要约束的是压缩后的信息密度而非 <span class=\"inline-math\">r</span> 本身：</p>\n<div class=\"formula\">$$r_{\\text{safe}}(N)=\\min\\left(r_{\\max},\\ \\frac{N}{M_{\\min}}\\right),\\quad M_{\\min}=\\alpha\\cdot\\frac{H_{\\text{img}}W_{\\text{img}}}{P^{2}}$$</div>\n<p>其中 <span class=\"inline-math\">P</span> 是视觉塔的 patch 边长，<span class=\"inline-math\">\\(\\alpha\\)</span> 是“每个 patch 至少保留多少比例的可分辨细节”的经验系数，<span class=\"inline-math\">\\(r_{\\max}\\)</span> 是压缩模块自身能稳定工作的上限。这个式子的意义在于：高分辨率输入下 <span class=\"inline-math\">N</span> 很大，若仍用固定 <span class=\"inline-math\">r</span>，<span class=\"inline-math\">M</span> 会大到让 projector 与 LLM 前缀都变长，等于没压；低分辨率下 <span class=\"inline-math\">N</span> 本来就小，固定 <span class=\"inline-math\">r</span> 会把仅有的细节压没。分段判据的具体形态是：当 <span class=\"inline-math\">N</span> 低于某个下限时直接跳过压缩（<span class=\"inline-math\">r=1</span>），当 <span class=\"inline-math\">N</span> 超过上限时把 <span class=\"inline-math\">r</span> 抬到 <span class=\"inline-math\">\\(r_{\\max}\\)</span>，中间区间按上式线性取值。代价面很清楚：压缩比抬高会降低视觉塔输出到 projector 之间的中间张量显存占用与后续 attention 的 KV 长度，但会牺牲细粒度定位类任务的精度；跳过压缩则相反。一个具体例子：同一批请求里混入 448×448 与 1024×1024 两种图像，若统一用固定压缩比，前者几乎不压缩、后者细节丢失，分段判据让两者都落在可接受区间，且批内 <span class=\"inline-math\">M</span> 的方差被压小，有利于连续批处理的 token 预算估算。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-15\">十五 · 融合kernel的带宽账：中间张量往返次数是硬指标</h3>\n<p>材料把“以融合kernel完成压缩、减少视觉塔输出到 projector 之间的中间张量显存往返”列为关键工程要求，这意味着阈值应当直接写成显存往返次数的上限，而不是写成抽象的“性能优化”。设视觉塔输出张量形状为 <span class=\"inline-math\">[B, N, D]</span>，压缩模块若单独起 kernel，典型路径是：视觉塔写出 <span class=\"inline-math\">[B,N,D]</span> → 压缩 kernel 读入 → 写出 <span class=\"inline-math\">[B,M,D]</span> → projector 读入，中间张量至少两次落盘显存。融合后压缩与 projector 的读入合并，往返次数从 2 降到 1（或把压缩写回与 projector 读入合并为一次流式读写）。带宽代价可写成：</p>\n<div class=\"formula\">$$T_{\\text{bw}}=\\frac{c\\cdot B\\cdot N\\cdot D\\cdot s}{W_{\\text{HBM}}}$$</div>\n<p>其中 <span class=\"inline-math\">s</span> 是元素字节数（NVFP4/FP8 下显著小于 BF16），<span class=\"inline-math\">\\(W_{\\text{HBM}}\\)</span> 是 HBM 带宽，<span class=\"inline-math\">c</span> 是往返次数。工程阈值因此是：<span class=\"inline-math\">c</span> 必须为 1；若压缩模块无法融合，则必须证明 <span class=\"inline-math\">\\(T_{\\text{bw}}\\)</span> 相对该层 MMA 时间可忽略，否则压缩收益会被带宽吃掉。测量方法不是看端到端吞吐，而是用 Nsight 类工具统计该段 kernel 的 DRAM 读写字节数，除以理论带宽得到下界，再与实测 kernel 时间比对；两者差距大说明存在额外往返或未对齐访问。具体例子：一个基于相似度的 merge 若在变长批上单独起 kernel，除了两次往返，还会因序列内两两比较引入数据依赖，使批内并行退化——这正是材料列出的第二常见踩坑，其延迟在实测中高于快速池化下采样，尽管后者的压缩质量未必更好。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-16\">十六 · 相似度merge的数据依赖阈值：批内并行度的量化</h3>\n<p>相似度 merge 的代价不在 FLOPs 而在依赖结构。设批内第 <span class=\"inline-math\">i</span> 个样本的序列长度为 <span class=\"inline-math\">N_i</span>，merge 需要在该序列内做两两相似度比较或贪心配对，其关键路径长度随 <span class=\"inline-math\">N_i</span> 增长，而池化下采样的关键路径是常数。批内并行度可量化为：</p>\n<div class=\"formula\">$$\\text{par}=\\frac{\\sum_i N_i}{\\max_i N_i}\\quad\\text{（理想）},\\qquad \\text{par}_{\\text{merge}}\\approx\\frac{\\sum_i N_i}{\\sum_i f(N_i)}$$</div>\n<p>其中 <span class=\"inline-math\">f(N_i)</span> 是 merge 在单样本上的串行步数。工程阈值是：当批内长度方差大（长短样本混批）时，<span class=\"inline-math\">\\(\\text{par}_{\\text{merge}}\\)</span> 会明显低于理想值，此时应把相似度 merge 换成池化，或按长度分桶后再 merge。测量方法是构造固定 batch size、改变长度分布的微基准，记录 kernel 占用率与 SM 活跃度随长度方差的变化曲线；阈值取占用率跌破可接受水平的那一点。代价面：merge 的精度收益在细粒度检索类任务上可见，但延迟代价在混批场景下由最长样本决定，等于让短样本为空转买单。具体例子：一批 8 个请求，长度从 256 到 4096 token 不等，merge 的串行步数由 4096 那条决定，短样本的 SM 大部分时间在等依赖，此时池化方案的实测延迟更低且方差更小。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-17\">十七 · 变分辨率适配的测量口径</h3>\n<p>压缩工具对变分辨率输入的适配方式直接决定阈值怎么测。材料把“对变分辨率输入的适配方式”列为分类维度，工程上必须区分两种口径：按 token 网格对齐的池化（要求 <span class=\"ilnnline-math\">N</span> 可被池化窗口整除，否则需要 padding 或边界处理）与按序列长度自适应的 merge（对任意 <span class=\"inline-math\">N</span> 都成立但依赖结构更复杂）。测量时必须固定像素级输入尺寸集合，而不是固定 token 数，因为不同视觉塔的 patch 划分会让同一像素尺寸产生不同 <span class=\"inline-math\">N</span>。阈值写法：池化窗口 <span class=\"inline-math\">k</span> 应满足 <span class=\"inline-math\">\\(N \\bmod k = 0\\)</span> 的比例在目标输入分布中足够高，否则 padding 带来的无效 token 会稀释压缩收益；自适应 merge 则应约束单样本串行步数上限。代价面：padding 会增加中间张量有效元素数，抬高 <span class=\"inline-math\">\\(T_{\\text{bw}}\\)</span>；自适应 merge 则抬高关键路径。具体例子：图像与视频帧混跑时，视频帧的 token 网格常与图像不同，若池化窗口只对图像对齐，视频帧会走 padding 分支，实测显存往返字节数上升，抵消了压缩带来的显存节省。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-18\">十八 · 压缩比动态化的判据与回归口径</h3>\n<p>材料指出“压缩比按固定值设定，高分辨率输入下丢失过多细节，低分辨率下又几乎不压缩”是失败模式之一，因此动态压缩比不是可选项而是工程要求。动态化的判据应写成可测量的量：以压缩前后视觉特征在检索/定位类探针上的保真度为约束，以中间张量显存与 projector 读入带宽为目标，做带约束的取值。工程上更实用的做法是把动态压缩比实现为按 <span class=\"inline-math\">N</span> 分段的查表，段边界由第一节的 <span class=\"inline-math\">\\(r_{\\text{safe}}\\)</span> 决定，查表本身在融合 kernel 内完成，不引入额外 kernel。回归口径必须包含三项：一是固定输入分布下的端到端延迟与显存峰值；二是压缩段 kernel 的 DRAM 字节数与理论下界之比；三是混批长度方差扫描下的占用率曲线。三项中任一项退化即判定压缩配置不可上线。具体例子：同一模型在低分辨率批量场景下把 <span class=\"inline-math\">r</span> 设为 1（跳过压缩）反而更快，因为压缩 kernel 的固定开销超过了节省的 projector 读入；而在高分辨率场景下 <span class=\"inline-math\">r</span> 抬到 <span class=\"inline-math\">\\(r_{\\max}\\)</span> 才让显存峰值回到预算内。这说明阈值必须按场景分段，单一固定值在两个极端都会失效。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-19\">十九 · 与projector接口约定的测量落点</h3>\n<p>压缩模块与 projector 的接口约定决定了测量落点在哪里。材料把“与 projector 的接口约定”列为速查表列之一，工程上要明确三件事：压缩后张量的 dtype 是否与 projector 输入一致（NVFP4/FP8 下不一致会引入额外转换 kernel）、布局是否连续（非连续会触发额外的 stride 访问）、以及压缩是否改变 token 顺序语义（改变顺序会让 projector 之后的位置编码或注意力掩码失效）。测量落点因此是压缩 kernel 的出口处：统计该点的 dtype 转换次数、非连续访问比例、以及顺序语义是否被标记。阈值写法：dtype 转换次数必须为 0（压缩直接在目标 dtype 上完成），非连续访问比例必须为 0（压缩输出按 projector 期望的布局写出）。代价面：任何一次额外转换都是一次显存往返，直接叠加到 <span class=\"inline-math\">c</span> 上；顺序语义改变则会让下游 attention 的掩码构造多一步重排。具体例子：一个 Q-Former 式重采样若输出顺序与视觉塔 token 顺序不同，projector 之后必须插入重排 kernel，这等于把融合 kernel 的收益又还回去；正确的工程判断是把顺序语义作为接口约定的一部分写死，压缩模块内部负责在写出时保持顺序，而不是让下游补救。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-20\">二十 · 压缩模块的失效边界与系统代价核算</h3>\n<p>这套工具真正的工程风险不在算法本身，而在“压缩模块被当成独立算子”这件事上。视觉塔输出到 projector 之间若插入一个单独起 kernel 的压缩步骤，中间张量就要经历一次写显存、一次读显存，再被 projector 读一次；融合 kernel 的意义正是把这三趟访存压成一趟。代价可以直接算：设视觉塔输出形状为 <span class=\"inline-math\">[B, N, D]</span>，压缩后 token 数为 <span class=\"inline-math\">N'</span>，则非融合路径的额外中间张量流量约为</p>\n<div class=\"formula\">$$M_{\\text{extra}} \\approx 2 \\cdot B \\cdot N \\cdot D \\cdot s$$</div>\n<p>其中 <span class=\"inline-math\">s</span> 为元素字节数（BF16 为 2）。在 NVL72 单卡 HBM 带宽受限的 decode 侧，这笔流量会直接体现在首 token 延迟上，而不是稳态吞吐上——因为压缩只在 prefill 阶段发生一次。判断是否需要融合 kernel 的阈值很朴素：当 <span class=\"inline-math\">\\(M_{\\text{extra}}\\)</span> 与 projector 权重读取量同量级时，非融合实现的首 token 延迟就会被带宽而非算力支配。测量方法是把压缩 kernel 单独摘出来做一次空跑（只读写不计算），与融合版本对比端到端 TTFT，差值即为访存代价的上界。</p>\n<p>第二类失效来自相似度 merge 的数据依赖。基于相似度的合并需要在序列内做两两比较或 top-k 选择，变长批下每个样本的有效长度不同，批内并行度被序列长度绑死，短序列的 SM 空转、长序列成为关键路径。这与池化下采样形成鲜明对比：池化只依赖固定的空间邻接关系，token 顺序语义不变，可直接按 <span class=\"inline-math\">[B, N, D]</span> 的规则步长切分，批内并行度与 <span class=\"inline-math\">N</span> 解耦。工程判断是：在线服务里若批内序列长度方差大，优先池化；相似度 merge 只在离线或长度齐整的场景用。测量方法是对同一批混合长度请求分别跑两种实现，记录 p99 延迟而非均值——均值会被短序列稀释。</p>\n<p>第三类失效是固定压缩比与变分辨率输入的不匹配。压缩比写死为常数时，高分辨率输入下 <span class=\"inline-math\">N</span> 大、细节被过度丢弃，低分辨率下 <span class=\"inline-math\">N</span> 本就小、几乎不压缩，等于白付一次 kernel 开销。可学习 Q-Former 类重采样能把压缩比做成动态的（按查询槽位数与输入长度比自适应），但代价是引入可学习参数、增加一次注意力计算，且其输出 token 顺序语义与原始 patch 顺序不再一一对应，projector 接口必须约定好位置编码的重映射方式。下表给出三类实现在这几个维度上的取舍。</p>\n<table class=\"mini\"><thead><tr><th>实现类型</th><th>压缩比</th><th>可学习</th><th>批内并行</th><th>顺序语义</th><th>主要代价</th></tr></thead><tbody><tr><td>相似度 merge</td><td>固定或按阈值</td><td>否</td><td>受序列长度约束</td><td>改变</td><td>变长批延迟高</td></tr><tr><td>池化下采样</td><td>固定步长</td><td>否</td><td>与 N 解耦</td><td>保持</td><td>高分辨率细节损失</td></tr><tr><td>Q-Former 重采样</td><td>动态（槽位数）</td><td>是</td><td>受槽位数约束</td><td>改变</td><td>额外注意力算力与参数</td></tr></tbody></table>\n<p>阈值设定没有通用数字，材料未给出具体压缩比，因此正确做法是把阈值当成可测的量：以 projector 输入维度和下游任务精度回退为约束，扫描压缩比直到精度掉出可接受区间，取该点前一档作为默认值；同时用融合 kernel 的空跑基线确认访存代价未成为 TTFT 主项。若压缩比必须动态，则把“槽位数 / 输入 token 数”作为控制量暴露给调度层，让批调度按输入分辨率分组，避免同一批内压缩比抖动导致 kernel 形状反复重编译。</p>\n<h3 id=\"ap-visual-token-tools-sec-21\">二十一 · 坑一：压缩模块独立起 kernel，中间张量反复落盘</h3>\n<p>这是视觉 token 压缩工具落地时最高频的失败模式，也是最容易被性能剖析掩盖的一种。典型形态是：视觉塔（ViT 主干）输出形状为 <code>[B, N, D]</code> 的 token 张量，压缩模块被写成一个独立的 CUDA kernel 或独立的算子调用，压缩结果再交给 projector（MLP 或线性投影）。表面上每一步都“正确”，但视觉塔输出到 projector 之间多出了至少两次完整的显存往返：一次写回压缩前的 token 张量，一次读入压缩模块，再一次写出压缩后的张量供 projector 读取。</p>\n<p>代价可以直接算出来。设视觉塔输出 token 数为 N、隐藏维 D、批内图像数 B、数据类型字节数 s（FP8 为 1，BF16 为 2），则单次落盘与回读的显存流量为：</p>\n<div class=\"formula\">$$T_{\\text{traffic}} = 2 \\cdot B \\cdot N \\cdot D \\cdot s \\quad \\text{(写一次 + 读一次)}$$</div>\n<p>以 B=8、N=4096、D=1024、BF16 为例，单次往返即 128 MiB 量级；若压缩模块内部还有中间缓冲（相似度矩阵、排序索引），流量再翻倍。在 HBM 带宽被 projector 与后续 attention 共享的推理流水里，这部分流量不产生任何有用计算，纯粹是带宽税。工程判断标准很简单：用 Nsight 看视觉塔输出到 projector 之间是否存在额外的 global memory 读写峰值，若压缩 kernel 的 dram__bytes 与理论最小值之比超过 1.2，就说明中间张量没有被融合掉。</p>\n<p>正确做法是把压缩作为视觉塔输出 epilogue 的一部分，或至少与 projector 的输入准备合并为单一融合 kernel：压缩在寄存器/共享内存中完成，压缩后的 token 直接写进 projector 的输入缓冲，压缩前的完整张量根本不落盘。检查清单第一条因此是“压缩 kernel 是否与视觉塔输出或 projector 输入共享同一段 global memory 生命周期”。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-22\">二十二 · 坑二：相似度 merge 的数据依赖打断批内并行</h3>\n<p>基于相似度的 merge（如 token merging 一类的两两相似度配对合并）在定长、单图场景下表现良好，但一旦进入变长批（不同图像分辨率、不同视频帧 token 数），就会暴露结构性缺陷。其核心是序列内两两比较：对每个 token 计算与候选集的相似度，再按相似度排序做配对。这个过程的计算图依赖序列长度 N，且配对结果依赖前一轮合并的结果，形成串行链。</p>\n<p>伪代码层面的依赖关系是：</p>\n<div class=\"formula\">$$\\text{merge}^{(k+1)} = \\text{pair}\\big(\\text{sort}(\\text{sim}(X^{(k)}))\\big), \\quad X^{(k+1)} = \\text{merge}^{(k+1)}(X^{(k)})$$</div>\n<p>每一轮 k 都必须等上一轮写回完成，且批内不同样本的 N 不同，无法用统一的 tile 划分覆盖。工程后果是：GPU 占用率被最长的那个样本拖住，短样本的 SM 空转；批越大，尾部效应越明显。相比之下，快速池化下采样（固定窗口、固定步长）没有跨 token 依赖，可以直接按输出 token 索引并行，延迟可预测。因此在连续批处理场景下，相似度 merge 的实际端到端延迟经常高于池化方案，尽管其单图质量指标更好。</p>\n<p>检查顺序上，这一条应排在融合 kernel 检查之后：先确认压缩没有额外落盘，再确认压缩算法在目标批形态下是否可并行。若业务必须用相似度 merge，缓解手段是限制批内 N 的方差（按分辨率分桶）、把 merge 轮数压到固定小值、或对短序列走池化分支——但这会引入分支发散，需要在 kernel 内用统一 tile 掩码处理。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-23\">二十三 · 坑三：固定压缩比与变分辨率输入的错配</h3>\n<p>压缩比按固定值设定是第三个高频坑。视觉塔输出的 token 数随输入分辨率线性增长（patch 数），若压缩比固定为 r，则高分辨率输入下保留的 token 数仍然很大，压缩“看起来生效”但绝对量没降下来；低分辨率输入下压缩过度，细节被抹掉，下游任务精度下降。更隐蔽的是，固定压缩比让显存预算与延迟预算无法随输入自适应，容量规划只能按最坏情况留余量。</p>\n<p>动态压缩比的判定应基于视觉塔输出的实际 token 数与下游 projector 的输入预算：</p>\n<div class=\"formula\">$$r_{\\text{target}} = \\max\\left(1,\\ \\frac{N_{\\text{vis}}}{N_{\\text{budget}}}\\right), \\quad N_{\\text{out}} = \\left\\lceil \\frac{N_{\\text{vis}}}{r_{\\text{target}}} \\right\\rceil$$</div>\n<p>其中 <code>N_budget</code> 由 projector 的吞吐与 KV cache 预算共同决定。代价体现在两个方向：压缩比过低时，projector 与跨模态注意力的输入 token 数居高不下，prefill 延迟与 KV 显存同步上升；压缩比过高时，视觉细节丢失不可逆，且池化/merge 的 kernel 在极小 N 下并行度不足，SM 利用率反而下降。检查清单要求记录每个分辨率桶下的实际 <code>N_out</code> 分布，而不是只记录配置里的标称压缩比。</p>\n<p>具体例子：同一套压缩工具在 448×448 与 1024×1024 两种输入下，若固定 r=4，前者输出 token 数可能已低于 projector 的高效工作区间，后者输出仍超出预算。工程上应把压缩比做成按桶配置或按 <code>N_vis</code> 运行时计算，并在 kernel 内保证不同 r 的分支走同一套 tile 掩码，避免批内分支发散。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-24\">二十四 · 检查顺序：从显存流量到语义正确性</h3>\n<p>上线前的检查不应按“功能—性能—精度”的直觉顺序，而应按失败代价从高到低排。建议顺序如下，每一步都有明确的判据而非定性感觉。</p>\n<ul>\n<li><b>第一步，显存流量与融合性。</b>确认视觉塔输出到 projector 之间没有压缩前的完整张量落盘；用 dram 读写计数与理论最小值比对。这是带宽税的直接来源，也是最容易修复的一项。</li>\n<li><b>第二步，批形态下的并行度。</b>用目标业务的真实批（含变长、含混合分辨率）测压缩 kernel 的 SM 占用与尾部延迟；若相似度 merge 的串行链成为瓶颈，记录最长样本与最短样本的延迟差。</li>\n<li><b>第三步，压缩比与分辨率桶的匹配。</b>逐桶记录 <code>N_vis</code>、<code>N_out</code>、projector 输入预算，确认没有桶出现“压缩了但没降下来”或“压过头”。</li>\n<li><b>第四步，token 顺序语义。</b>确认压缩是否改变了 token 的空间顺序语义（池化下采样会重排，merge 会打乱索引），以及 projector 与跨模态注意力是否依赖原始顺序；若依赖，需要位置编码或索引映射同步调整。</li>\n<li><b>第五步，可学习参数与权重加载。</b>Q-Former 类可学习重采样引入额外权重，需确认其精度（FP8/BF16）与视觉塔、projector 的精度策略一致，避免在融合 kernel 中发生隐式升精度导致带宽回涨。</li>\n</ul>\n<p>这个顺序的逻辑是：前两步决定系统级代价（带宽、延迟），后三步决定正确性与可维护性。把语义检查放在最后不是因为不重要，而是因为前三步的修复成本更低、收益更直接；语义问题一旦确认，往往需要改接口约定而非改 kernel。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-25\">二十五 · 回滚方案：把压缩做成可旁路的开关</h3>\n<p>压缩工具的回滚不应是“改代码重新部署”，而应是运行时可切换的旁路。工程上要求压缩模块在接口层保持与 projector 的契约不变：无论压缩开启与否，projector 收到的都是 <code>[B, N_out, D]</code> 的张量，差异只在 <code>N_out</code> 与是否经过压缩 kernel。这样回滚只需把压缩比设为 1（或直接跳过压缩 kernel），projector 与下游无需改动。</p>\n<p>回滚触发条件应绑定可观测指标而非人工判断：压缩 kernel 的 dram 流量超出理论值阈值、批尾部延迟超过 SLO、或某分辨率桶下 <code>N_out</code> 低于下限。触发后自动切到旁路路径，同时保留压缩路径的开关状态供后续灰度。代价是旁路路径下显存与延迟回到未压缩水平，容量规划必须按旁路状态留出余量——这也是为什么压缩比与批调度预算要联动配置，而不是各自独立设定。</p>\n<p>具体机制上，融合 kernel 内部用一个 <code>compress_enable</code> 标志位选择写回压缩后 token 还是原样透传，两条路径共享同一段输出缓冲，避免回滚时重新分配显存。检查清单最后一项因此是“旁路路径是否与压缩路径共享缓冲与接口，回滚是否为零拷贝切换”。这一条决定了压缩工具能否在灰度期安全地开关，而不是每次调整都变成一次带风险的发布。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-26\">二十六 · 融合边界、失效条件与回滚判据</h3>\n<p>这套工具的设计前提只有一个：压缩必须在视觉塔输出到 projector 之间以融合 kernel 一次完成，中间张量不落显存。一旦这个前提被破坏，方案就从“省带宽”退化为“多一次全量读写”。设视觉塔输出形状为 <span class=\"formula\">$$[B, N, D]$$</span>，压缩后为 <span class=\"formula\">$$[B, M, D]$$</span>，若压缩单独起 kernel，则额外显存往返量为 <span class=\"formula\">$$2 \\cdot B \\cdot N \\cdot D \\cdot s$$</span>（s 为元素字节数），读一次写一次；在 N 很大、D 为千级、批内序列变长的预填阶段，这一项直接压在 HBM 带宽上，而不是算力上。典型例子是相似度 merge：它需要序列内两两相似度，天然产生 <span class=\"formula\">$$O(N^2)$$</span> 的中间分数矩阵，即使最终只保留 M 个 token，分数矩阵本身也往往比压缩结果大一个量级，融合 kernel 若不把打分与合并放进同一趟 tile 循环，就会把这个矩阵实体化到显存。检查顺序应是：先确认压缩与 projector 是否同 kernel 或同 fused region，再确认打分矩阵是否被物化，最后才看压缩比是否合理——顺序反了会在错误的层面上调参。</p>\n<p>失效条件集中在三类。其一是变长批下的数据依赖：相似度 merge 的配对关系依赖同一条序列内部的比较结果，批内不同长度样本无法共享同一并行切分，实际延迟反而高于池化下采样，后者对每个 token 独立作用、无跨 token 依赖，在连续批处理下可直接按 token 数切块。其二是固定压缩比：高分辨率输入下固定压到同一 M 会丢掉过多细节，低分辨率下又几乎不压缩，等于白付 kernel 开销；压缩比应按输入分辨率或 token 数动态给出，并把动态规则写进接口约定，而不是留给调用方猜。其三是与 projector 的接口错位：merge 若改变 token 顺序语义（例如按相似度重排），projector 之后的位置编码或注意力掩码必须同步，否则数值正确但语义错位，这类错误不会报错，只会让下游指标缓慢劣化。</p>\n<table class=\"mini\"><thead><tr><th>检查项</th><th>通过判据</th><th>不通过的代价</th></tr></thead><tbody><tr><td>压缩与 projector 同 kernel</td><td>中间张量无显存实体化</td><td>带宽瓶颈，预填延迟上升</td></tr><tr><td>打分矩阵不物化</td><td>tile 内完成打分与合并</td><td>显存峰值抬高，批容量下降</td></tr><tr><td>变长批可并行</td><td>无跨 token 数据依赖</td><td>批内串行化，吞吐塌陷</td></tr><tr><td>压缩比动态</td><td>随分辨率或 token 数变化</td><td>高分辨率丢细节、低分辨率空转</td></tr><tr><td>顺序语义不变</td><td>下游位置编码同步</td><td>静默语义错位</td></tr></tbody></table>\n<p>回滚方案要按代价排序，而不是按功能排序。第一级回滚是把压缩比退回保守档（接近不压缩），只保留融合 kernel 的结构，代价是显存与带宽回到未压缩水平但语义不变，适合上线后发现下游指标漂移时快速止血。第二级是把相似度 merge 换成池化下采样，放弃可学习参数与动态配对，换取无数据依赖的批内并行，代价是细节保留能力下降，适合变长批占比高的服务形态。第三级是整体摘除压缩模块、恢复视觉塔输出直连 projector，代价是中间张量显存往返回归，但在融合 kernel 本身存在正确性缺陷时这是唯一安全路径。回滚判据应绑定可观测项：中间张量显存峰值、预填阶段 HBM 带宽利用率、批内 token 吞吐随批大小的斜率；斜率转负即说明并行被破坏，此时调压缩比无效，应直接走第二级回滚。可学习 Q-Former 类重采样还要额外检查参数是否随压缩比动态变化而失配，这类失配表现为压缩后 token 分布偏移，只能通过固定压缩比或重训重采样头解决，不能靠 kernel 优化绕过。</p>\n<h3 id=\"ap-visual-token-tools-sec-27\">二十七 · 上游依赖：视觉塔的输出契约决定压缩工具的形态</h3>\n<p>视觉token压缩工具不是独立模块，它的输入契约完全由上游视觉塔决定。工具在视觉塔输出之后、projector之前介入，这意味着它拿到的张量形状是 <code>[B, N_patch, D_vision]</code>，其中 N_patch 随输入分辨率与切图策略变化，D_vision 由视觉塔的隐藏维度决定。压缩工具的第一项上游依赖是<strong>变分辨率语义</strong>：视觉塔是否输出带位置编码的二维网格结构、是否保留 patch 的空间邻接关系，直接决定相似度merge能否成立。若上游只给出扁平序列而无空间索引，基于相似度的merge就退化为全序列两两比较，代价从邻域比较升到 O(N²)。</p>\n<p>第二项依赖是<strong>视觉塔的数值格式</strong>。Blackwell 上视觉塔常以 FP8 或 BF16 输出，压缩工具若要在融合kernel内完成合并，就必须与上游的累加精度对齐——池化下采样在 FP8 上做均值会引入额外舍入，通常需要在 kernel 内部提升到 BF16 累加再落回目标精度。第三项依赖是<strong>视觉塔的显存布局</strong>：输出张量是连续存放还是分块驻留，决定融合kernel能否以单次读入完成压缩。上游若把视觉塔输出写回 HBM 再由压缩工具另起 kernel 读取，就已经输在带宽上了。</p>\n<p>把依赖写成约束式：设视觉塔输出字节数为 <span class=\"formula\">$$M = B \\cdot N_{patch} \\cdot D_{vision} \\cdot b$$</span>，其中 b 为每元素字节数。若压缩与projector分属两个kernel，中间张量至少经历一次写+一次读，额外带宽代价为 2M；在 B200 的 HBM3e 带宽量级下，当 M 达到数百 MB 时，这 2M 的往返就成为prefill阶段可见的延迟项。融合kernel的意义就是把这次往返消掉，让压缩在视觉塔输出的寄存器/共享内存驻留期内完成。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-28\">二十八 · 下游影响：压缩比与token顺序语义如何传导到projector与LLM</h3>\n<p>压缩工具的下游是projector，再下游是多模态LLM的prefill。压缩工具对下游的第一项传导是<strong>接口约定</strong>：输出必须是 <code>[B, N_compressed, D_vision]</code> 且与projector的输入维度严格一致，压缩比变化时projector不得感知形状漂移。第二项传导是<strong>token顺序语义</strong>——这是最容易被忽视的下游影响。池化下采样按固定窗口聚合，输出顺序与输入网格顺序天然一致；相似度merge若把被合并的token写到被保留token的位置，顺序语义保持不变，但若采用追加式写入，projector的位置编码就会错位。可学习Q-Former则输出一组固定数量的query token，顺序由query索引决定，与输入空间顺序解耦，下游必须接受“压缩后无空间邻接”的事实。</p>\n<p>第三项传导是<strong>压缩比对prefill长度的直接缩放</strong>。设原始视觉token数为 N_patch，压缩后为 N_c，则多模态prefill的视觉部分计算量按 N_c 线性缩放，KV cache 中视觉段的占用同样按 N_c 缩放。以N_patch 数千、压缩比数倍计，视觉段在prefill总长度中的占比会从主导降到与文本段可比，这直接改变批调度器的分桶策略——视觉段变短后，变长批内的长度方差下降，连续批处理的填充浪费随之减少。反过来，压缩比按固定值设定时，高分辨率输入丢失细节、低分辨率输入几乎不压缩，下游看到的是质量与长度的双重不稳定，这是压缩比动态化的直接动机。</p>\n<p>第四项传导落在<strong>融合kernel与下游kernel的衔接</strong>上。压缩输出若直接以projector期望的布局写出，projector的GEMM就能连续读取；若压缩工具输出的是转置或分块布局，projector前就要多一次重排kernel，把刚省下的带宽又花回去。工程判断是：压缩工具的写出布局应由projector的输入约定倒推，而不是由压缩算法自身的便利决定。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-29\">二十九 · 与量化配方的耦合：压缩发生在量化之前还是之后</h3>\n<p>压缩工具与多模态量化配方的耦合点在于<strong>量化发生的阶段</strong>。若视觉塔输出即被量化到FP8，压缩工具在量化后的张量上做相似度比较，比较的是量化噪声下的距离，merge判据需要放宽阈值以免把本不相似的token合并；若压缩在量化之前完成，压缩工具工作在更高精度上，判据更干净，但压缩后的张量还要再走一次量化kernel。两种顺序的代价不同：前者省一次量化前的全精度驻留，后者省一次量化后的重排。</p>\n<p>更细的耦合在<strong>池化下采样的累加精度</strong>。池化是均值运算，在FP8输入上直接求平均会因累加溢出或舍入损失细节，融合kernel内部必须以BF16或FP16累加后再落回FP8。这一步若被拆到独立kernel，累加的中间结果又要落盘，正是“压缩模块单独起kernel导致中间张量反复读写显存”这一踩坑的典型形态。Q-Former路径则不同：可学习参数本身通常保持BF16，注意力重采样的中间激活不适合压到FP8，量化配方需要为这条路径保留高精度分支。</p>\n<p>从全书位置看，量化配方管的是“每个张量用什么精度”，压缩工具管的是“哪些张量值得保留”。两者在视觉塔输出到projector之间这段窄通道上正面相遇，谁先谁后不是风格问题，而是带宽与质量的取舍问题：先压缩后量化，带宽花在压缩后的短张量上；先量化后压缩，带宽花在全长张量上但判据受噪声污染。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-30\">三十 · 与分离式预填、批调度的关系：压缩改变的是阶段边界</h3>\n<p>压缩工具对多模态分离式预填配方的影响是<strong>改变了预填与解码之间的张量边界</strong>。分离式部署把prefill放在一组GPU、decode放在另一组，中间通过NIXL搬运KV cache。视觉段压缩后，prefill侧产出的视觉KV长度缩短，跨节点搬运的字节数按压缩比下降，这对NVLink 5与NIXL的传输预算是有利的；但压缩工具本身若不能在prefill的融合kernel链内完成，就会在prefill侧引入额外的kernel启动与显存往返，抵消掉搬运节省。判断标准很直接：压缩带来的KV搬运节省必须大于压缩kernel自身的显存往返代价。</p>\n<p>对多模态批调度的影响则在<strong>批内长度方差</strong>。相似度merge依赖序列内两两比较，在变长批下每个样本的merge路径长度不同，形成数据依赖，破坏批内并行——这是材料明确指出的失败模式，实际延迟高于池化方案。调度器面对这种数据依赖，要么把相似度merge的样本单独成批（牺牲批大小），要么接受批内串行化的尾延迟。池化下采样按固定窗口聚合，窗口数与序列长度成正比但每步独立，天然适合变长批并行。Q-Former的query数量固定，输出长度与输入无关，对调度器最友好，但代价是压缩比不可动态调整。</p>\n<p>把这条关系写成调度侧的判据：设批内样本的压缩路径代价为 <span class=\"formula\">$$T_{compress} = \\max_i T_i(N_i) + \\text{sync}$$</span>，其中 T_i 随样本长度 N_i 增长。相似度merge的 T_i 含 O(N_i²) 项，max 由最长样本主导，短样本被迫等待；池化的 T_i 近似线性，max 与均值差距小。这就是为什么在高吞吐场景下池化方案更稳，而相似度merge更适合离线或低并发的高质量场景。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-31\">三十一 · 在全书中的位置：窄通道上的可插拔决策点</h3>\n<p>把压缩工具放回全书结构，它占据的是<strong>视觉塔与projector之间这条窄通道上的可插拔决策点</strong>。上游的视觉编码器术语表定义了张量形状与语义，图像视频预处理工具链决定了 N_patch 的分布，视觉塔显存溢出条目处理的是视觉塔自身的驻留问题；压缩工具不碰这些，它只在这条通道上做“保留哪些、丢弃哪些”的决策。下游的多模态推理框架消费它的输出形状，多模态量化配方决定它的数值精度，多模态批调度与分离式预填配方消费它的长度缩减。</p>\n<p>它与视觉token压缩术语条目的分工是：术语条目给分类维度与命名，本工具条目给实现清单与插入位置的工程约束。它与跨模态注意力术语条目的关系是：压缩改变了视觉段与文本段在注意力中的长度比，跨模态注意力的计算图随之变形，但注意力本身的机制不变。它与多模态上线前清单的关系是：清单里的检查项之一就是压缩与projector是否同kernel、压缩比是否随分辨率动态调整。</p>\n<p>从代价角度看，这个决策点的价值可以用一条不等式概括：融合kernel带来的带宽节省 <span class=\"formula\">$$\\Delta W = 2M - M_{fused}$$</span> 必须为正，且要大于压缩算法本身引入的计算增量。M 是视觉塔输出的中间张量字节数，M_fused 是融合路径下实际发生的显存流量。当压缩比高、N_patch 大时 ΔW 显著；当压缩比接近1、序列很短时，融合kernel的收益被kernel启动开销吃掉，此时不如让projector直接消费未压缩张量。这条不等式就是“是否值得插入压缩工具”的工程判据，也是本条目在全书中的位置：它不是必选项，而是一个由带宽账本决定的可插拔开关。</p>\n<p>最后落在具体机制上：压缩工具的接口约定应写成“输入 <code>[B, N_patch, D_vision]</code>、输出 <code>[B, N_c, D_vision]</code>、在视觉塔输出驻留期内以融合kernel完成、写出布局对齐projector的GEMM输入”，压缩比作为运行期参数由输入分辨率与下游SLO共同决定，而不是编译期常量。这条约定同时约束了上游视觉塔的输出布局与下游projector的读取方式，是这条窄通道上唯一需要跨条目协商的契约。</p>\n\n<h3 id=\"ap-visual-token-tools-sec-32\">三十二 · 压缩工具的边界：失效条件、系统代价与全书坐标</h3>\n<p>这个工具的价值上限由插入位置决定：它只能在视觉塔输出之后、projector之前工作，因此无法挽回视觉塔内部已经发生的注意力稀释，也无法改变projector自身的降维损失。它的失效条件可以收敛为三条。其一，压缩与projector分属不同kernel，中间张量多次落盘显存，带宽成为瓶颈——此时压缩比再高也只是把瓶颈从计算搬到HBM。其二，相似度merge依赖序列内两两比较，变长批下难以并行，实际延迟高于池化方案，且破坏批内并行度。其三，压缩比按固定值设定，高分辨率输入下丢失过多细节，低分辨率下又几乎不压缩。三条的共同点是：压缩工具不是免费的精度换吞吐，它的收益必须用“融合kernel是否成立”和“压缩比是否随分辨率自适应”两个开关来兑现。</p>\n<p>把系统代价写成可判定的形式：设视觉塔输出张量形状为 <span class=\"formula\">$$T_{\\text{vis}}=[B,\\,N,\\,D]$$</span>，压缩后为 <span class=\"formula\">$$[B,\\,N/r,\\,D]$$</span>，若压缩与projector分kernel，则额外显存往返量为 <span class=\"formula\">$$\\Delta M = 2\\,B\\,N\\,D\\,b$$</span>（b为字节数，系数2为写回与再读），对应带宽代价 <span class=\"formula\">$$\\Delta M / \\text{BW}_{\\text{HBM}}$$</span> 直接叠加在prefill关键路径上。融合kernel把这一项压到接近零，代价是kernel内部必须同时完成相似度或池化归约与projector的线性变换，寄存器与共享内存压力上升，occupancy下降。这是典型的“省带宽、吃占用”的交换，在NVL72这类带宽相对充裕但SM资源紧张的平台上，判断依据应是prefill的SLO余量而非单纯带宽利用率。</p>\n<p>与全书其他条目的接口关系需要说清楚。上游它依赖视觉塔的输出布局与分块方式——若视觉塔输出为变分辨率打包序列，压缩工具必须携带序列长度元数据，否则相似度merge的数据依赖无法在批内切分；下游它直接决定projector的输入token数与KV cache中视觉段的长度，进而影响连续批处理的调度粒度与分离式预填/解码的传输量。它与NVFP4/FP8量化条目是正交的：压缩减少的是token数，量化减少的是每token字节数，二者叠加时要注意压缩后的归约统计量在低精度下的稳定性。它与投机解码的关系在于视觉段属于prefill侧，压缩收益体现在首token延迟而非解码吞吐。在全书结构中，本条目处于“视觉输入预处理”与“projector/多模态融合”之间，是七个领域中多模态推理形态的前置环节，其速查表的列设计（压缩类型、压缩比范围、是否可学习、是否支持融合kernel、插入位置、显存中间张量影响、与projector接口约定）正是为了让读者在选型时把“是否融合”作为第一筛选条件，而非压缩比。</p>\n<p>工程判断落在具体机制上：把压缩模块的kernel融合视为硬门槛，未融合的实现只作为精度对照基线；压缩比按输入分辨率分档而非固定值，并在变长批下优先选池化或固定感受野重采样以保住批内并行；相似度merge仅在批内序列等长或可padding到等长的场景启用。这三条不是建议，而是该工具在Blackwell上能否进入prefill关键路径的准入条件。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-visual-token-tools\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>列出可插拔的token合并与重采样实现，包括基于相似度的merge、快速池化下采样与可学习Q-Former，需…</td></tr><tr><td>关键点</td><td>见正文</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-visual-token-tools · 共 5 个片段</p>\n"},{"id":"ap-mm-serving-frameworks","title":"多模态推理框架","summary":"对比vLLM多模态输入、TensorRT-LLM视觉塔插件、SGLang多模态前端与Triton多模型编排，重点说明各框架对视觉编码器独立部署、图像embedding缓存与异构批的支持程度。","kind":"工具","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-1\">一 · 条目的边界：什么算“多模态推理框架”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-2\">二 · 分类维度一：视觉塔的部署形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-3\">三 · 分类维度二：图像 embedding 缓存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-4\">四 · 分类维度三：异构批与调度粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-5\">五 · 与相邻概念的区别：前端接口与多模型编排</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-6\">六 · 分类的工程落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-7\">七 · 速查表结构与口径定义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-8\">八 · 速查表主体</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-9\">九 · 阈值与判据速查</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-10\">十 · 失败模式对照表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-11\">十一 · 按场景取表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-12\">十二 · 字段填写的工程纪律</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-13\">十三 · 三个解耦维度决定阈值形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-14\">十四 · 图像 embedding 缓存的命中率阈值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-15\">十五 · 异构批的分辨率分桶判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-16\">十六 · 视觉塔与 LLM 的扩容比例测量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-17\">十七 · 没有数字时的测量规程</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-18\">十八 · 阈值随负载漂移的工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-19\">十九 · 解耦阈值：三项能力如何决定视觉塔的扩容边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-20\">二十 · 耦合进程：最贵的坑在调度队列里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-21\">二十一 · 无缓存：同一张图被反复编码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-22\">二十二 · 异构批未分桶：最大分辨率拖慢整批</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-23\">二十三 · 检查顺序：从拓扑到策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-24\">二十四 · 回滚方案：按变更粒度设计</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-25\">二十五 · 清单落地：把坑变成可测的量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-26\">二十六 · 上游依赖：视觉编码器的部署形态决定框架边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-27\">二十七 · 图像 embedding 缓存：框架能力与上游显存条目的接口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-28\">二十八 · 异构批：与批调度条目的分工边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-29\">二十九 · 下游影响：分离式预填/解码与并行通信条目的输入</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-30\">三十 · 在全书中的位置：三条接口线的汇合点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-serving-frameworks-sec-31\">三十一 · 工程判断：选型顺序与失败模式的传导路径</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-mm-serving-frameworks\"><svg style=\"max-width:482px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 482.0 319\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"400.0\" height=\"83.0\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"53.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"57.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：多模态推理框架</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">对比vLLM多模态输入、TensorRT-LLM视觉塔插件、SGLang多模</text><text x=\"75.0\" y=\"78.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">态…</text><line x1=\"82.0\" y1=\"97.0\" x2=\"82.0\" y2=\"114.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 113.0 L 86.5 113.0 L 82.0 121.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"121.0\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"143.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"147.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"148.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><line x1=\"82.0\" y1=\"167.9\" x2=\"82.0\" y2=\"184.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 183.9 L 86.5 183.9 L 82.0 191.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"191.9\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"214.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"218.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"219.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"238.7\" x2=\"82.0\" y2=\"255.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 254.8 L 86.5 254.8 L 82.0 262.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"262.8\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"285.2\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"289.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"290.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-mm-serving-frameworks-sec-1\">一 · 条目的边界：什么算“多模态推理框架”</h3>\n<p>本卷把“多模态推理框架”限定为承载视觉编码器与语言模型协同服务的系统层，而不是模型结构、不是预处理工具链、也不是单个算子库。判据只有一条：它是否在运行时同时管理两类异构计算——视觉塔（通常是 ViT 或卷积主干）与语言解码器——并为它们之间的数据流（像素张量、图像 embedding、token 序列）提供调度、放置与生命周期管理。按此判据，候选集合收敛为四类：vLLM 的多模态输入路径、TensorRT-LLM 的视觉塔插件、SGLang 的多模态前端、Triton 的多模型编排。四者的共同点在于都位于请求入口与 GPU kernel 之间；区别在于它们对“视觉塔是不是一个独立可部署单元”的回答不同。</p>\n<p>需要与相邻概念划清界限。视觉编码器术语表讲的是塔内部的结构与张量形状；视觉 token 压缩术语讲的是像素到 token 的压缩比与信息损失；跨模态注意力术语讲的是融合发生在哪一层。这些都属于“模型内部”，而本条目讲的是“模型外部”：谁先跑、跑在哪个进程、结果放在哪、能不能复用。同样，图像视频预处理工具链处理的是解码、缩放、归一化，产出的是可直接喂给视觉塔的张量；多模态推理框架从这张量被提交给视觉塔的那一刻开始接管，直到文本 token 流回前端。把预处理逻辑塞进框架、或把框架当成预处理库，都是常见的边界误判。</p>\n<p>一个具体机制可以说明这条边界为何重要：当视觉塔与 LLM 处于同一进程、共享同一 CUDA 流与同一调度队列时，一张高分辨率图像的编码会占满 SM 与显存带宽，此时队列中排队的纯文本请求无法被取出执行。这不是模型慢，而是框架把两类负载放进了同一个执行域。工程代价直接体现在尾延迟上：文本请求的排队时间被图像编码时间污染，形成队头阻塞。判据由此可以写成一个不等式——若记文本请求到达率为 λ_t、图像编码平均占用时长为 E_v，则文本请求在共享队列下的等效服务强度近似为 ρ = λ_t·E_t + λ_v·E_v，只要 E_v 相对 E_t 不可忽略，ρ 的抖动就由图像侧主导。框架是否把 E_v 从文本路径上摘出去，就是分类的第一根轴。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-2\">二 · 分类维度一：视觉塔的部署形态</h3>\n<p>第一个维度是视觉编码器能否独立部署。内嵌形态指视觉塔与 LLM 在同一进程、同一 GPU 甚至同一 CUDA context 内，前向由框架直接调用；独立形态指视觉塔作为单独的服务单元（独立进程、独立 GPU 集合或独立副本），通过 RPC 或张量传输把 embedding 交给 LLM 侧。TensorRT-LLM 的视觉塔插件属于前者的典型：视觉塔被编译进引擎、作为插件在 LLM 执行图内被调用，优势是零拷贝、无序列化开销，代价是扩容时视觉塔与 LLM 必须同比例扩，无法按各自负载单独伸缩。Triton 的多模型编排则天然偏后者：视觉塔与 LLM 各自是一个 model repository 中的模型，由编排层按 ensemble 或 BLS 组合，可以给视觉塔单独配置实例数与 GPU。</p>\n<p>独立部署的收益可以用一个简单的扩容判据表达。设视觉塔单副本吞吐为 V、LLM 单副本吞吐为 L（以请求/秒计），若二者内嵌绑定，则系统吞吐为 min(V, L) 乘以副本数；若解耦，则可分别取副本数 n_v 与 n_l，系统吞吐为 min(n_v·V, n_l·L)。当图像分辨率上升导致 V 显著下降而 L 基本不变时，绑定形态被迫整体扩容，多买的 LLM 副本处于闲置；解耦形态只需加视觉塔副本。代价是跨进程传输：embedding 张量需经主机内存或 NVLink 传输，引入序列化与拷贝延迟，且独立视觉塔的显存需要单独预留激活峰值——这正是视觉塔显存溢出条目讨论的场景，此处只需记住它是解耦的必然账单。</p>\n<p>具体例子：一个以短文本问答为主、夹杂少量高分辨率图片审核的负载，V 远小于 L。内嵌形态下每加一张图就要多配一份 LLM 权重，显存成本按 LLM 规模计；解耦形态下视觉塔副本可以放在显存较小、算力较弱的卡上，LLM 副本数不变。判断标准不是“哪种更先进”，而是图像请求占比与分辨率分布是否使 V 与 L 失衡。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-3\">三 · 分类维度二：图像 embedding 缓存</h3>\n<p>第二个维度是图像 embedding 是否可缓存。缓存的对象是视觉塔输出的 embedding 张量（每张图对应一组定长或变长 token），键通常是图像内容哈希加预处理参数（分辨率、裁剪、归一化配置）。命中时跳过视觉塔前向，直接把 embedding 注入 LLM 的输入序列。这个机制在多轮对话中价值最大：同一张图在后续轮次被反复引用，若无缓存则每轮都重跑视觉塔。失败模式写得很直白——无缓存时同一图片被反复编码，浪费视觉塔算力；而算力浪费会转化为排队延迟，因为视觉塔的每次重复编码都占用本可服务新请求的 SM 周期。</p>\n<p>缓存的收益可以写成命中率与单次编码成本的乘积。设多轮会话中图像重复引用比例为 h，单次视觉编码耗时为 E_v，则每轮平均节省的视觉塔时间为 h·E_v；当 h 接近 1（同一图被追问多轮）时，缓存几乎把视觉塔从该会话的关键路径上移除。代价在显存：embedding 缓存占用的是持久显存，条目规模为 N·S_e，其中 N 为缓存条目数、S_e 为单图 embedding 字节数；高分辨率图的 token 数大，S_e 随分辨率线性上升，缓存容量必须与 KV cache 争夺同一块显存池。因此缓存策略的核心不是“开不开”，而是淘汰策略与容量配额——按内容哈希做 LRU，并给缓存设显存上限，超限时优先淘汰低复用图。</p>\n<p>四个候选对缓存的支持程度不同：vLLM 的多模态输入路径在请求层接收图像并管理其生命周期，缓存需要框架显式提供输入缓存机制；TensorRT-LLM 视觉塔插件把编码放在引擎内，缓存需在插件之外另建；SGLang 的多模态前端把图像处理前置到前端层，天然具备在请求入口做内容哈希与复用的位置；Triton 多模型编排可在 ensemble 之间插入缓存模型或由编排层持有缓存。工程判断是：缓存位置越靠近请求入口，命中判定越早，越能避免无效的视觉塔调度；缓存放在 LLM 进程内则要跨进程回传哈希，反而增加耦合。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-4\">四 · 分类维度三：异构批与调度粒度</h3>\n<p>第三个维度是异构批支持，即不同分辨率、不同模态的样本能否进入同一批。视觉塔的批处理有一个硬约束：同一批内所有样本要被 padding 或 resize 到统一形状，批吞吐由批内最大分辨率样本决定。失败模式明确指出，异构批未按分辨率分桶时，混批会被最大分辨率样本拖慢整批。因此“支持异构批”不等于“把所有样本塞进一个批”，而是框架是否提供按分辨率/模态分桶的调度能力，以及是否允许视觉塔与 LLM 使用不同的批组成。</p>\n<p>分桶的代价模型可以直接写出来。设批内有 k 个分辨率桶，桶 i 的样本数为 n_i、单样本编码时间为 t_i（随像素数增长），则按桶分批的总时间为 Σ_i ⌈n_i / b_i⌉·t_i，其中 b_i 为桶 i 的批大小；不分桶时总时间为 ⌈Σn_i / b⌉·max_i t_i。两者之差就是 padding 浪费。分桶越细，浪费越小，但批大小下降会降低 SM 利用率与 kernel 启动摊销，存在一个最优点。调度粒度因此成为分类的关键：vLLM 的多模态输入在连续批处理框架内接收图像，其调度单位是请求；SGLang 的多模态前端把图像处理放在前端，可在进入 LLM 调度器之前完成分桶；TensorRT-LLM 视觉塔插件受引擎静态形状约束，分桶需在构建期确定；Triton 多模型编排可通过动态批处理器按模型分别配置批大小，天然允许视觉塔与 LLM 使用不同批策略。</p>\n<p>具体例子：一个批里混入一张 4K 图与七张 224×224 图。不分桶时整批按 4K 形状 padding，七张小图的算力被浪费在填充上，且整批延迟由 4K 样本决定；按分辨率分两桶后，小图桶以较大批大小快速完成，大图桶单独成批，文本侧可以更早拿到小图的 embedding 开始解码。这里体现的工程判断是：异构批的价值不在“混”，而在“分”——框架能否在视觉塔入口处按形状聚类，决定了它是否真的支持异构负载。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-5\">五 · 与相邻概念的区别：前端接口与多模型编排</h3>\n<p>第四个维度是前端接口形态与多模型编排能力，这两者常被误认为同一件事。前端接口指请求进入框架时的协议与数据形态：图像以 URL、base64、张量还是预计算 embedding 提交，决定了框架在何处接管。若前端接受预计算 embedding，则视觉塔已在框架之外，框架退化为纯 LLM 服务；若前端接受原始像素，则框架必须承担视觉塔调度。SGLang 的多模态前端把图像解析与预处理前置，接口层就完成了模态识别与形状归一；vLLM 的多模态输入在请求层接受多模态输入并映射到模型输入；TensorRT-LLM 视觉塔插件要求输入已被处理为引擎可接受的张量布局。接口形态直接决定缓存与分桶能在哪一层做。</p>\n<p>多模型编排则是把多个独立模型（视觉塔、LLM、可能的投影层）组合成一个逻辑服务的能力，典型如 Triton 的 ensemble 与 BLS。它与“独立部署”相关但不等价：可以独立部署而无编排（手工写 RPC 胶水），也可以有编排而视觉塔仍内嵌。编排能力的代价是每跳的调度与传输开销，收益是每个模型可独立配置批大小、实例数、量化接口与 GPU 亲和性。表格可以把四者的差异压到一屏：</p>\n<table class=\"mini\"><thead><tr><th>框架</th><th>视觉塔部署形态</th><th>embedding 缓存</th><th>异构批</th><th>调度粒度</th><th>多模型编排</th></tr></thead><tbody><tr><td>vLLM 多模态输入</td><td>内嵌为主</td><td>需框架侧输入缓存机制</td><td>受连续批处理调度约束</td><td>请求级</td><td>有限，偏单模型服务</td></tr><tr><td>TensorRT-LLM 视觉塔插件</td><td>内嵌于引擎</td><td>插件外另建</td><td>受静态形状约束，构建期分桶</td><td>引擎执行图级</td><td>弱，以引擎为中心</td></tr><tr><td>SGLang 多模态前端</td><td>可前置、可解耦</td><td>前端入口易做内容哈希复用</td><td>前端可分桶后再入调度</td><td>前端请求级</td><td>中等，前端承担编排</td></tr><tr><td>Triton 多模型编排</td><td>独立模型单元</td><td>可插入缓存模型或编排层持有</td><td>按模型分别配置动态批</td><td>模型级</td><td>强，ensemble/BLS</td></tr></tbody></table>\n<p>读这张表的方式是看三列的联动：视觉塔部署形态决定扩容自由度，缓存支持决定重复图像的算力浪费，异构批支持决定 padding 浪费。三者共同决定“视觉塔能否与 LLM 解耦扩容”这一工程结论。量化接口列之所以单列，是因为它约束视觉塔与 LLM 能否采用不同精度——视觉塔常用 FP8/FP16，LLM 侧可能用 NVFP4，若框架强制统一精度，解耦就失去一半意义；这一点在多模态量化配方中展开，此处只作为分类维度记录。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-6\">六 · 分类的工程落点</h3>\n<p>把四个维度合成一个判断流程：先看图像请求占比与分辨率分布，若视觉塔吞吐与 LLM 吞吐失衡，则独立部署是必要条件；再看多轮会话中图像复用比例，若复用显著，则缓存位置必须靠近请求入口；最后看批内分辨率方差，方差大则必须要求按形状分桶的调度能力。三者任一不满足，框架在负载上升时都会退化为“视觉编码阻塞文本解码”的形态——这正是最常见踩坑的第一条。反过来，若负载以纯文本为主、图像稀疏且分辨率单一，内嵌形态的零拷贝优势反而更大，解耦带来的传输与显存预留是净损失。</p>\n<p>一个可操作的判据是把解耦收益写成差值：解耦带来的吞吐增益约为 min(n_v·V, n_l·L) − min(V, L)·n_bound，减去跨进程传输开销 λ_v·T_transfer 与独立显存预留成本；当 V 与 L 差距越大、T_transfer 越小（同机 NVLink、embedding 尺寸可控），解耦越划算。框架选型的落点因此不是“哪个框架更强”，而是“哪个框架把这三项能力暴露给了运维”——能否单独给视觉塔配副本、能否在入口做哈希缓存、能否按分辨率分桶，决定了容量规划时能不能把视觉塔与 LLM 当成两个独立资源池来算。</p>\n<h3 id=\"ap-mm-serving-frameworks-sec-7\">七 · 速查表结构与口径定义</h3>\n<p>本表按六个字段横向铺开，每一列都对应一个可以在部署评审会上直接追问的工程问题，而不是产品功能清单。口径先定死：<strong>视觉塔部署形态</strong>只取“内嵌”与“独立”两值——内嵌指视觉编码器与语言模型在同一进程/同一 CUDA 上下文内被同一调度器驱动；独立指视觉塔拥有自己的服务边界（独立进程、独立端口或独立模型实例），语言侧通过张量或句柄跨边界取 embedding。<strong>图像 embedding 缓存支持</strong>取“无 / 进程内 / 跨实例”三档，判据是缓存键能否在请求之间稳定复用同一张图的编码结果。<strong>异构批支持</strong>取“同构 / 分桶 / 原生”三档：同构指一个 batch 内分辨率与模态必须一致，分桶指框架按分辨率或模态切子批，原生指调度器直接接纳混合样本而不要求前端预分组。<strong>批调度策略</strong>记录调度粒度（请求级还是 token/块级）与是否具备连续批处理能力。<strong>量化接口</strong>只记录视觉塔与语言模型两侧是否各自暴露可独立配置的精度入口，不评价具体配方。<strong>多模型编排能力</strong>指框架能否在同一服务内声明多个模型/多个视觉塔并按路由分发。</p>\n<p>阈值口径同样要写死，否则表格无法执行：<strong>解耦扩容判据</strong>是“视觉塔实例数能否独立于语言模型实例数伸缩”，只有部署形态为独立且 embedding 可跨边界传递时才成立；<strong>缓存命中判据</strong>是“同一图像在多轮对话中是否只编码一次”，命中率按会话内重复图像占比估算，工程上以“重复编码次数 / 总编码次数”作为观测指标；<strong>异构批判据</strong>是“混批吞吐是否被最大分辨率样本支配”，若一批内编码时延由最长边样本决定且无分桶，则判为同构档。<strong>耦合阻塞判据</strong>最直接：视觉编码与文本解码若共享同一调度队列，则一个长图像编码会推迟队列中所有短文本请求的首 token 时延，这是必须在上线前排除的形态。</p>\n<div class=\"formula\">$$\\text{有效视觉吞吐} = \\frac{N_{\\text{img}}\\cdot (1-h_{\\text{cache}})}{T_{\\text{enc}}^{\\text{bucket}} + T_{\\text{xfer}}}$$</div>\n<p>式中 $h_{\\text{cache}}$ 为 embedding 缓存命中率，$T_{\\text{enc}}^{\\text{bucket}}$ 为按分辨率分桶后的单图编码时延，$T_{\\text{xfer}}$ 为 embedding 跨边界传输开销。该式给出速查表的读法：缓存档位决定分子，部署形态决定分母里的传输项，异构批档位决定 $T_{\\text{enc}}^{\\text{bucket}}$ 是否被最大样本拖长。代价侧要盯的是显存与带宽——独立部署意味着 embedding 要经 NVLink 或主机内存搬运，跨实例缓存则额外占用显存或远端存储；内嵌部署省掉传输却把视觉塔的激活峰值压进语言模型的显存预算里。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-8\">八 · 速查表主体</h3>\n<table class=\"mini\">\n<thead>\n<tr><th>框架</th><th>视觉塔部署形态</th><th>图像 embedding 缓存</th><th>异构批支持</th><th>批调度策略</th><th>量化接口</th><th>多模型编排</th></tr>\n</thead>\n<tbody>\n<tr><td>vLLM 多模态输入</td><td>内嵌为主，视觉塔随模型实例加载</td><td>进程内可复用，跨实例需外置</td><td>分桶：按分辨率/模态切子批</td><td>请求级连续批处理，视觉编码占用同一调度队列</td><td>视觉塔与语言侧分别可配精度入口</td><td>弱：以单模型实例为中心</td></tr>\n<tr><td>TensorRT-LLM 视觉塔插件</td><td>可独立：视觉塔作为插件/独立引擎部署</td><td>依赖外层缓存层，插件本身不持有跨请求缓存</td><td>分桶：需前端预分组，引擎按桶编译</td><td>引擎级批处理，视觉与语言可拆成两条执行路径</td><td>强：引擎按精度分别构建，视觉塔可单独量化</td><td>中：多引擎可组合，编排靠外层</td></tr>\n<tr><td>SGLang 多模态前端</td><td>内嵌，前端统一接纳图像与文本</td><td>进程内前缀/图像缓存，会话内可复用</td><td>原生倾向：前端接纳混合样本，调度侧再分</td><td>token/请求混合粒度，Radix 式前缀复用</td><td>语言侧精度入口明确，视觉塔随模型配置</td><td>中：前端路由多模型</td></tr>\n<tr><td>Triton 多模型编排</td><td>独立：视觉塔与语言模型各自为独立模型实例</td><td>无内建，需在编排层或外部存储实现</td><td>取决于各模型实例的批配置，编排层可分派</td><td>模型级批处理，编排层做请求路由与扇出</td><td>各实例独立配置，精度解耦最彻底</td><td>强：多模型、多实例、集成流水线</td></tr>\n</tbody>\n</table>\n<p>读表时按“三列定生死”的顺序：先看部署形态，再看缓存，最后看异构批。这三项直接决定视觉塔能否与语言模型解耦扩容——若部署形态为内嵌且缓存为“无”，则视觉塔算力被语言模型的批节奏绑架，扩容只能整机复制；若部署形态为独立但缓存缺失，则跨边界传输开销叠加重复编码，独立部署的收益被抵消。TensorRT-LLM 插件与 Triton 编排在部署形态上给到独立，但缓存责任被推给外层，这意味着工程上必须自建以图像内容哈希为键的缓存层，否则多轮对话场景下视觉塔会被同一张图反复打满。SGLang 前端的原生混批倾向降低了前端预分组负担，但调度侧仍需分辨率分桶，否则混批时延被最大样本支配。</p>\n<p>量化接口一列的工程含义是“能否只对视觉塔降精度而不动语言模型”。插件式与多模型编排天然支持这种非对称配置；内嵌形态下两侧共享构建流程，改动视觉塔精度往往牵动整模型重编译，代价是构建时间与回归测试面。多模型编排能力一列则对应路由复杂度：Triton 的强编排换来的是请求扇出与结果聚合的额外一跳，这一跳在 embedding 传输上表现为显存到主机再到显存的往返，是独立部署必须计入的带宽成本。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-9\">九 · 阈值与判据速查</h3>\n<ul>\n<li><strong>解耦扩容成立</strong>：部署形态=独立 且 embedding 可跨边界传递 且 缓存档位≥进程内。三项缺一，扩容收益按整机复制计。</li>\n<li><strong>缓存必须自建</strong>：缓存列为“无”或“依赖外层”时，以图像内容哈希（而非请求 ID）为键建缓存，否则多轮对话重复编码无法拦截。</li>\n<li><strong>异构批可上线</strong>：异构批列为“分桶”时，前端必须按分辨率区间预分组，桶边界取编码器输入尺寸的整数倍；列为“原生”时仍需在调度侧验证最长边样本对批时延的支配程度。</li>\n<li><strong>阻塞风险排除</strong>：批调度策略若为“视觉编码占用同一调度队列”，则长图像编码阻塞短文本请求的失败模式必然出现，须拆队列或拆进程。</li>\n<li><strong>量化非对称</strong>：量化接口需支持视觉塔单独配置精度，否则视觉塔降精度会触发整模型重建，构建代价计入上线周期。</li>\n</ul>\n<p>这些判据的代价侧对应关系要写进容量规划：缓存命中率每提升一档，视觉塔实例数可相应下调，但跨实例缓存引入远端读取时延，需在首 token 时延预算里预留一次缓存查询的往返；分桶带来的收益是批时延方差收敛，代价是桶未填满时的算力空转，桶大小需按到达率分布设定而非按最大分辨率设定。以多轮对话为例：同一张图在会话中被引用三次，无缓存时视觉塔编码三次，进程内缓存时编码一次、两次命中，跨实例缓存时编码一次且命中查询走一次 NVLink 往返——三种形态的视觉塔占用差异直接体现在实例数上，这就是速查表要固定的口径。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-10\">十 · 失败模式对照表</h3>\n<table class=\"mini\">\n<thead>\n<tr><th>失败模式</th><th>触发条件（表中列值）</th><th>观测信号</th><th>处置</th></tr>\n</thead>\n<tbody>\n<tr><td>视觉编码阻塞文本解码</td><td>部署形态=内嵌 且 调度策略=同一队列</td><td>短文本请求首 token 时延随图像请求到达率上升</td><td>拆进程或拆队列，视觉塔转独立部署</td></tr>\n<tr><td>同图重复编码</td><td>缓存=无 或 缓存键非内容哈希</td><td>视觉塔利用率与图像请求数不成比例，重复编码计数上升</td><td>建内容哈希缓存，跨实例则外置存储</td></tr>\n<tr><td>混批被最大分辨率拖慢</td><td>异构批=同构 且 前端未预分组</td><td>批时延由最长边样本决定，小图请求排队等待</td><td>按分辨率分桶，桶边界对齐编码器输入尺寸</td></tr>\n</tbody>\n</table>\n<p>第三行的处置要补一句机制：分桶的本质是把编码时延的支配项从“批内最大样本”换成“桶内最大样本”，桶越窄方差越小但空转越多，工程上以到达率的分位数定桶而非以极值定桶。第一行的处置在插件式与编排式框架里是天然成立的，因为视觉塔本就不在语言模型的调度队列里；内嵌形态要拆，代价是 embedding 传输一跳，这一跳的带宽成本必须小于阻塞消除带来的时延收益，否则拆了反而更慢——这是速查表里部署形态与调度策略两列必须联读的原因。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-11\">十一 · 按场景取表</h3>\n<p>场景一，单模型、图像请求占比低、多轮对话为主：优先看缓存列，选进程内缓存档位，部署形态可容忍内嵌，但要把视觉编码从文本调度队列里摘出来单独成队，否则少量长图请求会周期性拉高文本首 token 时延。场景二，图像请求占比高且分辨率分布宽：优先看异构批列，必须分桶，且桶边界与编码器输入尺寸对齐；此时内嵌形态的显存峰值会与语言模型争预算，独立部署的收益开始显现。场景三，多视觉塔或多模态路由：优先看多模型编排列，Triton 式编排给到最强路由能力，代价是请求扇出与 embedding 聚合的额外一跳，需在时延预算里显式计入。场景四，视觉塔需单独降精度以压显存：优先看量化接口列，非对称配置能力决定构建代价，内嵌形态下这一列往往是短板。</p>\n<p>取表的顺序不可颠倒：先部署形态定扩容模型，再缓存定视觉塔实例数，再异构批定批时延方差，最后量化与编排定构建与路由成本。反过来先挑编排能力再回头补缓存，会在上线后发现视觉塔算力被重复编码吃掉，而此时改部署形态意味着服务边界重划，代价远高于建缓存层。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-12\">十二 · 字段填写的工程纪律</h3>\n<p>填表时禁止把“支持”写成布尔值而不写档位，因为“支持缓存”与“跨实例可复用”是两件事，前者只保证进程内命中，后者才决定独立部署能否真正省下视觉塔实例。同理，“支持异构批”必须落到分桶还是原生，分桶意味着前端有预分组责任，原生意味着调度侧有支配项验证责任，责任归属不同则上线前的验证项不同。部署形态一列要写清边界是进程、端口还是模型实例，因为 embedding 跨边界的传输介质随之不同——进程边界走主机内存，实例边界走 NVLink 或网络，带宽与延迟差一个量级。</p>\n<p>最后一条纪律落在观测上：速查表的每一档都要有对应的可观测指标才能执行——缓存档位对应重复编码计数，异构批档位对应批时延与最大样本时延之比，部署形态对应视觉塔与语言模型的实例数比。没有指标的档位只是标签，无法在容量规划里换算成实例数。工程判断的落点是：当视觉塔与语言模型的实例数比可以独立调节且重复编码计数趋零时，这张表的三列才算真正被满足；否则任何一项编排能力都只是在耦合形态上做的表面解耦。</p>\n<h3 id=\"ap-mm-serving-frameworks-sec-13\">十三 · 三个解耦维度决定阈值形态</h3>\n<p>本片段讨论的“阈值”不是某一组固定常数，而是随框架能力变化的判据边界。视觉塔能否独立部署、图像 embedding 能否缓存、异构批能否按分辨率分桶，这三项能力各自把系统推到不同的工作点，因此阈值必须按能力组合分别测量。工程上先把候选框架按这三项打标，再决定测什么：视觉塔内嵌在同一进程时，要测的是编码阻塞解码的尾部延迟；视觉塔独立部署时，要测的是跨进程传输 embedding 的带宽开销与队列空转；有 embedding 缓存时，要测的是命中率对视觉塔利用率的削减；支持异构批时，要测的是分桶策略对整批步进时间的支配程度。没有这三项打标就直接抄别人的吞吐数字，等于把不同工作点的测量结果混为一谈。</p>\n<p>判据可以写成一个简单的分解：端到端时延由预处理、视觉编码、embedding 传输、LLM 预填与解码五段构成，其中视觉编码段是否与解码段串行，取决于调度队列是否共享。用 <span class=\"formula\">$$T_{e2e} = T_{pre} + T_{enc} + T_{xfer} + T_{prefill} + T_{decode}$$</span> 表示，内嵌形态下 <span class=\"formula\">$$T_{enc}$$</span> 会插入到文本请求的关键路径上，独立部署形态下它只影响图像请求自身，而 <span class=\"formula\">$$T_{xfer}$$</span> 变成新的可见成本。测量方法因此不是测一个总吞吐，而是分别对五段打点，确认哪一段在目标负载下成为支配项。代价上，内嵌形态省掉传输但把视觉塔的算力与显存绑在 LLM 进程上，独立部署形态换来扩容自由度却引入 embedding 的跨进程搬运带宽。</p>\n<p>具体例子：一个以短文本问答为主、夹杂少量高分辨率图像提问的服务，若视觉塔与 LLM 共享同一调度队列，一张大图编码期间队列里的短文本请求全部等待，表现为文本侧 P99 抖动；把视觉塔拆到独立进程后，文本队列不再被图像编码占住，但每张图的 embedding 需要一次跨进程传输，此时要测的是传输耗时是否超过编码耗时的一个可接受比例。这个比例没有通用数字，必须在本机实测 <span class=\"formula\">$$T_{xfer}$$</span> 与 <span class=\"formula\">$$T_{enc}$$</span> 的比值。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-14\">十四 · 图像 embedding 缓存的命中率阈值</h3>\n<p>缓存是否值得做，取决于重复编码的浪费是否超过缓存查找与存储的代价。设单位时间内图像请求数为 <span class=\"formula\">$$N$$</span>，缓存命中率为 <span class=\"formula\">$$h$$</span>，单次编码耗时为 <span class=\"formula\">$$T_{enc}$$</span>，则视觉塔被节省的算力时间为 <span class=\"formula\">$$S = N \\cdot h \\cdot T_{enc}$$</span>；缓存本身的成本是查找开销与 embedding 驻留显存。命中率阈值因此可以写成：当 <span class=\"formula\">$$h$$</span> 低于某个使 <span class=\"formula\">$$S$$</span> 不足以抵消驻留显存挤占 KV cache 所带来的解码吞吐损失时，缓存就是负收益。这个阈值必须实测，因为 embedding 驻留显存与 KV cache 争的是同一块 HBM，挤占效应随并发批大小变化。</p>\n<p>测量方法：固定请求集合，先关闭缓存跑一遍，记录视觉塔利用率与解码吞吐；再开启缓存跑同一集合，记录命中率、视觉塔利用率下降幅度与解码吞吐变化。判据是解码吞吐不下降而视觉塔利用率下降，才算正收益。多轮对话场景是命中率最容易做高的形态，同一图片在后续轮次被反复引用，若无缓存则每次都要重编码，这是材料点明的典型浪费。代价上，缓存键的设计决定命中率：按图像内容哈希可以跨会话命中，按请求 ID 缓存则几乎只在本会话内有效，后者命中率天然低，不值得为它付出驻留显存。</p>\n<p>具体例子：一个文档问答服务，用户上传一页扫描件后连续追问五轮。无缓存时视觉塔被调用五次，有内容哈希缓存时只调用一次，节省的算力时间等于四次编码。此时要测的是这四次编码原本占用的视觉塔时间是否足以支撑更多并发图像请求；若视觉塔本就空闲，节省算力不转化为吞吐，缓存的价值只体现在首 token 延迟上。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-15\">十五 · 异构批的分辨率分桶判据</h3>\n<p>异构批的核心风险是整批步进时间被最大分辨率样本支配。设一批内有 <span class=\"formula\">$$k$$</span> 个样本，各自视觉 token 数为 <span class=\"formula\">$$n_i$$</span>，批步进时间近似正比于 <span class=\"formula\">$$\\max_i n_i$$</span> 而非 <span class=\"formula\">$$\\sum_i n_i$$</span>，则混批的浪费率为 <span class=\"formula\">$$W = 1 - \\frac{\\sum_i n_i}{k \\cdot \\max_i n_i}$$</span>。分桶的判据是：当 <span class=\"formula\">$$W$$</span> 超过按桶拆分所引入的额外批次数与调度开销时，必须分桶；反之可以混批以提高批利用率。这个判据没有通用数值，取决于视觉塔在该分辨率下的实际步进曲线是否线性。</p>\n<p>测量方法：构造分辨率跨度大的请求集合，分别测混批与按分辨率分桶两种策略下的视觉塔吞吐与 P99 延迟。分桶的代价是桶内样本少时批利用率下降，混批的代价是短样本陪跑长样本。工程判断落在“桶边界怎么划”：按 token 数区间划桶比按像素尺寸划桶更贴近实际步进时间，因为预处理后的 token 数才是视觉塔真正处理的量。材料指出混批被最大分辨率样本拖慢整批是常见失败模式，因此分桶不是可选优化而是必测项。</p>\n<p>具体例子：同时到达的一批请求里有缩略图与整页扫描件，缩略图 token 数远小于扫描件。混批时缩略图请求的延迟被扫描件的编码时间拉长；分桶后缩略图桶快速完成，扫描件桶单独步进。要测的是分桶后扫描件桶的批利用率是否低到使视觉塔总算力浪费超过混批的陪跑浪费，这个比较只能用实测步进时间做，不能用 token 数比例推算。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-16\">十六 · 视觉塔与 LLM 的扩容比例测量</h3>\n<p>独立部署的直接收益是视觉塔与 LLM 可以按各自负载扩容。设视觉塔副本数为 <span class=\"formula\">$$R_v$$</span>，LLM 副本数为 <span class=\"formula\">$$R_l$$</span>，系统稳定运行的条件是两侧处理速率匹配：<span class=\"formula\">$$R_v \\cdot \\mu_v \\geq R_l \\cdot \\mu_l \\cdot \\rho$$</span>，其中 <span class=\"formula\">$$\\mu_v$$</span> 为单视觉塔副本的图像处理速率，<span class=\"formula\">$$\\mu_l$$</span> 为单 LLM 副本的请求处理速率，<span class=\"formula\">$$\\rho$$</span> 为每请求平均图像数。扩容比例的阈值就是使上式取等号的 <span class=\"formula\">$$R_v / R_l$$</span>，它随 <span class=\"formula\">$$\\rho$$</span> 变化，因此必须按业务的实际图文比测量，而不是按框架默认配置。</p>\n<p>测量方法：在固定 LLM 副本数下逐步增加视觉塔副本，记录端到端吞吐的拐点；拐点之前增加视觉塔副本带来吞吐上升，拐点之后视觉塔不再是瓶颈，继续加副本只增加显存占用与功耗。代价上，视觉塔副本各自占用显存，独立部署的显存账要与 LLM 的 KV cache 分开算，不能把两者混在一个预算里。材料强调这三项能力直接决定视觉塔能否与 LLM 解耦扩容，因此扩容比例是这套框架对比里最该实测的一项。</p>\n<p>具体例子：图文比高的服务里 <span class=\"formula\">$$\\rho$$</span> 大，视觉塔成为瓶颈，需要更多视觉塔副本；纯文本为主、偶发图像的服务里 <span class=\"formula\">$$\\rho$$</span> 小，视觉塔副本可以少配，把显存留给 KV cache。两种业务的扩容比例不同，用同一套配置上线必然一侧浪费一侧瓶颈。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-17\">十七 · 没有数字时的测量规程</h3>\n<p>材料未给出具体吞吐或延迟数字，因此本部分的工程结论只能落在测量规程上。规程分四步：第一步按三项能力给候选框架打标，确定各自的工作点；第二步对五段时延分别打点，找出目标负载下的支配段；第三步对缓存与分桶分别做开/关对照实验，用解码吞吐与视觉塔利用率两个指标判定正负收益；第四步做扩容拐点扫描，确定 <span class=\"formula\">$$R_v / R_l$$</span> 的实测值。每一步都必须固定请求集合与并发水平，否则对照实验不可比。</p>\n<p>指标口径要写清：视觉塔利用率按编码时间占墙钟时间的比例计，解码吞吐按每秒完成请求数计，P99 延迟按端到端五段之和计。代价上，这套规程本身消耗工程时间，但比抄一个不适配的默认配置上线后返工便宜。判断标准是：任何一项优化在对照实验中若使解码吞吐下降或 P99 上升，即判定为负收益，无论其单项指标多好看。</p>\n<p>具体例子：一个团队按规程测出内嵌形态下文本 P99 被图像编码拉高，拆出视觉塔后文本 P99 回落但 embedding 传输成为新支配段，于是把传输改为批量搬运以摊薄单次开销，再复测确认 P99 继续下降。这个链条里每一步都由实测支配段驱动，没有一步依赖外部数字。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-18\">十八 · 阈值随负载漂移的工程判断</h3>\n<p>上述阈值都不是常数：缓存命中率随会话结构漂移，分桶收益随分辨率分布漂移，扩容比例随图文比漂移。因此阈值必须绑定负载画像一起记录，画像至少包含图文比、分辨率分布与会话轮次分布三项。当画像变化超过一定幅度时，原阈值失效，需要重测。工程判断是：把这三项画像做成上线后的持续观测指标，而不是上线前的一次性测量；阈值表随画像更新，而不是随框架版本更新。</p>\n<p>漂移的代价体现在容量规划上：按旧画像算出的视觉塔副本数在新画像下可能不足，表现为图像请求排队；也可能过剩，表现为显存被闲置视觉塔占住而 KV cache 不足。具体机制是把画像指标与阈值表联动，任一画像指标越界即触发重测，而不是等 P99 报警后再回溯。这一步落在具体机制上：画像驱动的阈值重测循环，是本片段给出的最终工程判断。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-19\">十九 · 解耦阈值：三项能力如何决定视觉塔的扩容边界</h3>\n<p>视觉塔能否与 LLM 解耦扩容，不取决于框架宣传的“支持多模态”，而取决于三个可测量的布尔量：视觉编码器是否可独立部署、图像 embedding 是否可缓存、异构批是否按分辨率分桶。这三项构成一条串联的判定链——任一为否，扩容收益即被截断。可独立部署意味着视觉塔能跑在独立进程或独立 GPU 组上，其扩缩容与 LLM 的批调度解耦；embedding 缓存决定同一图像在多轮对话中是否被重复编码；异构批分桶则决定混批时整批是否被最大分辨率样本拖慢。工程上应把这三项写成配置检查项，而非依赖文档描述，因为“支持”与“默认开启”是两件事。</p>\n<p>量化这三项的系统代价，可用一个粗略的解耦收益式判断是否值得拆分部署：</p>\n<div class=\"formula\">$$G \\approx \\frac{T_{\\text{enc}}\\cdot (1-\\rho)}{T_{\\text{enc}}\\cdot(1-\\rho)+T_{\\text{dec}}}$$</div>\n<p>其中 $T_{\\text{enc}}$ 为单张图像编码耗时，$\\rho$ 为 embedding 缓存命中率，$T_{\\text{dec}}$ 为对应文本解码耗时。当 $\\rho$ 接近 0 且 $T_{\\text{enc}}$ 与 $T_{\\text{dec}}$ 同量级时，$G$ 接近 0.5，说明视觉编码占据了近半的端到端时延，此时把视觉塔放进与 LLM 共享的调度队列就是明确的失效配置——长图像编码会阻塞短文本请求。反之，若缓存命中率高，$G$ 迅速下降，独立部署的紧迫性随之降低。测量方法很直接：在固定请求集上分别记录纯文本请求与含图请求的 TTFT，做差即得视觉编码的暴露时延；再把同一图像重复送入多轮对话，观察视觉塔算力是否随轮次线性增长，即可判定缓存是否真正生效。</p>\n<p>异构批的失效条件更隐蔽。未按分辨率分桶时，混批的完成时间由批内最大分辨率样本决定，小图样本被迫等待，整批吞吐被拖慢。判定方法是构造一组分辨率跨度大的请求，测量批完成时间的方差：方差大且与最大分辨率正相关，说明分桶缺失。下表给出三项能力的检查口径与失效信号：</p>\n<table class=\"mini\"><thead><tr><th>能力项</th><th>检查口径</th><th>失效信号</th><th>系统代价</th></tr></thead><tbody><tr><td>视觉塔独立部署</td><td>视觉编码与文本解码是否分进程/分卡</td><td>长图请求抬高纯文本 TTFT</td><td>解码被编码阻塞，尾延迟抬升</td></tr><tr><td>embedding 缓存</td><td>同图多轮是否复用编码结果</td><td>视觉塔算力随轮次线性增长</td><td>视觉算力与显存带宽浪费</td></tr><tr><td>异构批分桶</td><td>混批是否按分辨率分组</td><td>批完成时间方差随最大分辨率放大</td><td>小图样本空等，批吞吐下降</td></tr></tbody></table>\n<p>需要强调的是，材料未给出具体吞吐或延迟数字，因此上述阈值只能以相对量和方差形态测量，不能引用绝对指标。工程判断应落在配置层面：先确认视觉塔是否真的独立于 LLM 调度队列，再确认缓存键是否覆盖图像内容而非仅请求 ID，最后确认批构造是否按分辨率分桶。三项中任一缺失，都应视为该框架在当前负载形态下的扩容边界，而非等待后续版本补齐的“待优化项”。</p>\n<h3 id=\"ap-mm-serving-frameworks-sec-20\">二十 · 耦合进程：最贵的坑在调度队列里</h3>\n<p>把视觉塔和语言模型塞进同一个进程、共用同一个调度队列，是多模态框架落地时最普遍、也最难在上线前自查出来的坑。表面上它只是“少起一个服务”的部署便利，实质是把两类完全不同的工作负载绑到了同一条时间线上：视觉编码是计算密集、输入尺寸可变、单次耗时长的批处理任务；文本解码是访存密集、逐 token 推进、对首 token 延迟极度敏感的任务。一旦它们共享队列，调度器看到的是一串混合请求，它无法在不拆队列的前提下区分“这个请求还要先跑几百毫秒的 ViT”和“这个请求只差一次 prefill”。</p>\n<p>后果是可量化的。设文本请求的服务时间预算为 <span class=\"inline-math\">S_text</span>，视觉编码耗时为 <span class=\"inline-math\">T_vis</span>，则一个短文本请求若排在长图像请求之后，其首 token 延迟被抬升到近似 <span class=\"inline-math\">T_vis + S_text</span>。连续批处理的前提是批内每个请求的推进步长可比，而视觉编码的步长与解码步长差着数量级，批内最慢成员决定整批节奏——这就是长图像编码阻塞短文本请求的机制本身，不需要额外的排队论假设。</p>\n<div class=\"formula\">$$L_{\\text{ttft}} \\approx \\max_{i \\in \\text{batch}} \\left( T_{\\text{vis},i} \\right) + S_{\\text{text}}$$</div>\n<p>判断是否踩中这条坑，看的是调度粒度而非部署拓扑：即便视觉塔以插件形式挂在同一引擎内，只要它有独立的执行流与独立的批队列，耦合就不成立；反过来，两个进程通过同步 RPC 串行调用，耦合照样成立。检查顺序上，这一项应排在最前，因为它是唯一会同时污染延迟指标与吞吐指标的坑。工程代价体现在三处：首 token 延迟的尾部被拉长、解码吞吐因批内节奏失配而下降、以及视觉塔算力在等待解码时段的闲置。回滚方案是把视觉编码拆成独立部署单元，前端只负责预处理与路由，用 embedding 传递替代进程内调用；拆分后若发现跨进程传输 embedding 的带宽成为新瓶颈，再考虑同机共享内存或 NVLink 域内的直传。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-21\">二十一 · 无缓存：同一张图被反复编码</h3>\n<p>第二个高频坑是图像 embedding 缓存缺失。多轮对话、文档问答、视频逐帧追问这三类形态有一个共同特征：同一份视觉输入在会话生命周期内被引用多次。没有缓存时，每一轮请求都会重新走一遍预处理、ViT 前向、投影到语言模型隐藏维度的全过程。视觉塔的算力被同一份像素反复消耗，而这份算力本可以用来服务新请求。</p>\n<p>缓存键的设计决定命中率。以图像内容哈希（而非请求 ID、也非文件路径）为主键，配合分辨率与预处理参数作为次级键，才能让“同一张图换个问法”命中；若键里混入了会话 ID 或 prompt 片段，命中率会塌到接近零。缓存条目应存投影后的 embedding 而非 ViT 中间激活，前者体积小、可直接拼进语言模型输入序列，后者还要再跑一层投影。容量规划上，单条 embedding 的显存占用与视觉 token 数成正比，因此缓存容量必须与视觉 token 压缩策略联动——压缩率提高，同等显存能缓存的图像数上升，这是两个模块之间少见的正向耦合。</p>\n<p>代价是双向的：命中时省下整段视觉塔前向，未命中时多一次缓存查找与一次写回。若缓存放在主机内存而非显存，查找本身引入的延迟在长图像场景下可忽略，但在小图高频场景下会成为可见开销，此时应把热条目驻留显存、冷条目下沉。检查方法是统计“视觉塔前向次数 / 唯一图像数”的比值，该比值显著大于一即说明缓存未生效或键设计有误。回滚方案是先把缓存做成旁路——命中则用，未命中照常编码并异步写回，不让缓存故障阻断主链路；确认命中率稳定后再把缓存提升为强依赖。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-22\">二十二 · 异构批未分桶：最大分辨率拖慢整批</h3>\n<p>异构批是多模态框架相对纯文本框架最本质的增量能力，也是最容易被误用的一项。支持“不同分辨率、不同模态混批”不等于“混批总是更优”。ViT 的计算量与 token 数近似呈超线性关系，把一张高分辨率图与若干低分辨率图放进同一批，批内每个样本都要按最大样本的形状补齐或按最大序列长度分配激活，整批的显存占用与计算时间由最大者决定。</p>\n<div class=\"formula\">$$\\text{Cost}_{\\text{batch}} \\approx \\max_{i} \\left( N_{\\text{patch},i}^{2} \\right) \\cdot B$$</div>\n<p>上式是分桶必要性的直接来源：批成本由最大 patch 数的平方主导，而非批内平均值。正确做法是按分辨率区间分桶，桶内形状接近，桶间独立调度；跨桶混批只在桶内样本数不足以填满批时才允许，且应设上限。分桶粒度是工程判断点：桶太细则批填充率低、调度开销上升；桶太粗则退化为混批。经验上以视觉 token 数的二倍区间为桶宽，能在填充率与拖慢之间取得平衡。</p>\n<p>这条坑的隐蔽性在于它只在混合流量下暴露。纯高分辨率流量或纯低分辨率流量都跑得很好，一旦两类流量同时到达，尾延迟突然抬升，而单看平均吞吐可能还略有改善——平均值掩盖了尾部。检查顺序上应放在耦合与缓存之后，因为分桶策略的有效性依赖前两项已经理顺：若视觉塔仍与解码共享队列，分桶带来的收益会被队列阻塞吃掉。代价是调度器复杂度上升与批填充率下降，回滚方案是保留“强制同桶”开关，在流量突变时退化为严格同分辨率批，牺牲填充率换确定性延迟。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-23\">二十三 · 检查顺序：从拓扑到策略</h3>\n<p>踩坑清单不能平铺，必须有顺序，因为后面的检查依赖前面的结论。推荐顺序是：部署拓扑 → 缓存 → 分桶 → 量化接口 → 前端契约。理由逐条说明。</p>\n<ul>\n<li><b>拓扑先行。</b>先确认视觉塔是否可独立部署、embedding 是否跨进程传递。若拓扑是耦合的，缓存与分桶的调优都是在错误的地基上做功，收益会被队列阻塞抵消。这一项对应框架分类维度中的“视觉编码器是否可独立部署”，是三项决定解耦扩容能力的维度之首。</li>\n<li><b>缓存其次。</b>拓扑理顺后，视觉塔成为可独立扩容的单元，此时缓存的价值才能被度量——因为缓存直接减少的是这个独立单元的负载。若拓扑未拆，缓存命中省下的算力仍被同一进程的解码等待吞掉，指标上看不出来。</li>\n<li><b>分桶第三。</b>分桶影响的是批内效率，而批的构成由前端路由与缓存命中共同决定。缓存命中率稳定后，到达视觉塔的请求分布才可预测，分桶宽度才有依据。</li>\n<li><b>量化接口第四。</b>视觉塔与语言模型的量化精度可以不同，接口处必须明确 embedding 的数值格式与缩放因子归属。这一项放在后面，是因为它只影响数值正确性与显存占用，不影响调度结构；但一旦出错，表现为生成质量漂移而非性能异常，排查成本高，所以不能省。</li>\n<li><b>前端契约最后。</b>前端接口形态决定预处理在哪一侧完成、图像以何种形式进入服务。它影响的是端到端延迟的固定开销，属于收尾优化项。</li>\n</ul>\n<p>这个顺序的代价是检查周期长——拓扑改造通常涉及部署变更，无法在单次灰度内完成。因此工程上常把顺序折成两轮：第一轮只做拓扑与缓存的只读诊断，第二轮做分桶与量化的可回滚变更。诊断阶段的关键指标是视觉塔前向次数与唯一图像数之比、以及批内 patch 数的方差；前者指向缓存，后者指向分桶。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-24\">二十四 · 回滚方案：按变更粒度设计</h3>\n<p>多模态框架的变更粒度比纯文本框架粗，因为一次变更往往同时动到视觉塔与语言模型两侧。回滚方案必须按变更粒度而非按故障现象设计，否则会出现“回滚了分桶却留着耦合拓扑”的半吊子状态。</p>\n<table class=\"mini\"><thead><tr><th>变更项</th><th>回滚动作</th><th>回滚代价</th><th>触发信号</th></tr></thead><tbody><tr><td>视觉塔拆分部署</td><td>切回进程内嵌路径，保留独立路径待查</td><td>首 token 延迟尾部回升，视觉算力闲置</td><td>跨进程 embedding 传输延迟超出预算</td></tr><tr><td>embedding 缓存</td><td>降级为旁路，不阻断主链路</td><td>视觉塔负载回升至未缓存水平</td><td>缓存查找延迟可见或命中率异常</td></tr><tr><td>异构批分桶</td><td>切强制同桶，牺牲填充率</td><td>吞吐下降，尾延迟确定性改善</td><td>混合流量下尾延迟抬升</td></tr><tr><td>量化接口变更</td><td>回退 embedding 数值格式与缩放因子</td><td>显存占用回升，质量恢复</td><td>生成质量漂移而非性能异常</td></tr></tbody></table>\n<p>回滚设计的核心原则是：每一项变更都必须有独立的开关，且开关的默认值在灰度期保持“旧行为”。耦合拓扑的回滚最贵，因为它涉及部署形态，所以拆分动作应先在旁路流量上验证，再切主流量；缓存与分桶的回滚最便宜，因为它们是纯策略层开关，可以按请求比例逐步放量。量化接口的回滚介于两者之间，难点在于它不产生性能告警，只产生质量漂移，因此必须配套固定的评测集做回归，而不能依赖线上指标。</p>\n<p>还有一个容易被忽略的回滚维度：前端契约。若前端把预处理放在服务侧，回滚到客户端预处理会改变图像进入服务的形态与分辨率分布，进而使分桶宽度失效。因此前端契约的回滚必须与分桶策略的回滚捆绑执行，单独回滚任一项都会让另一项的调优参数失去意义。这一条应写进变更单的依赖栏，而不是留给值班工程师临场判断。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-25\">二十五 · 清单落地：把坑变成可测的量</h3>\n<p>清单要能执行，每一条必须对应一个可测的量，而不是一句“确认已支持”。把前述四类坑转成四个观测量，检查就从主观判断变成数据判断。</p>\n<ul>\n<li><b>耦合度：</b>视觉塔前向与文本解码是否在同一调度队列推进。可观测量是“解码步与视觉编码步的交叠比例”，交叠比例高说明两者在抢同一时间线。</li>\n<li><b>缓存效率：</b>视觉塔前向次数除以唯一图像数。该比值趋近于一说明缓存生效；显著大于一说明键设计或写回策略有问题。</li>\n<li><b>批同质性：</b>批内 patch 数的方差。方差大说明分桶失效，最大样本正在拖慢整批。</li>\n<li><b>数值一致性：</b>量化接口两侧 embedding 的统计量偏差。偏差超阈值说明缩放因子归属错位，表现为质量漂移。</li>\n</ul>\n<p>这四个量分别落在调度、算力复用、批效率、数值正确性四个层面，互不重叠，可以并行采集。工程上应把它们做成常驻指标而非一次性检查项，因为多模态流量分布随业务形态漂移——今天以文档问答为主、明天以视频追问为主，缓存命中率与批同质性都会随之变化。回滚开关的触发条件也应挂在这四个量上，而不是挂在端到端延迟这一个聚合指标上；聚合指标会把四类问题混成一个数字，失去定位能力。</p>\n<p>最后落到一个具体判断：若四个量中只有耦合度异常，优先做拓扑拆分而非调参；若只有缓存效率异常，先查键设计再查容量；若只有批同质性异常，先确认分桶宽度是否与当前流量分布匹配，再考虑是否退化为强制同桶；若只有数值一致性异常，停止放量并回退量化接口，因为这一类异常不会自愈。四条判断互斥，按此顺序执行即可在不引入新变量的前提下定位绝大多数多模态推理的性能与质量异常。</p>\n<h3 id=\"ap-mm-serving-frameworks-sec-26\">二十六 · 上游依赖：视觉编码器的部署形态决定框架边界</h3>\n<p>多模态推理框架在全书中的位置，首先由它的上游依赖界定。上游不是模型权重，而是视觉编码器能否被当作独立服务单元来调度。vLLM 的多模态输入路径把视觉塔挂在同一个推理进程内，图像张量经前端预处理后进入模型执行器，视觉编码与文本解码共享同一套调度资源；TensorRT-LLM 的视觉塔插件则把编码器作为可插拔的引擎组件，允许在构建期决定它与语言模型是否同引擎、同进程；SGLang 的多模态前端把图像处理放在前端层，视觉编码结果以 embedding 形式交给后端；Triton 多模型编排把视觉塔与语言模型当作两个独立模型仓库条目，由编排层决定请求路由。这四种形态的差别不在 API 表面，而在“视觉编码是否占用语言模型的调度时隙”这一条上。上游依赖一旦选错，下游所有优化都被锁死：视觉塔与 LLM 强耦合在同一进程时，图像编码阻塞文本解码，长图像请求会把短文本请求压在队列后面，这是本条目反复强调的失败模式。工程判断很直接——只要业务中存在图像与纯文本混跑，就应优先选择视觉塔可独立部署的形态，把编码延迟从解码关键路径上摘出去。</p>\n<p>从全书结构看，这一条目承接的是算子与数值精度条目给出的视觉塔计算形态（卷积与注意力的精度选择、视觉塔的显存占用），也承接显存与 KV cache 条目对图像 embedding 占用显存的核算。它向下游输出的第一个接口是“视觉塔部署形态”这一列：内嵌还是独立。这个选择直接决定后续容量规划是按“视觉塔副本数 × 单副本显存”还是按“单进程总显存”来算。用公式表达解耦收益，设单张图像编码耗时为 <span class=\"formula\">$$T_{enc}$$</span>，文本解码每 token 耗时为 <span class=\"formula\">$$T_{dec}$$</span>，耦合形态下请求的端到端延迟近似为 <span class=\"formula\">$$T_{enc} + N_{tok} \\cdot T_{dec}$$</span>，而独立部署后编码与解码可在不同资源池并行，解码侧不再等待编码完成才获得调度时隙。代价是跨进程传输图像 embedding 的带宽开销与一次额外的序列化，工程上必须用 embedding 缓存把这笔开销摊薄，否则解耦只换来更复杂的拓扑而没有吞吐收益。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-27\">二十七 · 图像 embedding 缓存：框架能力与上游显存条目的接口</h3>\n<p>图像 embedding 缓存是这一条目与显存、KV cache 条目的直接接口。多轮对话中同一张图片被反复送入，若无缓存，视觉塔对同一图像重复编码，浪费的是视觉塔算力而非语言模型算力——这一点决定了缓存的放置位置：缓存应挂在视觉塔输出侧，键为图像内容摘要（而非请求 ID），值为该图像在语言模型侧的 embedding 序列。vLLM 的多模态输入路径对缓存的支持取决于其输入处理层是否保留图像哈希到 embedding 的映射；TensorRT-LLM 视觉塔插件把编码器独立后，缓存可放在插件与语言模型引擎之间；SGLang 多模态前端天然适合在前端层做内容寻址缓存；Triton 多模型编排则把缓存做成编排层的一个有状态组件。四种形态对缓存的支持程度不同，速查表里“图像 embedding 缓存支持”这一列就是在标注这个差异。</p>\n<p>缓存的上游依赖是显存条目的核算口径：一份图像 embedding 占用的显存等于视觉 token 数乘以隐藏维度乘以精度字节数，缓存容量上限必须与 KV cache 预算一起纳入总显存规划，不能把 embedding 缓存当作“免费”的旁路。下游影响则落在批调度条目上：有缓存时，命中缓存的请求可以直接进入解码队列，视觉塔的负载呈现稀疏突发；无缓存时，视觉塔负载与请求到达率线性相关，容量规划必须按峰值图像到达率配置视觉塔副本。伪代码思路是：请求到达后先对图像做内容摘要，查缓存；命中则跳过视觉塔直接组装语言模型输入，未命中则路由到视觉塔副本编码并回填缓存。代价是摘要计算本身消耗前端 CPU 时间，且缓存失效策略（按容量淘汰还是按会话生命周期）会影响命中率，工程上应把缓存命中率作为独立指标监控，而不是混在端到端延迟里。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-28\">二十八 · 异构批：与批调度条目的分工边界</h3>\n<p>异构批支持是本条目与多模态批调度条目的分工点。批调度条目讲的是连续批处理、批饥饿与调度粒度的一般机制；本条目只讲框架层面对“不同分辨率、不同模态混批”的支持程度，以及这个支持程度如何反过来约束调度策略。异构批未按分辨率分桶时，混批会被最大分辨率样本拖慢整批，这是失败模式之一。框架能否支持异构批，取决于它的批组装发生在哪一层：vLLM 的多模态输入在模型执行器内组装批，分辨率差异直接体现为视觉 token 数差异，需要框架内部做 padding 或变长处理；TensorRT-LLM 视觉塔插件在引擎边界组装，可对不同分辨率走不同引擎配置；SGLang 前端可在请求进入后端前按分辨率分组；Triton 多模型编排把分组责任交给编排层，灵活性最高但需要用户自己实现分桶逻辑。</p>\n<p>这里的推理系统代价是显存与吞吐的权衡：按分辨率分桶会降低单批的填充浪费，但会增加批的等待时间，桶越细等待越长；不分桶则单批被最大样本主导，视觉塔的算力利用率随批内分辨率方差上升而下降。设批内样本的视觉 token 数为 <span class=\"formula\">$$n_1,\\dots,n_B$$</span>，不分桶时整批按 <span class=\"formula\">$$\\max_i n_i$$</span> 分配计算资源，有效利用率近似为 <span class=\"formula\">$$\\frac{\\sum_i n_i}{B \\cdot \\max_i n_i}$$</span>。这个比值就是分桶策略要优化的目标，而框架对异构批的支持程度决定了这个优化能落在哪一层：支持度高的框架允许在编排层做分桶而不改动模型执行器，支持度低的框架只能在批内做 padding，优化空间被压缩。具体例子是同一批里混入一张高分辨率截图与若干小图，不分桶时小图请求的视觉塔时隙被拉长到与截图相同，端到端延迟被无谓放大；分桶后小图批独立成批，截图批单独调度，两类请求的延迟分布各自收敛。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-29\">二十九 · 下游影响：分离式预填/解码与并行通信条目的输入</h3>\n<p>本条目向下游输出的第二个接口是“视觉塔能否与语言模型解耦扩容”。分离式预填/解码条目讨论的是预填与解码分池部署，多模态场景下这个分池多了一层：视觉编码是否也独立成池。若框架支持视觉塔独立部署，则拓扑可以是视觉塔池、预填池、解码池三段，图像 embedding 从视觉塔池流向预填池；若不支持，视觉编码只能挤在预填池里，预填池的显存与算力预算必须同时容纳视觉塔与语言模型预填，扩容粒度被绑死。这个判断直接影响并行与通信条目的设计：三段拓扑意味着两段跨节点传输，图像 embedding 的体积（视觉 token 数 × 隐藏维度 × 精度字节）与 KV cache 传输量在同一量级时，NIXL 或 NCCL 的带宽预算要按两股流量叠加来算；两段拓扑则只有一段传输，但预填池的扩容必须整机扩容，无法只加视觉塔副本。</p>\n<p>功耗与带宽代价在这里体现为：视觉塔独立成池后，空闲视觉塔副本可以被下电或降频，而耦合形态下视觉塔随语言模型进程常驻，无法单独调节。工程判断是——当图像请求占比低且突发性强时，独立视觉塔池的功耗收益明显；当图像请求占比高且稳定时，耦合形态省掉一次跨进程传输，反而更省带宽。这个判断依赖业务画像而非框架偏好，框架选型应把“视觉塔部署形态”作为第一决策项，而不是先选框架再适配部署形态。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-30\">三十 · 在全书中的位置：三条接口线的汇合点</h3>\n<p>把这一条目放回全书，它处在三条接口线的汇合点。向上，它接收算子与数值精度条目给出的视觉塔计算形态与量化接口——速查表里“量化接口”这一列标注的是框架能否对视觉塔单独施加 NVFP4/FP8 配方，而这取决于视觉塔是否被框架视为独立可配置单元；若视觉塔内嵌在语言模型进程里，量化配置往往只能整模型统一，视觉塔的精度选择空间被压缩。向侧，它与视觉 token 压缩条目共享 embedding 序列的长度口径：压缩后的视觉 token 数直接决定 embedding 缓存容量与跨池传输量，压缩比越高，解耦的传输代价越低，独立部署的收益越容易兑现。向下，它向 SLO 与容量规划条目输出可计算的容量单元：视觉塔副本数、embedding 缓存容量、分桶策略三个参数构成多模态容量模型的自变量，而这三个参数的可行取值范围由框架的支持程度划定。</p>\n<p>具体机制上，框架对三项能力的支持程度（独立部署、embedding 缓存、异构批）构成一个三维能力向量，容量规划条目的输入就是这个向量而非单一吞吐数字。举例来说，Triton 多模型编排在三项上都给出最大灵活性，代价是用户必须自己实现路由、缓存与分桶逻辑，工程复杂度转移到应用层；TensorRT-LLM 视觉塔插件在独立部署与量化接口上支持度高，缓存与分桶需要借助插件边界实现；vLLM 多模态输入在易用性上占优但解耦能力受限；SGLang 多模态前端在前端层缓存上占优。这个能力向量的差异就是本条目在全书中的位置——它不重复任何单项机制的定义，只负责把框架能力映射为下游条目的输入参数，并把上游条目的约束翻译成框架选型的判据。</p>\n\n<h3 id=\"ap-mm-serving-frameworks-sec-31\">三十一 · 工程判断：选型顺序与失败模式的传导路径</h3>\n<p>最后落在工程判断上。多模态推理框架的选型顺序应是：先定视觉塔部署形态（内嵌还是独立），再定 embedding 缓存位置，最后定异构批的分桶层。这个顺序不可颠倒，因为后两项的可行空间由第一项划定。失败模式的传导路径也沿这条链：视觉塔与 LLM 强耦合在同一进程，图像编码阻塞文本解码，这是第一环；缺少 embedding 缓存，同一图像在多轮对话中被反复编码，这是第二环，它放大了第一环的阻塞效应；异构批未按分辨率分桶，混批被最大分辨率样本拖慢，这是第三环，它把前两环的延迟放大传导到整批。三环叠加时，端到端延迟的方差远大于均值，SLO 会被尾部请求击穿，而容量规划若按均值配置视觉塔副本，峰值到达时必然批饥饿。</p>\n<p>可操作的判据是：若业务中图像请求与文本请求共享同一 SLO，视觉塔必须独立部署且 embedding 缓存必须开启，否则文本请求的延迟分布会被图像编码污染；若图像请求有独立 SLO 且占比稳定，耦合形态可以接受，但异构批分桶仍必须在框架层或编排层实现，因为分辨率方差是图像请求的固有属性而非偶发。框架能力向量中任何一项为“不支持”，都应在容量模型里折算为等效的副本数上浮或缓存命中率下调，而不是假设框架会自行兜底。这一条判断把本条目与容量规划条目扣在一起：框架选型不是性能评测，而是把三项能力的有无翻译成容量模型里的确定性参数。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-mm-serving-frameworks\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>对比vLLM多模态输入、TensorRT-LLM视觉塔插件、SGLang多模态前端与Triton多模型编排，重…</td></tr><tr><td>关键点</td><td>见正文</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-mm-serving-frameworks · 共 5 个片段</p>\n"},{"id":"ap-mm-quant-recipe","title":"多模态量化配方","summary":"视觉塔建议保留FP8/BF16敏感层、对projector与LLM采用FP8 W8A8并校准视觉token分布，KV cache用FP8存储；需按图像分辨率分桶校准，防止高分辨率token激活离群导致精度塌陷。","kind":"配方","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-1\">一 · 条目边界：什么算“一份配方”，什么不算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-2\">二 · 四个量化对象：分类的第一维</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-3\">三 · 格式与校准：第二、第三维的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-4\">四 · 敏感层豁免：第四维与速查表的落地</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-5\">五 · 与相邻条目的分界：三个易混点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-6\">六 · 边界条件：分辨率分桶与敏感层豁免的失效面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-7\">七 · 速查表总览与字段口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-8\">八 · 阈值：分辨率分桶与离群判定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-9\">九 · 敏感层豁免：名单如何登记与验证</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-10\">十 · KV cache FP8：长上下文误差累积的口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-11\">十一 · 风险等级判定与回退路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-12\">十二 · 速查表的使用顺序与判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-13\">十三 · 阈值不是常数，是分桶边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-14\">十四 · 敏感层名单的量化判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-15\">十五 · KV cache FP8 的误差累积怎么测</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-16\">十六 · 校准集覆盖度的测量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-17\">十七 · 把阈值写进速查表的可执行形式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-18\">十八 · 分辨率分桶校准的失效边界与量化代价核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-19\">十九 · 踩坑清单：三类失败模式的机理与代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-20\">二十 · 检查顺序：从数据分布到数值路径的固定排查链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-21\">二十一 · 分桶校准的落地：分辨率桶的划分与scale策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-22\">二十二 · 敏感层豁免与KV cache的联动检查</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-23\">二十三 · 回滚方案：分级降级而非一刀切</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-24\">二十四 · 分辨率分桶校准的失效边界与回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-25\">二十五 · 上游依赖：配方吃的是谁的数据契约</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-26\">二十六 · 与视觉塔显存溢出的耦合：精度策略换显存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-27\">二十七 · 与多模态批饥饿、批调度的联动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-28\">二十八 · 与分离式预填、KV cache 条目：FP8 KV 的边界条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-29\">二十九 · 下游影响：多模态上线前清单与容量规划</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-quant-recipe-sec-30\">三十 · 在全书中的位置：配方是精度维度的收口点</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-mm-quant-recipe\"><svg style=\"max-width:487px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 487.1 357\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"405.1\" height=\"83.0\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"53.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"57.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：多模态量化配方</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">视觉塔建议保留FP8/BF16敏感层、对projector与LLM采用FP8 </text><text x=\"75.0\" y=\"78.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">…</text><line x1=\"82.0\" y1=\"97.0\" x2=\"82.0\" y2=\"114.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 113.0 L 86.5 113.0 L 82.0 121.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"121.0\" width=\"405.1\" height=\"83.0\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"162.6\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"166.8\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"148.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><text x=\"75.0\" y=\"171.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">需按图像分辨率分桶校准，防止高分辨率token激活离群导致精</text><text x=\"75.0\" y=\"187.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">度塌陷。</text><line x1=\"82.0\" y1=\"206.1\" x2=\"82.0\" y2=\"223.1\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 222.1 L 86.5 222.1 L 82.0 230.1 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"230.1\" width=\"405.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"252.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"256.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"257.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"276.9\" x2=\"82.0\" y2=\"293.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 292.9 L 86.5 292.9 L 82.0 300.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"300.9\" width=\"405.1\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"323.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"327.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"328.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-mm-quant-recipe-sec-1\">一 · 条目边界：什么算“一份配方”，什么不算</h3>\n<p>多模态量化配方在本书语境下有严格的外延：它是一份<strong>按模块分列精度策略的组合方案</strong>，同时覆盖视觉塔、projector、LLM 主干与 KV cache 四个对象，并对每个对象给出权重精度、激活精度、是否校准、校准数据分桶方式与敏感层豁免名单。判断一份材料是否属于本条目，看它是否同时回答“哪些模块用什么格式”和“用什么数据校准”两个问题。只给单模块精度（例如“视觉塔用 FP8”）是算子级配置，不是配方；只给校准方法论而不落到模块划分，是校准流程条目，也不是配方。配方的本质是<strong>跨模块的精度预算分配</strong>：视觉塔保留 FP8/BF16 敏感层、projector 与 LLM 采用 FP8 W8A8、KV cache 以 FP8 存储，这三句话构成一个可执行的整体，拆开任何一句都会失去配方属性。</p>\n<p>与相邻概念的边界需要一次说清。视觉编码器术语表管的是视觉塔内部结构与张量语义，配方管的是这些张量在什么精度下被乘、被存；视觉 token 压缩术语管的是 token 数量削减，配方管的是剩余 token 的数值表示，两者正交——压缩改变的是 token 序列长度，量化改变的是每个 token 的位宽，一个配方可以在压缩前后各有一套校准桶。跨模态注意力术语描述的是注意力如何跨模态对齐，配方只关心该注意力路径上的 QKV 是否被量化以及 KV cache 的存储格式。多模态批调度术语处理的是请求排队与显存占用节奏，配方则决定单请求的显存底噪，二者在容量规划上耦合但定义不重叠。</p>\n<p>给出一个具体例子以固定边界。某部署把视觉塔全部层统一压到 FP8、projector 与 LLM 用 FP8 W8A8、KV cache 用 FP8，校准集只含低分辨率图像。这份材料形式上满足“四对象全覆盖”，但它缺少敏感层豁免名单与分辨率分桶，因此属于<strong>不完整配方</strong>，其失败模式正是视觉塔敏感层被一并 FP8 量化后细粒度视觉特征丢失、下游问答准确率下降。配方条目要求把“豁免哪些层”和“按什么分桶校准”写成显式字段，否则无法在速查表中被审计。</p>\n\n<h3 id=\"ap-mm-quant-recipe-sec-2\">二 · 四个量化对象：分类的第一维</h3>\n<p>第一分类维度是量化对象，它决定了误差如何传播。视觉塔是图像到 token 的入口，其输出直接决定后续所有模态对齐的质量；projector 承担视觉特征到 LLM 隐空间的映射，是跨模态语义的瓶颈层；LLM 主干承载绝大部分参数与算力；KV cache 是解码阶段的显存主项。四者的量化风险不对称：视觉塔的误差会被 projector 放大并沿序列传播，LLM 主干的误差在长上下文里累积，KV cache 的误差则随解码步数单调叠加。</p>\n<p>用一条误差传播链表达这种不对称。设视觉塔第 $l$ 层量化引入的相对扰动为 $\\epsilon_l$，projector 的映射矩阵条件数为 $\\kappa$，则进入 LLM 的视觉 token 扰动近似满足</p>\n<div class=\"formula\">$$\\|\\delta \\mathbf{h}\\| / \\|\\mathbf{h}\\| \\;\\lesssim\\; \\kappa \\cdot \\sum_{l} \\epsilon_l$$</div>\n<p>该式说明视觉塔的逐层小误差会经 projector 的条件数放大，因此配方对视觉塔采取“保留敏感层”的策略，而对 projector 与 LLM 直接采用 FP8 W8A8——后者的权重与激活分布更接近常规 LLM 量化经验，且误差不经过高条件数映射。KV cache 的误差则不同，它不进入上述乘积，而是在每个解码步以 $O(t)$ 累积，故配方单独为它设定 FP8 存储并配合长上下文误差监控。</p>\n<p>系统代价按对象分列。视觉塔保留 BF16 敏感层意味着该部分权重与激活占两倍位宽，直接抬高视觉塔的显存占用与加载带宽；projector 与 LLM 的 FP8 W8A8 把矩阵乘的算力需求减半、权重带宽减半，是吞吐的主要来源；KV cache 的 FP8 存储把每 token 每层的缓存字节数减半，是长上下文并发数的决定性因素。一个具体例子：高分辨率图像输入使视觉 token 数上升，视觉塔激活的显存峰值随之上升，若此时视觉塔敏感层仍为 BF16，则该峰值成为整条流水线的显存瓶颈，配方必须在此处显式标注风险等级。</p>\n\n<h3 id=\"ap-mm-quant-recipe-sec-3\">三 · 格式与校准：第二、第三维的耦合</h3>\n<p>第二维是量化格式，取值包括 FP8、BF16 与 FP8 W8A8。格式不是孤立标签，它与对象绑定才有意义：视觉塔的“FP8/BF16 敏感层”是混合格式，同一塔内不同层取不同格式；projector 与 LLM 的“FP8 W8A8”是权重与激活同为 FP8 的对称方案；KV cache 的“FP8 存储”只约束缓存张量的表示，不涉及计算格式。第三维是校准数据分布，核心是按图像分辨率分桶。这两维必须耦合设计：格式越激进，校准桶越要覆盖激活分布的尾部。</p>\n<p>分桶校准的机制可写成伪代码思路：对每个分辨率桶 $b$ 收集该桶内视觉 token 的激活样本，统计其分位数作为缩放因子，再将该桶的缩放因子写入对应模块的量化参数表；推理时按输入图像的实际分辨率选择桶，而非使用全局单一缩放。这样做的原因是高分辨率 token 激活存在离群值，若用低分辨率校准集统计，离群值未被覆盖，量化区间被压缩，高分辨率输入下精度塌陷。工程阈值方面，材料未给出具体精度下降数值，关键经验就是分桶校准本身——它是防止激活离群导致塌陷的唯一显式手段。</p>\n<p>代价体现在校准成本与推理切换成本上。分桶意味着多套缩放因子，校准阶段需要按桶采集数据，桶数增加线性抬高校准数据量与离线统计时间；推理阶段按分辨率选桶是一次查表，开销可忽略，但桶边界设计不当会造成同一请求在相邻桶间跳变，引起输出不一致。一个具体例子：校准集只含低分辨率图像时，高分辨率桶缺失，推理遇到高分辨率输入只能回退到低分辨率缩放，此时视觉 token 激活离群未被统计，量化后精度塌陷——这正是本条目列出的首要失败模式，也是速查表中“校准数据分桶方式”列必须逐模块填写的原因。</p>\n\n<h3 id=\"ap-mm-quant-recipe-sec-4\">四 · 敏感层豁免：第四维与速查表的落地</h3>\n<p>第四维是敏感层豁免策略，它回答“哪些层不进 FP8”。豁免不是凭经验拍板，而是由校准阶段的逐层误差统计支撑：对视觉塔逐层做量化前后输出偏差比较，偏差超过阈值的层进入豁免名单，保持 BF16 或 FP8 但不做激活量化。豁免名单是配方的一部分，必须与模块名称、权重精度、激活精度并列写入速查表，否则配方无法被复现。</p>\n<p>速查表的列定义为：模块名称、权重精度、激活精度、是否校准、校准数据分桶方式、KV cache 精度、敏感层名单、精度塌陷风险等级。这张表的作用是把四维分类压成可审计的行。每一行对应一个模块，风险等级由该模块的误差传播位置与校准覆盖度共同决定：视觉塔敏感层若被误纳入 FP8，风险等级应标为高；KV cache 在长上下文场景下风险等级随上下文长度上升。表格不是文档装饰，它是上线前核对精度策略的唯一结构化载体。</p>\n<table class=\"mini\"><thead><tr><th>模块名称</th><th>权重精度</th><th>激活精度</th><th>是否校准</th><th>校准分桶方式</th><th>KV cache 精度</th><th>敏感层名单</th><th>塌陷风险</th></tr></thead><tbody><tr><td>视觉塔</td><td>FP8/BF16 混合</td><td>FP8/BF16 混合</td><td>是</td><td>按图像分辨率分桶</td><td>—</td><td>逐层误差超标层</td><td>高（敏感层误量化时）</td></tr><tr><td>projector</td><td>FP8</td><td>FP8</td><td>是</td><td>按图像分辨率分桶</td><td>—</td><td>无</td><td>中</td></tr><tr><td>LLM 主干</td><td>FP8</td><td>FP8</td><td>是</td><td>按图像分辨率分桶</td><td>FP8</td><td>按逐层统计确定</td><td>中</td></tr><tr><td>KV cache</td><td>—</td><td>—</td><td>否</td><td>—</td><td>FP8</td><td>—</td><td>随上下文长度上升</td></tr></tbody></table>\n<p>系统代价在此维上表现为显存与吞吐的取舍。豁免层越多，视觉塔的 BF16 占比越高，权重带宽与显存占用上升，视觉塔前向延迟增加；豁免层越少，FP8 占比越高，吞吐上升但细粒度视觉特征丢失风险上升。一个具体例子：某配方把视觉塔最后若干层列入豁免名单以保住细粒度特征，代价是这部分层的激活显存翻倍，在批较大时压缩了可并发请求数——配方必须把这一代价写进风险等级列，供容量规划引用。</p>\n\n<h3 id=\"ap-mm-quant-recipe-sec-5\">五 · 与相邻条目的分界：三个易混点</h3>\n<p>第一个易混点是配方与视觉塔显存溢出。后者描述的是视觉塔激活峰值撑爆显存的故障现象，配方则是预防该现象的精度侧手段之一：降低视觉塔非敏感层的位宽可以直接压低激活峰值，但配方不负责批大小与分块策略，那些属于显存管理与批调度条目。配方在速查表中标注风险等级，溢出条目消费该等级做容量判断，两者是供给与消费的关系，不是同一件事。</p>\n<p>第二个易混点是配方与多模态上线前清单。清单是流程性核对项集合，配方是清单中被核对的一项技术产物。清单会问“是否按分辨率分桶校准”“敏感层名单是否完整”，配方提供这些字段的取值。把配方写成清单会丢失精度预算的定量结构，把清单写成配方会丢失流程校验的顺序性。</p>\n<p>第三个易混点是配方与多模态分离式预填配方。分离式预填处理的是预填与解码在不同资源池上的切分，配方处理的是数值表示。二者在 KV cache 上相交：分离式预填决定 KV cache 在哪个池生成与传输，配方决定它以 FP8 存储。传输带宽因此受配方影响——FP8 存储使跨池传输的 KV 字节数减半，这是配方对分离式部署的间接贡献，但配方本身不规定传输路径。</p>\n<p>工程判断落在速查表的完整性上：一份配方若缺少敏感层名单或分桶方式任一列，就不能进入上线核对；若 KV cache 精度列填写但未标注长上下文误差累积风险，则多轮多模态对话后段输出漂移无法被归因。配方条目的价值不在于给出某个格式，而在于把四个对象的精度策略与校准覆盖度绑成一张可审计的表，使精度塌陷风险在部署前就被定位到具体模块与具体分辨率桶。</p>\n\n<h3 id=\"ap-mm-quant-recipe-sec-6\">六 · 边界条件：分辨率分桶与敏感层豁免的失效面</h3>\n<p>这套配方的适用边界由两个前提共同划定：其一，视觉塔中存在一批对量化误差不可交换的敏感层，必须保留FP8/BF16而非统一压到更低位宽；其二，projector与LLM的FP8 W8A8校准统计量必须覆盖真实推理时出现的激活分布。第一个前提失效的典型形态是把视觉塔敏感层一并纳入FP8量化——细粒度视觉特征在patch embedding与早期attention中被抹平，下游问答准确率下降，而这一损失在纯文本benchmark上不可见，容易被误判为“量化无损”。第二个前提失效则更隐蔽：校准集只含低分辨率图像时，高分辨率输入产生的token激活离群值从未进入amax统计，scale被系统性低估，量化后出现精度塌陷。因此配方不是一组静态位宽，而是一条以分辨率分桶为索引的条件策略。</p>\n<div class=\"formula\">$$ s_{b}=\\frac{\\max_{x\\in\\mathcal{C}_{b}}|x|}{q_{\\max}},\\qquad \\hat{x}=\\mathrm{clamp}\\!\\left(\\mathrm{round}(x/s_{b}),-q_{\\max},q_{\\max}\\right) $$</div>\n<p>式中分桶集合$\\mathcal{C}_{b}$按图像分辨率划分，$s_b$为该桶的激活scale。工程含义直接：单一分辨率校准等价于用一个小$\\mathcal{C}$去覆盖全部$b$，高分辨率桶的$s_b$被低估，截断误差在离群通道上放大。代价体现在校准流水线的存储与调度——每个分辨率桶需独立保存校准激活、独立跑一遍前向统计，桶数增加线性抬升校准显存占用与离线时间；推理侧则需在请求进入时按分辨率路由到对应scale，路由表本身很小，但桶边界设置不当会造成同桶内分布跨度大、scale偏保守，牺牲有效位宽。一个具体判断：当输入分辨率跨度超过一个数量级时，单桶方案在高分辨率端的精度塌陷风险等级应标为高，速查表中该模块的“校准数据分桶方式”列必须写明桶边界而非留空。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>机制</th><th>系统代价</th></tr></thead><tbody><tr><td>校准集缺高分辨率样本</td><td>激活离群未入amax，scale低估</td><td>离线校准省时，在线精度塌陷</td></tr><tr><td>视觉塔敏感层被FP8覆盖</td><td>细粒度特征在早期层丢失</td><td>视觉塔带宽降，问答准确率降</td></tr><tr><td>KV cache FP8用于长上下文</td><td>误差随token数累积</td><td>KV显存降，多轮后段输出漂移</td></tr></tbody></table>\n<p>第三类失效来自KV cache的FP8存储：显存与带宽收益明确，但误差沿序列长度累积，多轮多模态对话的后段输出出现漂移，且漂移不表现为单轮崩溃而是渐进退化，难以用单次评测捕获。配方因此需要把“KV cache精度”与“精度塌陷风险等级”并列写入速查表，让风险等级由分辨率分桶覆盖度、敏感层名单完整性、上下文长度三者共同决定，而不是由位宽单独决定。边界之外的部分——视觉塔敏感层名单如何枚举、projector校准如何与LLM解耦——属于本模块其他小节的展开范围。</p>\n<h3 id=\"ap-mm-quant-recipe-sec-7\">七 · 速查表总览与字段口径</h3>\n<p>这张表是给工程同学直接贴到设计评审或上线 checklist 里的，不是概念索引。它把“多模态量化配方”拆成八列，每列对应一个必须落地的决策点：模块名称、权重精度、激活精度、是否校准、校准数据分桶方式、KV cache 精度、敏感层名单、精度塌陷风险等级。八列的顺序即决策顺序——先定模块边界，再定权重与激活格式，再定校准口径，最后用风险等级兜底。</p>\n<p>字段口径需要先说清楚，否则同一张表在不同团队手里会读出歧义。“权重精度”指该模块线性层权重的存储格式；“激活精度”指该模块前向激活的存储与计算格式，W8A8 意味着两者都是 8 位整型/浮点通道。“是否校准”只回答一个问题：该模块的量化尺度是否由数据驱动产生，而不是静态经验值。“校准数据分桶方式”描述校准集如何切分，本配方唯一推荐的口径是按图像分辨率分桶。“KV cache 精度”单列，因为它是跨模块的存储决策，不属于任何单一模块的权重/激活范畴。“敏感层名单”是豁免清单，列的是不参与激进量化的层。“精度塌陷风险等级”是定性分级，材料未给出具体精度下降数值，因此这一列只写高/中/低，并附一句触发条件。</p>\n<p>表的结构如下，可直接复制为评审模板：</p>\n<table class=\"mini\">\n<thead>\n<tr><th>模块名称</th><th>权重精度</th><th>激活精度</th><th>是否校准</th><th>校准数据分桶方式</th><th>KV cache 精度</th><th>敏感层名单</th><th>精度塌陷风险等级</th></tr>\n</thead>\n<tbody>\n<tr><td>视觉塔（ViT 主干）</td><td>FP8</td><td>FP8</td><td>是</td><td>按图像分辨率分桶</td><td>不适用</td><td>保留 FP8/BF16 敏感层，逐层登记</td><td>高：敏感层误入 FP8 即触发</td></tr>\n<tr><td>视觉塔（敏感层子集）</td><td>BF16 或 FP8</td><td>BF16 或 FP8</td><td>否（沿用主干尺度）</td><td>不适用</td><td>不适用</td><td>本行即名单本体</td><td>中：豁免不足则细粒度特征丢失</td></tr>\n<tr><td>Projector（跨模态投影）</td><td>FP8 W8A8</td><td>FP8 W8A8</td><td>是</td><td>按图像分辨率分桶，覆盖视觉 token 分布</td><td>不适用</td><td>无默认豁免，按离群统计决定</td><td>中：视觉 token 分布偏移未覆盖时升高</td></tr>\n<tr><td>LLM 主体</td><td>FP8 W8A8</td><td>FP8 W8A8</td><td>是</td><td>按图像分辨率分桶，视觉 token 与文本 token 混合采样</td><td>FP8</td><td>按层登记，与文本侧共用豁免逻辑</td><td>中：长上下文下与 KV 误差叠加</td></tr>\n<tr><td>KV cache（全局）</td><td>不适用</td><td>不适用</td><td>是（尺度校准）</td><td>按分辨率分桶 + 序列长度分层</td><td>FP8</td><td>不适用</td><td>高：长上下文误差累积</td></tr>\n</tbody>\n</table>\n<p>这张表的工程代价体现在三个口径上。显存侧，视觉塔保留 BF16 敏感层的比例直接决定视觉塔权重占用，豁免越多省得越少；带宽侧，projector 与 LLM 走 FP8 W8A8 后权重读取带宽减半，这是吞吐的主要来源；延迟侧，KV cache 用 FP8 存储使长上下文解码的 KV 读取带宽下降，但校准与反量化引入额外指令，短序列下收益被抵消。举例：一个以高分辨率图像问答为主的服务，若视觉塔敏感层名单登记过窄，细粒度视觉特征在 FP8 下丢失，下游问答准确率下降，此时表里“视觉塔”行的风险等级必须从“高”改为“已触发”，并回退该子集到 BF16。</p>\n\n<h3 id=\"ap-mm-quant-recipe-sec-8\">八 · 阈值：分辨率分桶与离群判定</h3>\n<p>本配方唯一硬阈值是“按图像分辨率分桶校准”。材料未给出具体精度下降数值，因此阈值不写成百分比，而写成口径规则：校准集必须按输入分辨率切分成至少低、中、高三档，每档独立统计激活分布并生成量化尺度；任何一档缺失，该档输入在推理时就落在未统计区间，高分辨率 token 激活离群无法被尺度覆盖，精度塌陷由此发生。</p>\n<p>离群判定可以用一个可执行的伪代码思路表达，不依赖具体数值：对每一分辨率桶，收集该桶内视觉 token 激活的绝对值分布，取分位数作为尺度上界；若某 token 的激活超过该桶上界的固定倍数，则标记为离群并在该桶的尺度计算中单独处理，而不是被平均掉。公式上，尺度可写成：</p>\n<div class=\"formula\">$$ s_b = \\frac{\\max_{x \\in X_b} |x|}{q},\\quad \\text{若 } |x| &gt; k\\cdot s_b \\text{ 则 } x \\text{ 进入离群集合} $$</div>\n<p>其中 \\(b\\) 是分辨率桶，\\(X_b\\) 是该桶校准激活集合，\\(q\\) 是量化格式对应的满量程码点，\\(k\\) 是离群倍数阈值。这个式子的工程含义是：每个桶有自己的尺度，桶间不共享；离群集合不参与尺度平均，避免高分辨率桶的极端值把低分辨率桶的尺度拉爆。</p>\n<p>代价出现在校准阶段而非推理阶段。按分辨率分桶意味着校准数据量与桶数成正比，校准耗时随桶数线性上升；若桶划分过细，校准集覆盖不足反而引入统计噪声。工程判断是桶数控制在个位数，按实际服务输入分辨率分布切分，而不是按理论分辨率枚举。举例：服务同时接收缩略图与整页文档扫描，两档分辨率差异跨数量级，若只用缩略图校准，整页扫描的视觉 token 激活离群未被统计，projector 与 LLM 的 FP8 W8A8 尺度在高分辨率输入下失配，表现为长文档问答后段输出漂移——这正是“单一分辨率校准集覆盖所有输入”这一最常见踩坑的机制。</p>\n\n<h3 id=\"ap-mm-quant-recipe-sec-9\">九 · 敏感层豁免：名单如何登记与验证</h3>\n<p>敏感层名单不是拍脑袋列的，它由两个来源合并：一是视觉塔中承担细粒度特征提取的层，材料明确要求视觉塔保留 FP8/BF16 敏感层；二是校准阶段离群统计中反复越界的层。名单必须逐层登记，不能写成“视觉塔整体豁免”，否则豁免粒度太粗，省不下显存也保不住精度。</p>\n<p>登记口径建议三列：层标识、当前精度、豁免理由。豁免理由只允许两类——“结构敏感”与“离群越界”，前者来自对视觉塔细粒度特征路径的判断，后者来自第二节的离群集合统计。验证方式是消融：把名单内某层放回 FP8，观察下游问答准确率是否下降；若下降，该层留在名单内，风险等级上调。这一步的代价是额外的评测轮次，但它把“敏感层被一并 FP8 量化，细粒度视觉特征丢失”这一失败模式挡在上线之前。</p>\n<p>工程代价要算清楚：每豁免一层，该层权重与激活按 BF16 存储，视觉塔显存占用上升，视觉塔前向的矩阵乘吞吐下降。因此名单不是越长越安全，而是“最小充分集”——刚好覆盖结构敏感与离群越界的层，其余层留在 FP8。举例：某视觉塔在 patch embedding 之后的若干层对高频纹理敏感，这些层若走 FP8，细粒度视觉特征在量化噪声下丢失，下游问答准确率下降；把这几层登记进名单并回退 BF16，视觉塔显存上升但整体仍在预算内，因为 projector 与 LLM 的 FP8 W8A8 已经把大头省下来了。</p>\n\n<h3 id=\"ap-mm-quant-recipe-sec-10\">十 · KV cache FP8：长上下文误差累积的口径</h3>\n<p>KV cache 以 FP8 存储是本配方的固定项，但它带来一个跨模块风险：长上下文误差累积。表里 KV cache 行的风险等级标为“高”，触发条件是序列长度超过校准分层上界。口径上，KV cache 的尺度校准必须按分辨率分桶加序列长度分层，两者缺一不可——分辨率决定视觉 token 的激活量级，序列长度决定误差累积的步数。</p>\n<p>误差累积的机制可以写成递推思路：每步解码写入新的 KV 并以 FP8 存储，读取时反量化；单步误差有界，但注意力输出对历史 KV 的依赖使误差随步数叠加。伪代码上，校准阶段对每个（分辨率桶，长度层）组合统计 KV 激活的绝对值分位数，生成该组合的尺度；推理阶段按输入所属组合选取尺度，而不是全局单一尺度。公式上，累积误差上界与步数 \\(T\\) 和单步量化误差 \\(\\epsilon\\) 的关系可定性写成：</p>\n<div class=\"formula\">$$ E_T \\lesssim \\sum_{t=1}^{T} \\epsilon_t,\\quad \\epsilon_t = f(\\text{尺度失配}) $$</div>\n<p>代价在解码延迟与显存两侧同时出现。显存侧，FP8 KV cache 把 KV 存储减半，这是长上下文能跑起来的前提；延迟侧，反量化与尺度选取引入额外操作，短序列下这部分开销占比高，长序列下被带宽节省抵消。工程判断是：多轮多模态对话必须按长度分层校准，且在后段输出漂移出现时优先检查 KV 尺度是否落在未校准的长度层。举例：多轮图文对话中，前几轮图像分辨率低、序列短，KV 尺度匹配良好；后几轮叠加高分辨率图像与长历史，KV 激活量级跳变，若长度分层未覆盖，FP8 存储后长上下文误差累积，多轮多模态对话后段输出漂移——这与“KV cache 量化后长上下文误差累积”这一踩坑完全对应。</p>\n\n<h3 id=\"ap-mm-quant-recipe-sec-11\">十一 · 风险等级判定与回退路径</h3>\n<p>表里最后一列“精度塌陷风险等级”不是装饰，它决定回退顺序。判定口径三条：第一，校准桶是否覆盖服务实际输入的分辨率分布，缺一档即高风险；第二，敏感层名单是否经过消融验证，未验证即中风险；第三，KV cache 长度分层是否覆盖服务最长上下文，未覆盖即高风险。三条全满足才可标“低”。</p>\n<p>回退路径按代价从低到高排：先扩校准桶，再补敏感层豁免，最后回退 KV cache 到更高精度存储。这个顺序的理由是代价结构——扩校准桶只增加离线校准成本，不影响推理吞吐；补敏感层豁免增加视觉塔显存、降低视觉塔吞吐；回退 KV cache 直接吃掉长上下文显存收益，代价最大。工程上应把前两步做成常规动作，第三步作为熔断。举例：上线前评测发现高分辨率桶问答准确率下降，先检查校准桶是否缺高档，补上后若恢复则不动敏感层名单；若仍下降，再把离群越界的层加入豁免名单；只有当前两步都无效且漂移出现在长上下文后段时，才回退 KV cache 精度。</p>\n<p>风险等级还要与容量规划挂钩。高风险模块在容量规划里必须预留回退后的显存与带宽，否则熔断时没有余量。具体做法是把视觉塔敏感层豁免后的显存占用与 KV cache 回退后的显存占用同时计入峰值预算，而不是只按最优配方算。这一步的代价是容量看起来更紧，但它让回退路径真实可用，而不是纸面预案。</p>\n\n<h3 id=\"ap-mm-quant-recipe-sec-12\">十二 · 速查表的使用顺序与判据</h3>\n<p>这张表的使用顺序是自下而上填、自上而下审。填表时先定 KV cache 行，因为它跨模块且风险最高；再定视觉塔敏感层名单，因为它决定视觉塔两行的拆分；最后填 projector 与 LLM 行，这两行格式固定为 FP8 W8A8，只需确认校准桶覆盖。审表时反过来：先看视觉塔敏感层是否逐层登记、是否有消融记录，再看校准桶是否覆盖服务分辨率分布，最后看 KV cache 长度分层是否覆盖最长上下文。</p>\n<p>判据只有一条是可执行的：任何一行若“是否校准”为“是”而“校准数据分桶方式”写成“全局单一分桶”，该行直接判不合格，因为这与本配方的核心口径冲突。同理，视觉塔行若“敏感层名单”写成“整体豁免”或“无”，判不合格，因为豁免粒度不足。这两条判据把两个最常见踩坑——单一分辨率校准集、敏感层被一并 FP8 量化——变成表内可检查的字段，而不是靠评审记忆。</p>\n<p>最后落在工程判断上：速查表的价值不在列全，而在每列都有可核对的来源。权重与激活精度来自配方定义，校准分桶来自分辨率分布，敏感层名单来自消融记录，风险等级来自覆盖性检查。把这四类来源钉在表后作为附件，表就从一张纸变成可审计的决策记录；缺任何一类来源，对应行在评审时按未验证处理，不得进入容量规划。</p>\n<h3 id=\"ap-mm-quant-recipe-sec-13\">十三 · 阈值不是常数，是分桶边界</h3>\n<p>多模态量化里被反复引用的“阈值”几乎都不是一个全局标量，而是一组分桶边界。视觉输入的激活分布随分辨率剧烈变化：同一张图缩放到不同边长，patch 数量按平方增长，视觉塔最后一层输出的激活极值位置与幅度都会迁移。因此配方中的第一个工程阈值是<strong>分辨率分桶的切点</strong>——把校准集按输入边长切成若干桶，每桶独立统计激活的百分位截断值（如 99.9% 分位），而不是用一张全局校准表覆盖所有输入。切点怎么定：取部署侧真实流量里分辨率的长尾分布，把累计占比超过某个比例（工程上常用“覆盖绝大多数请求”的定性判断，材料未给具体数值）的边长区间各设一桶，桶内样本量必须足以让百分位统计稳定。</p>\n<p>第二个阈值是<strong>离群通道判定线</strong>。对每个桶统计各通道激活幅度的分布，把幅度显著偏离桶内中位数的通道标记为离群通道；这些通道在 FP8 W8A8 下会被同一缩放因子压掉有效位。判定线不是拍脑袋的倍数，而是用“该通道被纳入统一缩放后，桶内重构误差的相对增幅”来定：把候选通道逐个并入统一缩放，观察桶级误差曲线的拐点，拐点左侧的通道可以合并，右侧必须走敏感层豁免。这个测量只需在校准集上做前向，不需要端到端评测，代价是每个桶一次全量校准前向的显存与算力开销——桶越多，校准阶段占用的 GPU 小时越多，这是配方上线前一次性成本，与在线延迟无关。</p>\n<div class=\"formula\">$$\\text{err}_b(s)=\\frac{\\lVert W_b-\\hat W_b(s)\\rVert_F}{\\lVert W_b\\rVert_F},\\quad s^\\*=\\arg\\min_s\\{\\text{err}_b(s)\\le \\tau\\}$$</div>\n<p>其中 $b$ 为分辨率桶，$s$ 为缩放因子候选，$\\tau$ 为可接受的桶级相对误差上限。$\\tau$ 的取法决定了敏感层名单的长度：$\\tau$ 收紧，豁免层变多，视觉塔保留 BF16/FP8 的层数上升，显存占用与 MMA 吞吐随之变化。举例：一个以高分辨率文档扫描件为主的业务，若把 $\\tau$ 定得与低分辨率自然图像桶相同，会迫使大量通道进入豁免名单，视觉塔权重显存回涨、tcgen05 路径上 FP8 的吞吐优势被削弱；正确做法是给高分辨率桶单独放宽 $\\tau$ 并配套更细的通道分组缩放。</p>\n\n<h3 id=\"ap-mm-quant-recipe-sec-14\">十四 · 敏感层名单的量化判据</h3>\n<p>“视觉塔保留 FP8/BF16 敏感层”这句话在工程上必须落成一张可执行的名单，判据不能是层号直觉。可测的判据是<strong>逐层替换后的桶级输出漂移</strong>：固定其他层精度，把候选层从 BF16 换成 FP8，测量该桶校准集上视觉塔输出（进入 projector 之前的特征）的相对偏差，以及 projector 输出端的偏差放大倍数。细粒度视觉特征对下游问答的贡献集中在少数层，这些层的偏差会在 projector 处被放大，因此判据应取“projector 端偏差”而非“视觉塔端偏差”作为排序依据。</p>\n<ul>\n<li>测量方法：逐层单变量替换，每层一次校准前向；桶内取最大偏差而非平均偏差，因为离群样本决定塌陷风险。</li>\n<li>名单粒度：按 transformer block 而非按算子，避免同一 block 内权重与激活精度不一致带来的额外缩放对齐开销。</li>\n<li>代价：每多保留一层 BF16，视觉塔权重显存按该层参数量线性上升，且该层无法走 FP8 MMA，视觉塔前向延迟中该层占比上升；名单过长会把视觉塔变成吞吐瓶颈，抵消 LLM 侧 W8A8 的收益。</li>\n</ul>\n<p>具体例子：某配方在低分辨率桶上测得所有层替换偏差均在容差内，于是名单为空；同一名单直接用于高分辨率桶时，浅层细粒度特征层偏差被 projector 放大，问答准确率下降。这说明敏感层名单必须<strong>按桶生成</strong>，而不是全局一份——这正是“按图像分辨率分桶校准”在敏感层维度上的直接推论。</p>\n\n<h3 id=\"ap-mm-quant-recipe-sec-15\">十五 · KV cache FP8 的误差累积怎么测</h3>\n<p>KV cache 以 FP8 存储的阈值问题不在单步误差，而在<strong>多轮多模态对话的误差累积</strong>。可测的量是“后段输出漂移”：构造固定前缀（含图像 token）的多轮对话，逐轮记录同一追问的答案与 BF16 KV 基线的差异，观察差异随轮数/上下文长度的增长斜率。测量时必须把视觉 token 与文本 token 分开统计，因为视觉 token 的激活分布由分辨率桶决定，其 FP8 量化误差与文本 token 不同源。</p>\n<div class=\"formula\">$$\\Delta_n=\\lVert y_n^{\\text{fp8}}-y_n^{\\text{bf16}}\\rVert,\\quad \\text{slope}=\\frac{\\Delta_{n+k}-\\Delta_n}{k}$$</div>\n<p>工程判据：斜率在可接受范围内平坦，则 FP8 KV 可用于该桶；斜率随上下文长度上升明显，则对视觉 token 段采用更高精度存储或对 KV 缩放因子做分段校准。代价侧要算清两笔账：FP8 KV 把 cache 显存减半，直接决定单卡可承载的并发会话数与最大上下文；但若为抑制漂移而对部分 token 段回退精度，显存收益被部分抵消，且混合精度的 cache 读写路径增加带宽开销。举例：长上下文多模态检索场景中，图像 token 占比高，若整段 cache 统一 FP8，后段追问漂移随轮数累积；把视觉 token 段单独提精度后，漂移斜率被压平，代价是 cache 显存回升，容量规划需按混合精度重新计算每会话字节数。</p>\n\n<h3 id=\"ap-mm-quant-recipe-sec-16\">十六 · 校准集覆盖度的测量</h3>\n<p>最常见踩坑是单一分辨率校准集覆盖所有输入。要把它变成可测量的工程项，需定义<strong>覆盖度指标</strong>：对部署流量的分辨率分布做直方图，检查每个桶的校准样本数是否与该桶的流量占比匹配；不匹配的桶标记为“未覆盖桶”。未覆盖桶在量化后不会立刻报错，而是在高分辨率输入上出现激活离群未被统计，表现为精度塌陷——这类故障只在特定输入上复现，排查成本极高。</p>\n<ul>\n<li>测量方法：离线采样一段真实流量（脱敏后）统计分辨率分布，与校准集分布做逐桶比对；比对结果直接写进速查表的“校准数据分桶方式”列。</li>\n<li>补充测量：对每个桶单独做留出集验证，报告桶级而非全局的精度指标；全局指标会被大占比桶掩盖小桶塌陷。</li>\n<li>代价：分桶校准使校准阶段的前向次数与桶数成正比，校准集存储与预处理（解码、缩放、归一化）的 CPU 侧开销同步上升；桶数过细会让每个桶样本不足，百分位统计噪声反而增大，因此桶数与桶内样本量是一对需要共同确定的参数。</li>\n</ul>\n<p>具体例子：校准集只含低分辨率图像时，高分辨率桶的离群通道从未进入统计，统一缩放因子按低分辨率分布定出，高分辨率 token 激活被截断，视觉特征丢失，下游问答准确率下降。修复不是调缩放因子，而是补采高分辨率桶样本并重跑该桶的通道判定。</p>\n\n<h3 id=\"ap-mm-quant-recipe-sec-17\">十七 · 把阈值写进速查表的可执行形式</h3>\n<p>速查表的每一行都应携带可复核的数字或测量口径，否则阈值无法交接给运维。对“模块名称/权重精度/激活精度/是否校准/校准数据分桶方式/KV cache 精度/敏感层名单/精度塌陷风险等级”这组列，工程上要补的是每格的<strong>来源标注</strong>：分辨率桶切点、$\\tau$ 取值、敏感层判据（projector 端偏差上限）、KV 漂移斜率容差、覆盖度比对结果。风险等级不是主观评级，而由三项测量共同决定——未覆盖桶是否存在、敏感层名单是否按桶生成、KV 漂移斜率是否平坦。</p>\n<table class=\"mini\"><thead><tr><th>测量项</th><th>测量对象</th><th>判据形式</th><th>系统代价</th></tr></thead><tbody><tr><td>桶切点</td><td>流量分辨率直方图</td><td>桶样本量与流量占比匹配</td><td>校准前向次数随桶数上升</td></tr><tr><td>离群通道判定线</td><td>桶内通道幅度分布</td><td>重构误差拐点</td><td>豁免层增加，视觉塔显存与延迟上升</td></tr><tr><td>敏感层名单</td><td>逐层替换的 projector 端偏差</td><td>桶内最大偏差上限</td><td>BF16 层数增加，FP8 MMA 收益下降</td></tr><tr><td>KV 漂移斜率</td><td>多轮对话后段输出</td><td>斜率平坦性</td><td>cache 显存减半 vs 混合精度带宽开销</td></tr></tbody></table>\n<p>落地判断：当一个桶同时满足覆盖度匹配、敏感层名单按桶生成、KV 漂移斜率平坦，该桶可整段走 FP8 W8A8 与 FP8 KV；任一条件不满足，就把该桶的对应模块回退到 BF16 或分段提精度，并在速查表的风险等级列标注触发条件。这套判据的代价是校准与验证阶段的 GPU 小时，收益是把“精度塌陷”从上线后的随机故障变成校准期的可测项——对多模态推理系统而言，后者才是真正的容量确定性来源。</p>\n\n<h3 id=\"ap-mm-quant-recipe-sec-18\">十八 · 分辨率分桶校准的失效边界与量化代价核算</h3>\n<p>按图像分辨率分桶校准并非把校准集切碎就行，桶边界本身就是工程阈值。视觉编码器的 token 数随分辨率呈平方增长，若把 448×448 与 1024×1024 混进同一桶，高分辨率样本的激活离群值会被低分辨率样本的统计量稀释，校准出的 scale 偏小，量化时直接削顶。可操作的做法是按 token 数而非像素面积分桶，令桶边界落在 token 数跨越 2 的幂次的位置，并在每桶内单独统计激活的绝对最大值与分位数。判据可写成：若某桶内激活绝对值最大值超过相邻低桶同一分位数的倍数超过预设倍数，则该桶必须独立校准，不得与低桶合并。这个倍数没有给定数值，只能靠离线扫描确定——逐桶量化后跑同一批高分辨率评测样本，找到精度开始塌陷的拐点，把拐点对应的倍数作为阈值写进配方。</p>\n<p>校准数据量本身也有下限约束。每桶样本数不足时，离群值统计不稳定，scale 在不同校准轮次间抖动，表现为同一模型两次部署精度不一致。测量方法是固定桶边界，把每桶样本数从少量逐步增加，观察量化后输出与 BF16 参考输出的相对误差曲线，曲线进入平台区的最小样本数即为该桶的校准下限。代价在显存与带宽：FP8 W8A8 的 projector 与 LLM 权重显存约为 BF16 的一半，但校准阶段要同时驻留参考精度激活与量化激活，峰值显存反而高于推理态；KV cache 以 FP8 存储把每 token 的 KV 占用减半，直接换来可容纳的并发序列数或上下文长度翻倍，代价是长上下文下误差沿序列累积，多轮多模态对话后段输出漂移，需在配方里标注 KV cache 量化的最大可信上下文长度。</p>\n<p>敏感层豁免是另一条边界。视觉塔中被豁免的层保持 FP8/BF16，其余层走 FP8，豁免名单必须与分辨率分桶联动：高分辨率桶下细粒度视觉特征更依赖少数层，若这些层被一并量化，下游问答准确率下降且无法靠校准挽回。系统代价体现在 kernel 调度上，混合精度使视觉塔前向出现精度切换点，切换点两侧的 kernel 不能融合，端到端延迟增加，需按切换点数量估算额外开销。下表给出配方速查表的关键列，用于把上述阈值固化到部署配置中。</p>\n<table class=\"mini\"><thead><tr><th>模块</th><th>权重</th><th>激活</th><th>校准分桶</th><th>KV 精度</th><th>塌陷风险</th></tr></thead><tbody><tr><td>视觉塔</td><td>FP8/BF16 敏感层豁免</td><td>FP8</td><td>按 token 数分桶</td><td>—</td><td>高（敏感层误量化）</td></tr><tr><td>projector</td><td>FP8</td><td>FP8</td><td>随视觉桶</td><td>—</td><td>中</td></tr><tr><td>LLM</td><td>FP8</td><td>FP8</td><td>随视觉桶</td><td>FP8</td><td>中（长上下文累积）</td></tr></tbody></table>\n<div class=\"formula\">$$ \\text{桶内 scale} = \\frac{\\max_{x\\in B}|x|}{\\text{FP8\\_max}},\\quad B=\\{\\text{token 数落入同一幂次区间}\\} $$</div>\n<p>测量方法应固定为三段：先用 BF16 参考跑分桶评测集得到基线，再逐桶量化并对比同一桶内样本的输出偏差，最后做跨桶泛化测试——用低桶校准的 scale 去量化高桶样本，观察偏差是否超出阈值。跨桶泛化失败即证明分桶不可合并，这是配方中最容易被忽略的验证步骤。KV cache 侧的测量则要沿序列位置切片统计误差，定位误差开始加速累积的位置，据此设定 FP8 KV 的上下文上限，超过上限的请求回退到更高精度存储，用显存换稳定。</p>\n<h3 id=\"ap-mm-quant-recipe-sec-19\">十九 · 踩坑清单：三类失败模式的机理与代价</h3>\n<p>多模态量化配方在纸面上只有三行——视觉塔保留敏感层、projector与LLM走FP8 W8A8、KV cache存FP8——但落地时几乎总在这三行上翻车。第一类失败是<strong>校准集分辨率单一</strong>：用一批低分辨率图像跑完校准，统计出的激活范围窄而平滑，高分辨率输入进来后，视觉token的激活分布出现长尾离群，FP8的E4M3尾数只有3位，离群值一旦超出校准得到的scale，就被截断或压成粗粒度台阶，精度塌陷在需要细粒度定位的任务上最先暴露。第二类是<strong>视觉塔敏感层被无差别量化</strong>：视觉塔里承担细粒度特征提取的层对权重扰动远比LLM的线性层敏感，把这些层一并塞进FP8，等于在特征进入projector之前就把信息削掉一层，下游问答准确率下降但loss曲线看不出来。第三类是<strong>KV cache FP8的长上下文误差累积</strong>：单轮短对话里FP8 KV的误差可以忽略，但多轮多模态对话中，每一轮写入的KV都带着量化误差，后段解码时注意力在这些带噪历史上反复加权，输出漂移随轮次单调增长。</p>\n<p>三类坑的共同点是：它们在离线perplexity或单轮benchmark上都不显著，只在真实输入分布和长会话里放大。工程上必须把它们当作<em>分布偏移问题</em>而非数值问题处理。用代价语言表述：第一类坑的代价是<strong>精度塌陷集中在高分辨率桶</strong>，而高分辨率桶往往正是产品的主路径；第二类坑的代价是<strong>视觉塔算力占比不变但有效信息减少</strong>，等于白花了视觉编码的FLOPs；第三类坑的代价是<strong>KV显存降了、但有效上下文长度缩水</strong>，容量规划里按FP8算出的并发数在实际SLO下不可达。</p>\n<div class=\"formula\">$$\\text{err}_{\\text{out}} \\approx \\sum_{t=1}^{T} \\left\\| \\hat{a}_t - a_t \\right\\| \\cdot w_t,\\quad \\hat{a}_t = \\text{dequant}(\\text{quant}(a_t; s_{\\text{cal}}))$$</div>\n<p>式中的$s_{\\text{cal}}$来自校准集；若校准集只覆盖低分辨率，$s_{\\text{cal}}$偏小，高分辨率token的$a_t$被截断，误差按注意力权重$w_t$加权后进入输出。这解释了为什么坑一和坑三会叠加：校准偏差让每步误差变大，长上下文让误差被累加$T$次。</p>\n\n<h3 id=\"ap-mm-quant-recipe-sec-20\">二十 · 检查顺序：从数据分布到数值路径的固定排查链</h3>\n<p>排查不能按模块随机试，必须按“先分布、后数值、再会话”的顺序走，因为后一环的误差会掩盖前一环的信号。第一步查<strong>校准集的分辨率覆盖</strong>：把线上真实输入的图像分辨率做直方图，与校准集直方图对齐，确认每个分辨率桶都有足够样本，尤其是高分辨率长尾桶。这一步的产出是分桶清单，直接对应速查表里的“校准数据分桶方式”列。第二步查<strong>敏感层豁免名单是否生效</strong>：不要只看配置文件里写了哪些层名，要在量化后的模型上验证这些层确实以BF16/FP8高精度运行——常见错误是层名匹配规则写错，豁免名单静默失效，视觉塔被整体量化。第三步查<strong>KV cache的写入路径</strong>：确认FP8量化发生在写入时还是读取时，scale是按头还是按token，长上下文下scale是否会因分布漂移而失配。</p>\n<p>每一步都要有可观测的判据，而不是“看起来没问题”。第一步的判据是分桶后的激活最大值与校准scale的比值，高分辨率桶的比值明显大于1即为漏校准。第二步的判据是对同一张图做高精度与量化两次前向，比较视觉塔输出特征的余弦相似度，若豁免层生效，相似度应集中在高位；若整体量化，相似度会在细粒度区域掉下来。第三步的判据是构造多轮多模态对话，逐轮记录输出与高精度基线的偏差，观察偏差是否随轮次单调上升。</p>\n<table class=\"mini\"><thead><tr><th>检查步</th><th>对象</th><th>判据</th><th>失败代价</th></tr></thead><tbody><tr><td>1</td><td>校准集分辨率直方图</td><td>高分辨率桶激活最大值/scale &gt; 1</td><td>高分辨率精度塌陷</td></tr><tr><td>2</td><td>敏感层豁免生效性</td><td>视觉塔输出特征余弦相似度</td><td>细粒度特征丢失</td></tr><tr><td>3</td><td>KV cache FP8写入路径</td><td>多轮偏差随轮次单调上升</td><td>长会话输出漂移</td></tr></tbody></table>\n<p>顺序不能颠倒：如果先查KV，长会话偏差里混着校准偏差和视觉塔量化误差，无法归因；先把分布和敏感层修好，KV的误差信号才干净。这个顺序本身就是一条工程判断——<strong>量化误差的排查必须从误差源的上游往下游走</strong>。</p>\n\n<h3 id=\"ap-mm-quant-recipe-sec-21\">二十一 · 分桶校准的落地：分辨率桶的划分与scale策略</h3>\n<p>按图像分辨率分桶不是把分辨率离散成几个档位就完事，桶的划分要跟视觉塔的patch切分和token数挂钩。视觉塔把图像切成固定patch，分辨率越高token数越多，激活分布的形状随token数变化——低分辨率下token少、激活集中，高分辨率下token多、出现离群通道的概率上升。因此桶的边界应选在token数发生明显跳变的位置，而不是等距切分辨率。每个桶独立统计激活范围，得到各自的scale；推理时按输入分辨率选桶，而不是全局共用一个scale。</p>\n<p>这里有一个容易忽略的代价：分桶校准意味着<strong>校准阶段的计算量和存储量随桶数线性增长</strong>，每个桶都要跑一遍校准前向并保存scale表。桶数太少覆盖不住长尾，桶数太多则校准成本上升且小桶样本不足导致scale估计噪声大。工程上的折中是让桶的数量与线上分辨率分布的模态数匹配，长尾桶用更大样本量，头部桶可以粗一些。</p>\n<div class=\"formula\">$$s_b = \\max_{x \\in \\mathcal{D}_b} \\left| a(x) \\right| / q_{\\max},\\quad b = \\text{bucket}(\\text{res}(x))$$</div>\n<p>式中$\\mathcal{D}_b$是第$b$个分辨率桶的校准样本，$q_{\\max}$是FP8格式的最大可表示值。关键是$\\max$必须在桶内取，跨桶取全局最大值会让低分辨率桶的scale过大、有效位数浪费，而高分辨率桶仍可能不够。举例：同一套配方在低分辨率桶上校准出的scale用于高分辨率输入时，离群通道被截断，视觉token进入projector后特征失真，下游问答在需要读取小字或细部结构的样本上先崩——这正是“按图像分辨率分桶校准”这条经验数字背后的机制，而不是一句口号。</p>\n\n<h3 id=\"ap-mm-quant-recipe-sec-22\">二十二 · 敏感层豁免与KV cache的联动检查</h3>\n<p>敏感层豁免和KV cache FP8是两个独立开关，但它们在同一条数值路径上耦合。视觉塔的敏感层若被正确豁免，进入projector的视觉token分布更接近高精度基线，projector的FP8 W8A8校准scale也更稳；反过来，若视觉塔被整体量化，projector收到的token分布已经偏移，此时projector的校准scale是在偏移分布上统计的，KV cache再叠加FP8，误差在两层量化上串联。检查时必须把这两个开关放在一起看：先确认视觉塔豁免生效，再确认projector的校准输入来自豁免后的视觉塔输出，最后确认KV cache的FP8 scale是在正确的激活分布上统计的。</p>\n<p>KV cache的FP8存储还有一个隐性代价：<strong>解码阶段的注意力读取带宽降了，但反量化在SM上引入额外指令</strong>。Blackwell的tcgen05路径上，KV以FP8存储意味着注意力计算前要做反量化或直接在FP8域做MMA，前者增加寄存器压力和指令数，后者要求注意力算子支持混合精度。若框架的注意力kernel没有为FP8 KV做专门路径，反量化开销会吃掉显存带宽收益，表现为长上下文下吞吐不升反降。这是“KV cache量化后长上下文误差累积”之外的另一半代价，检查清单里必须包含kernel路径确认。</p>\n<ul><li>确认视觉塔敏感层以BF16/FP8高精度运行，层名匹配规则经过实测验证；</li><li>确认projector的校准输入取自豁免后的视觉塔输出，而非量化后的输出；</li><li>确认KV cache FP8的scale按头或按token统计，且长上下文下不失配；</li><li>确认注意力kernel存在FP8 KV的原生路径，否则反量化开销抵消带宽收益；</li><li>确认多轮对话下逐轮偏差可观测，偏差随轮次单调上升即触发回滚评估。</li></ul>\n\n<h3 id=\"ap-mm-quant-recipe-sec-23\">二十三 · 回滚方案：分级降级而非一刀切</h3>\n<p>回滚不是把整套配方退回BF16，而是按失败模式分级降级，因为三类坑的修复成本差异很大。第一级回滚只动校准：保留FP8 W8A8与FP8 KV，重新按分辨率分桶校准，补足高分辨率桶样本。这一级代价最小，不改变显存与吞吐画像，只增加校准阶段的计算。第二级回滚动敏感层：把视觉塔的豁免名单扩大，把细粒度特征层从FP8拉回BF16，代价是视觉塔权重显存上升、视觉编码的MMA吞吐下降，但LLM与KV仍保持FP8。第三级回滚动KV：把KV cache从FP8退回BF16，代价是KV显存翻倍、并发容量按比例缩水，这是容量规划里必须预留的余量。</p>\n<p>分级回滚的关键是<strong>每一级都有独立的触发判据和独立的代价核算</strong>，而不是等精度崩了再整体回退。触发判据沿用第二节的检查链：高分辨率桶激活越界触发第一级；视觉塔特征相似度掉下阈值触发第二级；多轮偏差单调上升且第一二级已修复触发第三级。回滚顺序与检查顺序相反——从下游往上游退，因为下游的回滚代价通常更可控，且能快速恢复SLO。</p>\n<table class=\"mini\"><thead><tr><th>级别</th><th>动作</th><th>触发判据</th><th>主要代价</th></tr></thead><tbody><tr><td>一级</td><td>重做分桶校准</td><td>高分辨率桶激活越界</td><td>校准计算量上升</td></tr><tr><td>二级</td><td>扩大敏感层豁免</td><td>视觉塔特征相似度下降</td><td>视觉塔显存与算力上升</td></tr><tr><td>三级</td><td>KV cache退回BF16</td><td>多轮偏差单调上升</td><td>KV显存翻倍、并发缩水</td></tr></tbody></table>\n<p>回滚方案必须在上线前就写进容量规划：如果三级回滚是可能路径，那么按FP8 KV算出的最大并发数不能作为SLO承诺的基线，必须留出KV显存翻倍的余量，否则回滚时不是精度问题而是直接OOM。这条判断把量化配方和容量规划绑在一起——<strong>回滚余量是配方的一部分，不是事后补丁</strong>。</p>\n<p>最后落到一个具体机制上：把分桶校准的scale表、敏感层豁免名单、KV FP8的scale策略三者做成一个可版本化的配置单元，每次变更都跑一遍第二节的三步检查链，任一步判据不满足就按第五节的分级表回退到上一版本。这样踩坑不再是线上事故，而是配置变更时被拦截的检查项。</p>\n\n<h3 id=\"ap-mm-quant-recipe-sec-24\">二十四 · 分辨率分桶校准的失效边界与回滚判据</h3>\n<p>这套配方的精度保障几乎全部押在“按图像分辨率分桶校准”上，因此它的失效条件也集中在这里。分桶的本质是让每个桶的激活统计量（尤其是每通道的绝对最大值，即离群因子）覆盖该分辨率区间内真实出现的分布：若某桶校准集只含低分辨率样本，而线上高分辨率图像产生的视觉 token 激活离群值远超校准观测到的范围，FP8 的缩放因子就会被系统性低估，激活被截断，精度塌陷并非渐变而是断崖式。工程上应把桶边界与视觉塔的 patch 网格对齐，而不是按像素宽高随意切分，因为激活离群程度由 token 序列长度与感受野共同决定。判断某个桶是否“校准不足”，可看该桶内激活的动态范围比：</p>\n<div class=\"formula\">$$ r_b = \\frac{\\max_{x\\in b}\\lVert x\\rVert_\\infty}{\\mathrm{median}_{x\\in b}\\lVert x\\rVert_\\infty} $$</div>\n<p>当 $r_b$ 明显高于相邻桶时，说明该桶存在未被充分采样的离群通道，应扩充该桶校准样本或对该桶单独放宽缩放粒度，而不是全局调大缩放因子——后者会牺牲低分辨率桶的有效位宽。</p>\n<p>第二类失效来自 KV cache 的 FP8 存储。KV 量化的误差不会在单轮内爆发，而是在多轮多模态对话中随上下文增长逐步累积：每轮写入的 K/V 都带一次量化误差，后续注意力读取又在此误差基础上叠加，后段输出漂移表现为对早期图像细节的“遗忘”而非明显乱码。检查顺序应是先验视觉塔与 projector（单帧前向即可暴露截断），再验 LLM 权重侧，最后才开 KV cache FP8；顺序颠倒会让 KV 误差与激活截断混在一起，无法归因。回滚方案要分级：视觉塔敏感层一旦被误纳入 FP8，细粒度特征丢失不可通过重新校准挽回，必须按敏感层名单逐层回退到 BF16/FP8 混合；KV cache 则可先回退到 BF16 存储、保留权重与激活的 FP8，用显存换精度，代价是 KV 容量减半、可并发序列数下降，需同步下调批调度上限以免触发换出。</p>\n<table class=\"mini\"><thead><tr><th>检查项</th><th>失效信号</th><th>回滚动作</th><th>系统代价</th></tr></thead><tbody><tr><td>分辨率分桶覆盖</td><td>高分辨率桶 $r_b$ 异常高</td><td>补采该桶校准集</td><td>校准离线成本上升，不影响线上延迟</td></tr><tr><td>视觉塔敏感层</td><td>下游问答细粒度属性错误</td><td>敏感层回退 BF16</td><td>视觉塔显存与带宽上升，预填变慢</td></tr><tr><td>KV cache FP8</td><td>多轮后段输出漂移</td><td>KV 回退 BF16</td><td>KV 容量减半，并发序列数下降</td></tr></tbody></table>\n<p>把这三项写进速查表的“精度塌陷风险等级”列时，应按“不可逆性”而非“发生概率”排序：视觉塔敏感层误量化属于不可逆，优先级最高；分辨率分桶不足可通过离线补采修复，属可逆；KV cache 误差累积可在线切换精度，属可即时回滚。工程判断的落点是：任何一次配方变更都必须先在最高分辨率桶与最长多轮会话两个极端场景上跑回归，因为这两个场景正是离群激活与误差累积唯一会同时显形的交集。</p>\n<h3 id=\"ap-mm-quant-recipe-sec-25\">二十五 · 上游依赖：配方吃的是谁的数据契约</h3>\n<p>多模态量化配方不是独立成立的模块，它把三个上游条目的输出当作输入契约。第一条是图像视频预处理工具链：归一化方式、resize 插值、通道顺序、像素值域（0–1 还是 0–255）决定了视觉塔第一层激活的分布形态，量化校准统计的正是这个分布。预处理若在上线前后发生版本漂移——比如从双线性换成双三次、从中心裁剪换成短边缩放——校准集统计到的激活直方图就与实际推理流不匹配，W8A8 的 scale 与 zero-point 全部偏置。第二条是视觉token压缩：压缩比决定了进入 projector 的 token 数量与空间排布，而 projector 的 FP8 W8A8 校准需要按 token 分布取样；压缩策略改变后，token 的通道统计随之改变，原先的校准表失效。第三条是视觉编码器术语表所定义的敏感层边界：哪些层属于细粒度特征提取、哪些层可以整体降精度，这份名单是配方中“敏感层豁免”一列的直接来源。</p>\n<p>依赖关系的工程含义是：量化配方的版本号必须与预处理版本、压缩版本、敏感层名单三者绑定，任何一项变更都触发重新校准。代价落在发布流程上——一次预处理参数调整会带来一轮全分辨率分桶校准的 GPU 机时开销，校准本身需要跑前向统计激活范围，属于吞吐型负载而非延迟敏感负载，可以放在离线队列里做，但不能省。判断规则很直接：预处理或压缩的变更若改变了进入视觉塔的张量形状或值域，就必须重跑校准；若只改变了批组织方式而不改变单样本张量，校准表可复用。</p>\n<div class=\"formula\">$$\\text{calib-valid} = f(\\text{preprocess ver},\\ \\text{compress ver},\\ \\text{sensitive-list ver})$$</div>\n<p>举例：预处理把短边缩放的基准从固定值改为按长宽比自适应，高分辨率输入的有效像素覆盖发生变化，原先按分辨率分桶的校准集里高分辨率桶的样本不再代表真实输入，此时即便敏感层名单未动，也必须重建高分辨率桶。这就是上游依赖的具体形态——不是接口依赖，而是统计依赖。</p>\n\n<h3 id=\"ap-mm-quant-recipe-sec-26\">二十六 · 与视觉塔显存溢出的耦合：精度策略换显存</h3>\n<p>视觉塔显存溢出条目处理的是激活峰值与中间张量驻留问题，量化配方在此处提供一个可调的交换维度：把视觉塔的非敏感层从 BF16 降到 FP8，权重显存减半，同时矩阵乘的输入输出张量位宽下降，激活峰值随之下降。但这条路径有明确边界——敏感层必须保留 FP8/BF16 混合而非统一 FP8，因为细粒度视觉特征在低比特下丢失后，下游问答准确率下降，而这个下降不会在视觉塔自身的重建误差指标上暴露。因此配方与显存溢出条目的接口是一张分层精度表：按层类型给出位宽，而不是给一个全局位宽。</p>\n<p>代价要算清楚。视觉塔的显存占用由权重、激活峰值、以及分桶批处理带来的多份中间缓冲组成。降精度减少的是权重与激活两部分，但对高分辨率桶，激活峰值由 token 数量主导，位宽减半带来的绝对节省与 token 数的平方关系并不成立——token 数翻倍时激活峰值大致线性增长，位宽减半则把这条曲线整体下移一个固定比例。工程判断是：当溢出由权重驻留主导（多模型共存、多副本），降精度收益直接；当溢出由单张大图的激活峰值主导，应先走视觉token压缩或分桶限流，再考虑降精度，否则会在敏感层上被迫让步。</p>\n<table class=\"mini\"><thead><tr><th>溢出主因</th><th>首选手段</th><th>量化配方角色</th></tr></thead><tbody><tr><td>权重驻留（多副本/多模型）</td><td>视觉塔非敏感层 FP8</td><td>直接减半权重占用</td></tr><tr><td>高分辨率激活峰值</td><td>token 压缩、分桶限流</td><td>辅助下移峰值曲线</td></tr><tr><td>KV cache 增长</td><td>FP8 KV 存储</td><td>容量减半，需长上下文校验</td></tr></tbody></table>\n\n<h3 id=\"ap-mm-quant-recipe-sec-27\">二十七 · 与多模态批饥饿、批调度的联动</h3>\n<p>批饥饿条目关注的是视觉塔与 LLM 两个阶段的批组织不匹配导致的空转。量化配方在此处改变的是两个阶段的相对耗时：视觉塔降精度后单图前向变快，projector 与 LLM 的 FP8 W8A8 使预填阶段的矩阵乘吞吐上升，于是视觉阶段与语言阶段的耗时比例被重新分配。原本视觉阶段是瓶颈、LLM 阶段等待的批饥饿形态，可能在量化后反转为 LLM 预填成为瓶颈。这意味着批调度参数——视觉批大小、LLM 连续批处理的最大批 token 数——不能沿用未量化时的配置。</p>\n<p>更细的耦合点在分桶校准与批组成上。按图像分辨率分桶校准意味着不同桶的激活分布不同，而批调度会把不同分辨率的请求混进同一批。若同一批内混入高分辨率样本，其激活离群值会拉高整批的量化动态范围，压低低分辨率样本的有效位宽利用率。伪代码思路是：在批组装阶段读取每个请求的分辨率桶标签，同桶优先聚合，跨桶混批时对高分辨率样本单独走一条精度路径或限制混批比例。</p>\n<div class=\"formula\">$$\\text{batch-cost} = \\sum_{b\\in\\text{buckets}} n_b \\cdot t_b(q) + \\text{mix-penalty}(\\text{cross-bucket ratio})$$</div>\n<p>代价体现在吞吐与尾延迟两侧：同桶聚合提高量化利用率与吞吐，但降低了批的填充灵活性，短请求可能等待同桶伙伴而增加排队延迟；跨桶混批保持填充率，却引入动态范围损失。工程判断是给跨桶混批设一个比例上限，超过上限就拆批，把量化精度损失控制在可接受范围内，而不是追求满批。</p>\n\n<h3 id=\"ap-mm-quant-recipe-sec-28\">二十八 · 与分离式预填、KV cache 条目：FP8 KV 的边界条件</h3>\n<p>KV cache 以 FP8 存储是配方的一部分，它与分离式预填条目的接口在传输环节：预填节点产出 KV 后要经 NVLink/NIXL 传到解码节点，FP8 存储使传输字节数减半，直接降低跨节点带宽占用与传输延迟。但这里有一个不能忽略的边界——KV 量化误差在长上下文上累积，多轮多模态对话的后段输出会漂移。分离式预填把预填与解码拆到不同节点，KV 在传输前完成量化、在解码端反量化，量化误差不因分离而消失，反而因为跨节点后无法做端到端的误差补偿而更难校正。</p>\n<p>因此配方与 KV cache 条目的分工是：配方给出 FP8 KV 的适用条件与校验方法，KV cache 条目给出容量与淘汰策略。适用条件按上下文长度分层——短上下文、单轮问答，FP8 KV 的误差累积有限；长上下文、多轮对话，需要保留最近若干轮的 KV 为高精度，或对 KV 量化采用分组 scale 而非全局 scale，把离群通道隔离。校验方法是构造多轮多模态对话的回放集，比对量化前后后段输出的漂移，而不是只看首轮。</p>\n<p>代价是显存与带宽的双向收益对应精度风险：FP8 KV 使 KV 容量减半，解码阶段每 token 的 KV 读取带宽减半，长上下文解码的带宽瓶颈得到缓解；代价是后段输出漂移，且漂移在离线评测中容易被首轮指标掩盖。工程判断是把 KV 精度策略写进 SLO 校验项，而不是当作默认开启的优化。</p>\n\n<h3 id=\"ap-mm-quant-recipe-sec-29\">二十九 · 下游影响：多模态上线前清单与容量规划</h3>\n<p>配方是上线前清单里的一类检查项，但它向下游输出的是一张可执行的精度配置表：模块名称、权重精度、激活精度、是否校准、校准数据分桶方式、KV cache 精度、敏感层名单、精度塌陷风险等级。这张表是清单条目的输入，清单负责逐项核验，配方负责给出每项的取值与依据。两者不能合并——配方回答“配成什么”，清单回答“是否按配方配了、是否校验过”。</p>\n<p>对容量规划的影响体现在资源画像上。量化后单副本的权重显存、KV 容量、单请求计算量都发生变化，容量规划条目据此重算每 GPU 可承载的并发数与 SLO 满足率。关键点是校准开销要计入容量：校准是离线吞吐型负载，占用 GPU 机时但不产生服务容量，规划时要单独预留窗口，不能与在线服务抢同一批卡。另一个影响是分桶校准带来的多份校准表存储，表本身很小，但按分辨率桶与模型版本组合后数量增长，需要版本管理。</p>\n<ul>\n<li>上游：预处理版本、压缩版本、敏感层名单三者任一变更触发重新校准。</li>\n<li>下游：上线前清单按配置表逐项核验；容量规划按量化后资源画像重算并发。</li>\n<li>横向：与视觉塔显存溢出共享分层精度表；与批饥饿共享分桶批组装规则；与分离式预填共享 FP8 KV 的传输与校验边界。</li>\n</ul>\n\n<h3 id=\"ap-mm-quant-recipe-sec-30\">三十 · 在全书中的位置：配方是精度维度的收口点</h3>\n<p>把全书按维度切开，算子与数值精度这一维度讲的是 tcgen05、TMEM、2-SM MMA 与 NVFP4/FP8 的硬件能力，回答“硬件能做什么精度”；多模态量化配方回答“多模态这条链路上每个模块该用什么精度、怎么校准、哪里豁免”。前者是能力面，后者是策略面，配方是精度维度在多模态场景下的收口点——它把硬件精度能力翻译成模块级配置，并把配置的校验责任交给上线清单。</p>\n<p>它与视觉token压缩、跨模态注意力等条目的关系是横向的而非纵向的：压缩改变 token 分布，配方据此调整 projector 校准；跨模态注意力的 QKV 投影若走 FP8，其精度策略由配方统一给出，注意力条目本身不重复定义精度。这样切分的好处是精度决策只有一处源头，避免每个条目各自给一套位宽建议导致配置冲突。判断规则是：任何条目涉及位宽选择时，引用配方表而不自行定义；配方表变更时，所有引用条目的示例配置同步更新。</p>\n<p>最后落在具体机制上：配方表的每一行都对应一次可复现的校准动作与一次可回放的校验动作，行与行之间的依赖由模块边界决定——视觉塔的敏感层豁免影响 projector 的输入分布，projector 的输出分布影响 LLM 预填的激活统计，KV 精度影响解码阶段的误差累积。工程上把这四条依赖写成校准流水线的阶段顺序，任一阶段失败即阻断后续阶段，而不是让错误配置流入线上。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-mm-quant-recipe\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>视觉塔建议保留FP8/BF16敏感层、对projector与LLM采用FP8 W8A8并校准视觉token分布…</td></tr><tr><td>关键点</td><td>需按图像分辨率分桶校准，防止高分辨率token激活离群导致精度塌陷。</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-mm-quant-recipe · 共 5 个片段</p>\n"},{"id":"ap-video-frame-recipe","title":"视频抽帧与批配方","summary":"按帧率与时长自适应抽帧、统一分辨率分桶、按镜头切分组织批，视频token按时间维压缩后再送入LLM；批内按帧数而非请求数配平，避免长视频请求独占prefill导致尾延迟飙升。","kind":"配方","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-1\">一 · 条目边界：抽帧配方到底规定什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-2\">二 · 分类维度一：采样密度是时长的函数，不是常数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-3\">三 · 分类维度二：分辨率桶是形状契约，档位数是代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-4\">四 · 分类维度三：批的组成单位是帧数，不是请求数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-5\">五 · 与相邻概念的区别：压缩、调度、编码器各管一段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-6\">六 · 配方失效的三条边界：请求配平、帧率下限与分桶粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-7\">七 · 采样密度速查：帧率、时长与 token 预算的三角约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-8\">八 · 分辨率分桶速查：档位数量是硬约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-9\">九 · 镜头切分批速查：批内方差是调度目标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-10\">十 · 时间维压缩速查：ρ 与帧率的联动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-11\">十一 · 批配平速查：按帧数而非请求数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-12\">十二 · 失败模式对照速查：阈值越界的判定与动作</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-13\">十三 · 阈值从哪里来：把“配方参数”还原成可测量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-14\">十四 · 分辨率分桶的档位数：用编译与碎片成本定上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-15\">十五 · 按镜头切分后的批内方差：一个可算的配平准则</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-16\">十六 · 时间维压缩比：用运动强度而不是固定系数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-17\">十七 · 按帧数配平的配额：把尾延迟写成帧数函数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-18\">十八 · 测量基础设施：让阈值可复现的最小采集集</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-19\">十九 · 阈值怎么定：从帧数配额到分桶档位的可测量边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-20\">二十 · 批配平只看请求数：长视频独占 prefill 的尾延迟塌陷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-21\">二十一 · 自适应帧率下限过低：时序混叠在压缩后不可逆</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-22\">二十二 · 分辨率分桶档位过多：重编译与显存碎片吃掉吞吐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-23\">二十三 · 时间维压缩与空间分辨率错配：压缩率当成了分辨率替代</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-24\">二十四 · 上线检查清单与回滚顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-25\">二十五 · 失效边界：配平口径、帧率下限与分桶粒度的三处塌陷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-26\">二十六 · 上游依赖：抽帧配方吃的是预处理工具链与视觉塔的接口契约</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-27\">二十七 · 与视觉 token 压缩条目的分工：时间维压缩发生在抽帧之后、入 LLM 之前</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-28\">二十八 · 下游影响之一：批配平把抽帧输出翻译成调度配额</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-29\">二十九 · 下游影响之二：分离式预填与显存溢出条目的输入假设</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-30\">三十 · 在全书中的位置：视觉前端的“入口整形器”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-video-frame-recipe-sec-31\">三十一 · 配方边界：何时这套抽帧与批组织会反噬</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-video-frame-recipe\"><svg style=\"max-width:551px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 550.9 357\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"468.9\" height=\"83.0\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"53.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"57.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：视频抽帧与批配方</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">按帧率与时长自适应抽帧、统一分辨率分桶、按镜头切分组织批，视频</text><text x=\"75.0\" y=\"78.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">token按时间…</text><line x1=\"82.0\" y1=\"97.0\" x2=\"82.0\" y2=\"114.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 113.0 L 86.5 113.0 L 82.0 121.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"121.0\" width=\"468.9\" height=\"83.0\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"162.6\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"166.8\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"148.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><text x=\"75.0\" y=\"171.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">批内按帧数而非请求数配平，避免长视频请求独占prefill导致尾延迟飙升</text><text x=\"75.0\" y=\"187.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">。</text><line x1=\"82.0\" y1=\"206.1\" x2=\"82.0\" y2=\"223.1\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 222.1 L 86.5 222.1 L 82.0 230.1 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"230.1\" width=\"468.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"252.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"256.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"257.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"276.9\" x2=\"82.0\" y2=\"293.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 292.9 L 86.5 292.9 L 82.0 300.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"300.9\" width=\"468.9\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"323.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"327.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"328.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-video-frame-recipe-sec-1\">一 · 条目边界：抽帧配方到底规定什么</h3>\n<p>“视频抽帧与批配方”不是一套预处理脚本的集合，而是一份把视频请求的<strong>时间采样密度、空间输入形状、批内组成、时间维压缩</strong>四件事绑定在一起、并给出相互约束关系的推理侧配置契约。它规定的是：给定一路视频的帧率与时长，输出多少帧、每帧归入哪个分辨率桶、这些帧和哪些其他请求的帧组成一个批、进入视觉塔之前时间维要不要压缩、压缩多少。它不规定视觉塔内部怎么算（那是视觉编码器与 tcgen05 kernel 的事），也不规定 KV cache 怎么分页（那是显存与批调度的事），更不规定跨模态注意力怎么对齐——本片段只把边界划清，具体机制由同模块其他条目展开。</p>\n<p>把它当成“预处理”是常见误判。预处理工具链关心的是解码、色彩空间、缩放算法是否正确；抽帧配方关心的是<strong>这些帧在推理系统里造成的代价</strong>。同一个 1080p、30fps、4 分钟的视频，抽 64 帧与抽 256 帧，视觉 token 数差 4 倍，prefill 的 MMA 工作量、视觉塔激活显存、跨模态注意力的序列长度全部随之变化。配方的作用是在准确率可接受的前提下，把这个 token 数钉在一个预算内，并让不同请求的预算可比、可批。</p>\n<p>因此条目的最小完整定义包含四个字段：采样密度策略（随帧率与时长自适应）、分辨率桶编号、批组成规则（按帧数配平、按镜头切分）、时间维压缩比。缺任何一个，配方就不闭合——只给帧数不给桶，视觉塔会遇到任意 shape；只给桶不给批规则，调度器仍按请求数配平；只给压缩比不给采样密度，压缩后的时序信息无从判断是否混叠。</p>\n\n<h3 id=\"ap-video-frame-recipe-sec-2\">二 · 分类维度一：采样密度是时长的函数，不是常数</h3>\n<p>最朴素的做法是固定帧率抽帧，例如一律 1fps。它在短视频上丢时序细节，在长视频上把 token 总量顶穿预算。配方的第一条分类维度就是<strong>采样密度随帧率与时长自适应</strong>：短视频提高帧率保时序细节，长视频降低帧率控 token 总量，使单请求视觉 token 数落在预算内。这条规则的数学形式是一个受预算约束的采样决策：</p>\n<div class=\"formula\">$$N_f=\\min\\left(\\left\\lceil \\frac{T}{1/f_{\\text{low}}} \\right\\rceil,\\ \\left\\lfloor \\frac{B_{\\text{vis}}}{N_{\\text{tok/frame}}\\cdot \\rho_{\\text{time}}} \\right\\rfloor\\right),\\quad f_{\\text{sample}}=\\frac{N_f}{T}$$</div>\n<p>其中 $T$ 为时长，$f_{\\text{low}}$ 是时序保真所需的下限帧率，$B_{\\text{vis}}$ 是单请求视觉 token 预算，$N_{\\text{tok/frame}}$ 是单帧在视觉塔输出端的 token 数（由分辨率桶决定），$\\rho_{\\text{time}}$ 是时间维压缩比。取 min 的含义是：短素材受下限帧率约束，长素材受 token 预算约束，两条约束在某个时长处交接。这个交接点就是配方分类的第一条分界线——交接点两侧的请求，其帧数由完全不同的机制决定，调度器对它们的批内行为预期也应不同。</p>\n<p>系统代价直接落在 prefill 上。视觉 token 数线性进入视觉塔的 MMA 计算量与激活显存，而 prefill 阶段这些 token 还要与文本 token 一起占据批的激活预算。对一路长视频把帧率从 1fps 降到 0.25fps，token 数降为四分之一，视觉塔的算力占用与激活峰值同步下降，代价是快速运动镜头出现时序混叠——这正是条目列出的失败模式之一：自适应帧率下限设得过低时，时间维压缩后动作信息丢失，下游准确率下降。所以下限帧率不是可随意调低的旋钮，它是准确率的护栏，配方必须把它写成显式字段而非隐含默认值。</p>\n<p>具体例子：一路 10 秒、60fps 的短视频与一路 10 分钟、30fps 的监控视频。前者时长约束宽松，配方取较高采样帧率以保住动作相位；后者时长把 $N_f$ 顶到预算上限，采样帧率被压到远低于 1fps，此时配方必须同时检查镜头切分是否把长视频拆成足够多的片段，否则单请求的 token 仍然集中在一个批里。</p>\n\n<h3 id=\"ap-video-frame-recipe-sec-3\">三 · 分类维度二：分辨率桶是形状契约，档位数是代价</h3>\n<p>统一分辨率分桶把不同宽高比的帧归入固定几档分辨率桶，同桶帧共享视觉塔输入形状。这条规则的分类意义在于：它把“连续变化的输入形状”离散化为“有限个编译单元”。视觉塔在 Blackwell 上走 tcgen05 路径时，输入 shape 决定 MMA 的 tile 划分与 TMEM 占用；shape 每变一次，就可能触发重编译或 kernel 切换。分桶的本质是用少量准确率损失（重采样到桶尺寸）换取形状稳定性。</p>\n<p>分类维度在这里是<strong>桶的档位数</strong>。档位太少，宽高比差异大的帧被强行拉到同一形状，padding 浪费与几何失真同时上升；档位太多，视觉塔频繁重编译或 kernel 切换，编译开销与显存碎片抵消了分桶带来的吞吐收益——这是条目明确列出的第三条失败模式。配方要给出的是档位集合与归桶规则（按面积、按宽高比、还是按二者联合），而不是让运行时临时决定。</p>\n<p>代价可以写成每批的 padding 浪费率与编译摊销的权衡：</p>\n<div class=\"formula\">$$\\text{waste}=\\frac{\\sum_i (A_{\\text{bucket}(i)}-A_i)}{\\sum_i A_{\\text{bucket}(i)}},\\qquad \\text{amortize}=\\frac{C_{\\text{compile}}}{N_{\\text{frames per bucket per batch}}}$$</div>\n<p>前者随档位减少而上升，后者随档位增加而上升，配方的工作点是二者之和的最小处。工程判断上，档位应当与视觉塔已编译的 kernel 集合对齐——若某个桶尺寸没有对应的优化 kernel，它带来的就不是吞吐而是回退路径。显存侧的代价是碎片：每个桶的激活缓冲按该桶最大 shape 分配，档位多则缓冲种类多，长驻显存上升。具体例子：竖屏短视频与横屏影视素材混跑时，若只设一个方形桶，竖屏帧的 padding 浪费显著；若为每个宽高比设桶，视觉塔的编译单元数随之上跳，配方应把桶集合限制在少数几档并让归桶规则吸收剩余差异。</p>\n\n<h3 id=\"ap-video-frame-recipe-sec-4\">四 · 分类维度三：批的组成单位是帧数，不是请求数</h3>\n<p>这是本条目与相邻批调度概念最清晰的分界。多模态批调度关心的是请求如何排队、如何抢占、如何做连续批处理；抽帧配方关心的是<strong>一个批里装了什么形状的帧</strong>。条目给出的规则是批内按帧数而非请求数配平：调度器以总帧数/token 数为配额，避免单个长视频请求独占 prefill 带宽导致尾延迟飙升。按镜头切分组织批则进一步以镜头边界把视频拆成片段，同批尽量放帧数相近的片段，使批内视觉 token 长度方差收敛。</p>\n<p>按请求数配平的失败模式写得很具体：长视频请求与短视频请求同批，长请求独占 prefill 使同批短请求排队，P99 延迟显著抬升。机制在于 prefill 是批级同步的——一个批的完成时间由批内最长的序列决定，短请求的 token 早已算完却要等长请求的 MMA 走完才能返回。按帧数配额则把批的“长度”变成可控量：批的总帧数上限固定，长视频请求只能占据其中一部分配额，剩余配额由短视频请求填充，批内最长序列与最短序列的差距被配额压住。</p>\n<p>镜头切分是这条规则的补充维度。同一路视频内部，镜头之间的帧数分布并不均匀；若把整路视频当一个片段入批，它的帧数方差就进入批内。以镜头边界拆片段后，配方可以按片段帧数排序并做装箱，使批内 token 长度方差收敛。代价是片段边界处的时序连续性需要在时间维压缩时特殊处理，否则跨镜头的相邻时间步被错误合并。吞吐侧的收益是 prefill 的 SM 占用更均衡：批内没有超长序列拖尾，tcgen05 的 MMA 流水不会在尾部空转。具体例子：一路含快速剪辑的长视频被拆成数十个镜头片段，每个片段帧数相近，装箱后同批片段长度方差小，prefill 的批完成时间接近批内均值而非最大值。</p>\n\n<h3 id=\"ap-video-frame-recipe-sec-5\">五 · 与相邻概念的区别：压缩、调度、编码器各管一段</h3>\n<p>视觉 token 压缩处理的是“已经产生的 token 如何变少”，其对象是视觉塔输出端的 embedding 序列；抽帧配方处理的是“产生多少 token、什么形状、和谁一批”。条目里的时间维压缩是配方的一个字段（压缩比 $\\rho_{\\text{time}}$），因为压缩比反过来决定采样密度预算：对相邻时间步的视觉 embedding 做合并或池化，降低序列长度而不改空间分辨率，于是同样的 token 预算可以容纳更多帧。但压缩算法本身、合并窗口怎么选、是否用注意力加权，属于压缩条目，本片段只用它的比值作为约束。</p>\n<p>与视觉编码器术语表的区别在于抽象层级：编码器条目讲视觉塔内部的数据流与精度路径，配方讲的是喂给它的输入契约。配方不关心 ViT 的层数或 patch 大小，只关心输入 shape 落在哪个桶、桶是否有对应 kernel。与多模态批饥饿的区别在于症状归属：批饥饿是调度侧请求不足导致的 SM 空闲，配方侧的按帧数配平是防止批内长度失衡；两者都表现为利用率问题，但一个靠增加并发请求解决，一个靠改变批组成解决，不能互相替代。</p>\n<p>与多模态分离式预填配方的区别最容易被混淆。分离式预填把 prefill 与 decode 放到不同资源池，解决的是阶段间资源争用；抽帧配方决定的是进入 prefill 的 token 总量与形状分布。二者叠加时，配方给出的批帧数配额直接决定 prefill 池的负载形状——配额过大，prefill 池的批完成时间被长片段拉长；配额过小，批次数增多、通信与调度开销上升。配方必须把配额写成可与分离式部署对齐的量，而不是留给运行时试探。</p>\n<p>最后落到一个工程判断上：这四类字段中，采样密度与分辨率桶决定单请求的 token 数与形状，批组成与时间维压缩决定批级方差与序列长度。配方条目的准确性取决于这四个字段是否都被显式写出并可被调度器读取——任何一项留在默认值里，失败模式就会以尾延迟或准确率下降的形式在线上出现，而那时已经无法从请求日志里区分是抽帧错了还是调度错了。</p>\n\n<h3 id=\"ap-video-frame-recipe-sec-6\">六 · 配方失效的三条边界：请求配平、帧率下限与分桶粒度</h3>\n<p>这套配方的有效性建立在三个前提上：批内工作量可比、采样密度足以保真、视觉塔输入形状收敛。任一前提被打破，收益立刻反转为代价。最典型的是<b>按请求数配平</b>：调度器若以 batch size 为配额，一个长视频请求与若干短视频请求同批，长请求在 prefill 阶段独占 SM 与 HBM 带宽，短请求只能排队等待其视觉 token 全部编码完毕。设批内请求 i 的视觉 token 数为 <span class=\"inline-math\">n_i</span>，批完成时间近似由最大值决定：</p>\n<div class=\"formula\">$$T_{\\text{batch}} \\approx \\max_i \\left( \\frac{n_i \\cdot c_{\\text{enc}}}{B_{\\text{eff}}} \\right) + T_{\\text{dec}}$$</div>\n<p>其中 <span class=\"inline-math\">\\(c_{\\text{enc}}\\)</span> 是单 token 编码代价，<span class=\"inline-math\">\\(B_{\\text{eff}}\\)</span> 是有效算力配额。请求数配平等价于假设各 <span class=\"inline-math\">n_i</span> 相近，而长视频的 <span class=\"inline-math\">n_i</span> 可比短视频高一个数量级以上，于是 <span class=\"inline-math\">max</span> 项被长请求牢牢占据，同批短请求的排队时间被无偿放大，P99 尾延迟显著抬升。按帧数配额配平的本质，是把上式中的 <span class=\"inline-math\">max</span> 换成受控的 <span class=\"inline-math\">\\(\\sum n_i\\)</span> 上限，让批完成时间对请求长度分布不敏感。</p>\n<p>第二条边界是<b>自适应帧率的下限</b>。降帧率控 token 总量的前提是时间维信息冗余；快速运动镜头不满足该前提。当采样间隔 <span class=\"inline-math\">\\(\\Delta t\\)</span> 大于场景特征时间尺度 <span class=\"inline-math\">\\(\\tau\\)</span> 时发生时序混叠，随后时间维合并/池化把相邻时间步 embedding 压成一个，动作相位差被抹平。判据可写成 <span class=\"inline-math\">\\Delta t < \\tau/2</span>；配方若只按总时长反比设帧率而不设下限，长视频中的高速片段必然越界。系统代价不在显存或吞吐，而在下游准确率——这是配方唯一无法用调度手段补偿的失效，必须在抽帧阶段以镜头运动强度做兜底。</p>\n<p>第三条边界是<b>分辨率分桶的档位数</b>。分桶收益来自同桶帧共享视觉塔输入形状，从而复用已编译 kernel、消除 padding 浪费；但每增加一档就多一套 shape 专属的 kernel 与 workspace。设档位数为 <span class=\"inline-math\">K</span>，编译与切换开销随 <span class=\"inline-math\">K</span> 增长，而显存池按档位切分后碎片化加剧。当 <span class=\"inline-math\">K</span> 大到单个桶内帧数不足以摊薄编译成本时，重编译与 kernel 切换的代价抵消吞吐收益，配方退化为负优化。工程判断是：档位数应由实际宽高比分布的长尾决定，而非穷举所有比例。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>机制</th><th>系统代价</th></tr></thead><tbody><tr><td>按请求数配平</td><td>长请求独占 prefill，批完成时间由 max 决定</td><td>P99 尾延迟抬升，短请求排队</td></tr><tr><td>帧率下限过低</td><td>Δt &gt; τ/2，时序混叠后被时间维压缩抹平</td><td>动作信息丢失，下游准确率下降</td></tr><tr><td>分桶档位过多</td><td>视觉塔频繁重编译、kernel 切换、显存碎片</td><td>编译开销抵消吞吐收益</td></tr></tbody></table>\n<h3 id=\"ap-video-frame-recipe-sec-7\">七 · 采样密度速查：帧率、时长与 token 预算的三角约束</h3>\n<p>抽帧配方的第一张表不是“抽多少帧”，而是“在给定 token 预算下，帧率与时长如何互相让步”。速查口径统一为：先定单请求视觉 token 预算 <em>B</em>，再定空间分辨率桶（决定每帧 token 数 <em>t_s</em>），最后反解帧率。公式为：</p>\n<div class=\"formula\">$$f = \\frac{B}{t_s \\cdot T \\cdot \\rho}$$</div>\n<p>其中 <em>T</em> 为视频时长（秒），<em>ρ</em> 为时间维压缩比（相邻时间步合并后的保留比例，取值在 (0,1]）。这张表的字段必须包含：时长档、帧率上限、帧率下限、目标 token 预算、压缩比、触发动作。短视频档提高帧率保时序细节，长视频档降低帧率控总量，两者的分界点由 <em>B</em> 与 <em>t_s</em> 共同决定，而不是拍脑袋定时长阈值。工程代价直接体现在 prefill 上：帧率每翻一倍，视觉塔前向次数与 LLM 侧序列长度同步翻倍，prefill 延迟近似线性上升，而解码阶段几乎不受益——所以帧率是 prefill 侧的成本项，不是解码侧的。具体例子：一段 30 秒、每帧 256 token、压缩比 0.5、预算 8192 token 的请求，反解出 f≈2.1 fps；若把预算压到 4096，则 f≈1.07 fps，此时快速运动镜头已接近时序混叠边界，必须触发“保帧率、降分辨率桶”而不是继续降帧率。</p>\n<table class=\"mini\"><thead><tr><th>字段</th><th>口径</th><th>阈值/取值规则</th><th>越界动作</th></tr></thead><tbody>\n<tr><td>时长档</td><td>按秒计，短/中/长三档</td><td>由 B/(t_s·ρ) 与可接受最低帧率反解分界</td><td>跨档重算帧率</td></tr>\n<tr><td>帧率上限</td><td>fps</td><td>受视觉塔单帧前向吞吐约束</td><td>降分辨率桶</td></tr>\n<tr><td>帧率下限</td><td>fps</td><td>由运动剧烈程度决定，低于此值时序混叠</td><td>改走空间降采样或镜头切分</td></tr>\n<tr><td>token 预算 B</td><td>单请求视觉 token</td><td>由 LLM 上下文与批配额共同约束</td><td>拒绝或分段</td></tr>\n<tr><td>压缩比 ρ</td><td>时间维保留比例</td><td>与帧率联动，ρ 越低对帧率下限要求越高</td><td>回调 ρ</td></tr>\n</tbody></table>\n\n<h3 id=\"ap-video-frame-recipe-sec-8\">八 · 分辨率分桶速查：档位数量是硬约束</h3>\n<p>分桶表的字段不是“有哪些桶”，而是“桶的数量上限”和“桶间跳变规则”。统一分辨率分桶把不同宽高比的帧归入固定几档，同桶帧共享视觉塔输入形状，减少动态 shape 重编译与 padding 浪费。速查口径：桶数以视觉塔 kernel 编译缓存能容纳的 shape 数为上限，超出即触发重编译或 kernel 切换，编译开销与显存碎片会抵消分桶收益。字段应包含：桶 ID、宽高、每帧 token 数 <em>t_s</em>、允许的宽高比区间、padding 浪费率上限、桶切换惩罚。公式上，padding 浪费率为：</p>\n<div class=\"formula\">$$w = 1 - \\frac{H \\cdot W}{\\max(H_b) \\cdot \\max(W_b)}$$</div>\n<p>其中 <em>H·W</em> 为原始帧面积，分母为该桶的包围盒面积。工程判断：当 <em>w</em> 超过阈值时，宁可升一档桶也不要留在低档桶里做大量 padding，因为 padding 的算力浪费是每帧都付的，而升档只付一次形状切换。代价口径落在显存与吞吐两侧：桶过多导致视觉塔频繁重编译，编译期显存峰值抬升、稳态吞吐下降；桶过少则 padding 浪费率上升，等效算力利用率下降。具体例子：同一批里混入 16:9 与 9:16 两种帧，若只设一个方形桶，竖屏帧的 padding 浪费率接近一半；设两个桶后浪费率收敛，但桶数从 1 增到 2 带来的 shape 切换次数必须在编译缓存容量内，否则每次切换都变成一次 kernel 重编译，吞吐反而低于单桶。</p>\n<table class=\"mini\"><thead><tr><th>字段</th><th>口径</th><th>阈值/取值规则</th><th>越界动作</th></tr></thead><tbody>\n<tr><td>桶 ID / 宽高</td><td>像素</td><td>覆盖主流宽高比，档间面积比不宜过密</td><td>合并相邻桶</td></tr>\n<tr><td>每帧 token t_s</td><td>视觉 token</td><td>= 桶面积 / patch 面积</td><td>重算预算</td></tr>\n<tr><td>宽高比区间</td><td>比值</td><td>区间内 padding 浪费率 ≤ 上限</td><td>拆桶或改裁剪</td></tr>\n<tr><td>桶数上限</td><td>个</td><td>≤ 视觉塔编译缓存可容纳 shape 数</td><td>合并或改动态 shape</td></tr>\n<tr><td>切换惩罚</td><td>毫秒/次</td><td>重编译或 kernel 切换实测开销</td><td>批内按桶排序</td></tr>\n</tbody></table>\n\n<h3 id=\"ap-video-frame-recipe-sec-9\">九 · 镜头切分批速查：批内方差是调度目标</h3>\n<p>按镜头切分组织批的速查表，核心字段是“批内帧数方差”而非“批大小”。以镜头边界把视频拆成片段，同批尽量放帧数相近的片段，使批内视觉 token 长度方差收敛。调度口径：批的组成单位是片段，不是请求；一个请求可贡献多个片段进入不同批。字段包含：片段帧数、片段 token 数、批内帧数方差上限、批配额（总帧数/token 数）、跨请求混批允许标志。伪代码思路：</p>\n<div class=\"formula\">$$\\text{sort}(segments,\\ key=n_{frames});\\ \\text{pack greedily while } \\sum n_{frames} \\le Q$$</div>\n<p>其中 <em>Q</em> 为批配额。代价口径：批内方差大意味着最长片段决定该批 prefill 完成时间，短片段在批内空等，GPU 利用率与尾延迟同时恶化。具体例子：一批配额 512 帧，若混入一个 400 帧长片段与若干 20 帧短片段，长片段独占 prefill 带宽，短片段排队，P99 延迟显著抬升；按帧数排序后，400 帧片段与相近长度片段同批，短片段自成一批，批内方差收敛，尾延迟回落。这里的关键工程判断是：镜头切分本身不减少 token，它只是把“长度方差”从请求级降到片段级，真正的收益来自同批长度相近带来的 prefill 同步完成。</p>\n<table class=\"mini\"><thead><tr><th>字段</th><th>口径</th><th>阈值/取值规则</th><th>越界动作</th></tr></thead><tbody>\n<tr><td>片段帧数 n_frames</td><td>帧</td><td>由镜头边界切出</td><td>过长片段二次切分</td></tr>\n<tr><td>片段 token 数</td><td>视觉 token</td><td>= n_frames · t_s · ρ</td><td>重算批配额</td></tr>\n<tr><td>批配额 Q</td><td>总帧数或总 token</td><td>由 prefill 显存与带宽反推</td><td>拆批</td></tr>\n<tr><td>批内方差上限</td><td>帧数标准差</td><td>超过则重排或拆批</td><td>按帧数排序重打包</td></tr>\n<tr><td>跨请求混批</td><td>布尔</td><td>仅当片段长度相近时允许</td><td>隔离长片段</td></tr>\n</tbody></table>\n\n<h3 id=\"ap-video-frame-recipe-sec-10\">十 · 时间维压缩速查：ρ 与帧率的联动</h3>\n<p>时间维压缩的速查表字段必须把 <em>ρ</em> 与帧率绑在一起看，因为两者对时序信息的作用是乘法关系而非加法关系。视频 token 按时间维压缩后再送入 LLM，即对相邻时间步的视觉 embedding 做合并或池化，降低序列长度而不改空间分辨率。口径：压缩发生在视觉塔输出之后、送入 LLM 之前，合并窗口大小 <em>k</em> 与 <em>ρ</em> 的关系为 <em>ρ</em>=1/<em>k</em>（均匀合并时）。字段包含：合并窗口 k、压缩比 ρ、压缩后序列长度、运动强度标志、压缩后 token 预算校验。公式为压缩后序列长度：</p>\n<div class=\"formula\">$$L' = \\left\\lceil \\frac{f \\cdot T}{k} \\right\\rceil \\cdot t_s$$</div>\n<p>代价口径：压缩降低 LLM 侧 prefill 与 KV cache 占用，序列长度按 <em>ρ</em> 缩减，KV cache 显存同比例下降；但它不降低视觉塔的计算量，视觉塔仍按原始帧数前向。所以压缩是“省 LLM、不省视觉塔”的手段，配方里必须把这两笔账分开记。具体例子：快速运动镜头下，若帧率已压到下限附近再叠加较大 <em>k</em>，相邻时间步的 embedding 被池化掉，动作信息丢失，下游推理准确率下降；此时正确动作是回调 <em>k</em> 或提高帧率，而不是继续加大压缩。工程判断：<em>ρ</em> 的下限由运动强度决定，帧率的下限由混叠决定，两者不能同时压到极限。</p>\n<table class=\"mini\"><thead><tr><th>字段</th><th>口径</th><th>阈值/取值规则</th><th>越界动作</th></tr></thead><tbody>\n<tr><td>合并窗口 k</td><td>时间步</td><td>ρ = 1/k（均匀合并）</td><td>改非均匀合并</td></tr>\n<tr><td>压缩比 ρ</td><td>比例</td><td>与帧率联动，运动强时不得过低</td><td>回调 ρ</td></tr>\n<tr><td>压缩后长度 L'</td><td>token</td><td>≤ LLM 上下文与批配额</td><td>降帧率或分段</td></tr>\n<tr><td>运动强度标志</td><td>定性/分级</td><td>由镜头切分与帧间差异给出</td><td>锁定 ρ 下限</td></tr>\n<tr><td>视觉塔开销</td><td>不计入压缩收益</td><td>按原始帧数计</td><td>单独核算</td></tr>\n</tbody></table>\n\n<h3 id=\"ap-video-frame-recipe-sec-11\">十一 · 批配平速查：按帧数而非请求数</h3>\n<p>批内按帧数而非请求数配平，是这张速查表里最容易被忽略却最直接影响尾延迟的一行。调度器以总帧数/token 数为配额，避免单个长视频请求独占 prefill 带宽导致尾延迟飙升。字段包含：配额单位（帧数或 token 数）、单请求帧数上限、批内请求数上限（辅助约束）、长请求隔离标志、尾延迟观测口径（P99 prefill 时长）。伪代码思路：</p>\n<div class=\"formula\">$$\\text{admit}(r)\\ \\text{iff}\\ \\sum_{i \\in batch} n^{(i)}_{frames} + n^{(r)}_{frames} \\le Q$$</div>\n<p>代价口径：按请求数配平时，一个长视频请求与若干短视频请求同批，长请求独占 prefill 使同批短请求排队，P99 延迟显著抬升；按帧数配平后，批的 prefill 工作量有上界，尾延迟可预测。具体例子：配额按请求数设为 8，混入一个占满配额大半帧数的长视频，其余 7 个短请求的 prefill 完成时间被拉长到与长请求同量级；改为按帧数配额后，长请求单独成批或与相近长度请求同批，短请求批的 prefill 时长回到短请求自身的量级。工程判断：请求数上限只作为辅助字段防止批内元数据开销过大，真正的准入判据是帧数/token 数之和。</p>\n<table class=\"mini\"><thead><tr><th>字段</th><th>口径</th><th>阈值/取值规则</th><th>越界动作</th></tr></thead><tbody>\n<tr><td>配额单位</td><td>帧数或 token 数</td><td>与 prefill 显存、带宽反推</td><td>调 Q</td></tr>\n<tr><td>单请求帧数上限</td><td>帧</td><td>超过则分段或降帧率</td><td>拆请求</td></tr>\n<tr><td>批内请求数上限</td><td>个</td><td>辅助约束，防元数据开销</td><td>拆批</td></tr>\n<tr><td>长请求隔离</td><td>布尔</td><td>帧数超批均值倍数时置真</td><td>单独成批</td></tr>\n<tr><td>P99 prefill 时长</td><td>毫秒</td><td>观测口径，按批统计</td><td>重排批组成</td></tr>\n</tbody></table>\n\n<h3 id=\"ap-video-frame-recipe-sec-12\">十二 · 失败模式对照速查：阈值越界的判定与动作</h3>\n<p>最后一张表把前述字段的越界组合映射到具体失败模式与纠正动作，供上线前逐行核对。三条失败模式各自对应一组阈值组合：只按请求数配平批对应“配额单位=请求数”且“长请求隔离=假”；自适应帧率下限过低对应“帧率下限”被压到混叠边界以下且“压缩比 ρ”同时偏低；分辨率分桶档位过多对应“桶数上限”超过视觉塔编译缓存容量。速查口径要求每行给出可观测信号，而不是事后归因。字段包含：失败模式、触发字段组合、可观测信号、纠正动作、代价类型（延迟/吞吐/显存/带宽）。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>触发字段组合</th><th>可观测信号</th><th>纠正动作</th><th>代价类型</th></tr></thead><tbody>\n<tr><td>长请求独占 prefill</td><td>配额单位=请求数；长请求隔离=假</td><td>P99 prefill 时长抬升，短请求排队</td><td>改按帧数配额，长请求隔离</td><td>延迟</td></tr>\n<tr><td>时序混叠、动作丢失</td><td>帧率下限过低；ρ 偏低</td><td>下游准确率下降，快速镜头段误差集中</td><td>回调帧率下限或 ρ</td><td>准确率/吞吐</td></tr>\n<tr><td>分桶重编译开销</td><td>桶数上限 > 编译缓存容量</td><td>kernel 切换频繁，显存碎片上升</td><td>合并桶或改动态 shape</td><td>吞吐/显存</td></tr>\n<tr><td>padding 浪费</td><td>宽高比区间过宽；w 超上限</td><td>视觉塔算力利用率下降</td><td>拆桶或改裁剪</td><td>吞吐</td></tr>\n<tr><td>批内方差过大</td><td>批内方差上限被突破；未按帧数排序</td><td>批完成时间由最长片段决定</td><td>按帧数排序重打包</td><td>延迟/利用率</td></tr>\n</tbody></table>\n<p>这张对照表的用法是逐行核对字段取值是否落在阈值内，而不是等失败发生后再查。工程判断落在最后一行之外：任何一行纠正动作都会改变另一行的字段取值，例如合并桶会改变 <em>t_s</em> 进而改变 token 预算反解出的帧率，所以速查表必须整表联动校验，单行调参只会把代价从延迟搬到吞吐或显存。</p>\n<h3 id=\"ap-video-frame-recipe-sec-13\">十三 · 阈值从哪里来：把“配方参数”还原成可测量</h3>\n<p>抽帧配方里每一个看似随意的数字，本质上都是某个可测量在预算约束下的解。工程上要避免两种做法：一是凭直觉拍一个帧率，二是把别人机器上的数字抄过来。正确路径是把配方参数写成“约束 → 观测量 → 阈值”的三段式。约束来自 SLO（首 token 延迟、P99 端到端、单卡并发数）与显存预算；观测量是能在你的栈上直接采到的量；阈值则是观测量在约束边界上的取值。以自适应帧率为例，短视频提高帧率保时序细节、长视频降低帧率控 token 总量，这条规则要落地，必须先定义“单请求视觉 token 预算”这个观测量：</p>\n<div class=\"formula\">$$T_{\\text{vis}} = N_f \\cdot \\frac{H_b W_b}{p^2} \\cdot \\rho_t$$</div>\n<p>其中 $N_f$ 为抽帧数，$H_b W_b$ 为所选分辨率桶的面积，$p$ 为视觉塔 patch 边长，$\\rho_t$ 为时间维压缩比（相邻时间步合并或池化后的保留比例）。这个式子把“帧率与时长自适应”翻译成一个可算的预算：给定 $T_{\\text{vis}}$ 上限，帧率上限由时长反解，而不是反过来。测量方法上，$N_f$ 与桶面积是配方自己决定的，$p$ 与 $\\rho_t$ 由模型与压缩算子决定，唯一需要实测的是“在给定 $T_{\\text{vis}}$ 下 prefill 阶段视觉塔的耗时与显存峰值”。做法是固定桶与压缩比，扫描 $N_f$ 的若干档，记录视觉塔 kernel 时间与激活峰值，找到耗时随 $N_f$ 近似线性上升的区间——阈值就落在该区间内、且使 $T_{\\text{vis}}$ 不越过预算的那一档。代价面很直接：$N_f$ 每翻一倍，视觉 token 数与视觉塔 prefill 计算量同步翻倍，而 LLM 侧序列长度也翻倍，KV cache 占用随序列长度线性增长，因此这个阈值同时是延迟阈值和显存阈值。</p>\n\n<h3 id=\"ap-video-frame-recipe-sec-14\">十四 · 分辨率分桶的档位数：用编译与碎片成本定上限</h3>\n<p>统一分辨率分桶把不同宽高比的帧归入固定几档桶，同桶帧共享视觉塔输入形状，减少动态 shape 重编译与 padding 浪费。但档位不是越多越好：档位过多会导致视觉塔频繁重编译或 kernel 切换，编译开销与显存碎片抵消分桶收益。这里的工程阈值可以用一个简单的收益-成本不等式来定：</p>\n<div class=\"formula\">$$\\Delta_{\\text{pad}}(K) \\;&gt;\\; C_{\\text{recompile}} \\cdot f_{\\text{switch}}(K) + M_{\\text{frag}}(K)$$</div>\n<p>左侧是 $K$ 档分桶相对单档（最坏 padding）节省的 padding 计算量占比，右侧是编译/切换开销与显存碎片随档位增长的部分。测量方法分三步：第一，统计真实流量中帧的宽高比分布，按分位数聚成候选桶边界（例如以面积与长边比例两个维度聚类），得到候选 $K$ 值序列；第二，对每个 $K$ 在目标框架上跑一段固定请求序列，采集视觉塔的 kernel 启动次数、动态 shape 重编译次数与显存分配器的高水位与碎片率；第三，把 padding 浪费折算成等效 token 数，与重编译耗时折算的等效 token 数放在同一量纲上比较。经验判断是：当候选桶的边界间距小于视觉塔一个 tile 的尺寸时，再细分几乎不减少 padding，却确定性地增加切换次数，此时应停止加档。代价侧要盯住显存碎片：桶形状种类多，激活缓冲池难以复用，高水位上升会直接压缩 KV cache 可用的显存，进而压低并发数——这是分桶收益被吞掉的典型路径。</p>\n\n<h3 id=\"ap-video-frame-recipe-sec-15\">十五 · 按镜头切分后的批内方差：一个可算的配平准则</h3>\n<p>按镜头切分组织批，以镜头边界把视频拆成片段，同批尽量放帧数相近的片段，使批内视觉 token 长度方差收敛。这条规则的阈值不在“帧数”本身，而在“批内长度方差”与“批利用率”的折中点。设批内片段视觉 token 数为 $l_1,\\dots,l_B$，批的实际计算由最长片段决定（无连续批处理时的同步批），则浪费率为：</p>\n<div class=\"formula\">$$W = 1 - \\frac{\\sum_i l_i}{B \\cdot \\max_i l_i}$$</div>\n<p>配平的目标是把 $W$ 压到某个可接受上限之下。测量方法：在调度器侧记录每个批的 $\\max_i l_i$ 与 $\\sum_i l_i$，按分钟窗口统计 $W$ 的分布，而不是只看均值——尾部的 $W$ 才是尾延迟的来源。阈值取法是把 $W$ 的 P99 与 SLO 中的 P99 延迟对齐：若 $W$ 的 P99 超过某个比例，说明批内混入了过长片段，应触发更严格的同桶配对（按帧数分位分桶后再组批）。具体例子：一段长视频被切成若干镜头片段，其中包含一个长镜头与若干短镜头，若按请求数把它们塞进同一批，长镜头片段决定整批的 prefill 时长，短片段全部排队等待，P99 被单批拉高；改为按帧数分位分组后，长短片段各自成批，短批快速返回，长批独占其应得的带宽。代价是批利用率下降、批次数增多，调度开销与批间切换上升，因此阈值必须允许一定比例的“不完美配平”，否则会把吞吐换成无谓的调度开销。</p>\n\n<h3 id=\"ap-video-frame-recipe-sec-16\">十六 · 时间维压缩比：用运动强度而不是固定系数</h3>\n<p>视频 token 按时间维压缩后再送入 LLM，即对相邻时间步的视觉 embedding 做合并或池化，降低序列长度而不改空间分辨率。压缩比 $\\rho_t$ 的阈值不能全局固定：自适应帧率下限设得过低时，快速运动镜头出现时序混叠，时间维压缩后动作信息丢失，下游准确率下降。因此压缩比要与“相邻帧间的表观位移”挂钩。一个可操作的测量方法是：在视觉塔输出 embedding 上计算相邻时间步的余弦距离或特征差分能量，作为运动强度代理量 $m_t$；当 $m_t$ 超过某分位阈值时，减小压缩窗口（保留更多时间步），反之加大窗口。伪代码思路：</p>\n<ul>\n<li>对每个镜头片段，计算相邻帧 embedding 差分的分位数 $q_{90}(m_t)$；</li>\n<li>若 $q_{90}(m_t)$ 高于该镜头类别的高运动阈值，则 $\\rho_t$ 取保守档（少合并）；否则取激进档；</li>\n<li>合并后校验片段总 token 数是否仍落在 $T_{\\text{vis}}$ 预算内，超出则回退帧率而非继续加大压缩。</li>\n</ul>\n<p>代价面：压缩比越激进，LLM 侧序列越短、KV cache 与注意力计算越省、吞吐越高，但时序信息损失不可逆；压缩比越保守，prefill 与解码的序列成本线性上升。阈值的工程含义是“用可测的运动强度换不可测的准确率损失”，因此必须配一个离线回归集：固定一批含快速运动的样本，扫描压缩档位，观察下游任务指标随档位的变化拐点，把拐点作为该镜头类别的压缩上限。没有拐点数据时，宁可把帧率下限抬高、压缩比放保守，因为时序混叠一旦发生，后续任何 LLM 侧优化都无法补回。</p>\n\n<h3 id=\"ap-video-frame-recipe-sec-17\">十七 · 按帧数配平的配额：把尾延迟写成帧数函数</h3>\n<p>批内按帧数而非请求数配平，调度器以总帧数/token 数为配额，避免单个长视频请求独占 prefill 带宽导致尾延迟飙升。这里的阈值是“每批帧数配额”$F_{\\max}$，它应由 prefill 带宽与 SLO 反解，而不是由显存上限单独决定。设单帧视觉 token 数为 $t_f$，批的 prefill 计算量近似正比于 $B \\cdot F_{\\max} \\cdot t_f$，则批 prefill 时长可写成：</p>\n<div class=\"formula\">$$\\tau_{\\text{prefill}} \\approx \\alpha \\cdot F_{\\max} \\cdot t_f + \\beta$$</div>\n<p>$\\alpha$ 为单位视觉 token 的 prefill 时间（由视觉塔与投影层决定），$\\beta$ 为固定开销。测量方法：固定批形状，扫描 $F_{\\max}$，记录批 prefill 墙钟时间与其中最短请求的等待时间，画出“配额—尾延迟”曲线；阈值取曲线开始上翘的拐点，因为超过拐点后，批内短请求的排队时间由长请求主导，P99 抬升快于吞吐增益。具体例子：只按请求数配平批时，一个长视频请求与若干短视频请求同批，长请求独占 prefill 使同批短请求排队，P99 延迟显著抬升；改为以总帧数为配额后，长请求被拆到独立批或按镜头片段分批，短请求所在批的 prefill 时长被 $F_{\\max}$ 硬性截断。代价是长请求的批次数增加、调度与批间切换开销上升，且 GPU 利用率在长短混合流量下下降——因此 $F_{\\max}$ 的取值必须与流量中长短视频的比例一起调，流量结构变化后要重测拐点，而不是把一次测得的配额当成常量。</p>\n\n<h3 id=\"ap-video-frame-recipe-sec-18\">十八 · 测量基础设施：让阈值可复现的最小采集集</h3>\n<p>上述所有阈值都依赖同一批观测量，工程上应把它们做成默认开启的低开销采集，而不是临时加埋点。最小采集集包括：每请求的抽帧数、所选分辨率桶、镜头片段数、时间维压缩档位、视觉 token 总数；每批的总帧数、批内最大与最小片段 token 数、批 prefill 墙钟时间；以及视觉塔的动态 shape 重编译次数与显存分配器高水位、碎片率。把这些量与请求的排队时间、首 token 时间、端到端时间按同一请求 ID 关联，才能回答“阈值该往哪边调”。测量纪律有三条：其一，阈值实验必须固定其余配方参数，一次只动一个量，否则方差与配平的耦合会让结论失真；其二，尾延迟用分位数而非均值判定，且样本量要覆盖流量中的长尾请求；其三，任何阈值在跨模型、跨框架、跨分辨率桶迁移时都要重测，因为 $\\alpha$、$\\beta$、$p$、$\\rho_t$ 都随栈变化。工程判断落在最后这一步：配方里的数字不是知识，而是你机器上某条曲线的拐点；把曲线测出来、把拐点记下来、把重测触发条件写进上线清单，比记住任何具体数字都更有价值。</p>\n\n<h3 id=\"ap-video-frame-recipe-sec-19\">十九 · 阈值怎么定：从帧数配额到分桶档位的可测量边界</h3>\n<p>这一节的判断对象不是配方本身，而是配方的失效边界。三个可测阈值决定系统是否还站在收益区：批内帧数配额上限、自适应帧率下限、分辨率桶档位数。它们都不是拍脑袋常量，而是由 prefill 带宽、视觉塔编译开销与下游精度容差共同夹出来的区间。测量方法统一为：固定其余两维，扫描第三维，记录 P99 首 token 延迟、视觉 token 吞吐与下游任务准确率三条曲线，取准确率不塌、P99 不翘的交叉区间。</p>\n<p>帧数配额的失效条件是批内帧数方差过大。设批内片段帧数为 $f_i$，配额 $F$，则批完成时间近似被 $\\max_i f_i$ 支配而非 $\\sum_i f_i$，尾延迟抬升倍数约为 $\\max_i f_i / \\bar{f}$。只按请求数配平会让长视频与短视频同批，长请求独占 prefill，短请求排队，P99 显著抬升——这是条目已列明的失败模式，此处只给量化抓手：把 $\\max_i f_i / \\bar{f}$ 作为调度器的在线监控指标，超过设定倍数即触发拆批。测量上对比“按请求数”与“按帧数”两种配平在同一到达序列下的 P99，差值即为该阈值的代价。</p>\n<p>自适应帧率下限的失效条件是快速运动镜头出现时序混叠。判据是镜头内相邻帧的光流位移与采样间隔之积超过空间感受野，即 $v \\cdot \\Delta t &gt; R$ 时动作信息在时间维压缩后不可恢复。工程上不直接测光流，而用下游动作类任务的准确率做代理：把帧率下限逐档下调，观察准确率拐点，拐点之上留一档余量作为下限。代价是 token 总量随帧率线性上升，需与帧数配额联动，否则下限放宽会直接击穿 prefill 预算。</p>\n<p>分辨率桶档位过多则走向反面：视觉塔频繁重编译或 kernel 切换，编译开销与显存碎片抵消分桶收益。可测指标是单位时间内 shape 切换次数与编译耗时占比，后者超过稳态推理耗时的一定比例即应合并相邻桶。下表给出三阈值的观测量与失效信号，供容量规划时逐项打勾。</p>\n<table class=\"mini\"><thead><tr><th>阈值</th><th>观测指标</th><th>失效信号</th></tr></thead><tbody><tr><td>批内帧数配额</td><td>$\\max_i f_i/\\bar{f}$、P99 首 token</td><td>长请求独占 prefill，短请求排队</td></tr><tr><td>自适应帧率下限</td><td>动作类任务准确率拐点</td><td>时序混叠，压缩后动作丢失</td></tr><tr><td>分辨率桶档位数</td><td>shape 切换频次、编译耗时占比</td><td>重编译与显存碎片吃掉吞吐</td></tr></tbody></table>\n<h3 id=\"ap-video-frame-recipe-sec-20\">二十 · 批配平只看请求数：长视频独占 prefill 的尾延迟塌陷</h3>\n<p>配方里写的是“批内按帧数而非请求数配平”，但落到调度器实现上，最常见的退化是把配额键写成 <code>batch_size</code> 而不是 <code>sum(frames)</code>。一旦如此，一个 30 秒 30fps 的请求与七个 2 秒短请求同批，视觉塔的 prefill 工作量由最长请求决定，短请求全部排在它的 token 队列之后，P99 被单条长请求钉死。机制上要盯的是配额变量本身：调度器入队时对每个请求算出 <code>n_frames = clip(fps_target × duration, floor, cap)</code>，再按 <code>Σ n_frames</code> 与 <code>Σ n_frames × tokens_per_frame</code> 双配额做 bin packing，长请求要么单独成批、要么与帧数相近的请求配对。</p>\n<div class=\"formula\">$$\\text{admit}(r)=\\Big[\\sum_{i\\in B\\cup\\{r\\}} f_i \\le F_{\\max}\\Big]\\wedge\\Big[\\sum_{i\\in B\\cup\\{r\\}} f_i\\cdot t_i \\le T_{\\max}\\Big]$$</div>\n<p>代价面很直接：prefill 阶段视觉塔的算力占用与帧数近似线性，批内帧数方差每扩大一倍，尾延迟抬升的幅度就向最慢请求的 prefill 时间收敛。检查顺序上，先在调度器日志里打 <code>frames_per_batch</code> 的分布而不是 <code>requests_per_batch</code>，若 P99 批帧数 / P50 批帧数超过阈值，说明配平键错了。回滚方案：把帧数配额从“软约束”降级为硬门限，超限请求强制拆批或延迟入队，同时保留旧版按请求数配平的开关，线上出现尾延迟回归时一键切回并只对长视频请求做单独队列。</p>\n\n<h3 id=\"ap-video-frame-recipe-sec-21\">二十一 · 自适应帧率下限过低：时序混叠在压缩后不可逆</h3>\n<p>短视频提帧率、长视频降帧率是配方的主线，坑出在下限的设定。快速运动镜头（体育、动作、手势）在低采样率下发生时序混叠，相邻采样帧之间物体位移超过半个空间周期，时间维压缩做池化时把不同相位的信息平均掉，动作方向与速度信息直接丢失，下游时序推理准确率下降且无法通过后处理找回。机制上，下限不应是全局常数，而应与镜头运动强度挂钩：用镜头切分得到的片段内光流幅值或帧间差分能量估计运动等级，对高运动片段抬高帧率下限，对静态访谈类片段允许更低。</p>\n<div class=\"formula\">$$f_{\\text{sample}}=\\max\\Big(f_{\\min},\\ \\min\\big(f_{\\max},\\ \\tfrac{N_{\\text{budget}}}{\\lceil d\\cdot \\bar{\\rho}\\rceil}\\big)\\Big),\\quad \\bar{\\rho}=\\text{motion level}$$</div>\n<p>系统代价是 token 预算与准确率的对冲：抬高下限直接增加单请求视觉 token 数，挤占 LLM 的 KV cache 与 prefill 带宽，长视频请求尤其明显。具体例子：一段 60 秒、含三次快速摇镜的素材，全局下限设得低时三次摇镜各只采到两三帧，时间维压缩后动作段退化为静态画面；按片段运动等级抬升后，摇镜段帧数上升、静态段帧数下降，总 token 数基本持平而时序信息保住。检查顺序：抽取样本视频跑“帧间差分能量 vs 采样帧数”散点，找能量高但帧数低的片段；回滚方案是保留全局下限作为兜底，把运动自适应作为可关闭的增强层，准确率回归时先关增强层再调下限。</p>\n\n<h3 id=\"ap-video-frame-recipe-sec-22\">二十二 · 分辨率分桶档位过多：重编译与显存碎片吃掉吞吐</h3>\n<p>统一分辨率分桶的收益来自同桶帧共享视觉塔输入形状，减少动态 shape 重编译与 padding 浪费。坑在于档位设计过细：为了压低 padding，把宽高比切成十几档，视觉塔在批间频繁切换输入形状，触发 kernel 重编译或切换开销，同时不同形状的中间激活在显存池里留下尺寸不一的块，碎片化让本可复用的显存无法复用，吞吐收益被抵消。机制上，桶的数量应由视觉塔的编译缓存容量与显存池的块粒度共同决定，而不是由宽高比分布决定。</p>\n<div class=\"formula\">$$\\text{gain}(K)=\\underbrace{\\Delta_{\\text{pad}}(K)}_{\\text{padding 节省}}-\\underbrace{c_{\\text{recompile}}\\cdot N_{\\text{switch}}(K)}_{\\text{编译开销}}-\\underbrace{\\phi_{\\text{frag}}(K)}_{\\text{碎片代价}}$$</div>\n<p>代价判断要量化到批级：每次形状切换的编译开销乘以批间切换次数，与 padding 节省的算力做比较；显存侧看池化分配器的块尺寸分布，档位越多，大块被小块切碎的概率越高。具体例子：同一批混合横屏、竖屏、方形素材，档位从三档扩到十档后 padding 显著下降，但视觉塔每批都在换形状，编译缓存命中率掉下来，端到端吞吐反而回退。检查顺序：先看编译缓存命中率与形状切换次数，再看显存池碎片率，最后才看 padding 比例。回滚方案：把档位表做成配置项并保留粗档位默认值，线上出现吞吐回退时切回粗档位，同时把细档位限定在离线批处理路径使用。</p>\n\n<h3 id=\"ap-video-frame-recipe-sec-23\">二十三 · 时间维压缩与空间分辨率错配：压缩率当成了分辨率替代</h3>\n<p>时间维压缩是对相邻时间步的视觉 embedding 做合并或池化，降低序列长度而不改空间分辨率。坑是把压缩率当成控制 token 总量的唯一旋钮：为了压进预算，把时间压缩率调得很高，却不检查空间分辨率是否已经在分桶时被降档，结果是空间细节与时间细节同时被削，视觉塔输出的 embedding 既不够细也不够连续。机制上，压缩率与分辨率档位要联合求解：先由分桶定空间 token 数，再由预算反推可用的时间压缩率，压缩率超过阈值时改为降帧率而不是继续压时间维。</p>\n<div class=\"formula\">$$N_{\\text{vis}}=N_{\\text{space}}\\cdot\\Big\\lceil \\frac{N_{\\text{frame}}}{r_t}\\Big\\rceil \\le N_{\\text{budget}}$$</div>\n<p>系统代价体现在视觉塔与 LLM 的耦合处：时间压缩发生在送入 LLM 之前，压缩率过高会让 LLM 侧注意力在时间轴上失去可分辨的位置结构，KV cache 虽短但信息密度低，等效于用显存换准确率却换不到。具体例子：一段长视频在低分辨率桶里已丢失文字细节，再把时间压缩率翻倍，画面内字幕与动作连续性同时消失，下游问答退化。检查顺序：固定分辨率档位扫压缩率，观察下游指标拐点；回滚方案是给压缩率设上限并与帧率下限联动，超限时自动降帧率而非加压缩，同时保留未压缩路径用于离线高精度场景。</p>\n\n<h3 id=\"ap-video-frame-recipe-sec-24\">二十四 · 上线检查清单与回滚顺序</h3>\n<p>把上述坑收敛成一份按依赖排序的检查清单，顺序不能乱：配额键 → 帧率下限与运动自适应 → 分桶档位与编译缓存 → 压缩率与分辨率联合约束 → 尾延迟与吞吐回归。每一项都要有可观测量和明确的回滚开关，回滚顺序与检查顺序相反，先退最外层的增强层。</p>\n<table class=\"mini\"><thead><tr><th>检查项</th><th>观测信号</th><th>失败表现</th><th>回滚动作</th></tr></thead><tbody><tr><td>批配额键</td><td>批帧数分布 P99/P50</td><td>长请求独占 prefill，P99 抬升</td><td>切回按请求数配平并隔离长请求队列</td></tr><tr><td>帧率下限</td><td>高运动片段采样帧数</td><td>时序混叠，动作信息丢失</td><td>关闭运动自适应，抬全局下限</td></tr><tr><td>分桶档位</td><td>编译缓存命中率、显存碎片率</td><td>形状切换开销吃掉吞吐</td><td>切回粗档位表</td></tr><tr><td>时间压缩率</td><td>压缩率与分辨率档位组合</td><td>时空细节同时被削</td><td>压缩率封顶，改降帧率</td></tr></tbody></table>\n<p>回滚方案的设计原则是“增强层可独立关闭、默认路径始终可用”：运动自适应帧率、细粒度分桶、高压缩率三条都做成配置开关，默认走保守路径；每条开关旁挂一个自动触发条件，例如批帧数方差超阈值即回滚配额策略，编译缓存命中率跌破阈值即回滚档位表。工程判断上，宁可让默认路径的 token 预算偏保守、吞吐略低，也不要把三个增强层同时打开去赌一次上线——尾延迟与准确率的回归往往来自增强层之间的相互作用，而不是单层失效。</p>\n\n<h3 id=\"ap-video-frame-recipe-sec-25\">二十五 · 失效边界：配平口径、帧率下限与分桶粒度的三处塌陷</h3>\n<p>这套配方最脆弱的环节不在抽帧算法本身，而在三个\"看似合理\"的默认设定上。第一处是批内配平口径：调度器若以请求数为配额，一个两小时长视频与九个十秒短视频同批，长请求的视觉 token 在 prefill 阶段独占 SM 与 TMEM 带宽，短请求只能排队等它算完，批内尾延迟被单个请求绑架。正确做法是以总帧数或总视觉 token 数为配额，令 <span class=\"formula-inline\">B_frames</span> 满足 <span class=\"formula-inline\">Σ frames_i ≤ B_frames</span> 且批内帧数方差收敛；代价是调度器需要预知每请求的抽帧结果，抽帧与调度之间必须串行或做保守估计，这本身引入一拍额外延迟。工程判断是：宁可让批变小、批数变多，也不要让一个长请求把整批的 P99 拖到不可接受——后者在连续批处理下会通过 KV cache 占位进一步放大，长请求的中间态常驻显存，挤掉后续短请求的接纳空间。</p>\n<p>第二处是自适应帧率的下限。短视频提帧率、长视频降帧率以把单请求视觉 token 压进预算，这条规则在慢速镜头下成立，但在快速运动镜头上失效：帧率低于运动周期的一半时出现时序混叠，相邻帧采样到动作的不同相位，时间维压缩（对相邻时间步 embedding 做合并或池化）会把两个相位平均成一个不存在的中间态，动作信息被抹平而非被压缩。判据可写成采样定理形式：</p>\n<div class=\"formula\">$$f_s \\geq 2 f_{motion},\\quad N_{token} \\approx \\frac{T \\cdot f_s}{r_t} \\cdot N_{spatial}$$</div>\n<p>其中 <span class=\"formula-inline\">r_t</span> 为时间维压缩率，<span class=\"formula-inline\">N_spatial</span> 为单帧空间 token 数。帧率下限一旦设得过低，<span class=\"formula-inline\">N_token</span> 是省下来了，但下游准确率下降是静默的——离线评测集若以慢镜头为主，这个坑不会暴露，直到线上出现快速运动内容才显现。检查清单里必须有一条：对含快速运动的样本单独跑帧率下限扫描，观察压缩后 embedding 与未压缩版本的余弦距离，距离骤降即为混叠信号。</p>\n<p>第三处是分辨率分桶的档位粒度。分桶让同桶帧共享视觉塔输入形状，减少动态 shape 重编译与 padding 浪费；但档位过多时，视觉塔在相邻档之间反复重编译或切换 kernel，编译开销与显存碎片反过来吃掉分桶收益。失效条件是档位数与批内桶分布不匹配：批内桶越分散，每桶实际帧数越少，编译摊销越差。代价可定性为\"每桶固定开销 × 桶数\"与\"padding 浪费 × 帧数\"之间的权衡，档位应随批内实际分布收敛，而非按理论宽高比穷举。一个具体例子：竖屏短视频与横屏影视内容混跑时，若为每个宽高比各设一桶，批内可能同时出现四五个桶，视觉塔每步都在换形状，吞吐反而不如两档粗分桶加适度 padding。</p>\n<table class=\"mini\"><thead><tr><th>失效点</th><th>触发条件</th><th>可观测信号</th><th>回滚动作</th></tr></thead><tbody><tr><td>按请求数配平</td><td>长短视频同批</td><td>批内 P99 与均值差距拉大</td><td>切回按帧数配额，批上限下调</td></tr><tr><td>帧率下限过低</td><td>快速运动镜头</td><td>压缩前后 embedding 距离骤降</td><td>对该类内容锁定帧率下限</td></tr><tr><td>分桶档位过多</td><td>批内桶分散</td><td>kernel 切换与编译计数上升</td><td>合并至粗档位，容忍 padding</td></tr></tbody></table>\n<p>检查顺序应按\"先口径、再下限、后粒度\"排列：先验证配平口径是否以帧数为配额，再验证帧率下限对快速运动是否安全，最后才调分桶档位——前两者决定尾延迟与准确率，后者只影响吞吐。回滚方案要能分级：配平口径回滚是调度器参数，可在线切换；帧率下限回滚需按内容类型打标，属于策略层；分桶粒度回滚涉及视觉塔输入形状，需重建编译缓存，代价最高，因此应放在最后动、且改动前先固化一版桶表快照，出问题按快照回退而非逐档试错。</p>\n<h3 id=\"ap-video-frame-recipe-sec-26\">二十六 · 上游依赖：抽帧配方吃的是预处理工具链与视觉塔的接口契约</h3>\n<p>抽帧配方本身不产生任何算力收益，它的全部价值来自对下游两个接口的精确适配：预处理工具链的输出张量布局，以及视觉塔对输入形状的容忍度。配方里“统一分辨率分桶”这一条，本质上是与视觉塔的 kernel 选择表做对齐——每个桶对应一组固定的 H×W，视觉塔据此走同一条已编译的卷积或 attention 路径。若工具链在解码阶段就把帧缩放成任意宽高比，分桶环节就得再做一次重采样，多一次全帧读写；在 4K 素材上这一次重采样就是数 GB 级的显存带宽往返，直接吃掉分桶本该省下的 padding 收益。因此上游依赖的第一条是：解码器输出必须带可枚举的尺寸元数据，让分桶在解码后立即完成，而不是等到送进视觉塔前才做。</p>\n<p>第二条依赖是时间戳的保真度。自适应帧率要按“帧率与时长”决定采样密度，前提是容器层给出的 PTS 可信；变帧率素材（VFR）若被工具链按平均帧率强行恒定化，快速运动段落的实际采样点会偏移，配方里“短视频提高帧率保时序细节”的意图就落空。工程上要求预处理工具链透传原始 PTS 并在抽帧后回写采样时间戳，供后续时间维压缩时判断相邻时间步的真实间隔。代价体现在元数据通路上：每帧多一个 64 位时间戳字段，在万帧级批内是几十 KB 量级，可忽略；但若工具链丢弃 PTS 导致配方退化为均匀采样，则时序混叠的风险无法在下游被检测到。</p>\n<p>第三条依赖是镜头切分的边界来源。按镜头切分组织批要求上游提供镜头边界，这通常来自预处理阶段的直方图或光流检测。边界精度直接决定批内帧数方差：边界漏检会把两个镜头并成一个长片段，该片段帧数远超同批其他片段，正是批内方差收敛要压制的情形。因此抽帧配方对上游的契约是“边界列表 + 每段帧数”，而不是“一段视频一个请求”。</p>\n\n<h3 id=\"ap-video-frame-recipe-sec-27\">二十七 · 与视觉 token 压缩条目的分工：时间维压缩发生在抽帧之后、入 LLM 之前</h3>\n<p>本条目与视觉 token 压缩条目的边界必须划清，否则两处都做时间维合并会造成二次降采样。抽帧配方决定“取哪些时间步”，压缩条目决定“取到的时间步如何合并”。配方输出的是采样后的帧序列及其时间戳；压缩环节对相邻时间步的视觉 embedding 做合并或池化，降低序列长度而不改空间分辨率。两者的顺序不可交换：先压缩再抽帧等于在未采样的稠密序列上做池化，计算量按原始帧率计，显存峰值回到未优化状态。</p>\n<p>接口上的关键参数是压缩比与采样密度的乘积必须落在单请求视觉 token 预算内。设原始时长 T、原始帧率 f0、配方采样率 f1、时间维合并窗口 w，则送入 LLM 的视觉 token 数近似为：</p>\n<div class=\"formula\">$$N_{\\text{vis}} \\approx \\frac{T \\cdot f_1}{w} \\cdot \\frac{H \\cdot W}{p^2}$$</div>\n<p>其中 p 为空间 patch 尺寸。配方调 f1，压缩条目调 w，二者共同决定 N_vis。工程判断是：把预算约束主要压在 f1 上，因为降帧率减少的是视觉塔的前向次数，省的是整条视觉塔的算力与显存带宽；而增大 w 只减少 LLM 侧的序列长度，视觉塔仍要处理全部采样帧。以一段长视频为例，若只靠加大 w 把 N_vis 压到预算内，视觉塔的帧级前向次数不变，prefill 阶段的视觉塔耗时仍是瓶颈；反之若配方先把 f1 降到下限，视觉塔负载同步下降，但快速运动镜头面临时序混叠——这正是配方条目里“自适应帧率下限”阈值要守住的边界，压缩条目不应替它兜底。</p>\n<p>显存代价的分配也随之明确：视觉塔激活峰值由 f1 与批内总帧数决定，属抽帧与批配平的管辖范围；KV cache 中视觉 token 占用的长度由 N_vis 决定，属压缩与批调度的管辖范围。两个条目在容量规划时分别对应不同的显存池，混算会导致预分配失准。</p>\n\n<h3 id=\"ap-video-frame-recipe-sec-28\">二十八 · 下游影响之一：批配平把抽帧输出翻译成调度配额</h3>\n<p>抽帧配方产出的不是“请求”，而是“片段 + 帧数”。多模态批调度条目消费的正是这个帧数向量。批内按帧数而非请求数配平的含义是：调度器以总帧数/token 数为配额装批，而不是数请求个数。这一条把抽帧的输出直接变成调度器的输入约束——若配方输出的帧数方差大，调度器就必须做装箱（bin packing）而不是顺序填充；若配方通过分桶与镜头切分已经把帧数方差压小，调度器可以用近似 FIFO 的简单策略而仍保住尾延迟。</p>\n<p>伪代码层面的接口大致是：调度器维护一个以帧数为权重的配额 Q，装批时累加候选片段的帧数直到逼近 Q 即封批；长视频请求被拆成多个镜头片段后，单个片段不再可能独占整批配额。代价体现在批利用率上：配额按帧数计意味着批内请求数不固定，短片段多时请求数上升、每请求的固定开销（元数据、采样参数）摊薄；长片段多时请求数下降但单批 token 数饱和，prefill 带宽利用率高。失败模式在配方侧就已埋下：若镜头切分过粗，一个片段帧数超过 Q，调度器只能让它单独成批，prefill 被独占，同批短请求排队，P99 抬升——这正是配方必须保证“片段帧数上界”的原因。</p>\n<p>另一个下游影响是连续批处理中的 chunked prefill 切分点。视觉 token 序列被时间维压缩后长度已知，调度器可据此决定把一次 prefill 切成几个 chunk；若配方输出的 N_vis 波动大，chunk 边界难以对齐，迭代间气泡增多。因此配方在预算内稳定 N_vis，等于替调度器省掉了动态切分的决策开销。</p>\n\n<h3 id=\"ap-video-frame-recipe-sec-29\">二十九 · 下游影响之二：分离式预填与显存溢出条目的输入假设</h3>\n<p>多模态分离式预填配方把视觉塔前向放在预填节点、把 LLM 解码放在解码节点，其容量假设直接引用抽帧配方的输出：预填节点的算力需求正比于批内总帧数，而非请求数。若抽帧配方未做分桶，预填节点收到的输入形状动态变化，视觉塔 kernel 反复重编译，预填节点的吞吐被编译开销侵蚀；分桶档位过多同样触发频繁 kernel 切换，编译开销与显存碎片抵消分桶收益——这条失败模式在分离式部署下被放大，因为预填节点是纯吞吐机器，任何非计算开销都直接体现为节点数需求上升。</p>\n<p>视觉塔显存溢出条目关注的是单次前向的激活峰值。抽帧配方通过限制批内总帧数与单帧分辨率上界，为溢出条目提供了可计算的输入：峰值激活近似正比于批内帧数 × 单帧空间 token 数 × 每 token 激活字节。配方把这两个乘数都框在桶内，溢出条目才敢按固定值预分配 workspace；否则只能按最坏情况预留，显存利用率下降。工程判断是：分桶的档位数应少到让 workspace 可按最大桶预分配而不浪费，多到让 padding 浪费可接受——这个折中点在配方条目里定，溢出条目只消费结果。</p>\n<p>功耗维度上，预填节点的视觉塔是持续高利用率负载，抽帧降帧率直接线性削减其能耗；解码节点的功耗由 KV cache 读取主导，与抽帧无直接关系。因此配方对分离式部署的省电贡献全部落在预填侧，容量规划时不应把抽帧优化计入解码节点的功耗预算。</p>\n\n<h3 id=\"ap-video-frame-recipe-sec-30\">三十 · 在全书中的位置：视觉前端的“入口整形器”</h3>\n<p>把全书的多模态推理链路摊开，抽帧配方处在最前端、唯一同时约束算力与显存两条曲线的环节。它上游接预处理工具链，下游同时喂给视觉塔（算力）、KV cache（显存）、调度器（配额）、分离式预填（节点容量）。它的输出是一个三元组：片段列表、每片段帧数、每帧所属分辨率桶。全书其余条目大多消费这个三元组的某一个分量——压缩条目消费帧序列的时间结构，批调度条目消费帧数向量，量化配方消费桶对应的固定形状以选定 NVFP4/FP8 kernel，上线前清单则逐项核对这三个分量是否都落在阈值内。</p>\n<p>这也解释了为什么本条目不适合承载具体数值阈值之外的调参讨论：任何下游条目的优化若绕开抽帧输出直接改输入形状，都会让上游契约失效。例如量化配方为追求吞吐把视觉塔输入改成非桶内形状，分桶收益归零；又如批调度为提升批内请求数把长片段强行与短片段混装，尾延迟失败模式复现。正确的位置感是：抽帧配方定形状与配额，下游只做消费与校验，不反向修改。</p>\n<p>工程判断落在最后一道关口：当上游 PTS 不可信或镜头边界缺失时，配方应退化为保守的均匀采样并显式标记该请求，让调度器按最坏帧数配额装批，而不是让不确定性渗透到下游的容量假设里。这条退化路径本身就是全书“把不确定性挡在入口”的原则在视觉前端的具体实现。</p>\n\n<h3 id=\"ap-video-frame-recipe-sec-31\">三十一 · 配方边界：何时这套抽帧与批组织会反噬</h3>\n<p>这套配方的前提是“单请求视觉 token 可预算、批内帧数可对齐”。一旦前提破裂，收益立刻转为代价。最典型的失效是只按请求数配平：调度器把一条长视频与若干短视频塞进同一 prefill 批，长请求的视觉 token 占满 tensor 并行切分后的激活预算，短请求只能等它算完才拿到第一个 token，P99 尾延迟被单条长请求拖高。工程上应把配额改成帧数或视觉 token 数，即批内约束 <span class=\"formula\">$$\\sum_{i \\in B} F_i \\le F_{\\max},\\quad \\max_{i \\in B} F_i \\le \\alpha \\bar{F}_B$$</span> 其中 $F_i$ 为请求 $i$ 的抽帧数，$\\alpha$ 控制批内最长与均值之比。$\\alpha$ 取紧，批内长度方差收敛，prefill 的 SM 占用更均匀；$\\alpha$ 取松，吞吐略升但尾延迟失控。这是调度器层面的显存与带宽代价，不是模型问题。</p>\n<p>第二个边界在自适应帧率的下限。为控 token 总量而把长视频帧率压得过低，快速运动镜头会出现时序混叠：相邻采样帧之间物体位移超过空间感受野，时间维压缩（相邻时间步 embedding 合并或池化）后动作信息不可恢复，下游准确率下降。此时压缩比 $r_t$ 与采样间隔 $\\Delta t$ 必须联合约束，<span class=\"formula\">$$v_{\\max}\\Delta t \\cdot r_t \\le \\delta_{\\text{roi}}$$</span> $v_{\\max}$ 为场景最大像速，$\\delta_{\\text{roi}}$ 为可容忍的位移像素。帧率下限应按镜头运动强度而非视频时长单独设定，否则“省 token”直接换来精度损失，且损失在压缩后无法用更大 LLM 弥补。</p>\n<p>第三个边界是分辨率分桶的档位数量。分桶让同桶帧共享视觉塔输入形状，减少动态 shape 重编译与 padding 浪费；但档位过多会让视觉塔在批间频繁切换 kernel 与重编译，编译开销和显存碎片抵消吞吐收益。判断标准是分桶带来的 padding 节省是否大于形状切换的固定开销：<span class=\"formula\">$$\\text{净收益} \\approx \\frac{W_{\\text{pad}}}{W_{\\text{total}}} - \\frac{c_{\\text{recompile}}}{N_{\\text{batch}}}$$</span> 档位应压到个位数并与实际宽高比分布对齐，而不是按输入逐档细分。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>直接代价</th><th>工程对策</th></tr></thead><tbody><tr><td>按请求数配平</td><td>P99 尾延迟抬升、prefill 带宽被独占</td><td>按帧数/token 配额，限制批内最长/均值比</td></tr><tr><td>帧率下限过低</td><td>时序混叠、压缩后动作信息丢失</td><td>按镜头运动强度设下限，约束 $\\Delta t \\cdot r_t$</td></tr><tr><td>分桶档位过多</td><td>重编译与 kernel 切换、显存碎片</td><td>档位压到个位数，对齐宽高比分布</td></tr></tbody></table>\n<p>在全书位置上，这一节是视觉前端与 LLM 调度之间的接缝：向上它依赖视觉塔的形状契约与 token 预算，向下它决定 prefill 批的组成与 KV cache 的序列长度分布，因此任何批调度或显存规划条目都必须把“帧数配额”当作输入而不是事后修正。判断这套配方是否适用，只看一条：批内帧数方差是否已被调度器显式约束；没有约束，抽帧再精细也会被一条长视频拖垮整批。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-video-frame-recipe\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>按帧率与时长自适应抽帧、统一分辨率分桶、按镜头切分组织批，视频token按时间维压缩后再送入LLM</td></tr><tr><td>关键点</td><td>批内按帧数而非请求数配平，避免长视频请求独占prefill导致尾延迟飙升。</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-video-frame-recipe · 共 5 个片段</p>\n"},{"id":"ap-mm-prefill-decode","title":"多模态分离式预填配方","summary":"将视觉编码与LLM prefill放在预填节点、解码放解码节点，视觉embedding经高速互联传输；按图像token量做预填分块与优先级调度，使解码侧KV cache增长可预测并稳定TPOT。","kind":"配方","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-1\">一 · 条目边界：它到底在分离什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-2\">二 · 分类维度：按什么切分这个配方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-3\">三 · 与相邻概念的区别：三组容易混淆的对</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-4\">四 · 核心机制的形式化：分块、优先级与可预测性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-5\">五 · 具体例子：一次长视觉序列请求的完整路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-6\">六 · 多模态分离式预填的边界：何时解耦、何时失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-7\">七 · 速查表总览：字段口径与读法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-8\">八 · 分块粒度与传输对齐：C 的算法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-9\">九 · 产出/消费比 ρ 与 KV 增长斜率</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-10\">十 · 优先级分档：按 token 量而非到达顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-11\">十一 · 扩缩容同步与容量规划口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-12\">十二 · 速查表之外的失效边界：什么情况下这张表会骗你</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-13\">十三 · 配方速查表：字段、阈值与失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-14\">十四 · 阈值从哪里来：先把三条链路量化成同一把尺子</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-15\">十五 · 分块阈值：块大小由解码侧可容忍的 KV 增长步长决定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-16\">十六 · 优先级阈值：按 token 量分级，而不是按到达顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-17\">十七 · 扩缩容阈值：产出速率与消费速率的比值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-18\">十八 · 一致性开销与传输对齐的测量口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-19\">十九 · 没有数字时怎么测：最小可复现的标定流程</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-20\">二十 · 阈值从哪里来：三类可测量、两条硬边界、一个对齐公式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-21\">二十一 · 阈值不是拍脑袋：三类可测边界与失效判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-22\">二十二 · 坑一：embedding 传输与预填分块不对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-23\">二十三 · 坑二：扩缩容不同步导致 KV cache 堆积</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-24\">二十四 · 坑三：优先级只看到达顺序，不看 token 量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-25\">二十五 · 检查顺序：从传输对齐到速率守恒再到优先级</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-26\">二十六 · 回滚方案：按影响面分层退避</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-27\">二十七 · 失效边界：三类典型故障的触发链与检查顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-28\">二十八 · 上游依赖：视觉塔与预处理链路决定传输量基线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-29\">二十九 · 上游依赖：多模态批调度与框架能力约束分块粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-30\">三十 · 下游影响：解码侧 KV cache 增长模型与 TPOT 收敛</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-31\">三十一 · 下游影响：容量规划与扩缩容同步性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-32\">三十二 · 在全书中的位置：与量化、互联、SLO 三条主线的交点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-prefill-decode-sec-33\">三十三 · 配方边界：互联带宽、分块对齐与扩缩容耦合</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-mm-prefill-decode\"><svg style=\"max-width:510px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 509.6 357\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"427.6\" height=\"83.0\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"53.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"57.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：多模态分离式预填配方</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">将视觉编码与LLM prefill放在预填节点、解码放解码节点，视觉</text><text x=\"75.0\" y=\"78.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">embed…</text><line x1=\"82.0\" y1=\"97.0\" x2=\"82.0\" y2=\"114.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 113.0 L 86.5 113.0 L 82.0 121.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"121.0\" width=\"427.6\" height=\"83.0\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"162.6\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"166.8\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"148.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">入口</text><text x=\"75.0\" y=\"171.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">按图像token量做预填分块与优先级调度，使解码侧KV cache增长可</text><text x=\"75.0\" y=\"187.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">预测并…</text><line x1=\"82.0\" y1=\"206.1\" x2=\"82.0\" y2=\"223.1\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 222.1 L 86.5 222.1 L 82.0 230.1 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"230.1\" width=\"427.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"252.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"256.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"257.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">依赖</text><line x1=\"82.0\" y1=\"276.9\" x2=\"82.0\" y2=\"293.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 292.9 L 86.5 292.9 L 82.0 300.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"300.9\" width=\"427.6\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"323.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"327.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"328.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">最小复现</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-mm-prefill-decode-sec-1\">一 · 条目边界：它到底在分离什么</h3>\n<p>多模态分离式预填配方（multimodal disaggregated prefill）指：把视觉编码器前向与 LLM 的 prefill 阶段一起放在“预填节点”上执行，把自回归解码放在“解码节点”上执行，两侧之间只传递视觉 embedding（以及必要的 KV 元数据），不传递原始像素。它的分离粒度是<strong>阶段</strong>而非<strong>模型</strong>：视觉塔与语言模型并未被拆到不同机器上各自成篇，而是被归入同一侧，因为二者共享同一种负载形态——一次性、大算力、输出体积与输入 token 数成正比的稠密前向。真正被切开的是“算力密集且显存瞬时占用高”的 prefill 与“带宽密集且状态常驻”的 decode。</p>\n<p>这个定义排除了三类相邻做法。其一，纯文本 PD 分离：文本场景下 prefill 输出的是 KV cache，传输量正比于层数×头数×序列长×精度字节；多模态场景下 prefill 还要额外搬运视觉 embedding，其体积正比于图像 token 数×隐维×精度，两笔账必须分开做容量规划。其二，视觉塔独立服务（vision-as-a-service）：那只是把编码器摘出来做无状态批处理，prefill 仍与 decode 同机，KV 增长依旧不可预测。其三，单机内阶段流水（chunked prefill + 连续批处理）：它靠时间切片缓解抢占，但没有把两类负载的显存与算力特征真正解耦，扩缩容仍绑在同一组 GPU 上。本配方的判别性特征是<strong>两侧可独立扩缩容</strong>，这既是它存在的理由，也是它全部代价的来源。</p>\n<p>工程上判断一个部署是否属于本配方，看三个可观测事实：预填节点是否同时持有视觉塔权重与 LLM 全部层权重；解码节点是否只持有 LLM 权重与 KV cache、不持有视觉塔；跨节点链路上是否出现与图像 token 数成正比的 embedding 流量。三者齐备才算，缺一即是变体。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-2\">二 · 分类维度：按什么切分这个配方</h3>\n<p>同一名字下的实现差异极大，需要用四个正交维度定位，否则“我们上了分离式预填”这句话在容量规划时毫无信息量。</p>\n<ul>\n<li><strong>切分位置</strong>：在视觉塔之后切（传视觉 embedding），还是在 LLM 第 k 层之后切（传中间激活）。前者传输量小、语义干净，但要求解码节点从第 0 层开始重算位置编码与跨模态对齐；后者传输量大但解码侧启动更快。本配方默认指前者。</li>\n<li><strong>分块依据</strong>：按固定 token 数切，还是按图像 token 量自适应切。后者是本配方的核心机制，直接决定解码侧 KV 增长是否可预测。</li>\n<li><strong>优先级策略</strong>：按到达顺序（FCFS）、按 token 量（短请求优先）、按 SLO 余量（deadline 最近者优先）。只有后两者能与分块配合压住 TPOT 抖动。</li>\n<li><strong>传输通道</strong>：节点内 NVLink 域、跨节点 RDMA（NIXL 一类点对点搬运）、或经 NCCL 集合通信中转。通道选择决定 embedding 传输是叠加在首 token 延迟上还是被流水掩盖。</li>\n</ul>\n<p>四维组合出可用的工程坐标。举例：一个 8 卡预填池 + 8 卡解码池的部署，若切分位置在视觉塔后、分块按图像 token 量自适应、优先级按 token 量、传输走跨节点 RDMA，则它属于“可预测 KV 增长”型；若把优先级换回 FCFS，同一套硬件立刻退化为“长视觉序列可抢占预填资源”的失败形态，TPOT 稳定性目标落空。分类不是学术标签，而是失败模式的预警器。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-3\">三 · 与相邻概念的区别：三组容易混淆的对</h3>\n<p><strong>与多模态批调度</strong>：批调度回答“哪些请求进这一批、按什么顺序”，作用域在单侧内部；分离式预填回答“哪一侧执行哪一阶段、两侧如何配速”，作用域跨节点。二者会互相污染——预填侧的分块策略若不被解码侧的批调度感知，解码节点会按自己的批节奏消费 KV，导致堆积。区别的实操含义：批调度调的是 batch 组成，本配方调的是<em>产出速率与消费速率的匹配</em>。</p>\n<p><strong>与视觉 token 压缩</strong>：压缩改变的是 embedding 的体积本身（token 数下降），本配方改变的是这些 token 在何时、何地被产生和搬运。压缩是减小传输量的分子，分离式预填是管理传输的时序。二者叠加时要注意：压缩率不稳定会让“按图像 token 量分块”的切点抖动，分块边界与压缩后实际 token 数不一致，正是“embedding 传输未与 prefill 分块对齐”的一个具体来源。</p>\n<p><strong>与视觉塔显存溢出</strong>：后者是单节点内视觉塔激活峰值挤爆显存的故障；本配方通过把视觉塔挪到预填节点、让解码节点不承担这部分峰值来规避它，但代价是把压力转成了跨节点传输延迟。也就是说，它不是消除了显存问题，而是把显存约束换成了互联带宽约束。</p>\n<table class=\"mini\"><thead><tr><th>概念</th><th>作用域</th><th>调节量</th><th>主要代价</th></tr></thead><tbody><tr><td>多模态批调度</td><td>单侧批内</td><td>batch 组成与顺序</td><td>批内尾延迟</td></tr><tr><td>视觉 token 压缩</td><td>编码器输出</td><td>token 数</td><td>精度损失</td></tr><tr><td>视觉塔显存溢出</td><td>单节点显存</td><td>激活峰值</td><td>OOM 中断</td></tr><tr><td>本配方</td><td>跨节点两阶段</td><td>产出/消费速率匹配</td><td>互联延迟与一致性开销</td></tr></tbody></table>\n\n<h3 id=\"ap-mm-prefill-decode-sec-4\">四 · 核心机制的形式化：分块、优先级与可预测性</h3>\n<p>设请求 i 的图像 token 数为 <span>n_i</span>，预填节点以块大小 <span>B</span> 切分，则块数 <span>k_i = ⌈n_i / B⌉</span>。预填侧单位时间产出的 KV 条目速率受块调度约束，解码侧单位时间消费的 KV 条目速率由批内并发解码请求数与 TPOT 目标决定。可预测性的形式化条件可写成：</p>\n<div class=\"formula\">$$\\frac{d}{dt}\\mathrm{KV}_{dec} = R_{pre}(t) - R_{dec}(t) \\approx 0,\\quad R_{pre}(t)=\\sum_{i\\in \\text{active}} \\frac{B\\cdot \\mathbf{1}[\\text{block } j \\text{ of } i \\text{ done}]}{\\tau_{blk}(B)}$$</div>\n<p>其中 <span>τ_blk(B)</span> 是单块预填耗时，随 B 增大而超线性上升（注意力与 MLP 的算力占比变化）。工程含义是：B 太小则块间调度开销与跨节点小包传输开销占比升高，B 太大则单块占用预填资源过久、短请求被拖住。伪代码层面的调度骨架是——按 <span>n_i</span> 升序维护就绪队列，短请求整段预填并立即推送 embedding，长请求切成 <span>k_i</span> 块、每块完成即推送、块间让出算力给新到的短请求；解码侧按已到达的完整块启动对应位置的 KV 写入，未到齐的块不阻塞已到块的解码。</p>\n<p>代价必须明写：跨节点传输延迟 <span>L_t</span> 与一致性开销 <span>L_c</span>（序号对齐、乱序重排、块边界校验）直接叠加到首 token 延迟上，除非用流水掩盖。容量规划的自由变量是三元组（token 量分布、互联带宽、批大小），而不是单节点吞吐——追求单节点吞吐最大化会推高 B，反而破坏解码侧的可预测性。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-5\">五 · 具体例子：一次长视觉序列请求的完整路径</h3>\n<p>取一个工程上常见的形态：某请求带一张高分辨率图像，编码后产生大量视觉 token（量级由预处理与压缩策略决定，此处不虚构数值），进入预填节点。调度器读 <span>n_i</span> 后判定为长请求，切成若干块并置为低优先级；同时到达的三个短请求（小图或纯文本）整段预填、优先占用算力。第一块预填完成即通过 RDMA 推送 embedding 到解码节点，解码节点在收到块 1 后即开始该段位置的 KV 写入与首 token 生成，而不等整段 embedding 到齐——这正是规避“等待整段 embedding 到达才启动”失败模式的关键动作。后续块陆续到达，KV 按块序增长，增长节奏由 <span>R_pre</span> 与 <span>R_dec</span> 的匹配决定，TPOT 波动因此收敛，因为解码节点不再被突发的长视觉序列 prefill 抢占算力与显存带宽。</p>\n<p>该路径上的三个可观测代价点：其一，块 1 的传输延迟直接进入首 token 延迟，量级由互联带宽与块体积决定；其二，若预填池扩容快于解码池，<span>R_pre &gt; R_dec</span>，KV 在解码侧堆积直至显存溢出，这是扩缩容不同步的典型故障；其三，若优先级只看到达顺序，长请求仍可抢占预填资源，前述分块机制形同虚设。三个代价点分别对应本配方在延迟、显存、稳定性上的三处脆弱面，也是分类维度中“切分位置/分块依据/优先级策略”三项选择的实际落点。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-6\">六 · 多模态分离式预填的边界：何时解耦、何时失效</h3>\n<p>多模态分离式预填的准确定义是：把视觉编码器与 LLM prefill 绑定在预填节点上执行，解码节点只承担自回归生成；两者之间流动的不是原始像素，也不是完整的 KV cache，而是视觉 embedding 张量。这一定义划出了三条分类维度。其一是切分位置——切在视觉编码之后、LLM prefill 之前，意味着预填节点必须同时容纳视觉塔与语言塔的前段权重，解码节点只持有语言塔的解码层与 KV cache，显存画像因此被拆成两份互不重叠的份额。其二是传输对象——传 embedding 而非传 KV，使跨节点流量正比于图像 token 数而非序列长度乘层数，量级上小得多，但也意味着解码节点必须自己完成 embedding 到 KV 的投影，预填节点省下的算力并未消失，只是转移。其三是调度粒度——按图像 token 量分块，而不是按请求整体排队，这决定了该配方是否具备可预测性。</p>\n<p>与相邻概念的区别必须说清，否则容量规划会算错。它不同于 PD 分离（prefill-decode disaggregation）：后者切的是同一模态序列的 prefill 与 decode，KV cache 是跨节点传输的主体；本配方切的是模态负载，传输主体是 embedding，KV 始终留在解码侧生成。它也不同于 chunked prefill：后者在单节点内把长 prefill 切片以平滑 TPOT，本配方把切片动作跨到了节点边界上，切片粒度同时受 token 量与互联带宽两个变量约束。它更不同于视觉编码卸载：卸载只把视觉塔挪走，prefill 仍与 decode 同节点，两类负载的显存与算力特征并未解耦，扩缩容也无法独立进行。</p>\n<p>边界条件可以用一个不等式刻画。设单块 embedding 传输量为 <span class=\"formula\">$$S_b = T_b \\cdot d$$</span>，其中 <span class=\"formula\">$$T_b$$</span> 为该块图像 token 数、<span class=\"formula\">$$d$$</span> 为每 token embedding 字节数，互联有效带宽为 <span class=\"formula\">$$B$$</span>，则解码节点启动该块解码的最早时刻受 <span class=\"formula\">$$S_b/B$$</span> 约束；只有当分块边界与传输完成事件对齐、且 <span class=\"formula\">$$S_b/B$$</span> 小于该块解码所需时间时，传输才被完全隐藏在计算之后。一旦分块大于解码消费能力，互联延迟就直接叠加到首 token 延迟上——这正是该配方最典型的失效模式：视觉 embedding 传输未与 prefill 分块对齐，解码节点等待整段 embedding 到达才启动。工程上的判断标准是让传输块与解码块一一对应、流水推进，而不是整段到达后再开闸。</p>\n<p>第二类失效来自扩缩容不同步：预填产出速率超过解码消费速率，KV cache 在解码侧单调堆积直至显存溢出。此时系统代价不是延迟而是显存，且溢出发生在最贵的解码节点上。第三类失效来自优先级调度只按到达顺序而非 token 量，长视觉序列请求仍可抢占预填资源，TPOT 稳定性目标落空。三类失效共同指向一个结论：该配方的收益不在单节点吞吐，而在解码侧 KV cache 增长的确定性；代价则是跨节点传输延迟与一致性开销。容量规划必须在 token 量、互联带宽与批大小三者间联立求解，把互联带宽当作一等约束而非余量。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>成立条件</th><th>失效信号</th><th>主要代价</th></tr></thead><tbody><tr><td>传输对齐</td><td>分块边界与 embedding 到达事件同步</td><td>首 token 延迟随图像 token 线性上升</td><td>互联延迟叠加至 TTFT</td></tr><tr><td>速率匹配</td><td>预填产出 ≤ 解码消费</td><td>解码侧 KV cache 持续堆积</td><td>解码节点显存溢出</td></tr><tr><td>调度依据</td><td>按图像 token 量分级</td><td>长序列请求抢占预填</td><td>TPOT 波动扩散</td></tr></tbody></table>\n<h3 id=\"ap-mm-prefill-decode-sec-7\">七 · 速查表总览：字段口径与读法</h3>\n<p>这张表按“一行一个决策点”组织，字段固定为六列：<strong>字段</strong>（配置项或观测量）、<strong>取值口径</strong>（怎么算、算谁的）、<strong>建议阈值</strong>（可直接落成配置或告警线）、<strong>越界后果</strong>（对应哪条失败模式）、<strong>调参方向</strong>（往哪边拧）、<strong>验证方法</strong>（用什么量确认改对了）。阈值只给相对量纲与比例关系，不给绝对毫秒数——因为绝对数值取决于互联代际与模型，而比例关系在 B200/B300、GB200/GB300 NVL72 上是一致的。读表时先看“取值口径”再看阈值：口径错了，阈值再准也是错的。表中所有阈值均以“预填节点产出速率”与“解码节点消费速率”这两个可测量为基准，其余字段都是它们的派生量。</p>\n<table class=\"mini\">\n<thead><tr><th>字段</th><th>取值口径</th><th>建议阈值</th><th>越界后果</th><th>调参方向</th><th>验证方法</th></tr></thead>\n<tbody>\n<tr><td>视觉 token 量 <em>N<sub>v</sub></em></td><td>单请求图像经视觉塔与压缩后进入 LLM 的 token 数，不含文本 token</td><td>作为分块与优先级的唯一分档依据</td><td>按到达顺序调度则长序列抢占</td><td>压缩比、分辨率、抽帧数</td><td>按 <em>N<sub>v</sub></em> 分桶统计 P50/P99</td></tr>\n<tr><td>分块粒度 <em>C</em></td><td>单次预填提交的视觉 token 数上限</td><td><em>C</em> ≤ 单块 embedding 传输量对应互联时延的 1/4 个 TPOT 预算</td><td>传输未对齐分块，首 token 等待整段</td><td>减小 <em>C</em> 或提高互联并发</td><td>首 token 延迟与 <em>C</em> 的散点关系</td></tr>\n<tr><td>embedding 传输量 <em>B<sub>e</sub></em></td><td><em>N<sub>v</sub></em> × 每 token 字节数（精度决定）</td><td>单请求 <em>B<sub>e</sub></em> 不超过解码节点单批 KV 写入带宽的等效时长</td><td>互联带宽成为瓶颈，解码侧空转</td><td>降精度、压缩、分块流水</td><td>互联利用率与解码 SM 占用率联看</td></tr>\n<tr><td>产出/消费比 <em>ρ</em></td><td>预填节点 token 产出速率 ÷ 解码节点 token 消费速率</td><td>稳态 <em>ρ</em> ∈ [1.0, 1.2]，瞬时峰值允许到 1.5 但需回落到 1.2 内</td><td><em>ρ</em>&gt;1 持续则 KV 堆积至溢出</td><td>扩预填或缩预填、调批大小</td><td>解码侧 KV 占用随时间的斜率</td></tr>\n<tr><td>KV 增长斜率 <em>k</em></td><td>解码节点 KV cache 字节数对时间的导数，按批归一</td><td>批内 <em>k</em> 的方差不超过均值的 20%</td><td>斜率抖动直接体现为 TPOT 抖动</td><td>分块对齐、优先级分档</td><td>TPOT 的 P99/P50 比</td></tr>\n<tr><td>优先级分档</td><td>按 <em>N<sub>v</sub></em> 分档，不按到达时间</td><td>≥3 档，大 token 请求降档且必须可切块</td><td>长视觉序列仍抢占预填资源</td><td>档位边界随 <em>N<sub>v</sub></em> 分布重划</td><td>各档请求的预填等待时间分布</td></tr>\n<tr><td>扩缩容同步度</td><td>预填副本数与解码副本数的变更时序差</td><td>预填扩容先于解码扩容一个调度周期</td><td>产出速率超过消费速率</td><td>联动扩缩容策略</td><td>扩容后 <em>ρ</em> 的收敛时间</td></tr>\n</tbody>\n</table>\n\n<h3 id=\"ap-mm-prefill-decode-sec-8\">八 · 分块粒度与传输对齐：<em>C</em> 的算法</h3>\n<p>失败模式里最隐蔽的一条是“视觉 embedding 传输未与 prefill 分块对齐”：解码节点等整段 embedding 到齐才启动，互联延迟被整段叠加到首 token 延迟上。修法不是简单调小分块，而是让<strong>传输单元与计算单元同粒度</strong>。设单块视觉 token 数为 <em>C</em>，每 token embedding 字节数为 <em>b</em>，则单块传输量 <em>B<sub>e</sub></em> = <em>C</em>·<em>b</em>；设互联有效带宽为 <em>W</em>，则单块传输时延 <em>t<sub>x</sub></em> = <em>C</em>·<em>b</em>/<em>W</em>。解码侧启动首 token 的等待不应超过一个 TPOT 预算 <em>T<sub>tp</sub></em> 的若干分之一，于是得到分块上界：</p>\n<div class=\"formula\">$$C \\le \\frac{\\alpha \\cdot T_{tp} \\cdot W}{b}, \\quad \\alpha \\in (0, 0.25]$$</div>\n<p>系数 <em>α</em> 取 1/4 的含义是：把首 token 等待压到 TPOT 预算的四分之一以内，剩下四分之三留给解码侧真实的 KV 读取与注意力计算。工程上更实用的做法是<strong>流水化</strong>：预填节点算完第 <em>i</em> 块即发起传输，解码节点在第 <em>i</em>−1 块到达时就开始消费，使 <em>t<sub>x</sub></em> 被计算时间掩盖。此时真正的约束变成“传输吞吐 ≥ 计算吞吐”，即 <em>W</em>/<em>b</em> ≥ 预填节点每秒产出的视觉 token 数。举例：一个请求 <em>N<sub>v</sub></em> 很大，被切成若干块，若不分块对齐，解码节点要等全部块到齐才动，首 token 延迟里含整段传输；对齐后首 token 延迟只含首块传输，后续块在解码进行中陆续到达。代价是解码侧需要额外的接收缓冲与块间状态管理，显存开销随块数线性增长——这是用少量显存换首 token 延迟的典型交易。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-9\">九 · 产出/消费比 <em>ρ</em> 与 KV 增长斜率</h3>\n<p>第二条失败模式是扩缩容不同步导致 KV 在解码侧堆积直至溢出。它的可观测代理量就是 <em>ρ</em>。定义预填节点在窗口内的视觉 token 产出速率为 <em>R<sub>p</sub></em>，解码节点消费速率为 <em>R<sub>d</sub></em>（以每秒可接纳并完成 prefill 的 token 计），则 <em>ρ</em> = <em>R<sub>p</sub></em>/<em>R<sub>d</sub></em>。解码侧 KV 字节数 <em>M<sub>kv</sub></em>(<em>t</em>) 的增长斜率为：</p>\n<div class=\"formula\">$$k(t) = \\frac{dM_{kv}}{dt} = (\\rho(t) - 1) \\cdot R_d \\cdot s_{kv}$$</div>\n<p>其中 <em>s<sub>kv</sub></em> 是每 token 的 KV 字节数。阈值定在 <em>ρ</em> ∈ [1.0, 1.2]：低于 1.0 说明预填侧成为瓶颈、解码侧饿着；高于 1.2 则 <em>k</em>(<em>t</em>) 持续为正，KV 单调上升，溢出只是时间问题。1.2 这个上界不是拍出来的，它对应“在解码侧预留的 KV 余量被填满之前，扩缩容控制器至少完成一次扩容决策”的余量比例。验证方法很直接：把解码侧 KV 占用画成时间序列，稳态段斜率应接近零且方差小；若出现阶梯状上升，说明预填产出是突发的，需回头查分块与优先级。代价方面，<em>ρ</em> 压得越接近 1.0，解码侧越没有缓冲余量，任何预填抖动都会传导成 TPOT 抖动；因此工程判断是“稳态略大于 1，靠优先级分档吸收瞬时峰值”，而不是把 <em>ρ</em> 锁死在 1.0。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-10\">十 · 优先级分档：按 token 量而非到达顺序</h3>\n<p>第三条失败模式是优先级只按到达顺序排，长视觉序列仍能抢占预填资源。速查表里这一行的口径必须写死：<strong>分档键是 <em>N<sub>v</sub></em>，不是时间戳</strong>。建议至少三档：小 token 请求（高优先级、整块预填）、中 token 请求（中优先级、按 <em>C</em> 切块）、大 token 请求（低优先级、强制切块且每轮只提交一块）。伪代码思路如下：</p>\n<ul>\n<li>入队时计算 <em>N<sub>v</sub></em>，映射到档位 <em>p</em> = f(<em>N<sub>v</sub></em>)，f 为单调递减阶梯函数；</li>\n<li>预填调度器每轮从高到低扫描档位，高档次每轮最多提交 <em>C</em> 个 token，低档次提交 <em>C</em> 且提交后让出；</li>\n<li>解码侧按块到达顺序消费，块间不等待整段完成，KV 增长因此被摊平为近似恒定斜率。</li>\n</ul>\n<p>这套机制的收益直接体现在 KV 增长斜率 <em>k</em> 的方差上：按到达顺序调度时，一个大请求可能一次性推高 <em>k</em>；按 token 量分档并切块后，<em>k</em> 被切成等幅小台阶，方差收敛。代价是预填节点的调度开销上升（每轮多一次档位扫描与块状态维护），以及大请求的完成时间被拉长——这是用大请求的尾延迟换全体请求的 TPOT 稳定性，属于该配方的核心取舍。具体例子：同一批里混入一个 <em>N<sub>v</sub></em> 远大于其他的请求，若不降档，它会占满预填算力数个周期，期间解码侧 KV 增长出现尖峰；降档切块后，它每周期只贡献一块，其余算力留给小请求，解码侧看到的 <em>k</em> 曲线变平。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-11\">十一 · 扩缩容同步与容量规划口径</h3>\n<p>该配方的代价是跨节点传输延迟与一致性开销，容量规划要在 token 量、互联带宽与批大小三者之间做，而非追单节点吞吐。速查表最后两行就是这条的落地：扩缩容同步度要求预填扩容先于解码扩容一个调度周期，理由是 <em>ρ</em> 的分母 <em>R<sub>d</sub></em> 提升需要时间（新解码副本要预热、要建立 KV 空间），若两者同时扩，瞬态 <em>ρ</em> 会冲高。容量规划的基本不等式是：</p>\n<div class=\"formula\">$$W \\ge \\frac{N_v^{P99} \\cdot b \\cdot Q}{T_{tp}}$$</div>\n<p>其中 <em>Q</em> 是目标并发请求数。这条不等式说明互联带宽不是“够用就行”，而是被 P99 视觉 token 量与并发数直接锁定；<em>N<sub>v</sub></em> 的长尾会显著抬高带宽需求，因此视觉 token 压缩与分辨率策略在此配方里不是可选项而是容量前提。工程判断：先按 P99 而非均值规划带宽，再按均值规划算力，两者差额用分块流水与优先级分档吸收；若带宽按均值规划，长尾请求会周期性打穿 <em>t<sub>x</sub></em> 预算，首 token 延迟出现不可预测的尖峰。验证方法是把互联利用率与解码 SM 占用率画在同一时间轴上：健康状态下两者反相（传输忙时计算也忙，说明流水掩盖成功），同相则说明传输在等计算或计算在等传输，分块粒度需要重算。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-12\">十二 · 速查表之外的失效边界：什么情况下这张表会骗你</h3>\n<p>速查表的价值在于把“图像 token 量—互联带宽—批大小”三者压成可查的阈值，但它只在配方假设成立时有效。第一个假设是视觉 embedding 的传输粒度与预填分块粒度一致：若预填节点按 512 token 切块产出，而传输层按整段请求聚合发送，解码节点就必须等最后一块 embedding 到齐才启动首 token 计算，互联延迟从“可重叠的流水”退化为“串行等待”。此时首 token 延迟近似为 <span class=\"formula\">$$T_{FTT} \\approx T_{prefill} + \\frac{S_{emb}}{B_{link}} + T_{decode\\_first}$$</span>，其中 <span class=\"formula\">$$S_{emb}$$</span> 为整段视觉 embedding 字节数、<span class=\"formula\">$$B_{link}$$</span> 为有效互联带宽。速查表若只列“每图像 token 对应多少微秒传输”，却不校验分块对齐，就会低估这一项。工程判断是：把“分块大小 = 传输批次大小”写成硬约束，任何一侧改动都要重新查表。</p>\n<p>第二个假设是扩缩容同步。预填节点扩容后产出速率上升，若解码节点未同步扩容，KV cache 在解码侧的堆积速率由 <span class=\"formula\">$$\\Delta_{KV} = R_{prefill} - R_{consume}$$</span> 决定，只要差值为正，显存占用单调上升直至溢出。速查表里“每解码节点可承载的图像 token 上限”必须按最坏情况下的产出/消费速率差来标定，而不是按稳态均值。一个具体例子：预填侧因批调度把大 token 请求切块后并行度提高，瞬时产出翻倍，而解码侧批大小未变，此时表上的“安全 token 上限”立刻失效——需要的是按速率差留出的显存水位线，而非静态容量数字。</p>\n<p>第三个假设是优先级调度按 token 量而非到达顺序。若调度器只做 FIFO，长视觉序列请求仍会占据预填资源，解码侧 KV cache 增长重新变得突发，TPOT 波动回归。速查表应把“优先级键 = 图像 token 量分档”单列一行，并注明失效条件：当大 token 请求占比超过某一比例时，降优先级会导致其排队时间超过 SLO，此时需要的是分块并发而非单纯降级。系统代价方面，跨节点传输延迟与一致性开销是这张表的固定扣除项：token 量越大，传输占比越高，互联带宽成为主约束，单节点吞吐的优化收益被传输项稀释。因此查表的正确姿势是先定互联带宽与分块对齐，再定批大小，最后才看单节点算力余量。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-13\">十三 · 配方速查表：字段、阈值与失效边界</h3>\n<p>这张表把配方拆成可直接照抄的字段口径，核心不是“开不开启分离”，而是“分离之后拿什么量去卡边界”。三个字段必须成组使用：<code>image_tokens</code>（单请求视觉 token 数，决定 embedding 传输量与预填分块粒度）、<code>chunk_credit</code>（预填节点允许在途的分块信用，单位是分块而非请求）、<code>kv_headroom</code>（解码节点为未消费 KV 预留的显存水位）。阈值口径统一按“最坏单块”而非均值取：分块大小取 <code>ceil(image_tokens / chunk_credit)</code>，解码侧准入条件写成 <div class=\"formula\">$$\\text{admit} \\iff \\text{kv\\_headroom} \\ge \\sum_{i \\in \\text{inflight}} \\text{image\\_tokens}_i \\cdot s_{\\text{kv}}$$</div>其中 <code>s_kv</code> 是每视觉 token 折算的 KV 字节数。这条不等式是配方的硬边界：它把“预填产出速率”与“解码消费速率”的失配直接翻译成显存判断，而不是等堆积发生后再靠驱逐补救。</p>\n<table class=\"mini\"><thead><tr><th>字段</th><th>取值口径</th><th>越界后果</th></tr></thead><tbody><tr><td>image_tokens</td><td>按请求实测，不按模板均值</td><td>分块过粗，单块预填抢占解码带宽</td></tr><tr><td>chunk_credit</td><td>在途分块数上限，与互联带宽挂钩</td><td>信用放空则预填节点空转，信用过满则 embedding 排队</td></tr><tr><td>kv_headroom</td><td>解码节点预留水位，按最坏在途请求求和</td><td>低于求和值即触发准入拒绝，否则溢出</td></tr><tr><td>embedding 对齐</td><td>分块边界必须与 embedding 分段边界重合</td><td>解码节点等整段到达，互联延迟叠加进首 token</td></tr></tbody></table>\n<p>失效条件集中在两处。其一是传输与分块不对齐：若 embedding 按整图整段发送而预填按块推进，解码节点只能等最后一段落地才启动，互联延迟被完整计入首 token 延迟，分离带来的解耦收益被抵消。其二是扩缩容不同步：预填节点扩容快于解码节点，产出速率超过消费速率，KV 在解码侧单调堆积直至越过 <code>kv_headroom</code>；此时唯一有效动作是收紧 <code>chunk_credit</code> 或拒绝新请求准入，而不是提高解码批大小——后者只会加速显存见底。优先级调度若只按到达顺序排队，长视觉序列仍会抢占预填资源，TPOT 稳定性目标落空，因此排序键必须是 <code>image_tokens</code> 升序而非时间戳。</p>\n<p>系统代价要按互联带宽口径核算：embedding 传输量正比于图像 token 数，跨节点链路成为主约束，容量规划的自变量是 <code>(image_tokens, 互联带宽, 批大小)</code> 三元组，而非单节点吞吐。工程判断落在一条：当 <code>image_tokens</code> 分布的长尾足以让最坏在途求和逼近 <code>kv_headroom</code> 时，配方退化为“预填节点必须限流”的形态，此时提升单节点预填吞吐无收益，应转而压缩分块粒度并加密准入检查频率。</p>\n<h3 id=\"ap-mm-prefill-decode-sec-14\">十四 · 阈值从哪里来：先把三条链路量化成同一把尺子</h3>\n<p>分离式预填的阈值不是拍脑袋定的，而是把三条物理链路换算成同一个时间单位再比较：视觉编码算力、embedding 跨节点传输、解码侧 KV 增长速率。任何一条成为瓶颈，阈值就该落在它身上。工程上先定义三个可测量量：单请求视觉 token 数 <em>n<sub>v</sub></em>、embedding 每 token 字节数 <em>b</em>（由视觉塔输出维度与精度决定，NVFP4/FP8 下显著小于 BF16）、互联有效带宽 <em>B</em>（NVLink 5 域内与跨域 IB 要分开测）。传输时间下界即</p>\n<div class=\"formula\">$$T_{xfer} \\ge \\frac{n_v \\cdot b}{B_{eff}},\\qquad B_{eff} = B_{peak}\\cdot \\eta_{proto}$$</div>\n<p>其中 <em>η<sub>proto</sub></em> 是协议效率，必须实测而非取标称值——NIXL 的 RDMA 路径与 NCCL 集合通信在同一链路上的有效吞吐不同，前者适合点对点 embedding 搬运，后者适合分块广播。测量方法：固定 <em>n<sub>v</sub></em> 扫 batch，记录首 token 延迟中传输段占比；把 <em>B<sub>eff</sub></em> 反解出来。这个反解值才是配方里所有带宽阈值的分母。举例：一个 4 卡预填节点产出 8K 视觉 token 的 embedding，若实测 <em>B<sub>eff</sub></em> 只有标称的六成，则传输段就可能压过视觉编码本身的时间，此时阈值应改为“按 token 量切块、边传边算”，而不是等整段完成。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-15\">十五 · 分块阈值：块大小由解码侧可容忍的 KV 增长步长决定</h3>\n<p>分块不是为预填节点服务，而是为解码节点的显存曲线服务。设解码侧每 token 的 KV 占用为 <em>k</em> 字节（与层数、头数、精度相关，FP8 KV 下减半），则一个块贡献的 KV 增量为 <em>n<sub>chunk</sub></em>·<em>k</em>。要让 TPOT 波动收敛，块到达解码节点的节奏必须平滑，即相邻块到达间隔的方差要小。工程判据是：单块 KV 增量不超过解码节点单卡剩余显存的某个安全比例，且块传输时间不超过解码侧一个调度周期的量级。写成约束：</p>\n<div class=\"formula\">$$\\frac{n_{chunk}\\cdot k}{M_{free}} \\le \\rho_{safe},\\qquad \\frac{n_{chunk}\\cdot b}{B_{eff}} \\le \\tau_{sched}$$</div>\n<p>两个不等式取更紧的那个反解 <em>n<sub>chunk</sub></em>。测量方法：在解码节点上以固定采样周期记录 <code>kv_cache_used</code>，对时间序列做一阶差分，差分序列的尖峰就是块过大或到达不均的信号；同时记录 TPOT 的 p99，两者做相关性对照。具体例子：一个长视频请求产生数万视觉 token，若整段一次到达，解码侧 KV 曲线出现阶跃，正在解码的其他请求 TPOT 被拉高；切成若干块并按 token 量降优先级后，阶跃变成斜坡，p99 收敛。注意块太小会推高传输次数与一致性开销，块下界由协议固定开销决定，需实测单次传输的固定延迟。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-16\">十六 · 优先级阈值：按 token 量分级，而不是按到达顺序</h3>\n<p>失败模式里最隐蔽的一条是“只按到达顺序调度”。到达顺序与 token 量无关，长视觉序列请求照样能抢占预填资源。正确做法是给每个请求算一个 token 量分档，档位阈值来自实测的预填吞吐曲线：预填节点在 batch 内 token 总量超过某点后，单 token 边际吞吐下降、尾延迟抬升，这个拐点就是分档边界。伪代码思路：</p>\n<ul>\n<li>入队时计算 <em>n<sub>v</sub></em>，落入档位 <em>g</em> = f(<em>n<sub>v</sub></em>)；</li>\n<li>优先级 <em>p</em> = <em>p<sub>base</sub></em> − <em>g</em>·<em>w</em>，<em>w</em> 为档位权重，由实测 TPOT 敏感度标定；</li>\n<li>大 token 请求强制切块，块间让出预填资源给小请求；</li>\n<li>解码侧维护“待消费块队列”，队列深度超过阈值即回压预填节点。</li>\n</ul>\n<p>代价是吞吐：降优先级会牺牲预填节点的填充率，大请求的完成时间被拉长。工程判断是——分离式配方的目标函数不是单节点吞吐，而是解码侧 TPOT 的稳定性，因此允许预填侧吞吐损失。测量方法：构造混合负载（小图请求与大视频请求按比例注入），扫权重 <em>w</em>，画 TPOT p99 与预填吞吐的帕累托前沿，选拐点。没有实测数据就不要写死权重，把 <em>w</em> 做成可配置项并在上线前用真实流量回放标定。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-17\">十七 · 扩缩容阈值：产出速率与消费速率的比值</h3>\n<p>预填节点与解码节点扩缩容不同步，是 KV 在解码侧堆积直至溢出的直接原因。设预填产出速率为 <em>R<sub>p</sub></em>（token/s），解码消费速率为 <em>R<sub>d</sub></em>（token/s），稳态要求 <em>R<sub>p</sub></em> ≤ <em>R<sub>d</sub></em>。工程上不追求等号，而是留出安全裕度：</p>\n<div class=\"formula\">$$\\frac{R_p}{R_d} \\le \\sigma_{cap},\\qquad \\sigma_{cap} = 1 - \\frac{M_{headroom}}{M_{kv}}$$</div>\n<p><em>M<sub>headroom</sub></em> 是解码侧预留的显存余量，<em>M<sub>kv</sub></em> 是当前 KV 池容量。测量方法：在预填与解码两侧分别埋点计数 token 产出与消费，按滑动窗口算比值；比值持续超过 <em>σ<sub>cap</sub></em> 即触发预填侧限流或解码侧扩容。具体例子：视觉编码突发（一批高分辨率图同时到达）会让 <em>R<sub>p</sub></em> 短时飙升，若扩缩容只看队列长度而不看速率比，解码侧会先溢出再扩容，为时已晚。因此阈值应设在速率比上，且窗口要短于扩容生效时间——扩容本身有冷启动延迟，这个延迟必须实测并计入裕度。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-18\">十八 · 一致性开销与传输对齐的测量口径</h3>\n<p>跨节点传输不只是带宽，还有一致性开销：embedding 到达解码节点后要写入正确的 KV 位置，块边界必须与位置编码对齐，否则解码节点要么等整段到达，要么做重排。失败模式“传输未与分块对齐”正是这里出的问题。判据是：块 i 的传输完成时刻必须早于解码侧需要该块位置的时刻，即流水线不空转。测量方法：给每个块打三个时间戳——预填完成、传输发起、解码首次消费——算三段的重叠率；重叠率低说明对齐没做好，互联延迟直接叠加到首 token 延迟。代价体现在首 token 延迟上，而非稳态 TPOT，因此要单独建一个首 token 延迟的 SLO 口径，不能和 TPOT 混在一起看。工程判断：把块边界定义在视觉 token 的自然分段上（如图像 patch 分组），让传输与计算天然重叠，比事后调块大小更省事。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-19\">十九 · 没有数字时怎么测：最小可复现的标定流程</h3>\n<p>本配方涉及的多数阈值依赖具体模型、精度与互联拓扑，不能跨部署照搬。给出可复现的标定流程，替代任何编造的经验数字。第一步，单请求基线：固定 <em>n<sub>v</sub></em> 从最小到最大扫，记录视觉编码时间、embedding 传输时间、解码首 token 时间，得到三条曲线与各自的拐点。第二步，混合负载：按真实流量比例注入长短请求，扫分块大小与优先级权重，记录 TPOT p99、预填吞吐、解码显存峰值三者的关系。第三步，故障注入：人为让预填产出速率超过消费速率，观察 KV 堆积到溢出的时间，反推 <em>σ<sub>cap</sub></em> 的合理取值。第四步，把上述结果固化为配置项与告警阈值，并在每次模型或精度变更后重跑——NVFP4 与 FP8 下 <em>b</em> 与 <em>k</em> 都变，旧阈值全部失效。整个流程的产出不是一组魔法数字，而是一张“阈值—测量方法—失效信号”的对照表，让容量规划落在 token 量、互联带宽与批大小三者的可测关系上。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-20\">二十 · 阈值从哪里来：三类可测量、两条硬边界、一个对齐公式</h3>\n<p>这套配方里真正需要“定数字”的地方只有三处：分块粒度、优先级分档、以及预填/解码两侧的产出-消费配比。它们都不是拍脑袋的经验值，而是从互联带宽、显存增量速率和 TPOT 目标反解出来的。先看分块粒度：视觉 embedding 的传输量正比于图像 token 数，设单请求图像 token 数为 <span class=\"inline-math\">N<sub>v</sub></span>、每 token embedding 字节数为 <span class=\"inline-math\">b</span>、互联有效带宽为 <span class=\"inline-math\">B</span>，则整段 embedding 的传输时间为 <span class=\"inline-math\">T<sub>tx</sub> = N<sub>v</sub>·b/B</span>。若分块大小为 <span class=\"inline-math\">c</span> 个 token，解码侧第 <span class=\"inline-math\">k</span> 块可启动的条件是前 <span class=\"inline-math\">k·c</span> 个 token 的 KV 已落地，于是首 token 延迟里被互联“卡住”的那一段约为 <span class=\"inline-math\">c·b/B</span>，而不是 <span class=\"inline-math\">N<sub>v</sub>·b/B</span>。这就是分块阈值的第一条硬边界：<span class=\"inline-math\">c</span> 必须小到让 <span class=\"inline-math\">c·b/B</span> 落在首 token 预算的可接受份额内，同时又不能小到让每块的调度与一致性开销（握手、序号校验、KV 写入同步）反超传输本身。</p>\n<div class=\"formula\">$$c^{*} \\;=\\; \\arg\\min_{c}\\ \\Big[\\ \\frac{c\\,b}{B} \\;+\\; \\frac{N_v}{c}\\,\\tau_{\\text{oh}}\\ \\Big],\\qquad \\frac{c^{*}b}{B}\\ \\le\\ \\alpha\\cdot \\text{TTFT}_{\\text{budget}}$$</div>\n<p>其中 <span class=\"inline-math\">τ<sub>oh</sub></span> 是单块的一致性开销，<span class=\"inline-math\">α</span> 是首 token 预算中允许分配给传输的份额。测量方法很直接：在预填节点与解码节点之间跑一次固定 <span class=\"inline-math\">N<sub>v</sub></span> 的 embedding 传输，扫 <span class=\"inline-math\">c</span> 从“一块装下全部”到“每块几十 token”，记录端到端首 token 延迟与解码侧 KV 写入的抖动，取曲线拐点左侧一档作为生产值——拐点右侧说明开销已主导，左侧说明传输仍主导。这条曲线必须在目标互联拓扑上实测，因为 <span class=\"inline-math\">B</span> 的有效值受并发流数、消息大小与协议栈影响，纸面带宽不能直接代入。</p>\n<p>第二条硬边界是产出-消费配比。设预填节点单请求平均产出 KV 速率为 <span class=\"inline-math\">r<sub>p</sub></span>（token/s），解码节点单请求消费速率为 <span class=\"inline-math\">r<sub>d</sub></span>（受 TPOT 目标约束，<span class=\"inline-math\">r<sub>d</sub> ≈ 1/TPOT</span>），两侧并发请求数分别为 <span class=\"inline-math\">n<sub>p</sub></span>、<span class=\"inline-math\">n<sub>d</sub></span>，则解码侧 KV 净增长速率为 <span class=\"inline-math\">n<sub>p</sub>r<sub>p</sub> − n<sub>d</sub>r<sub>d</sub></span>。只要这个值为正，KV cache 就在解码侧单调堆积，直到显存溢出——这正是“扩缩容不同步”失效模式的定量形态。容量规划的判据不是“预填节点吞吐越高越好”，而是把上式钳在零附近并留出突发余量：<span class=\"inline-math\">n<sub>p</sub>r<sub>p</sub> ≤ (1−β)·n<sub>d</sub>r<sub>d</sub></span>，<span class=\"inline-math\">β</span> 是留给图像 token 突发与重试的余量系数。测量方法是给解码侧 KV 占用打点采样，画出占用随时间的斜率：斜率持续为正且不回落，说明配比已越界，此时应降预填并发或抬解码批大小，而不是继续加预填节点。</p>\n<table class=\"mini\"><thead><tr><th>观测量</th><th>测法</th><th>越界信号</th><th>对应代价</th></tr></thead><tbody><tr><td>分块传输时延 <span class=\"inline-math\">c·b/B</span></td><td>固定 <span class=\"inline-math\">N<sub>v</sub></span> 扫 <span class=\"inline-math\">c</span>，记 TTFT 与 KV 写入抖动</td><td>曲线拐点右侧</td><td>首 token 延迟被互联延迟直接叠加</td></tr><tr><td>KV 净增长斜率</td><td>解码侧 KV 占用定时采样</td><td>斜率持续为正</td><td>显存溢出，TPOT 崩溃</td></tr><tr><td>优先级命中率</td><td>按 token 量分档后统计长序列抢占次数</td><td>长序列仍抢占预填</td><td>TPOT 波动不收敛</td></tr></tbody></table>\n<p>第三处是优先级分档阈值。分档必须按图像 token 量而非到达顺序，否则长视觉序列仍会抢占预填资源，TPOT 稳定性目标落空。可操作的判据是：把 <span class=\"inline-math\">N<sub>v</sub></span> 超过“单块可容纳 token 数若干倍”的请求划入低优先级并强制切块，小请求走快车道；分档边界取在“该请求整段预填是否会挤占一个解码步的算力窗口”上，用预填节点单步耗时与解码 TPOT 目标之比来标定。还有一个常被忽略的对齐条件：视觉 embedding 传输必须与 prefill 分块同粒度对齐，否则解码节点会等整段 embedding 到齐才启动，互联延迟原封不动叠回首 token 延迟——这时前面所有分块优化都归零。验证办法是看解码侧首块 KV 的写入时刻是否早于整段传输完成时刻；若不是，说明对齐没做上，应把传输切分与预填分块绑成同一套序号。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-21\">二十一 · 阈值不是拍脑袋：三类可测边界与失效判据</h3>\n<p>这套配方真正要回答的工程问题只有一个：<strong>视觉 embedding 的到达节奏能不能被解码侧的消费节奏追上</strong>。把互联带宽记为 <span class=\"formula\">$$B$$</span>（有效单向带宽），单请求视觉 token 数记为 <span class=\"formula\">$$n_v$$</span>，每 token embedding 字节数记为 <span class=\"formula\">$$s$$</span>，则单请求传输时间下界为 <span class=\"formula\">$$t_{xfer} \\ge n_v \\cdot s / B$$</span>。判据是把它与解码节点上该请求的预填等效耗时 <span class=\"formula\">$$t_{prefill}$$</span> 比较：当 <span class=\"formula\">$$t_{xfer} &gt; t_{prefill}$$</span> 时，互联而非算力成为首 token 延迟的主项，此时唯一有效的做法是把 embedding 传输按 prefill 分块切齐、流水重叠，而不是等整段到达。测量方法很直接：在预填节点打 embedding 分块发送时间戳，在解码节点打分块接收与首个 decode step 启动时间戳，取两者差值的分位数分布，而不是均值——尾部才是 SLO 的真实敌人。</p>\n<p>第二类阈值在扩缩容耦合处。设预填节点集群的视觉 token 产出速率为 <span class=\"formula\">$$R_p$$</span>（token/s），解码节点集群的消费速率为 <span class=\"formula\">$$R_d$$</span>，则解码侧 KV cache 的堆积速率为 <span class=\"formula\">$$\\max(0, R_p - R_d) \\cdot c_{kv}$$</span>，其中 <span class=\"formula\">$$c_{kv}$$</span> 是每 token 的 KV 字节数。工程上要守的不是瞬时相等，而是<strong>堆积量在两次扩缩容决策间隔内不超过解码侧预留显存水位</strong>。测量方式：以固定间隔采样解码节点的 KV 占用与预填队列深度，画出「队列深度—占用斜率」曲线，斜率持续为正即说明产出速率已越界，此时应优先压制大 token 请求的预填优先级，而不是急着扩解码节点——扩解码节点只会把显存压力往后推。</p>\n<p>第三类阈值是优先级调度的正确性判据，也是最容易被写错的一处。若调度键取请求到达顺序，长视觉序列仍会占据预填资源，TPOT 稳定性目标直接落空。可测的替代判据是<strong>按 token 量分桶后的预填占用分布</strong>：统计单位时间内落入大 token 桶的预填 step 占比，该占比超过预设上限即判定调度失效。下表给出三类边界的观测点与代价归属，便于在容量规划时定位瓶颈。</p>\n<table class=\"mini\"><thead><tr><th>边界</th><th>观测点</th><th>系统代价归属</th></tr></thead><tbody><tr><td>传输—预填失配</td><td>分块到达与 decode 启动的时间差尾部</td><td>首 token 延迟，互联带宽</td></tr><tr><td>产出—消费失衡</td><td>KV 占用斜率、预填队列深度</td><td>解码侧显存，溢出风险</td></tr><tr><td>调度键错误</td><td>大 token 桶的预填 step 占比</td><td>TPOT 波动，算力与显存带宽抢占</td></tr></tbody></table>\n<p>这三类阈值共同划出配方的适用边界：token 量、互联带宽与批大小必须联合规划，单节点吞吐再高也不能替代跨节点节奏对齐。当图像 token 量增长使 <span class=\"formula\">$$t_{xfer}$$</span> 逼近甚至超过 <span class=\"formula\">$$t_{prefill}$$</span>，或扩缩容决策周期短于 KV 堆积到水位的时间，这套分离式结构就从收益转为负担，应退回同节点预填或改用更细粒度的分块流水。</p>\n<h3 id=\"ap-mm-prefill-decode-sec-22\">二十二 · 坑一：embedding 传输与预填分块不对齐</h3>\n<p>这是该配方最先暴露、也最容易被误判为“互联慢”的失败模式。视觉编码器产出的是整幅图像的 embedding 张量，而 LLM prefill 侧是按块消费的：若预填节点把整段 embedding 编完才发起一次传输，解码节点就必须等整段到达才能启动第一个 decode step，互联延迟被完整地叠加到首 token 延迟上，而不是被流水线掩盖。工程上要检查的不是带宽峰值，而是<strong>传输粒度是否等于分块粒度</strong>。</p>\n<p>正确形态是让 embedding 的传输单元与 prefill 的 chunk 边界一一对应，伪代码思路如下：</p>\n<div class=\"formula\">$$\n\\text{chunk}_i \\rightarrow \\text{embed}_i \\xrightarrow{\\text{async send}} \\text{decode node} \\quad\\text{s.t.}\\quad \\text{send}(\\text{embed}_i)\\ \\text{与}\\ \\text{prefill}(\\text{chunk}_{i+1})\\ \\text{重叠}\n$$</div>\n<p>代价体现在首 token 延迟上：设单块 embedding 传输耗时为 <em>t<sub>tx</sub></em>、单块 prefill 耗时为 <em>t<sub>pf</sub></em>，对齐良好时首 token 等待约为 <em>t<sub>tx</sub></em>+<em>t<sub>pf</sub></em>（首块），不对齐时退化为 Σ<em>t<sub>tx</sub></em>+Σ<em>t<sub>pf</sub></em> 的串行叠加。检查顺序上，先在预填节点侧打印每个 chunk 的 embedding 发送时间戳与 chunk 完成时间戳，两者应几乎同时；若发送时间戳集中在请求末尾，说明分块边界没有下传到视觉侧。具体例子：一张被切成 4 块的图像，若视觉塔按整图出 embedding，解码节点在前 3 块 prefill 期间完全空转，互联带宽再高也救不回首 token。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-23\">二十三 · 坑二：扩缩容不同步导致 KV cache 堆积</h3>\n<p>预填节点与解码节点的负载特征解耦，正是这个配方要独立扩缩容的理由，但解耦也意味着两边的扩容决策互不知情。预填侧按视觉 token 吞吐扩容、解码侧按并发序列数扩容，一旦预填产出速率超过解码消费速率，视觉 embedding 对应的 KV 就在解码侧单调堆积，直到显存溢出。这个坑的隐蔽性在于：预填节点指标一切正常（吞吐高、队列短），故障却出现在解码节点。</p>\n<p>需要建立一条跨节点的速率守恒检查。设预填侧单位时间产出的视觉 token 数为 <em>R<sub>pf</sub></em>，解码侧单位时间消化并释放的 token 数为 <em>R<sub>dc</sub></em>，稳态要求：</p>\n<div class=\"formula\">$$\nR_{pf} \\le R_{dc}, \\qquad \\Delta Q = (R_{pf}-R_{dc})\\cdot \\Delta t\n$$</div>\n<p>其中 Δ<em>Q</em> 就是解码侧 KV 的净增量，直接换算成显存占用。检查顺序：把 <em>R<sub>pf</sub></em> 与 <em>R<sub>dc</sub></em> 做成同一条时间序列上的两条曲线，任何持续为正的差值都是显存泄漏式堆积的前兆；再看解码节点的 KV 占用斜率是否与 Δ<em>Q</em> 吻合。代价是显存，而非算力——解码节点的算力可能仍有余量，但 KV 池已被未消费的视觉序列占满，新请求被拒绝。具体例子：预填节点因小请求优先策略而快速吐出大量短序列 embedding，解码侧却因长序列占用 batch 槽位而消费缓慢，两条曲线剪刀差扩大，最先崩的是解码侧显存而不是预填吞吐。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-24\">二十四 · 坑三：优先级只看到达顺序，不看 token 量</h3>\n<p>配方要求按图像 token 量做预填分块与优先级调度：大 token 请求切块并降优先级，小请求优先。若调度器只实现了 FIFO 或按到达时间排序，长视觉序列请求仍会在队列头部一次性占用预填资源，把后面所有小请求压住，解码侧看到的 KV 增长节奏重新变得不可预测，TPOT 波动收敛的目标落空。这个坑的判据很直接：<strong>优先级键里是否含 token 量这一维</strong>。</p>\n<p>检查方式是对调度决策做离线回放：取一段真实请求 trace，分别用“到达顺序”和“token 量加权”两种优先级跑一遍，比较解码侧 TPOT 的方差。若两者方差接近，说明 token 量维度没有真正生效，可能被实现成了仅对超阈值请求做特殊处理的旁路逻辑。伪代码思路：</p>\n<div class=\"formula\">$$\n\\text{prio}(r) = f(\\text{arrival}(r),\\ \\text{tokens}(r)),\\quad \\frac{\\partial\\,\\text{prio}}{\\partial\\,\\text{tokens}} &lt; 0\n$$</div>\n<p>代价是吞吐与延迟的再分配：小请求优先会降低大请求的预填吞吐利用率，预填节点的总算力吞吐可能下降，但换来解码侧 TPOT 的稳定性。具体例子：一个含大量视频帧的长请求若未被降优先级并切块，它会在预填节点上连续占用数个 chunk 周期，期间解码节点收不到新 embedding，已驻留序列的 TPOT 因缺少新 batch 补充而抖动。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-25\">二十五 · 检查顺序：从传输对齐到速率守恒再到优先级</h3>\n<p>三类坑的排查不能并行乱查，应按因果链排序，因为后一类坑的症状会被前一类掩盖。推荐顺序：</p>\n<ul>\n<li><strong>第一步，传输对齐</strong>：核对 embedding 发送时间戳与 chunk 完成时间戳的偏差，确认分块边界已下传到视觉编码侧。这一步不通过，首 token 延迟的异常无法归因到其他环节。</li>\n<li><strong>第二步，速率守恒</strong>：在传输对齐的前提下比较 <em>R<sub>pf</sub></em> 与 <em>R<sub>dc</sub></em> 曲线，确认解码侧 KV 斜率与 Δ<em>Q</em> 一致。传输未对齐时 <em>R<sub>pf</sub></em> 的测量本身失真，此步无意义。</li>\n<li><strong>第三步，优先级生效性</strong>：前两步稳定后，再用 trace 回放验证 token 量维度是否真正进入优先级键，观察 TPOT 方差是否收敛。</li>\n<li><strong>第四步，容量规划复核</strong>：把 token 量、互联带宽、批大小三者的当前取值代入容量模型，确认扩缩容阈值与实测速率匹配。</li>\n</ul>\n<p>这个顺序的代价是排查时间：串行排查意味着单次故障定位周期变长，但换来的是归因唯一性——每一步只允许一个变量处于可疑状态。工程上应把这三步做成上线前的固定检查项，而不是故障后的临时手段。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-26\">二十六 · 回滚方案：按影响面分层退避</h3>\n<p>回滚不是一键切回单节点，而是按影响面分层退避，因为三类坑的爆炸半径不同。传输不对齐主要伤首 token 延迟，速率失衡伤解码侧显存，优先级失效伤 TPOT 稳定性，三者的回滚动作应分开设计。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>故障类别</th><th>首要影响</th><th>回滚动作</th><th>回滚代价</th></tr>\n</thead>\n<tbody>\n<tr><td>embedding 传输未对齐分块</td><td>首 token 延迟</td><td>退回整段传输 + 解码侧等待，或临时增大 chunk 粒度减少传输次数</td><td>首 token 延迟仍偏高，但消除串行叠加</td></tr>\n<tr><td>扩缩容不同步、KV 堆积</td><td>解码侧显存</td><td>冻结预填侧扩容，或将部分预填节点转为解码节点消费积压</td><td>预填吞吐短时下降，积压消化期内新请求排队</td></tr>\n<tr><td>优先级未按 token 量</td><td>TPOT 稳定性</td><td>临时对超阈值长请求做强制切块 + 限流，绕过优先级键缺陷</td><td>长请求吞吐下降，短请求延迟改善</td></tr>\n</tbody>\n</table>\n<p>回滚的判据应绑定可观测指标而非主观感受：首 token 延迟超过容量规划设定的上限、解码侧 KV 占用斜率持续为正超过一个观测窗口、TPOT 方差回放到不可接受区间，三者任一触发即执行对应层的回滚。回滚后必须保留原配置的快照与触发时刻的 trace，否则下一次故障仍会从零开始定位。具体例子：解码侧 KV 占用在十分钟窗口内单调上升且与 Δ<em>Q</em> 估算吻合，应先冻结预填扩容而非直接重启解码节点——重启会丢掉积压序列的上下文，代价远大于冻结扩容。</p>\n<p>最后落在工程判断上：这套配方的稳定性不取决于单点性能，而取决于三个耦合量的守恒关系——传输粒度与分块粒度对齐、产出速率与消费速率匹配、优先级键与 token 量挂钩。任何一项失守，另外两项的调优都会被症状掩盖；因此检查清单的执行顺序本身，就是这套配方可运维性的核心资产。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-27\">二十七 · 失效边界：三类典型故障的触发链与检查顺序</h3>\n<p>这套配方的稳定性不来自任何单点优化，而来自“预填产出节奏 ≈ 解码消费节奏”这一守恒关系。一旦该关系被打破，故障不会以报错形式出现，而是以延迟劣化或显存溢出的形式在解码侧显形。最典型的失效链是 embedding 传输与预填分块未对齐：预填节点按块产出视觉 embedding，但解码节点被实现为“整段 embedding 到齐才启动 decode”，于是跨节点传输的尾块延迟直接叠加到首 token 延迟上。设单请求图像 token 数为 <span class=\"inline-math\">T</span>，分块大小为 <span class=\"inline-math\">b</span>，互联有效带宽为 <span class=\"inline-math\">B</span>，每 token embedding 字节数为 <span class=\"inline-math\">s</span>，则首 token 额外等待可写成</p>\n<div class=\"formula\">$$L_{\\text{first}} \\approx \\frac{T \\cdot s}{B} + \\left\\lceil \\frac{T}{b} \\right\\rceil \\cdot \\tau_{\\text{sync}}$$</div>\n<p>其中 <span class=\"inline-math\">τ_sync</span> 是每块的同步与一致性开销。工程含义很直接：分块越小，流水重叠越好，但同步次数上升；分块越大，同步开销摊薄，但首 token 被整段传输拖住。检查顺序应从“解码侧是否按块消费”入手，再看预填侧块边界是否与传输消息边界一致，最后核对 <span class=\"inline-math\">b</span> 与 <span class=\"inline-math\">B</span> 的匹配度——若单块传输时间远小于解码单步时间，说明分块过细、同步开销成为主项。</p>\n<p>第二类故障是扩缩容不同步导致的 KV cache 堆积。预填节点与解码节点独立扩缩容本是该配方的卖点，但也意味着两侧的容量决策彼此不可见。当预填侧因突发大图请求扩容、解码侧未同步扩容时，预填产出速率超过解码消费速率，KV cache 在解码侧单调增长直至显存溢出。设解码节点单卡可用于 KV 的显存为 <span class=\"inline-math\">\\(M_{\\text{kv}}\\)</span>，单 token KV 字节数为 <span class=\"inline-math\">k</span>，在途请求数为 <span class=\"inline-math\">N</span>，平均上下文长度为 <span class=\"inline-math\">C</span>，则安全条件为 <span class=\"inline-math\">\\(N·C·k &lt; M_{\\text{kv}}\\)</span>；而堆积速率为预填吞吐与解码吞吐之差。检查清单应把“预填队列深度 / 解码消费速率”作为常驻指标，并在扩容动作上绑定同一份 token 预算，而非各自按 GPU 数扩。代价是：为吸收这种不同步，解码侧必须预留显存余量，直接压缩了可承载的并发批大小，等效于牺牲吞吐换稳定。</p>\n<p>第三类故障是优先级调度退化。若调度器只按请求到达顺序排队，长视觉序列请求仍会占据预填资源，把本应受保护的小请求推到队尾，TPOT 稳定性目标落空。正确做法是以图像 token 量为排序键：大 token 请求切块并降优先级，小请求优先进入预填。检查顺序为——先验证调度键确实是 token 量而非时间戳，再验证切块后的块是否可被抢占或插入，最后验证降优先级请求不会因长期饥饿而拖高尾延迟。这里存在明确的系统代价：切块与抢占引入额外的调度开销与 embedding 缓冲，预填节点的有效算力利用率下降，单节点吞吐低于不切块的朴素实现。这正是该配方的边界——它用单节点吞吐换取解码侧 TPOT 的可预测性，容量规划必须落在 token 量、互联带宽与批大小三者的联合约束上，而不是追求任一节点的峰值吞吐。</p>\n<table class=\"mini\"><thead><tr><th>故障</th><th>可观测信号</th><th>检查顺序</th><th>回滚动作</th></tr></thead><tbody><tr><td>embedding 未按块消费</td><td>首 token 延迟随图像 token 线性上升</td><td>解码消费粒度 → 块边界对齐 → 分块大小</td><td>退回整段传输并临时增大批间隔</td></tr><tr><td>扩缩容不同步</td><td>解码侧 KV 占用单调爬升</td><td>队列深度比 → 显存余量 → token 预算</td><td>冻结预填扩容，按解码消费速率限流</td></tr><tr><td>优先级退化</td><td>TPOT 方差随长请求比例上升</td><td>调度键 → 可抢占性 → 饥饿检测</td><td>恢复按 token 量排序并启用切块</td></tr></tbody></table>\n<h3 id=\"ap-mm-prefill-decode-sec-28\">二十八 · 上游依赖：视觉塔与预处理链路决定传输量基线</h3>\n<p>本配方在全书中的位置，首先由它的上游决定：它不生产视觉 token，只搬运与调度视觉 token。视觉编码器术语表定义了 patch 划分与 token 序列长度如何从分辨率与 patch size 推导，图像视频预处理工具链决定了实际送入视觉塔的帧数与裁切策略，视觉token压缩工具与视觉token压缩术语则决定了压缩后每个请求还剩多少 token。这三者叠加，构成预填节点向解码节点传输的 embedding 字节数基线。配方本身无法把这个基线降下来，只能在其之上做分块与优先级。</p>\n<p>传输量可写成对请求集合的求和：</p>\n<div class=\"formula\">$$B_{\\text{xfer}} = \\sum_{r \\in \\mathcal{R}} n_r \\cdot d \\cdot b$$</div>\n<p>其中 $n_r$ 是请求 $r$ 经压缩后的视觉 token 数，$d$ 是隐藏维度，$b$ 是每元素字节数（由多模态量化配方决定，例如 FP8 与 NVFP4 的选择直接改变 $b$）。互联带宽 $W$ 给定时，单请求传输下界为 $B_{\\text{xfer},r}/W$，这一项在首 token 延迟里无法被预填分块掩盖，因为解码侧必须先拿到对应块的 embedding 才能开始该块的跨模态注意力。因此上游压缩比与量化位宽的任何变化，都会以线性方式改写本配方的容量规划输入，而不是仅仅影响预填节点的算力占用。</p>\n<p>具体例子：同一张高分辨率图像，若预处理链路保留更多切片、压缩工具保留更高 token 保留率，则 $n_r$ 上升，预填节点算力尚可吸收，但跨节点传输时间按比例上升，解码侧等待窗口变长。工程判断是：调压缩率时必须同时看预填节点利用率与互联利用率两条曲线，只盯前者会把瓶颈推到链路上。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-29\">二十九 · 上游依赖：多模态批调度与框架能力约束分块粒度</h3>\n<p>第二个上游是多模态批调度术语所定义的请求组织方式，以及多模态推理框架提供的传输原语。本配方的“按图像 token 量分块”不是调度器凭空决定的，它要求框架能把一个请求的视觉 embedding 切成若干段、每段带独立序号、可乱序到达并在解码侧按序拼接。若框架只支持整请求粒度的 KV 传输或 embedding 传输，分块就退化为整段等待，失败模式“解码节点等待整段 embedding 到达才启动”随即出现。</p>\n<p>分块粒度存在一个下界：块太小则每块都携带固定的传输与一致性开销（握手、序号校验、接收缓冲管理），链路有效带宽被开销吞掉；块太大则首块到达时间被拉长，首 token 延迟变差。可写成有效传输时间的近似：</p>\n<div class=\"formula\">$$T_{\\text{chunk}} \\approx \\frac{B_{\\text{chunk}}}{W} + \\tau_{\\text{oh}}, \\quad \\text{s.t. } B_{\\text{chunk}} \\le B_{\\text{buf}}$$</div>\n<p>$\\tau_{\\text{oh}}$ 是每块的固定开销，$B_{\\text{buf}}$ 是解码侧为该请求预留的接收缓冲上限。多模态批饥饿条目讨论的是解码节点无事可做的空转，而本配方从另一侧回应它：分块让预填产出以细粒度、可预测的节奏进入解码侧，避免“要么全无、要么突发”的供给形态。视觉塔显存溢出条目关注预填侧视觉塔的激活峰值，本配方则通过把视觉编码固定在预填节点、并按 token 量切块，使预填侧峰值可被分块摊平——两者是同一约束的两端。</p>\n<p>代价落在预填节点的调度复杂度上：分块意味着一个请求在预填节点上被多次调度，块间可能插入其他小请求，预填节点的批内碎片与状态管理开销上升，单节点吞吐低于整请求批处理。这是为解码侧 TPOT 稳定性支付的确定性成本。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-30\">三十 · 下游影响：解码侧 KV cache 增长模型与 TPOT 收敛</h3>\n<p>本配方对下游最直接的作用，是把解码侧 KV cache 的增长从“突发阶跃”改写为“可预测斜坡”。解码节点不再执行视觉编码与长序列 prefill，其算力与显存带宽只服务解码 token 生成；当预填节点按 token 量分块、按块交付时，解码侧每个请求的 KV 占用按块阶梯上升，任意时刻的在途增长量有上界。</p>\n<p>设解码节点有 $N_d$ 个请求在跑，每请求每步新增 KV 字节为 $k$，块交付带来的额外占用为 $B_{\\text{chunk}}$，则一个调度周期内的显存增长可约束为：</p>\n<div class=\"formula\">$$\\Delta M_{\\text{KV}} \\le N_d \\cdot k \\cdot s + \\sum_{c \\in \\mathcal{C}} B_{\\text{chunk},c}$$</div>\n<p>其中 $s$ 是周期内解码步数，$\\mathcal{C}$ 是该周期内到达的块集合。只要预填节点的产出速率被优先级调度限制在解码侧消费速率之下，$\\Delta M_{\\text{KV}}$ 就不会出现无法回收的堆积，失败模式“KV cache 在解码侧堆积直至显存溢出”被结构性排除。TPOT 波动的收敛机制也在此：解码节点不被突发长视觉序列抢占算力与显存带宽，步间时间方差下降，SLO 里的 TPOT 分位数才有意义。</p>\n<p>具体例子：一批混合请求中，少量超长视频请求与大量短图文请求共存。若按到达顺序调度，长视频请求整段预填会周期性打断解码节奏；按 token 量切块并把大块降优先级后，短请求先完成预填并进入解码，长请求的块在空隙中交付，解码侧每步新增 KV 量平稳，TPOT 尾部不再被拉长。下游的多模态上线前清单若要验收该配方，应直接测“长请求注入时的 TPOT 分位数漂移”，而不是只测平均吞吐。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-31\">三十一 · 下游影响：容量规划与扩缩容同步性</h3>\n<p>本配方把系统拆成两个可独立扩缩容的资源池，这既是收益也是下游负担。预填节点按视觉 token 吞吐扩容，解码节点按并发请求数与 KV 容量扩容，两者速率不匹配时，配方退化为一个带缓冲的队列系统。设预填产出速率为 $\\lambda_p$（token/s），解码消费速率为 $\\lambda_d$，则解码侧 KV 积压的稳态条件为：</p>\n<div class=\"formula\">$$\\lambda_p &gt; \\lambda_d \\;\\Rightarrow\\; \\text{积压单调增长}$$</div>\n<p>工程上必须让扩缩容策略同时观察两侧：只按预填节点队列长度扩容会加剧积压，只按解码侧 TPOT 扩容会在预填侧形成长尾。容量规划的自变量是 token 量、互联带宽与批大小三者的联合约束——互联带宽决定单块交付时间，批大小决定解码侧同时可接纳的块数，token 量决定总传输量。这与“单纯追求单节点吞吐”的目标函数不同：单节点吞吐最优往往意味着更大的批与更大的块，而本配方要求块大小服从链路与解码侧缓冲，牺牲局部吞吐换全局稳定性。</p>\n<p>代价是跨节点传输延迟与一致性开销成为固定支出：每个块都要付出链路时间与序号/完整性校验成本，且两侧状态必须对齐（哪些块已交付、哪些 KV 已写入）。多模态推理框架若不能把这一致性状态纳入调度决策，扩缩容就会出现“预填已扩、解码未扩”的窗口期，积压在此期间发生。因此本配方在全书中的位置是“连接件”：它把上游的 token 经济性、下游的 KV 经济性与链路的带宽经济性绑成一个联合优化问题。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-32\">三十二 · 在全书中的位置：与量化、互联、SLO 三条主线的交点</h3>\n<p>放到全书结构里看，本配方是少数同时触及三条主线的条目。与多模态量化配方的交点在于 $b$：embedding 以何种精度跨节点传输，直接改变 $B_{\\text{xfer}}$，量化位宽减半即传输时间减半，但解码侧反量化或直接以低精度参与注意力的数值路径必须与预填侧一致，否则一致性开销转化为精度校验成本。与互联主线（NVLink 5、NCCL、NIXL）的交点在于 $W$ 与传输原语：embedding 传输走的是点对点搬运而非集合通信，NIXL 这类传输层的能力决定分块能否异步、能否与计算重叠。与 SLO 与容量规划主线的交点在于 TPOT 分位数：本配方存在的理由就是把 TPOT 方差压下来，因此它的验收指标天然属于 SLO 体系而非吞吐体系。</p>\n<p>它与其他多模态条目的分工也由此清晰：视觉token压缩工具与量化配方负责把 $n_r$ 与 $b$ 做小；视觉塔显存溢出与多模态批饥饿负责单节点内的资源形态；本配方负责跨节点的交付节奏与一致性。视频抽帧与批配方决定帧数进而决定 $n_r$ 的上游输入，跨模态注意力术语则解释了为什么解码侧必须等 embedding 到位才能推进该块——这解释了传输延迟为何无法被计算掩盖。多模态上线前清单应把本配方的三个失败模式各自映射为一项检查：分块与传输对齐、两侧扩缩容同步、优先级按 token 量而非到达顺序。</p>\n<p>最后一个工程判断落在分块边界的选择上：块边界应与解码侧 KV 页分配粒度对齐，使每块到达即可一次性写入连续页、不产生跨页拼接；同时块大小应使 $B_{\\text{chunk}}/W$ 显著小于一个解码步的典型耗时，从而让传输被解码计算重叠掩盖，而不是叠加到首 token 延迟上。这一条同时约束了互联带宽下限、页大小上限与优先级调度的最小时间片，是本配方从“能跑”到“稳跑”的分界线。</p>\n\n<h3 id=\"ap-mm-prefill-decode-sec-33\">三十三 · 配方边界：互联带宽、分块对齐与扩缩容耦合</h3>\n<p>该配方的收益来自解耦，代价也来自解耦：视觉 embedding 必须跨节点搬运，传输量正比于图像 token 数，互联带宽因此成为首要约束。设单请求图像 token 数为 <span class=\"formula\">$$T_v$$</span>、embedding 每 token 字节数为 <span class=\"formula\">$$b$$</span>、有效互联带宽为 <span class=\"formula\">$$B$$</span>，则单请求传输下界为 <span class=\"formula\">$$t_{xfer} \\ge T_v \\cdot b / B$$</span>。当解码侧并发请求的图像 token 总量逼近 <span class=\"formula\">$$B$$</span> 的可用份额时，传输就从“可隐藏”变为“首 token 关键路径”。失效条件是分块与传输未对齐：若解码节点必须等整段 embedding 到达才启动，互联延迟直接叠加到 TTFT，分离式预填的收益被抵消。工程上应让每个 prefill 分块产出即触发一次传输与一次解码侧挂载，把 <span class=\"formula\">$$t_{xfer}$$</span> 与分块计算重叠，而非串行等待。</p>\n<p>第二个失效面在扩缩容耦合。预填节点与解码节点独立扩缩容是卖点，但两者速率不匹配时，预填产出超过解码消费，KV cache 在解码侧单调堆积直至显存溢出。容量规划应以 token 吞吐而非请求数为单位：解码侧可容纳的 KV 增长速率须不低于预填侧 embedding 产出速率，否则必须回压预填队列或触发分块降级。这解释了为何该配方不能单纯追求单节点吞吐——单节点峰值吞吐越高，越容易在解码侧制造突发堆积。</p>\n<p>第三是调度判据的边界。优先级若只按到达顺序，长视觉序列仍可抢占预填资源，TPOT 稳定性目标落空；必须按图像 token 量切块并对大 token 请求降优先级。下表给出三类边界条件下的主导代价：</p>\n<table class=\"mini\"><thead><tr><th>边界条件</th><th>主导代价</th><th>观测信号</th></tr></thead><tbody><tr><td>互联带宽饱和</td><td>TTFT 抬升</td><td>传输等待占首 token 路径比例上升</td></tr><tr><td>扩缩容不同步</td><td>解码侧显存溢出</td><td>KV cache 占用单调爬升不回撤</td></tr><tr><td>调度按到达序</td><td>TPOT 抖动</td><td>长序列请求后 TPOT 方差放大</td></tr></tbody></table>\n<p>在全书位置上，该配方上游依赖 tcgen05/TMEM 与 NVFP4/FP8 决定的视觉编码与 prefill 算力密度，以及 NVLink 5/NCCL/NIXL 提供的跨节点搬运能力；下游影响 KV cache 管理与连续批处理的参数选择——解码侧 KV 增长可预测后，批大小与抢占阈值才能按稳态而非峰值配置。它与分离式预填/解码、批调度条目共享同一批机制，但本配方独有之处在于把“图像 token 量”作为分块、优先级与容量规划的统一计量单位；一旦这个单位被请求数替代，上述三条边界会同时失效。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-mm-prefill-decode\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>仓库</td><td>将视觉编码与LLM prefill放在预填节点、解码放解码节点，视觉embedding经高速互联传输</td></tr><tr><td>入口</td><td>按图像token量做预填分块与优先级调度，使解码侧KV cache增长可预测并稳定TPOT。</td></tr><tr><td>依赖</td><td>见正文</td></tr><tr><td>最小复现</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-mm-prefill-decode · 共 5 个片段</p>\n"},{"id":"ap-visual-oom-failure","title":"视觉塔显存溢出","summary":"高分辨率图像或长视频使视觉token序列暴涨，视觉塔激活与中间attention矩阵瞬时占满显存；表现为编码阶段OOM或批吞吐骤降，需动态分辨率上限、分块编码与token压缩前置。","kind":"失败模式","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-1\">一 · 条目边界：什么算视觉塔显存溢出</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-2\">二 · 分类维度一：按失败形态分直接 OOM 与吞吐塌陷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-3\">三 · 分类维度二：按 token 数增长来源分图像与视频</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-4\">四 · 分类维度三：按峰值构成分激活主导与中间矩阵主导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-5\">五 · 与批调度、预处理、量化的概念切分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-6\">六 · 定义收敛：三条判据与一个反例</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-7\">七 · 边界条件：编码侧峰值与解码侧占用的分界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-8\">八 · 速查表的字段口径：把&quot;像素预算—token 数—激活峰值&quot;钉成一条链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-9\">九 · 阈值分层：硬阈值、软阈值与并发叠加阈值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-10\">十 · 分块编码的字段：块数、块内 token、块间重叠</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-11\">十一 · 监控口径：两条曲线必须分开，字段不可合并</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-12\">十二 · 速查表的使用顺序与失效判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-13\">十三 · 速查表：视觉塔显存预算的字段、阈值与失效口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-14\">十四 · 像素预算：把分辨率上限写成可执行的字节约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-15\">十五 · 并发叠加系数：静态上限为什么会失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-16\">十六 · 分块编码的块尺寸与重叠带测量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-17\">十七 · token 压缩前置的收益兑现条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-18\">十八 · 两条曲线的分离监控与阈值设定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-19\">十九 · 阈值怎么定：从像素预算到并发叠加的工程标尺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-20\">二十 · 视觉塔峰值显存的阈值判定与实测方法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-21\">二十一 · 三类高频踩坑的机理定位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-22\">二十二 · 检查顺序：从曲线到根因的固定路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-23\">二十三 · 动态上限与分块编码的落地细节</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-24\">二十四 · 压缩前置与监控口径的统一</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-25\">二十五 · 回滚方案与变更边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-26\">二十六 · 编码阶段的显存盲区：三条失效路径与回滚顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-27\">二十七 · 上游依赖：分辨率预算与预处理链决定视觉塔的输入形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-28\">二十八 · 下游影响：批调度、分离式预填与 KV 预算被编码峰值反向约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-29\">二十九 · 在全书中的位置：编码阶段失败模式与解码阶段失败模式的分界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-30\">三十 · 跨条目契约：监控、容量与配方三处接口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-31\">三十一 · 工程判断：先解编码峰值，再谈解码优化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-visual-oom-failure-sec-32\">三十二 · 边界条件：视觉塔溢出条目与上下游条目的耦合面</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-visual-oom-failure\"><svg style=\"max-width:535px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 535.4 357\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"453.4\" height=\"83.0\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"53.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"57.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：视觉塔显存溢出</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">高分辨率图像或长视频使视觉token序列暴涨，视觉塔激活与中间</text><text x=\"75.0\" y=\"78.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">attentio…</text><line x1=\"82.0\" y1=\"97.0\" x2=\"82.0\" y2=\"114.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 113.0 L 86.5 113.0 L 82.0 121.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"121.0\" width=\"453.4\" height=\"83.0\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"162.6\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"166.8\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"148.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><text x=\"75.0\" y=\"171.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">表现为编码阶段OOM或批吞吐骤降，需动态分辨率上限、分块编码与</text><text x=\"75.0\" y=\"187.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">token压缩前…</text><line x1=\"82.0\" y1=\"206.1\" x2=\"82.0\" y2=\"223.1\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 222.1 L 86.5 222.1 L 82.0 230.1 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"230.1\" width=\"453.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"252.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"256.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"257.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"276.9\" x2=\"82.0\" y2=\"293.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 292.9 L 86.5 292.9 L 82.0 300.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"300.9\" width=\"453.4\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"323.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"327.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"328.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-visual-oom-failure-sec-1\">一 · 条目边界：什么算视觉塔显存溢出</h3>\n<p>视觉塔显存溢出（visual tower OOM）是一个发生在编码阶段的失败模式：高分辨率图像或长视频把视觉 token 序列推高，视觉塔的激活张量与中间 attention 矩阵在瞬时占满显存，导致单请求峰值超出卡容量而直接报错，或在接近上限时迫使调度器缩批、吞吐骤降。它属于推理侧的显存失败，不是精度失败、不是通信失败，也不是调度饥饿——后者的特征是队列空转而非显存打满。判定的关键判据有两条：一是失败点落在视觉编码器前向内部（patch embed、窗口划分、attention、MLP 激活），二是显存峰值随输入像素预算与批内并发数变化，而不随解码长度变化。</p>\n<p>与相邻概念的第一道分界是 LLM 侧 KV cache 溢出。KV 溢出发生在解码阶段，占用随上下文长度与并发序列数线性增长，回收靠 PagedAttention 式的块管理与抢占；视觉塔溢出发生在编码阶段，占用随 token 数的平方项膨胀，回收只能靠缩短序列或切块。工程上这意味着两条独立的监控曲线：视觉塔激活峰值与解码侧 KV 占用必须分开采集，否则 OOM 出现在编码阶段却被误判为解码侧不足，扩容方向会完全走错——加 KV 块预算对视觉塔峰值毫无帮助。</p>\n<p>第二道分界是视觉 token 压缩。压缩是缓解手段，不是失败模式本身；把压缩放在视觉塔之后而非前置，压缩前的中间 attention 矩阵已经占满显存，收益无法兑现。因此本条目讨论的是“峰值发生在压缩之前”的那类溢出，与“压缩率不够导致 LLM 侧上下文过长”是两回事。</p>\n<div class=\"formula\">$$ M_{\\text{peak}} \\approx M_{\\text{weight}} + \\alpha \\cdot B \\cdot N^2 \\cdot d_{\\text{head}} \\cdot L + \\beta \\cdot B \\cdot N \\cdot d $$</div>\n<p>其中 $N$ 为视觉 token 数，$B$ 为批内并发编码的请求数，$L$ 为层数，$\\alpha,\\beta$ 为与实现相关的常数因子（是否物化完整 attention 矩阵、是否使用分块 softmax）。平方项是条目成立的物理基础：$N$ 翻倍，attention 项约四倍。举例：一张切块后 token 数为数千量级的图，单请求尚可容纳；同一批内并发若干张，$\\alpha B N^2$ 项叠加即击穿上限——这正是“按请求静态设定分辨率上限”失效的原因。</p>\n\n<h3 id=\"ap-visual-oom-failure-sec-2\">二 · 分类维度一：按失败形态分直接 OOM 与吞吐塌陷</h3>\n<p>同一根因有两种可观测形态。直接 OOM 是硬失败：单请求峰值显存超过卡容量，前向在某一层抛出分配失败，请求被丢弃或重试。吞吐塌陷是软失败：峰值逼近上限但未越界，调度器为安全起见缩小批尺寸或串行化编码，编码阶段的有效并发下降，端到端吞吐下滑而错误率不升。两者在监控上的区别是：前者看分配失败计数与请求错误率，后者看编码阶段批尺寸的时间序列与每 token 编码耗时。</p>\n<p>分类的工程意义在于处置路径不同。硬失败必须降低单请求峰值，手段是像素预算上限与切块；软失败优先调整批内并发与编码调度，因为单请求本身能过。把软失败误当硬失败去砍分辨率，会白白损失精度；把硬失败当软失败去缩批，则永远无法让该请求通过。</p>\n<ul>\n<li>硬失败信号：编码阶段分配失败、请求级错误、重试风暴。</li>\n<li>软失败信号：编码批尺寸被动下降、编码阶段 SM 占用率与 HBM 带宽利用率同步走低、端到端 P99 抬升。</li>\n<li>共同信号：视觉塔激活峰值曲线出现尖峰，且尖峰时刻与图像/视频请求到达时刻对齐。</li>\n</ul>\n<p>代价侧写：软失败下，缩批直接换算为吞吐损失——编码阶段本可并行的请求被串行化，单位时间完成的图像数下降，而解码侧可能仍然空闲，形成前后段失衡。这类失衡在多模态分离式预填部署中尤其昂贵，因为编码资源的闲置无法被解码任务填补。</p>\n\n<h3 id=\"ap-visual-oom-failure-sec-3\">三 · 分类维度二：按 token 数增长来源分图像与视频</h3>\n<p>图像侧的增长来自分辨率与切块策略：像素预算提高使切块数线性上升，token 数随之线性上升，attention 项平方膨胀。视频侧的增长来自帧数与每帧分辨率两个乘子，时间维再乘一层；长视频的 token 序列可达图像的若干倍，且帧间注意力若被物化，峰值进一步放大。分类意义在于：图像侧的上限主要靠动态分辨率上限约束，视频侧的上限必须同时约束帧数与单帧像素，只压一个维度不足以控制峰值。</p>\n<p>一个具体机制差异：图像切块编码通常各块独立前向，块间无注意力，峰值由单块 token 数与批内块并发决定；视频若采用时空联合注意力，峰值由整段序列长度决定，切块只能沿时间轴做，切分粒度受时序语义约束。因此视频侧的显存治理更依赖前置的 token 压缩与帧采样策略，而非单纯切块。</p>\n<div class=\"formula\">$$ N_{\\text{video}} \\approx F \\cdot \\frac{H \\cdot W}{p^2} \\cdot r_{\\text{merge}} $$</div>\n<p>其中 $F$ 为帧数，$p$ 为 patch 尺寸，$r_{\\text{merge}}$ 为空间合并率。该式说明视频 token 数是三因素乘积，任一因素翻倍都使 $N^2$ 项四倍。代价上，视频请求的编码阶段 HBM 带宽占用时间更长，峰值窗口更宽，与并发请求重叠的概率更高——这使视频成为触发软失败的主要来源。</p>\n\n<h3 id=\"ap-visual-oom-failure-sec-4\">四 · 分类维度三：按峰值构成分激活主导与中间矩阵主导</h3>\n<p>视觉塔峰值由两部分构成：逐层激活（MLP 中间张量、归一化缓冲、残差）与中间 attention 矩阵。前者随 $N$ 线性增长，后者随 $N^2$ 增长。在小 $N$ 区间激活主导，在大 $N$ 区间 attention 矩阵主导，存在一个交叉点。分类的价值在于选缓解手段：激活主导时，减小批内并发或做层间重计算有效；矩阵主导时，唯一有效的是缩短 $N$（切块、压缩前置）或改用不物化完整矩阵的 attention 实现（分块 softmax、流式归约）。</p>\n<p>工程判断方法：在编码阶段按层打点显存峰值，若峰值集中在 attention 层且随 $N$ 超线性抬升，判定为矩阵主导；若峰值均匀分布在各层 MLP 且随 $N$ 近似线性，判定为激活主导。前者对应本条目最典型的形态，也是“压缩放在视觉塔之后无效”的根本原因——压缩发生在矩阵已经物化之后。</p>\n<table class=\"mini\"><thead><tr><th>峰值构成</th><th>随 N 的增长</th><th>有效缓解</th><th>无效缓解</th></tr></thead><tbody><tr><td>逐层激活</td><td>线性</td><td>缩批、重计算</td><td>仅压分辨率</td></tr><tr><td>中间 attention 矩阵</td><td>平方</td><td>切块、压缩前置、分块 attention</td><td>缩批（单请求仍超限）</td></tr></tbody></table>\n<p>代价侧写：矩阵主导时，单请求即可击穿容量，缩批无效，必须改单请求的 $N$；这意味着分辨率上限成为硬约束，精度损失不可避免，工程上要在像素预算与任务精度之间做显式取舍，而不是靠调度兜底。</p>\n\n<h3 id=\"ap-visual-oom-failure-sec-5\">五 · 与批调度、预处理、量化的概念切分</h3>\n<p>与多模态批饥饿的区别：批饥饿是队列侧无请求可组批、GPU 空转，显存并不紧张；视觉塔溢出是显存侧打满、被迫缩批。两者都表现为吞吐下降，但前者扩容方向是请求供给与路由，后者是单请求峰值与并发上限。监控上，饥饿时编码阶段显存峰值低而利用率低，溢出时峰值高而利用率被动下降。</p>\n<p>与预处理工具链的区别：预处理做解码、缩放、归一化，发生在 GPU 编码之前，其失败是主机侧或拷贝侧问题；视觉塔溢出发生在 GPU 前向内部。把像素预算约束放在预处理阶段是有效的（它直接改变 $N$），但预处理本身不构成该失败模式。与量化配方的区别：量化降低权重与激活的位宽，能压低 $M_{\\text{weight}}$ 与部分激活占用，但对 $N^2$ 项只能按位宽比例缩放，不能改变增长阶；因此量化是乘性缓解，不是结构性缓解，遇到矩阵主导的峰值仍需切块与压缩前置。</p>\n<p>一个具体例子：同一张高分辨率图，在预处理阶段把长边限制到某一像素预算并切块，$N$ 从数千降到数百量级，attention 项按平方缩小，单请求峰值回到可容纳区间；若只在视觉塔之后压缩 token，则峰值不变，OOM 依旧。这个对比就是本条目与“视觉 token 压缩”条目的分界线：压缩的位置决定它是否属于本失败模式的缓解手段。</p>\n<p>监控口径上，需在编码器入口记录 $N$ 与批内并发 $B$，在每层记录激活峰值，在出口记录压缩前后 token 数；三条数据合起来才能把一次 OOM 归因到“$N$ 过大”“$B$ 叠加”还是“压缩未前置”。缺少入口 $N$ 的记录，扩容只能靠猜。</p>\n\n<h3 id=\"ap-visual-oom-failure-sec-6\">六 · 定义收敛：三条判据与一个反例</h3>\n<p>收敛为三条判据：失败点位于视觉编码器前向；峰值随输入像素预算与批内并发变化，随解码长度不变；attention 项呈平方增长且可通过缩短 $N$ 或改 attention 实现消除。三条同时成立才归入本条目。反例：某次 OOM 发生在编码阶段，但根因是权重加载与编码并发争抢显存——峰值不随 $N$ 变化，这属于部署配置问题，不是视觉塔溢出，处置应是错开加载与编码，而非砍分辨率。</p>\n<p>这个反例的工程价值在于防止过度归因：一旦把所有编码阶段 OOM 都当作 token 暴涨，就会系统性地牺牲分辨率精度去修一个配置问题。判据二的“随解码长度不变”正是用来排除 KV 侧混入，判据三的“平方项”用来排除权重与碎片问题。分类维度最终服务于处置顺序：先判硬/软失败定是否缩批，再判图像/视频定约束哪个乘子，最后判激活/矩阵主导定是重计算还是切块压缩前置。</p>\n\n<h3 id=\"ap-visual-oom-failure-sec-7\">七 · 边界条件：编码侧峰值与解码侧占用的分界</h3>\n<p>视觉塔显存溢出的判定边界不在“显存用了多少”，而在“峰值出现在哪个阶段”。同一张卡上，视觉塔激活峰值与解码侧 KV 占用是两条独立曲线：前者随输入像素预算、切块数量、批内并发编码请求数瞬时抬升，在编码完成后即回落；后者随上下文长度与并发序列数单调累积，在解码全程持续存在。把两条曲线合并成一条“显存利用率”指标，就丧失了区分能力——编码阶段 OOM 会被误读为解码侧不足，扩容方向随之错配。工程上应分别采样视觉塔激活峰值与 KV 占用，并以“单请求峰值是否超过卡容量”作为硬边界、“接近上限时调度器是否被迫缩批”作为软边界，后者表现为吞吐骤降而非报错。</p>\n<p>失效条件集中在三处。其一，动态分辨率上限按请求静态设定而不随批内并发调整：单请求时像素预算安全，多请求并发编码时激活叠加仍会击穿上限，因此上限必须是批级预算而非请求级常量。其二，token 压缩放在视觉塔之后而非前置：压缩前的中间 attention 矩阵已按 token 数平方增长占满显存，压缩收益无法兑现，压缩必须前移到切块编码的输出侧。其三，只监控 LLM 侧 KV cache：编码阶段 OOM 发生在视觉塔内部，KV 曲线毫无异常，误判几乎必然发生。</p>\n<div class=\"formula\">$$M_{\\text{peak}} \\approx B_{\\text{enc}} \\cdot \\left( A_{\\text{act}}(T) + \\alpha T^2 \\right),\\quad T = \\sum_{i=1}^{K} T_i$$</div>\n<p>其中 $B_{\\text{enc}}$ 为并发编码请求数，$T$ 为切块后总 token 数，$K$ 为切块数，$\\alpha T^2$ 即中间 attention 矩阵项。该式给出两个系统代价判断：切块使 $T$ 随分辨率线性上升，但平方项使激活峰值超线性膨胀，故分辨率上限与切块策略必须联合标定；并发编码使 $B_{\\text{enc}}$ 直接乘在峰值上，批调度需为视觉塔预留独立配额，否则解码侧扩容对编码侧 OOM 无效。以长视频抽帧为例，帧数与每帧切块数共同决定 $K$，若仅限制单帧分辨率而不限制帧数，$T$ 仍可击穿预算——这正是该失败模式区别于 LLM 侧 KV 溢出的根本：它的自变量是输入像素与切块结构，而非上下文长度。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>视觉塔显存溢出</th><th>LLM 侧 KV cache 溢出</th></tr></thead><tbody><tr><td>发生阶段</td><td>编码</td><td>解码</td></tr><tr><td>峰值形态</td><td>瞬时、随批并发叠加</td><td>单调累积、随序列增长</td></tr><tr><td>主自变量</td><td>像素预算、切块数、并发编码数</td><td>上下文长度、并发序列数</td></tr><tr><td>监控曲线</td><td>视觉塔激活峰值</td><td>KV 占用</td></tr></tbody></table>\n<h3 id=\"ap-visual-oom-failure-sec-8\">八 · 速查表的字段口径：把\"像素预算—token 数—激活峰值\"钉成一条链</h3>\n<p>这张表不是参数推荐表，而是<strong>判读表</strong>：每一行给出一个可观测字段、一个必须当场判定的阈值口径、以及该字段在哪个阶段被采样。视觉塔显存溢出的根因是 attention 矩阵随 token 数平方增长，而高分辨率切块后 token 数线性上升、激活峰值随之超线性膨胀，所以任何单看\"输入分辨率\"或单看\"卡剩余显存\"的字段都不足以定位问题。速查表的第一原则是：字段必须能还原成 token 数，token 数必须能还原成激活峰值。</p>\n<p>把链路写成一条可核算的关系式，便于工程上反推预算：</p>\n<div class=\"formula\">$$M_{\\text{peak}} \\approx \\underbrace{N_{\\text{patch}}\\,d\\,b}_{\\text{激活主体}} + \\underbrace{\\alpha\\,N_{\\text{patch}}^{2}\\,h\\,b}_{\\text{中间 attention}} + M_{\\text{static}}$$</div>\n<p>其中 $N_{\\text{patch}}$ 为切块后视觉 token 总数，$d$ 为塔内隐维，$b$ 为编码批内并发请求数，$h$ 为注意力头数，$\\alpha$ 为与注意力实现（是否融合、是否分块 softmax）相关的系数，$M_{\\text{static}}$ 为权重与工作区。工程判读的关键在于：第二项对 $N_{\\text{patch}}$ 是平方、对 $b$ 是线性，因此\"批内并发编码\"与\"单请求超高分辨率\"是两种不同量级的爆点，速查表必须能分别识别。</p>\n<p>代价口径要写清楚：单请求峰值超卡容量时直接报错，属硬失败；接近上限时调度器被迫缩批，表现为批吞吐骤降——后者更隐蔽，因为监控上只看到吞吐下滑而看不到 OOM 事件。因此速查表把\"峰值占卡容量比例\"设为独立字段，而不是只记录是否 OOM。</p>\n<ul>\n<li><strong>字段</strong>：视觉塔激活峰值（采样于编码 kernel 结束前的峰值显存水位，非稳态均值）。</li>\n<li><strong>口径</strong>：以卡容量为分母，超过 1.0 为硬失败，落在高区间即触发缩批风险判定。</li>\n<li><strong>采样点</strong>：每个编码 micro-batch 结束后立即读取，与解码侧 KV 占用曲线分开记录。</li>\n</ul>\n\n<h3 id=\"ap-visual-oom-failure-sec-9\">九 · 阈值分层：硬阈值、软阈值与并发叠加阈值</h3>\n<p>速查表的阈值不能只给一条线。视觉塔溢出有三种触发路径，对应三类阈值：单请求分辨率导致的硬阈值、批内并发叠加导致的软阈值、以及压缩前置缺失导致的\"收益不可兑现\"阈值。三者判定依据不同，混用一条线会把扩容方向带偏。</p>\n<p>硬阈值针对单请求：给定卡容量与塔权重占用，反解允许的最大 $N_{\\text{patch}}$，再折算成像素预算。由于 attention 项是平方项，像素预算随分辨率提升不是线性收紧，而是加速收紧——这就是动态分辨率上限必须按\"像素预算\"而非\"边长上限\"设定的原因。软阈值针对批：当 $b$ 个请求同时进入编码，激活项按 $b$ 线性叠加，而 attention 项在融合实现下可能被分块摊薄，实际叠加系数小于 $b$，需实测标定而非按 $b$ 直接乘。</p>\n<p>第三类阈值最容易被漏掉：token 压缩若放在视觉塔之后，压缩前的中间 attention 矩阵已占满显存，压缩收益无法兑现。速查表因此设一个\"压缩位置\"字段，取值只有\"前置\"与\"后置\"两种，后置即判定为无效配置，无论压缩比多高。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>阈值类型</th><th>判定字段</th><th>触发条件口径</th><th>系统代价表现</th></tr>\n</thead>\n<tbody>\n<tr><td>硬阈值</td><td>单请求激活峰值 / 卡容量</td><td>超过 1.0</td><td>编码阶段 OOM，请求直接失败</td></tr>\n<tr><td>软阈值</td><td>批内并发编码数 × 单请求峰值</td><td>叠加后逼近卡容量</td><td>调度器缩批，批吞吐骤降</td></tr>\n<tr><td>压缩阈值</td><td>压缩位置（前置/后置）</td><td>后置即无效</td><td>峰值未被削减，压缩算力白付</td></tr>\n<tr><td>分辨率阈值</td><td>像素预算 vs 动态上限</td><td>上限按请求静态设定且不随并发调整</td><td>多请求并发编码时激活叠加击穿上限</td></tr>\n</tbody>\n</table>\n<p>具体例子：一张高分辨率图切块后 token 数线性上升，若塔内注意力未做分块 softmax，中间矩阵按平方膨胀，单请求即可越过硬阈值；此时若把分辨率上限从\"边长\"改成\"像素预算\"并允许按批内并发下调，同一批请求的峰值水位被压回软阈值以下，吞吐恢复而非继续缩批。</p>\n\n<h3 id=\"ap-visual-oom-failure-sec-10\">十 · 分块编码的字段：块数、块内 token、块间重叠</h3>\n<p>分块编码是速查表里字段最多的一栏，因为它是把\"平方项\"切成\"多个小平方项\"的唯一手段。设总 token 数为 $N$，切成 $k$ 块、每块 $N/k$ 个 token，则 attention 项从 $\\alpha N^{2}$ 降为 $k\\cdot\\alpha (N/k)^{2}=\\alpha N^{2}/k$——峰值随块数线性摊薄，但块间重叠会把这笔收益部分吃掉。</p>\n<div class=\"formula\">$$N_{\\text{eff}} = k\\cdot\\frac{N}{k}\\,(1+\\rho),\\qquad M_{\\text{attn}} \\approx \\alpha\\,(N/k)^{2}\\,h\\,b\\,(1+\\rho)^{2}$$</div>\n<p>$\\rho$ 为块间重叠比例。速查表要求同时记录块数、块内 token 上限、重叠比例三个字段，因为只调块数而不控重叠，实际峰值下降会低于预期。代价侧要写清：块数增加意味着编码 kernel 启动次数增加、块间结果拼接引入额外显存搬运，端到端编码延迟上升；这是用延迟换显存的典型交换，速查表须标注该栏为\"延迟敏感\"。</p>\n<ul>\n<li><strong>块内 token 上限</strong>：直接决定单块 attention 矩阵规模，是硬阈值的实际控制变量。</li>\n<li><strong>重叠比例</strong>：影响拼接质量与峰值摊薄效率，重叠越大摊薄越差。</li>\n<li><strong>块间拼接缓冲</strong>：分块结果的暂存区，属常被忽略的显存项，需单独计入 $M_{\\text{static}}$。</li>\n</ul>\n<p>具体例子：长视频抽帧后 token 序列暴涨，若整段一次性编码，attention 矩阵瞬时占满显存；改为按时间窗分块、块内 token 数封顶、重叠比例压低，则每块峰值可控，编码阶段不再 OOM，代价是编码总时长增加、块边界处需做特征对齐。</p>\n\n<h3 id=\"ap-visual-oom-failure-sec-11\">十一 · 监控口径：两条曲线必须分开，字段不可合并</h3>\n<p>速查表最核心的一条纪律是：视觉塔激活峰值与解码侧 KV 占用是两条独立曲线，不可合并成一个\"显存使用率\"。该失败模式发生在视觉编码阶段，与 LLM 侧 KV cache 溢出机理完全不同；只监控 KV 曲线会把编码阶段的 OOM 误判为解码侧显存不足，扩容方向随之错误——加 KV 分页或降并发解码都无济于事。</p>\n<p>监控字段的采样口径要写死：激活峰值按编码 micro-batch 采样并保留峰值而非均值，因为均值会抹平瞬时尖峰；KV 占用按解码步采样。两条曲线的时间轴对齐后，可判断 OOM 发生在编码窗口还是解码窗口。工程上这决定了排查顺序：先看编码窗口峰值是否越线，再看解码侧。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>监控字段</th><th>采样口径</th><th>误判风险</th></tr>\n</thead>\n<tbody>\n<tr><td>视觉塔激活峰值</td><td>编码 micro-batch 峰值，非均值</td><td>与 KV 合并后尖峰被稀释</td></tr>\n<tr><td>解码侧 KV 占用</td><td>解码步采样</td><td>被当作 OOM 主因，导致错误扩容</td></tr>\n<tr><td>批内并发编码数</td><td>编码窗口内同时在编请求数</td><td>缺失则无法解释软阈值触发</td></tr>\n<tr><td>缩批事件</td><td>调度器缩批日志</td><td>吞吐骤降被误判为算力不足</td></tr>\n</tbody>\n</table>\n<p>具体例子：线上出现编码阶段 OOM，若监控只有 KV 曲线，运维会判定解码侧显存不足并扩容 KV 池，问题复现；补上激活峰值字段后可见编码窗口尖峰越线，正确动作是下调像素预算或增加分块数，而非动 KV。</p>\n\n<h3 id=\"ap-visual-oom-failure-sec-12\">十二 · 速查表的使用顺序与失效判据</h3>\n<p>速查表按固定顺序读：先看压缩位置字段，后置则整表其余优化都不成立，先改前置；再看单请求激活峰值是否越硬阈值，越线则收紧像素预算或加分块；再看批内并发编码数与软阈值，叠加越线则动态下调分辨率上限而非静态设定；最后看缩批事件与吞吐曲线，确认代价落在延迟还是吞吐。</p>\n<p>失效判据要明确写出：动态分辨率上限按请求静态设定、不随批内并发调整时，多请求并发编码的激活叠加仍会击穿显存上限，此时表上各项看似合规而实际失败——这是速查表最需要防范的\"合规但失效\"状态。判据是：并发编码数上升时峰值是否同步上升且未被上限拦截，若是，则上限配置失效。</p>\n<ul>\n<li><strong>顺序不可颠倒</strong>：压缩前置是前提条件，不是优化项。</li>\n<li><strong>上限必须动态</strong>：像素预算随批内并发反比收紧，静态上限在并发场景下失效。</li>\n<li><strong>代价归属要标注</strong>：分块换显存付延迟，缩批换稳定付吞吐，二者不可混记。</li>\n</ul>\n<p>具体例子：批内并发从单请求升到多请求同时编码，静态像素上限未变，激活叠加击穿容量触发缩批；把上限改为按并发数反比下调后，峰值被压在软阈值下，吞吐回到缩批前水平，代价是单请求分辨率在高峰时段被临时降级——这一降级必须作为显式字段记录，否则会被误读为画质回退故障。</p>\n\n<h3 id=\"ap-visual-oom-failure-sec-13\">十三 · 速查表：视觉塔显存预算的字段、阈值与失效口径</h3>\n<p>这张表不是参数清单，而是编码阶段的“熔断判据”。四个字段必须同时采集：视觉塔激活峰值 <code>A_peak</code>（编码器前向中最大的单层激活字节数，含 attention 中间矩阵）、输入像素预算 <code>P_budget</code>（单请求允许的最大像素数）、批内并发编码数 <code>B_enc</code>（同一调度窗口内同时进入视觉塔的请求数）、以及分块数 <code>C</code>（单图切块后的子图数量）。判据写作：<div class=\"formula\">$$A_{peak}(P_{budget}, C) \\times B_{enc} \\le M_{free} - M_{reserve}$$</div>其中 <code>M_free</code> 是编码时刻卡上可用显存，<code>M_reserve</code> 是留给 LLM 侧 KV 与权重的保留量。关键在于 <code>A_peak</code> 随 token 数平方增长，而 token 数随 <code>P_budget</code> 线性上升——所以像素预算翻倍，激活峰值约四倍，这条非线性决定了阈值不能按线性余量设定。</p>\n<table class=\"mini\"><thead><tr><th>字段</th><th>采集口径</th><th>触发动作</th><th>失效条件</th></tr></thead><tbody><tr><td><code>A_peak</code></td><td>视觉塔单层最大激活字节，按最大分块实测</td><td>超过 <code>M_free−M_reserve</code> 的 70% 即降 <code>P_budget</code></td><td>只测平均激活，漏掉 attention 矩阵瞬时峰值</td></tr><tr><td><code>P_budget</code></td><td>按请求静态设定</td><td>超限则切块</td><td>不随 <code>B_enc</code> 联动，并发叠加击穿上限</td></tr><tr><td><code>B_enc</code></td><td>调度窗口内并发编码请求数</td><td>乘性校验 <code>A_peak×B_enc</code></td><td>与解码批混算，误判为 KV 不足</td></tr><tr><td><code>C</code></td><td>切块数，块间独立编码</td><td><code>C</code> 增大则单块 <code>A_peak</code> 下降</td><td>压缩放在塔后，中间矩阵已占满</td></tr></tbody></table>\n<p>这张表的边界很硬：它只覆盖编码阶段的激活占用，不覆盖解码侧 KV。工程上最常见的失效是把两条曲线合并成一条“显存使用率”，于是 OOM 发生在编码阶段却被判为解码侧不足，扩容方向整个错掉——加 KV 分页、调低并发解码都无济于事，因为峰值根本不在那条路径上。第二个失效是 <code>P_budget</code> 按请求静态设定：单请求时表算得通，多请求并发编码时 <code>B_enc</code> 让激活线性叠加，而 <code>A_peak</code> 本身已是超线性，乘起来直接击穿 <code>M_reserve</code> 之上的余量。第三个失效是压缩位置：token 压缩若放在视觉塔之后，压缩前的中间 attention 矩阵已经把显存吃满，压缩带来的收益无法兑现，表上 <code>C</code> 那一行等于白填。</p>\n<p>系统代价要按口径算清楚。降 <code>P_budget</code> 换来的是编码延迟上升——分块编码把一次前向拆成 <code>C</code> 次，块间串行则编码时延近似乘 <code>C</code>，块间并行则激活叠加回 <code>B_enc</code> 那一侧，两条路都要付代价：前者牺牲首 token 延迟，后者牺牲显存余量。缩 <code>B_enc</code> 直接压吞吐，因为编码阶段是批处理管线的入口，入口缩批会让后续解码批填不满，GPU 利用率下滑。真正的工程判断是：把 <code>A_peak×B_enc</code> 作为调度器的准入条件而非事后告警，让视觉塔激活峰值与解码侧 KV 占用各走一条监控曲线，两条曲线各自的余量独立核算，任何一条触线就只动它自己那一侧的旋钮。</p>\n<h3 id=\"ap-visual-oom-failure-sec-14\">十四 · 像素预算：把分辨率上限写成可执行的字节约束</h3>\n<p>“动态分辨率上限”在工程上必须落成一个可计算的像素预算，而不是一个凭感觉设定的边长。视觉塔的激活峰值近似正比于 <span>N<sub>tok</sub></span> 的平方项与线性项之和，其中 <span>N<sub>tok</sub> = ⌈H/p⌉ · ⌈W/p⌉</span>，<span>p</span> 为 patch 边长。给定卡上可用于视觉塔的显存额度 <span>M<sub>vis</sub></span>，可反解出允许的最大 token 数：</p>\n<div class=\"formula\">$$N_{\\text{tok}}^{\\max}=\\left\\lfloor \\frac{M_{\\text{vis}}-M_{\\text{w}}}{a\\cdot L_{\\text{enc}}+b\\cdot L_{\\text{enc}}^{2}}\\right\\rfloor,\\qquad P^{\\max}=N_{\\text{tok}}^{\\max}\\cdot p^{2}$$</div>\n<p>其中 <span>M<sub>w</sub></span> 是权重与工作区常驻部分，<span>a</span>、<span>b</span> 是每层线性激活与 attention 矩阵的单位 token 系数，<span>L<sub>enc</sub></span> 是编码层数。工程上不必解析求解 <span>a</span>、<span>b</span>，而是用二分法实测：固定批为 1，把输入像素从低到高扫，记录首次触发 OOM 或触发分配器回退的像素值，再乘一个安全系数（经验上取 0.7–0.85，取决于同卡是否还跑其他进程）。这个“单请求像素上限”是后续所有并发控制的分母。</p>\n<p>代价落在吞吐上：像素预算收紧后，同一张大图被切成更多块，编码调用次数线性上升，单请求编码延迟随之上升，而峰值显存下降。对视频而言，预算要按“帧数 × 单帧像素”联合分配，因为长视频的 token 数由帧数与每帧切块数相乘得到，只限单帧分辨率而不限帧数，等于没限。</p>\n\n<h3 id=\"ap-visual-oom-failure-sec-15\">十五 · 并发叠加系数：静态上限为什么会失效</h3>\n<p>按请求静态设定的分辨率上限在多请求并发编码时会失效，原因是激活峰值不是简单相加而是叠加后再乘一个调度系数。设批内第 <span>i</span> 个请求的 token 数为 <span>N<sub>i</sub></span>，若视觉塔把批内 token 拼接成一条序列做 attention，峰值近似为 <span>(ΣN<sub>i</sub>)<sup>2</sup></span>；若逐请求独立编码再聚合，峰值为 <span>ΣN<sub>i</sub><sup>2</sup></span>。两者差距在批越大时越显著，这正是“单请求能跑、批一开就 OOM”的机制来源。</p>\n<p>因此并发控制要写成：</p>\n<div class=\"formula\">$$\\sum_{i\\in \\text{batch}} N_i \\le N_{\\text{tok}}^{\\max}\\quad\\text{或}\\quad \\sum_{i\\in \\text{batch}} N_i^{2}\\le \\left(N_{\\text{tok}}^{\\max}\\right)^{2}$$</div>\n<p>前者对应拼接式编码，后者对应独立编码。工程判断是先确认框架走哪条路径，再选约束式；把拼接式误当独立式配额度，就会在并发 2–4 路时击穿上限。具体例子：一批 4 张图，单张 1024×1024、patch 14，单张约 5.4k token；独立编码峰值按平方和计，拼接编码峰值按 21.6k 的平方计，后者是前者的 4 倍量级。调度器若只按“每请求 ≤ 单请求上限”放行，就会在编码阶段 OOM 而非解码阶段。</p>\n<p>代价是批吞吐：约束式收紧后，调度器被迫把大图请求单独成批或延后，批内并发度下降，编码阶段 GPU 利用率下滑。这是用吞吐换稳定性的显式交易，必须写进容量规划而不是临时降级。</p>\n\n<h3 id=\"ap-visual-oom-failure-sec-16\">十六 · 分块编码的块尺寸与重叠带测量</h3>\n<p>分块编码把大图切成若干块分次编码，块尺寸的选择直接决定峰值显存与块间语义断裂程度。块太小，块数上升、编码调用次数上升、跨块注意力被切断，下游精度受损；块太大，单块激活仍可能超预算。经验做法是把块尺寸设为像素预算对应的最大边长，再留 10%–20% 的重叠带（overlap）以缓解切缝处的语义断裂。重叠带使有效 token 数上升，需在预算中扣除：</p>\n<div class=\"formula\">$$N_{\\text{eff}}=\\left(\\left\\lceil \\frac{H}{B-o}\\right\\rceil\\cdot\\left\\lceil \\frac{W}{B-o}\\right\\rceil\\right)\\cdot\\left(\\frac{B}{p}\\right)^{2}$$</div>\n<p>其中 <span>B</span> 为块边长，<span>o</span> 为重叠带宽度。测量方法是：固定重叠带，扫块边长，记录单块峰值显存与块数，取“峰值显存低于预算的 80% 且块数最少”的点。代价是延迟：块数增加使编码从一次调用变为多次串行或并行调用，串行时延迟近似线性上升；并行时峰值显存按块数叠加，反而回到并发叠加问题，因此分块编码通常与“块内并行、块间串行”的调度配合。</p>\n<p>具体例子：一张 4096×4096 的图，patch 14，整图约 85k token，平方项直接超预算；切成 4×4 共 16 块、每块 1024×1024 加 128 像素重叠，单块约 5.4k token，峰值回到单请求预算内，但编码调用从 1 次变为 16 次，编码延迟相应上升。是否值得取决于 SLO 中编码阶段的时间预算，而不是默认开启。</p>\n\n<h3 id=\"ap-visual-oom-failure-sec-17\">十七 · token 压缩前置的收益兑现条件</h3>\n<p>token 压缩放在视觉塔之后而非前置，压缩收益无法兑现，因为压缩前的中间 attention 矩阵已经占满显存。前置压缩的工程含义是：在视觉塔内部或入口处就降低 token 数，例如在 patch embedding 后做池化或选择，使进入深层 attention 的序列变短。收益兑现的条件可写成不等式：</p>\n<div class=\"formula\">$$M_{\\text{peak}}^{\\text{after}}\\left(N_{\\text{tok}}\\right)\\approx M_{\\text{peak}}^{\\text{before}}\\left(r\\cdot N_{\\text{tok}}\\right),\\qquad r&lt;1$$</div>\n<p>只有当压缩比 <span>r</span> 作用在 attention 矩阵形成之前，峰值才按 <span>r<sup>2</sup></span> 量级下降；若压缩发生在之后，峰值不变，只是下游 LLM 侧 KV 占用下降——那是另一个失败模式，不能用来缓解编码阶段 OOM。测量方法是分别记录“压缩前视觉塔峰值”与“压缩后视觉塔峰值”两条曲线，若两者重合，说明压缩位置错了。</p>\n<p>代价是精度与实现复杂度：前置压缩改变视觉塔输出分布，需要重新校准下游；实现上要在编码器内部插入压缩算子，而不是在编码器输出后加一个模块。工程判断是：先确认 OOM 发生在视觉塔内部还是编码输出之后，前者才值得做前置压缩，后者应优先调分辨率上限与分块。</p>\n\n<h3 id=\"ap-visual-oom-failure-sec-18\">十八 · 两条曲线的分离监控与阈值设定</h3>\n<p>监控必须把视觉塔激活峰值与解码侧 KV 占用分成两条独立曲线，否则 OOM 发生在编码阶段却被误判为解码侧显存不足，扩容方向错误。可执行的测量方法是在编码入口与出口各打一个显存采样点，记录 <span>M<sub>vis,peak</sub></span> 与 <span>M<sub>kv</sub></span>，并计算两者占卡容量的比例。阈值设定建议：视觉塔峰值超过可用额度 80% 触发告警，超过 90% 触发分辨率上限收紧；KV 占用单独设阈值，两者不共用一条水位线。</p>\n<p>具体机制上，采样点要放在 attention 矩阵分配之后、释放之前，否则采样到的是稳态而非峰值。代价是采样本身引入同步开销，高频采样会拖慢编码；折中做法是每 N 个请求采样一次，或在检测到批吞吐骤降时临时提高采样频率。批吞吐骤降是编码阶段接近上限的先行指标：调度器缩批导致吞吐下滑，此时峰值往往已接近上限但尚未报错，是最有价值的观测窗口。</p>\n<p>工程判断落在阈值与调度策略的耦合上：分辨率上限、并发叠加约束、分块尺寸三者共享同一个像素预算分母，任何一项单独调松都会让另外两项失效。把预算写成配置项、把三条约束写成同一份校验逻辑，比在 OOM 后逐项排查更能稳住编码阶段的显存曲线。</p>\n\n<h3 id=\"ap-visual-oom-failure-sec-19\">十九 · 阈值怎么定：从像素预算到并发叠加的工程标尺</h3>\n<p>视觉塔的显存阈值不能拍一个“最大分辨率”了事，必须拆成三层可测量的量：单请求激活峰值、批内并发叠加系数、以及留给解码侧的余量。第一层用像素预算约束输入，设视觉塔切块边长为 <span class=\"inline-math\">P</span>、patch 尺寸为 <span class=\"inline-math\">p</span>，则单块 token 数 <span class=\"inline-math\">n=(P/p)^2</span>，attention 矩阵元素数约 <span class=\"inline-math\">n^2</span>；若切块数为 <span class=\"inline-math\">k</span>，串行编码时峰值只与单块 <span class=\"inline-math\">n</span> 有关，而一旦把 <span class=\"inline-math\">k</span> 块并行铺到同一 batch，峰值就按 <span class=\"inline-math\">k</span> 倍叠加。工程上真正要卡的是“同时驻留的块数”，而不是图像总像素。</p>\n<div class=\"formula\">$$M_{\\text{peak}} \\approx B_{\\text{blk}}\\cdot\\big(\\alpha\\, n^2 + \\beta\\, n\\, d\\big) + M_{\\text{static}} \\le M_{\\text{card}} - M_{\\text{kv}}^{\\text{reserve}}$$</div>\n<p>式中 <span class=\"inline-math\">\\(B_{\\text{blk}}\\)</span> 是并发编码的块数，<span class=\"inline-math\">α、β</span> 是 attention 与激活的每元素字节系数，<span class=\"inline-math\">\\(M_{\\text{static}}\\)</span> 为权重与工作区，<span class=\"inline-math\">\\(M_{\\text{kv}}^{\\text{reserve}}\\)</span> 是必须留给解码侧 KV 的硬预留。这条式子给出两个可直接落地的阈值：其一，固定 <span class=\"inline-math\">\\(M_{\\text{kv}}^{\\text{reserve}}\\)</span> 后反解出允许的 <span class=\"inline-math\">\\(B_{\\text{blk}}\\)</span> 上限，调度器据此限制同一时刻进入编码阶段的请求数；其二，固定 <span class=\"inline-math\">\\(B_{\\text{blk}}\\)</span> 后反解出单块 <span class=\"inline-math\">n</span> 的上限，即动态分辨率上限的真实来源。注意 <span class=\"inline-math\">n^2</span> 项意味着分辨率上限对峰值是超线性的，把边长放宽一倍，单块激活约涨四倍，这就是“稍微调大一点分辨率就 OOM”的数学原因。</p>\n<p>测量方法上，不能只看框架报的显存占用总量，那会把视觉塔激活与解码 KV 混在一条曲线里，正是误判扩容方向的根源。正确做法是在编码阶段前后打点：进入视觉塔前记录一次基线，每完成一个切块记录一次增量，得到“块数—峰值”的阶梯曲线；同时单独记录解码侧 KV 占用曲线。两条曲线分开画，才能判断 OOM 究竟发生在编码还是解码。若手头没有细粒度打点，可用二分法逼近：固定 batch 与分辨率，逐步增加并发块数直到报错，取报错前一步的块数作为该配置下的经验上限，再乘一个安全系数（工程上常取留出可观的显存余量而非贴边运行）写入调度约束。这个上限必须随批内并发动态调整——静态按请求设定的分辨率上限在多请求并发编码时会被叠加击穿，这正是该方案最典型的失效条件。</p>\n<p>系统代价要算清三笔账。第一是吞吐：把 <span class=\"inline-math\">\\(B_{\\text{blk}}\\)</span> 压到 1 换取安全，等于把视觉编码完全串行化，编码阶段延迟随切块数线性上升，长视频场景下这段延迟会直接顶穿 TTFT 的 SLO。第二是显存碎片：分块编码反复申请释放中间缓冲，若分配器不做池化，峰值之外的碎片会把有效余量吃掉，表现为“算出来够、跑起来 OOM”。第三是 token 压缩的位置账：压缩若放在视觉塔之后，压缩前的中间 attention 矩阵已经按 <span class=\"inline-math\">n^2</span> 占满显存，压缩收益无法兑现；只有把压缩前置到切块入口、先降 <span class=\"inline-math\">n</span> 再算 attention，峰值才真正下降。因此阈值表应写成“像素预算 → 块边长 → 并发块数 → 预留 KV”的四元组，并明确每条约束失效时的降级顺序：先降并发块数，再降块边长，最后才动压缩策略，因为前两者只影响编码延迟，后者会改变模型输入分布。</p>\n<table class=\"mini\"><thead><tr><th>观测量</th><th>打点位置</th><th>判据</th><th>失效后果</th></tr></thead><tbody><tr><td>视觉塔激活峰值</td><td>每切块编码前后</td><td>峰值+预留 ≤ 卡容量</td><td>编码阶段 OOM</td></tr><tr><td>并发块数</td><td>调度入队处</td><td>≤ 反解上限</td><td>叠加击穿上限</td></tr><tr><td>解码 KV 占用</td><td>解码步进</td><td>独立于激活曲线</td><td>误判扩容方向</td></tr><tr><td>压缩前 token 数</td><td>视觉塔入口</td><td>先降 n 再算 attention</td><td>压缩收益为零</td></tr></tbody></table>\n\n<h3 id=\"ap-visual-oom-failure-sec-20\">二十 · 视觉塔峰值显存的阈值判定与实测方法</h3>\n<p>视觉塔是否已经逼近溢出边界，不能靠卡上剩余显存的瞬时读数判断，而要盯住编码阶段的激活峰值。工程上可用的判据是：单请求编码峰值 <span class=\"formula\">$$M_{\\text{peak}} \\approx M_{\\text{weight}} + s \\cdot N_{\\text{tok}}^2 \\cdot b_{\\text{attn}} + N_{\\text{tok}} \\cdot d \\cdot b_{\\text{act}}$$</span> 其中 <span class=\"formula\">$$N_{\\text{tok}}$$</span> 为切块后视觉 token 数，<span class=\"formula\">$$b_{\\text{attn}}$$</span>、<span class=\"formula\">$$b_{\\text{act}}$$</span> 为 attention 矩阵与激活的每元素字节数，<span class=\"formula\">$$s$$</span> 为同时驻留的注意力头/层因子。真正决定 OOM 的是平方项，因此阈值应表述为“每卡可容纳的最大 <span class=\"formula\">$$N_{\\text{tok}}$$</span>”，而不是“最大分辨率”。测量方法是：固定批大小为 1，逐级抬高输入像素预算直到编码阶段报错，回退一档得到单请求安全 token 上限；再以该上限除以批内并发编码请求数，得到动态分辨率上限的运行时取值。若只按静态分辨率配置，多请求并发编码时激活叠加仍会击穿上限。</p>\n<p>经验上需要区分两条曲线：视觉塔激活峰值与解码侧 KV 占用。前者随输入像素预算阶跃式抬升、在编码完成后立即释放；后者随生成长度线性累积、常驻显存。监控若只采样解码侧 KV，OOM 发生在编码阶段就会被误判为解码侧不足，扩容方向随之错误。可操作的做法是在编码 kernel 前后各打一次显存水位，取差值作为该请求的激活峰值，并按 token 数归档成表，供调度器在准入时查询。</p>\n<table class=\"mini\"><thead><tr><th>观测量</th><th>采样点</th><th>用途</th></tr></thead><tbody><tr><td>编码前后显存差值</td><td>视觉塔 forward 首末</td><td>单请求激活峰值，准入判据</td></tr><tr><td>批内并发编码数</td><td>调度器队列</td><td>动态分辨率上限缩放因子</td></tr><tr><td>解码侧 KV 水位</td><td>每步 decode</td><td>与视觉峰值分曲线告警</td></tr></tbody></table>\n<p>系统代价体现在三处：把分辨率上限压到安全 token 数以下，会直接损失细粒度视觉信息，等效于降低有效输入像素预算；分块编码把一次大激活拆成多次小激活，代价是编码阶段串行化、首 token 延迟上升；token 压缩若放在视觉塔之后而非前置，压缩前的中间 attention 矩阵已占满显存，压缩收益无法兑现。因此阈值设定的工程判断是：以单请求安全 token 上限为硬边界，按批内并发数动态收缩分辨率，并把压缩与切块放在编码入口而非出口，使峰值显存在准入阶段即可预测而非事后观测。</p>\n<h3 id=\"ap-visual-oom-failure-sec-21\">二十一 · 三类高频踩坑的机理定位</h3>\n<p>视觉塔显存溢出的排查之所以反复失手，是因为失败点不在一个地方，而在三个互相掩护的位置。第一类是监控盲区：只盯 LLM 侧 KV cache 曲线，把编码阶段 OOM 误读成解码侧显存不足，于是扩容方向整个错掉——加卡、加 KV 分块、调低 max batch，全都不解决问题，因为峰值根本不来自解码。第二类是静态分辨率上限的失效：上限按单请求像素预算设定，看起来安全，但批内多请求并发编码时，视觉塔激活是叠加的，N 个请求同时进入编码阶段，峰值近似 N 倍单请求峰值，静态上限挡不住这种叠加。第三类是压缩位置错误：token 压缩放在视觉塔之后，压缩前的中间 attention 矩阵已经把显存占满，压缩带来的收益在时间上晚于峰值出现，等于没做。</p>\n<p>三者共同的数学根源是视觉塔 attention 矩阵随 token 数平方增长。设切块后 token 数为 <span class=\"inline-math\">S</span>，单层 attention 分数矩阵元素量为 <span class=\"inline-math\">S²</span>，若批内并发编码请求数为 <span class=\"inline-math\">B_enc</span>，则瞬时峰值近似正比于：</p>\n<div class=\"formula\">$$ M_{\\text{peak}} \\;\\approx\\; B_{\\text{enc}} \\cdot L \\cdot \\alpha \\cdot S^{2} \\cdot b $$</div>\n<p>其中 <span class=\"inline-math\">L</span> 为层数、<span class=\"inline-math\">α</span> 为同时驻留的中间张量份数、<span class=\"inline-math\">b</span> 为元素字节数。这个式子直接解释了三类坑：<span class=\"inline-math\">B_enc</span> 不受静态上限约束（坑二），<span class=\"inline-math\">S²</span> 项在压缩前置之前就已计入（坑三），而 <span class=\"inline-math\">M_peak</span> 与解码侧 KV 完全无关（坑一）。工程代价上，坑一导致错误的容量投资，坑二导致吞吐在高峰期骤降而非报错，坑三导致压缩算力白花、显存峰值不降。</p>\n<p>具体例子：一个批里同时进来若干张高分辨率图，调度器按单请求预算放行，编码阶段并发触发，激活叠加击穿上限，表现为编码阶段 OOM；若此时监控只看 KV 曲线，运维会得出“KV 不够”的错误结论。正确的判断是看编码阶段激活峰值是否与批内并发编码数同向变化。</p>\n\n<h3 id=\"ap-visual-oom-failure-sec-22\">二十二 · 检查顺序：从曲线到根因的固定路径</h3>\n<p>排查必须固定顺序，避免在错误方向上反复试探。第一步永远是分离两条曲线：视觉塔激活峰值与解码侧 KV 占用必须作为独立指标采集，前者按编码阶段的时间窗统计峰值，后者按解码步统计占用。只有两条曲线分开，才能判定 OOM 发生在编码阶段还是解码阶段。这一步的代价很低，但缺了它后面全部失效。</p>\n<p>第二步核对峰值与并发编码数的关系。取若干次编码阶段的峰值样本，观察 <span class=\"inline-math\">M_peak</span> 是否随 <span class=\"inline-math\">B_enc</span> 近似线性上升。若是，说明静态分辨率上限没有随批内并发调整，属于坑二；若峰值与并发无关而只随单请求分辨率上升，则问题在像素预算本身。第三步检查压缩发生的位置：在计算图上确认 token 压缩节点是在视觉塔 attention 之后还是之前，若在之后，则峰值时间窗内压缩尚未生效，坑三成立。</p>\n<p>第四步才是量化验证：用一次受控输入，记录编码阶段各层的中间张量尺寸，确认平方项主导的是哪一层、哪一份中间量。伪代码思路如下：</p>\n<ul>\n<li>采集编码阶段逐层峰值，标记 <span class=\"inline-math\">S²</span> 项最大的层；</li>\n<li>固定单请求分辨率，扫描 <span class=\"inline-math\">B_enc</span>，拟合峰值斜率；</li>\n<li>在计算图上定位压缩节点，比较压缩前后峰值时间窗；</li>\n<li>按定位结果选择动态上限、分块编码或压缩前置中的一项先改，单项验证。</li>\n</ul>\n<p>顺序的意义在于代价：先改调度参数再改压缩位置，等于用吞吐代价换一个不存在的收益；先分离曲线再动容量，避免把编码峰值当成解码缺口去扩容。每一步都对应一个可观测的量，不做无依据的调参。</p>\n\n<h3 id=\"ap-visual-oom-failure-sec-23\">二十三 · 动态上限与分块编码的落地细节</h3>\n<p>动态分辨率上限的关键不是设一个数，而是让上限随批内并发编码数收缩。设卡上可用于视觉塔的显存预算为 <span class=\"inline-math\">\\(M_{\\text{budget}}\\)</span>，单请求在给定 token 数下的峰值估计为 <span class=\"inline-math\">m(S)</span>，则允许同时编码的请求数应满足：</p>\n<div class=\"formula\">$$ B_{\\text{enc}} \\;\\le\\; \\left\\lfloor \\frac{M_{\\text{budget}}}{m(S)} \\right\\rfloor $$</div>\n<p>调度器据此在编码阶段做准入控制：当 <span class=\"inline-math\">B_enc</span> 达到上限时，新请求排队等待编码而非直接放行。这会把“接近上限时被迫缩批导致吞吐下滑”变成可控的排队，代价是编码阶段尾延迟上升，但避免了 OOM 与吞吐骤降的抖动。分块编码则从另一侧降低 <span class=\"inline-math\">S</span>：把大图切块分次编码，单次 <span class=\"inline-math\">S</span> 下降使 <span class=\"inline-math\">S²</span> 项按平方缩小，峰值随之下降；代价是块间需要合并逻辑，且块数增加带来额外的前处理与调度开销。</p>\n<p>两者叠加时的次序很重要：先按动态上限控制并发，再对超预算的单请求启用分块，最后在进 LLM 前做 token 压缩前置。具体例子：批内并发编码数上升时，调度器收缩单请求允许的像素预算并降低 <span class=\"inline-math\">B_enc</span>，同时对仍超预算的请求切块分次编码，使编码阶段峰值稳定在预算内，吞吐不再出现骤降。这里要强调的是，动态上限必须与批调度联动，静态设定在多请求并发下必然失效。</p>\n\n<h3 id=\"ap-visual-oom-failure-sec-24\">二十四 · 压缩前置与监控口径的统一</h3>\n<p>token 压缩前置是唯一能在峰值时间窗内生效的压缩方式。把压缩节点移到视觉塔 attention 之前，意味着进入平方项的 <span class=\"inline-math\">S</span> 已经是压缩后的序列长度，峰值按 <span class=\"inline-math\">S²</span> 缩小；若压缩放在之后，峰值时间窗内 <span class=\"inline-math\">S</span> 未变，收益为零。工程代价是压缩本身要在编码前完成，可能引入额外的预处理延迟与精度损失，需要在压缩率与视觉质量之间取舍，但显存收益是确定的。</p>\n<p>监控口径必须与这一改动同步：视觉塔激活峰值曲线要标注压缩节点位置，确保峰值统计发生在压缩之后的时间窗；否则会把压缩前的瞬时峰值误记为系统峰值，得出“压缩无效”的错误结论。同时，编码阶段 OOM 与解码侧 KV 占用必须继续分开统计，避免坑一复发。具体例子：压缩前置后，编码阶段峰值随压缩率下降，而解码侧 KV 曲线不变；若监控仍按旧口径统计压缩前峰值，就会看不到改善，进而错误回滚。</p>\n<p>这里的一个工程判断是：压缩前置与动态上限解决的是不同维度，前者降 <span class=\"inline-math\">S</span>，后者降 <span class=\"inline-math\">B_enc</span>，两者不能互相替代。只做压缩前置而不控制并发，多请求叠加仍会击穿上限；只控制并发而不压缩，单请求高分辨率仍可能超预算。</p>\n\n<h3 id=\"ap-visual-oom-failure-sec-25\">二十五 · 回滚方案与变更边界</h3>\n<p>回滚方案要按变更的影响面分级，而不是一刀切回旧版本。第一级回滚是调度参数：把动态上限与并发准入恢复到变更前的取值，代价是吞吐回到旧水平但不影响正确性，适用于峰值抖动但未 OOM 的情形。第二级是压缩位置：把压缩节点从视觉塔前移回之后，代价是显存峰值回升、压缩收益消失，适用于压缩前置引入精度问题或预处理延迟不可接受的情形。第三级是分块编码：关闭切块合并逻辑，回到整图编码，代价是单请求峰值回升，适用于块间合并引入视觉质量下降的情形。</p>\n<p>回滚的判据必须是可观测的：编码阶段峰值是否回到预算内、批吞吐是否恢复、输出质量是否达标。三者中任一不满足，就应停在上一级而不是继续回滚。工程上还要保留变更前的基线峰值样本，否则回滚后无法判断是否真的恢复。具体例子：压缩前置上线后若发现视觉问答质量下降，应先核对是否压缩率过高而非直接回滚调度参数；若确认是压缩位置导致，则回滚到压缩后置并保留动态上限，避免把两个独立变更一起撤销。</p>\n<p>最后落在机制上：视觉塔显存溢出的稳定性来自峰值可预测，而峰值可预测的前提是 <span class=\"inline-math\">B_enc</span> 与 <span class=\"inline-math\">S</span> 两个变量都在准入控制之下，压缩前置保证 <span class=\"inline-math\">S</span> 在平方项计入前已被削减，动态上限保证并发叠加不越预算。任何一项缺失，峰值就重新变成不可预测的量，OOM 与吞吐骤降会以随机形式复现。</p>\n\n<h3 id=\"ap-visual-oom-failure-sec-26\">二十六 · 编码阶段的显存盲区：三条失效路径与回滚顺序</h3>\n<p>这套缓解组合的边界不在算法本身，而在监控口径。视觉塔激活峰值与解码侧 KV 占用是两条独立曲线，前者随输入像素预算瞬时冲高、随编码完成立即回落，后者随序列长度单调累积。若容量规划只按 KV 曲线做水位告警，编码阶段的尖峰就落在采样盲区里：OOM 报错被归因为解码侧显存不足，扩容方向指向 KV 分页或前缀缓存，而真正的瓶颈是视觉塔中间 attention 矩阵。工程上必须把两条曲线分开采集，并把视觉塔激活峰值作为独立 SLO 指标，采样粒度要细到单次编码调用，否则尖峰在聚合窗口内被均值抹平。代价是监控开销：逐请求记录激活峰值意味着额外的显存打点与事件上报，在高并发编码下本身会引入可观测的调度抖动，需限定采样率而非全量埋点。</p>\n<p>第二条失效路径来自静态分辨率上限。按请求设定像素预算，在单请求场景下确实能把 token 数压在阈值内，但批内并发编码时激活是叠加的：若调度器把 N 个请求同时送进视觉塔，峰值近似为各请求激活之和而非最大值。设单请求视觉 token 数为 <span class=\"formula\">$$T_i = \\frac{P_i}{p^2}$$</span>（<span class=\"formula\">$$P_i$$</span> 为像素预算，<span class=\"formula\">$$p$$</span> 为切块边长），则批内视觉塔激活峰值随 <span class=\"formula\">$$\\sum_i T_i^2$$</span> 增长，平方项使并发叠加远快于线性。因此分辨率上限必须与批内并发数联动：并发上升时收紧单请求像素预算，或强制编码阶段串行化分块。代价直接体现在吞吐上——串行编码把视觉塔的并行度压到单请求级别，批吞吐骤降，这正是该失败模式在接近显存上限时的典型表现。</p>\n<p>第三条是压缩时序错位。token 压缩若放在视觉塔之后，压缩前的中间 attention 矩阵已经按平方规模占满显存，压缩收益无法兑现，等于用一次 OOM 换取一个更小的输出。压缩必须前置到切块编码的入口，在 token 进入 attention 计算之前完成降采样或剪枝，使参与平方运算的序列长度本身变小。检查顺序应按代价从低到高排：先核对监控是否区分两条曲线，再验证分辨率上限是否随批内并发动态调整，最后确认压缩点位于视觉塔之前而非之后。回滚方案对应这条顺序反向执行——先恢复静态分辨率上限并强制编码串行，牺牲吞吐换稳定；若仍击穿，则关闭分块并行、退回单块编码；最后才回退压缩前置逻辑，因为它是收益最高也最易引入精度损失的一环。回滚的工程判断标准是编码阶段峰值显存与卡容量的余量，余量不足时宁可降批也不动压缩路径。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>误判方向</th><th>回滚动作</th><th>系统代价</th></tr></thead><tbody><tr><td>只监控 KV 曲线</td><td>归因解码侧不足</td><td>拆分双曲线采集</td><td>监控打点开销</td></tr><tr><td>静态分辨率上限</td><td>忽略并发叠加</td><td>编码串行化</td><td>批吞吐骤降</td></tr><tr><td>压缩后置</td><td>收益无法兑现</td><td>压缩前置</td><td>精度与实现复杂度</td></tr></tbody></table>\n<h3 id=\"ap-visual-oom-failure-sec-27\">二十七 · 上游依赖：分辨率预算与预处理链决定视觉塔的输入形态</h3>\n<p>视觉塔显存溢出不是孤立故障，它的触发条件由上游预处理链直接写入。图像视频预处理工具链决定送入视觉塔的像素张量形状，而动态分辨率上限决定这个形状的上界；两者共同定义了视觉塔 attention 矩阵的边长。工程上必须把“像素预算”作为跨条目契约固定下来：预处理侧不得在未通知推理侧的情况下放大分辨率，推理侧也不得假设预处理已做等比裁剪。一个具体机制是：预处理输出携带 <code>pixel_budget</code> 与切块网格元数据，视觉塔入口据此计算 token 数 <code>N = ceil(H/p)·ceil(W/p)</code>，并在编码前与当前批的激活预算比较。代价落在延迟与吞吐上——预算校验本身是微秒级，但一旦校验失败触发重切块，单请求编码延迟会从一次前向变成多次分块前向，批吞吐随之被拉低。公式上，激活峰值近似正比于 <code>N²·d</code>（d 为视觉塔隐藏维），因此像素预算翻倍会让峰值约四倍化，这正是预处理侧一个看似无害的放大操作能击穿显存的路径。例子：同一张图在预处理中被补边到方形而非等比缩放，token 数上升，编码阶段 OOM，而解码侧 KV 曲线完全正常——这类故障若只按解码侧扩容，方向就错了。</p>\n<p>上游还依赖多模态量化配方：视觉塔若以 FP8/NVFP4 运行，激活张量的字节宽度下降，同一显存容量可容纳更大的 token 序列，但量化前的校准与反量化中间缓冲会额外占显存，配方必须声明这些缓冲的峰值。视觉编码器术语表提供 token 数与感受野的换算，跨模态注意力术语提供视觉 token 进入 LLM 前的接口形状，这两者是本条目计算预算时的输入，不在此复述。</p>\n\n<h3 id=\"ap-visual-oom-failure-sec-28\">二十八 · 下游影响：批调度、分离式预填与 KV 预算被编码峰值反向约束</h3>\n<p>视觉塔激活峰值一旦成为批级约束，多模态批调度就从“按 KV 容量装箱”变成“按双预算装箱”：批内每个请求同时消耗视觉激活预算与解码 KV 预算，调度器必须在编码阶段与解码阶段之间切换约束。伪代码思路是：对候选批 B，计算 <code>peak_vis(B) = Σ_i act(N_i)</code> 与 <code>kv(B) = Σ_i kv_len_i·bytes</code>，仅当两者分别低于各自水位才接纳；否则按 <code>N_i</code> 降序剔除请求。代价是吞吐：编码阶段接近上限时调度器被迫缩批，批吞吐骤降正是该失败模式的第二种表现。具体机制上，连续批处理在编码与解码交错时会出现“编码请求占住激活、解码请求等 KV”的争用，分离式预填配方把编码放到独立池正是为了切断这种争用——但独立池的容量规划必须直接引用本条的激活峰值模型，否则预填池会在高分辨率突发时先 OOM。例子：NVL72 上一个预填池按平均分辨率配置显存，遇到长视频抽帧批次时视觉塔激活叠加击穿上限，预填池整体重启，解码侧被迫排队，端到端 SLO 违约。</p>\n<p>下游还影响多模态批饥饿：当调度器为规避激活溢出而长期压低编码并发，编码队列积压，解码侧出现饥饿，表现为 TTFT 恶化而 ITL 正常。多模态上线前清单应把“视觉塔激活峰值与 KV 占用两条曲线分别监控”列为必检项，因为只监控 KV 会把编码期 OOM 误判为解码侧不足。视频抽帧与批配方则决定单请求 token 数的分布尾部，尾部越厚，批级激活预算越难装箱。</p>\n\n<h3 id=\"ap-visual-oom-failure-sec-29\">二十九 · 在全书中的位置：编码阶段失败模式与解码阶段失败模式的分界</h3>\n<p>本书把推理失败模式按阶段切分：视觉塔显存溢出属于编码阶段，LLM 侧 KV cache 溢出属于解码阶段，二者的监控曲线、扩容方向与缓解手段都不同。本条目在全书中的位置是“多模态链路的入口约束”——它约束的是 token 进入 LLM 之前的形状与峰值，而不是解码期的缓存增长。这个位置决定了它与其他条目的关系是“供给方”：视觉 token 压缩前置、动态分辨率上限、分块编码三项手段的产出（压缩后的 token 序列与切块元数据）是下游所有多模态条目的输入假设。工程判断上，任何多模态容量规划都应先解编码阶段峰值，再解解码阶段 KV，因为编码峰值是超线性的而 KV 是线性的，前者更容易成为硬墙。代价维度上，编码阶段失败是“全有或全无”的：单请求峰值超过卡容量直接报错，没有降级余地；解码侧则可以通过缩批、换页、驱逐来软降级。这个不对称性正是本条在全书结构中的分量所在。</p>\n<p>与视觉token压缩术语的关系是：压缩前置把 <code>N</code> 降下来，直接缩小 <code>N²·d</code> 的峰值，因此压缩不是后处理优化而是显存安全手段；把它放在视觉塔之后，压缩前的中间 attention 矩阵已经占满显存，收益无法兑现。与多模态推理框架的关系是：框架的图捕获与内存池策略决定激活峰值能否被复用，图捕获若把最大分辨率形状写死，动态分辨率上限就失效。与 Triton/CUTLASS 的关系是：分块编码的 kernel 选择影响分块间的激活复用率，进而影响峰值。</p>\n\n<h3 id=\"ap-visual-oom-failure-sec-30\">三十 · 跨条目契约：监控、容量与配方三处接口</h3>\n<p>本条目向其他条目输出三处接口，每处都有明确的代价。监控接口：视觉塔激活峰值与解码侧 KV 占用必须是两条独立曲线，采样粒度对齐到编码步而非请求级，否则瞬时峰值被平均掉；代价是监控开销与存储，但换来的是 OOM 归因正确。容量接口：容量规划条目在计算单卡可承载并发时，必须把 <code>peak_vis</code> 作为独立项扣除，而不是并入 KV 预算；代价是可用并发数下降，收益是消除编码期硬失败。配方接口：多模态量化配方与视频抽帧配方必须声明其输出 token 数的分布上界，供本条计算最坏峰值。表格给出接口与失效后果的对应。</p>\n<table class=\"mini\"><thead><tr><th>接口</th><th>对接条目</th><th>失效后果</th></tr></thead><tbody><tr><td>像素预算与切块元数据</td><td>预处理工具链</td><td>token 数超预期，编码 OOM</td></tr><tr><td>激活峰值模型</td><td>批调度 / 分离式预填</td><td>缩批或预填池重启，吞吐骤降</td></tr><tr><td>双曲线监控</td><td>上线前清单</td><td>OOM 误判为解码侧，扩容方向错误</td></tr><tr><td>token 分布上界</td><td>抽帧与量化配方</td><td>尾部请求击穿批级预算</td></tr></tbody></table>\n<p>一个具体机制是把激活峰值模型做成调度器的准入函数：<code>admit(B) = peak_vis(B) ≤ V_budget ∧ kv(B) ≤ K_budget</code>，并在批内并发上升时动态收紧 <code>V_budget</code>，因为多请求并发编码时激活叠加而非共享。这正是“动态分辨率上限按请求静态设定”这一坑的根因：静态上限不随批内并发调整，叠加仍会击穿上限。</p>\n\n<h3 id=\"ap-visual-oom-failure-sec-31\">三十一 · 工程判断：先解编码峰值，再谈解码优化</h3>\n<p>在全书的多模态条目群中，本条是唯一以“超线性峰值”为特征的失败模式，因此它的优先级高于解码侧的一切优化：解码侧的 PagedAttention、前缀复用、投机解码都在线性或近线性维度上做文章，而编码侧的 <code>N²</code> 会在分辨率或时长跨过一个阈值时突然吃掉全部余量。工程判断是：容量规划的顺序必须是像素预算→切块→压缩前置→批级准入→KV 预算，任何跳过前三步直接调 KV 页大小的做法都会在编码阶段撞墙。代价上，压缩前置会损失少量视觉信息，分块编码会增加编码延迟与 kernel 启动开销，动态分辨率上限会降低极端输入的保真度——这三项代价换的是编码阶段不出现硬失败。例子：长视频抽帧批次在未设上限时单请求 token 数远超图像批次，视觉塔 attention 矩阵瞬时占满显存，表现为编码阶段 OOM；加上限与分块后，同一批次转为多次分块前向，峰值被压到水位以下，吞吐以编码延迟增加为代价恢复稳定。最后落在机制上：把 <code>act(N)</code> 的峰值估算与准入函数绑定，让调度器在编码前而非 OOM 后才知道预算不够，这是本条对其他条目最硬的约束。</p>\n\n<h3 id=\"ap-visual-oom-failure-sec-32\">三十二 · 边界条件：视觉塔溢出条目与上下游条目的耦合面</h3>\n<p>本条目在全书中的位置是“编码阶段失败模式”的独立条目，它与 KV cache 溢出条目构成一对容易混淆的邻居：两者都表现为 OOM，但监控曲线不同——前者是视觉塔激活峰值，后者是解码侧 KV 占用。工程上的直接后果是扩容方向错误：若把编码阶段 OOM 误判为解码侧不足，会去加 KV 分页预算或降并发，而真正该动的是像素预算与分块策略。因此本条目对上游的依赖是显存与 KV cache 条目提供的“两条曲线分离监控”约定，对下游的影响则是批调度与连续批处理条目必须把视觉编码的瞬时峰值纳入准入判断，否则调度器在接近上限时缩批，吞吐骤降会被记到调度策略头上。</p>\n<p>失效条件集中在“静态设定”与“前置位置”两点。动态分辨率上限若按请求静态设定而不随批内并发调整，多请求并发编码时激活叠加仍会击穿显存上限；此时单请求峰值不超限，但批内叠加超限，属于调度层失效而非算子层失效。另一条是 token 压缩放在视觉塔之后而非前置：压缩前的中间 attention 矩阵已占满显存，压缩收益无法兑现。设视觉 token 数为 <span class=\"formula\">$$N$$</span>，attention 矩阵元素量按 <span class=\"formula\">$$O(N^2)$$</span> 增长，切块后 <span class=\"formula\">$$N$$</span> 线性上升而激活峰值超线性膨胀，故压缩必须发生在矩阵形成之前，否则前置条件不成立。</p>\n<p>系统代价可用一个准入判据表达：批内并发 <span class=\"formula\">$$B$$</span> 个请求、每请求切块后 token 数 <span class=\"formula\">$$N_i$$</span>，编码阶段峰值近似为 <span class=\"formula\">$$\\sum_i c\\cdot N_i^2$$</span>，其中 <span class=\"formula\">$$c$$</span> 为每 token 的激活字节系数。准入要求该和低于卡容量减去解码侧预留。这解释了为何分辨率上限必须随 <span class=\"formula\">$$B$$</span> 动态收紧：固定上限只保证单请求安全，不保证批安全。代价体现在延迟与吞吐的取舍上——收紧上限降峰值但增加切块次数与编码往返，放宽则提升单请求分辨率却压缩并发空间。</p>\n<table class=\"mini\"><thead><tr><th>耦合对象</th><th>本条目提供的约束</th><th>失效时的表现</th></tr></thead><tbody><tr><td>KV cache 监控</td><td>区分视觉激活与解码 KV 两条曲线</td><td>扩容方向错误</td></tr><tr><td>批调度准入</td><td>峰值随批内并发动态收紧</td><td>并发编码叠加击穿上限</td></tr><tr><td>token 压缩</td><td>压缩必须前置到矩阵形成前</td><td>压缩收益无法兑现</td></tr></tbody></table>\n<p>在全书七个领域的推理形态中，该条目对高分辨率图像与长视频两类负载是硬约束：分块编码与压缩前置的顺序不可交换，先限像素预算、再切块分次编码、最后进 LLM 前压缩，三步中任一步后移都会让峰值落在错误阶段。工程判断落在监控粒度上——把视觉塔激活峰值作为独立 SLO 指标而非附属于解码侧，才能让上游的显存条目与下游的调度条目在同一判据下协同。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-visual-oom-failure\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>高分辨率图像或长视频使视觉token序列暴涨，视觉塔激活与中间attention矩阵瞬时占满显存</td></tr><tr><td>关键点</td><td>表现为编码阶段OOM或批吞吐骤降，需动态分辨率上限、分块编码与token压缩前置。</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-visual-oom-failure · 共 5 个片段</p>\n"},{"id":"ap-mm-batch-starvation","title":"多模态批饥饿","summary":"视觉编码耗时差异大导致LLM侧批内序列长度参差，短请求等待长图像编码完成而空转；表现为GPU利用率低与P99延迟抖动，需视觉塔独立批、分辨率分桶与超时降级策略。","kind":"失败模式","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-1\">一 · 条目边界：什么算批饥饿，什么不算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-2\">二 · 分类维度之一：方差来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-3\">三 · 分类维度之二：耦合强度与同步点位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-4\">四 · 分类维度之三：长尾的性质与降级路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-5\">五 · 与相邻概念的区别：三个易混点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-6\">六 · 边界条件：何时不算批饥饿，以及降级阈值的两难</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-7\">七 · 速查表的字段口径：先定义“可观测”，再定义“可配置”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-8\">八 · 速查表主体：字段、阈值、口径三列对照</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-9\">九 · 分辨率分桶的阈值口径：按像素量而非宽高比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-10\">十 · 超时降级的阈值口径：双向约束而非单边调参</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-11\">十一 · 独立批的配平字段：填充率与耦合度的联合判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-12\">十二 · 口径纪律：同一字段不得跨层混用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-13\">十三 · 速查表：阈值口径与失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-14\">十四 · 先量“编码耗时分布”，再谈阈值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-15\">十五 · 超时降级阈值的两难与设法定量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-16\">十六 · 分辨率分桶的阈值：按像素量而非宽高比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-17\">十七 · 批配平阈值的测量：编码耗时预估与批组成</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-18\">十八 · 阈值之间的耦合与上线前的测量清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-19\">十九 · 阈值不是拍脑袋：从「批就绪时刻」反推容忍窗口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-20\">二十 · 坑一：把视觉编码塞进解码批的同步点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-21\">二十一 · 坑二：超时降级阈值的双向失准</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-22\">二十二 · 坑三：分辨率分桶只按宽高比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-23\">二十三 · 坑四：把调度问题误判为容量问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-24\">二十四 · 检查清单与回滚顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-25\">二十五 · 阈值失准与分桶失配：补写清单里最容易漏掉的两类回滚触发点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-26\">二十六 · 上游依赖：视觉编码方差从哪来，本条目接谁的账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-27\">二十七 · 下游影响：批饥饿如何污染 KV cache、分离式部署与 SLO 容量规划</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-28\">二十八 · 与相邻条目的边界：哪些问题不归这里管</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-29\">二十九 · 在全书中的位置：调度层的“方差治理”节点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-batch-starvation-sec-30\">三十 · 边界条件：何时这套配平逻辑会失效</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-mm-batch-starvation\"><svg style=\"max-width:555px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 555.0 357\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"473.0\" height=\"83.0\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"53.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"57.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：多模态批饥饿</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">视觉编码耗时差异大导致LLM侧批内序列长度参差，短请求等待长图像编码完</text><text x=\"75.0\" y=\"78.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">成而空转</text><line x1=\"82.0\" y1=\"97.0\" x2=\"82.0\" y2=\"114.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 113.0 L 86.5 113.0 L 82.0 121.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"121.0\" width=\"473.0\" height=\"83.0\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"162.6\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"166.8\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"148.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><text x=\"75.0\" y=\"171.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">表现为GPU利用率低与P99延迟抖动，需视觉塔独立批、分辨率分桶与超时降</text><text x=\"75.0\" y=\"187.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">级策略。</text><line x1=\"82.0\" y1=\"206.1\" x2=\"82.0\" y2=\"223.1\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 222.1 L 86.5 222.1 L 82.0 230.1 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"230.1\" width=\"473.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"252.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"256.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"257.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"276.9\" x2=\"82.0\" y2=\"293.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 292.9 L 86.5 292.9 L 82.0 300.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"300.9\" width=\"473.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"323.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"327.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"328.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-mm-batch-starvation-sec-1\">一 · 条目边界：什么算批饥饿，什么不算</h3>\n<p>多模态批饥饿（multimodal batch starvation）在本卷中的准确定义是：视觉编码阶段各请求耗时差异过大，使 LLM 侧同一批内序列长度参差，短请求必须等待同批最慢的图像编码完成才能进入解码，等待期间其占用的批槽位与算力空转，表现为 GPU 利用率下降与 P99 延迟抖动。定义里有三个不可省略的成分：一是异构性来源必须是视觉编码耗时而非文本长度；二是耦合点必须是视觉编码与 LLM 解码共享同一调度单元与同一批同步点；三是后果必须落在批级资源空转上，而不只是单个请求变慢。</p>\n<p>据此可以划出三条排除线。第一，若某请求自身编码慢但批内其他请求并不等它——例如编码与解码已解耦到不同执行流、不同批——那属于分离式预填的调度收益问题，不是批饥饿。第二，若整批变慢是因为显存不够、KV cache 被换出或视觉塔激活峰值触发重算，那是容量问题，归入视觉塔显存溢出条目，其判据是显存水位与分配失败，而非批内耗时方差。第三，若所有请求编码都慢且方差很小，整批只是均匀地慢，那是吞吐不足而非饥饿；饥饿的本质是方差被同步屏障放大成木桶效应，而不是均值偏高。</p>\n<p>一个可操作的判别式：设批内第 i 个请求的视觉编码耗时为 $t^{enc}_i$，解码启动时刻为 $T_{start}=\\max_i t^{enc}_i$，则批级空转量近似为</p>\n<div class=\"formula\">$$W=\\sum_{i}\\left(T_{start}-t^{enc}_i\\right)\\cdot s_i$$</div>\n<p>其中 $s_i$ 为该请求在等待期间已占用的批槽位资源份额。$W$ 相对整批有效计算量的比值就是饥饿度。工程上判断是否命中该失败模式，看的是这个比值随批组成波动的幅度，而不是单看 GPU 利用率曲线——利用率低也可能是 kernel 粒度太细或通信等待，需要结合批内编码耗时的分布才能归因。</p>\n\n<h3 id=\"ap-mm-batch-starvation-sec-2\">二 · 分类维度之一：方差来源</h3>\n<p>批饥饿按方差来源可分为分辨率型、内容型与模态型三类，三者的配平手段不同，混为一谈会导致分桶策略失效。分辨率型方差来自像素量差异：同一批里混入 4K 截图与 224×224 缩略图，视觉塔的 token 数与注意力计算量随像素量增长，编码耗时相差数倍。内容型方差来自图像本身的可压缩性：高纹理、密集文字、复杂场景的图像在同样的像素量下需要更多有效计算，而大片纯色或简单图形的图像在视觉塔内早早饱和。模态型方差来自请求携带的模态组合：纯图、图+视频帧序列、多图交错文档，视频帧数直接乘进编码工作量。</p>\n<p>分类的意义在于决定分桶键。只按宽高比分桶属于典型的分类错误——它把分辨率型方差的一部分（形状）当成了全部，而同桶内像素量仍可能相差一个数量级，独立批的配平收益被抵消。正确的桶键至少应包含像素量区间，内容型方差则需要以编码耗时的在线预估或历史分位数作为二级键。举例：一个文档理解服务同时接收扫描件（高像素、高文字密度）与聊天截图（中等像素、低纹理），若只按 16:9 / 4:3 分桶，扫描件与截图仍会同桶，长尾依旧拖住整批；改为像素量分桶后，扫描件桶内耗时分布收窄，短请求桶可以在毫秒级内整批就绪。</p>\n<p>代价方面，分类越细，桶内批大小越小，视觉塔的批利用率下降，单位图像的编码摊销变高；分类越粗，饥饿度上升。这是一个显式的吞吐—延迟权衡，需要用桶内耗时方差与桶的到达率共同定标，而不是拍一个固定桶数。</p>\n\n<h3 id=\"ap-mm-batch-starvation-sec-3\">三 · 分类维度之二：耦合强度与同步点位置</h3>\n<p>第二个分类维度是视觉编码与 LLM 解码之间的耦合强度，即同步屏障出现在哪一层。最强耦合是批级同步：整批所有请求的编码全部完成后，才允许该批进入解码，屏障粒度等于批。次强是请求级流水：每个请求编码完成后即可插入解码队列，但受连续批处理的槽位约束，仍可能与后续请求的编码争抢同一执行资源。最弱是执行流级解耦：视觉塔与 LLM 各自独立批、独立调度，通过 KV/嵌入缓冲区交接，屏障退化为一次内存可见性同步。</p>\n<p>耦合强度决定了饥饿的传导路径。批级同步下，$T_{start}$ 由批内最大编码耗时决定，短请求的等待是硬等待，无法通过提高批大小摊薄，反而批越大长尾越可能被抽中。请求级流水下，等待被转化为槽位争抢：短请求虽不必等长请求编码完，但其解码槽位可能被长请求的编码占用，表现为解码吞吐的间歇性塌陷。执行流级解耦下，饥饿基本消失，代价转为缓冲区管理与跨流同步开销，以及视觉塔独立批在低到达率时的利用率损失。</p>\n<p>工程判断上，先测同步点位置，再谈配平。若框架默认把图像编码放在 LLM 调度器的同一步内，那么任何分桶策略都只是在缩小方差，而不能消除屏障；此时第一优先是把视觉塔拆成独立批，第二优先才是桶内配平。反过来，若已经解耦，仍观察到 P99 抖动，则应怀疑缓冲区交接处的批组成失衡，而不是视觉编码本身。</p>\n\n<h3 id=\"ap-mm-batch-starvation-sec-4\">四 · 分类维度之三：长尾的性质与降级路径</h3>\n<p>第三个维度是长尾请求的性质，它决定了超时降级策略的形态。第一类是分辨率长尾：少数请求携带超高像素图像，降级路径明确——降采样到低分辨率桶重编码，质量损失可控且可解释。第二类是内容长尾：像素量正常但视觉塔内部计算路径长（例如密集小文字触发更多有效 token），降级只能靠裁剪、分块或跳过部分区域，质量损失难以预估。第三类是模态长尾：视频帧数或交错图数量超限，降级是抽帧或截断，属于语义级取舍。</p>\n<p>超时降级阈值 $\\tau$ 的设定直接对应本条目说明中的两难：$\\tau$ 过松，长尾编码持续拖住批，P99 抖动无法收敛；$\\tau$ 过紧，降级比例过高，输出质量下滑且降级本身引入额外编码开销。可用的形式化思路是把 $\\tau$ 与批级等待预算挂钩：设批的 SLO 允许的解码启动延迟为 $D$，则 $\\tau$ 应满足 $\\tau \\le D - t^{dec}_{min}$，其中 $t^{dec}_{min}$ 为最短请求的解码首 token 时间下界；同时用长尾耗时分布的尾分位数校准，使降级比例落在可接受区间。</p>\n<p>具体例子：一个以 P99 首 token 延迟为 SLO 的图文问答服务，若把 $\\tau$ 设为批内编码耗时中位数的固定倍数，则在长尾到达率上升时降级比例被动抬升，输出质量抖动；改为按批级等待预算反推 $\\tau$，并把降级请求路由到低分辨率桶的独立批，长尾被隔离而非被砍掉，P99 收敛的同时降级比例保持稳定。代价是低分辨率桶需要额外的批槽位与一次重编码，显存带宽上多一次特征写入读出。</p>\n\n<h3 id=\"ap-mm-batch-starvation-sec-5\">五 · 与相邻概念的区别：三个易混点</h3>\n<p>第一，与连续批处理的槽位饥饿不同。后者指解码侧因新请求不断插入导致老请求被反复抢占、批槽位周转不灵，其方差来源是到达过程；多模态批饥饿的方差来源是编码耗时，即使到达过程完全平稳也会发生。第二，与分离式预填的队列失衡不同。后者发生在预填与解码被拆到不同 GPU 池后，两侧容量配比失当导致一侧排队；多模态批饥饿可以发生在单池内，不需要任何池间拆分，其判据是批内编码耗时分布而非队列长度。第三，与视觉塔显存溢出的区别已在第一节给出：前者是调度与同步问题，后者是容量问题；一个饥饿的批可能显存水位很低，一个显存溢出的批也可能编码耗时高度一致。</p>\n<p>还有一个易混点是视觉 token 压缩。压缩改变的是编码输出长度与解码侧序列长度，能降低解码成本并间接缩小批内序列参差，但它不改变编码阶段的耗时方差本身——压缩率高的图像仍可能编码慢。因此压缩是缓解饥饿的辅助手段，不是分类维度；把压缩当成配平主手段，会在长尾来自内容复杂度时失效。</p>\n<table class=\"mini\"><thead><tr><th>概念</th><th>方差/瓶颈来源</th><th>判据</th><th>主要代价</th></tr></thead><tbody><tr><td>多模态批饥饿</td><td>批内视觉编码耗时方差</td><td>批级空转量占比随批组成波动</td><td>GPU 利用率、P99 抖动</td></tr><tr><td>连续批槽位饥饿</td><td>请求到达过程与抢占</td><td>槽位周转率与排队时长</td><td>解码吞吐</td></tr><tr><td>分离式预填队列失衡</td><td>两池容量配比</td><td>池间队列长度差</td><td>跨池传输带宽</td></tr><tr><td>视觉塔显存溢出</td><td>激活峰值与 KV 占用</td><td>分配失败、换出、重算</td><td>显存容量</td></tr></tbody></table>\n<p>分类的落点是配平动作的选择：方差来源决定桶键，耦合强度决定是否先解耦，长尾性质决定降级路径的形态。三者共同确定一个批的组成规则，而这条规则的正确性只能由批级空转量与 P99 抖动两个观测量来验证，不能由单一利用率指标代替。</p>\n\n<h3 id=\"ap-mm-batch-starvation-sec-6\">六 · 边界条件：何时不算批饥饿，以及降级阈值的两难</h3>\n<p>多模态批饥饿的判定边界要先与两类相邻现象切开。其一是<b>容量型失败</b>：显存溢出、KV cache 打满、权重换入换出导致的吞吐塌陷，特征是显存水位与驱逐计数同步恶化，加卡或降并发即可缓解；批饥饿则是调度与同步问题，显存可能仍有富余，GPU 利用率却上不去。其二是<b>纯计算型长尾</b>：单请求自身编码就慢，但批内其余请求并不等它——那只是慢，不是饥饿。判据在于批级同步屏障是否存在：若视觉编码与 LLM 解码共用同一调度单元，批内最慢编码决定整批就绪时刻，短请求被迫空转，才构成条目定义下的批饥饿。工程上可用一个粗略的配平缺口来量化：设批内第 i 个请求的视觉编码耗时为 $t_i$，批就绪时刻为 $\\max_i t_i$，则空转代价近似为</p>\n<div class=\"formula\">$$W=\\sum_{i}\\left(\\max_{j} t_j - t_i\\right)$$</div>\n<p>W 越大，说明批组成越不配平；当 W 与批内解码计算量同量级时，饥饿已成为主导瓶颈，而非容量或算力不足。</p>\n<p>该方案最典型的失效条件是<b>超时降级阈值的两难</b>。阈值设得过松，长尾编码请求持续拖住整批，P99 延迟抖动无法收敛，短请求的空转照旧；设得过紧，降级比例过高，请求被切到低分辨率路径，输出质量受损，且降级本身引入额外的分支与重试逻辑，反而增加调度开销。阈值不是常数，应随批内编码耗时分布自适应：以近期同桶编码耗时的分位数作为基线，只在超出基线一定倍数时触发降级，并把降级决策记录进批组成日志，便于回溯 P99 抖动的来源。系统代价上，降级路径的显存占用更低、编码延迟更短，但精度损失不可逆，属于用质量换延迟的显式交易。</p>\n<p>第二个失效条件是<b>分辨率分桶的粒度错配</b>。若分桶只按宽高比而不按像素量，同桶内图像的实际编码耗时仍可能相差数倍，独立批的配平收益被抵消，视觉塔独立批退化为“换了个地方排队”。分桶键应至少包含像素量区间与宽高比两个维度，并在桶内按预估编码耗时排序后再组批。下表给出三种批组成策略在同步屏障上的差异：</p>\n<table class=\"mini\"><thead><tr><th>策略</th><th>同步屏障位置</th><th>主要代价</th><th>失效条件</th></tr></thead><tbody><tr><td>编码解码同批</td><td>批级，由最慢编码决定</td><td>短请求空转，GPU 利用率低</td><td>批内编码耗时方差大</td></tr><tr><td>视觉塔独立批</td><td>桶级，桶内仍需配平</td><td>跨塔流水线气泡、显存驻留上升</td><td>分桶粒度不足</td></tr><tr><td>超时降级</td><td>请求级，绕过屏障</td><td>输出质量下降、分支开销</td><td>阈值过松或过紧</td></tr></tbody></table>\n<p>值得注意的是，独立批并非没有代价：编码与解码解耦后，两段流水线之间需要显存驻留中间特征，跨塔交接引入气泡，若桶内请求数不足以填满视觉塔的批，独立批反而降低视觉塔自身的利用率。因此该方案的适用边界是“编码耗时方差显著且请求量足以支撑多桶并行”，在低负载或图像规格高度一致的场景下，同批耦合的同步开销可能小于解耦的交接开销，此时不应启用。</p>\n<h3 id=\"ap-mm-batch-starvation-sec-7\">七 · 速查表的字段口径：先定义“可观测”，再定义“可配置”</h3>\n<p>这张表不是参数清单，而是把多模态批饥饿从“现象”落到“可测量字段”的映射。字段必须满足两个条件：能从框架侧直接采样，且与批级同步屏障有因果链。口径上分三类：<strong>观测字段</strong>（只读，用于判定饥饿是否发生）、<strong>配平字段</strong>（参与批组成决策）、<strong>策略字段</strong>（触发降级或分桶）。观测字段的采样周期必须短于批周期，否则测到的是上一批的残影；配平字段必须在批组建之前可得，事后统计的编码耗时只能用于下一批的预估，不能救当前批。</p>\n<p>核心观测口径是“批就绪时刻的方差”，而不是平均利用率。设批 $b$ 内请求 $i$ 的视觉编码耗时为 $e_i$，LLM 侧首 token 前的等待为 $w_i$，则批启动时刻由 $\\max_i e_i$ 决定，短请求的空转量为：</p>\n<div class=\"formula\">$$S_b=\\sum_{i\\in b}\\left(\\max_{j\\in b} e_j-e_i\\right),\\qquad \\text{饥饿率}=\\frac{S_b}{\\sum_i e_i}$$</div>\n<p>这个比值直接对应 GPU 空转的算力份额。工程上把它作为一级指标，比看 SM 利用率更早暴露问题：利用率是结果，饥饿率是原因。举例：一批 8 个请求，编码耗时分别为 12、14、15、16、18、20、22、90 ms，则 $\\max=90$，空转总和约 113 ms，饥饿率接近 0.55——一半以上的编码算力花在等最慢那一个上。这个数字不需要实验测量，按字段采样即可算出。</p>\n\n<h3 id=\"ap-mm-batch-starvation-sec-8\">八 · 速查表主体：字段、阈值、口径三列对照</h3>\n<p>下表按“字段—阈值—口径”组织，阈值一列给的是判定方向而非固定常数，因为阈值必须随分辨率桶与模型规模标定；口径一列说明该字段在哪个环节采集、以什么统计量进入决策。表内所有阈值均以“相对量”表达，避免跨机型移植时失效。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>字段</th><th>阈值/判定</th><th>口径</th></tr>\n</thead>\n<tbody>\n<tr><td>批内编码耗时极差 max−min</td><td>超过桶内中位耗时的 2 倍即判饥饿</td><td>批组建前用历史分桶预估，批结束后回填实测</td></tr>\n<tr><td>饥饿率 $S_b/\\sum e_i$</td><td>持续高于 0.3 触发配平</td><td>按批滚动窗口统计，取 P50 与 P99 双口径</td></tr>\n<tr><td>编码耗时 P99/P50 比</td><td>大于 3 说明长尾未收敛</td><td>按分辨率桶分别统计，不跨桶合并</td></tr>\n<tr><td>批就绪等待 $w_i$ 的 P99</td><td>超过解码单步耗时的若干倍即不可接受</td><td>以请求为单位的端到端口径，含排队</td></tr>\n<tr><td>桶内像素量方差</td><td>同桶像素量跨度超过一档即需再分桶</td><td>按宽高比与总像素量双维度归桶</td></tr>\n<tr><td>超时降级比例</td><td>降级率上升而 P99 不降，说明阈值过松</td><td>降级请求数与总请求数之比，按时间窗</td></tr>\n<tr><td>视觉塔独立批的填充率</td><td>低于某比例说明独立批未配平</td><td>独立批实际请求数与该批容量上限之比</td></tr>\n<tr><td>解码侧批内序列长度方差</td><td>方差随编码方差同步上升即耦合未解</td><td>解码批组建时刻的序列长度分布</td></tr>\n</tbody>\n</table>\n<p>表的用法是“先看极差、再看饥饿率、最后看降级比例”。极差是瞬时信号，饥饿率是批级信号，降级比例是策略信号。三者顺序不能颠倒：先配平再降级，降级是兜底而不是首选。若跳过配平直接调超时阈值，等于用输出质量换延迟，且长尾依旧存在。</p>\n\n<h3 id=\"ap-mm-batch-starvation-sec-9\">九 · 分辨率分桶的阈值口径：按像素量而非宽高比</h3>\n<p>分桶字段最容易出错的地方是把宽高比当成分桶键。同一宽高比下，一张 336×336 与一张 1344×1344 的编码耗时不在一个量级，同桶内极差仍然很大，独立批的配平收益被抵消。正确口径是二维键：宽高比档位 + 总像素量档位。像素量档位按视觉塔的 patch 数取整，因为编码耗时近似随 patch 数线性增长：</p>\n<div class=\"formula\">$$n_{\\text{patch}}=\\left\\lceil\\frac{H}{p}\\right\\rceil\\cdot\\left\\lceil\\frac{W}{p}\\right\\rceil,\\qquad \\hat e\\approx \\alpha\\cdot n_{\\text{patch}}+\\beta$$</div>\n<p>其中 $p$ 为 patch 边长，$\\alpha$、$\\beta$ 由桶内实测回归得到，只用于批组建前的排序，不用于绝对预测。工程代价在于：桶数增加会降低每桶的批填充率，桶太细则独立批经常凑不满，视觉塔的算力利用率反而下降；桶太粗则极差回归。判断口径是“桶内像素量跨度不超过一档、桶间中位耗时差异明显”，用桶内方差与桶间均值差同时约束。举例：把 4 个像素档与 2 个宽高比档组合成 8 个桶，若某桶长期填充率不足，就与相邻桶合并，而不是放宽像素档。</p>\n\n<h3 id=\"ap-mm-batch-starvation-sec-10\">十 · 超时降级的阈值口径：双向约束而非单边调参</h3>\n<p>超时降级是唯一直接触碰输出质量的策略字段，因此阈值必须双向约束。设降级阈值为 $T$，长尾编码耗时分布为 $F$，则降级比例 $r=F(T)$ 与批就绪等待的 P99 构成一对矛盾：$T$ 放宽，$r$ 下降但 P99 抖动不收敛；$T$ 收紧，P99 收敛但 $r$ 上升。可用的判定口径是“降级带来的 P99 改善是否大于质量损失的可接受边界”，而不是追求单一最优 $T$。</p>\n<p>具体机制上，降级不是丢弃请求，而是把该请求路由到低分辨率路径重编码，其代价是视觉 token 数减少、跨模态对齐精度下降。因此阈值应以“该请求预估编码耗时超过当前批已就绪请求的最大耗时”为触发条件，而不是固定毫秒数——固定毫秒数在不同分辨率桶之间不可移植。伪代码思路：批组建时按预估耗时升序排列，累计到预估总耗时超过预算即封批，剩余请求进入下一批或触发降级；这个“预算”就是阈值的真实载体。代价上，封批过早会让批变小、解码侧吞吐下降；封批过晚则长尾拖住整批。工程判断是把预算绑定到解码单步耗时，使编码等待不超过一个解码步的量级。</p>\n\n<h3 id=\"ap-mm-batch-starvation-sec-11\">十一 · 独立批的配平字段：填充率与耦合度的联合判据</h3>\n<p>视觉塔独立批解决的是耦合，不解决方差。独立批之后仍需配平，判据是两个字段的联合：独立批填充率与解码侧序列长度方差。若填充率低而解码方差仍高，说明独立批只是把饥饿从解码侧搬到了编码侧，同步屏障没有消失，只是换了位置。此时应回到分桶字段，而不是继续加大独立批容量。</p>\n<p>耦合度的量化口径是“编码方差对解码批启动时刻的传导系数”：把批启动时刻的抖动对编码耗时极差做滚动回归，系数接近 1 说明完全耦合，接近 0 说明解耦生效。这个系数不需要精确数值，只需看趋势方向。举例：独立批上线后填充率上升但传导系数不降，通常意味着独立批内部仍按到达顺序组批，未按预估耗时排序；改为按桶内预估耗时排序组批后，传导系数才应下降。代价是排序本身引入调度开销，且预估误差会转化为新的方差，因此预估字段必须用回填实测持续校正。</p>\n\n<h3 id=\"ap-mm-batch-starvation-sec-12\">十二 · 口径纪律：同一字段不得跨层混用</h3>\n<p>最后一条是纪律而非参数：请求级口径与批级口径不得混用。请求级的 $w_i$ 用于 SLO 判定，批级的饥饿率用于配平决策，两者的统计窗口和聚合方式不同。把请求级 P99 直接当作批级阈值，会导致阈值随流量波动而漂移；把批级均值当作请求级 SLO，会掩盖长尾。工程上要求每个字段标注“层级—窗口—聚合”三元组，缺一不可。</p>\n<p>另一个纪律是降级比例必须与桶绑定统计。全局降级比例会被大桶稀释，小桶的长尾被掩盖；按桶看降级比例，才能判断是哪个像素档在持续触发降级。若某桶降级比例长期偏高而该桶请求量不大，正确动作是拆桶或为该桶单独设预算，而不是全局放宽阈值。这条判断落在具体机制上：批饥饿是调度与同步问题，任何试图用容量或全局参数掩盖它的做法，都会把方差推到下一个环节。</p>\n\n<h3 id=\"ap-mm-batch-starvation-sec-13\">十三 · 速查表：阈值口径与失效边界</h3>\n<p>这张表不是调参建议，而是把“批饥饿”从现象翻译成可观测字段的对照口径。核心思路只有一条：<strong>批就绪时刻由批内最慢视觉编码决定</strong>，因此所有字段都必须围绕“编码耗时预估”与“批级同步屏障”来设。表中阈值一律用相对量而非绝对毫秒，因为视觉塔的绝对耗时随分辨率、patch 数与模型深度漂移，写死数值必然失效。</p>\n<table class=\"mini\"><thead><tr><th>字段</th><th>口径与阈值</th><th>失效条件</th><th>系统代价</th></tr></thead><tbody><tr><td>编码耗时预估误差</td><td>预估与实际编码耗时之比，控制在窄区间内；超出即视为配平失效</td><td>分辨率分桶只按宽高比、不按像素量，同桶内方差仍大</td><td>误差越大，短请求空转越多，GPU 利用率下降</td></tr><tr><td>批内编码耗时极差</td><td>批内最长与最短编码耗时之差，超过桶内中位耗时的一定比例即拆批</td><td>拆批粒度过细导致批尺寸不足，解码吞吐塌陷</td><td>拆批增加调度开销与权重换入换出</td></tr><tr><td>超时降级阈值</td><td>以批就绪等待时间为触发量，而非单请求编码时长</td><td>过松：长尾持续拖住批，P99 抖动不收敛；过紧：降级比例过高，输出质量受损</td><td>降级路径省下编码算力，但牺牲视觉保真度</td></tr><tr><td>降级比例</td><td>单位时间内走低分辨率路径的请求占比，需与质量指标联动监控</td><td>阈值收紧后该比例单调上升，形成质量—延迟的硬权衡</td><td>低分辨率路径降低视觉塔负载与显存带宽占用</td></tr><tr><td>批同步屏障等待</td><td>短请求从编码完成到整批启动的空转时长</td><td>编码与解码耦合在同一调度单元时必然存在</td><td>直接体现为 SM 空闲与 P99 延迟抖动</td></tr></tbody></table>\n<p>把“批内编码耗时极差”作为拆批判据，是因为木桶效应下的等待代价可以写成可加的形式。设批内有 $n$ 个请求，第 $i$ 个请求的编码耗时为 $t_i$，解码启动时刻为 $T=\\max_i t_i$，则短请求的空转总量为</p>\n<div class=\"formula\">$$W=\\sum_{i=1}^{n}\\left(T-t_i\\right)=n\\cdot\\max_i t_i-\\sum_i t_i$$</div>\n<p>这个式子说明两件事：等待量随批尺寸线性放大，且完全由最大值主导。因此“按编码耗时预估配平”等价于压缩 $\\max_i t_i-\\min_i t_i$ 的极差，而不是压缩均值。分辨率分桶若只按宽高比切分，桶内像素量仍可相差数倍，$\\max_i t_i$ 的方差没有被消掉，独立批的收益就被抵消——这正是该方案最典型的失效条件。工程上应把桶键改为“像素量区间 × patch 数”，并在桶内再做一次极差检查。</p>\n<p>超时降级阈值的口径必须落在<strong>批就绪等待</strong>而非单请求编码时长上，否则阈值与真正要收敛的 P99 抖动脱钩。设阈值为 $\\tau$，降级比例为 $r(\\tau)$，则系统在延迟与质量之间沿一条单调曲线滑动：$\\tau$ 放宽使 $r$ 下降、质量上升，但长尾请求持续占据批同步点，P99 抖动无法收敛；$\\tau$ 收紧使 $r$ 上升，视觉塔负载与显存带宽压力下降，但低分辨率路径的输出质量损失不可逆。可操作的判据是：当降级比例随阈值收紧出现陡升拐点时，说明长尾分布本身未被分桶消解，此时应回到分桶策略而非继续压阈值。该失败模式是调度与同步问题而非容量问题，加显存、加卡都不改变批级屏障的存在，代价只会从空转转移到闲置带宽上。</p>\n<h3 id=\"ap-mm-batch-starvation-sec-14\">十四 · 先量“编码耗时分布”，再谈阈值</h3>\n<p>多模态批饥饿的所有阈值都建立在一个前提上：视觉编码耗时不是常数，而是一条带长尾的分布。工程上要设阈值，第一步不是拍数字，是把这条分布测出来。测量方法很直接：在视觉塔入口处给每个请求打两个时间戳，进入编码前与编码完成（或编码 kernel 结束、特征写回显存）各记一次，按请求的像素量、宽高比、图像数量分桶统计，输出每个桶的 P50、P90、P99 与最大值。这条分布的形状决定了后面所有阈值的取值方式——如果 P99 与 P50 的比值接近 1，说明编码耗时稳定，批饥饿风险低，阈值可以放宽；如果 P99 是 P50 的数倍，长尾就是主要矛盾，任何按均值配平的调度都会失效。</p>\n<p>这里要区分两个耗时口径：<strong>墙钟耗时</strong>（含排队、H2D 拷贝、kernel 启动）与<strong>纯 kernel 耗时</strong>（视觉塔前向本身）。批饥饿的直接原因是墙钟耗时的方差，而不是 kernel 本身的方差——一个像素量不大的图像如果排在长队列后面，墙钟耗时照样很长。因此测量必须记录请求从进入视觉塔队列到特征就绪的完整区间，否则会把排队延迟误判为编码方差，阈值方向就设反了。</p>\n<p>代价侧要同时采集三个量：视觉塔的 SM 占用率、LLM 侧批的空转比例（批已组成但未启动解码的时长占比）、以及 P99 端到端延迟。三者放在同一时间轴上对齐，才能看出“编码长尾 → 批就绪延迟 → P99 抖动”的传导链。经验判断是：当 LLM 侧空转比例超过一个可感知的水平，且该比例与视觉编码 P99/P50 比值正相关时，批饥饿已经发生，此时讨论阈值才有意义。</p>\n\n<h3 id=\"ap-mm-batch-starvation-sec-15\">十五 · 超时降级阈值的两难与设法定量</h3>\n<p>超时降级是批饥饿最直接的止血手段：请求在视觉塔停留超过阈值 T 后，放弃当前分辨率路径，改走低分辨率路径重新编码，或直接以已编码的部分特征进入解码。T 的取值是一个双向代价问题。设得过松，长尾请求持续拖住批，P99 抖动无法收敛；设得过紧，降级比例过高，输出质量受损。工程上把这两个代价写成可测量的量：</p>\n<div class=\"formula\">$$T^{*}=\\arg\\min_{T}\\ \\Big[\\lambda\\cdot \\frac{N_{\\text{deg}}(T)}{N_{\\text{total}}}+(1-\\lambda)\\cdot \\frac{W_{\\text{idle}}(T)}{W_{\\text{total}}}\\Big]$$</div>\n<p>其中 $N_{\\text{deg}}(T)/N_{\\text{total}}$ 是降级比例，$W_{\\text{idle}}(T)/W_{\\text{total}}$ 是 LLM 侧空转时间占比，$\\lambda$ 是业务给定的质量权重。这个式子不是用来解析求解的，而是用来做<strong>扫描实验</strong>：把 T 从编码耗时 P50 到 P99 之间取若干档，每档跑一段真实流量，记录降级比例与空转占比，画出两条曲线，取加权和最小的档位。关键在于 T 不能只按单请求耗时设，还要参考批内其他请求的就绪状态——同一个 T 在批内已有多个短请求就绪时应该更激进，在批内全是长请求时应该更保守。这就引出按批状态动态调整 T 的做法，而不是全局固定值。</p>\n<p>具体例子：一批请求的编码耗时分布在 P50 附近集中，但存在少量像素量极大的图像。固定 T 取在 P90 附近时，长尾请求被降级，批就绪时间被压到 P90 量级，P99 抖动收敛；但若这批长尾图像恰好是业务重点（如高分辨率票据识别），降级比例上升会直接反映在识别准确率上。因此 T 的最终取值必须与降级路径的质量损失一起评估，而不是只看延迟指标。</p>\n\n<h3 id=\"ap-mm-batch-starvation-sec-16\">十六 · 分辨率分桶的阈值：按像素量而非宽高比</h3>\n<p>分桶的目的是让同批编码的请求耗时接近，从而让独立批的配平收益成立。只按宽高比分桶是常见错误：同是 16:9，一个 720p 与一个 4K 的像素量差数倍，编码耗时仍会拉开，桶内方差没有被压下去。正确的分桶键是<strong>像素量区间</strong>，宽高比只作为次级键用于 kernel 形状选择。桶边界怎么定？用第一步测出的耗时分布，把耗时接近的像素量归入同一桶，使桶内 P99/P50 比值控制在一个可接受范围内。</p>\n<p>桶的数量与批大小之间存在权衡：桶太多，每个桶的请求数不足以组成有效批，视觉塔的批利用率下降，独立批反而变成小批空转；桶太少，桶内方差回升，配平失效。工程做法是先按像素量做粗分（例如按数量级分档），再在每档内部按宽高比细分，并给每个桶设一个最小批规模，低于该规模的桶与相邻桶合并。这个最小批规模本身就是一个需要测量的阈值：它取决于视觉塔在该分辨率下的单批吞吐曲线，批太小则 kernel 启动开销占比高，批太大则桶内等待时间变长。</p>\n<p>代价侧要盯的是视觉塔的批利用率与桶间等待时间。分桶后如果某个桶长期凑不满最小批，请求会在桶内排队等待合并，这段等待会计入墙钟耗时，抵消独立批带来的收益。因此分桶阈值必须与流量画像一起看：低流量时段应放宽桶边界、允许跨桶合并，高流量时段应收紧边界、让桶内方差最小。</p>\n\n<h3 id=\"ap-mm-batch-starvation-sec-17\">十七 · 批配平阈值的测量：编码耗时预估与批组成</h3>\n<p>批饥饿的根因是批级同步屏障，因此配平的目标是让批内各请求的“预计就绪时刻”接近。工程上给每个请求算一个编码耗时预估 $\\hat{t}_i$，它是像素量、图像数量、当前视觉塔队列深度的函数，用第一步的分布拟合出来。批组成时按 $\\hat{t}_i$ 排序，把预估接近的请求放进同一批，或者给批设一个就绪窗口：批内最慢请求的预估耗时与最快请求之差超过窗口阈值 W 时，把慢请求移出本批、延后处理。</p>\n<div class=\"formula\">$$\\text{starvation}(B)=\\max_{i\\in B}\\hat{t}_i-\\min_{i\\in B}\\hat{t}_i$$</div>\n<p>W 的设法是：让 $\\text{starvation}(B)$ 控制在编码耗时 P50 的一个可接受倍数内，使得批就绪时间不被单个长尾请求主导。W 太小，批组成受限、批规模下降、吞吐受损；W 太大，批饥饿回归。测量方法是扫描 W，记录 LLM 侧空转占比与批规模两条曲线，取空转占比明显下降而批规模尚未崩塌的拐点。</p>\n<p>具体例子：一批混合了缩略图与大图的请求，若不配平，缩略图请求在批内空转到最大图编码完成，SM 算力被浪费在等待上；按 $\\hat{t}_i$ 配平后，缩略图请求组成独立批先启动解码，大图请求在另一批编码，两批在时间上重叠，LLM 侧空转占比下降，P99 抖动收敛。代价是批规模变小、调度开销上升，这个开销要计入吞吐账。</p>\n\n<h3 id=\"ap-mm-batch-starvation-sec-18\">十八 · 阈值之间的耦合与上线前的测量清单</h3>\n<p>超时降级阈值 T、分桶边界、配平窗口 W 三者不是独立的。T 收紧会让长尾请求提前降级，从而降低批内方差，W 可以放宽；分桶变细会让桶内方差下降，T 也可以放宽；W 收紧会让批规模下降，桶的最小批规模阈值要相应调整。因此调参不能逐个孤立地扫，而应按“分桶 → 配平 → 超时降级”的顺序分层确定：先固定分桶使桶内方差可控，再在桶内定 W 使批组成合理，最后用 T 兜住剩余的长尾。</p>\n<p>上线前的测量清单至少包含：视觉编码墙钟耗时的分桶分布（P50/P90/P99/最大值）；LLM 侧空转占比的时间序列；降级比例与降级路径的质量损失对照；各桶的批利用率与桶间等待时间；以及在不同流量水平下上述指标的稳定性。没有这些测量，任何阈值都是猜的。工程判断是：当视觉编码 P99/P50 比值显著大于 1 且 LLM 侧空转占比可观测时，优先做分桶与配平，把 T 作为最后一道兜底而非主要手段——因为降级直接损伤输出质量，而分桶与配平只损伤吞吐，后者可以用容量规划吸收。</p>\n\n<h3 id=\"ap-mm-batch-starvation-sec-19\">十九 · 阈值不是拍脑袋：从「批就绪时刻」反推容忍窗口</h3>\n<p>超时降级阈值的物理含义必须锚定在批级同步屏障上，而不是单请求的绝对耗时。设第 <em>i</em> 个请求的视觉编码耗时为 <em>t<sub>i</sub></em>，批内共 <em>n</em> 个请求，则该批的就绪时刻为 <em>T<sub>ready</sub></em> = max<sub>i</sub>(<em>t<sub>i</sub></em>)，短请求的空转代价为 Σ<sub>i</sub>(<em>T<sub>ready</sub></em> − <em>t<sub>i</sub></em>)。降级阈值 τ 的作用是把 <em>t<sub>i</sub></em> > τ 的请求踢出快路径，于是新的就绪时刻变成 min(max<sub>i</sub>(<em>t<sub>i</sub></em>), τ) 加上降级路径自身的固定开销。这给出一个可直接测量的判据：把 τ 从当前值往下压一档，观察 P99 是否收敛、降级比例是否跳变；两个方向都单调，收敛点就是 τ 的工程取值。注意 τ 必须按「桶内」标定，全局一个 τ 在混合分辨率流量下必然失真——高像素量桶的合法长耗时会被误杀，低像素量桶的长尾反而漏网。</p>\n<div class=\"formula\">$$\\text{waste}(\\tau)=\\sum_{i}\\bigl(\\min(\\max_j t_j,\\ \\tau)-t_i\\bigr)^{+},\\qquad \\text{deg}(\\tau)=\\frac{|\\{i:t_i&gt;\\tau\\}|}{n}$$</div>\n<p>测量方法上，不要用端到端延迟反推编码耗时——它被排队、批组成和降级路径污染。正确做法是在视觉塔出口打两个时间戳（进入编码 kernel 前、编码完成同步后），按桶聚合出 <em>t</em> 的分布，重点看 P50 与 P99 的比值：比值接近 1 说明桶内配平已经到位，比值显著大于 1 说明分桶维度选错了（只按宽高比不按像素量正是典型反例，同桶内 token 数仍可能差出数倍）。这个比值同时是独立批配平收益的上界估计——比值越大，把视觉塔拆成独立批、按耗时预估重新组批的收益越大。</p>\n<p>系统代价要算清三笔账。第一笔是空转算力：批内空转的 SM 周期不产生任何 token，直接表现为 GPU 利用率下降，在解码侧尤其昂贵，因为解码是显存带宽受限而非算力受限，空转的批仍占着 KV cache 的读取带宽。第二笔是降级质量：降级比例 <em>deg</em>(τ) 是输出质量的直接代理，τ 压得过紧会让高分辨率图像走低分辨率路径，细节类问答的准确率下滑，而这类下滑在离线评测里往往被平均指标掩盖。第三笔是独立批的显存与调度开销：视觉塔独立批意味着编码阶段的激活与解码阶段的 KV cache 同时驻留，峰值显存上升，且两套调度队列之间需要显式的交接与背压，否则编码队列会无限堆积。</p>\n<p>失效条件集中在三类边界。其一，流量本身方差低（单一分辨率、单一图像类型）时，独立批与分桶的收益趋近于零，反而引入队列交接延迟，此时应退回耦合调度。其二，长尾由少数超大图主导而非分布性长尾时，τ 的统计意义消失，任何基于分位数的阈值都不稳定，应改为按像素量硬上限截断并显式拒绝，而不是降级——降级对超大图的质量损失不可接受。其三，解码侧本身已接近饱和时，视觉塔独立批释放出的算力无处可去，收益被解码瓶颈吞掉，此时优先级应转向 KV cache 与批调度，而不是继续调 τ。判断依据很直接：把 τ 调低后若 GPU 利用率不升而 P99 只降一点点，说明瓶颈已经不在同步屏障上。</p>\n<table class=\"mini\"><thead><tr><th>观测量</th><th>采集点</th><th>判读</th></tr></thead><tbody><tr><td>桶内 P99/P50 编码耗时比</td><td>视觉塔出口双时间戳</td><td>接近 1 则配平到位；显著大于 1 则分桶维度错误</td></tr><tr><td>批内空转占比</td><td>批就绪时刻减各请求编码耗时</td><td>高则同步屏障是主因，独立批收益大</td></tr><tr><td>降级比例</td><td>降级路径计数器</td><td>随 τ 单调，跳变点即质量风险点</td></tr><tr><td>利用率对 τ 的敏感度</td><td>调 τ 前后对比</td><td>不敏感说明瓶颈已转移</td></tr></tbody></table>\n<h3 id=\"ap-mm-batch-starvation-sec-20\">二十 · 坑一：把视觉编码塞进解码批的同步点</h3>\n<p>最常见的踩坑方式不是配置错误，而是架构层面的默认耦合：视觉塔的输出被当作解码批的前置条件，于是整批的启动时刻由批内最慢的那次视觉编码决定。这条路径在代码里往往表现为一个隐式的 join——调度器收集够 N 条请求就发批，但批里每条请求的视觉 token 还没就绪，于是解码 kernel 只能等所有编码 kernel 落地。木桶效应的代价直接体现在两个指标上：GPU 利用率在等待窗口内塌陷（SM 空转但显存仍被占），P99 延迟抖动随批内编码耗时的方差线性放大。</p>\n<p>检查顺序上，先看时间线而不是看平均值。取一段连续批的 trace，把每条请求的“视觉编码开始/结束”与“解码首 token”两个时刻画在同一时间轴上，若存在大量短请求的解码首 token 时刻被钉在批内最长编码结束之后，即坐实耦合。伪代码层面的判据是：</p>\n<div class=\"formula\">$$T_{\\text{batch\\_ready}} = \\max_{i \\in \\text{batch}} \\left( T^{\\text{enc}}_i \\right) + T^{\\text{decode\\_start}}$$</div>\n<p>只要这个 max 出现在视觉侧而非解码侧，配平就无从谈起。具体例子：一个批里混入一张高分辨率长图与七条纯文本短请求，七条短请求的解码槽位在编码窗口内完全闲置，等效于把批的有效算力按 1/8 打折。回滚方案不是回退代码，而是回退调度策略——把视觉编码从解码批的同步点里摘出去，改为独立批先行落地、解码批只消费已就绪的视觉 token；这一步在不动模型的前提下即可恢复利用率，属于低风险先行动作。</p>\n\n<h3 id=\"ap-mm-batch-starvation-sec-21\">二十一 · 坑二：超时降级阈值的双向失准</h3>\n<p>超时降级是这套失败模式里唯一带质量代价的旋钮，因此也是最容易设错的地方。阈值过松，长尾编码请求持续拖住批，P99 抖动无法收敛，降级形同虚设；阈值过紧，降级比例升高，低分辨率路径接管后输出质量下滑，且降级本身引入一次额外的路径切换开销。这里的工程判断是：阈值不该是一个全局常数，而应按分辨率桶分别标定，因为编码耗时的分布随像素量呈非线性变化，用同一个毫秒数卡所有桶必然在某个桶上失准。</p>\n<p>检查方法是把降级率与 P99 抖动放在同一张图上做二维观察：若降级率极低而抖动仍高，说明阈值过松，长尾未被截断；若降级率显著抬升而抖动改善有限，说明阈值过紧且降级并未命中真正的长尾，只是误伤了正常请求。代价核算要同时计入两侧：降级带来的质量损失是输出侧的，而降级路径切换带来的额外编码或重采样是延迟侧的。具体例子：同一批内一张超大图与若干中等图同桶，若阈值按中等图的耗时设定，超大图必然触发降级，但降级后仍需一次低分辨率重编码，端到端反而比原路径更慢——这说明阈值必须与桶绑定，而不是与请求绑定。</p>\n\n<h3 id=\"ap-mm-batch-starvation-sec-22\">二十二 · 坑三：分辨率分桶只按宽高比</h3>\n<p>分桶的目的是让同批编码耗时接近，从而让独立批的配平收益成立。只按宽高比切桶是典型的形式正确、实质失效：同为 16:9 的两张图，像素量可能相差数倍，编码耗时随之拉开，同桶内的方差并未被压缩，独立批只是把耦合从解码批搬到了编码批，木桶效应照旧。正确的桶键应包含像素量或等价的 token 数区间，宽高比只作为次级键用于对齐内存布局与 kernel 选择。</p>\n<p>检查顺序：对每个桶统计桶内编码耗时的分位差（如 P90 与 P10 之比），若该比值接近全局比值，说明分桶没有起到压缩方差的作用。配平判据可写成桶内方差的收敛条件：</p>\n<div class=\"formula\">$$\\frac{\\mathrm{P90}(T^{\\text{enc}} \\mid \\text{bucket})}{\\mathrm{P10}(T^{\\text{enc}} \\mid \\text{bucket})} \\ll \\frac{\\mathrm{P90}(T^{\\text{enc}})}{\\mathrm{P10}(T^{\\text{enc}})}$$</div>\n<p>代价层面，桶划分过细会让独立批的批大小下降，编码 kernel 的占用率与带宽效率受损；桶过粗则方差压不住。具体例子：把竖版长图与竖版方图并入同一“竖版桶”，前者像素量远高于后者，桶内 P90/P10 比值与全局几乎一致，独立批的收益被抵消——这正是需要在桶键里加入像素量区间的直接理由。回滚方案是把桶键退回“像素量优先、宽高比次级”，并保留旧桶配置以便对照抖动指标。</p>\n\n<h3 id=\"ap-mm-batch-starvation-sec-23\">二十三 · 坑四：把调度问题误判为容量问题</h3>\n<p>这条失败模式与显存溢出不同，是调度与同步问题而非容量问题。踩坑的典型表现是：观察到利用率低与抖动，第一反应是加卡、扩副本或调大批上限，结果抖动不变而成本上升。判别方法是看显存水位与批组成的关系——若显存充裕但批内序列长度参差、短请求长期空转，则问题在批组成而非容量。检查顺序应先做批组成分析（按编码耗时预估给请求排序，看批内极差），再决定是否动容量。</p>\n<p>配平思路是按编码耗时预估做批组成层面的排序与分组，而不是按到达顺序贪心填批。伪代码层面即：</p>\n<div class=\"formula\">$$\\text{fill}:\\ \\text{sort by } \\hat{T}^{\\text{enc}},\\ \\text{pack buckets s.t. } \\max \\hat{T}^{\\text{enc}} - \\min \\hat{T}^{\\text{enc}} \\le \\delta$$</div>\n<p>其中 δ 是允许的批内编码耗时极差，直接对应同步屏障的等待窗口。代价是排序引入的调度开销与潜在的头阻塞（长编码请求被推迟），需要在吞吐与 P99 之间取衡。具体例子：一个副本在显存水位健康的情况下 P99 抖动明显，扩容后抖动未改善，而按耗时预估重排批组成后等待窗口收窄——这证明加容量对该失败模式无效。回滚方案是保留原贪心填批路径作为开关，一旦排序策略在特定流量形态下导致头阻塞恶化，可即时切回并仅保留分桶收益。</p>\n\n<h3 id=\"ap-mm-batch-starvation-sec-24\">二十四 · 检查清单与回滚顺序</h3>\n<p>把上述坑收敛成一份可执行的检查顺序，按“先证伪耦合、再校阈值、后验分桶、末判容量”的次序推进，避免在错误层面反复调参。</p>\n<ul>\n<li>时间线取证：短请求解码首 token 是否被钉在批内最长编码之后；若是，先做编码与解码的解耦调度。</li>\n<li>降级率与抖动二维对照：降级率低而抖动高判阈值过松；降级率高而抖动改善有限判阈值过紧且误伤。</li>\n<li>桶内方差比：逐桶计算编码耗时 P90/P10，与全局比值对照，确认分桶是否真正压缩方差。</li>\n<li>批组成极差：按编码耗时预估统计批内极差，判断是否需要排序配平而非扩容。</li>\n<li>容量证伪：显存水位健康而抖动持续，则排除容量假设，回到批组成层面。</li>\n</ul>\n<p>回滚顺序应与风险等级对齐：解耦调度是可逆的调度开关，优先执行且可即时回退；阈值调整影响输出质量，回滚时需同时恢复旧阈值与旧降级路径；分桶键变更影响内存布局与 kernel 选择，回滚需保留旧桶配置做指标对照；批组成排序策略的回滚以保留贪心填批开关为准。每一步回滚都应绑定一个可观测指标（利用率、P99 抖动、降级率、桶内方差比），否则回滚本身无法判定是否奏效。</p>\n<p>最后落在机制上：这套失败模式的修复不靠单点调参，而靠把同步屏障从“批级 max”改成“桶级 max + 超时截断”，让等待窗口有上界。工程判断是——只要批内编码耗时极差 δ 未被显式约束，任何容量或框架层面的优化都只是在放大木桶的最短板。</p>\n\n<h3 id=\"ap-mm-batch-starvation-sec-25\">二十五 · 阈值失准与分桶失配：补写清单里最容易漏掉的两类回滚触发点</h3>\n<p>前文把视觉塔独立批、分辨率分桶与超时降级当作三条并列缓解手段，但工程上真正决定这套方案能否长期驻留的，是它们的失效条件与回滚判据。超时降级阈值是唯一一个同时牵动延迟与质量的旋钮：设得过松，长尾编码请求持续占住视觉塔的批槽位，解码侧虽然已经解耦，但下游等待该请求的会话仍被拖住，P99 抖动无法收敛；设得过紧，降级比例抬升，低分辨率路径接管后输出质量下滑，且降级请求本身仍要占用一次编码与一次重排。可用的判据不是拍脑袋的固定毫秒数，而是把阈值锚定在分桶后的编码耗时分布上：设第 $b$ 桶的编码耗时中位数为 $m_b$、$p$ 分位数为 $q_b$，则阈值取 $\\tau_b = \\alpha \\cdot q_b$（$\\alpha$ 略大于 1），并要求降级率 $r_b = P(t &gt; \\tau_b)$ 落在可接受带内。检查顺序上先看 $r_b$ 再看 P99：降级率是先行指标，P99 是滞后指标，等 P99 恶化再调阈值已经晚了一个观测窗口。</p>\n<p>分辨率分桶的经典坑是只按宽高比切桶、不按像素量切桶。同为 16:9 的两张图，像素量差一个数量级，视觉塔内的 token 数与注意力代价随之拉开，同桶内编码耗时方差依旧很大，独立批的配平收益被直接抵消。分桶键应当是像素量区间与宽高比的双维组合，并在桶内再按 token 数排序做贪心配平。代价体现在显存与带宽两侧：桶越细，单桶可成批的样本越少，视觉塔的批利用率下降，权重与激活的重复加载比例上升；桶越粗，桶内方差回归。一个可操作的检查项是监控每个桶的批内编码耗时极差与桶间负载偏斜，若某桶长期只有一两个样本成批，说明该桶该合并或改走降级路径。表格给出回滚判据的最小集合：</p>\n<table class=\"mini\"><thead><tr><th>观测项</th><th>恶化信号</th><th>回滚动作</th></tr></thead><tbody><tr><td>桶内编码耗时极差</td><td>持续接近桶中位数量级</td><td>合并该桶或改按像素量重切</td></tr><tr><td>降级率 $r_b$</td><td>越出可接受带上限</td><td>放宽 $\\tau_b$，先保质量</td></tr><tr><td>视觉塔批利用率</td><td>低于独立批前的水平</td><td>退回耦合调度，保留分桶</td></tr><tr><td>解码侧 P99 抖动</td><td>未随解耦收敛</td><td>检查是否仍有同步屏障残留</td></tr></tbody></table>\n<p>回滚方案必须按“先退最贵的一层”排序，而不是整体关掉。第一层退超时降级，因为它对输出质量的影响最直接且最难事后补偿；第二层退分桶粒度，把细桶并回粗桶，牺牲配平收益换批利用率；第三层才退视觉塔独立批，回到编码与解码共用同步点的耦合调度。这个顺序的系统代价很清楚：独立批带来的是调度器复杂度与跨塔队列的显存驻留，分桶带来的是批利用率损失，降级带来的是质量方差，三者中前两者的代价可观测、可回收，降级的质量损失一旦发生就写进了输出。检查清单还应包含一个常被忽略的边界条件：当请求流中短文本配大图的组合占比升高时，解码侧批内序列长度参差会重新放大，此时即便视觉塔已独立，LLM 侧的连续批处理仍需按预估解码长度配平，否则批饥饿只是从编码阶段搬到了解码阶段。最后一条工程判断是：这套方案的收益上限由请求流的编码耗时分布决定，若分布本身接近单峰，独立批与分桶的边际收益不足以覆盖调度复杂度，应直接保留耦合调度并把预算投到别处。</p>\n<h3 id=\"ap-mm-batch-starvation-sec-26\">二十六 · 上游依赖：视觉编码方差从哪来，本条目接谁的账</h3>\n<p>多模态批饥饿不是孤立现象，它是若干上游条目失效后在调度层的显影。视觉编码器术语表定义的那批结构选择——patch 划分、位置编码插值方式、窗口注意力与全局注意力的配比——决定了单张图像的编码 FLOPs 随分辨率如何增长；视觉 token 压缩术语与压缩工具则决定了压缩后序列还能保留多少空间冗余。这两者共同塑造了编码耗时的分布形状：压缩比越高、token 越少，编码阶段的绝对耗时下降，但不同图像之间的相对方差未必收敛，因为高信息密度图像在压缩后仍需要更多迭代或更重的注意力计算。</p>\n<p>图像视频预处理工具链是方差的第一道放大器。解码、缩放、色彩空间转换、归一化若在 CPU 侧串行完成，进入视觉塔的张量到达时刻本身就不齐；视频抽帧与批配方进一步把这种不齐放大到帧级——同一请求内抽出的帧数不同、关键帧与均匀采样混用，会让单个请求的视觉工作量在进入调度器前就已不可比。多模态量化配方则改变编码器的算力—精度曲线：视觉塔用 FP8 还是 NVFP4，直接影响 tcgen05 MMA 的吞吐与 TMEM 占用，从而改变单张图像的编码时延基线。基线越低，长尾的相对抖动越刺眼。</p>\n<p>把这些上游量收拢成一个可调度的预估量，是本条目对上游提出的唯一硬要求：调度器需要在请求入队时拿到一个编码耗时预估值，而不是等视觉塔跑完再知道。工程上可行的做法是用分辨率分桶的桶号加预处理元数据（帧数、是否含 OCR 密集区域）查表得到分位估计，形如</p>\n<div class=\"formula\">$$\\hat{t}_{enc}=f(\\text{bucket},\\ n_{frame},\\ \\text{density})\\ \\Rightarrow\\ \\text{priority}=\\frac{\\hat{t}_{enc}}{\\text{SLO}_{remain}}$$</div>\n<p>其中 density 可由预处理阶段的边缘密度或文本区域占比近似。代价是调度器多了一次查表与优先级重排，CPU 侧开销在微秒级，相对于视觉编码的毫秒到百毫秒级可忽略；但如果预处理工具链不输出这些元数据，整个预估链路就断了，批饥饿只能靠事后观测发现。</p>\n\n<h3 id=\"ap-mm-batch-starvation-sec-27\">二十七 · 下游影响：批饥饿如何污染 KV cache、分离式部署与 SLO 容量规划</h3>\n<p>批饥饿的直接受害者是 LLM 侧的连续批处理。短请求在批内空转时，其 KV cache 已经被分配并占据显存分页，却迟迟不产生有效解码步。显存与 KV cache 条目关心的分页利用率在这里被拉低：分页被占住、token 不增长，等效于把 HBM 容量换成了等待时间。更糟的是，若调度器为了填满批而持续接纳新请求，KV cache 的分配压力会在长尾编码未完成时提前上升，形成“容量看似够、有效吞吐不够”的假象——这正是本条目与视觉塔显存溢出必须分开处理的原因：后者是容量问题，前者是同步问题。</p>\n<p>对多模态分离式预填配方而言，批饥饿是解耦不到位的症状。分离式部署把预填与解码放到不同实例，本意就是切断编码方差向解码批的传导；但只要视觉塔与 LLM 预填仍在同一调度单元内共享同步点，解耦就只解了一半。判定标准很直接：视觉塔独立批之后，解码实例的批组成应当只由解码侧的就绪请求决定，而不是由最慢的图像编码决定。若观测到解码实例的批启动时刻与视觉塔的长尾完成时刻强相关，说明同步屏障仍在。</p>\n<p>多模态推理框架层面，vLLM 与 SGLang 的调度器需要把视觉编码建模为独立的可抢占阶段，TensorRT-LLM 则要在引擎切分时给视觉塔单独的 execution context；Dynamo 一类编排层负责把超时降级策略下发到路由。这些改动都会改变容量规划的口径：SLO 与容量规划不能再按“平均编码耗时 × 请求数”估算视觉塔算力，而必须按高分位耗时与降级比例联合估算。超时降级阈值设得过松，长尾持续拖批，P99 抖动不收敛；设得过紧，降级比例上升，低分辨率路径的输出质量下降，等效于把延迟问题换成了质量问题。容量规划因此需要一条显式的降级预算：</p>\n<div class=\"formula\">$$C_{vision}\\ \\ge\\ \\frac{N\\cdot \\bar{t}_{enc}}{(1-p_{deg})\\cdot U_{target}},\\qquad p_{deg}=P(\\hat{t}_{enc}&gt;T_{timeout})$$</div>\n<p>其中 p_deg 是降级比例，由编码耗时分布与阈值共同决定。这条式子把超时阈值从“运维旋钮”变成“容量输入”，是本条目对下游容量规划最实质的贡献。</p>\n\n<h3 id=\"ap-mm-batch-starvation-sec-28\">二十八 · 与相邻条目的边界：哪些问题不归这里管</h3>\n<p>跨模态注意力术语处理的是编码完成之后、视觉 token 如何进入 LLM 注意力的问题；批饥饿发生在 token 尚未产生之前，二者时间上不重叠。视觉 token 压缩工具降低的是进入 LLM 的序列长度，从而缓解解码侧压力，但它不改变编码阶段的方差，因此不能替代视觉塔独立批。多模态上线前清单里的检查项与本条目的关系是验收关系：清单负责确认独立批、分桶、降级三条链路是否真的生效，本条目负责解释为什么这三条链路缺一不可。</p>\n<p>分辨率分桶的失效模式值得单独点出，因为它常被误认为已经解决了问题。只按宽高比分桶时，同桶内像素量仍可能相差数倍，编码耗时差异依旧显著，独立批的配平收益被抵消。正确做法是按像素量或 token 数分桶，并在桶内再做耗时预估排序。代价是桶数量上升带来的调度开销与批利用率下降之间的权衡：桶太细，每桶凑不满批，视觉塔的 MMA 效率下降；桶太粗，方差回归。工程判断是以视觉塔单批的最小有效规模为下界反推桶粒度，而不是先定桶再谈利用率。</p>\n\n<h3 id=\"ap-mm-batch-starvation-sec-29\">二十九 · 在全书中的位置：调度层的“方差治理”节点</h3>\n<p>把全书条目按数据流排布，本条目处在视觉预处理与 LLM 解码之间的接缝上，属于调度与同步类问题，与算子精度、显存容量两条线正交。它向上承接预处理与量化给出的耗时分布，向下把预估量交给批调度、分离式部署与容量规划。它的方法论价值在于示范了一类通用模式：当一条流水线的阶段方差远大于均值时，耦合调度必然产生木桶效应，解法是把高方差阶段拆成独立批、按同类归并、并对长尾设降级出口。这一模式同样适用于工具调用密集的 agent 推理与长上下文预填，因此本条目在全书里不只是多模态专有问题的注脚，而是方差治理的一个可复用范式。</p>\n<p>工程判断落在最后一步：批饥饿的修复不能只看 GPU 利用率曲线，因为利用率低既可能是批饥饿，也可能是视觉塔本身算力不足。区分方法是看批启动时刻与最长编码完成时刻的相关性，以及短请求在批内的实际空转步数。若相关性高且空转步数随分桶粒度变粗而上升，则是调度问题；若相关性低而视觉塔自身已打满，则是容量问题，应回到视觉塔显存与算力条目。这条判据决定了后续所有优化投入的方向。</p>\n\n<h3 id=\"ap-mm-batch-starvation-sec-30\">三十 · 边界条件：何时这套配平逻辑会失效</h3>\n<p>多模态批饥饿的缓解手段——视觉塔独立批、分辨率分桶、超时降级——并非无条件成立。它们的有效性建立在三个前提上：视觉编码耗时可预估、桶内方差可收敛、降级路径质量可接受。任一前提被打破，配平收益迅速归零。最典型的失效条件是<strong>编码耗时不可预估</strong>：当视觉塔输入来自动态分辨率、任意裁剪或变长视频帧时，单张图像的编码时间由像素量与内容复杂度共同决定，仅按宽高比分桶会把像素量相差数倍的图像塞进同一桶，桶内编码耗时方差依旧很大，独立批的配平被抵消。此时系统退化为“分桶但不均衡”，批级同步屏障仍在，只是屏障从LLM侧挪到了视觉侧。工程判断是：分桶键必须包含像素量或等效token数，而非仅宽高比；若无法在入队时获得可靠像素量（如流式图像解码未完成），则独立批方案不适用，应回到耦合调度并接受方差。</p>\n<p>第二个失效条件是<strong>超时降级阈值不可调</strong>。阈值过松，长尾编码请求持续拖住批，P99抖动无法收敛；阈值过紧，降级比例过高，输出质量受损。设批内第i个请求的编码耗时为 $t_i$，批就绪时刻为 $\\max_i t_i$，短请求空转时间为 $\\max_i t_i - t_i$。降级策略本质是用质量换同步：将超过阈值 $\\tau$ 的请求切换到低分辨率路径，使 $\\max_i t_i$ 被截断在 $\\tau$ 附近。但 $\\tau$ 的选取依赖编码耗时分布的上尾，而该分布在分辨率分桶不充分时本身不稳定，导致 $\\tau$ 无法静态设定。代价体现在两个方向：延迟侧，$\\tau$ 过大则P99抖动不收敛；吞吐侧，$\\tau$ 过小则降级请求占用额外低分辨率编码算力，且降级后的输出可能触发下游重试，反而增加总工作量。这是一个调度代价而非容量代价——显存并未溢出，但GPU利用率因空转与重试而下降。</p>\n<p>第三个边界是<strong>与显存溢出类失败模式的区分</strong>。批饥饿是调度与同步问题，KV cache与权重显存可能充裕，GPU却因批内木桶效应空转；显存溢出则是容量问题，需靠分页KV、前缀复用或降批解决。两者在监控上表现不同：批饥饿表现为SM利用率低而显存占用平稳，显存溢出表现为OOM或强制换出导致的延迟尖峰。混淆二者会导致错误的容量规划——把调度问题当容量问题加卡，利用率不升反降。因此本方案在全书中的位置是“批组成层”的配平手段，上游依赖视觉编码耗时预估与分辨率分桶的入队元数据，下游影响连续批处理的批组成策略与SLO容量规划中的P99预算分配。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>机制</th><th>系统代价</th></tr></thead><tbody><tr><td>分桶仅按宽高比</td><td>桶内像素量方差大，编码耗时不可预估</td><td>独立批配平收益抵消，屏障仍在</td></tr><tr><td>降级阈值过松</td><td>长尾编码拖住批就绪时刻</td><td>P99抖动不收敛，短请求空转</td></tr><tr><td>降级阈值过紧</td><td>降级比例高，低分辨率路径算力占用</td><td>输出质量下降，下游重试增加总工作量</td></tr><tr><td>误判为容量问题</td><td>加卡不改变批级同步屏障</td><td>GPU利用率不升，显存冗余浪费</td></tr></tbody></table>\n<p>在全书结构中，本条目属于批调度与连续批处理模块的边界分析层：它不重复视觉塔独立批的实现细节（那是上游条目的主题），也不展开超时降级的具体阈值调优（属于SLO与容量规划条目），而是界定“配平何时有效、何时应放弃”。对工程读者的判断是：先确认入队元数据能否给出可靠像素量，再决定是否启用分桶独立批；若不能，则接受耦合调度下的方差，把优化预算投向降级路径的质量补偿而非批组成配平。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-mm-batch-starvation\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>视觉编码耗时差异大导致LLM侧批内序列长度参差，短请求等待长图像编码完成而空转</td></tr><tr><td>关键点</td><td>表现为GPU利用率低与P99延迟抖动，需视觉塔独立批、分辨率分桶与超时降级策略。</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-mm-batch-starvation · 共 5 个片段</p>\n"},{"id":"ap-mm-launch-checklist","title":"多模态上线前清单","summary":"核对视觉塔与LLM精度一致性、图像embedding缓存命中率、分辨率分桶覆盖、批内异构序列掩码正确性、FP8校准集代表性、分离式部署带宽余量、SLO尾延迟与降级路径，逐项留证后方可放量。","kind":"清单","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-1\">一 · 条目是什么：一份带证据链的放量门禁</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-2\">二 · 分类维度：六组检查对象与三种正交切法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-3\">三 · 与相邻概念的区别：清单条目不是术语表条目</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-4\">四 · 速查表的列结构与证据可追溯性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-5\">五 · 两个高频踩坑对应的条目定义缺口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-6\">六 · 数值未给出时的清单纪律</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-7\">七 · 表结构与留证口径：七列如何闭合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-8\">八 · 精度一致性类：视觉塔与 LLM 的数值对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-9\">九 · 缓存与分桶类：命中率与覆盖率的双口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-10\">十 · 批调度正确性类：异构序列掩码逐位比对</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-11\">十一 · 量化类：FP8 校准集代表性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-12\">十二 · 部署资源与服务类：带宽余量与尾延迟降级</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-13\">十三 · 速查表之外：门禁失效的边界条件与留证代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-14\">十四 · 阈值不是常数：把判定标准锚在业务分布上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-15\">十五 · 精度一致性：逐位比对而不是看 loss 曲线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-16\">十六 · 缓存命中率与掩码正确性：两个必须分开测的量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-17\">十七 · FP8 校准集代表性：用分布距离量化，而不是凭感觉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-18\">十八 · 分离式部署带宽余量：测尾延迟而不是测平均</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-19\">十九 · SLO 尾延迟与降级路径：把触发条件写成可执行的门禁</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-20\">二十 · 精度一致性：最贵的一类静默失败</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-21\">二十一 · 缓存与分桶：命中率与覆盖率要分开取证</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-22\">二十二 · 掩码正确性：同构批跑通不算通过</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-23\">二十三 · FP8 校准集：代表性比数值本身更重要</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-24\">二十四 · 分离式部署：平均带宽是伪证据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-25\">二十五 · 检查顺序与回滚：门禁要能倒着走</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-26\">二十六 · 放量门禁的失效边界：清单在什么条件下会漏判</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-27\">二十七 · 上游依赖：清单的七项检查分别锚定哪些条目</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-28\">二十八 · 下游影响：清单结论如何改变放量策略与容量规划</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-29\">二十九 · 横向关系：与同类条目共享证据但角度不同</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-30\">三十 · 在全书中的位置：从算子到放量的最后一环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-31\">三十一 · 依赖闭环：清单自身作为其他条目的输入</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-launch-checklist-sec-32\">三十二 · 清单条目之间的依赖链与失效边界</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-mm-launch-checklist\"><svg style=\"max-width:515px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 514.7 319\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"432.7\" height=\"83.0\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"53.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"57.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：多模态上线前清单</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">核对视觉塔与LLM精度一致性、图像embedding缓存命中率、分辨率分</text><text x=\"75.0\" y=\"78.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">桶覆盖…</text><line x1=\"82.0\" y1=\"97.0\" x2=\"82.0\" y2=\"114.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 113.0 L 86.5 113.0 L 82.0 121.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"121.0\" width=\"432.7\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"143.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"147.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"148.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><line x1=\"82.0\" y1=\"167.9\" x2=\"82.0\" y2=\"184.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 183.9 L 86.5 183.9 L 82.0 191.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"191.9\" width=\"432.7\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"214.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"218.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"219.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"238.7\" x2=\"82.0\" y2=\"255.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 254.8 L 86.5 254.8 L 82.0 262.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"262.8\" width=\"432.7\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"285.2\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"289.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"290.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-mm-launch-checklist-sec-1\">一 · 条目是什么：一份带证据链的放量门禁</h3>\n<p>多模态上线前清单不是“检查一下模型能不能跑”的验收脚本，而是一份<strong>逐项留证的放量前核对表</strong>。它的判定对象是七类检查项：视觉塔与LLM精度一致性、图像embedding缓存命中率、分辨率分桶覆盖、批内异构序列掩码正确性、FP8校准集代表性、分离式部署带宽余量、SLO尾延迟与降级路径。每一项都必须产出一条可追溯的证据记录，才允许放量。这里的“证据”有严格含义：不是“我测过了”，而是速查表中那一行能指向具体日志、比对脚本输出或分布直方图文件。</p>\n<p>把它与相邻概念切开，是理解本条目成本结构的前提。它与<strong>性能基准</strong>的区别在于：基准回答“快不快”，清单回答“对不对、稳不稳、能不能放”。基准可以只跑一条最优路径，清单必须覆盖失败路径——尤其是降级路径是否被预演过。它与<strong>回归测试套件</strong>的区别在于：回归测试是持续跑的自动化断言，清单是放量闸门上的一次性签核，带责任人、复核状态与门禁结论三列。它与<strong>可观测性看板</strong>的区别在于：看板是上线后的连续信号，清单是上线前的离散证据快照；看板发现漂移，清单证明放量那一刻没有已知漂移。三者不互相替代，清单的独特价值是把“已知风险”在放量前钉死成文件。</p>\n<p>工程代价直接体现在流程延迟上：七类检查项各自需要独立的测量窗口，精度一致性要跑逐位比对，缓存命中率要回放真实请求分布，带宽余量要在突发批下取尾部分位数。清单因此把放量从“一次部署”变成“一次带证据的签核”，其吞吐代价不在GPU上，而在发布流水线的时间预算上——这也是为什么清单必须做成速查表而不是散文式报告。</p>\n\n<h3 id=\"ap-mm-launch-checklist-sec-2\">二 · 分类维度：六组检查对象与三种正交切法</h3>\n<p>给定分类维度是按检查对象分成六组：精度一致性类（视觉塔与LLM数值对齐）、缓存与分桶类（embedding缓存命中率、分辨率分桶覆盖）、批调度正确性类（异构序列掩码）、量化类（FP8校准集代表性）、部署资源类（分离式带宽余量）、服务类（尾延迟与降级路径）。六组不是并列的六个抽屉，而是按“失效发生在哪一层”排列：数值层、数据层、调度层、量化层、传输层、服务层。失效越靠下，越难在上线后被定位，因此清单的证据强度要求也应随层加深而提高。</p>\n<p>除给定维度外，还有三种正交切法可用于给条目排优先级。其一是<strong>按可观测性</strong>：精度一致性与掩码正确性属于“静默失效”——不报错、不崩溃，只表现为输出质量漂移或跨样本串扰，必须靠逐位比对脚本抓；带宽余量与尾延迟属于“显性失效”，会在监控上冒头但往往已经影响SLO。其二是<strong>按证据形态</strong>：分布类证据（缓存命中率、分桶覆盖、FP8校准集覆盖）是直方图与覆盖率比例，比对类证据（精度一致性、掩码）是逐位通过率，时序类证据（带宽余量、尾延迟）是分位数曲线。其三是<strong>按责任归属</strong>：精度与量化归模型侧，缓存分桶与掩码归推理引擎侧，带宽与SLO归部署与服务侧——速查表的“责任人”列正是按这条线切的。</p>\n<p>用伪代码表达分类到门禁的映射关系：</p>\n<div class=\"formula\">$$\\text{gate} = \\bigwedge_{i \\in \\{1..7\\}} \\big( \\text{evidence}_i \\neq \\varnothing \\;\\wedge\\; \\text{review}_i = \\text{pass} \\big)$$</div>\n<p>即门禁是七项证据非空与复核通过的逻辑与。任何一项证据缺失，门禁即为假——清单不允许“其他都过了所以放行”的加权妥协。代价是：七项中只要有一项的证据采集需要重跑长尾分布回放，整条发布流水线就被这一项卡住，这就是清单在工程上的关键路径属性。</p>\n\n<h3 id=\"ap-mm-launch-checklist-sec-3\">三 · 与相邻概念的区别：清单条目不是术语表条目</h3>\n<p>本套书其他片段讲的是概念本身——视觉编码器术语表定义什么是视觉塔，视觉token压缩术语定义压缩比与信息损失，跨模态注意力术语定义融合方式。清单条目与它们的区别在于<strong>判据方向相反</strong>：术语表回答“这个概念是什么”，清单条目回答“这个概念的实现是否达到了放量条件，证据在哪”。例如“视觉塔与LLM精度一致性”这一条，不是解释FP16与BF16/FP8的数值格式差异，而是要求产出一份视觉塔输出经投影后与LLM输入embedding的逐位或逐元素比对记录；术语是背景，证据是交付物。</p>\n<p>与工具链类条目的区别同理：图像视频预处理工具链讲的是抽帧、缩放、归一化的实现，分辨率分桶覆盖这一条讲的不是分桶算法，而是<strong>分桶集合对真实业务分辨率分布的覆盖比例</strong>以及未覆盖分辨率落入哪个兜底桶的证据。工具是手段，覆盖率是判据。与配方类条目（多模态量化配方、视频抽帧与批配方）的区别在于：配方给出“怎么做”，清单条目给出“做完之后拿什么证明它没坏”——FP8校准集代表性这一条不重复量化配方里的scale计算，只追问校准集的分布是否覆盖了长尾分辨率与低照度图像，并把覆盖比例写进判定标准列。</p>\n<p>最容易混淆的是清单与批调度类条目。多模态批调度术语讲连续批处理与批内序列组织，而“批内异构序列掩码正确性”这一条是调度层的<strong>正确性断言</strong>：不同图像token数的样本拼批后，视觉token与文本token的位置偏移必须逐位比对通过。这里的关键区别是测试批的构造——只用同构批（所有样本图像token数相同）跑通不构成证据，因为位置偏移在同构批下天然对齐，缺陷被掩盖。清单要求证据文件里明确记录异构批的构造参数与逐位比对脚本输出。</p>\n\n<h3 id=\"ap-mm-launch-checklist-sec-4\">四 · 速查表的列结构与证据可追溯性</h3>\n<p>速查表应包含七列：检查项名称、判定标准、实测值、证据文件路径、责任人、复核状态、放量门禁结论。这七列的设计意图是把“结论”与“依据”强制分离：判定标准列必须写明阈值来源，例如校准集分布覆盖比例、掩码逐位比对通过率；证据列必须可追溯到具体日志或比对脚本输出。没有阈值来源的判定标准是无效的——它无法被复核人独立重算。</p>\n<table class=\"mini\"><thead><tr><th>列</th><th>填写要求</th><th>常见缺陷</th></tr></thead><tbody><tr><td>检查项名称</td><td>与七类检查项一一对应，不合并</td><td>把精度一致性与量化合并成一行，证据互相顶替</td></tr><tr><td>判定标准</td><td>写明阈值来源（覆盖比例、逐位通过率）</td><td>只写“符合预期”，无法复核</td></tr><tr><td>实测值</td><td>与判定标准同量纲</td><td>用平均值代替分位数</td></tr><tr><td>证据文件路径</td><td>指向日志或比对脚本输出</td><td>指向聊天记录或口头结论</td></tr><tr><td>责任人 / 复核状态</td><td>采集人与复核人分离</td><td>同一人自采自核</td></tr><tr><td>门禁结论</td><td>七项全过后统一签署</td><td>逐项放行，绕过整闸</td></tr></tbody></table>\n<p>证据可追溯性的工程代价是存储与检索：七类证据中分布类证据是直方图文件，比对类证据是逐位比对脚本的完整输出，时序类证据是分位数曲线采样。这些文件必须与发布版本号绑定，否则复核时无法确认证据对应的是哪一版权重与哪一版预处理参数。一个具体例子：掩码正确性证据若只记录了“通过”，而没有记录异构批的样本构成（各样本图像token数列表）与比对脚本版本，那么复核人无法判断这次通过是否覆盖了长图像token与短文本token混合的极端拼批形态，证据在形式上存在、在实质上失效。</p>\n\n<h3 id=\"ap-mm-launch-checklist-sec-5\">五 · 两个高频踩坑对应的条目定义缺口</h3>\n<p>最常见踩坑之一是只核对视觉塔输出精度而忽略其与LLM输入embedding的数值一致性。这条踩坑暴露的是条目定义的精度：<strong>精度一致性类的判定对象不是视觉塔单独的输出，而是视觉塔输出经投影层进入LLM输入端的那个张量</strong>。视觉侧用FP16、LLM侧用BF16或FP8时，混用会在投影与类型转换处产生静默漂移——不报错，只表现为生成质量缓慢劣化。因此该条目的证据必须是端到端比对：同一输入图像，分别取视觉塔原始输出与LLM实际消费的embedding，逐元素比对并记录最大偏差与分布。代价在于这条证据需要打通两侧的中间张量导出，推理引擎必须支持在投影层前后各打一个探针，这本身是对框架可观测性的一次改造。</p>\n<p>第二个踩坑是掩码正确性仅用同构批测试。异构序列拼批后位置偏移未被发现，上线后表现为跨样本注意力串扰——一个样本的视觉token被另一个样本的注意力读到。这条踩坑对应条目定义中的“异构”二字必须落到证据里：证据文件应包含异构批的构造清单、每个样本的视觉token数与文本token数、以及逐位比对脚本对位置索引的校验输出。工程代价是测试批的构造成本：要覆盖极端形态（长图像token配短文本、短图像token配长文本、多图样本混排），测试用例数随形态组合增长，清单要求的是覆盖关键形态而非穷举，但关键形态的选择本身要写进判定标准的阈值来源里。</p>\n\n<h3 id=\"ap-mm-launch-checklist-sec-6\">六 · 数值未给出时的清单纪律</h3>\n<p>材料未给出具体数值阈值：缓存命中率、分桶覆盖率、FP8校准集覆盖比例均需按业务分布设定，清单要求逐项留证而非给出统一数字。这不是清单的缺陷，而是清单的定义特征——<strong>阈值来源必须随业务分布走，清单只强制“来源被写明”与“证据被留下”</strong>。因此速查表的判定标准列写的不是“命中率≥X%”，而是“命中率阈值来源：近N天真实请求分布回放所得的分位数，见证据文件”。这样复核人不需要相信一个拍脑袋的数字，而是可以重跑回放验证阈值本身的合理性。</p>\n<p>这条纪律直接决定放量门禁的形态：门禁结论不是“七项都达标”，而是“七项均有证据且阈值来源可复核”。对于分离式部署带宽余量这一条，材料明确指出只测平均带宽不测尾延迟是失败模式——突发批下视觉embedding传输排队使SLO尾延迟超标且降级路径未预演。因此该条目的证据必须是尾部分位数而非均值，且降级路径要有预演记录。代价是测量窗口变长：尾延迟证据需要覆盖突发批形态，测量时长与突发注入次数直接转化为发布流水线的时间成本。清单在这里的工程判断是：宁可让门禁多等一个测量窗口，也不让一条只有均值的证据混进速查表——因为均值证据在复核时无法区分“稳态健康”与“尾部已崩”。</p>\n<h3 id=\"ap-mm-launch-checklist-sec-7\">七 · 表结构与留证口径：七列如何闭合</h3>\n<p>速查表不是给人“看一眼”的，而是给门禁用的。每一行必须能独立回答一个问题：这项检查凭什么判定通过？因此表列固定为七列——检查项名称、判定标准、实测值、证据文件路径、责任人、复核状态、放量门禁结论。七列中真正决定成败的是第三与第四列：判定标准必须写明阈值来源，实测值必须与证据文件一一对应。没有来源的阈值等于拍脑袋，没有路径的实测值等于口说无凭。</p>\n<p>留证口径要统一到“可重跑”这一层。判定标准列写成可执行表达式，例如“掩码逐位比对通过率 = 100%”“缓存命中率 ≥ 业务分布下设定值（来源：流量采样窗口的分布统计脚本输出）”。实测值列只填数字或布尔，不填形容词。证据文件路径列指向具体产物：比对脚本 stdout、日志切片、分布直方图导出文件、带宽压测的尾延迟分位表。责任人列落到人而非团队，复核状态列只允许“未复核/已复核/复核不通过”三态，门禁结论列只允许“放行/阻塞”两态——中间态会让人误以为“差不多可以上”。</p>\n<p>代价在这里体现为流程延迟而非算力：每项证据的生成都要跑一次针对性压测或比对，七项串行跑完会把放量窗口往后推。工程做法是把证据生成脚本与常规回归流水线绑定，让证据在每次候选版本构建时自动落盘，门禁只做读取与判定，把人工从“造证据”挪到“审证据”。一个具体例子：把掩码比对脚本挂进 CI，每次改动批调度代码就自动对异构批跑一遍逐位比对，输出落到固定路径，复核人只需看通过率是否为 100%。</p>\n\n<h3 id=\"ap-mm-launch-checklist-sec-8\">八 · 精度一致性类：视觉塔与 LLM 的数值对齐</h3>\n<p>这一项的判定标准不是“视觉塔输出误差小于某值”，而是“视觉塔输出经投影后与 LLM 输入 embedding 的数值一致性”。机制上要做的是端到端对齐：固定同一批图像，分别取视觉塔输出、投影层输出、LLM 第一层实际收到的 embedding，三者逐元素比对。因为视觉侧常以 FP16 计算，而 LLM 侧可能是 BF16 或 FP8，混用时的舍入路径不同，误差会在投影与类型转换处累积，表现为静默漂移——单看视觉塔精度是合格的，接到 LLM 上分布已经偏了。</p>\n<div class=\"formula\">$$\\delta = \\frac{\\lVert \\mathbf{e}_{\\text{llm}} - \\mathbf{e}_{\\text{ref}} \\rVert_2}{\\lVert \\mathbf{e}_{\\text{ref}} \\rVert_2},\\quad \\text{门禁要求 } \\delta \\le \\delta_{\\max}\\ \\text{且逐元素最大绝对差有界}$$</div>\n<p>公式里参考向量应取高精度路径（如 FP32 投影）的输出，实测向量取线上实际路径的输出。阈值来源必须写清：δ_max 由业务侧对下游任务指标的容忍度反推，而不是抄一个通用数字。代价是显存与带宽——保留高精度参考路径意味着比对时要多驻留一份 embedding，长序列下这份副本会挤占 KV cache 的空间；工程上通常只在离线比对阶段开高精度路径，线上不保留。例子：某次候选版本视觉塔用 FP16、LLM 用 FP8，视觉塔单测误差合格，但端到端 δ 在低照度图像上明显放大，正是这一项拦下来的。</p>\n\n<h3 id=\"ap-mm-launch-checklist-sec-9\">九 · 缓存与分桶类：命中率与覆盖率的双口径</h3>\n<p>图像 embedding 缓存命中率与分辨率分桶覆盖率必须分开统计，混在一起会掩盖问题。命中率的机制是键的设计：键要包含图像内容指纹、预处理参数、视觉塔版本号三者，任一变化即失效。只按图像指纹做键，视觉塔升级后仍命中旧 embedding，属于最隐蔽的一类错误。命中率的判定标准要写明统计窗口与分母口径——分母是请求数还是去重后的图像数，两者差异很大，重复图多的业务里按请求数算会虚高。</p>\n<p>分桶覆盖率的机制是把输入分辨率按桶归档，统计线上流量落在各桶的比例，再与分桶表比对。判定标准写成“线上流量覆盖的桶集合 ⊇ 分桶表声明的桶集合，且各桶样本量满足统计下限”。代价在显存：桶越多，每个桶的编译形态与中间缓冲越多，视觉塔的 workspace 占用上升；桶太少则跨桶填充浪费算力。例子：业务里竖屏短视频占比高，分桶表却按横屏方图设计，覆盖率检查直接暴露了长尾分辨率无桶可落、被迫走填充路径的问题。</p>\n<table class=\"mini\"><thead><tr><th>检查项</th><th>判定标准（阈值来源）</th><th>实测值口径</th><th>证据形态</th></tr></thead><tbody><tr><td>embedding 缓存命中率</td><td>≥ 业务分布设定值，来源为流量采样窗口统计</td><td>命中请求数 / 总请求数，并附去重口径</td><td>缓存日志切片 + 键构成说明</td></tr><tr><td>分辨率分桶覆盖率</td><td>线上桶集合覆盖分桶表，各桶样本量达下限</td><td>各桶流量占比直方图</td><td>分布导出文件 + 分桶表版本</td></tr></tbody></table>\n\n<h3 id=\"ap-mm-launch-checklist-sec-10\">十 · 批调度正确性类：异构序列掩码逐位比对</h3>\n<p>掩码正确性只在同构批上跑通是无效证据。异构序列拼批后，不同样本的图像 token 数不同，视觉 token 与文本 token 的拼接位置随样本而变，位置偏移一旦算错，注意力就会跨样本串扰。机制上要做逐位比对：构造一批图像 token 数互不相同的样本，用参考实现（逐样本单独前向）算出注意力可见性矩阵，再与拼批实现的掩码逐位比对，通过率必须是 100%，不允许“接近”。</p>\n<p>伪代码思路：对批内每个样本 i，记录其视觉段起止偏移 [s_i, e_i) 与文本段起止，生成期望掩码 M_ref；取拼批实现的实际掩码 M_act；断言 M_ref == M_act 逐位相等，任一不等即打印样本索引与偏移。代价是测试时间与显存：异构批要覆盖足够多的 token 数组合，组合爆炸会让比对脚本跑得久；工程上用等价类抽样，按 token 数分档取代表组合，把比对控制在可接受时长内。例子：某次批调度改动后同构批全绿，异构批比对在“一图长文 + 一图短文”组合上发现文本段起点偏移了一位，正是跨样本串扰的来源。</p>\n\n<h3 id=\"ap-mm-launch-checklist-sec-11\">十一 · 量化类：FP8 校准集代表性</h3>\n<p>FP8 校准集代表性这一项的判定标准不是“校准误差小于某值”，而是“校准集分布覆盖线上业务分布”。机制上要把校准集的图像按场景、分辨率、照度等维度分档，与线上流量分布逐档比对，输出覆盖比例。覆盖比例不足的档位，量化后视觉塔输出分布会偏移，而这种偏移在放量前的小流量里往往不显现。</p>\n<div class=\"formula\">$$\\text{覆盖比例}_k = \\frac{\\text{校准集中第 } k \\text{ 档样本数}}{\\text{该档按线上分布应占样本数}},\\quad \\min_k \\text{覆盖比例}_k \\ge \\rho_{\\min}$$</div>\n<p>阈值 ρ_min 的来源必须写明：由该档位在下游任务上的敏感度决定，敏感档位要求更高覆盖。代价是校准成本——覆盖长尾档位意味着校准集要扩，校准前向的次数与显存占用上升；工程上对长尾档位做加权采样而非等比扩样，把校准预算压在敏感档上。例子：校准集只取单一明亮场景，长尾分辨率与低照度图像未覆盖，量化后视觉塔在暗光图上输出分布偏移，放量后才暴露——这一项的作用就是在放量前把这类档位标红。</p>\n\n<h3 id=\"ap-mm-launch-checklist-sec-12\">十二 · 部署资源与服务类：带宽余量与尾延迟降级</h3>\n<p>分离式部署的带宽余量不能只看平均带宽。机制上要测突发批下的尾延迟：视觉 embedding 从预填节点传往解码节点，突发批到来时传输队列排队，平均带宽看着充裕，尾延迟已经超标。判定标准写成“在设定突发批倍率下，传输环节的 P99 延迟不超过预算，且链路利用率峰值留有余量”，阈值来源是 SLO 分解到传输环节的预算份额。</p>\n<p>SLO 尾延迟与降级路径要合并成一项证据：不仅测尾延迟，还要预演降级路径——当尾延迟逼近预算时，系统是否按预案降级（降分辨率、降批、回退精度路径），降级后尾延迟是否回到预算内。降级路径未预演等于没有降级路径。代价直接落在功耗与吞吐：留带宽余量意味着链路不能跑满，突发时吞吐上限被压；降级则牺牲质量换时延。例子：只测平均带宽的版本在突发批下 P99 超标，且降级开关从未在压测中打开过，放量后只能靠人工介入——这一项要求把降级预演做成压测脚本的一部分，输出降级前后的尾延迟对照表作为证据。</p>\n<table class=\"mini\"><thead><tr><th>检查项</th><th>判定标准（阈值来源）</th><th>代价维度</th><th>证据形态</th></tr></thead><tbody><tr><td>分离式带宽余量</td><td>突发倍率下传输 P99 ≤ SLO 分解预算，链路峰值留余量</td><td>吞吐上限、功耗</td><td>尾延迟分位表 + 利用率曲线</td></tr><tr><td>SLO 尾延迟与降级路径</td><td>降级预演后尾延迟回到预算内，降级开关可自动触发</td><td>时延、质量</td><td>降级前后对照表 + 触发日志</td></tr></tbody></table>\n<p>门禁结论的写法要落到可执行判断：七项中任一项复核状态非“已复核”或实测值未达判定标准，结论列即为“阻塞”，不允许以“其余项均通过”为由放行。证据路径必须指向本次候选版本构建产出的文件，跨版本复用旧证据视为无效——视觉塔版本号变了，缓存键与精度一致性证据同时失效，这是速查表在工程上最容易被绕过、也最该被卡住的一处。</p>\n\n<h3 id=\"ap-mm-launch-checklist-sec-13\">十三 · 速查表之外：门禁失效的边界条件与留证代价</h3>\n<p>这张速查表的真正作用不是“打分”，而是把七类检查项各自绑定到一条可复现的证据链上。判定标准列必须写明阈值来源——缓存命中率与分辨率分桶覆盖率按业务真实请求分布离线统计得出，掩码项按异构批逐位比对脚本的通过率给出，FP8 校准集按长尾分辨率与低照度样本的覆盖比例给出。实测值列填的是同一口径下的复测结果，证据列指向具体日志或比对脚本输出路径，复核状态与门禁结论由非提交人签署。系统代价在于：每项留证都要占用一次全量或抽样回放，视觉塔与 LLM 精度一致性比对需在真实 batch 形状下跑前向并落盘中间张量，缓存命中率统计要在生产流量镜像上跑够一个分布周期，这些回放本身消耗 GPU 时与存储带宽，属于放量前必须计入的固定开销。</p>\n<p>速查表最容易失效的边界是“同构假设”。掩码项若只在相同图像 token 数的批上验证，异构序列拼批后视觉 token 与文本 token 的位置偏移不会被逐位比对捕获，上线即表现为跨样本注意力串扰；这条失败模式无法靠提高阈值发现，只能靠证据列强制要求异构批比对脚本的输出。同理，FP8 校准集若只取单一场景分布，量化后视觉塔输出分布偏移要到放量后才暴露，速查表应把校准集覆盖比例作为独立判定项而非附注。精度一致性项则须区分“视觉塔输出精度”与“送入 LLM 的 embedding 数值一致性”——视觉侧 FP16 与 LLM 侧 BF16/FP8 混用时的静默漂移，只有对 embedding 逐元素比对才能留证。</p>\n<div class=\"formula\">$$\\text{门禁通过} = \\bigwedge_{i=1}^{7}\\left(\\text{evidence}_i \\neq \\varnothing\\right) \\wedge \\left(\\text{metric}_i \\geq \\text{threshold}_i(\\text{dist})\\right)$$</div>\n<p>分离式部署的带宽项是速查表里最容易被“平均值”糊弄的一格：只测平均带宽不测尾延迟，突发批下视觉 embedding 传输排队会让 SLO 尾延迟超标，而降级路径若未预演，门禁结论就是假的通过。工程判断是：带宽余量按尾部分位而非均值判定，降级路径必须有一次真实触发的演练记录；这两项的证据成本最高，但也是唯一能在放量前暴露排队型故障的检查项。</p>\n<h3 id=\"ap-mm-launch-checklist-sec-14\">十四 · 阈值不是常数：把判定标准锚在业务分布上</h3>\n<p>多模态上线清单最容易写坏的一列是“判定标准”。工程团队习惯填一个绝对数字，比如缓存命中率≥80%、分桶覆盖率≥95%，然后在复核栏打勾。问题在于这些数字一旦脱离业务分布就没有意义：一个以电商商品图为主的推理服务，图像分辨率高度集中，分桶覆盖率天然接近上限；换成以用户随手拍为主的场景，长尾分辨率与极端长宽比会让覆盖率骤降，同样的95%阈值会把一个健康系统判为不合格。清单的判定标准列必须写明阈值来源，而不是只写阈值本身。</p>\n<p>可操作的做法是把每个阈值表达为“分布覆盖比例”而非“单点数值”。以分辨率分桶为例，设业务流量中第 i 个分辨率桶的请求占比为 p<sub>i</sub>，分桶方案把该桶映射到某个目标尺寸，则覆盖率定义为</p>\n<div class=\"formula\">$$\\text{Cov} = \\sum_{i \\in \\mathcal{B}} p_i \\cdot \\mathbb{1}\\left[\\text{dist}\\big(r_i, \\hat{r}_i\\big) \\le \\tau_r\\right]$$</div>\n<p>其中 𝒝 是被分桶方案实际命中的桶集合，r<sub>i</sub> 是原始分辨率，r̂<sub>i</sub> 是映射后的目标分辨率，τ<sub>r</sub> 是允许的相对形变容差。这个式子的价值在于它同时惩罚两件事：漏掉的桶（p<sub>i</sub> 大但不在 𝒝 里）和被强行拉伸的桶（距离超过 τ<sub>r</sub>）。阈值来源应当写成“基于最近 N 天线上采样流量统计的 p<sub>i</sub> 分布，τ<sub>r</sub> 取业务可接受的形变上限”，而不是一个孤立的百分数。测量方法也随之明确：离线跑一遍流量回放，把 p<sub>i</sub> 与 𝒝 代入上式，输出覆盖率与未覆盖桶的清单，作为证据文件。</p>\n<p>系统代价在这里体现为显存与吞吐的权衡。分桶越细，覆盖率越高，但每个桶对应一组预分配的激活缓冲与可能的 CUDA Graph 捕获，桶数增加会推高显存占用并拉长首次编译时间；分桶越粗，显存友好但形变误差上升，视觉塔输出的语义质量下降，最终反映在 LLM 侧的回答准确率上。工程判断是：先按流量分布聚类出少量主桶覆盖大头，长尾桶走动态路径并单独记录其占比，把“长尾占比”本身作为一项证据，而不是假装它不存在。</p>\n\n<h3 id=\"ap-mm-launch-checklist-sec-15\">十五 · 精度一致性：逐位比对而不是看 loss 曲线</h3>\n<p>视觉塔与 LLM 的精度一致性是清单里最容易被“看起来没问题”糊弄过去的一项。典型踩坑是只核对视觉塔自身输出的数值范围与统计量，忽略了它写进 LLM 输入 embedding 的那一步。当视觉塔以 FP16 计算、LLM 侧以 BF16 或 FP8 接收时，中间存在一次 dtype 转换，转换点上的舍入与饱和不会在视觉塔的日志里留下任何痕迹，却在跨模态注意力里表现为静默漂移。</p>\n<p>验证机制应当是逐位比对，而不是端到端指标对比。做法是固定同一批输入图像，分别跑“视觉塔输出 → 直接转 LLM dtype”与“视觉塔输出 → 参考高精度路径 → 转 LLM dtype”两条链路，对 embedding 张量做逐元素比较，统计超过容差 ε 的元素比例：</p>\n<div class=\"formula\">$$\\text{Drift} = \\frac{1}{N}\\sum_{j=1}^{N} \\mathbb{1}\\left[\\left|e_j^{\\text{fast}} - e_j^{\\text{ref}}\\right| &gt; \\varepsilon\\right]$$</div>\n<p>ε 的来源必须写清：它由 LLM 侧该层对输入扰动的敏感度决定，可通过在参考路径上注入已知幅度扰动、观察下游 logits 偏移是否超出可接受范围来标定。这一步的代价是显存——同时驻留两条链路的中间张量，对视觉塔输出这种高维特征图意味着可观的临时占用，因此比对通常在离线或专用验证节点上做，不占用线上推理卡。具体例子：一个使用 FP8 视觉塔配 BF16 LLM 的部署，视觉塔输出在低照度图像上出现少量饱和值，逐位比对把这些位置标出来，定位到是视觉塔末层激活的 clamp 范围与 LLM 输入归一化不匹配，而不是笼统地归因于“量化损失”。</p>\n<p>证据文件应是比对脚本的输出：参与比对的样本 ID 列表、ε 取值及其标定记录、超差元素的位置直方图。没有这份输出，精度一致性项不能判为通过。</p>\n\n<h3 id=\"ap-mm-launch-checklist-sec-16\">十六 · 缓存命中率与掩码正确性：两个必须分开测的量</h3>\n<p>图像 embedding 缓存命中率常被当成一个孤立的效率指标，但它与批内异构序列掩码正确性是两件事，混在一起测会互相掩盖问题。缓存命中率的测量方法是给每次请求打上图像内容指纹（感知哈希或内容寻址键），统计命中次数与总请求数之比，并按图像来源分桶报告。这里的关键是分母：如果把预处理阶段被丢弃的请求也算进分母，命中率会被稀释；如果只统计进入视觉塔的请求，又会高估缓存的实际收益。清单要求写明分母口径，并把分桶命中率一并留证，因为单一场景的高命中率可能掩盖另一场景的零命中。</p>\n<p>系统代价直接体现在视觉塔的算力占用上。命中率每提高一档，视觉塔的 batch 规模下降，释放出的 SM 可以还给 LLM 的 decode 阶段；但缓存本身占用显存或主机内存，且内容指纹的计算有 CPU 开销。工程判断是把缓存容量与命中率的边际收益画成一条曲线，找到拐点，而不是无限扩大缓存。</p>\n<p>掩码正确性必须用异构批测。同构批（所有样本图像 token 数相同）下，位置编码与注意力掩码的偏移量恰好对齐，任何实现错误都不会暴露。异构序列拼批后，视觉 token 与文本 token 的边界位置随样本变化，掩码若按固定偏移构造就会串扰。验证机制是逐位比对：对每个样本单独跑一遍（batch size 为 1）得到参考注意力输出，再在拼批里跑同一批样本，比较每个样本对应位置的输出是否与单独跑一致。伪代码思路是构造一个含 K 个不同图像 token 数的批，记录每个样本的 token 区间 [s<sub>k</sub>, e<sub>k</sub>)，然后对拼批输出的每个位置检查其注意力权重是否只落在本样本区间内。证据文件是比对脚本的逐位通过率与失败样本的位置偏移量。</p>\n<table class=\"mini\"><thead><tr><th>检查项</th><th>测量口径</th><th>证据形态</th><th>主要代价</th></tr></thead><tbody><tr><td>embedding 缓存命中率</td><td>按来源分桶，写明分母是否含被丢弃请求</td><td>指纹日志 + 分桶统计</td><td>缓存显存/主机内存、指纹 CPU 开销</td></tr><tr><td>分辨率分桶覆盖</td><td>流量回放代入覆盖率公式</td><td>未覆盖桶清单 + p<sub>i</sub> 分布</td><td>桶数增加推高显存与编译时间</td></tr><tr><td>异构掩码正确性</td><td>拼批输出与单样本输出逐位比对</td><td>逐位通过率 + 偏移直方图</td><td>验证需额外算力，离线执行</td></tr></tbody></table>\n\n<h3 id=\"ap-mm-launch-checklist-sec-17\">十七 · FP8 校准集代表性：用分布距离量化，而不是凭感觉</h3>\n<p>FP8 校准集代表性这一项，材料明确没有给出统一数值阈值，清单要求逐项留证。这意味着判定标准必须由团队自己定义并写明来源。可操作的量化方式是计算校准集与线上流量在关键维度上的分布距离。以图像亮度与分辨率两个维度为例，把校准集与线上采样分别离散成直方图，计算两者之间的总变差距离：</p>\n<div class=\"formula\">$$\\text{TVD} = \\frac{1}{2}\\sum_{b}\\left|h^{\\text{cal}}_{b} - h^{\\text{live}}_{b}\\right|$$</div>\n<p>h<sup>cal</sup> 与 h<sup>live</sup> 是归一化后的直方图。TVD 接近 0 表示校准集覆盖了线上分布，接近 1 表示两者几乎不重叠。阈值来源写成“业务可接受的分布偏移上限”，并由团队在验证阶段用已知良好与已知失败的校准集标定出参考区间。失败模式的典型形态是校准集只取自单一场景，未覆盖长尾分辨率与低照度图像，量化后视觉塔输出分布偏移在放量后才暴露——TVD 正是能在放量前把这种偏移量化的工具。</p>\n<p>代价方面，校准本身是一次离线前向，占用的是验证节点的算力，不影响线上；但校准集构建需要采样与标注，是人力成本。工程判断是：校准集不必追求与线上完全同分布，但必须覆盖每个业务场景的尾部，且 TVD 要按场景分别报告，因为全局 TVD 可能被大头场景拉低而掩盖小场景的严重偏移。证据文件包括直方图原始计数、TVD 计算脚本输出、以及按场景拆分的覆盖清单。</p>\n\n<h3 id=\"ap-mm-launch-checklist-sec-18\">十八 · 分离式部署带宽余量：测尾延迟而不是测平均</h3>\n<p>分离式预填/解码部署里，视觉 embedding 从预填侧传到解码侧，这条链路的带宽余量是清单的部署资源类检查项。只测平均带宽是无效的：突发批到达时，多个请求的视觉 embedding 同时排队传输，平均带宽看起来充裕，尾延迟却已经超标。测量方法是在链路两端打时间戳，记录每个 embedding 传输的排队等待时间与传输时间，取高分位（如 p99）作为判定依据，并把突发批的到达模式写进测试脚本。</p>\n<p>带宽余量的判定标准应表达为“在峰值并发下，embedding 传输的 p99 排队时间不超过预算”，预算由 SLO 尾延迟反推：总尾延迟预算减去解码侧计算时间与调度开销，剩下的才是传输可用的份额。这个反推过程本身就是证据的一部分。系统代价是显存与带宽的耦合——预填侧为了平滑突发会缓冲更多 embedding，占用显存；缓冲越多，传输越平滑但显存越紧。工程判断是给缓冲设上限，并把“缓冲耗尽时的降级行为”写进降级路径检查项，而不是假设缓冲永远够用。</p>\n<p>具体例子：一个 NVL72 机架内的分离式部署，视觉塔在预填侧、LLM 在解码侧，突发批下 embedding 传输排队使 SLO 尾延迟超标，而降级路径未预演，线上只能被动丢请求。清单要求把这一场景在放量前跑一遍，记录 p99 排队时间与降级触发点，作为证据。</p>\n\n<h3 id=\"ap-mm-launch-checklist-sec-19\">十九 · SLO 尾延迟与降级路径：把触发条件写成可执行的门禁</h3>\n<p>尾延迟与降级路径是服务类检查项，也是清单的最终门禁所在。尾延迟的测量不能只看端到端平均，必须按请求类型分层：纯文本请求、单图请求、多图请求、视频抽帧请求的尾延迟分布形态不同，混在一起统计会让多模态请求的长尾被平均掉。测量方法是在服务入口与出口打点，按请求类型分组取高分位，并把分组口径写进证据文件。</p>\n<p>降级路径的验证要点是“预演”而非“存在”。清单要求每一项降级策略都有对应的触发条件、触发后的行为、以及一次实际预演记录。触发条件应当是可观测的量，比如 embedding 传输 p99 排队时间超过预算、或视觉塔队列深度超过阈值；触发后的行为可以是降低分辨率分桶精度、跳过缓存直接计算、或把多图请求拆成串行。预演记录要包含触发时的实测值与降级后的尾延迟变化，证明降级确实把尾延迟拉回预算内，而不是把问题推迟。</p>\n<p>代价判断落在容量规划上：降级路径的存在意味着系统在峰值时不以全精度服务，容量规划必须按降级后的服务质量来承诺 SLO，否则门禁通过只是纸面通过。工程上可执行的判断是：把每个降级触发条件写成监控告警规则，把预演记录挂到清单的证据列，放量门禁结论只有在“触发条件可观测、降级行为已验证、降级后尾延迟回到预算内”三条同时满足时才判为通过。没有这三条，其余检查项再齐全也不足以支撑放量。</p>\n<h3 id=\"ap-mm-launch-checklist-sec-20\">二十 · 精度一致性：最贵的一类静默失败</h3>\n<p>七类检查项里，精度一致性类最容易在上线后变成“查不出来的错”。典型踩坑是只核对视觉塔输出本身的数值精度，却不去核对它写进 LLM 输入 embedding 的那一段是否与 LLM 侧 dtype 对齐。视觉塔常以 FP16 计算并输出，而 LLM 侧可能跑 BF16 或 FP8；如果拼接处没有显式的 dtype 转换与范围检查，跨模态投影后的 embedding 会在低位上发生静默漂移——loss 不报错、服务不崩，但同一张图在不同批次里给出不同答案。</p>\n<p>检查机制应当是“双端采样 + 逐元素比对”，而不是只看单端统计量。伪代码思路：固定一组覆盖典型与长尾的校准图，分别在前端视觉塔导出与 LLM 输入侧抓取同一位置的 embedding 张量，按 <span>dtype</span> 提升到 FP32 后计算相对误差与最大绝对误差，并额外检查是否存在超出目标 dtype 表示范围的饱和点。</p>\n<div class=\"formula\">$$\\varepsilon_{\\text{align}}=\\max_{i}\\frac{|e^{\\text{vis}}_{i}-e^{\\text{llm}}_{i}|}{\\max(|e^{\\text{llm}}_{i}|,\\ \\delta)}$$</div>\n<p>系统代价落在验证吞吐上：双端抓取意味着一次前向要跑两遍采样路径，且比对脚本本身占用主机侧 CPU 与显存拷贝带宽。工程上把它做成离线门禁而非在线常驻，用少量固定样本换确定性。具体例子：某服务视觉塔输出 FP16、LLM 输入走 FP8，拼接处直接截断，长尾低照度图像的 embedding 尾部被压平，检索类任务召回下降，而单看视觉塔输出的余弦相似度仍然漂亮——这正是“只核对一端”漏掉的形态。</p>\n\n<h3 id=\"ap-mm-launch-checklist-sec-21\">二十一 · 缓存与分桶：命中率与覆盖率要分开取证</h3>\n<p>缓存与分桶类包含两项，取证方式完全不同，混在一起做就会互相掩盖。图像 embedding 缓存命中率是运行时指标，必须在真实流量分布下采样；分辨率分桶覆盖率是静态覆盖问题，必须在预处理阶段对输入分辨率做直方图统计，再与分桶边界逐桶对照。常见坑是把缓存命中率当成“缓存有效”的唯一证据：高命中率可能只是因为流量集中在少数几个分辨率上，长尾分辨率全部落到慢路径，尾延迟被少数请求拉爆。</p>\n<p>检查顺序上，先做分桶覆盖取证，再做命中率取证。前者输出一张“分辨率直方图 × 分桶边界”的对照表，标出落在桶外或跨桶边界的比例；后者输出按桶分组的命中率，而不是全局一个数。系统代价：分桶过细会增加批内异构度，直接抬高批调度与掩码校验的成本；分桶过粗则让同一桶内图像被拉伸或裁切，视觉 token 数与语义分布同时漂移。具体例子：业务流量九成集中在固定几档分辨率，全局命中率看起来很高，但剩余一成的极端宽高比图像每次都要重跑视觉塔，且这些请求恰好是长文档扫描件，单请求视觉 token 数远高于均值，于是尾延迟超标而均值指标毫无异常。</p>\n\n<h3 id=\"ap-mm-launch-checklist-sec-22\">二十二 · 掩码正确性：同构批跑通不算通过</h3>\n<p>批调度正确性类只有一项，却是上线后最难定位的故障源：批内异构序列掩码。踩坑形态非常固定——验证只在同构批上做，即批内每个样本的图像 token 数相同，此时位置偏移恰好对齐，掩码看起来完全正确；一旦异构序列（不同图像 token 数）拼批，视觉 token 与文本 token 的相对位置发生偏移，跨样本注意力串扰就出现了。</p>\n<p>机制上要抓的是位置索引与注意力掩码的逐位一致性。检查脚本应构造一个刻意异构的批：批内样本的图像 token 数取不同档位，文本长度也取不同档位，然后对每个样本单独前向（batch=1）得到参考输出，再与拼批输出逐位比对注意力可见性矩阵。判定标准写成“掩码逐位比对通过率”，证据是可追溯的比对脚本输出，而不是一句“测试通过”。</p>\n<div class=\"formula\">$$\\text{pass}=\\frac{\\#\\{(i,j): M^{\\text{batched}}_{ij}=M^{\\text{single}}_{ij}\\}}{N^2}$$</div>\n<p>系统代价：逐位比对是 O(N²) 的，N 为拼批后序列长度，长序列下比对本身耗时显著，因此只在门禁阶段跑固定几组异构组合，不进在线路径。具体例子：某服务把两张图与两段文本拼成一个批，视觉 token 数分别为 A 与 B 且 A≠B，位置编码按各自起点写入但掩码按统一长度生成，结果第二段文本的注意力窗口越界看到了第一张图的尾部 token，输出里出现与自身图像无关的描述——单样本测试永远复现不了。</p>\n\n<h3 id=\"ap-mm-launch-checklist-sec-23\">二十三 · FP8 校准集：代表性比数值本身更重要</h3>\n<p>量化类的检查项是 FP8 校准集代表性。踩坑不在校准算法，而在校准数据的分布：校准集只取自单一场景，未覆盖长尾分辨率与低照度图像，量化后视觉塔输出分布偏移在放量后才暴露。此时离线评测集若与校准集同源，指标会一致地好看，形成自我确认的闭环。</p>\n<p>检查机制是把校准集与真实流量分布做显式对照：按分辨率档位、亮度分位、图像长宽比三个维度分别统计覆盖比例，任何一档覆盖为零即判定不通过。证据是覆盖比例表加校准脚本的输入清单。系统代价体现在量化收益与精度损失的权衡上：扩大校准集覆盖会拉长校准离线作业时间，且更宽的动态范围可能迫使部分层回退到更高精度，直接损失吞吐与显存收益。具体例子：校准集全部来自白天室内场景，低照度图像的激活值落在 FP8 表示范围的低端，量化步长相对过大，视觉塔输出的细节通道被抹平，而离线评测集同样是白天室内图，精度指标毫无变化，直到夜间流量进入才出现明显的描述退化。</p>\n\n<h3 id=\"ap-mm-launch-checklist-sec-24\">二十四 · 分离式部署：平均带宽是伪证据</h3>\n<p>部署资源类的检查项是分离式部署带宽余量。最常见的错误是只测平均带宽不测尾延迟：突发批下视觉 embedding 从预填节点传到解码节点时排队，平均带宽仍然充裕，但单次传输的排队延迟把 SLO 尾延迟顶穿，而降级路径从未预演过，于是没有可切换的退路。</p>\n<p>取证方式必须是分布而非均值：在压测中记录每次视觉 embedding 传输的排队时长与完成时长，取高分位与平均值的比值作为余量判据，并同时验证降级路径——当传输延迟超过阈值时，系统是否能退回同节点预填或降低并发。系统代价很直接：分离式部署省下的是显存与算力错配，付出的是跨节点带宽与排队不确定性；余量不足时，尾延迟的代价会以 SLO 违约的形式一次性结算。具体例子：压测用平稳流量，平均带宽余量充足；上线后遇到突发批，多个请求的视觉 embedding 同时等待同一条链路，排队延迟叠加，尾延迟超标，而预设的降级开关因为从未演练，切换时触发了连接重建，反而制造了第二波超时。</p>\n\n<h3 id=\"ap-mm-launch-checklist-sec-25\">二十五 · 检查顺序与回滚：门禁要能倒着走</h3>\n<p>七类检查项不是并列关系，顺序错了会浪费证据。建议顺序：先精度一致性（决定数值地基是否可信），再掩码正确性（决定批调度是否可信），再 FP8 校准集代表性（决定量化是否可信），然后分辨率分桶覆盖与缓存命中率（决定预处理与缓存路径是否可信），接着分离式带宽余量（决定部署形态是否可信），最后 SLO 尾延迟与降级路径（决定服务形态是否可信）。前四项任一不通过，后面的取证都建立在不可信的数值或调度之上，做了也是白做。</p>\n<p>每项证据必须落到速查表的固定列：检查项名称、判定标准（写明阈值来源，如校准集分布覆盖比例、掩码逐位比对通过率）、实测值、证据文件路径、责任人、复核状态、放量门禁结论。判定标准列不允许写“符合预期”这类无来源表述，证据列必须能追溯到具体日志或比对脚本输出。</p>\n<p>回滚方案要按检查项分组设计，而不是一个全局开关。精度一致性与量化类失败的回滚是切回上一版精度配方与校准集，代价是一次全量重新校准的离线时间；掩码类失败的回滚是关闭异构拼批、退回同构批或更小批，代价是吞吐下降；带宽与尾延迟类失败的回滚是切回同节点预填或降低并发上限，代价是显存占用上升。回滚路径本身也要预演并留证，否则它只是纸面上的开关。工程判断落在最后一句：门禁的价值不在于拦住多少项，而在于每一项失败都有一条已经演练过、代价已知的倒着走的路。</p>\n\n<h3 id=\"ap-mm-launch-checklist-sec-26\">二十六 · 放量门禁的失效边界：清单在什么条件下会漏判</h3>\n<p>这份清单的价值不在“七项都打勾”，而在每项都留下可追溯的证据文件——判定标准列必须写明阈值来源，证据列必须指向具体日志或比对脚本输出。失效条件恰恰出现在证据形态降级时：把“视觉塔输出精度达标”当作终点，而不比对视觉塔输出与LLM输入embedding的数值一致性。视觉侧跑FP16、LLM侧吃BF16或FP8时，两侧各自“合格”，拼起来却是静默精度漂移，单测全绿、线上答错。判据应写成逐元素比对而非统计均值：<div class=\"formula\">$$\\max_{i}\\left|\\,\\hat{e}_i-\\mathrm{cast}_{bf16}(e_i)\\,\\right| \\le \\tau_{emb},\\qquad \\tau_{emb}\\ \\text{由校准集分布覆盖比例反推}$$</div>代价是每轮放量前多跑一遍全量embedding比对，占用一次端到端前向的算力与显存带宽；省掉它，漂移只会在长尾样本上以低概率暴露。</p>\n<p>第二类漏判来自批调度正确性。掩码验证若只在同构批（各样本图像token数相同）上跑通，异构序列拼批后视觉token与文本token的位置偏移不会被发现，上线即出现跨样本注意力串扰。检查顺序上应把异构掩码逐位比对排在缓存与分桶之前：先证明拼批语义正确，再谈命中率优化，否则缓存命中率再高也是在错误语义上加速。逐位比对的做法是对同一批做“单样本串行前向”与“拼批前向”的输出逐位置比对，通过率作为门禁结论，代价是一次双倍前向的吞吐损失，只在放量前执行。</p>\n<p>第三类是资源与量化的边界条件。FP8校准集只取单一场景分布、未覆盖长尾分辨率与低照度图像时，量化后视觉塔输出分布偏移要到放量后才暴露——校准集的代表性必须用分布覆盖比例留证，而非样本数量。分离式部署只测平均带宽不测尾延迟同样致命：突发批下视觉embedding传输排队，SLO尾延迟超标，而降级路径未预演则意味着超标时无路可退。回滚方案因此要绑定降级路径的预演记录，把“切回非分离式”或“降精度档”作为可执行动作而非文档条款。下表给出六组检查项的放量门禁顺序与对应代价：</p>\n<table class=\"mini\"><thead><tr><th>顺序</th><th>检查组</th><th>门禁证据</th><th>系统代价</th></tr></thead><tbody><tr><td>1</td><td>精度一致性</td><td>embedding逐元素比对脚本输出</td><td>一次全量前向算力</td></tr><tr><td>2</td><td>批调度正确性</td><td>异构批逐位比对通过率</td><td>双倍前向吞吐损失</td></tr><tr><td>3</td><td>量化</td><td>校准集分布覆盖比例</td><td>长尾分辨率显存占用</td></tr><tr><td>4</td><td>缓存与分桶</td><td>命中率与分桶覆盖日志</td><td>缓存显存与带宽</td></tr><tr><td>5</td><td>部署资源</td><td>尾延迟实测与带宽余量</td><td>突发批排队延迟</td></tr><tr><td>6</td><td>服务</td><td>降级路径预演记录</td><td>回滚切换的容量冗余</td></tr></tbody></table>\n<h3 id=\"ap-mm-launch-checklist-sec-27\">二十七 · 上游依赖：清单的七项检查分别锚定哪些条目</h3>\n<p>这份清单不是自成一体的文档，它是一张“验收接口表”：每一项检查都必须能指回某个上游条目的产出物，否则证据无从追溯。七项检查与上游条目的映射关系决定了清单的执行顺序——精度一致性类依赖量化配方与框架集成条目给出的 dtype 组合；缓存与分桶类依赖视觉token压缩工具与预处理工具链给出的分桶边界与缓存键设计；批调度正确性类依赖多模态批调度条目给出的拼批规则；FP8校准集代表性直接继承多模态量化配方的校准流程；分离式带宽余量继承分离式预填配方的拓扑与链路预算；尾延迟与降级路径则挂在SLO与容量规划条目上。工程含义是：清单里任何一项“无法留证”，往往不是清单本身的问题，而是上游条目尚未交付可观测的中间产物。例如掩码逐位比对脚本，若批调度条目没有把位置偏移的计算方式固化成可导出的中间张量，清单执行者就只能做端到端黑盒比对，无法定位串扰来源。</p>\n<p>上游依赖的代价体现在准备周期上。以精度一致性为例，视觉塔输出与LLM输入embedding的数值比对需要在同一批次上同时抓取两侧张量，这要求框架层暴露embedding注入点；若框架只提供端到端logits，比对只能退化为统计分布检验，灵敏度下降。清单因此要求证据文件路径可追溯到具体日志或比对脚本输出，本质是把上游条目的可观测性作为放量前置条件。一个具体例子：视觉侧FP16与LLM侧BF16混用时，端到端logits差异可能被采样温度掩盖，而逐元素embedding比对能直接暴露静默漂移；前者不需要上游改造，后者需要框架在视觉塔出口处留钩子——这就是清单倒逼上游交付的典型形态。</p>\n\n<h3 id=\"ap-mm-launch-checklist-sec-28\">二十八 · 下游影响：清单结论如何改变放量策略与容量规划</h3>\n<p>清单的门禁结论不是二值的“通过/不通过”，而是分级的：某项证据缺失时，放量策略必须相应收缩。缓存命中率未达业务分布设定值时，下游影响是KV cache与图像embedding缓存的显存预算被高估，容量规划中的并发上限需要下调；分辨率分桶覆盖不足时，下游影响是长尾分辨率请求落入兜底路径，单请求视觉token数上升，进而推高预填阶段的算力占用与尾延迟。掩码正确性未通过逐位比对时，下游不是“修一个bug”，而是整个异构拼批策略需要回退到同构批或按图像token数分组，连续批处理的吞吐收益随之收窄。这些影响都应写进清单的“放量门禁结论”列，而不是留在复核人的口头判断里。</p>\n<p>下游影响最直接的是降级路径的预演要求。分离式部署只测平均带宽不测尾延迟时，突发批下视觉embedding传输排队会让SLO尾延迟超标；清单要求降级路径必须预演，意味着下游的容量规划要把“降级后吞吐”作为独立工况建模，而不是把降级当作兜底开关。用公式表达门禁与容量的耦合：</p>\n<div class=\"formula\">$$\\text{可放量并发} = \\min\\left(\\frac{B_{\\text{链路}}}{\\bar{s}_{\\text{emb}} \\cdot (1+\\rho_{\\text{尾}})},\\ \\frac{M_{\\text{显存}}}{m_{\\text{KV}}+m_{\\text{emb}}}\\right)$$</div>\n<p>其中链路带宽项带尾延迟放大因子，显存项带embedding缓存占用；清单中带宽余量与缓存命中率两项证据分别约束这两个上界。工程判断是：清单结论应直接喂给容量规划表，而不是作为发布评审的附件。</p>\n\n<h3 id=\"ap-mm-launch-checklist-sec-29\">二十九 · 横向关系：与同类条目共享证据但角度不同</h3>\n<p>本清单与视觉token压缩、批调度、量化配方等条目共享同一批中间产物，但视角是“验收”而非“设计”。视觉token压缩条目关心压缩率与精度损失的权衡，清单只关心压缩后的分辨率分桶覆盖是否与业务分布匹配、缓存键是否随压缩策略变化而失效；批调度条目关心拼批算法与吞吐，清单只关心异构序列拼批后位置偏移是否被逐位比对。这种横向关系要求清单的判定标准列写明阈值来源——例如掩码逐位比对通过率、校准集分布覆盖比例——而不是引用其他条目的设计目标值。共享证据的好处是避免重复造轮子：预处理工具链产出的分桶统计可直接作为分桶覆盖率的证据文件，量化配方的校准集分布报告可直接作为FP8代表性证据。</p>\n<p>横向关系的代价是责任边界容易模糊。缓存命中率的实测值由谁产出？若缓存键设计归压缩工具条目、缓存实现归框架条目，清单执行者需要指定责任人列并明确证据产出方。一个具体例子：图像embedding缓存命中率低，可能是分桶边界与业务请求分布错配（预处理侧），也可能是缓存键未包含分辨率导致跨桶误命中（框架侧）；清单不负责定位根因，但要求证据文件能区分这两类，否则复核状态无法闭环。表格给出清单与相邻条目的接口关系：</p>\n<table class=\"mini\"><thead><tr><th>检查项</th><th>上游条目</th><th>共享证据</th><th>下游影响</th></tr></thead><tbody><tr><td>精度一致性</td><td>量化配方、框架集成</td><td>两侧embedding张量日志</td><td>决定dtype组合能否放量</td></tr><tr><td>缓存命中率</td><td>压缩工具、预处理工具链</td><td>缓存键与请求分布统计</td><td>约束显存预算与并发上限</td></tr><tr><td>分桶覆盖</td><td>预处理工具链</td><td>分桶边界与业务分布直方图</td><td>决定长尾请求兜底比例</td></tr><tr><td>掩码正确性</td><td>批调度条目</td><td>位置偏移逐位比对输出</td><td>决定异构拼批能否启用</td></tr><tr><td>FP8校准集</td><td>量化配方</td><td>校准集分布覆盖报告</td><td>决定量化后分布偏移风险</td></tr><tr><td>带宽余量</td><td>分离式预填配方</td><td>链路尾延迟测量记录</td><td>约束降级触发阈值</td></tr><tr><td>尾延迟与降级</td><td>SLO与容量规划</td><td>降级路径预演记录</td><td>决定SLO承诺可否签署</td></tr></tbody></table>\n\n<h3 id=\"ap-mm-launch-checklist-sec-30\">三十 · 在全书中的位置：从算子到放量的最后一环</h3>\n<p>把全书结构摊开看，本清单处在“机制层→配方层→验收层”三级链条的末端。算子与数值精度条目回答NVFP4/FP8、tcgen05、TMEM、2-SM MMA怎么用；显存与KV cache、批调度、投机解码、分离式预填回答系统怎么搭；框架条目回答用什么工具落地；本清单回答“凭什么敢放量”。它的独特位置在于：前面所有条目的正确性主张，最终都要在这里转化为可追溯的证据。精度一致性检查把量化配方的dtype选择变成逐元素比对记录；掩码检查把批调度的拼批规则变成位置偏移的逐位输出；带宽余量检查把分离式拓扑的链路预算变成尾延迟测量。没有这一环，前面的设计决策在放量时无法被审计。</p>\n<p>在全书中的位置也决定了它的读者分工：算子与配方条目的作者提供判定标准的阈值来源，框架条目的作者提供证据导出钩子，SLO条目的作者提供降级预演脚本，本清单的作者只负责把七类检查组织成门禁流程。工程代价是流程开销：逐项留证意味着放量前需要跑一轮专门的证据采集批次，这批请求的吞吐不贡献业务收入，但换来的是失败模式在上线前暴露——掩码串扰、校准集长尾缺失、尾延迟超标这三类问题在放量后修复的成本远高于采集批次的开销。具体例子：FP8校准集仅取自单一场景分布时，量化后视觉塔输出分布偏移在放量后才暴露，回滚涉及重新校准与重新验证，而清单要求在放量前用覆盖长尾分辨率与低照度图像的校准集留证，把回滚成本前置为采集成本。</p>\n\n<h3 id=\"ap-mm-launch-checklist-sec-31\">三十一 · 依赖闭环：清单自身作为其他条目的输入</h3>\n<p>关系不是单向的。清单的门禁结论会反向成为上游条目的输入：掩码逐位比对未通过，会把“位置偏移计算方式需固化”作为批调度条目的待办；缓存命中率未达标，会把“缓存键需包含分辨率与压缩策略版本”作为压缩工具条目的约束；尾延迟超标且降级未预演，会把“降级路径需独立建模吞吐”写回SLO条目的容量规划。这种反向输入让清单不只是发布评审的检查表，而是全书条目之间的反馈通道。伪代码思路可表达为闭环：</p>\n<div class=\"formula\">$$\\text{gate}_i = f(\\text{evidence}_i),\\quad \\text{backlog}_{\\text{上游}} \\mathrel{+}= \\{\\,i \\mid \\text{gate}_i = \\text{blocked}\\,\\}$$</div>\n<p>闭环的代价是责任人列的维护成本：每项检查的证据产出方与复核方必须分离，否则“自己证明自己”使门禁失效。工程判断落在具体机制上：清单的速查表列中，证据文件路径与复核状态两列是闭环的载体——路径指向可重跑的脚本输出，复核状态记录谁在什么证据上签字；当某项被标记为blocked时，blocked原因必须写成对上游条目的具体诉求，而不是“精度不达标”这类无法行动的描述。这样，本清单在全书中的位置才真正落定：它是把算子、配方、框架、SLO四条线拧成一股放量绳结的那道工序，绳结的每一股都能追溯到具体条目与具体证据。</p>\n\n<h3 id=\"ap-mm-launch-checklist-sec-32\">三十二 · 清单条目之间的依赖链与失效边界</h3>\n<p>七类检查项不是并列的勾选格，而是一条有向依赖链：精度一致性（视觉塔输出与LLM输入embedding的数值对齐）是根节点，缓存命中率与分桶覆盖依赖它才有意义——若视觉侧FP16与LLM侧BF16/FP8混用产生静默漂移，命中率再高也只是把错误embedding高效地复用。量化类检查（FP8校准集代表性）反向作用于精度一致性：校准集若只取单一场景分布，长尾分辨率与低照度图像的视觉塔输出分布偏移会在放量后暴露，此时根节点的比对结论失效。批调度正确性（异构序列掩码）独立于精度链，但它是唯一无法用统计量替代的检查项，必须逐位比对。部署资源类与服务类位于链尾：分离式部署的带宽余量决定尾延迟预算，而降级路径是尾延迟超标时的兜底，二者构成一条串联的可靠性约束。</p>\n<div class=\"formula\">$$T_{\\text{tail}} \\approx T_{\\text{prefill}} + \\frac{S_{\\text{img}}}{B_{\\text{eff}}} + T_{\\text{decode}},\\quad B_{\\text{eff}} = B_{\\text{avg}}\\,(1-\\rho_{\\text{burst}})$$</div>\n<p>其中 $S_{\\text{img}}$ 为单请求视觉embedding传输量，$\\rho_{\\text{burst}}$ 为突发批下的带宽占用率。只测平均带宽 $B_{\\text{avg}}$ 会低估排队项，突发批下 $B_{\\text{eff}}$ 塌缩，尾延迟超标而降级路径未预演——这是清单里唯一同时牵动部署与服务两组的失效模式。工程判断是：带宽余量检查必须与降级路径预演绑定为同一证据，单独测平均值不构成放量依据。</p>\n<table class=\"mini\"><thead><tr><th>上游检查项</th><th>下游受影响项</th><th>失效后的可观测症状</th></tr></thead><tbody><tr><td>精度一致性</td><td>缓存命中率、分桶覆盖</td><td>命中率正常但输出分布偏移</td></tr><tr><td>FP8校准集代表性</td><td>精度一致性</td><td>长尾分辨率下视觉输出漂移</td></tr><tr><td>异构掩码逐位比对</td><td>全部服务指标</td><td>跨样本注意力串扰，指标失真</td></tr><tr><td>带宽尾延迟</td><td>降级路径、SLO</td><td>突发批排队，降级未触发</td></tr></tbody></table>\n<p>在全书位置上，本清单是七个领域推理形态章节的收口件：它不引入新算子，而是把NVFP4/FP8精度、TMEM与2-SM MMA带来的数值路径差异、KV cache与embedding缓存的显存账、连续批处理与分离式预填/解码的调度假设，统一折算成可追溯的证据项。它的边界很明确——清单只保证“放量前已知的失效模式已被覆盖”，对放量后新出现的分布漂移不提供保护，因此复核状态须与线上监控指标联动，而非一次性签字。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-mm-launch-checklist\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>核对视觉塔与LLM精度一致性、图像embedding缓存命中率、分辨率分桶覆盖、批内异构序列掩码正确性、FP8…</td></tr><tr><td>关键点</td><td>见正文</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-mm-launch-checklist · 共 5 个片段</p>\n"},{"id":"ap-mm-data-license","title":"多模态数据许可合规","summary":"图像与视频训练/评测数据需记录来源许可、肖像与版权授权、抽帧与二次分发限制；商用推理输入应声明留存策略与用户同意，跨域传输视觉embedding需评估隐私泄露风险并做脱敏审计。","kind":"合规","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-1\">一 · 条目边界：合规档案而非法律意见</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-2\">二 · 五组分类维度：按生命周期切分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-3\">三 · 速查表八列：每列都是一条举证链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-4\">四 · 与“加密即合规”的区分：可反演性评估的位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-5\">五 · 两类高频失败模式在分类维度上的投影</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-6\">六 · 速查表的八列骨架与字段口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-7\">七 · 阈值列：哪些是数，哪些必须是“未给出”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-8\">八 · 授权凭证列与推理留存列的分离</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-9\">九 · 跨域传输评估列与脱敏审计列</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-10\">十 · 填表顺序与失败模式的字段映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-11\">十一 · 速查表的失效边界：什么时候这张表会骗你</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-12\">十二 · 为什么这一条没有数字，以及“没有数字”本身怎么写成可执行条款</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-13\">十三 · 五组分类对应的可测量对象：把合规字段映射到系统观测点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-14\">十四 · 测量方法：没有数字时，测的是“缺口暴露时间”与“可追溯率”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-15\">十五 · 三个失败模式各自的阈值形态：为什么它们不能共用一个数字</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-16\">十六 · 把阈值写进系统的地方：三个注入点与它们的代价账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-17\">十七 · 踩坑清单：五类失败模式的现场还原</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-18\">十八 · 检查顺序：按数据生命周期单向推进</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-19\">十九 · 回滚方案：三种缺口的差异化处置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-20\">二十 · 检查清单的字段纪律：可关联性是唯一硬约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-21\">二十一 · 上线前的最后一道闸：把检查顺序编译进流水线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-22\">二十二 · 上游依赖：许可档案是哪些条目的输入</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-23\">二十三 · 下游影响：批调度、显存与分离式部署被许可条款反向约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-24\">二十四 · 与传输和并行条目的接口：embedding跨域流动的审计点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-25\">二十五 · 在全书中的位置：合规是容量规划与SLO的约束项而非旁注</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-26\">二十六 · 失败模式沿依赖链的传播与断链点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-mm-data-license-sec-27\">二十七 · 合规档案的边界：它管不住什么，以及管不住时系统要付什么代价</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-mm-data-license\"><svg style=\"max-width:542px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 542.3 357\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"460.3\" height=\"83.0\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"53.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"57.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：多模态数据许可合规</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">图像与视频训练/评测数据需记录来源许可、肖像与版权授权、抽帧与二次</text><text x=\"75.0\" y=\"78.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">分发限制</text><line x1=\"82.0\" y1=\"97.0\" x2=\"82.0\" y2=\"114.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 113.0 L 86.5 113.0 L 82.0 121.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"121.0\" width=\"460.3\" height=\"83.0\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"162.6\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"166.8\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"148.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><text x=\"75.0\" y=\"171.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">商用推理输入应声明留存策略与用户同意，跨域传输视觉embedding需评</text><text x=\"75.0\" y=\"187.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">估隐私…</text><line x1=\"82.0\" y1=\"206.1\" x2=\"82.0\" y2=\"223.1\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 222.1 L 86.5 222.1 L 82.0 230.1 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"230.1\" width=\"460.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"252.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"256.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"257.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"276.9\" x2=\"82.0\" y2=\"293.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 292.9 L 86.5 292.9 L 82.0 300.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"300.9\" width=\"460.3\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"323.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"327.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"328.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-mm-data-license-sec-1\">一 · 条目边界：合规档案而非法律意见</h3>\n<p>多模态数据许可合规在推理工程语境下有明确的外延：它是一份随数据资产流动的合规档案，而不是一份法律意见书，也不是数据治理平台的全部功能。条目的准确定义是——对图像与视频训练/评测数据记录来源许可、肖像与版权授权、抽帧与二次分发限制，并要求商用推理输入声明留存策略与用户同意，跨域传输视觉embedding前评估隐私泄露风险并做脱敏审计。这个定义包含三个动作层：记录（训练/评测侧）、声明（推理输入侧）、评估与审计（传输侧）。三者共用一套标识体系，但触发时机不同，因此不能合并成一次性的“数据合规检查”。</p>\n<p>与相邻概念的区别必须讲清，否则工程上会把责任错配。数据治理（data governance）覆盖的是组织级的数据资产目录、权限与生命周期策略，粒度到表或数据集；许可合规的粒度到单条合同条款与单次审计日志编号。隐私工程（privacy engineering）处理的是个人信息的最小化、去标识与访问控制，其对象是个人数据本身；本条目处理的是“权利凭证是否覆盖当前使用方式”，对象是授权链。模型卡与数据卡（model/data card）是披露文档，面向外部说明数据构成；本条目是内部可举证的档案，每一列都要能回链到合同条款或审计日志编号，披露文档不能替代举证链。安全审计（security audit）关注未授权访问与链路防护；本条目在传输侧明确要求区分“链路加密”与“embedding可反演性评估”——前者属于安全审计，后者才是本条目要求的隐私泄露风险评估。把加密当成脱敏，是本条目与安全审计最典型的边界混淆。</p>\n<p>工程代价上，档案的维护成本主要落在元数据存储与查询延迟，而非算力。以速查表八列为例，每列若要求可关联到具体合同条款或审计日志编号，则单条数据资产的档案记录至少包含八个外键引用；在百万级图像/视频片段规模下，档案库的写入吞吐与联表查询会成为上线前的瓶颈。具体例子：一条商用推理请求携带用户上传图像，系统需在准入阶段查三件事——该图像是否落入训练集许可的二次分发范围、推理留存策略是否已声明、用户同意记录是否存在；这三次查询若走联表，单请求增加的是毫秒级准入延迟，而非GPU时间。因此档案设计的第一原则是把高频判定字段（留存策略、同意记录、传输评估结论）做成可缓存的窄表，把低频举证字段（合同条款编号、审计日志编号）留在冷路径。</p>\n\n<h3 id=\"ap-mm-data-license-sec-2\">二 · 五组分类维度：按生命周期切分</h3>\n<p>分类维度按数据生命周期分为五组，这个切分不是为了归档整齐，而是为了让每组对应一个不同的责任人与一个不同的失败点。来源许可类管采集来源与授权链，回答“这份数据最初从哪来、授权能否逐跳追溯”；内容权利类管肖像权与版权，回答“画面里的人与画面本身是否被许可”；使用限制类管抽帧限制与二次分发限制，回答“以什么形态、发给谁”；推理输入类管留存策略与用户同意声明，回答“上线后用户数据留多久、凭什么留”；传输类管跨域embedding传输的隐私评估与脱敏审计，回答“向量出境前是否评估过可反演性、审计是否留痕”。</p>\n<p>五组之间存在单向依赖：使用限制类的条款直接约束传输类的评估结论，推理输入类的留存策略又受来源许可类授权链的约束。形式化地，一条数据资产的可放行判定可写成合取式：</p>\n<div class=\"formula\">$$\\text{release}(d)=\\text{src}(d)\\wedge\\text{right}(d)\\wedge\\text{use}(d)\\wedge\\text{infer}(d)\\wedge\\text{xfer}(d)$$</div>\n<p>任一子项为假即整条不可放行，且子项之间不可互相替代——这正是“训练许可覆盖二次分发但不覆盖推理留存”这类缺口的成因：$\\text{use}(d)$ 为真不能推出 $\\text{infer}(d)$ 为真。工程上应把该合取式实现为逐项短路求值的准入检查，并把每个子项的判定结果与凭证编号一并落盘，使失败时可定位到具体子项而非笼统的“不合规”。</p>\n<p>代价体现在批调度侧：若准入检查放在请求入口同步执行，五组子项全查会拉长首token延迟；若异步补查，则存在“先放行后撤销”的窗口，需要留存策略与缓存淘汰策略配合。具体例子：视频抽帧数据在二次分发时，帧序列若被下游当作独立图像处理，使用限制类的授权链即断裂——因为原许可约束的是“抽帧率与二次分发范围需按许可条款逐项约束”，帧一旦脱离序列语境，条款适用对象改变，$\\text{use}(d)$ 的举证不再成立。这类断裂不会在传输层报错，只会在审计时暴露，因此使用限制类的字段必须随数据形态一起传递，而不是只挂在原始视频资产上。</p>\n\n<h3 id=\"ap-mm-data-license-sec-3\">三 · 速查表八列：每列都是一条举证链</h3>\n<p>速查表应包含的列是固定的八项：数据资产标识、来源与许可类型、肖像/版权授权凭证、抽帧与二次分发限制条款、推理留存策略、用户同意记录、跨域传输评估结论、脱敏审计状态。八列的设计逻辑是“一列一凭证”：前四列服务训练/评测侧，第五、六列服务推理输入侧，第七、八列服务传输侧。每列须可关联到具体合同条款或审计日志编号，这意味着列值不是自由文本，而是受控标识符加外键。</p>\n<table class=\"mini\"><thead><tr><th>列</th><th>归属组</th><th>举证对象</th><th>缺失时的典型后果</th></tr></thead><tbody><tr><td>数据资产标识</td><td>全局</td><td>资产目录条目</td><td>无法把请求回溯到具体数据</td></tr><tr><td>来源与许可类型</td><td>来源许可类</td><td>采集合同/授权链</td><td>授权链断点不可举证</td></tr><tr><td>肖像/版权授权凭证</td><td>内容权利类</td><td>肖像与版权授权文件</td><td>画面权利主张无凭据</td></tr><tr><td>抽帧与二次分发限制条款</td><td>使用限制类</td><td>许可条款原文编号</td><td>帧序列二次分发越界</td></tr><tr><td>推理留存策略</td><td>推理输入类</td><td>留存声明与配置</td><td>用户图像被默认缓存</td></tr><tr><td>用户同意记录</td><td>推理输入类</td><td>同意日志</td><td>无同意记录即留存</td></tr><tr><td>跨域传输评估结论</td><td>传输类</td><td>隐私泄露风险评估报告</td><td>只加密未评估可反演性</td></tr><tr><td>脱敏审计状态</td><td>传输类</td><td>脱敏审计日志编号</td><td>审计不可追溯</td></tr></tbody></table>\n<p>这张表的工程价值在于把“合规”拆成可查询的布尔与枚举字段，从而能进入准入路径。代价是档案写入放大：一条视频资产若按抽帧粒度登记，八列乘以帧数，元数据量可能超过原始资产本身的索引开销；因此实践中以“资产+条款”为最小登记单元，帧级只在二次分发时按条款派生登记，避免全量帧级档案。具体例子：跨域传输视觉embedding时，第七列要求给出评估结论而非“已加密”；若该列缺失，系统即便链路加密完好，也构成传输类子项为假，$\\text{release}(d)$ 整体不成立。</p>\n\n<h3 id=\"ap-mm-data-license-sec-4\">四 · 与“加密即合规”的区分：可反演性评估的位置</h3>\n<p>传输类是本条目与安全审计分野最锐利的一组。跨域传输视觉embedding前评估隐私泄露风险并做脱敏审计，这句话的重心在“评估”与“审计”，不在“加密”。链路加密保护的是传输过程中的窃听，而视觉embedding一旦到达对端，其可反演性决定了对端能否从向量重建出可识别的图像内容；加密在解密后即失效，可反演性风险却在解密后开始。因此第七列的评估结论必须回答的是“该embedding在本对端模型与数据分布下的反演风险等级”，而不是“链路是否TLS”。</p>\n<p>脱敏审计状态作为第八列，要求的是留痕而非一次性动作：脱敏做了什么、依据哪条评估结论、由哪个日志编号记录。伪代码层面的准入思路是，在embedding出域前插入一个判定点：</p>\n<div class=\"formula\">$$\\text{send}(e)=\\text{xferEval}(e)\\wedge\\text{redactAudit}(e)\\wedge\\text{encrypt}(e)$$</div>\n<p>三项合取中，加密只是其中一项，前两项缺失时即便加密为真也不得发送。工程代价在于评估本身：可反演性评估通常需要对embedding分布做离线分析，无法在请求路径上实时完成，因此实践中按“模型+数据域+对端”三元组做评估缓存，缓存键变更时触发重评；这带来的是评估缓存的管理成本与重评窗口期的放行策略问题，而不是GPU算力开销。具体例子：同一视觉编码器产出的embedding跨两个不同对端传输，若只按模型维度缓存评估结论，则对端数据分布差异被忽略，第七列结论失真；按三元组缓存则缓存条目数上升，查询延迟增加，需与准入路径的窄表缓存分层。</p>\n<p>另一个区分点是“脱敏”与“压缩”的不同：视觉token压缩改变的是表示长度，不改变可反演性结论；把压缩当作脱敏手段，会让第八列记录一个与评估结论不匹配的动作，审计时无法自洽。本条目只要求评估与审计到位，材料未给出脱敏强度的量化阈值，因此工程上不得以任何自设数值冒充条款要求，阈值必须回落到具体许可条款逐项约束。</p>\n\n<h3 id=\"ap-mm-data-license-sec-5\">五 · 两类高频失败模式在分类维度上的投影</h3>\n<p>最常见踩坑有两个，且都能精确投影到五组维度上，这说明分类维度不是描述性的，而是诊断性的。第一坑：把训练数据的许可凭证直接复用于商用推理输入，忽略推理阶段需单独声明留存策略与用户同意。投影结果是来源许可类与内容权利类为真、推理输入类为空——即 $\\text{src}\\wedge\\text{right}$ 成立而 $\\text{infer}$ 缺失，合取式整体为假但系统误判为真，因为凭证被跨阶段搬运。失败模式的具体形态是：训练集许可覆盖二次分发但未覆盖商用推理输入留存，上线后用户图像被默认缓存且无同意记录，形成合规缺口。工程上对应的机制缺失是“阶段标签”——凭证必须携带适用阶段，准入检查按阶段取凭证，禁止跨阶段复用。</p>\n<p>第二坑：跨域传输视觉embedding只做链路加密，未评估embedding的可反演隐私泄露风险，脱敏审计缺位导致审计不可追溯。投影结果是传输类两项为空而加密为真，$\\text{send}(e)$ 被误判为真。这一坑的代价不在延迟而在举证：审计不可追溯意味着事后无法证明当时做过何种评估，合规档案退化为不可用。第三类失败模式是视频抽帧率超出许可条款允许范围，二次分发时帧序列被当作独立图像处理，授权链断裂无法举证——投影到使用限制类，$\\text{use}(d)$ 的适用对象被下游改写而档案未同步派生，属于形态变更未触发重登记。</p>\n<p>三类失败模式的共同工程判断是：合规档案的字段必须与数据形态、使用阶段、传输边界三者绑定，任一维度变更即触发重登记与重判定。把八列做成静态快照、只在入库时填一次，是这些缺口的结构性来源。具体到推理系统，这意味着准入路径上至少要有一个“形态/阶段/边界”三元组的比对点，其开销是每次请求一次窄表比对，代价可测、可缓存，而漏掉它的代价是审计时无法举证。</p>\n<h3 id=\"ap-mm-data-license-sec-6\">六 · 速查表的八列骨架与字段口径</h3>\n<p>这张表不是合规台账的摘要，而是推理流水线里每个视觉资产在进入算子之前必须被填满的八个槽位。列定义按生命周期顺序排布：数据资产标识、来源与许可类型、肖像/版权授权凭证、抽帧与二次分发限制条款、推理留存策略、用户同意记录、跨域传输评估结论、脱敏审计状态。前四列对应训练/评测侧的来源许可类与内容权利类、使用限制类，后四列对应推理输入类与传输类。口径上有一条硬约束：每一列的值必须是可寻址的引用，而不是自由文本——许可类型指向合同条款编号，授权凭证指向签署文件哈希，抽帧限制指向条款中的帧率区间与分发范围原文，留存策略指向推理服务的配置项键名，同意记录指向用户会话 ID 与同意版本号，传输评估指向评估报告编号，脱敏审计指向审计日志批次号。任何一列填“是/否”而不带引用，在审计时等同于未填。</p>\n<p>工程上把这八列做成一条结构体，随视觉资产在 batch 组装时透传，代价是可观测的：每个请求多一次指针解引用与一次哈希校验，在连续批处理路径上属于纳秒级开销，可忽略；真正的代价在存储侧——凭证与审计日志是冷数据，需要独立于 KV cache 的持久化层，不能与推理显存池混用，否则显存回收策略会把审计线索一起换出。举例：一个视频资产在抽帧后产生 N 个帧张量，八列结构体只挂一份在资产 ID 上，帧张量共享该引用，避免逐帧复制凭证字段。</p>\n\n<h3 id=\"ap-mm-data-license-sec-7\">七 · 阈值列：哪些是数，哪些必须是“未给出”</h3>\n<p>本条目材料明确未给出留存时长、脱敏强度与传输评估的量化阈值，因此速查表中凡涉及这三项，单元格必须写“未给出（依条款逐项约束）”，不得填入任何看似合理的默认值。这不是保守，而是口径问题：一旦表里出现一个数字，下游就会把它当作可执行的默认策略，而许可条款里的帧率上限、二次分发范围是逐合同变化的，不存在全局常数。可量化的只有结构性的计数阈值，例如“抽帧率必须落在许可条款声明的区间内”这一条，表里存的是区间端点对（下限帧率、上限帧率）与条款编号，而不是一个推荐值。</p>\n<div class=\"formula\">$$\\text{帧合规} = \\big[\\, f_{\\text{抽帧}} \\in [f_{\\min}^{\\text{条款}},\\, f_{\\max}^{\\text{条款}}] \\,\\big] \\wedge \\big[\\, \\text{分发范围} \\subseteq \\text{许可范围} \\,\\big]$$</div>\n<p>该判定的代价落在预处理阶段而非推理阶段：抽帧器每产出一帧就要比对一次区间，属于 O(帧数) 的常数检查，相对解码本身可忽略；但如果条款区间未随资产透传，事后补查需要重跑抽帧并回溯原始视频，代价是整条预处理链重放加存储带宽占用。例子：某视频许可只允许抽帧用于评测、禁止二次分发帧序列，则表里“二次分发限制条款”列必须写明“帧序列视同独立图像、禁止分发”，且抽帧率区间端点必须来自该条款原文，不能沿用同批次其他视频的区间。</p>\n\n<h3 id=\"ap-mm-data-license-sec-8\">八 · 授权凭证列与推理留存列的分离</h3>\n<p>最常见踩坑是把训练数据的许可凭证直接复用于商用推理输入。速查表用两列强制分离来对抗这一点：授权凭证列记录的是采集与训练/评测阶段的肖像权、版权授权链，留存策略列记录的是推理阶段服务端的缓存行为声明。二者不是同一份文件，前者覆盖“能不能用这张图做训练/评测”，后者覆盖“用户输入进来之后存多久、存在哪、谁能读”。表里要求留存策略列填配置项键名而非时长数字，正是因为时长阈值未给出，可审计的是“策略已被声明且与配置一致”，而不是某个具体秒数。</p>\n<ul>\n<li>凭证列缺失 → 资产不得进入训练/评测 batch，属阻断级。</li>\n<li>留存列缺失 → 推理请求可放行但标记为合规缺口，需在上线前补齐同意记录。</li>\n<li>两列指向同一文件哈希 → 视为复用踩坑，审计直接判不通过。</li>\n</ul>\n<p>系统代价体现在请求准入路径上：把这两列做成准入前置校验，每个请求增加一次配置查询（可缓存于本地），延迟增量在微秒级；若做成事后抽查，则缺口发现时用户图像已被默认缓存，回滚需要清理缓存层并重放同意流程，吞吐损失远大于前置校验。例子：上线后用户图像被默认缓存且无同意记录，正是留存列空而凭证列有值的典型形态——表里两列都非空才算闭环。</p>\n\n<h3 id=\"ap-mm-data-license-sec-9\">九 · 跨域传输评估列与脱敏审计列</h3>\n<p>传输类的两列针对视觉 embedding 的跨域流动。评估结论列存的不是“已加密”，而是“已完成可反演性评估”的结论编号；脱敏审计列存的是审计日志批次号与脱敏算子版本。仅做链路加密不构成评估——加密保护的是传输通道，而 embedding 本身在接收侧可被反演回近似原图，这是与链路加密正交的风险维度。表里把这两列设为独立列，就是为了让“加密=合规”的误判在字段层面无法成立。</p>\n<div class=\"formula\">$$\\text{传输合规} = \\text{评估结论} \\neq \\varnothing \\;\\wedge\\; \\text{审计批次} \\neq \\varnothing \\;\\wedge\\; \\text{脱敏算子版本} \\in \\text{已批准清单}$$</div>\n<p>代价在带宽与算力两侧：脱敏算子若在 embedding 上做扰动或投影，会增加一次前向计算，相对视觉塔本身是小头，但会改变 embedding 分布，下游跨模态注意力的对齐精度需重新验证；审计日志的写入是每批次一次的顺序写，吞吐影响可忽略，但日志必须与 embedding 同批次号绑定，否则审计不可追溯。例子：跨域传输只做链路加密、脱敏审计缺位，表里评估列有编号而审计列为空，审计时无法举证该批次 embedding 经过了何种处理——这正是本列存在的意义。</p>\n\n<h3 id=\"ap-mm-data-license-sec-10\">十 · 填表顺序与失败模式的字段映射</h3>\n<p>填表顺序按阻断强度排：先填资产标识与来源许可，再填凭证与限制条款，然后填留存与同意，最后填传输评估与审计。前三步任一为空则资产不可用；第四步为空则请求可放行但带缺口标记；第五、六步为空则跨域路径整体关闭。三种失败模式在表上各有固定形态：训练集许可覆盖二次分发但未覆盖推理留存，表现为限制条款列有值、留存列空；跨域只加密不评估，表现为评估列空而审计列空、仅有链路配置记录；视频抽帧率超条款，表现为抽帧区间端点与条款原文不一致，且二次分发列把帧序列误标为可分发。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>表上形态</th><th>阻断级别</th></tr></thead><tbody><tr><td>凭证复用至推理输入</td><td>凭证列与留存列同哈希，同意列空</td><td>上线阻断</td></tr><tr><td>仅加密未评估反演</td><td>评估列空、审计列空</td><td>跨域路径关闭</td></tr><tr><td>抽帧超许可范围</td><td>帧率端点与条款不符，分发列误标</td><td>资产阻断</td></tr></tbody></table>\n<p>把这张表嵌进 batch 组装器时，代价是一次结构体校验与一次日志写，属于每 batch 常数开销；收益是把三类失败模式从“上线后审计发现”前移到“组装时字段为空即拒”。工程判断落在一点上：表的价值不在列多，而在每列都强制指向合同条款或审计日志编号——没有引用的单元格，在推理系统里就是一个未定义的合规状态，必须按阻断处理。</p>\n\n<h3 id=\"ap-mm-data-license-sec-11\">十一 · 速查表的失效边界：什么时候这张表会骗你</h3>\n<p>速查表的价值在于“照着填就能过审”，但它的失效条件必须写在表头之上，否则工程团队会把它当成合规证明而不是合规线索。第一类失效是<strong>授权链断裂</strong>：表中“肖像/版权授权凭证”列要求关联到具体合同条款编号，但视频数据在抽帧后帧序列被当作独立图像二次分发时，原始许可若只覆盖“整段视频的整体使用”，帧级分发就落在条款之外，此时表里填的凭证编号依然有效、结论却已失真。第二类失效是<strong>阶段错配</strong>：把训练数据的许可凭证直接复用于商用推理输入，是最高频的踩坑——训练集许可覆盖二次分发不等于覆盖推理阶段的留存与用户同意，表里“推理留存策略”与“用户同意记录”两列必须独立取值，不能从训练列继承。第三类失效是<strong>传输类评估的空转</strong>：跨域传输视觉 embedding 只做链路加密就填“已评估”，而 embedding 的可反演性未做评估、脱敏审计无日志编号可关联，这一列在审计时等于空白。</p>\n<p>把边界形式化，可以用一个可判定的覆盖条件来约束每一行记录。设某数据资产 <em>a</em> 的许可条款集合为 <em>L(a)</em>，实际使用行为集合为 <em>U(a)</em>（含抽帧、二次分发、推理留存、跨域传输四类动作），则该行“合规可举证”当且仅当每个动作都能映射到一条具体条款或审计日志编号：</p>\n<div class=\"formula\">$$\\forall u\\in U(a),\\ \\exists \\ell\\in L(a)\\cup A(a):\\ \\mathrm{covers}(\\ell,u)=1$$</div>\n<p>其中 <em>A(a)</em> 为脱敏审计日志集合。这个式子的工程含义是：速查表不是八列填满就算过，而是每一列都要能反向寻址——寻址不到，该行即判为不可举证。代价体现在审计侧：一次跨域 embedding 传输若缺脱敏审计编号，复核时需回溯原始采集与授权链，人工工时按资产条目数线性增长；视频抽帧率超出许可条款允许范围时，帧序列的每帧都要重新举证，授权链断裂导致整批资产不可用，直接后果是训练/评测流水线阻塞而非单条记录作废。</p>\n<p>第二类系统性代价来自推理侧。上线后用户图像被默认缓存且无同意记录，形成的不是一条记录缺失，而是<strong>留存策略与同意声明两个字段同时失联</strong>，此时速查表的“推理输入类”整组失效；补救路径只能是回填同意或清理缓存，前者受用户触达率约束、后者影响命中率与首 token 延迟。跨域传输侧，仅加密不评估可反演性意味着隐私泄露风险未被量化，脱敏审计缺位使事后追溯不可行，工程上必须把“传输评估结论”与“脱敏审计状态”拆成两列独立取值，禁止合并为“已加密”一个布尔位。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>表中表现</th><th>系统代价</th></tr></thead><tbody><tr><td>训练凭证复用于推理输入</td><td>留存/同意列继承训练值</td><td>缓存清理或同意回填，影响命中率与延迟</td></tr><tr><td>抽帧率超许可范围</td><td>凭证编号有效但覆盖不成立</td><td>帧级重新举证，整批资产阻塞</td></tr><tr><td>仅加密未评估可反演性</td><td>传输列填“已评估”无日志号</td><td>审计不可追溯，复核工时线性增长</td></tr></tbody></table>\n<p>因此速查表的正确用法是把它当<strong>寻址索引</strong>而非合规结论：每一行的八列都必须携带合同条款号或审计日志编号，任一项无法寻址即触发阻断，而不是留空待补。材料未给出留存时长、脱敏强度与传输评估的量化阈值，故这三项在表中只能填“未给出”并要求附条款出处，禁止用经验值填充——用未定义的阈值填表，等于把不可举证的判断伪装成已举证。</p>\n<h3 id=\"ap-mm-data-license-sec-12\">十二 · 为什么这一条没有数字，以及“没有数字”本身怎么写成可执行条款</h3>\n<p>多模态数据许可合规的工程难点不在“知道要合规”，而在“把合规变成可测量、可回归、可审计的系统参数”。本条目给出的明确事实是：材料未给出留存时长、脱敏强度或传输评估的量化阈值，领域常识中视频抽帧率与二次分发范围需按许可条款逐项约束，故本条目数值为未给出。这句话必须被工程化地理解成一条硬约束：<strong>任何试图在系统里写死一个“通用留存天数”“通用脱敏强度”“通用抽帧率”的做法，都是把合同条款替换成了未经授权的默认值</strong>。合规阈值不是技术常数，而是合同变量的函数。</p>\n<p>因此工程上正确的做法是把阈值建模为“条款解析 + 系统执行”的两段式。第一段把每份许可合同解析成结构化字段，第二段让推理系统在运行时读取这些字段并强制执行。伪代码思路如下：</p>\n<div class=\"formula\">$$\\text{policy}(a)=\\big\\langle\\, \\text{retain}(a),\\ \\text{consent}(a),\\ \\text{frame}(a),\\ \\text{redist}(a),\\ \\text{xfer}(a)\\,\\big\\rangle$$</div>\n<p>其中 $a$ 是数据资产标识，五个分量分别对应留存策略、用户同意、抽帧上限、二次分发范围、跨域传输评估结论，每个分量都必须携带合同条款编号或审计日志编号，否则视为未定义并拒绝进入生产路径。这个“未定义即拒绝”的默认拒绝（fail-closed）语义，是把“数值未给出”转化为工程可控性的关键机制：系统不需要知道正确的天数，只需要知道“没有条款编号就不许缓存”。代价是明显的——拒绝路径会增加请求失败率与人工介入工单量，但它把合规缺口从“上线后被动发现”前移到了“请求入口处同步暴露”。</p>\n<p>一个具体例子：商用推理服务收到用户上传图像，请求进入缓存决策点时，系统查询该租户的 $\\text{retain}(a)$。若该字段为空或没有关联合同条款编号，缓存写入被拒绝，图像仅在请求生命周期内驻留显存，请求结束后由显存回收路径清除。这个行为不依赖任何具体天数，却完全满足“声明留存策略”的要求——声明的内容就是“不留存，且该决定的依据是条款缺失”。</p>\n\n<h3 id=\"ap-mm-data-license-sec-13\">十三 · 五组分类对应的可测量对象：把合规字段映射到系统观测点</h3>\n<p>分类维度给出五组：来源许可类、内容权利类、使用限制类、推理输入类、传输类。工程阈值之所以“未给出”，是因为这五组各自的可测量对象根本不在同一个量纲上。要把它们变成可测的，必须先做一次映射：每一组对应一个系统观测点，观测点的取值来自合同而非来自经验。</p>\n<table class=\"mini\"><thead><tr><th>分类组</th><th>可测量对象</th><th>系统观测点</th><th>缺失时的工程行为</th></tr></thead><tbody><tr><td>来源许可类</td><td>授权链完整性（布尔）</td><td>资产入库流水线的凭证校验步骤</td><td>资产不得进入训练/评测集</td></tr><tr><td>内容权利类</td><td>肖像/版权凭证存在性（布尔）</td><td>凭证库与资产标识的关联查询</td><td>标记为不可商用，阻断推理输入路径</td></tr><tr><td>使用限制类</td><td>抽帧上限、二次分发范围（条款枚举）</td><td>视频解码与帧导出模块的参数注入点</td><td>抽帧任务拒绝执行</td></tr><tr><td>推理输入类</td><td>留存策略声明、同意记录（布尔+条款号）</td><td>请求入口的缓存决策点</td><td>不写缓存，仅请求内驻留</td></tr><tr><td>传输类</td><td>跨域评估结论、脱敏审计状态（枚举）</td><td>embedding 出域前的网关检查</td><td>传输被拦截</td></tr></tbody></table>\n<p>这张表的意义在于：它把“阈值未给出”拆成了五类<strong>可判定的布尔或枚举状态</strong>。合规系统不需要量化“多强才算脱敏”，它需要判定“该资产的脱敏审计状态是否为已审计且结论为通过”。判定所需的依据是审计日志编号，而不是一个强度分数。代价体现在吞吐上：每个请求入口多做一次凭证库关联查询与一次网关检查，会引入额外的查询延迟与凭证库读带宽；在连续批处理场景下，这类同步检查若放在批调度热路径上会放大批饥饿风险，因此工程上通常把它放在批形成之前的准入阶段，用异步预取凭证缓存来摊薄。</p>\n<p>具体例子：视频数据进入抽帧模块时，$\\text{frame}(a)$ 从许可条款解析得到的是“允许抽帧但不允许帧序列二次分发”。系统据此把抽帧率参数注入解码器，同时在帧导出路径上打上“不可二次分发”标签，任何下游导出请求被拒绝。这里没有出现任何数字阈值，但抽帧率被条款逐项约束这一事实，已经在参数注入点上被强制执行。</p>\n\n<h3 id=\"ap-mm-data-license-sec-14\">十四 · 测量方法：没有数字时，测的是“缺口暴露时间”与“可追溯率”</h3>\n<p>既然留存时长、脱敏强度、传输评估的量化阈值都未给出，那么可测量的就不是这些量本身，而是合规机制的运行质量。工程上可定义两个不依赖合同数值的指标：缺口暴露时间（从违规状态产生到被系统检出并阻断的时间）与可追溯率（能够关联到具体合同条款或审计日志编号的合规字段占比）。</p>\n<div class=\"formula\">$$\\text{trace}(S)=\\frac{\\big|\\{\\,f\\in S:\\ \\text{ref}(f)\\neq\\varnothing\\,\\}\\big|}{|S|},\\qquad \\text{gap}=t_{\\text{detect}}-t_{\\text{emit}}$$</div>\n<p>$\\text{trace}(S)$ 对合规字段集合 $S$ 统计带引用编号的字段比例，它是纯结构性的，不需要任何阈值假设；$\\text{gap}$ 度量的是检出延迟。这两个指标都可以在回归测试中稳定测量：构造一批故意缺失条款编号的资产与请求，观察系统是否在准入阶段拒绝、拒绝是否被记录、记录是否带日志编号。测量方法是注入式测试而非统计采样，因为合规缺口的分布不是随机的，它集中在“训练凭证被复用于推理输入”和“只做链路加密不做反演评估”这两个已知踩坑上。</p>\n<p>代价维度上，注入式测试的成本是测试环境的凭证库与网关需要可编程伪造，这要求合规字段的读取路径与生产路径完全一致，否则测出来的 $\\text{trace}$ 不代表线上。另一个代价是可追溯率的分母膨胀：当资产数量增长时，逐字段维护引用编号会带来元数据存储与查询开销，工程上通常把引用编号做成不可变日志的索引键，用追加写换取查询效率，代价是日志存储带宽随请求量线性增长。</p>\n<p>具体例子：跨域传输视觉 embedding 的网关检查点，测量的是“出域请求中带跨域评估结论编号的比例”。若某批请求只带链路加密标记而不带评估结论编号，$\\text{trace}$ 下降，网关按默认拒绝拦截。这个测量不涉及任何“反演风险有多高”的量化，只涉及“评估做过没有、编号在不在”。</p>\n\n<h3 id=\"ap-mm-data-license-sec-15\">十五 · 三个失败模式各自的阈值形态：为什么它们不能共用一个数字</h3>\n<p>三个失败模式分别对应三种完全不同的阈值形态，混用会直接导致授权链断裂。</p>\n<ul>\n<li><strong>训练许可覆盖二次分发但不覆盖推理留存。</strong>这里的阈值形态是“许可范围集合的包含关系”，不是数值。判定是集合运算：推理输入的留存行为是否落在训练许可允许的行为集合内。工程上表现为凭证复用检查——若某资产的凭证类型为“训练/评测”，则推理输入路径必须要求独立的留存策略声明与同意记录，否则阻断。代价是推理入口的凭证查询延迟，以及为每个租户维护独立同意记录带来的存储增长。</li>\n<li><strong>跨域传输只做链路加密、未评估 embedding 可反演性。</strong>阈值形态是“评估结论的存在性与审计状态”，不是加密强度。链路加密是传输层属性，反演风险评估是数据属性，二者不可互相替代。工程判定点是网关是否持有该 embedding 类型的评估结论编号与脱敏审计状态；缺失即拦截。代价是网关成为串行检查点，跨域吞吐受其检查延迟约束。</li>\n<li><strong>抽帧率超出许可允许范围、帧序列被当作独立图像二次分发。</strong>阈值形态是“条款逐项约束的枚举上限”，每个视频资产的上限不同。工程上表现为抽帧参数从条款注入而非从全局默认值注入，且帧导出路径继承视频资产的二次分发限制标签。代价是解码模块需要按资产读取参数，破坏了统一批处理的参数同质性，可能引发批饥饿——这正是把合规参数放在批调度热路径上的代价。</li>\n</ul>\n<p>具体例子：某视频资产的条款允许抽帧用于评测但不允许帧序列二次分发。系统在抽帧时注入条款上限，在帧导出时检查标签，导出请求被拒绝并写入带条款编号的审计日志。若工程师图省事把“允许二次分发”作为全局默认，则授权链在这一步断裂，且断裂无法举证——因为日志里没有条款编号。</p>\n\n<h3 id=\"ap-mm-data-license-sec-16\">十六 · 把阈值写进系统的地方：三个注入点与它们的代价账</h3>\n<p>合规阈值在系统里只有三个合法注入点，其余位置一律不得出现硬编码数字。</p>\n<ul>\n<li><strong>准入点（请求入口）。</strong>注入 $\\text{retain}(a)$ 与 $\\text{consent}(a)$，决定缓存写不写、驻留多久（由条款给出，无条款则不驻留）。代价：每请求一次凭证查询，可用异步预取摊薄；同步查询会抬高首 token 延迟。</li>\n<li><strong>解码点（视频抽帧）。</strong>注入 $\\text{frame}(a)$，决定抽帧率与帧导出权限。代价：破坏批内参数同质性，需按资产分组调度，吞吐下降来自批规模缩小。</li>\n<li><strong>出域点（embedding 网关）。</strong>注入 $\\text{xfer}(a)$，决定传输放行与脱敏审计状态校验。代价：串行检查延迟与审计日志追加写带宽。</li>\n</ul>\n<p>这三个注入点的共同工程判断是：<strong>合规检查必须位于数据流动的必经路径上，且其判定依据必须来自带编号的外部凭证，而不是来自系统内部的默认配置</strong>。默认配置只能表达“未定义”，不能表达“允许”。这一判断的直接推论是，合规字段的缺失必须表现为拒绝而非放行，从而把“数值未给出”这件事本身变成系统可观测的信号——$\\text{trace}(S)$ 的下降与拒绝率的上升，就是条款解析不完整的最早告警。</p>\n<p>具体例子：商用推理服务上线前，回归测试构造三类请求——带完整条款编号的、缺留存声明的、缺跨域评估结论的。预期结果是第一类放行、后两类在对应注入点被拒绝且日志带拒绝原因编号。若后两类被放行，说明某个注入点退化成了默认允许，此时 $\\text{trace}$ 与拒绝率同时异常，缺口暴露时间被压缩到测试阶段而非上线之后。</p>\n<h3 id=\"ap-mm-data-license-sec-17\">十七 · 踩坑清单：五类失败模式的现场还原</h3>\n<p>合规事故几乎不来自“不知道规则”，而来自“规则被跨阶段挪用”。本条目定义的五组分类（来源许可、内容权利、使用限制、推理输入、传输）在纸面上是并列的，但在工程流水线上它们是串联的，串联点就是踩坑点。第一个高频坑：把训练数据的许可凭证直接复用于商用推理输入。凭证上写着“可用于模型训练与评测”，团队就默认它覆盖线上推理，于是用户上传的图像被默认写入缓存，留存策略没有单独声明，用户同意记录为空。失败链条是清晰的——训练集许可覆盖了二次分发，却没覆盖推理输入的留存，上线即形成合规缺口。第二个坑在传输侧：跨域传输视觉 embedding 时只做链路加密（TLS、mTLS），把“加密”误当作“脱敏”。embedding 的可反演性意味着加密只保护管道，不保护语义；脱敏审计缺位，事后无法举证做过何种处理。第三个坑在视频：抽帧率超出许可条款允许的范围，二次分发时帧序列被当作独立图像逐张处理，授权链在“视频→帧”这一步断裂，无法举证。第四个坑是凭证与资产的关联断裂——速查表里每一列都必须能追溯到具体合同条款或审计日志编号，一旦只填“已授权”而不填编号，审计时整行失效。第五个坑是肖像权与版权的混同：把版权许可当作肖像授权使用，或反之，在含人物的商用输入上尤其致命。</p>\n<p>把坑映射到系统代价上，才能判断优先级。推理输入类缺口直接作用于在线路径：默认缓存意味着每请求都要占用显存与存储带宽，留存策略缺失使 KV 与图像特征无法按策略及时释放，长会话下显存水位被合规缺省值推高；传输类缺口作用于跨域链路，链路加密本身有吞吐代价，而脱敏审计若事后补做，需要重放 embedding 并重新计算，等于把一次离线批处理的成本追加到审计周期上。视频抽帧坑的代价最隐蔽：抽帧率越高，帧序列的存储与二次分发面越大，授权链断裂后需要人工回溯原始视频与合同，这是纯人力延迟。</p>\n\n<h3 id=\"ap-mm-data-license-sec-18\">十八 · 检查顺序：按数据生命周期单向推进</h3>\n<p>检查不能按“哪个部门先交材料”来排，必须按数据生命周期的单向顺序排：来源许可 → 内容权利 → 使用限制 → 推理输入 → 传输。理由是可举证性：后一环节的合规结论依赖前一环节的凭证编号，顺序颠倒会导致下游结论悬空。具体检查顺序如下。</p>\n<ul>\n<li>第一步，资产标识与来源许可：确认每个数据资产有唯一标识，来源与许可类型可追溯到合同条款编号。此步不通过，后续全部阻塞。</li>\n<li>第二步，内容权利：逐资产核对肖像授权凭证与版权授权凭证是否分别存在，禁止用一条“内容授权”笼统覆盖两类权利。</li>\n<li>第三步，使用限制：把抽帧限制与二次分发限制逐条落到条款上，特别是视频资产，必须明确允许的抽帧范围与帧序列的分发边界。</li>\n<li>第四步，推理输入：单独检查留存策略声明与用户同意记录，不得引用训练阶段的凭证。</li>\n<li>第五步，传输：检查跨域 embedding 传输的隐私泄露评估结论与脱敏审计状态，链路加密不能替代评估结论。</li>\n</ul>\n<p>这个顺序对应一个简单的准入伪代码思路：对资产 <em>a</em>，令 <em>ok(a)</em> 为五步布尔合取，<em>ok(a) = L(a) ∧ R(a) ∧ U(a) ∧ I(a) ∧ T(a)</em>，其中 <em>L</em> 为来源许可可追溯、<em>R</em> 为肖像与版权凭证齐备、<em>U</em> 为抽帧与二次分发条款明确、<em>I</em> 为推理留存与同意记录存在、<em>T</em> 为传输评估与脱敏审计完成。批调度层面，只有 <em>ok(a)=1</em> 的资产才允许进入推理可用的数据池；任何一项为 0，资产进入隔离队列而不是被静默丢弃，隔离队列本身就是审计证据。代价上，这个合取检查是 O(资产数) 的元数据扫描，不触碰像素与 embedding 本体，因此不占 GPU 算力，只占元数据库的读带宽；真正的成本在于人工补齐凭证，属于上线前的关键路径延迟。</p>\n<p>一个具体例子：某视频资产在第三步被查出许可条款只允许低抽帧率用于评测、不允许二次分发帧序列。检查在此处即中止，不进入第四、五步——因为即使推理侧留存策略写得再完整，也无法弥补使用限制的缺口。这种“早停”把返工成本压在上游，避免了下游已经完成脱敏审计却因授权链断裂而全部作废。</p>\n\n<h3 id=\"ap-mm-data-license-sec-19\">十九 · 回滚方案：三种缺口的差异化处置</h3>\n<p>回滚不是“把版本退回去”一个动作，而是按缺口类型分三档处置，且每档都必须留下可追溯记录。第一档，推理输入类缺口（默认缓存、无同意记录）：立即关闭该输入路径的默认留存，将已缓存内容按策略清除，并为受影响请求补记同意状态；由于这类缺口直接作用于在线服务，回滚窗口以请求批次为单位，代价是缓存清空后短期内命中率下降、预填阶段重复计算增多，表现为首 token 延迟上升。第二档，传输类缺口（只加密未评估、脱敏审计缺位）：暂停该跨域链路，对已传输的 embedding 做可反演性评估，补做脱敏审计并记录处理参数；代价是链路停用期间的跨域吞吐归零，需要本地降级承接，同时审计重放占用离线算力。第三档，使用限制类缺口（抽帧超范围、帧序列二次分发）：冻结该资产的帧序列分发，回溯授权链，必要时将资产整体移出可用池；这类回滚不涉及在线路径，但会削减可用数据量，影响评测覆盖度。</p>\n<div class=\"formula\">$$ \\text{rollback\\_cost} = N_{\\text{req}} \\cdot c_{\\text{recompute}} + B_{\\text{link}} \\cdot t_{\\text{pause}} + A_{\\text{asset}} \\cdot c_{\\text{audit}} $$</div>\n<p>式中第一项是推理输入回滚的重算代价（请求数乘以单请求重算成本，重算主要落在预填与视觉塔前向），第二项是传输回滚的带宽机会成本（链路带宽乘以停用时延），第三项是使用限制回滚的审计人力与算力代价（资产数乘以单资产审计成本）。工程判断上，第一项应尽量通过“先声明留存策略再开放路径”来避免，因为它的代价直接体现在 SLO 上；第二项应在链路设计期就并行完成评估，把回滚概率压到最低；第三项只能靠上游检查顺序早停来减少暴露面。</p>\n<p>回滚方案还必须与速查表的列对齐：每一档回滚完成后，对应列的状态要从未完成改为已完成并写入审计日志编号，否则回滚只是操作而非合规闭环。一个具体例子：跨域链路因脱敏审计缺位被暂停后，团队补做评估发现某类视觉 embedding 在特定条件下可反演，于是把该类别从跨域传输清单中剔除，仅保留已脱敏类别——这不是恢复原状，而是以回滚为契机构建了更窄的传输面，代价是跨域可用特征维度下降，收益是审计可追溯。</p>\n\n<h3 id=\"ap-mm-data-license-sec-20\">二十 · 检查清单的字段纪律：可关联性是唯一硬约束</h3>\n<p>速查表的八列（资产标识、来源与许可类型、肖像/版权凭证、抽帧与二次分发条款、推理留存策略、用户同意记录、跨域传输评估结论、脱敏审计状态）不是信息展示，而是举证结构。字段纪律只有一条硬约束：每列必须可关联到具体合同条款或审计日志编号。这条约束把“填表”变成“建索引”，任何一格填“是/已授权/已评估”而不带编号，在审计视角下等同于空值。检查清单的执行要点因此不是“填满”，而是“填到可跳转”。</p>\n<table class=\"mini\"><thead><tr><th>缺口类型</th><th>触发字段</th><th>回滚动作</th><th>主要代价</th></tr></thead><tbody><tr><td>推理输入</td><td>推理留存策略、用户同意记录</td><td>关闭默认留存、清缓存、补记同意</td><td>缓存命中率下降、首 token 延迟上升</td></tr><tr><td>传输</td><td>跨域传输评估结论、脱敏审计状态</td><td>暂停链路、补评估与审计</td><td>跨域吞吐归零、离线审计算力占用</td></tr><tr><td>使用限制</td><td>抽帧与二次分发条款</td><td>冻结帧序列分发、回溯授权链</td><td>可用数据量下降、评测覆盖度受损</td></tr></tbody></table>\n<p>表格的三行对应三种回滚档位，但真正的纪律在表外：资产标识列必须与元数据库主键一致，否则回滚时无法定位受影响请求批次；条款编号列必须与合同管理系统可跳转，否则审计时无法举证。代价方面，维护这套可关联性需要元数据写入路径在预处理阶段就采集条款编号，而不是上线后补录——补录意味着对已入库资产做一次全量回溯，其成本与资产数成正比，且回溯期间速查表处于不可信状态。一个具体例子：视频资产的抽帧条款若在入库时未记录允许抽帧范围，后续任何抽帧率调整都无法判断是否越界，只能整批冻结，这正是字段纪律缺失导致的过度回滚。</p>\n\n<h3 id=\"ap-mm-data-license-sec-21\">二十一 · 上线前的最后一道闸：把检查顺序编译进流水线</h3>\n<p>检查清单若只存在于文档里，它会在第一次赶工期时被跳过。可行做法是把第二节的五步顺序编译进数据流水线的准入环节：预处理阶段采集来源许可与内容权利凭证编号，抽帧阶段强制读取使用限制条款并写入允许范围，推理服务启动时校验留存策略与同意记录字段非空且带编号，跨域传输客户端在建立链路前校验评估结论与审计状态。每一步的失败都产生隔离记录而非异常退出，保证审计链完整。系统代价上，这些校验是元数据层面的短路判断，对推理吞吐无直接影响；真正的代价是流水线耦合度上升——条款变更需要触发下游重新校验，变更传播延迟成为新的运维成本项。工程判断落在取舍上：把校验放在预处理与传输客户端两处收益最高，因为这两处分别对应授权链的起点与隐私风险的出口，而推理服务侧的校验应保持轻量，只做字段存在性检查，避免把在线路径拖进元数据查询。</p>\n<p>最后落在具体机制上：跨域传输的脱敏审计应作为链路建立的前置条件而非事后补录，审计日志编号在传输请求发出前即写入速查表对应列；这样即使链路中途失败，审计状态也是已完成而非悬空，回滚时无需重放。视频资产的抽帧范围应作为预处理产物的元数据随帧序列一同传递，二次分发时逐帧携带授权链引用，使“帧被当作独立图像”这一断裂点从设计上消失。这两条机制的共同点是：把合规证据前移到数据产生的那一刻，而不是等到审计时再回溯。</p>\n<h3 id=\"ap-mm-data-license-sec-22\">二十二 · 上游依赖：许可档案是哪些条目的输入</h3>\n<p>本条目在全书的数据与合规层，处在多个推理条目的上游。它的产出物不是模型，也不是算子，而是一份可被机器读取、可被审计追溯的合规档案：数据资产标识、来源与许可类型、肖像/版权授权凭证、抽帧与二次分发限制条款、推理留存策略、用户同意记录、跨域传输评估结论、脱敏审计状态，每一列都必须能挂到具体合同条款号或审计日志编号上。下游条目在开工前要读的正是这份档案，而不是口头确认。</p>\n<p>对视觉token压缩与视觉编码器相关条目，上游依赖点是抽帧限制与二次分发限制：压缩比、帧采样策略一旦超出许可条款允许的抽帧范围，压缩后的token序列在法务意义上仍是原视频的派生，授权链会断。对多模态量化配方，依赖点是数据资产标识与来源许可类型——量化校准集若混入了二次分发受限的帧，量化产物本身就可能带上分发约束。对多模态分离式预填配方与跨模态注意力条目，依赖点是跨域传输评估结论：预填与解码分处不同域时，视觉embedding跨域流动，必须先有隐私泄露风险评估与脱敏审计状态，否则链路加密只是传输层动作，不构成合规证据。</p>\n<p>工程上把这条依赖做成硬门禁：加载任何视觉资产前，先查档案中该资产标识对应的五组分类（来源许可、内容权利、使用限制、推理输入、传输）是否齐全，缺一列即拒绝进入流水线。代价是启动阶段多一次元数据查询与校验，相对整条推理链的时延可忽略；但缺了它，后面所有优化都建立在不可举证的数据上。</p>\n\n<h3 id=\"ap-mm-data-license-sec-23\">二十三 · 下游影响：批调度、显存与分离式部署被许可条款反向约束</h3>\n<p>许可条款会反向改写推理系统的运行参数，这一点在多模态批调度与视觉塔显存溢出两个条目上最明显。留存策略若声明“不落盘、仅内存驻留至请求结束”，则KV cache与视觉embedding的缓存复用范围被限制在同一请求内，连续批处理不能跨请求复用视觉前缀，批调度器必须把“可复用前缀”标记为不可跨用户共享。反之，若留存策略允许短期缓存，则要附带用户同意记录，缓存条目需携带同意凭证的引用，驱逐策略也要按凭证有效期裁剪。</p>\n<p>用伪代码表达这种约束注入：</p>\n<div class=\"formula\">$$ \\text{admit}(r) = \\text{licenseOK}(r.\\text{asset}) \\land \\text{consentOK}(r.\\text{user}) \\land \\text{retentionOK}(r.\\text{cacheClass}) $$</div>\n<p>只有三项同时为真，请求才允许进入带视觉前缀复用的批。这条与式把合规判断前移到调度准入，而不是事后审计。代价体现在吞吐上：跨请求视觉前缀复用被禁后，视觉塔前向无法摊薄，批饥饿风险上升；显存侧则因缓存条目要挂凭证引用而增加元数据开销，视觉塔显存溢出的回收策略必须把“凭证过期”作为一条独立驱逐触发条件，与显存压力并列。</p>\n<p>具体例子：一个商用推理服务默认把用户上传图像编码后的embedding缓存若干轮以加速重复提问，但档案中该资产的推理输入类只声明了“请求结束即释放”，且无用户同意记录。此时调度器若仍按吞吐优先复用缓存，就构成第一部分所列的失败模式——上线后用户图像被默认缓存且无同意记录。正确做法是把该资产的缓存类降级为请求内私有，接受吞吐损失，换取可举证。</p>\n\n<h3 id=\"ap-mm-data-license-sec-24\">二十四 · 与传输和并行条目的接口：embedding跨域流动的审计点</h3>\n<p>跨域传输视觉embedding是本书并行与通信条目（NVLink 5、NCCL、NIXL）与合规条目的交界面。通信层关心带宽与拓扑，合规层关心的是embedding的可反演性：视觉embedding并非不可逆的匿名数据，攻击者可在一定条件下由embedding重建出可辨识的图像内容，因此“只做链路加密”不等于合规。档案中的传输类要求先做隐私泄露风险评估，再决定脱敏强度与审计粒度；脱敏审计状态必须可追溯到具体日志编号。</p>\n<p>接口设计上，把传输评估结论作为通信配置的一个字段：当评估结论为“需脱敏”时，发送端在序列化embedding前插入脱敏算子（如维度扰动或量化截断），接收端记录审计条目；当结论为“可原样传输”时，仍要保留传输日志以便事后举证。代价是脱敏算子带来额外计算与精度损失，可能影响下游跨模态注意力的对齐质量；审计日志带来存储与写入开销，在NIXL这类高吞吐传输路径上要控制日志粒度，避免每token一条记录拖垮带宽。</p>\n<p>具体例子：预填节点与解码节点分处两个信任域，视觉embedding经NIXL搬运。若只启用链路加密而未评估可反演性，脱敏审计缺位，一旦发生泄露事件无法证明当时采取了何种保护措施——这正是第二部分列出的失败模式之一。工程判断是：把“传输评估结论”和“脱敏审计状态”设为建立传输通道的前置条件，通道建立失败优于无证据传输。</p>\n\n<h3 id=\"ap-mm-data-license-sec-25\">二十五 · 在全书中的位置：合规是容量规划与SLO的约束项而非旁注</h3>\n<p>放到全书结构里看，本条目属于数据与合规层，向下贯穿算子与数值精度、显存与KV cache、批调度、分离式预填/解码、并行与通信、框架与SLO容量规划。它不提供加速手段，而是给所有加速手段划定可行域。容量规划条目在估算每GPU可承载的并发会话数时，若忽略留存策略对缓存复用的限制，算出的吞吐是纸面值；SLO条目在设定首token时延时，若忽略同意校验与档案查询的准入开销，承诺的尾延迟会失守。</p>\n<p>把合规约束写成容量模型的一项：设单请求视觉前缀复用率为ρ，许可允许的跨请求复用上限为ρ_max，则有效批规模受ρ≤ρ_max约束，实际吞吐按ρ_max折算而非按硬件上限折算。ρ_max由留存策略与同意记录覆盖率共同决定，档案中缺同意记录的资产取ρ_max=0，即完全禁止跨请求复用。这一条让容量规划从“硬件能给多少”变成“许可允许给多少”，两者取小。</p>\n<p>七个领域的推理形态各自把这条约束落到不同位置：医疗与自动驾驶类输入涉及肖像与敏感场景，留存策略通常最严，ρ_max趋近于零，批调度要靠请求内并行而非跨请求复用来保吞吐；内容生成类则可能允许短期缓存，但二次分发限制会约束输出帧序列的再分发。框架层（TensorRT-LLM、vLLM、SGLang、Dynamo）需要把档案查询与准入判断做成可插拔的前置钩子，而不是写死在某个后端里，否则换框架即丢失合规证据链。</p>\n\n<h3 id=\"ap-mm-data-license-sec-26\">二十六 · 失败模式沿依赖链的传播与断链点</h3>\n<p>三类失败模式都不是孤立事件，而是沿上游到下游传播。训练集许可覆盖二次分发但未覆盖商用推理输入留存：上游档案的使用限制类与推理输入类出现缺口，下游批调度仍按可复用处理，最终在用户侧表现为默认缓存且无同意记录。断链点在准入判断：若调度器强制读推理输入类字段，缺口会在上线前暴露。</p>\n<p>跨域传输只做链路加密而未评估可反演性：上游传输类评估结论为空，下游通信层照常建链，脱敏审计缺位使事件不可追溯。断链点在通道建立前置条件：评估结论为空即拒绝建链。视频抽帧率超出许可条款允许范围、二次分发时帧序列被当作独立图像处理：上游使用限制类的抽帧条款未被解析成机器可读的帧率上限，下游预处理工具链按性能最优抽帧，授权链断裂无法举证。断链点在预处理入口：抽帧率必须与档案中的条款值比对，超出即拒绝或降采样到条款上限。</p>\n<p>三个断链点共同指向一个工程判断：合规档案必须在下游每个入口被强制读取并参与准入，而不是作为文档躺在对象存储里。代价是每个入口多一次元数据校验与日志写入，收益是任何一次优化都不会越过许可边界——在Blackwell上把推理做快做省做稳，前提是这些加速发生在许可允许的可行域内。</p>\n\n<h3 id=\"ap-mm-data-license-sec-27\">二十七 · 合规档案的边界：它管不住什么，以及管不住时系统要付什么代价</h3>\n<p>这套合规档案的效力边界由“可举证性”划定，而非由“数据是否敏感”划定。它只能约束那些能回溯到合同条款或审计日志编号的资产：来源许可链、肖像与版权凭证、抽帧与二次分发条款、推理留存策略、用户同意记录、跨域传输评估结论、脱敏审计状态。一旦某类视觉资产在采集时未留下授权链锚点，档案就只能记录“缺失”，而不能事后补证——补证在法律上无效，在工程上等价于该资产不可用于商用推理。因此它的失效条件很具体：<strong>训练侧凭证被跨阶段复用</strong>。训练集许可覆盖二次分发，却不覆盖推理输入的留存与同意，这是最常见的断裂点；档案本身不会自动阻止这种复用，它只在审计时暴露缺口。代价落在上线之后：用户图像被默认缓存且无同意记录，合规缺口无法用加密或访问控制弥补，只能回滚缓存策略并重建同意流程，直接冲击推理服务的可用性与 SLO。</p>\n<p>第二个失效条件是跨域传输环节的评估缺位。链路加密只解决传输机密性，不解决 embedding 的可反演性；脱敏审计若未落盘为可追溯记录，事后无法举证“已评估”。设一次跨域传输的资产集合为 $A$，其中具备完整评估结论与审计编号的子集为 $A_r$，则可举证覆盖率写作</p>\n<div class=\"formula\">$$C_r = \\frac{|A_r|}{|A|}$$</div>\n<p>$C_r$ 低于全量时，缺口不是“风险高”，而是“不可审计”。工程代价体现在传输带宽之外：为补齐审计需重放评估流程，跨域链路上的 embedding 需重新脱敏并回写审计日志，这段时间内该通路只能降级为拒绝传输或走同域回退，吞吐与跨域并行度同时受损。</p>\n<p>第三个失效条件在视频侧：抽帧率超出许可条款允许范围，二次分发时帧序列被当作独立图像处理，授权链断裂。此时档案的列结构仍然完整，但“抽帧限制条款”与“二次分发限制条款”两列指向的合同条款已不覆盖实际产物，举证失败。系统代价是显存与存储的连带损失——超范围抽出的帧已进入训练或评测流水线，回撤意味着重跑数据加载与特征缓存，KV cache 与视觉特征缓存的复用率下降。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>档案表现</th><th>系统代价</th></tr></thead><tbody><tr><td>训练凭证复用于推理输入</td><td>留存策略与同意记录列空缺</td><td>缓存策略回滚，服务可用性受损</td></tr><tr><td>仅链路加密、无脱敏审计</td><td>传输评估结论无审计编号</td><td>跨域通路降级，重放评估占用带宽</td></tr><tr><td>抽帧率越界</td><td>条款列与实际产物不匹配</td><td>流水线重跑，特征缓存复用率下降</td></tr></tbody></table>\n<p>在全书位置上，这一条目是上游数据治理条目与下游推理服务条目之间的<strong>举证接口</strong>：上游产出授权链与条款编号，下游消费留存策略与同意记录；它不定义脱敏强度或留存时长的量化阈值，这些阈值必须由具体合同条款逐项给出，档案只负责把条款映射为可关联的列值。工程判断因此落在一点上：把“是否有审计编号”作为准入闸门，而不是把“是否加密”作为闸门——加密是传输属性，审计编号才是可举证属性。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-mm-data-license\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>图像与视频训练/评测数据需记录来源许可、肖像与版权授权、抽帧与二次分发限制</td></tr><tr><td>关键点</td><td>商用推理输入应声明留存策略与用户同意，跨域传输视觉embedding需评估隐私泄露风险并做脱敏审计。</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-mm-data-license · 共 5 个片段</p>\n"}];})();
